    --font-sans: 'Figtree', 'Figtree Fallback', ui-sans-serif, system-ui, -apple-system, sans-serif;

    /* The default theme's colours, Stage dark (tool/themes.py writes these, and css/themes.css). What a
       colour means (status chips, messages) is never colour alone: always an icon and words too. */
    /* theme:start */
    --color-ink: #000000;
    --color-panel: #0e0e0e;
    --color-raised: #1c1c1c;
    --color-line: #5a5a5a;
    --color-edge: #303030;
    --color-cream: #ffffff;
    --color-muted: #cfcfcf;
    --color-accent: #ff79da;
    --color-good: #62f07c;
    --color-warn: #ffc762;
    --color-bad: #ff5a52;
    --color-record: #ff5a52;
    --color-record-label: #000000;
    --color-part-1: #ff9139;
    --color-part-text-1: #000000;
    --color-part-ink-1: #ff9139;
    --color-part-2: #ffea6b;
    --color-part-text-2: #000000;
    --color-part-ink-2: #ffea6b;
    --color-part-3: #45eca4;
    --color-part-text-3: #000000;
    --color-part-ink-3: #45eca4;
    --color-part-4: #968dfd;
    --color-part-text-4: #000000;
    --color-part-ink-4: #968dfd;
    --color-part-5: #0a999f;
    --color-part-text-5: #000000;
    --color-part-ink-5: #0a999f;
    --color-part-6: #65c1fe;
    --color-part-text-6: #000000;
    --color-part-ink-6: #65c1fe;
    --color-part-7: #9f6acb;
    --color-part-text-7: #000000;
    --color-part-ink-7: #9f6acb;
    --color-part-8: #d66798;
    --color-part-text-8: #000000;
    --color-part-ink-8: #d66798;    /* theme:end */
    /* Admin's up and down (Growth's fair comparisons, docs/growth-compare-spec.md 4.3): blue and orange, not green and red,
       so they part for every common colour blindness and an ordinary dip doesn't read as an alarm. Always with an arrow
       and a word. Checked with the dataviz validator against each theme's panel (dark pair on #0e0e0e, #141b2d, #1d1e20,
       #1e1814; light pair on #ffffff): all pass. The light themes take the deeper pair, below. Outside the theme markers,
       which tool/themes.py rewrites. */
    --color-up: #3a8de0;
    --color-down: #d4751c;
    /* The accent's stronger shade (hover) and the words on it (tool/accents.py; Warm dark's own here). */
    --color-accent-strong: #6ae9c9;
    --color-accent-ink: #17120f;

    --radius-card: 1.5rem;
    --radius-field: 0.75rem;
    --radius-stage: 1.75rem; /* a stage panel: Home's card, the lesson end */
    --radius-tile: 18px; /* a tinted tile or radio card */
    --radius-inset: 14px; /* a list inset in a tile */
    --radius-bar: 10px; /* a chart's bar track */
}

/* The light themes' up and down (deeper, for the white panel; validated as above). */
:root[data-theme$='-light'] {
    --color-up: #1f6fd1;
    --color-down: #b85400;
}

/* Admin's experiment arms, A and B (Funnel, Experiments, Growth's arms): teal and violet, never blue or orange, which in
   admin mean up and down only (docs/design-rules.md). Each arm is also named by its letter and in a legend. Checked with
   the dataviz validator: the dark pair on #0e0e0e, #141b2d, #1d1e20 and #1e1814, the light pair on #ffffff, all pass
   (deutan ΔE 14.8 and 18.6). Read with a fallback (var(--color-arm-a, ...)), so a stylesheet not yet rebuilt still draws them. */
:root {
    --color-arm-a: #1f9e88;
    --color-arm-b: #9a6be6;
}
:root[data-theme$='-light'] {
    --color-arm-a: #0f8a75;
    --color-arm-b: #7a4fd6;
}

@layer base {
    /* A fieldset is as wide as its widest unbreakable content by default (min-content): a row of
       choices made a whole sheet wider than a phone. As wide as its place, like any block. */
    fieldset {
        min-width: 0;
    }
    html {
        color-scheme: dark;
        -webkit-tap-highlight-color: transparent;
        /* Pages with and without a scrollbar line up (the design review). */
        scrollbar-gutter: stable;
    }

    button:not(:disabled),
    summary,
    [role='button'] {
        cursor: pointer;
    }

    :focus-visible {
        outline: 2px solid var(--ring);
        outline-offset: 2px;
    }
}

/* Each count-in number pops in on the beat. */
.count-pop {
    animation: count-pop 0.35s ease-out;
}

@keyframes count-pop {
    from {
        transform: scale(1.35);
        opacity: 0.2;
    }
}

/* "Nice!" over a note just found: up and away (still with reduced motion; the template skips the class). */
.cheer-pop {
    animation: cheer-pop 0.9s ease-out forwards;
}

@keyframes cheer-pop {
    from {
        transform: translate(-50%, 6px) scale(0.85);
        opacity: 0;
    }
    25% {
        transform: translate(-50%, 0) scale(1);
        opacity: 1;
    }
    to {
        transform: translate(-50%, -10px);
        opacity: 0;
    }
}

/* A lesson's stars appear one after another (each with its chime). */
.star-in {
    animation: star-in 0.45s ease-out both;
}

@keyframes star-in {
    from {
        transform: scale(0.3);
        opacity: 0;
    }
}

@media (prefers-reduced-motion: reduce) {
    .star-in {
        animation: none;
    }
}

/* A new 2 or 3 stars (js/celebrate.js): a sparkle on the stars, or with reduced motion a glow. */
.celebrate-sparkle {
    animation: celebrate-sparkle 0.9s ease-out;
}

@keyframes celebrate-sparkle {
    30% {
        transform: scale(1.08);
        filter: brightness(1.35) drop-shadow(0 0 10px var(--color-accent));
    }
}

.celebrate-glow,
.celebrate-glow-strong {
    animation: celebrate-glow 2.1s ease-in-out;
}

.celebrate-glow-strong {
    --glow: 28px;
}

@keyframes celebrate-glow {
    40% {
        filter: drop-shadow(0 0 var(--glow, 14px) var(--color-accent));
    }
}

/* Glass gems (Hillel: "bubbles made out of glass, like in Bejeweled"; ux-spec 2.6a): one recipe for every
   playable piece that isn't a note (star discs, path nodes, the keyboard's marked keys, the main Play
   and Record, progress bars). Notes are js/glass.js's gemBar only (components/gems.js; Hillel,
   2026-10-28). Set --gem to the colour. A body that's brighter in the core and darker at the rim, a top bevel,
   a specular crescent top-left, a refraction band at the bottom, a coloured glow and a shadow under.
   Light themes: less glow, more edge and shadow. Cards and
   panels stay calm: never glass a surface. */
.gem {
    --gem: var(--color-accent);
    --gem-hi: rgb(255 255 255 / 0.7);
    --gem-glow: 0.5;
    isolation: isolate;
    color: var(--gem-ink, var(--color-accent-ink));
    background: radial-gradient(130% 100% at 32% 18%, color-mix(in oklab, var(--gem) 55%, white) 0%, var(--gem) 42%, color-mix(in oklab, var(--gem) 62%, black) 100%);
    border: 1.5px solid color-mix(in oklab, var(--gem) 55%, black);
    box-shadow:
        inset 0 1.5px 0 var(--gem-hi),
        inset 0 -4px 7px color-mix(in oklab, var(--gem) 45%, black),
        inset 0 -1.5px 0 color-mix(in oklab, var(--gem) 55%, white),
        0 6px 14px -4px color-mix(in oklab, var(--gem) calc(var(--gem-glow) * 100%), transparent),
        0 2px 3px rgb(0 0 0 / 0.35);
}
/* In the components layer, so a piece placed with `absolute` (the exercise lane's notes, the voice
   bead) stays placed: an unlayered rule here would beat every utility (Hillel's challenge screenshot,
   where the sung notes fell into a staircase). */
@layer components {
    .gem { position: relative; }
}
.gem::before {
    content: "";
    position: absolute;
    z-index: -1;
    left: 14%;
    top: 7%;
    width: 48%;
    height: 40%;
    border-radius: 999px;
    background: linear-gradient(180deg, rgb(255 255 255 / 0.85), rgb(255 255 255 / 0));
    transform: rotate(-12deg);
    pointer-events: none;
}
/* A bar (a note): the crescent becomes a gloss along the top. */
.gem-bar::before {
    left: 6px;
    right: 24%;
    top: 2px;
    width: auto;
    height: 42%;
    transform: none;
    border-radius: inherit;
}
/* Unlit: the same shape, quieter (never hidden: the shape and its words carry it). */
.gem-dim {
    --gem: var(--color-raised);
    --gem-glow: 0;
    --gem-ink: var(--color-muted);
    filter: saturate(0.6);
}
.gem-dim::before { opacity: 0.35; }
:root[data-theme$="-light"] .gem {
    --gem-hi: rgb(255 255 255 / 0.9);
    --gem-glow: 0.22;
    border-color: color-mix(in oklab, var(--gem) 45%, black);
    box-shadow:
        inset 0 1.5px 0 var(--gem-hi),
        inset 0 -4px 7px color-mix(in oklab, color-mix(in oklab, var(--gem) 70%, black) 60%, transparent),
        inset 0 -1.5px 0 color-mix(in oklab, var(--gem) 55%, white),
        0 4px 10px -4px color-mix(in oklab, var(--gem) calc(var(--gem-glow) * 100%), transparent),
        0 2px 4px rgb(0 0 0 / 0.22);
}
/* The exercises' lane (components/exercise.js): the stage the notes sit on and the playhead as a
   glowing beam. The notes themselves are js/glass.js's gems on a canvas (components/gems.js), as
   every note is. Reduced motion keeps the depth, not the motion. */
.lane-stage {
    background:
        linear-gradient(180deg, transparent 62%, color-mix(in oklab, var(--color-accent) 12%, transparent)),
        linear-gradient(180deg, color-mix(in oklab, var(--color-cream) 3%, transparent), transparent);
}
.lane-stage::after {
    content: "";
    position: absolute;
    inset: 0;
    pointer-events: none;
    background: radial-gradient(120% 90% at 50% 50%, transparent 55%, rgb(0 0 0 / 0.35));
}
:root[data-theme$="-light"] .lane-stage::after { background: radial-gradient(120% 90% at 50% 50%, transparent 60%, rgb(0 0 0 / 0.06)); }
.lane-speck { position: absolute; border-radius: 999px; background: var(--color-accent); opacity: 0.25; animation: lane-drift 18s linear infinite; }
@keyframes lane-drift { from { transform: translateX(0); } to { transform: translateX(-60px); } }
.lane-beam { background: var(--beam, var(--color-cream)); box-shadow: 0 0 10px 2px color-mix(in oklab, var(--beam, var(--color-cream)) 55%, transparent); }
@media (prefers-reduced-motion: reduce) {
    .lane-speck { animation: none; }
}

/* The keyboard round your note (components/results.js): a piano is a piano in every theme. */
.key-white { background: linear-gradient(180deg, #ffffff, #e9e9e6); color: #4a4a4a; box-shadow: inset 0 -3px 0 rgb(0 0 0 / 0.12), 0 1px 2px rgb(0 0 0 / 0.3); }
.key-range { background: linear-gradient(180deg, color-mix(in oklab, var(--color-accent) 42%, #101010), color-mix(in oklab, var(--color-accent) 30%, #101010)); color: #ffffff; box-shadow: inset 0 -3px 0 rgb(0 0 0 / 0.3), 0 1px 2px rgb(0 0 0 / 0.3); }
.key-black { background: linear-gradient(180deg, #2a2a2a, #0d0d0d); box-shadow: inset 0 -2px 0 rgb(255 255 255 / 0.08), 0 2px 3px rgb(0 0 0 / 0.45); z-index: 1; }
.key-black-range { background: linear-gradient(180deg, color-mix(in oklab, var(--color-accent) 30%, #0b0b0b), color-mix(in oklab, var(--color-accent) 18%, #050505)); box-shadow: 0 2px 3px rgb(0 0 0 / 0.45); z-index: 1; }

/* A gem won just now: it pops (1.05, then settles) and a glint sweeps across. */
.gem-pop { animation: gem-pop 0.5s cubic-bezier(0.3, 1.6, 0.5, 1) both; }
@keyframes gem-pop {
    from { transform: scale(0.3); opacity: 0; }
    70% { transform: scale(1.05); opacity: 1; }
}
.gem-glint::after {
    content: "";
    position: absolute;
    inset: 0;
    border-radius: inherit;
    background: linear-gradient(105deg, transparent 35%, rgb(255 255 255 / 0.75) 50%, transparent 65%) no-repeat;
    background-size: 250% 100%;
    animation: gem-glint 0.9s ease-out 0.25s both;
    pointer-events: none;
}
@keyframes gem-glint {
    from { background-position: 120% 0; }
    to { background-position: -60% 0; }
}
@media (prefers-reduced-motion: reduce) {
    .gem-pop, .gem-glint::after { animation: none; }
    .gem-glint::after { display: none; }
}

/* The Learn steps' drawings (js/components/learn-visual.js): in the accent, moving gently. */
.learn-visual svg { fill: var(--color-accent); stroke: var(--color-accent); }
.learn-visual .lv-dim { opacity: 0.28; }
.learn-visual .lv-line { fill: none; }
.learn-visual .lv-line2 { fill: none; stroke: var(--color-accent-strong); }
.learn-visual .lv-fill { opacity: 0.75; }
.lv-move { transform-box: fill-box; transform-origin: center; animation-duration: 3s; animation-iteration-count: infinite; animation-timing-function: ease-in-out; }
.learn-visual.is-held .lv-move { animation: none; } /* Up next's preview: a still frame */
.lv-climb { animation-name: lv-climb; }
.lv-slide { animation-name: lv-slide; }
.lv-settle { animation-name: lv-settle; }
.lv-mouth { animation-name: lv-mouth; animation-duration: 4.5s; }
.lv-pulse { animation-name: lv-pulse; }
.lv-word { animation-name: lv-word; animation-duration: 2.4s; }
.lv-along { offset-path: path('M30 170 Q150 30 270 170'); animation-name: lv-along; animation-duration: 4s; }
.lv-ring { animation-name: lv-ring; }
.lv-enter { stroke-dasharray: 240; animation-name: lv-enter; animation-duration: 3.6s; }
.lv-floor { animation-name: lv-floor; }
.lv-level { animation-name: lv-level; }
.lv-swell { animation-name: lv-swell; animation-duration: 4s; }
.lv-wave { animation-name: lv-wave; animation-duration: 1.2s; animation-timing-function: linear; }
@keyframes lv-climb { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-110px); } }
@keyframes lv-slide { from { transform: translateX(0); } to { transform: translateX(220px); } }
@keyframes lv-settle { 0%, 100% { transform: translateY(14px); opacity: 0.5; } 60% { transform: translateY(-20px); opacity: 1; } }
@keyframes lv-mouth { 0%, 100% { transform: scale(0.55, 0.7); } 33% { transform: scale(0.8, 0.95); } 66% { transform: scale(0.95, 1.5); } }
@keyframes lv-pulse { 0%, 30% { transform: scale(0.6); opacity: 0.4; } 60%, 100% { transform: scale(1); opacity: 1; } }
@keyframes lv-word { 0%, 100% { opacity: 0.25; } 20%, 40% { opacity: 1; } }
@keyframes lv-along { from { offset-distance: 0%; } to { offset-distance: 100%; } }
@keyframes lv-ring { 0%, 100% { opacity: 0.45; } 50% { opacity: 1; } }
@keyframes lv-enter { from { stroke-dashoffset: 240; } 40%, to { stroke-dashoffset: 0; } }
@keyframes lv-floor { 0%, 100% { opacity: 0.7; } 50% { opacity: 1; } }
@keyframes lv-level { 0%, 100% { transform: scaleY(0.6); } 50% { transform: scaleY(0.95); } }
@keyframes lv-swell { 0%, 100% { transform: scale(0.6, 0.4); } 50% { transform: scale(1, 1); } }
@keyframes lv-wave { from { transform: translateX(0); } to { transform: translateX(-40px); } }
@media (prefers-reduced-motion: reduce) {
    .lv-move { animation: none; }
    .lv-along { offset-distance: 50%; }
}

/* Listening for your voice: a ring that breathes while the app waits to hear you. */
.listen-breathe {
    animation: listen-breathe 2.4s ease-in-out infinite;
}

@keyframes listen-breathe {
    0%,
    100% {
        transform: scale(0.92);
        opacity: 0.35;
    }
    50% {
        transform: scale(1.12);
        opacity: 0.9;
    }
}

@media (prefers-reduced-motion: reduce) {
    .listen-breathe {
        animation: none;
        opacity: 0.6;
    }
}

/*
 * Every dropdown: our own chevron (the browsers' differ, and sit against the edge), inset from the
 * end as far as the field's text is from its start, with room so a long choice never runs under it.
 * Unlayered, so it wins over a select's own padding utilities.
 */
select:not([multiple]):not([size]) {
    appearance: none;
    /* A V of two 2px strokes, in the theme's muted (so it follows every theme), 20px from the end. */
    background-image: linear-gradient(45deg, transparent calc(50% - 1px), var(--color-muted) calc(50% - 1px) calc(50% + 1px), transparent calc(50% + 1px)), linear-gradient(-45deg, transparent calc(50% - 1px), var(--color-muted) calc(50% - 1px) calc(50% + 1px), transparent calc(50% + 1px));
    background-repeat: no-repeat;
    background-position: right 26px center, right 20px center;
    background-size: 6px 6px;
    padding-inline-end: 46px;
}

[dir='rtl'] select:not([multiple]):not([size]) {
    background-position: left 20px center, left 26px center;
}

select:disabled {
    opacity: 0.45;
}

.sing-controls {
    transition: opacity 0.4s;
}

@media (prefers-reduced-motion: reduce) {
    .sing-controls {
        transition: none;
    }

    .count-pop,
    .animate-pulse {
        animation: none;
    }
}

/*
 * Components for forms and the admin, after iaw's (docs/conventions.md, "Admin screens and forms
 * look like iaw"), in Stackapella's colours. Every form and admin screen is built from these, and
 * /styleguide shows them all.
 */

/* The top padding below a phone's notch, for the server's pages (Blade can't hold the CSS function: the architecture test reads it as PHP's). */
/* A song card's tools (Preview or Play, Info, More): on a mouse they show on hover, keyboard focus
   inside the card, or while playing or open (.is-on); a touch screen always shows them (Hillel). */
@media (hover: hover) and (pointer: fine) {
    .card-tools { opacity: 0; transition: opacity 120ms ease-out; }
    .group:hover .card-tools, .group:focus-within .card-tools, .card-tools.is-on { opacity: 1; }
}

@utility pt-safe {
    padding-top: max(1.25rem, env(safe-area-inset-top));
}

/* The app's top bar on the public site's grid (Hillel, 2026-11-08: "make the logo in the top left corner the same size in
   the marketing and app pages ... make the app match the marketing size and position"): .s-wrap's row (1200 px, 16 px
   in from each side, 40 from 900 px) and .s-top's bar (60 px tall, 80 from 900 px, below the notch), so the logo
   (components/icon.js Logo) sits exactly where the site's does. app-wrap alone is the row, for a bar that wraps. */
@utility app-wrap {
    width: 100%;
    max-width: 1200px;
    margin-inline: auto;
    padding-inline: 16px;
    @media (min-width: 900px) {
        padding-inline: 40px;
    }
}

/* Two columns from 900 px (Hillel's width design; docs/design-rules.md, "App screens use the width too"): what you set
   or read at left, about 60%, and what it makes with its ways on at right. Below 900 px, nothing: a phone stacks the same
   order. A screen places a child elsewhere with col-start and row-start at 900 px, keeping its DOM (and a phone's) order. */
@utility app-split {
    @media (min-width: 900px) {
        display: grid;
        grid-template-columns: minmax(0, 3fr) minmax(0, 2fr);
        column-gap: 1.5rem;
        align-items: start;
    }
}

@utility app-top {
    display: flex;
    align-items: center;
    gap: 8px;
    height: calc(60px + env(safe-area-inset-top));
    padding-top: env(safe-area-inset-top);
    @media (min-width: 900px) {
        height: calc(80px + env(safe-area-inset-top));
        gap: 12px;
    }
}

/* Every other screen's bar (Hillel, 2026-11-10: "can we make the app and admin header and page width match the marketing
   site"): the same row and height as app-top, so Back sits where the logo does, but a least height rather than a fixed
   one, so a long title takes a second line (and a page's action drops under it) instead of being cut. One row is
   centred in the 60 or 80 px exactly as the site's logo is. components/page.js PageHeader draws it. */
@utility app-bar {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    column-gap: 12px;
    row-gap: 4px;
    min-height: calc(60px + env(safe-area-inset-top));
    padding-block: 8px;
    padding-top: calc(8px + env(safe-area-inset-top));
    @media (min-width: 900px) {
        min-height: calc(80px + env(safe-area-inset-top));
    }
}

@utility card {
    @apply rounded-[var(--radius-card)] border border-edge bg-panel;
}

@utility card-interactive {
    @apply card transition hover:border-muted/60 focus-visible:border-muted/60 has-[:focus-visible]:border-muted/60;
}

/*
 * Controls and forms, one system for both skins (Hillel, 2026-10-29: "I like new design system, I
 * think it works well for game mode on or off"; the spec is ~/Code/shots-review/designs/forms/NOTES.md).
 * - Gloss only on the note gems: every control is flat.
 * - Depth means "you can tap this" or "this is chosen": one small lift (--lift) on the chosen
 *   segment, a switch knob, a checked box or radio and a slider thumb. Nothing else gets a shadow.
 * - Fields are soft tints with no border at rest, a 2px ring on focus, a red ring and a message on error.
 * - Every control is 44px tall or keeps a 44px target. Fields share the buttons' corners.
 * - Two colours, two jobs: the primary says "do this" (cream in serious, the accent in game); the
 *   accent says "chosen" and draws the focus ring (cyan draws it in game).
 * The tokens come from each theme's own colours, so every theme and every custom accent gets them.
 * The fills are translucent, so the same token works on the page, a panel or a sheet.
 */
:root,
[data-theme] {
    --fill: color-mix(in srgb, var(--color-cream) 6%, transparent);
    --fill-2: color-mix(in srgb, var(--color-cream) 9%, transparent);
    --fill-3: color-mix(in srgb, var(--color-cream) 12%, transparent);
    --fill-4: color-mix(in srgb, var(--color-cream) 16%, transparent);
    --primary: var(--color-cream);
    --primary-ink: var(--color-ink);
    --selected: var(--color-accent);
    --selected-ink: var(--color-accent-ink);
    --ring: var(--color-accent);
    --ring-halo: color-mix(in srgb, var(--ring) 22%, transparent);
    --danger: var(--color-bad);
    --danger-ink: var(--color-record-label);
    --danger-halo: color-mix(in srgb, var(--danger) 20%, transparent);
    /* Hover and press move a solid fill away from its words, so they keep their contrast: in dark
       themes a coloured fill (the accent, the red) lightens, in light themes it darkens. The serious
       primary, white or cream with dark words, darkens a touch and stays far above AA. */
    --primary-hover-to: var(--color-ink);
    --solid-hover-to: white;
    /* A checkbox's and a radio's outline: 3:1 or better on the panel. */
    --box-edge: color-mix(in srgb, var(--color-cream) 45%, var(--color-panel));
    /* The off knob is muted, not white: 3:1 or better on its light track (the spec's call 3). */
    --knob-off: var(--color-muted);
    --lift: 0 1px 2px rgb(0 0 0 / 0.7), 0 0 0 0.5px rgb(0 0 0 / 0.4);
    --sel-wash: color-mix(in srgb, var(--selected) 9%, transparent);
    /* Corners: serious is round (fields are pills, the spec's call 2), game is crisp. */
    --r-control: 999px;
    --r-multi: 22px;
    --r-seg: 999px;
    --r-box: 6px;
    --r-pill: calc(infinity * 1px); /* a chip or a go button: as rounded-full */
    /* Buttons' shape: a skin can give them a drop shadow, an outlined secondary, a press and a clear secondary. */
    --btn-drop: none;
    --btn-outline: none;
    --btn-outline-pressed: none;
    --btn-press: none;
    --btn-soft: var(--fill-2);
    --btn-soft-hover: var(--fill-3);
    --btn-soft-active: var(--fill-4);
}

[data-theme$='-light'] {
    --solid-hover-to: black;
    --box-edge: color-mix(in srgb, var(--color-cream) 50%, var(--color-panel));
    --lift: 0 1px 2px rgb(0 0 0 / 0.18), 0 1px 1px rgb(0 0 0 / 0.08);
}

@utility btn {
    @apply inline-flex min-h-11 items-center justify-center gap-2 px-5 text-[0.9375rem] leading-none font-[650] whitespace-nowrap transition select-none disabled:pointer-events-none disabled:opacity-[0.42] aria-busy:cursor-progress;
    border-radius: var(--r-control);
}

/* Buttons are flat (Hillel, 2026-10-29: "lets change to a more modern flat style instead. the
   blocks will stand out even more"): only the notes (glass.js's gems, .gem) stay glossy. The
   primary is solid; hover mixes toward the page, press a little more. No shadow. */
@utility btn-primary {
    @apply btn;
    color: var(--primary-ink);
    background-color: var(--primary);
    box-shadow: var(--btn-drop);
    &:hover { background-color: color-mix(in oklab, var(--primary) 88%, var(--primary-hover-to)); }
    &:active { background-color: color-mix(in oklab, var(--primary) 78%, var(--primary-hover-to)); }
    &:active:not(:disabled) { transform: var(--btn-press); box-shadow: none; }
}

/* The secondary is a soft tint, never an outline ("Continue with Google" is one). */
@utility btn-secondary {
    @apply btn text-cream;
    background-color: var(--btn-soft);
    box-shadow: var(--btn-outline);
    &:hover { background-color: var(--btn-soft-hover); }
    &:active { background-color: var(--btn-soft-active); }
    &:active:not(:disabled) { transform: var(--btn-press); box-shadow: var(--btn-outline-pressed); }
}

/* Text only, in muted; a tint and cream on hover. */
@utility btn-ghost {
    @apply btn text-muted;
    &:hover { background-color: var(--fill); color: var(--color-cream); }
    &:active { background-color: var(--fill-2); color: var(--color-cream); }
}

/* Only on the final confirm of something destructive. */
@utility btn-danger {
    @apply btn;
    color: var(--danger-ink);
    background-color: var(--danger);
    box-shadow: var(--btn-drop);
    &:hover { background-color: color-mix(in oklab, var(--danger) 88%, var(--solid-hover-to)); }
    &:active { background-color: color-mix(in oklab, var(--danger) 78%, var(--solid-hover-to)); }
    &:active:not(:disabled) { transform: var(--btn-press); box-shadow: none; }
}

/* The red of Record (the studio's and Sing's Record), flat like every button. */
@utility glass-record {
    color: var(--color-record-label);
    background-color: var(--color-record);
    &:hover { background-color: color-mix(in oklab, var(--color-record) 88%, black); }
    &:active { background-color: color-mix(in oklab, var(--color-record) 78%, black); }
}

/* The app's shell before it draws (index.html): the logo, centred, faded in after 0.4 s so a quick load never shows it. */
.app-splash { position: fixed; inset: 0; display: grid; place-items: center; opacity: 0; animation: app-splash-in 0.3s ease 0.4s forwards; }
@keyframes app-splash-in { to { opacity: 1; } }
@media (prefers-reduced-motion: reduce) { .app-splash { animation-duration: 0.01s; } }

/* A round icon button (Play, back, close, plus and minus): the secondary's tint, or with
   glass-bubble-solid the primary. Flat; the names stay for the markup that uses them (not the glossy .bubble above). */
@utility glass-bubble {
    background-color: var(--fill-2);
    &:hover { background-color: var(--fill-3); }
    &:active { background-color: var(--fill-4); }
}

@utility glass-bubble-solid {
    color: var(--primary-ink);
    background-color: var(--primary);
    &:hover { background-color: color-mix(in oklab, var(--primary) 88%, var(--primary-hover-to)); }
    &:active { background-color: color-mix(in oklab, var(--primary) 78%, var(--primary-hover-to)); }
}

@utility btn-sm {
    @apply min-h-9 px-3.5 text-sm;
}

@utility btn-lg {
    @apply min-h-13 px-7 text-base;
}

/* A button that's working: a 16px spinner before the label (with aria-busy="true" on the button). */
@utility spinner {
    @apply inline-block size-4 shrink-0 animate-spin rounded-full border-2 border-current;
    border-inline-end-color: transparent;
    @media (prefers-reduced-motion: reduce) { animation-duration: 2.4s; }
}

/* A segmented control: a role="radiogroup" on a tinted track, the chosen segment in the accent with
   the small lift. role=radio with aria-checked, or aria-pressed, or .is-on marks the chosen one;
   the arrow keys move the choice (components/controls.js, Segmented). */
@utility seg {
    /* min-w-0: in a flex row it may shrink below its words, so a squeeze shows as its own overflow (fitSegments) instead of pushing out of the row. */
    @apply inline-flex max-w-full min-w-0 items-center gap-0.5 p-1;
    border-radius: var(--r-control);
    background-color: var(--fill-2);
}

/* A segmented control never wraps (Hillel's 84.png: "Chapel" alone on a second row inside the pill).
   When its options don't fit on one row, js/components/controls.js fitSegments adds seg-stack: equal
   segments two by two, or one under another for an odd count, each on its own line, never squeezed. */
.seg.seg-stack {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    width: 100%;
}
.seg.seg-stack.seg-stack-1 { grid-template-columns: minmax(0, 1fr); }
.seg.seg-stack > .seg-option { width: 100%; min-width: 0; white-space: normal; text-align: center; padding-block: 0.375rem; }

/* Just the segmented control's track, for a group laid out its own way (a grid). */
@utility seg-bg {
    background-color: var(--fill-2);
}

@utility seg-option {
    @apply relative inline-flex min-h-9 cursor-pointer items-center justify-center px-4 text-sm font-semibold whitespace-nowrap text-muted transition;
    border-radius: var(--r-seg);
    &:not([aria-checked='true'], [aria-pressed='true'], .is-on, :has(input:checked)):hover { color: var(--color-cream); background-color: var(--fill); }
    &:focus-visible { z-index: 1; }
    /* A label around a hidden radio (sr-only) works as a segment too. */
    &:has(input:focus-visible) { z-index: 1; outline: 2px solid var(--ring); outline-offset: 2px; }
    &[aria-checked='true'],
    &[aria-pressed='true'],
    &:has(input:checked),
    &.is-on {
        background-color: var(--selected);
        color: var(--selected-ink);
        box-shadow: var(--lift);
    }
}

/* A switch: a 48 x 28 track, its 22px knob muted when off, and the accent with the accent's ink
   when on; the knob has the small lift and stretches while pressed. On a role="switch" button
   (52 x 44 around it, components/controls.js), which sets aria-checked, or `is-on` on the track. */
@utility switch-track {
    @apply relative h-7 w-12 shrink-0 rounded-full transition-colors;
    background-color: var(--fill-3);
    [role='switch']:hover > & { background-color: var(--fill-4); }
    &.is-on,
    [aria-checked='true'] > & { background-color: var(--selected); }
    [aria-checked='true']:hover > &,
    [role='switch']:hover > &.is-on { background-color: color-mix(in oklab, var(--selected) 86%, var(--color-cream)); }
    [role='switch']:focus-visible > & { outline: 2px solid var(--ring); outline-offset: 2px; }
}

@utility switch-knob {
    @apply absolute top-[3px] size-[22px] rounded-full transition-[inset-inline-start,width,background-color] duration-150;
    inset-inline-start: 3px;
    background-color: var(--knob-off);
    box-shadow: var(--lift);
    [role='switch']:active & { width: 26px; }
    .is-on > &,
    [aria-checked='true'] & {
        inset-inline-start: 23px;
        background-color: var(--selected-ink);
    }
    [aria-checked='true']:active & { inset-inline-start: 19px; }
    @media (prefers-reduced-motion: reduce) { transition: none; }
}

/* A small control (a chip, a segmented toggle) whose tap area is still 44 px: an invisible box around it. */
@utility tap-44 {
    position: relative;
    &::after {
        content: '';
        position: absolute;
        left: 50%;
        top: 50%;
        width: max(100%, 44px);
        height: max(100%, 44px);
        transform: translate(-50%, -50%);
    }
}

/* A status tag (StatusChip): never a button. */
@utility chip {
    @apply inline-flex min-h-6 items-center gap-1.5 px-2.5 text-xs font-semibold text-muted;
    border-radius: var(--r-pill);
    background-color: var(--fill-2);
}

/* A status tag in the accent (Plus, Polished): a wash of it with accent words. */
@utility chip-accent {
    @apply chip text-accent;
    background-color: var(--sel-wash);
}

/* A chip you press (aria-pressed) or pick from a few (role=radio, aria-checked): 32px, with a 44px
   target; the accent when on. */
@utility filter-chip {
    @apply tap-44 inline-flex min-h-8 items-center gap-1.5 px-3 text-[0.84375rem] leading-none font-semibold whitespace-nowrap text-cream transition disabled:pointer-events-none disabled:opacity-[0.42];
    border-radius: var(--r-control);
    background-color: var(--fill-2);
    &:not([aria-pressed='true'], [aria-checked='true'], [aria-current='true'], :has(input:checked)):hover { background-color: var(--fill-3); }
    &:not([aria-pressed='true'], [aria-checked='true'], [aria-current='true'], :has(input:checked)):active { background-color: var(--fill-4); }
    /* A label around a hidden checkbox works as a chip too. */
    &:has(input:focus-visible) { outline: 2px solid var(--ring); outline-offset: 2px; }
    &:has(input:disabled) { opacity: 0.42; cursor: not-allowed; }
    &[aria-pressed='true'],
    &[aria-checked='true'],
    &[aria-current='true'],
    &:has(input:checked) { background-color: var(--selected); color: var(--selected-ink); }
}

/* A field: a soft tint with no border; a tint more on hover; on focus a 2px ring with a faint halo;
   on error (aria-invalid) a red ring, and the message under it says what to do. Read-only fields lose
   the tint and get a faint edge (the spec's call 4), so they never look typeable. 16px text on
   every screen: iOS zooms into anything smaller. */
@utility input {
    @apply block min-h-11 w-full border-0 px-[18px] py-2.5 text-base leading-snug text-cream transition outline-none;
    border-radius: var(--r-control);
    background-color: var(--fill);
    &::placeholder { color: var(--color-muted); opacity: 1; }
    &:hover { background-color: var(--fill-2); }
    &:focus { background-color: var(--fill); box-shadow: inset 0 0 0 2px var(--ring), 0 0 0 4px var(--ring-halo); }
    &[aria-invalid='true'] { box-shadow: inset 0 0 0 2px var(--danger); }
    &[aria-invalid='true']:focus { box-shadow: inset 0 0 0 2px var(--danger), 0 0 0 4px var(--danger-halo); }
    &:disabled { opacity: 0.45; cursor: not-allowed; }
    &[readonly] { background-color: transparent; box-shadow: inset 0 0 0 1.5px var(--fill-4); cursor: default; }
    &[readonly]:focus { box-shadow: inset 0 0 0 2px var(--ring), 0 0 0 4px var(--ring-halo); }
    &:is(textarea) { padding-block: 12px; border-radius: var(--r-multi); line-height: 1.45; }
    & option { background-color: var(--color-panel); color: var(--color-cream); }
}

/* A field with an icon inside (a lock on a read-only field, a spinner while a handle is checked): the
   wrapper places it, the field makes room with `pe-[46px]` (or `ps-11` for one at the start). */
@utility input-icon {
    @apply pointer-events-none absolute top-1/2 -translate-y-1/2 text-muted;
}

/* A stepper (− value +): the field's tint with two ghost round buttons; the ring on focus-within. */
@utility stepper {
    @apply inline-flex min-h-11 items-center p-1 transition;
    border-radius: var(--r-control);
    background-color: var(--fill);
    &:focus-within { box-shadow: inset 0 0 0 2px var(--ring), 0 0 0 4px var(--ring-halo); }
    & > button { @apply grid size-9 shrink-0 place-items-center text-cream transition; border-radius: var(--r-seg); }
    & > button:hover { background-color: var(--fill-2); }
    & > button:active { background-color: var(--fill-4); }
    & > button:disabled { opacity: 0.35; cursor: not-allowed; background-color: transparent; }
    & > button:focus-visible { outline: none; box-shadow: inset 0 0 0 2px var(--ring); }
    & input { @apply w-16 border-0 bg-transparent p-0 text-center text-base font-[650] text-cream tabular-nums outline-none; }
}

/* A checkbox or radio, drawn on the native input itself (appearance: none): 22px, a tint with a
   1.5px edge; checked, the accent with the small lift and its mark (a 14px check, an 8px dot, a
   10px bar when partly checked) in the accent's ink. Put it in a `check-row` label. */
@utility checkbox {
    @apply relative m-0 grid size-[22px] shrink-0 cursor-pointer place-items-center transition;
    appearance: none;
    border-radius: var(--r-box);
    background-color: var(--fill);
    box-shadow: inset 0 0 0 1.5px var(--box-edge);
    &::before {
        content: '';
        width: 14px;
        height: 14px;
        background-color: var(--selected-ink);
        clip-path: polygon(14% 44%, 0 59%, 39% 96%, 100% 22%, 86% 8%, 38% 66%);
        transform: scale(0);
        transition: transform 0.12s;
    }
    &:hover { background-color: var(--fill-3); }
    &:checked,
    &[type='checkbox']:indeterminate { background-color: var(--selected); box-shadow: var(--lift); }
    &:checked::before { transform: scale(1); }
    &[type='checkbox']:indeterminate::before { height: 2px; width: 10px; clip-path: none; border-radius: 2px; transform: scale(1); }
    &[aria-invalid='true']:not(:checked) { box-shadow: inset 0 0 0 2px var(--danger); }
    &:disabled { opacity: 0.45; cursor: not-allowed; }
}

@utility radio {
    @apply checkbox;
    border-radius: 999px;
    &::before { width: 8px; height: 8px; border-radius: 999px; clip-path: none; }
}

/* A checkbox's or radio's row: the label beside it, at least 44px tall, with an optional line under. */
@utility check-row {
    @apply flex min-h-11 cursor-pointer items-center gap-3 text-[0.9375rem] leading-snug font-medium text-cream;
    &:has(:disabled) { cursor: not-allowed; color: color-mix(in srgb, var(--color-cream) 55%, transparent); }
}

/* A choice as a card (a role="radio" button, or a label holding a radio): a tint, and when chosen a
   wash of the accent with a 2px accent ring. */
@utility radio-card {
    @apply relative flex cursor-pointer items-start gap-3 rounded-tile px-4 py-3.5 text-start text-cream transition;
    background-color: var(--fill);
    &:hover { background-color: var(--fill-2); }
    &[aria-checked='true'],
    &[aria-pressed='true'],
    &:has(input:checked) { background-color: var(--sel-wash); box-shadow: inset 0 0 0 2px var(--selected); }
    &:has(input:focus-visible) { outline: 2px solid var(--ring); outline-offset: 2px; }
    :root[data-skin='game'] & { border-radius: var(--r-control); }
}

/* A radio drawn inside a role="radio" (or aria-pressed) button or card, where there's no native
   input: the radio's look, filled when its button is chosen. */
@utility radio-mark {
    @apply grid size-[22px] shrink-0 place-items-center rounded-full transition;
    background-color: var(--fill);
    box-shadow: inset 0 0 0 1.5px var(--box-edge);
    &::before { content: ''; width: 8px; height: 8px; border-radius: 999px; background-color: var(--selected-ink); transform: scale(0); transition: transform 0.12s; }
    [aria-checked='true'] &,
    [aria-pressed='true'] & { background-color: var(--selected); box-shadow: var(--lift); }
    [aria-checked='true'] &::before,
    [aria-pressed='true'] &::before { transform: scale(1); }
}

/* A slider: a 6px track filled in the accent up to the value (--p, set from the value), and a 22px
   accent thumb with a collar in the panel's colour, in a 44px-tall input. */
@utility range {
    --p: 50%;
    @apply m-0 h-11 w-full cursor-pointer bg-transparent disabled:cursor-not-allowed disabled:opacity-[0.42];
    appearance: none;
    &:focus { outline: none; }
    &::-webkit-slider-runnable-track { height: 6px; border-radius: 99px; background: linear-gradient(90deg, var(--selected) var(--p), var(--fill-3) var(--p)); }
    &::-moz-range-track { height: 6px; border-radius: 99px; background: linear-gradient(90deg, var(--selected) var(--p), var(--fill-3) var(--p)); }
    &::-webkit-slider-thumb { appearance: none; width: 22px; height: 22px; margin-top: -8px; border: 0; border-radius: 99px; background: var(--selected); box-shadow: 0 0 0 3px var(--color-panel), var(--lift); transition: transform 0.12s; }
    &::-moz-range-thumb { width: 22px; height: 22px; border: 0; border-radius: 99px; background: var(--selected); box-shadow: 0 0 0 3px var(--color-panel), var(--lift); }
    &:hover::-webkit-slider-thumb { transform: scale(1.1); }
    &:active::-webkit-slider-thumb { transform: scale(1.2); }
    &:focus-visible::-webkit-slider-thumb { box-shadow: 0 0 0 3px var(--color-panel), 0 0 0 5px var(--ring); }
    &:focus-visible::-moz-range-thumb { box-shadow: 0 0 0 3px var(--color-panel), 0 0 0 5px var(--ring); }
    &:dir(rtl)::-webkit-slider-runnable-track { background: linear-gradient(270deg, var(--selected) var(--p), var(--fill-3) var(--p)); }
    &:dir(rtl)::-moz-range-track { background: linear-gradient(270deg, var(--selected) var(--p), var(--fill-3) var(--p)); }
}

/* A form's label, hint and error: 14px/600, 13px, 13px/600 in the danger red with its icon. */
@utility label {
    @apply block text-sm font-semibold text-cream;
}

@utility help {
    @apply text-[0.8125rem] leading-snug text-muted;
}

@utility field-error {
    @apply flex items-start gap-1.5 text-[0.8125rem] leading-snug font-semibold;
    color: var(--danger);
}

/* More contrast: the tinted controls get a 3:1 edge, but never over a field's focus or error ring
   (unlayered, so it would win over them). */
@media (prefers-contrast: more) {
    .input:not(:focus, [aria-invalid='true'], [readonly]), .stepper:not(:focus-within), .seg, .switch-track { box-shadow: inset 0 0 0 1px var(--box-edge); }
}

/* Forced colours (Windows High Contrast) drop fills and shadows, so every state is drawn again in
   system colours: real borders, focus as an outline, and chosen (on, checked, picked) in Highlight. */
@media (forced-colors: active) {
    .input, .stepper, .seg, .switch-track, .checkbox, .radio, .radio-mark, .filter-chip, .btn-secondary, .radio-card { border: 1px solid CanvasText; }
    .input:focus, .stepper:focus-within, .range:focus-visible { outline: 2px solid Highlight; outline-offset: 2px; }
    .seg-option[aria-checked='true'], .seg-option[aria-pressed='true'], .seg-option:has(input:checked),
    .filter-chip[aria-pressed='true'], .filter-chip[aria-checked='true'], .filter-chip[aria-current='true'], .filter-chip:has(input:checked) { forced-color-adjust: none; background: Highlight; color: HighlightText; }
    .checkbox:checked, .checkbox[type='checkbox']:indeterminate, .radio:checked,
    [aria-checked='true'] .radio-mark, [aria-pressed='true'] .radio-mark { forced-color-adjust: none; background: Highlight; border-color: Highlight; }
    .checkbox::before, .radio::before, .radio-mark::before { forced-color-adjust: none; background: HighlightText; }
    .switch-track { forced-color-adjust: none; background: Canvas; }
    .switch-knob { forced-color-adjust: none; background: CanvasText; }
    [aria-checked='true'] > .switch-track, .switch-track.is-on { background: Highlight; border-color: Highlight; }
    [aria-checked='true'] .switch-knob, .is-on > .switch-knob { background: HighlightText; }
    .radio-card[aria-checked='true'], .radio-card[aria-pressed='true'], .radio-card:has(input:checked) { outline: 3px solid Highlight; outline-offset: -3px; }
    .range { forced-color-adjust: none; }
    .range::-webkit-slider-runnable-track { background: linear-gradient(90deg, Highlight var(--p), GrayText var(--p)); }
    .bubble { border: 1px solid CanvasText; box-shadow: none; }
    .bubble::before { display: none; }
    .range::-moz-range-track { background: linear-gradient(90deg, Highlight var(--p), GrayText var(--p)); }
    .range::-webkit-slider-thumb { background: Highlight; box-shadow: 0 0 0 2px CanvasText; }
    .range::-moz-range-thumb { background: Highlight; box-shadow: 0 0 0 2px CanvasText; }
}

@utility eyebrow {
    @apply text-xs font-semibold tracking-[0.12em] text-accent uppercase;
}

/* A link for a quiet action beside a form (Forgot password?, Create an account): the words alone,
   underlined in the accent on hover and focus. `link` (always underlined) is for links in prose. */
/* A "go to" action (Course map, See all, Your voice): a small button with a chevron, never an
   underlined link (Hillel's call; underlines are for links inside sentences). */
@utility btn-go {
    @apply inline-flex min-h-9 shrink-0 items-center gap-1.5 px-3.5 text-sm font-semibold text-cream transition;
    border-radius: var(--r-pill);
    background-color: var(--btn-go-bg, color-mix(in oklab, var(--color-cream) 9%, transparent));
    box-shadow: var(--btn-outline);
    &:hover, &:focus-visible { background-color: var(--btn-go-hover, color-mix(in oklab, var(--color-cream) 14%, transparent)); }
    &:active:not(:disabled) { transform: var(--btn-press); box-shadow: var(--btn-outline-pressed); }
    &::after {
        content: '';
        width: 0.45em;
        height: 0.45em;
        border-top: 2px solid currentColor;
        border-inline-end: 2px solid currentColor;
        transform: rotate(45deg);
        opacity: 0.7;
    }
    &:dir(rtl)::after {
        transform: rotate(-45deg);
    }
}

@utility link-quiet {
    @apply font-semibold text-cream underline decoration-transparent decoration-2 underline-offset-4 transition hover:decoration-accent focus-visible:decoration-accent;
}

@utility link {
    @apply font-medium text-cream underline decoration-accent decoration-2 underline-offset-4 transition hover:text-accent-strong hover:decoration-accent-strong;
    /* A link that can't be used now looks it: dimmed, no underline, no pointer. */
    &:disabled,
    &[aria-disabled='true'] {
        @apply cursor-default no-underline opacity-45 hover:decoration-transparent;
    }
}

/* A loading placeholder: it pulses, and holds still under reduced motion (WCAG 2.3.3; the a11y sweep, 2026-11-02). */
@utility skeleton {
    @apply animate-pulse rounded-[var(--radius-field)] bg-raised motion-reduce:animate-none;
}

@utility divider {
    @apply border-t border-line;
}

@utility data-table {
    @apply w-full text-sm;

    & thead {
        @apply text-start text-xs text-muted uppercase;
    }

    & th {
        @apply px-4 py-3 text-start font-semibold whitespace-nowrap;
    }

    & td {
        @apply px-4 py-2.5 align-top;
    }

    & thead tr,
    & tbody tr {
        @apply border-b border-line;
    }

    & tbody tr:last-child {
        @apply border-b-0;
    }
}

@utility kbd {
    @apply inline-flex min-w-5 items-center justify-center rounded border border-line bg-raised px-1 tabular-nums text-[0.7rem] text-cream;
}

/* landing:start */
/* The public site in direction A (docs/public-site-plan.md, board-a2): the landing, the feature and
   "for" pages, about, press. Its own `s-` names, so nothing here touches the app's styles. Colours
   are theme tokens only; part colours come from `s-v1` to `s-v4` (--c, --ci, --ct). Players set
   [data-playing] and --p (0 to 1) on their root (js/public/mixer.js). */
.s-wrap { max-width: 1200px; margin-inline: auto; padding-inline: 16px; }
.s-v1 { --c: var(--color-part-1); --ci: var(--color-part-ink-1); --ct: var(--color-part-text-1); }
.s-v2 { --c: var(--color-part-2); --ci: var(--color-part-ink-2); --ct: var(--color-part-text-2); }
.s-v3 { --c: var(--color-part-3); --ci: var(--color-part-ink-3); --ct: var(--color-part-text-3); }
.s-v4 { --c: var(--color-part-4); --ci: var(--color-part-ink-4); --ct: var(--color-part-text-4); }
/* Parts 5 and 6, for a set of more than four (a voice type's six; game colours each one's range bar by them). */
.s-v5 { --c: var(--color-part-5); --ci: var(--color-part-ink-5); --ct: var(--color-part-text-5); }
.s-v6 { --c: var(--color-part-6); --ci: var(--color-part-ink-6); --ct: var(--color-part-text-6); }
.s-lk { color: var(--color-cream); font-weight: 600; text-decoration: underline; text-decoration-color: color-mix(in srgb, var(--color-accent) 70%, transparent); text-decoration-thickness: 2px; text-underline-offset: 4px; padding-block: 12px; margin-block: -12px; }
.s-lk:hover { text-decoration-color: var(--color-accent); }
/* Calm's link underline is ink, not pink (Hillel: "not pink for serious mode"; the design direction's final check). */
:root:not([data-skin='game']) .s-lk { text-decoration-color: color-mix(in srgb, var(--color-cream) 40%, transparent); }
:root:not([data-skin='game']) .s-lk:hover { text-decoration-color: var(--color-cream); }
/* A link's last word and its arrow stay on one line (x-site.arrow-end; Hillel: "it should be after singers not next line").
   The arrow is inline here, where preflight makes every svg a block; a page's own rule may set its alignment after this. */
.s-nw { white-space: nowrap; }
.s-nw > svg { display: inline-block; vertical-align: -0.2em; }
.s-soon { display: inline-flex; align-items: center; gap: 6px; font-size: 12.5px; font-weight: 700; color: var(--color-muted); white-space: nowrap; letter-spacing: 0; text-transform: none; }
.s-soon::before { content: ''; width: 7px; height: 7px; border-radius: 9px; box-shadow: inset 0 0 0 1.5px var(--color-muted); }
/* The eyebrow: uppercase, 0.12em, in the accent (docs/ux-spec.md 2.4); small words take the accent's
   strong shade, which passes AA on every palette (tool/accents.py). */
.s-eyebrow { font-size: 12px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; color: var(--color-accent-strong); display: flex; flex-wrap: wrap; align-items: center; gap: 8px 14px; }
.s-eyebrow .s-dots { display: inline-flex; gap: 3px; }
.s-eyebrow .s-dots b { width: 6px; height: 6px; border-radius: 9px; background: var(--c); }
.s-disc { width: 40px; height: 40px; border-radius: 99px; display: grid; place-items: center; font-size: 18px; font-weight: 800; flex: none; transition: box-shadow .2s, background .2s; }
.s-disc:not(.gem) { background: var(--c); color: var(--ct); }

/* The header and the menu (the light and dark switch is in the menu on phones). */
.s-top { display: flex; align-items: center; gap: 8px; height: calc(60px + env(safe-area-inset-top)); padding-top: env(safe-area-inset-top); }
.s-brand { display: flex; align-items: center; gap: 9px; min-height: 44px; min-width: 44px; font-weight: 800; font-size: 18px; letter-spacing: -0.01em; margin-inline-end: auto; color: var(--color-cream); }
.s-brand > svg { flex: none; } /* the mark keeps its 30 px however full the bar (the app's logo matches it) */
/* The Santa hat on the mark (Icons::hat): the carols page through Christmas Day, every page on Christmas Day itself
   (js/public/season.js). Worn on the mark's top-left corner (Hillel: "it should be on the corner and look like a hat
   on the block"): web/icons/santa-hat.svg is drawn in the mark's own box with room above and to the left (39 by 42, its
   0 to 30 square the mark's 30 px), its brim across the corner; an object only (game mode's in pixels, below); the
   mark itself never moves. */
.s-brand { position: relative; } /* the hat's place (Icons::hat) */
.s-brand > .s-hat[hidden] { display: none; }
.s-brand > .s-hat { position: absolute; left: -9px; top: calc(50% - 27px); width: 39px; height: 42px; pointer-events: none; filter: drop-shadow(0 1px 1px rgba(0, 0, 0, .3)); }
/* Game mode's hat: the same hat in the same box, traced in 2 px pixels on the mark's grid (web/icons/santa-hat-pixel.svg,
   the drawing's own shapes hidden), its shadow hard as a sprite's. */
:root[data-skin='game'] .s-brand > .s-hat > * { display: none; }
:root[data-skin='game'] .s-brand > .s-hat { background: url('/icons/santa-hat-pixel.svg') 0 0 / 100% 100% no-repeat; filter: drop-shadow(0 2px 0 rgba(0, 0, 0, .3)); }
.s-nav { display: none; gap: 4px; font-size: 15px; }
.s-nav a { display: inline-flex; align-items: center; min-height: 44px; padding-inline: 12px; font-weight: 600; color: var(--color-muted); border-radius: 99px; }
/* Navigation links (the header, the footer, the back links) are plain words, underlined in the accent
   only on hover and keyboard focus, as the app's link-quiet; links inside sentences keep theirs
   (docs/ux-spec.md 4.2; WCAG 1.4.1). */
.s-nav a, .s-flink { text-decoration: underline 2px transparent; text-underline-offset: 6px; transition: color .15s, text-decoration-color .15s; }
.s-nav a:hover, .s-nav a:focus-visible, .s-flink:hover, .s-flink:focus-visible { color: var(--color-cream); text-decoration-color: var(--color-accent); }
.s-nav a[aria-current="page"] { color: var(--color-cream); }
.s-iconbtn { @apply glass-bubble; width: 44px; height: 44px; flex: none; border-radius: 999px; display: grid; place-items: center; color: var(--color-muted); cursor: pointer; }
.s-iconbtn:hover { color: var(--color-cream); }
.s-dark-only { display: none; }
:root[data-theme$="-dark"] .s-dark-only { display: inline; }
:root[data-theme$="-dark"] .s-light-only { display: none; }
.s-menu { position: relative; }
.s-menu summary { list-style: none; }
.s-menu summary::-webkit-details-marker { display: none; }
.s-menu-panel { position: absolute; inset-inline-end: 0; top: calc(100% + 8px); z-index: 30; width: min(280px, calc(100vw - 32px)); display: grid; padding: 8px; border-radius: 20px; background: var(--color-panel); border: 1px solid var(--color-line); box-shadow: 0 20px 50px color-mix(in srgb, var(--color-cream) 14%, transparent); }
.s-menu-panel a, .s-menu-panel button { display: flex; align-items: center; gap: 10px; min-height: 48px; padding-inline: 12px; border-radius: 12px; font-weight: 650; color: var(--color-cream); text-align: start; cursor: pointer; }
.s-menu-panel a:hover, .s-menu-panel button:hover { background: var(--color-raised); }
/* Language and appearance (x-site.look-menu, the "Language and appearance" block's rules): a globe and the language's
   code, never wrapping, in the bar at every width from 320 px. On a phone its menu opens under the header, from the
   header's own edge. */
.s-top { position: relative; }

/* The hero and its mixer. */
.s-hero { padding-block: 4px 0; }
.s-hero h1 { font-size: clamp(26px, 8.2vw, 76px); line-height: 1.02; font-weight: 800; letter-spacing: -0.025em; margin-top: 8px; text-wrap: balance; }
.s-hero h1 em { font-style: normal; color: var(--color-part-ink-2); }
.s-hero .s-lead { font-size: 15.5px; line-height: 1.45; color: var(--color-muted); margin-top: 8px; max-width: 44ch; }
.s-mixer { margin-top: 14px; background: var(--color-panel); border: 1px solid var(--color-line); border-radius: 24px; padding: 8px; position: relative; }
/* Play sits on the voice circles' axis, and the title starts where the voice names do (Hillel). */
.s-mix-head { display: grid; grid-template-columns: auto minmax(0, 1fr); align-items: center; gap: 8px; padding-block: 4px 10px; padding-inline: 6px; }
.s-mix-head .s-t b { display: block; font-size: 15.5px; font-weight: 750; line-height: 1.25; }
.s-mix-head .s-t > span { display: block; font-size: 13px; color: var(--color-muted); font-variant-numeric: tabular-nums; margin-top: 2px; }
.s-play { @apply glass-bubble-solid; width: 48px; height: 48px; border-radius: 99px; display: grid; place-items: center; flex: none; cursor: pointer; }
.s-play:hover { transform: scale(1.04); }
.s-play svg { width: 24px; height: 24px; }
.s-play .s-i-stop, [data-playing] .s-play .s-i-play { display: none; }
[data-playing] .s-play .s-i-stop { display: block; }
.s-play[aria-busy="true"] { opacity: .7; }
/* A press answers at once (Hillel, 2026-11-02: "show instant feedback"): while the voices get ready, a ring
   turns round Play and the line under the title says so; once they sound, Play is Stop. */
.s-play { position: relative; }
.s-play::after { content: ''; position: absolute; inset: -6px; border-radius: inherit; border: 3px solid transparent; pointer-events: none; }
[data-loading] .s-play { opacity: 1; }
[data-loading] .s-play::after { border-color: color-mix(in oklab, var(--primary) 22%, transparent); border-top-color: var(--primary); animation: s-turn .8s linear infinite; }
/* Playing a whole song (Hillel: "let's always play the full songs"): a thin ring round Play fills with the song's
   progress (--p on the player, js/public/mixer.js), whatever the button's shape in either skin. A load that's slow
   shows a quiet hint under the button, and a failure says so in the same place, its ring the warning colour
   (js/public/play-state.js; Hillel: "make sure there is instant feedback if we need to load"). */
[data-playing] .s-play::after { border: 0; padding: 3px; background: conic-gradient(var(--primary) calc(var(--p, 0) * 1turn), color-mix(in oklab, var(--primary) 20%, transparent) 0); -webkit-mask: linear-gradient(#000 0 0) content-box exclude, linear-gradient(#000 0 0); mask: linear-gradient(#000 0 0) content-box exclude, linear-gradient(#000 0 0); -webkit-mask-composite: xor; }
[data-failed] .s-play::after { border-color: var(--color-warn, #c2410c); }
.s-play-hint { position: absolute; top: calc(100% + 8px); inset-inline-end: 0; z-index: 3; padding: 4px 10px; border-radius: 999px; background: var(--color-panel); box-shadow: 0 2px 10px rgb(0 0 0 / .18); color: var(--color-muted); font-size: 12px; font-weight: 600; line-height: 1.3; white-space: nowrap; pointer-events: none; }
.s-play-hint:empty { display: none; }
[data-failed] .s-play-hint { color: var(--color-cream); }
.s-mix-head .s-play-hint, [data-ui="part-play"] .s-play-hint { inset-inline-end: auto; inset-inline-start: 0; }
/* A song card's part rows follow the song: the part singing now is lit. */
.s-xpart { transition: background-color .15s; }
[data-playing] .s-xpart[data-sounding] { background: color-mix(in srgb, var(--color-cream) 7%, transparent); }
@media (prefers-reduced-motion: reduce) { .s-xpart { transition: none; } }
.s-mix-head .s-t > .s-mix-loading { color: var(--color-cream); font-weight: 650; }
[data-loading] .s-mix-head .s-t > .s-mix-meta { display: none; }
@keyframes s-turn { to { transform: rotate(1turn); } }
@keyframes s-breathe { 0% { box-shadow: 0 0 0 0 color-mix(in oklab, var(--primary) 45%, transparent); } 70%, 100% { box-shadow: 0 0 0 14px color-mix(in oklab, var(--primary) 0%, transparent); } }
@media (prefers-reduced-motion: reduce) {
    [data-loading] .s-play::after { animation: none; border-color: var(--primary); border-style: dashed; }
}
/* Play and the tune's two buttons do something only with the script: hidden until it's ready. */
[data-player]:has(> [data-song]):not([data-ready]) :is([data-play], [data-set], [data-hear-parts]) { visibility: hidden; }
.s-channels { display: grid; gap: 6px; }
/* The mixer's Hear row (a singer: "on a phone, it was hard to figure out how to change to listen to one part or another"):
   a line saying what it does, then All parts and each part as chips, 44 px tall, wrapping whole chips at 320 px, the one
   you hear ringed. */
/* The chip row's box (its own name: the landing's Hear four voices button is .s-hear). */
.s-hear-parts { display: grid; gap: 8px; margin-top: 12px; }
.s-hear-k { font-size: 13.5px; font-weight: 600; color: var(--color-muted); }
.s-hear-row { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; }
.s-hear-l { font-size: 14px; font-weight: 800; margin-inline-end: 2px; }
.s-hear-chip { display: inline-flex; align-items: center; gap: 7px; min-height: 44px; padding-inline: 14px; border-radius: 999px; background: var(--color-raised); font-size: 14.5px; font-weight: 700; white-space: nowrap; color: var(--color-cream); transition: box-shadow .15s, background .15s; }
.s-hear-chip i { width: 8px; height: 8px; border-radius: 50%; background: var(--c); }
.s-hear-chip:hover { box-shadow: inset 0 0 0 1px var(--color-line); }
.s-hear-chip[aria-pressed="true"] { background: var(--color-panel); box-shadow: inset 0 0 0 2px var(--color-cream); }
@media (max-width: 380px) { .s-hear-chip { padding-inline: 11px; font-size: 14px; } }
.s-ch { position: relative; display: grid; grid-template-columns: 40px minmax(0, 1fr) 30px; grid-template-areas: "disc name state" "disc wave wave"; column-gap: 12px; row-gap: 4px; align-items: center; text-align: start; padding-block: 9px; padding-inline: 10px 12px; border-radius: 18px; background: var(--color-raised); overflow: hidden; transition: background .2s; min-height: 62px; width: 100%; cursor: pointer; }
.s-ch:disabled { cursor: default; }
.s-ch::before { content: ''; position: absolute; inset: 0; background: radial-gradient(circle 46px at 30px 50%, color-mix(in srgb, var(--c) 18%, transparent), transparent); pointer-events: none; transition: opacity .2s; }
.s-ch > * { position: relative; }
.s-ch .s-disc { grid-area: disc; }
.s-ch-name { grid-area: name; display: flex; align-items: baseline; gap: 8px; min-width: 0; white-space: nowrap; }
.s-ch-name b { font-size: 15.5px; font-weight: 800; }
.s-ch-name small { font-size: 12.5px; color: var(--color-muted); overflow: hidden; text-overflow: ellipsis; }
.s-you { font-size: 11px; font-weight: 800; letter-spacing: .04em; text-transform: uppercase; background: var(--c); color: var(--ct); border-radius: 99px; padding: 2px 8px; }
.s-ch-wave { grid-area: wave; height: 22px; position: relative; }
.s-ch-wave::after { content: ''; position: absolute; top: -4px; bottom: -4px; left: calc(var(--p, 0) * 100%); width: 2px; background: var(--color-cream); border-radius: 2px; opacity: 0; }
[data-playing] .s-ch-wave::after { opacity: 1; }
/* Each voice's on or off: the forms system's switch (switch-track, switch-knob) in a 52 x 44 button, lit
   in its part's colour. */
.s-ch-state { grid-area: state; justify-self: end; display: grid; place-items: center; width: 52px; height: 44px; margin: -13px -4px; --selected: var(--c); --selected-ink: var(--ct); }
/* The mixer's glass takes its part's colour, and steps aside for .gem-dim while the voice is off. */
.s-ch .gem:not(.gem-dim) { --gem: var(--c); --gem-ink: var(--ct); }
.s-ch[data-off] { background: transparent; box-shadow: inset 0 0 0 1px var(--color-line); }
.s-ch[data-off]::before { opacity: 0; }
.s-ch[data-off] .s-disc:not(.gem) { background: transparent; color: var(--ci); box-shadow: inset 0 0 0 2.5px var(--c); }
.s-ch[data-off] .s-ch-wave { opacity: .22; filter: grayscale(1); }
.s-ch[data-off] .s-ch-name b { color: var(--color-muted); }
[data-playing] .s-ch:not([data-off]) .s-disc:not(.gem) { box-shadow: 0 0 0 5px color-mix(in srgb, var(--c) 28%, transparent), 0 0 24px color-mix(in srgb, var(--c) 60%, transparent); }
.s-ch.s-is-you { box-shadow: inset 0 0 0 2px var(--c); }
/* The hero's rows outside the Studio (a singer, then the fresh-eyes check, 2026-11-13: one control): the row itself plays
   its part alone ([data-solo] while it does), and a small My part at its end makes it yours. */
.s-mixer:not(.s-mixer-studio) .s-ch { grid-template-columns: 40px minmax(0, 1fr) auto; grid-template-areas: "disc name state" "disc wave state"; }
/* A small play mark before the name says the row plays its part. */
.s-ch-play { display: inline-grid; place-items: center; flex: none; width: 18px; height: 18px; border-radius: 50%; background: var(--c); color: var(--ct); align-self: center; }
.s-ch-play svg { margin-inline-start: 1px; }
/* The mark sits inside the name, so a layout that stacks the name's lines (a wide card) keeps them together. */
.s-mixer:not(.s-mixer-studio) .s-ch-name b { display: inline-flex; align-items: center; gap: 8px; }
/* The My part pill says it, so the name's You badge stays for the Studio. */
.s-mixer:not(.s-mixer-studio) .s-you { display: none; }
/* Your row keeps its line (the badge it made room for is gone), and a line wraps rather than cutting off. */
.s-mixer:not(.s-mixer-studio) .s-ch.s-is-you .s-ch-name small { display: inline; }
.s-mixer:not(.s-mixer-studio) .s-ch-name { flex-wrap: wrap; row-gap: 2px; white-space: normal; }
.s-mixer:not(.s-mixer-studio) .s-ch-name small { flex-basis: 100%; overflow: visible; }
.s-ch-mine { grid-area: state; justify-self: end; align-self: center; z-index: 2; display: inline-flex; align-items: center; min-height: 44px; padding-inline: 12px; border-radius: 999px; font-size: 12.5px; font-weight: 800; white-space: nowrap; color: var(--color-muted); box-shadow: inset 0 0 0 1.5px var(--color-line); }
.s-ch-mine:hover { color: var(--color-cream); }
.s-ch-mine[aria-checked="true"] { color: var(--color-cream); box-shadow: inset 0 0 0 2px var(--c); }
.s-ch-mine[aria-checked="true"] .s-mine-off, .s-ch-mine:not([aria-checked="true"]) .s-mine-on { display: none; }
.s-ch[data-solo] { background: color-mix(in srgb, var(--c) 16%, var(--color-raised)); box-shadow: inset 0 0 0 2px var(--c); }
.s-mix-lead { margin-bottom: 8px; font-size: 13.5px; font-weight: 600; color: var(--color-muted); }
/* A collection's hero keeps its tone's dark ground in a light theme too, where a part's ink (--ci) is dark: there My part
   takes the row's own ink (both skins). */
.s-xcoll-try .s-ch-mine[aria-checked="true"] { color: inherit; }
/* The row is a radio (bring this voice forward) under its switch (on or off): the radio covers the
   row, the switch sits above it with a 44 px tap area. "You" follows the voice brought forward. */
.s-ch > .s-ch-pick { position: absolute; inset: 0; z-index: 1; border-radius: inherit; cursor: pointer; }
.s-ch > .s-ch-state { z-index: 2; cursor: pointer; }
.s-ch:not(.s-is-you) .s-you, .s-ch.s-is-you .s-ch-name small { display: none; }
/* Each voice's own notes as bars, in its colour. While it plays: the notes still to come quiet,
   the sung ones half lit, the one sounding fully lit. */
.s-roll { display: block; width: 100%; height: 100%; overflow: visible; }
.s-roll .b { fill: var(--c); stroke: color-mix(in oklab, var(--c) 55%, black); stroke-width: 1; vector-effect: non-scaling-stroke; }
.s-roll g { transition: opacity .15s; }
[data-playing] .s-roll g { opacity: .3; }
[data-playing] .s-roll g[data-sung] { opacity: .7; }
[data-playing] .s-roll g[data-lit] { opacity: 1; }
.s-mix-words { padding: 10px 8px 8px; }
.s-lyrics { font-size: 16.5px; line-height: 1.4; font-weight: 650; color: var(--color-cream); }
.s-lyrics span { transition: color .15s; }
/* Each sung line its own block (Landing::lines), so a new line never runs on as "calling From glen". */
.s-lyrics [data-line] { display: block; text-wrap: balance; }
.s-lyrics [data-line] + [data-line] { margin-top: .3em; }
[data-playing] .s-lyrics span { color: var(--color-muted); }
[data-playing] .s-lyrics span[data-sung], [data-playing] .s-lyrics span[data-lit] { color: var(--color-cream); }
[data-playing] .s-lyrics span[data-lit] { text-decoration: underline; text-decoration-thickness: 3px; text-underline-offset: 5px; text-decoration-color: var(--color-part-2); }

/* Sections. */
.s-sec { padding-top: 64px; }
.s-h2 { font-size: clamp(28px, 7.4vw, 48px); line-height: 1.06; font-weight: 800; letter-spacing: -0.02em; text-wrap: balance; max-width: 20ch; }
.s-sub { font-size: 17px; line-height: 1.5; color: var(--color-muted); margin-top: 10px; max-width: 52ch; }
.s-steps { display: grid; gap: 14px; margin-top: 26px; }
.s-step { background: var(--color-panel); border: 1px solid var(--color-line); border-radius: 28px; padding: 20px; position: relative; overflow: hidden; }
.s-step::before { content: ''; position: absolute; inset: 0; background: radial-gradient(70% 60% at 100% 0%, color-mix(in srgb, var(--c) 10%, transparent), transparent 70%); pointer-events: none; }
.s-step > * { position: relative; }
.s-step-k { display: flex; align-items: center; gap: 10px; font-size: 13px; font-weight: 700; color: var(--color-muted); }
.s-step-k .s-disc { width: 36px; height: 36px; font-size: 16px; }
.s-step h3 { font-size: 23px; line-height: 1.15; font-weight: 800; letter-spacing: -0.015em; margin-top: 16px; }
.s-step p { font-size: 16px; line-height: 1.5; color: var(--color-muted); margin-top: 8px; }
.s-vis { margin-top: 18px; background: var(--color-ink); border-radius: 18px; padding: 14px; border: 1px solid var(--color-line); }
.s-vis-top { display: flex; justify-content: space-between; align-items: center; gap: 8px; font-size: 12.5px; color: var(--color-muted); margin-bottom: 8px; }
.s-vis-top b { color: var(--color-cream); font-size: 13.5px; }
.s-lane { width: 100%; height: 92px; display: block; }
.s-seg { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); background: var(--color-raised); border-radius: 99px; padding: 4px; font-size: 13px; font-weight: 700; text-align: center; color: var(--color-muted); }
.s-seg span { padding: 7px 4px; border-radius: 99px; }
.s-seg .s-on { @apply glass-bubble-solid; }
.s-recpill { display: inline-flex; align-items: center; gap: 6px; font-size: 12px; font-weight: 800; color: var(--color-record-label); background: var(--color-record); border-radius: 99px; padding: 3px 9px; }
/* The studio's compact tracks (117.png): the record-pick circle (a red gem when picked), the part's
   dot and name, small glass S and M on the mixer, and the waveform filling the lane. */
.s-trk { display: grid; grid-template-columns: 14px minmax(0, 76px) minmax(0, 1fr); gap: 8px; align-items: center; padding: 5px 0; }
.s-trk-mix { grid-template-columns: 14px minmax(0, 76px) auto minmax(0, 1fr); }
.s-trk-pick { width: 14px; height: 14px; border-radius: 99px; box-shadow: inset 0 0 0 1.5px var(--color-line); }
.s-trk-pick.gem { --gem: var(--color-record); --gem-glow: 0.7; border-width: 1px; }
.s-trk-name { display: flex; align-items: center; gap: 6px; min-width: 0; font-size: 12px; font-weight: 700; color: var(--color-cream); }
.s-trk-name::before { content: ""; flex: none; width: 8px; height: 8px; border-radius: 99px; background: var(--c); }
.s-trk-name span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.s-trk .s-wv { height: 22px; display: block; }
.s-trk-sm { display: flex; gap: 4px; }
.s-trk-sm span { display: grid; place-items: center; width: 18px; height: 18px; border-radius: 5px; font-size: 10px; font-weight: 800; color: var(--color-cream); background: color-mix(in srgb, var(--color-cream) 6%, var(--color-panel)); box-shadow: 0 0 0 1px var(--color-line); }
.s-share-btns { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 12px; }
.s-gv-wave { height: 44px; margin-top: 10px; }
.s-songs { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; margin-top: 24px; }
.s-song { display: flex; flex-direction: column; gap: 10px; padding: 14px; border-radius: 20px; background: var(--color-panel); border: 1px solid var(--color-line); min-height: 118px; height: 100%; }
.s-song:hover { border-color: var(--color-muted); }
.s-stackglyph { display: grid; gap: 3px; width: 44px; }
.s-stackglyph b { height: 6px; border-radius: 9px; background: var(--c); }
.s-song .s-t { display: block; font-size: 16px; font-weight: 750; line-height: 1.2; overflow-wrap: anywhere; }
.s-song .s-k { display: block; font-size: 13px; color: var(--color-muted); margin-top: 2px; }
.s-song .s-row { display: flex; justify-content: space-between; align-items: flex-start; gap: 6px; }
.s-badge { font-size: 12px; font-weight: 800; border-radius: 99px; padding: 3px 9px; }
.s-badge-free { background: var(--color-good); color: var(--color-ink); }
.s-more { margin-top: 18px; font-size: 15px; display: flex; flex-wrap: wrap; gap: 6px 18px; align-items: center; color: var(--color-muted); }
/* The site's segmented controls (tabs, Yearly or Monthly, the currency): the forms system's track and
   chosen segment (its tokens: --fill-2, --selected, --lift, --r-control, --r-seg, --ring). */
.s-seg2 { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 4px; padding: 4px; background: var(--fill-2); border-radius: var(--r-control); }
.s-seg2 button { display: inline-flex; align-items: center; justify-content: center; gap: 8px; min-height: 44px; border-radius: var(--r-seg); font-weight: 700; font-size: 14.5px; color: var(--color-muted); cursor: pointer; }
.s-seg2 [aria-pressed="true"] { background: var(--selected); color: var(--selected-ink); box-shadow: var(--lift); }

/* Plans. */
.s-plans { display: grid; gap: 14px; margin-top: 24px; }
.s-plan { border-radius: var(--k-r-feature); padding: 24px; background: var(--color-panel); border: 1px solid var(--color-line); position: relative; overflow: hidden; }
.s-plan-plus, .s-table-plans {
    /* Hillel's plans design: a warm fill and a solid edge, no corner glow. Ink is 4.5:1 or more on the fill. */
    --warm-fill: color-mix(in srgb, #d79a4e 10%, var(--color-panel)); --warm-edge: color-mix(in srgb, #d79a4e 60%, var(--color-panel)); --warm-ink: #e8b479;
}
.s-plan-plus { background: var(--warm-fill); border: 1.5px solid var(--warm-edge); }
:root[data-theme$="-light"] :is(.s-plan-plus, .s-table-plans) { --warm-fill: #f6ebdd; --warm-edge: #c9955b; --warm-ink: #82520f; }
.s-plan.s-plan-plus li svg { color: var(--warm-ink); }
.s-plan-plus .s-plan-k { border-top-color: color-mix(in srgb, var(--warm-edge) 45%, transparent); }
.s-plan > * { position: relative; }
.s-plan h3 { font-size: 20px; font-weight: 800; }
.s-price { font-size: 44px; font-weight: 800; letter-spacing: -0.02em; margin-top: 10px; line-height: 1; }
.s-price small { font-size: 16px; font-weight: 600; color: var(--color-muted); letter-spacing: 0; }
.s-plan .s-note { font-size: 14px; color: var(--color-muted); margin-top: 6px; }
.s-plan ul { margin-top: 18px; display: grid; gap: 10px; font-size: 15.5px; }
.s-plan li { display: flex; gap: 10px; align-items: flex-start; line-height: 1.35; }
.s-plan li svg { flex: none; color: var(--color-good); margin-top: 1px; }
.s-plan .btn-primary, .s-plan .btn-secondary { margin-top: 22px; width: 100%; }
.s-cur { font-size: 13.5px; color: var(--color-muted); margin-top: 14px; line-height: 1.6; }
.s-stories { display: grid; gap: 14px; margin-top: 24px; }
.s-story { border-radius: 24px; padding: 22px; background: var(--color-panel); border: 1px solid var(--color-line); }
.s-story blockquote { font-size: 18px; line-height: 1.45; }
.s-story figcaption { margin-top: 10px; font-size: 14px; color: var(--color-muted); }

/* Questions. */
.s-faq { margin-top: 20px; border-top: 1px solid var(--color-line); }
.s-faq details { border-bottom: 1px solid var(--color-line); }
.s-faq summary { list-style: none; display: flex; justify-content: space-between; gap: 12px; align-items: center; cursor: pointer; font-size: 17px; font-weight: 700; min-height: 60px; padding: 14px 2px; }
.s-faq summary::-webkit-details-marker { display: none; }
.s-faq summary svg { transition: transform .2s; flex: none; }
.s-faq details[open] summary svg { transform: rotate(180deg); }
.s-faq details p { color: var(--color-muted); font-size: 16px; line-height: 1.55; margin: -4px 2px 0; padding-bottom: 18px; max-width: 60ch; }

/* The mudeo letter: a signed note, only for mudeo's singers. */
.s-letter { border-radius: 28px; padding: 24px 22px; background: var(--color-panel); border: 1px solid var(--color-line); }
.s-letter .s-k { display: flex; align-items: center; gap: 10px; font-size: 12.5px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--color-muted); }
.s-letter h2 { font-size: clamp(26px, 6.6vw, 40px); font-weight: 800; letter-spacing: -0.02em; line-height: 1.08; margin-top: 12px; }
.s-letter p { font-size: 16.5px; line-height: 1.6; margin-top: 12px; max-width: 58ch; }
.s-letter .s-sig { font-size: 22px; font-weight: 300; letter-spacing: -0.01em; margin-top: 18px; }

.s-final { margin-top: 64px; text-align: center; padding: 44px 20px; border-radius: 32px; background: var(--color-panel); border: 1px solid var(--color-line); }
.s-final .s-stackbig { display: grid; gap: 8px; width: 140px; margin: 0 auto 22px; }
.s-final .s-stackbig b { height: 14px; border-radius: 9px; background: var(--c); }
.s-final h2 { font-size: clamp(28px, 7vw, 44px); font-weight: 800; letter-spacing: -0.02em; line-height: 1.08; text-wrap: balance; }
.s-final p { color: var(--color-muted); margin-top: 10px; font-size: 16px; }
.s-final .btn-primary { margin-top: 22px; }

.s-footer { margin-top: 56px; padding-bottom: 32px; font-size: 15px; color: var(--color-muted); }
.s-foot-grid { display: grid; gap: 32px; padding-top: 40px; border-top: 1px solid var(--color-line); }
.s-foot-brand p { margin-top: 8px; color: var(--color-cream); font-weight: 600; }
.s-social { display: flex; gap: 8px; margin-top: 16px; }
.s-social:empty { display: none; }
.s-foot-cols { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 28px 16px; }
.s-foot-h { font-size: 13px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--color-cream); margin-bottom: 4px; }
.s-foot-legal { margin-top: 36px; padding-top: 20px; border-top: 1px solid var(--color-line); font-size: 13px; }
.s-flink { display: inline-flex; align-items: center; min-height: 44px; font-weight: 500; color: var(--color-muted); }

/* With Language and appearance in the bar it needs about 410 px (430 with a language's code): on a narrower phone the
   mark stands for the name, as below 360. */
@media (max-width: 419.98px) {
    .s-top:has(> .s-look) .s-brand .s-word { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }
}
@media (max-width: 459px) {
    .s-top:has(> .s-look--lang) .s-brand .s-word { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }
}

/* From 360 to 389 px the name, Open the app and the menu all fit, but only just: the button a little narrower keeps the
   name clear of it (the fresh-eyes check, 2026-11-13: "Open the app nearly touches the logo"). */
@media (min-width: 360px) and (max-width: 389px) {
    .s-top > .btn-primary { padding-inline: 16px; }
}

@media (max-width: 359px) {
    .s-brand .s-word { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }
    /* The mark, Language and appearance, Open the app and the menu at 320 in either language: a little closer. */
    .s-top { gap: 6px; }
    .s-top > .btn-primary { padding-inline: 14px; }
    .s-top .s-look--lang > .s-look-btn { padding-inline: 9px; gap: 4px; }
}

@media (min-width: 900px) {
    .s-wrap { padding-inline: 40px; }
    .s-top { height: calc(80px + env(safe-area-inset-top)); gap: 12px; }
    .s-nav { display: flex; margin-inline-end: 8px; }
    .s-top > .s-menu { display: none; }
    .s-hero { padding-block: 36px 0; text-align: center; }
    .s-hero .s-eyebrow { justify-content: center; font-size: 13px; }
    .s-hero h1 { margin-top: 12px; }
    .s-hero .s-lead { margin: 16px auto 0; font-size: 20px; max-width: 46ch; }
    .s-mixer { margin-top: 36px; padding: 18px; border-radius: 36px; text-align: start; }
    .s-mix-head { grid-template-columns: auto minmax(0, 1fr) auto; gap: 20px; padding-block: 2px 16px; padding-inline: 16px 4px; }
    .s-mix-head .s-t b { font-size: 19px; }
    .s-mix-head .s-t > span { font-size: 14px; }
    .s-play { width: 64px; height: 64px; }
    .s-play svg { width: 28px; height: 28px; }
    .s-channels { gap: 10px; }
    .s-ch { grid-template-columns: 64px 150px minmax(0, 1fr) 40px; column-gap: 20px; padding-block: 14px; padding-inline: 16px 20px; }
    .s-ch { grid-template-areas: "disc name wave state"; min-height: 92px; border-radius: 24px; }
    .s-ch .s-disc { width: 64px; height: 64px; font-size: 26px; }
    .s-ch::before { background: radial-gradient(circle 64px at 48px 50%, color-mix(in srgb, var(--c) 18%, transparent), transparent); }
    .s-ch-name { flex-direction: column; gap: 3px; align-items: flex-start; }
    .s-ch-name b { font-size: 21px; }
    .s-ch-name small { font-size: 14px; }
    .s-ch-wave { height: 52px; }
    .s-ch-state { margin: -8px 0; }
    .s-mix-words { padding: 16px 20px 14px; text-align: center; }
    .s-lyrics { font-size: 20px; }
    .s-sec { padding-top: 112px; }
    .s-sub { font-size: 19px; }
    .s-steps { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 20px; margin-top: 40px; }
    .s-step { padding: 32px; border-radius: 32px; }
    .s-step h3 { font-size: 30px; }
    .s-step p { font-size: 17px; }
    .s-songs { grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 14px; margin-top: 36px; }
    .s-song { min-height: 150px; padding: 18px; }
    .s-two { display: grid; grid-template-columns: 4fr 7fr; gap: 56px; align-items: start; }
    .s-plans { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 20px; margin-top: 36px; }
    .s-plan { padding: 34px; }
    .s-stories { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 20px; }
    .s-faq { margin-top: 0; }
    .s-letter { padding: 44px 48px; display: grid; grid-template-columns: 4fr 7fr; gap: 0 56px; }
    .s-letter h2 { margin-top: 14px; }
    .s-letter div + div > p:first-child { margin-top: 0; }
    .s-final { margin-top: 112px; padding: 72px 40px; }
    .s-foot-grid { grid-template-columns: 2fr 5fr; gap: 48px; }
}
/* Another language's nav is longer (Spanish: Canciones, Cursos, Herramientas, Precios) and its language button joins the
   row, so at 900 the row ran 33 px into the margin: there the phone header holds until 960. */
@media (min-width: 900px) and (max-width: 959.98px) {
    :root:not(:lang(en)) .s-nav { display: none; }
    :root:not(:lang(en)) .s-top > .s-menu { display: block; }
}

/* Reduced motion: nothing glides, glows or travels along the line; the words and notes still
   light up, as a change of colour. */
@media (prefers-reduced-motion: reduce) {
    .s-ch-wave::after { display: none !important; }
    [data-playing] [aria-pressed="true"] .s-disc { box-shadow: none !important; }
    .s-play:hover { transform: none !important; }
    .s-ch, .s-disc, .s-lyrics span, .s-roll g, .s-faq summary svg { transition: none !important; }
}
/* The feature and "for" pages (views/site): the hero as the landing's, smaller; sections as cards;
   a grid of feature cards, each with its quiet label while it's coming. */
.s-page h1 { font-size: clamp(30px, 7vw, 60px); }
.s-sections { display: grid; gap: 14px; margin-top: 8px; }
.s-sections .s-step h2 { font-size: 23px; line-height: 1.15; font-weight: 800; letter-spacing: -0.015em; }
.s-points { margin-top: 14px; display: grid; gap: 8px; font-size: 15.5px; }
.s-points li { display: flex; gap: 10px; align-items: flex-start; line-height: 1.4; }
.s-points svg { flex: none; color: var(--color-good); margin-top: 1px; }
.s-cards { display: grid; gap: 12px; margin-top: 24px; }
.s-card { display: flex; flex-direction: column; gap: 6px; padding: 18px; border-radius: 22px; background: var(--color-panel); border: 1px solid var(--color-line); min-height: 44px; height: 100%; }
.s-card:hover { border-color: var(--color-muted); }
.s-card b { font-size: 17px; font-weight: 750; }
.s-card span:not(.s-soon) { font-size: 15px; line-height: 1.45; color: var(--color-muted); }
@media (min-width: 640px) {
    .s-foot-cols { grid-template-columns: repeat(3, minmax(0, 1fr)); }
    .s-cards { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (min-width: 900px) {
    .s-sections { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 20px; }
    .s-sections .s-step:last-child:nth-child(odd) { grid-column: 1 / -1; }
    .s-sections .s-step h2 { font-size: 28px; }
    .s-cards { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 16px; margin-top: 36px; }
}
/* About, press and what's new. */
.s-facts { margin-top: 14px; display: grid; gap: 10px; }
.s-facts div { display: grid; gap: 2px; }
.s-facts dt { font-size: 13px; font-weight: 700; color: var(--color-muted); }
.s-facts dd { font-size: 16px; }
/* Guides and legal pages: the words at a reading width, in the site's type. */
.s-doc { max-width: 760px; }
.s-doc-head { max-width: 760px; }
.s-prose { font-size: 17px; line-height: 1.65; }
.s-prose h2 { font-size: 24px; line-height: 1.2; font-weight: 800; letter-spacing: -0.015em; margin-top: 36px; }
.s-prose h3 { font-size: 19px; line-height: 1.3; font-weight: 750; margin-top: 26px; }
.s-prose p { margin-top: 14px; color: var(--color-cream); }
.s-prose ul { margin-top: 12px; display: grid; gap: 8px; padding-inline-start: 22px; list-style: disc; }
.s-prose li::marker { color: var(--color-muted); }
.s-prose strong { font-weight: 750; }
.s-prose > :first-child { margin-top: 0; }
.s-try { margin-top: 40px; }
.s-try h2 { font-size: 26px; font-weight: 800; margin-top: 10px; }
@media (min-width: 900px) {
    .s-doc, .s-doc-head { margin-inline: auto; }
    .s-doc-head { text-align: start; }
    .s-doc-head .s-eyebrow { justify-content: flex-start; }
    .s-doc-head .s-lead { margin-inline: 0; }
}
/* Pricing: the plans as the landing's, and the comparison as a quiet table. */
.s-plan-h { font-size: 20px; font-weight: 800; }
.s-table { width: 100%; min-width: 30rem; border-collapse: collapse; font-size: 15px; text-align: start; }
.s-table th, .s-table td { padding: 12px 16px 12px 0; text-align: start; border-bottom: 1px solid var(--color-line); vertical-align: top; }
.s-table thead th { font-size: 13px; font-weight: 700; color: var(--color-muted); }
.s-table tbody th { font-weight: 600; }
.s-table td { color: var(--color-muted); }
.s-small { margin-top: 16px; display: grid; gap: 6px; font-size: 14px; color: var(--color-muted); }
/* A song's page: its kind, the clip, the parts with their ranges and the verse. */
.s-song-kind { margin-top: 10px; font-size: 14px; font-weight: 650; color: var(--color-muted); }
.s-listen { margin-bottom: 32px; }
