.s-parts .s-disc { width: 32px; height: 32px; font-size: 14px; }
.s-parts span:not(.s-disc) { color: var(--color-muted); font-size: 15px; }
.s-verse { font-size: 19px; line-height: 1.6; font-weight: 600; }
/* Coaches: a picture or an initial, beside the name. */
.s-avatar { width: 48px; height: 48px; border-radius: 999px; object-fit: cover; flex: none; }
.s-coach-hero .s-avatar { width: 80px; height: 80px; }
.s-coach-hero .s-avatar-initial { font-size: 32px; }
.s-avatar-initial { display: grid; place-items: center; font-weight: 800; font-size: 20px; background: var(--c); color: var(--ct); }
.s-coach-top { display: flex; align-items: center; gap: 12px; }
.s-coach-top > span:not(.s-badge, .s-avatar, .s-faces) { display: grid; gap: 2px; flex: 1; min-width: 0; }
.s-coach-hero { margin-top: 12px; gap: 16px; }
.s-coach-hero h1 { margin-top: 0; }
.s-step .s-price { color: var(--color-cream); }
.s-try .btn-primary { white-space: normal; text-align: center; max-width: 100%; }
/* A page's hero buttons: a long label (Vocal coaches' "Write to us to be among the first") wraps on a small phone instead of pushing the page sideways. */
.s-actions :is(.btn-primary, .btn-secondary) { white-space: normal; text-align: center; max-width: 100%; }
/* A short page with one thing to say: errors, the gate, unsubscribing. */
