.s-notice-actions > .btn-primary, .s-notice-actions > .btn-secondary { justify-self: start; }
.s-notice-row { display: flex; flex-wrap: wrap; gap: 12px; }
.s-notice-row .btn-secondary { white-space: normal; text-align: center; }
@media (min-width: 900px) {
    .s-notice { padding-block: 96px 0; max-width: 760px; text-align: start; }
    .s-notice .s-eyebrow { justify-content: flex-start; }
    .s-notice .s-lead { margin-inline: 0; }
}
/* A shared harmony (/h/<id>): who sang it, the player (js/public/harmony.js draws its waveform),
   the way into the app and the credits. */
.s-sung { margin-top: 14px; }
.s-faces { display: flex; flex: none; }
.s-faces .s-avatar { width: 36px; height: 36px; font-size: 15px; margin-inline-end: -8px; box-shadow: 0 0 0 2px var(--color-ink); }
.s-sung > span:last-child { margin-inline-start: 8px; }
.s-sung b { font-size: 17px; }
.s-share-player { padding: 16px; }
.s-share-row { display: flex; align-items: center; gap: 14px; }
.s-share-wave { height: 64px; flex: 1; min-width: 0; border-radius: 8px; cursor: pointer; }
.s-share-time { margin-top: 8px; text-align: end; font-size: 12px; color: var(--color-muted); font-variant-numeric: tabular-nums; }
.s-share-audio { width: 100%; }
.s-share-credits { margin-top: 24px; display: grid; gap: 6px; font-size: 13px; color: var(--color-muted); }
.s-share-credits .s-report { justify-self: start; font-size: 13px; cursor: pointer; }
/* A shared idea and a virtual choir: each part with its range and voices, and who sang. */
.s-idea-parts { margin-top: 16px; display: grid; gap: 12px; }
.s-idea-parts li { flex-wrap: wrap; }
.s-credits { margin-top: 16px; display: grid; gap: 12px; }
.s-credits li { display: flex; align-items: center; gap: 12px; }
.s-credits li > span:last-child { display: grid; gap: 2px; }
.s-credits li > span:last-child > span { font-size: 13px; color: var(--color-muted); }
.s-credits .s-avatar { width: 32px; height: 32px; font-size: 14px; }
/* The gallery: harmony cards with their share card, and the New and Featured tabs. */
.s-harmony-card { padding: 12px; }
.s-harmony-image { width: 100%; height: auto; aspect-ratio: 1200 / 630; border-radius: 14px; object-fit: cover; background: var(--color-raised); }
.s-harmony-card .s-row { display: flex; justify-content: space-between; align-items: flex-start; gap: 8px; margin-top: 6px; }
.s-tabs { max-width: 320px; }
.s-tabs a { display: inline-flex; align-items: center; justify-content: center; min-height: 44px; border-radius: var(--r-seg); font-weight: 700; font-size: 14.5px; color: var(--color-muted); }
.s-tabs a[aria-current="page"] { background: var(--selected); color: var(--selected-ink); box-shadow: var(--lift); }
.s-tabs a:not([aria-current]):hover { color: var(--color-cream); background: var(--fill); }
.s-cur strong { background: var(--selected); color: var(--selected-ink); box-shadow: var(--lift); display: inline-flex; align-items: center; min-height: 44px; padding-inline: 14px; border-radius: var(--r-seg); font-size: 14px; }
.s-more .btn-secondary, .s-points .btn-secondary { white-space: normal; text-align: center; }

/* The user guide (/help, docs/user-guide-plan.md): on a phone the head, then search and the folded
   contents, then "On this page", then the page; from 1100 px the contents on the left and "On this
   page" on the right, both sticky. Screenshots show the light or the dark one for the theme. */
.s-guide { display: grid; gap: 16px; grid-template-columns: minmax(0, 1fr); grid-template-areas: "head" "rail" "toc" "body"; padding-top: 8px; }
.s-guide-head { grid-area: head; }
.s-guide-head h1 { font-size: clamp(30px, 7vw, 48px); line-height: 1.05; font-weight: 800; letter-spacing: -0.025em; margin-top: 8px; text-wrap: balance; }
.s-guide-head .s-lead { font-size: 19px; line-height: 1.5; color: color-mix(in srgb, var(--color-cream) 85%, var(--color-ink)); margin-top: 12px; margin-bottom: 16px; max-width: 60ch; }
.s-guide-rail { grid-area: rail; display: grid; gap: 10px; align-content: start; }
.s-guide-toc { grid-area: toc; }
.s-guide-body { grid-area: body; min-width: 0; max-width: 720px; }
.s-guide-fold { border: 1px solid var(--color-line); border-radius: 16px; background: var(--color-panel); }
.s-guide-fold > summary { display: flex; align-items: center; justify-content: space-between; min-height: 48px; padding-inline: 16px; font-weight: 700; cursor: pointer; list-style: none; }
.s-guide-fold > summary::-webkit-details-marker { display: none; }
.s-guide-fold[open] > summary svg { transform: rotate(180deg); }
.s-guide-fold > nav, .s-guide-fold > .s-guide-nav { padding: 0 8px 10px; }
.s-guide-group { font-size: 12px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--color-muted); padding: 14px 8px 4px; }
.s-guide-fold ul { display: grid; }
.s-guide-fold li a { display: flex; align-items: center; min-height: 40px; padding: 6px 8px; border-radius: 10px; font-size: 15px; color: var(--color-muted); line-height: 1.3; text-decoration: underline 2px transparent; text-underline-offset: 5px; }
.s-guide-fold li a:hover, .s-guide-fold li a:focus-visible { color: var(--color-cream); text-decoration-color: var(--color-accent); }
.s-guide-fold li a[aria-current="page"] { color: var(--color-cream); font-weight: 700; background: var(--color-raised); }
.s-guide-body .s-prose h2 { scroll-margin-top: 16px; }
.s-guide-body .s-prose ol { margin-top: 12px; display: grid; gap: 10px; padding-inline-start: 26px; list-style: decimal; }
.s-guide-body .s-prose ol li::marker { color: var(--color-muted); font-weight: 700; }
.s-tip { display: flex; gap: 12px; align-items: flex-start; margin-top: 16px; padding: 14px 16px; border-radius: 16px; background: var(--color-raised); font-size: 15.5px; line-height: 1.5; }
.s-tip svg { flex: none; margin-top: 2px; color: var(--color-accent-strong); }
/* Where an answer goes next (HelpGuide's links): a page of the guide, or the app's screen that fixes it. */
.s-see { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 14px; }
.s-shot { margin-top: 18px; }
.s-shot-frame { display: block; border-radius: 16px; overflow: hidden; border: 1px solid var(--color-line); background: var(--color-panel); }
.s-shot-frame img { display: block; width: 100%; height: auto; }
.s-shot-tall .s-shot-frame { max-width: 300px; border-radius: 24px; }
.s-shot-dark { display: none; }
:root[data-theme$="-dark"] .s-shot-light { display: none; }
:root[data-theme$="-dark"] .s-shot-dark { display: block; }
/* Before a theme is set (scripts off), the page wears the default dark, so the dark shot shows. */
:root:not([data-theme]) .s-shot-light { display: none; }
:root:not([data-theme]) .s-shot-dark { display: block; }
/* The serious skin's own screenshots (<id>-serious, when the guide has them): the calm look's pair in
   place of the game's, in the visitor's light or dark. Without them, the game's pair shows as before. */
.s-shot-serious, .s-shot-serious-dark { display: none; }
:root:not([data-skin="game"]) :is(.s-appshot, .s-shot):has(.s-shot-serious) :is(.s-shot-light, .s-shot-dark) { display: none; }
:root:not([data-skin="game"]):not([data-theme$="-dark"]) .s-shot-serious { display: block; }
:root:not([data-skin="game"])[data-theme$="-dark"] .s-shot-serious-dark { display: block; }
.s-pager { display: grid; gap: 12px; margin-top: 32px; }
.s-pager .s-card span { font-size: 13px; font-weight: 700; color: var(--color-muted); }
.s-pager-next { text-align: end; }
/* The search: a field with its icon, and its results in a panel under it. */
.s-hsearch { position: relative; }
.s-hsearch > svg { position: absolute; inset-inline-start: 14px; top: 13px; color: var(--color-muted); pointer-events: none; }
.s-hsearch input.input { min-height: 48px; padding-inline: 42px 14px; }
.s-hsearch-results { position: absolute; inset-inline: 0; top: calc(100% + 6px); z-index: 30; max-height: min(420px, 70vh); overflow-y: auto; padding: 6px; border-radius: 16px; background: var(--color-panel); border: 1px solid var(--color-line); box-shadow: 0 20px 50px color-mix(in srgb, var(--color-cream) 14%, transparent); }
.s-hsearch-results a { display: grid; gap: 2px; padding: 10px 12px; border-radius: 10px; min-height: 44px; }
.s-hsearch-results a b { font-weight: 700; color: var(--color-cream); }
.s-hsearch-results a span { font-size: 13.5px; color: var(--color-muted); overflow: hidden; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; }
.s-hsearch-results a:hover, .s-hsearch-results a[aria-selected="true"] { background: var(--color-raised); }
.s-hsearch-none { padding: 12px; font-size: 14.5px; color: var(--color-muted); }
.s-hsearch-hero input.input { min-height: 56px; font-size: 17px; }
.s-hsearch-hero > svg { top: 17px; }
/* The guide's front: the search, "Start here" as three numbered cards, then the groups. */
.s-help-find { margin-top: 24px; max-width: 640px; }
@media (min-width: 640px) {
    .s-pager { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); }
    .s-pager-next:only-child { grid-column: 2; }
}
@media (min-width: 900px) {
    .s-help-find { margin-inline: auto; }
}
@media (min-width: 1100px) {
    .s-guide { grid-template-columns: 240px minmax(0, 1fr) 200px; grid-template-areas: "rail head toc" "rail body toc"; grid-template-rows: auto 1fr; gap: 24px 48px; padding-top: 24px; }
    .s-guide-rail, .s-guide-toc { position: sticky; top: 16px; align-self: start; max-height: calc(100vh - 32px); overflow-y: auto; }
    .s-guide-fold { border: 0; background: none; border-radius: 0; }
    .s-guide-fold > summary { min-height: 0; padding: 0 8px 6px; font-size: 12px; letter-spacing: .1em; text-transform: uppercase; color: var(--color-muted); pointer-events: none; }
    .s-guide-fold > summary svg { display: none; }
    .s-guide-rail .s-guide-fold > summary { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); }
    .s-guide-fold > nav, .s-guide-fold > .s-guide-nav { padding: 0; }
    .s-guide-toc { grid-row: 1 / span 2; }
    .s-guide-rail { grid-row: 1 / span 2; }
}

/* The inner pages' shared parts (the design round's direction A): a left-aligned top with where you
   are, a picture or player beside it on a wide screen; sections with a heading beside their body; a
   panel band for rhythm; a range chart; and the page's own last word. */
.s-head { padding-top: 8px; }
.s-head-grid { display: grid; gap: 28px; align-items: start; }
.s-head h1 { font-size: clamp(32px, 8vw, 60px); line-height: 1.03; font-weight: 800; letter-spacing: -0.025em; margin-top: 8px; text-wrap: balance; max-width: 18ch; }
.s-head .s-lead { font-size: 17px; line-height: 1.5; color: var(--color-muted); margin-top: 12px; max-width: 48ch; }
.s-crumb { display: flex; flex-wrap: wrap; align-items: center; gap: 2px 8px; font-size: 14px; color: var(--color-muted); }
.s-crumb a { display: inline-flex; align-items: center; min-height: 44px; font-weight: 600; color: var(--color-muted); text-decoration: underline 2px transparent; text-underline-offset: 6px; }
.s-crumb a:hover, .s-crumb a:focus-visible { color: var(--color-cream); text-decoration-color: var(--color-accent); }
.s-crumb span[aria-hidden] { opacity: .6; }
/* In the tools' bar, the trail takes the room the name had. */
.s-tbrand-crumb { flex: 1 1 auto; }
.s-meta { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 16px; }
.s-meta span { display: inline-flex; align-items: center; min-height: 30px; padding: 4px 12px; border-radius: 99px; background: var(--color-raised); font-size: 13.5px; font-weight: 650; }
.s-meta .s-badge-free { background: var(--color-good); color: var(--color-ink); }
.s-actions { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 22px; align-items: center; }
.s-actions p { font-size: 13.5px; color: var(--color-muted); flex-basis: 100%; }
.s-sec2 { padding-top: 64px; }
.s-two2 { display: grid; gap: 20px; }
.s-band { background: var(--color-panel); border-block: 1px solid var(--color-line); padding-block: 56px; margin-top: 64px; }
.s-song-credits { display: grid; gap: 4px; margin-top: 10px; font-size: 14.5px; color: var(--color-muted); }
.s-verse-big { font-size: clamp(22px, 5.6vw, 32px); line-height: 1.35; font-weight: 700; letter-spacing: -0.01em; text-wrap: balance; }
.s-verse-big span { display: block; }
.s-verse-big span:nth-child(n + 3) { color: var(--color-muted); }
/* A song's page (public/song.blade.php; Hillel's Danny Boy design, "Responsive wrapping fixes"): the hero in the palette
   of the page that collects it (s-tone-<key>, its own when none does), "Find your part" cards, every verse a sung line a
   line with a hanging indent, then its story (public/_song-story) in a reading column with its contents beside it. */
.s-tone-song { --tb: #211B17; --ta: #F0B36A; --tm: #D3C7B8; --tl: #2E2620; --primary: #F0B36A; --primary-ink: #211B17; }
.s-tone-song { --dot: #9A9085; }
.s-sg-hero h1 { font-size: clamp(46px, 9vw, 96px); }
.s-sg-chips { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 18px; }
.s-sg-chips li { padding: 5px 12px; border-radius: 999px; font-size: 13.5px; font-weight: 650; line-height: 1.3; box-shadow: inset 0 0 0 1px rgba(247, 241, 230, .3); }
.s-sg-chips .s-sg-chip-free { background: var(--ta); color: var(--tb); box-shadow: none; }
.s-sg-hero .s-actions { display: flex; flex-wrap: wrap; align-items: center; gap: 12px; }
.s-sg-hero .s-actions .btn-lg { white-space: nowrap; }
.s-sg-note { margin-top: 12px; font-size: 14px; color: var(--color-muted); }
/* A song page's player (option C of the song page review): compact rows, as the landing's hero has them: the disc, the
   part's name over its tag and range ("Melody · B3 to E5"), its notes beside them from a tablet up (under them on a
   phone), and I sing this at the end. */
.s-sg-try .s-mixer:not(.s-mixer-studio) .s-ch { grid-template-columns: 40px minmax(0, 1fr) auto; grid-template-areas: "disc name state" "disc wave state"; column-gap: 12px; row-gap: 4px; min-height: 64px; padding-block: 10px; padding-inline: 12px 12px; border-radius: 18px; }
/* Every collection's player too (game's check, 2026-11-13): the 40px disc column the non-studio rows set, never the
   wide screen's 64px coin overrunning it into the tag. */
.s-xcoll-try .s-ch .s-disc, .s-sg-try .s-ch .s-disc { width: 40px; height: 40px; font-size: 16px; }
.s-sg-try .s-ch::before { background: radial-gradient(circle 46px at 32px 50%, color-mix(in srgb, var(--c) 14%, transparent), transparent); }
.s-sg-try .s-mixer:not(.s-mixer-studio) .s-ch-name { flex-direction: column; align-items: flex-start; gap: 2px; }
.s-sg-try .s-ch-name b { font-size: 16px; }
.s-sg-try .s-ch-name small { font-size: 12.5px; }
/* A row's range never breaks inside itself or leaves its dot behind ("· G3 to C4" is one piece, in either skin). */
.s-ch-range { white-space: nowrap; }
.s-sg-try .s-ch-wave { height: 26px; }
@media (min-width: 600px) {
    .s-sg-try .s-mixer:not(.s-mixer-studio) .s-ch { grid-template-columns: 40px minmax(0, 1.15fr) minmax(0, .85fr) auto; grid-template-areas: "disc name wave state"; column-gap: 14px; }
    .s-sg-try .s-ch-name small { white-space: nowrap; }
    .s-sg-try .s-ch-wave { height: 34px; }
}
/* Less empty ground under the hero (about 150 px on a desktop, the song page review): the words, or the parts, start sooner. */
.s-sg-hero + .s-sg-words { margin-top: 24px; padding-top: 44px; }
.s-sg-hero + .s-sg-parts { padding-top: 40px; }
.s-sg-try .s-mix-foot .s-sg-actions { margin-top: 0; }
/* The hero's text sits level with the player beside it. */
@media (min-width: 900px) { .s-sg-hero .s-xhero-in.s-xcoll-has-try { align-items: center; } }
/* A song page's actions in its player's foot (public/_song-actions): part of the panel under a rule, never a box of its
   own; Learn takes the room and Share sits beside it, wrapping under it where both don't fit (a narrow phone). */
.s-sg-try, .s-sg-try .s-mixer { min-width: 0; }
.s-sg-try .s-mixer .s-mix-foot { margin: 8px 4px 0; padding: 16px 4px 6px; background: none; border-radius: 0; }
.s-sg-try .s-sg-actions { margin-top: 0; gap: 10px; }
.s-sg-try .s-sg-actions > .btn-primary { flex: 1 1 auto; justify-content: center; }
.s-sg-try .s-sg-note { margin-top: 10px; font-size: 13.5px; }
/* A song page's hero with its score (public/_song-score.blade.php, js/public/score.js; Hillel's design, 2026-11-16):
   at left the part you sing and Learn; at right one card, the player's bar over the score on its sheet. The sheet is
   paper: white with dark ink in a light theme, a dark sheet with light ink in a dark one. */
@media (min-width: 900px) { .s-sg-hero .s-xhero-in.s-xcoll-has-try.s-sg-scored { align-items: start; } }
.s-sg-pick { margin-top: 26px; }
.s-sg-pick-h { font-size: 13px; font-weight: 650; letter-spacing: .06em; text-transform: uppercase; opacity: .82; }
.s-sg-seg { display: grid; grid-auto-flow: column; grid-auto-columns: minmax(max-content, 1fr); gap: 4px; margin-top: 10px; padding: 4px; max-width: 460px; overflow-x: auto; border-radius: 16px; background: var(--tl); }
.s-sg-seg button { min-height: 48px; padding: 0 10px; border: 0; border-radius: 12px; background: none; color: inherit; font: inherit; font-size: 15px; font-weight: 650; white-space: nowrap; cursor: pointer; }
.s-sg-seg button[aria-checked="true"] { background: #faf5ee; color: #1f1a14; box-shadow: 0 1px 2px rgb(0 0 0 / .25); }
.s-sg-seg button:focus-visible { outline: 2px solid var(--ta); outline-offset: 2px; }
/* A song's versions (Hillel, 2026-11-18, "One song, US/UK switch"; SongVersions): one small row of links on the song page and
   its part pages, "Version · US UK", the one shown chosen (the accent, with aria-current), the tune it sings under it.
   Calm and small: the page's own choices (the parts) stay the main ones. */
.s-ver { display: flex; flex-wrap: wrap; align-items: center; gap: 6px 12px; margin-top: 18px; }
.s-ver-h { font-size: 13px; font-weight: 650; letter-spacing: .06em; text-transform: uppercase; opacity: .82; }
.s-ver-seg { display: inline-flex; gap: 2px; padding: 3px; border-radius: 999px; background: var(--tl, var(--color-panel)); }
.s-ver-seg a { display: inline-grid; place-items: center; min-height: 40px; min-width: 52px; padding: 0 16px; border-radius: 999px; color: inherit; font-size: 14px; font-weight: 650; white-space: nowrap; text-decoration: none; }
.s-ver-seg a:hover { text-decoration: underline; text-underline-offset: 3px; }
.s-ver-seg a[aria-current] { background: var(--color-accent); color: var(--color-accent-ink); box-shadow: 0 1px 2px rgb(0 0 0 / .25); text-decoration: none; }
.s-ver-seg a:focus-visible { outline: 2px solid var(--ta, var(--color-accent)); outline-offset: 2px; }
.s-ver-note { flex-basis: 100%; margin: 0; font-size: 13px; line-height: 1.45; opacity: .86; }
.s-spart-side .s-ver { margin-top: 0; }
.s-sg-scored .s-sg-actions { margin-top: 12px; max-width: 460px; }
.s-sg-scored .s-sg-actions > .btn-primary { flex: 1 1 240px; justify-content: center; }
.s-sg-scored .s-sg-note { margin-top: 12px; font-size: 14px; }
.s-score { display: flex; flex-direction: column; gap: 14px; min-width: 0; padding: 18px; border-radius: 24px; background: var(--tl); color: #faf5ee; box-shadow: 0 24px 48px -28px rgb(0 0 0 / .45); }
.s-score-head { display: flex; align-items: center; gap: 14px; }
.s-score .s-play { width: 52px; height: 52px; }
.s-score-now { flex: 1; min-width: 0; display: grid; gap: 8px; }
.s-score-now p { display: flex; justify-content: space-between; gap: 8px; font-size: 14px; }
.s-score-now b { font-weight: 650; }
.s-score-time { opacity: .82; font-variant-numeric: tabular-nums; white-space: nowrap; }
.s-score-bar { display: block; height: 4px; overflow: hidden; border-radius: 2px; background: rgb(250 245 238 / .16); }
.s-score-bar i { display: block; width: calc(var(--p, 0) * 100%); height: 100%; background: var(--ta); }
.s-score-sheet, .s-score-paper { --paper: #fff; --ink: #1f1a14; background: var(--paper); color: var(--ink); }
:root[data-theme$="-dark"] .s-score-sheet, :root[data-theme$="-dark"] .s-score-paper { --paper: #17120f; --ink: #f4eee6; }
.s-score-sheet { padding: 12px 12px 8px; border-radius: 14px; }
/* The sheet keeps its room before the notes are drawn: a system's height on a phone (the rest grows below the fold), the
   card's one system on a wide screen, by the number of staves. */
.s-score-view { position: relative; min-height: calc(var(--staves) * 84px + 20px); }
.s-score-systems { position: relative; z-index: 1; pointer-events: none; }
.s-score-systems svg { display: block; width: 100%; height: auto; }
.s-score-systems svg[hidden] { display: none; }
@media (min-width: 900px) {
    .s-score-view { min-height: 0; aspect-ratio: 560 / calc(var(--staves) * 108 + 44); }
    .s-score-systems { position: absolute; inset: 0; }
    .s-score-systems svg { height: 100%; }
    /* A round's one staff, two systems at once, one over the other. */
    .s-score-view[data-round] { aspect-ratio: 560 / 330; }
    .s-score-view[data-round] .s-score-systems svg { height: 50%; }
}
/* Each staff's row: its letter (hear this part alone) at its left, the row tinted when the part is yours. */
.s-score-voice { position: absolute; inset-inline: 0; top: calc((var(--i) + .14) / var(--staves) * 100%); height: calc(.6 / var(--staves) * 100%); border-radius: 10px; pointer-events: none; }
.s-score-voice.s-is-you { background: color-mix(in srgb, var(--ta) 26%, var(--paper)); }
.s-score-voice button { position: absolute; inset-inline-start: var(--at, 4px); top: 50%; translate: 0 calc(-50% + var(--dy, 0px)); z-index: 2; width: 28px; height: 28px; border: 0; border-radius: 50%; font-size: 13px; font-weight: 750; cursor: pointer; pointer-events: auto; --bubble: #f1ebe2; --bubble-ink: #1f1a14; background-color: var(--bubble); } /* its own ground under the gloss, so its letter is dark on light on a dark sheet too */
.s-score-voice button::after { content: ''; position: absolute; inset: -8px; }
.s-score-voice.s-is-you button { --bubble: var(--ta); }
.s-score-voice[data-solo] button { outline: 2px solid var(--ink); outline-offset: 2px; }
.s-score-voice button:focus-visible { outline: 2px solid var(--ink); outline-offset: 3px; }
.s-score-view:not([data-engraved]) .s-score-voice::before { content: ''; position: absolute; inset-inline: 46px 8px; top: 50%; height: 33px; translate: 0 -50%; background: repeating-linear-gradient(to bottom, color-mix(in srgb, var(--ink) 50%, transparent) 0 1px, transparent 1px 8px); }
/* A staff goes quiet while another part is heard alone; a note and its word light in the part's colour, and thicken, as
   they sound. */
.s-score [data-staff][data-quiet], .s-score-paper [data-staff][data-quiet] { opacity: .3; }
/* A lit note in its part's colour, taken toward the sheet's ink so it reads on white paper and on dark alike. */
.s-score [data-lit], .s-score-paper [data-lit] { --lit: color-mix(in srgb, var(--c) 55%, var(--ink)); fill: var(--lit); stroke: var(--lit); stroke-width: .7; }
/* A round's one staff: each note lit in the colour of the voice singing it (the first named, where two meet). */
:is(.s-score, .s-score-paper) [data-echo][data-lit^="alto"] { --c: var(--color-part-2); }
:is(.s-score, .s-score-paper) [data-echo][data-lit^="tenor"] { --c: var(--color-part-3); }
