.s-score-files { display: flex; flex-wrap: wrap; gap: 0 14px; font-weight: 650; }
.s-score-files a { display: inline-flex; align-items: center; min-height: 44px; color: #faf5ee; text-decoration: underline; text-underline-offset: 3px; }
/* The whole score, opened under the hero: a printed page's look. */
.s-score-full { padding-top: 40px; }
.s-score-full-head { display: flex; align-items: center; justify-content: space-between; gap: 16px; margin-bottom: 16px; }
.s-score-full-head h2 { font-size: clamp(20px, 3vw, 26px); font-weight: 800; letter-spacing: -0.01em; }
