.s-score-title { text-align: center; font-size: 34px; line-height: 1.1; }
.s-score-kind { margin-top: 6px; text-align: center; font-size: 13px; letter-spacing: .14em; text-transform: uppercase; }
.s-score-credits { display: flex; align-items: flex-end; justify-content: space-between; gap: 16px; margin: 18px 0 6px; font-size: 14px; line-height: 1.45; }
.s-score-credits span:last-child { text-align: end; }
.s-score-paper svg { display: block; width: 100%; height: auto; margin-top: 10px; }
.s-score-rights { margin-top: 22px; text-align: center; font-size: 12px; opacity: .8; overflow-wrap: anywhere; }
/* Check my range keeps one line: the sentence wraps before it, never inside it. */
.s-sg-note .s-lk { white-space: nowrap; }
.s-sg-parts { scroll-margin-top: 16px; }
.s-sg-head { display: grid; gap: 4px; }
/* Its key and tempo, one quiet line under the lead (SongPage::keyTempo). */
.s-sg-keyline { font-size: 14px; font-weight: 600; color: var(--color-muted); }
@media (min-width: 900px) { .s-sg-head .s-sg-keyline { grid-column: 2; } }
@media (min-width: 900px) { .s-sg-head { grid-template-columns: minmax(0, 1fr) minmax(0, 26em); align-items: end; gap: 32px; } }
/* How each part goes (the song page review, option C): one panel, a ruled row a part; its facts (disc, name, tag, range,
   the range bar on the page's one scale, its guide voice) at left on a wide screen, where it goes in the words and its
   part page at right, about 75 characters a line. Nothing to pick: the hero's player picks. */
.s-sg-how { margin-top: 28px; border-radius: 20px; background: var(--color-panel); border: 1px solid var(--color-line); }
.s-sg-how-row { display: grid; gap: 14px; padding: 22px 20px; scroll-margin-top: 16px; }
.s-sg-how-row + .s-sg-how-row { border-top: 1px solid var(--color-line); }
@media (min-width: 900px) { .s-sg-how-row { grid-template-columns: 300px minmax(0, 1fr); gap: 40px; padding: 26px 28px; } }
.s-sg-how-facts { display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: center; gap: 0 12px; align-self: start; }
.s-sg-how-facts .s-disc { grid-column: 1; grid-row: 1 / span 2; width: 34px; height: 34px; font-size: 15px; }
.s-sg-how-facts h3 { grid-column: 2; grid-row: 1; font-size: 19px; line-height: 1.2; font-weight: 800; }
.s-sg-how-facts .s-sg-tag { grid-column: 2; grid-row: 2; }
.s-sg-how-facts .s-sg-range { grid-column: 3; grid-row: 1; color: var(--color-cream); }
.s-sg-how-facts .s-sg-bar, .s-sg-how-facts .s-sg-voice { grid-column: 1 / -1; }
.s-sg-how-facts .s-sg-bar { margin-block: 12px 0; }
.s-sg-how-facts .s-sg-voice { margin-top: 0; padding-top: 8px; font-size: 13.5px; }
.s-sg-how-text { display: grid; justify-items: start; gap: 6px; }
.s-sg-how-text .s-sg-part-note { max-width: 46em; font-size: 16px; line-height: 1.55; color: var(--color-cream); }
.s-sg-practise { display: inline-flex; align-items: center; gap: 6px; min-height: 44px; font-size: 15px; font-weight: 700; }
.s-sg-tag { font-size: 12px; font-weight: 750; letter-spacing: .04em; color: var(--ci); }
.s-sg-range { font-size: 14px; font-weight: 600; color: var(--color-muted); }
.s-sg-bar { position: relative; display: block; height: 8px; margin-block: 6px 4px; border-radius: 99px; background: var(--color-raised); }
.s-sg-bar i { position: absolute; inset-block: 0; left: var(--lo); width: calc(var(--hi) - var(--lo)); min-width: 10px; border-radius: 99px; background: var(--c); }
.s-sg-part-note { font-size: 15px; line-height: 1.5; color: var(--color-muted); }
.s-sg-voice { display: flex; flex-wrap: wrap; align-items: baseline; gap: 4px 10px; margin-top: auto; padding-top: 10px; font-size: 14px; color: var(--color-muted); }
.s-sg-voice b { font-weight: 750; color: var(--color-cream); }
.s-sg-voice .s-lk, .s-sg-voices-note .s-lk { position: relative; z-index: 2; }
.s-spart-be { margin-top: 16px; font-size: 14.5px; line-height: 1.55; color: var(--color-muted); }
.s-spart-be > .s-lk:first-child { display: inline-block; } /* its tap padding cancelled top and bottom, so the first line keeps the paragraph's spacing (Hillel, 2026-11-18) */
.s-sg-voices-note { margin-top: 18px; max-width: 60em; font-size: 14.5px; line-height: 1.55; color: var(--color-muted); }
.s-sg-words-in { display: grid; gap: 24px; }
@media (min-width: 900px) { .s-sg-words-in { grid-template-columns: minmax(0, 1fr) minmax(0, 2fr); gap: 48px; } }
.s-sg-lyrics { display: grid; gap: 26px; font-size: clamp(20px, 4.6vw, 28px); line-height: 1.38; font-weight: 650; letter-spacing: -0.005em; }
/* One sung line a line: a long one wraps under itself, indented, so it never reads as the next line (every width); its
   script above it (Hebrew right to left, its own line) and its meaning under it, smaller and muted, each wrapping so. */
.s-sg-line, .s-sg-line > span { display: block; }
.s-sg-line > span { padding-inline-start: 1.1em; text-indent: -1.1em; }
.s-sg-line + .s-sg-line { margin-top: 8px; }
.s-sg-script { font-size: .92em; }
.s-sg-meaning { margin-top: 2px; font-size: 16px; line-height: 1.45; font-weight: 500; letter-spacing: 0; color: var(--color-muted); }
