.s-sg-meaning-toggle { margin-bottom: 18px; white-space: nowrap; }
.s-sg-label { display: block; margin-bottom: 6px; font-size: 13px; line-height: 1.3; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--color-muted); }
.s-sg-words-intro { margin-bottom: 22px; font-size: 16px; }
/* A long song's further stanzas, folded under Show all verses (a details element); once open, the button goes. */
.s-sg-more > summary { width: fit-content; list-style: none; cursor: pointer; white-space: nowrap; font-size: 16px; letter-spacing: 0; }
.s-sg-more > summary::-webkit-details-marker { display: none; }
.s-sg-more[open] > summary { display: none; }
.s-sg-next { display: grid; gap: 12px; margin-top: 24px; }
@media (min-width: 900px) { .s-sg-next { grid-template-columns: repeat(3, minmax(0, 1fr)); } }
.s-sg-next a { display: grid; gap: 6px; height: 100%; padding: 18px 20px; border-radius: 18px; background: var(--color-panel); border: 1px solid var(--color-line); transition: border-color .15s; }
.s-sg-next a:hover { border-color: var(--color-cream); }
.s-sg-next b { font-size: 18px; font-weight: 800; }
.s-sg-next span { font-size: 15px; line-height: 1.5; color: var(--color-muted); }
.s-sst-grid { display: grid; gap: 28px; margin-top: 28px; }
@media (min-width: 1024px) { .s-sst-grid { grid-template-columns: 220px minmax(0, 46em); gap: 56px; } .s-sst-toc { position: sticky; top: 24px; align-self: start; } }
.s-sst-toc ol { display: grid; gap: 2px; margin-top: 10px; }
.s-sst-toc a { display: block; padding-block: 8px; font-size: 15px; font-weight: 600; color: var(--color-muted); text-decoration: none; }
.s-sst-toc a:hover { color: var(--color-cream); text-decoration: underline; text-underline-offset: 4px; }
@media (max-width: 1023px) { .s-sst-toc { padding: 16px 20px; border-radius: 18px; background: var(--color-panel); border: 1px solid var(--color-line); } .s-sst-toc a { padding-block: 6px; } }
.s-sst-main { min-width: 0; }
.s-sst .s-prose a { text-decoration: underline; text-underline-offset: 3px; }
.s-sst .s-cite a { color: var(--color-accent); text-decoration: none; padding-inline: 1px; }
.s-sst-quote { margin-top: 28px; padding: 22px 24px; border-radius: 20px; background: var(--color-panel); border: 1px solid var(--color-line); }
.s-sst-quote p { font-family: ui-serif, 'Iowan Old Style', 'Palatino Linotype', Palatino, Georgia, serif; font-style: italic; font-size: clamp(20px, 4.4vw, 24px); line-height: 1.4; }
.s-sst-quote p::before { content: "\201C"; } .s-sst-quote p::after { content: "\201D"; }
.s-sst-facts { margin-top: 28px; padding: 20px 22px; border-radius: 20px; background: var(--color-panel); border: 1px solid var(--color-line); }
.s-sst-facts dl { display: grid; gap: 12px; margin-top: 12px; }
.s-sst-facts dl > div { display: grid; gap: 2px; }
@media (min-width: 600px) { .s-sst-facts dl > div { grid-template-columns: 11em minmax(0, 1fr); gap: 16px; } }
.s-sst-facts dt { font-size: 14px; font-weight: 700; color: var(--color-muted); }
.s-sst-facts dd { font-size: 15.5px; line-height: 1.5; }
.s-sst-sec { margin-top: 48px; scroll-margin-top: 24px; }
.s-sst-sec > h3 { margin-bottom: 14px; font-size: clamp(22px, 5vw, 28px); line-height: 1.2; font-weight: 800; letter-spacing: -0.015em; }
.s-sst-tl-h { margin-top: 28px; }
.s-sst-tl { margin-top: 10px; border-top: 1px solid var(--color-line); }
.s-sst-tl li { display: grid; grid-template-columns: 5.5em minmax(0, 1fr); gap: 16px; padding-block: 14px; border-bottom: 1px solid var(--color-line); font-size: 16px; line-height: 1.55; }
.s-sst-tl b { font-size: 20px; line-height: 1.25; font-weight: 700; color: var(--color-part-ink-2); }
@media (max-width: 599px) { .s-sst-tl li { grid-template-columns: minmax(0, 1fr); gap: 2px; } }
.s-sst-dyk { display: grid; gap: 12px; }
.s-sst-dyk li { padding: 16px 18px; border-radius: 16px; background: var(--color-panel); border: 1px solid var(--color-line); font-size: 16px; line-height: 1.55; }
.s-sst-qs { display: grid; gap: 22px; }
.s-sst-q h4 { font-size: 18px; line-height: 1.35; font-weight: 750; margin-bottom: 6px; }
.s-sst-checked { font-size: 14.5px; color: var(--color-muted); }
.s-sst-src { display: grid; gap: 10px; margin-top: 14px; padding-inline-start: 1.6em; list-style: decimal; font-size: 14.5px; line-height: 1.55; color: var(--color-muted); }
.s-sst-src li { scroll-margin-top: 24px; overflow-wrap: anywhere; }
.s-sst-src li:target { color: var(--color-cream); }
.s-sst-listen { display: grid; gap: 8px; margin-top: 10px; }
.s-fig { margin-block: 24px; }
/* Never cropped: a printed page keeps its own shape (its width and height), at most most of a screen tall. */
.s-fig img { display: block; width: 100%; height: auto; max-height: 80vh; object-fit: contain; border-radius: 14px; background: var(--color-raised); }
.s-fig figcaption { display: grid; gap: 4px; margin-top: 10px; font-size: 14px; line-height: 1.5; color: var(--color-muted); }
.s-fig-cap { color: var(--color-cream); }
.s-more-songs { margin-top: 20px; }
.s-range { margin-top: 4px; }
.s-range-scale, .s-range-row { display: grid; grid-template-columns: 96px minmax(0, 1fr); gap: 12px; }
.s-range-scale { font-size: 11.5px; color: var(--color-muted); font-variant-numeric: tabular-nums; }
.s-range-scale > div { position: relative; height: 18px; }
.s-range-scale div span { position: absolute; transform: translateX(-50%); white-space: nowrap; }
.s-range-scale div span:first-child { transform: none; }
.s-range-scale div span:last-child { transform: translateX(-100%); }
.s-range-row { align-items: center; min-height: 44px; }
.s-range-nm { display: flex; align-items: center; gap: 8px; font-weight: 750; font-size: 15px; min-width: 0; }
.s-range-nm .s-disc { width: 28px; height: 28px; font-size: 12.5px; }
.s-range-track { position: relative; height: 30px; border-radius: 99px; background: var(--color-raised); }
.s-range-bar { position: absolute; top: 3px; bottom: 3px; border-radius: 99px; background: var(--c); color: var(--ct); font-size: 12px; font-weight: 800; display: flex; align-items: center; justify-content: space-between; gap: 6px; padding-inline: 8px; font-variant-numeric: tabular-nums; }
.s-range-bar span { white-space: nowrap; }
.s-end { margin-top: 64px; border-radius: 32px; background: var(--color-panel); border: 1px solid var(--color-line); padding: 28px 22px; display: grid; gap: 18px; position: relative; overflow: hidden; }
.s-end::before { content: ''; position: absolute; inset: 0; pointer-events: none; background: radial-gradient(40% 70% at 100% 100%, color-mix(in srgb, var(--color-part-1) 14%, transparent), transparent 70%), radial-gradient(30% 60% at 85% 100%, color-mix(in srgb, var(--color-part-3) 12%, transparent), transparent 70%); }
.s-end > * { position: relative; }
.s-end h2 { font-size: clamp(26px, 6vw, 38px); font-weight: 800; letter-spacing: -0.02em; line-height: 1.08; text-wrap: balance; }
.s-end p { color: var(--color-muted); margin-top: 8px; font-size: 16px; }
.s-end .btn-primary { justify-self: start; white-space: normal; text-align: center; }
.s-stackbig { display: grid; gap: 6px; width: 96px; }
.s-stackbig b { height: 10px; border-radius: 9px; background: var(--c); }
@media (min-width: 900px) {
    .s-head { padding-top: 40px; }
    .s-head-grid { grid-template-columns: 6fr 5fr; gap: 56px; }
    .s-head-solo { grid-template-columns: minmax(0, 1fr); }
    .s-sec2 { padding-top: 112px; }
    .s-two2 { grid-template-columns: 4fr 7fr; gap: 64px; align-items: start; }
    .s-band { padding-block: 96px; margin-top: 112px; }
    .s-range-scale, .s-range-row { grid-template-columns: 110px minmax(0, 1fr); }
    .s-more-songs { grid-template-columns: repeat(3, minmax(0, 1fr)); }
    .s-end { grid-template-columns: auto minmax(0, 1fr) auto; align-items: center; gap: 32px; padding: 44px 48px; margin-top: 112px; }
    /* A mixer in a narrow column (beside a page's top): the phone's row layout, a little larger. */
    .s-narrow .s-mixer { padding: 12px; border-radius: 28px; margin-top: 0; }
    .s-narrow .s-mix-head { grid-template-columns: auto minmax(0, 1fr); gap: 12px; padding-inline: 8px 4px; padding-block: 4px 12px; }
    .s-narrow .s-play { width: 52px; height: 52px; }
    .s-narrow .s-mix-head .s-t b { font-size: 16.5px; }
    .s-narrow .s-ch { grid-template-columns: 48px minmax(0, 1fr) 34px; grid-template-areas: "disc name state" "disc wave wave"; min-height: 76px; column-gap: 14px; padding-block: 10px; padding-inline: 12px 14px; border-radius: 20px; }
    .s-narrow .s-ch .s-disc { width: 48px; height: 48px; font-size: 20px; }
    .s-narrow .s-ch::before { background: radial-gradient(circle 50px at 36px 50%, color-mix(in srgb, var(--c) 18%, transparent), transparent); }
    .s-narrow .s-ch-name { flex-direction: row; align-items: baseline; gap: 8px; }
    .s-narrow .s-ch-name b { font-size: 16.5px; }
    .s-narrow .s-ch-name small { font-size: 13px; }
    .s-narrow .s-ch-wave { height: 30px; }
    .s-narrow .s-ch-state { margin: -12px -4px; }
    .s-narrow .s-mix-words { padding: 12px 8px 8px; text-align: start; }
    .s-narrow .s-lyrics { font-size: 17px; }
}

/* The feature drawings (components/site/pic): a dark well holding a drawing of the app from the
   site's own parts; a tile (a feature, its drawing, name and line); rows of words beside a
   drawing, alternating sides; "On the way" as compact chips; "Who it's for" as small tiles. */
.s-pic { border-radius: var(--k-r-card); background: var(--color-ink); border: 1px solid var(--color-line); padding: 18px; display: grid; align-content: center; gap: 8px; min-height: 170px; overflow: hidden; }
.s-pic .s-seg { font-size: 12.5px; }
.s-pic-icon { display: grid; place-items: center; height: 120px; color: var(--color-muted); }
.s-pic-icon svg { width: 56px; height: 56px; }
.s-pic-chips { display: flex; flex-wrap: wrap; gap: 6px; justify-content: center; }
.s-pic-chips span { display: inline-flex; align-items: center; gap: 6px; padding: 5px 10px; border-radius: 99px; background: var(--color-raised); font-size: 12.5px; font-weight: 700; color: var(--color-cream); }
.s-pic-chips .s-on { box-shadow: inset 0 0 0 1.5px var(--color-accent); background: color-mix(in srgb, var(--color-accent) 14%, transparent); }
.s-pic-roll { height: 44px; }
.s-pic-late { opacity: .35; transform: translateX(6%); }
.s-nodes { display: flex; align-items: center; justify-content: center; gap: 10px; }
.s-nodes i { width: 34px; height: 34px; border-radius: 99px; display: grid; place-items: center; box-shadow: inset 0 0 0 2.5px var(--c); color: var(--ci); }
.s-nodes i.s-done { background: var(--c); color: var(--ct); box-shadow: none; }
.s-nodes i.s-now { box-shadow: inset 0 0 0 2.5px var(--c), 0 0 0 5px color-mix(in srgb, var(--c) 22%, transparent); }
.s-nodes s { width: 18px; height: 2px; background: var(--color-line); }
.s-stars { display: flex; justify-content: center; gap: 4px; color: var(--color-part-ink-2); }
.s-pic-card { display: grid; grid-template-columns: 54px minmax(0, 1fr); gap: 10px; align-items: center; padding: 10px; border-radius: 14px; background: var(--color-panel); border: 1px solid var(--color-line); }
.s-pic-card .s-stackglyph { width: 54px; }
.s-pic-card small { display: block; font-size: 11.5px; color: var(--color-muted); }
.s-pic-card b { font-size: 13.5px; }
.s-pic-group { display: grid; grid-template-columns: 28px minmax(0, 1fr) auto; gap: 10px; align-items: center; padding: 6px 8px; border-radius: 14px; background: var(--color-raised); }
.s-pic-group .s-disc { width: 28px; height: 28px; font-size: 12px; }
.s-pic-group b { font-size: 13.5px; font-weight: 750; }
.s-pic-status { display: inline-flex; align-items: center; gap: 6px; font-size: 12px; font-weight: 700; padding: 3px 9px; border-radius: 99px; white-space: nowrap; color: var(--color-cream); }
/* The share page, the video, the Export sheet, Trim, progress, the workout, a part's guide voice,
   the creator's line and a group's song (components/site/pic): each its own screen, so no page
   repeats a picture. Glass for the pieces, calm for the cards. */
.s-pic-eyebrow { font-size: 10.5px; font-weight: 800; letter-spacing: .12em; text-transform: uppercase; color: var(--color-muted); }
.s-pic-title { display: block; margin: 2px 0 10px; font-size: 16px; font-weight: 800; line-height: 1.2; color: var(--color-cream); }
.s-pic-player { display: grid; grid-template-columns: 36px minmax(0, 1fr); gap: 10px; align-items: center; padding: 10px; border-radius: 14px; background: var(--color-panel); border: 1px solid var(--color-line); margin-bottom: 10px; }
.s-pic-play { @apply glass-bubble-solid; display: grid; place-items: center; width: 36px; height: 36px; border-radius: 99px; }
.s-pic-waves { display: grid; gap: 3px; }
.s-pic-waves .s-wv, .s-pic-vwaves .s-wv { display: block; height: 12px; }
.s-pic-video { display: grid; gap: 10px; width: min(150px, 60%); aspect-ratio: 9 / 16; margin: 0 auto; padding: 14px 12px; border-radius: 18px; background: var(--color-ink); border: 1px solid var(--color-line); align-content: space-between; text-align: center; }
