.s-pic-opt.s-on i { box-shadow: inset 0 0 0 4px var(--color-accent); }
.s-pic-opt b { display: block; font-size: 12.5px; color: var(--color-cream); }
.s-pic-opt small { display: block; font-size: 11px; color: var(--color-muted); }
.s-pic-opt em { font-style: normal; font-size: 10.5px; font-weight: 800; padding: 2px 8px; border-radius: 99px; background: color-mix(in srgb, var(--color-accent) 18%, transparent); color: var(--color-cream); }
.s-pic-opt + .s-pic-chips { margin-top: 8px; }
