.s-pic-note { display: flex; gap: 8px; align-items: flex-start; padding: 8px 10px; border-radius: 12px; background: var(--color-raised); font-size: 11.5px; line-height: 1.35; text-align: start; color: var(--color-cream); }
.s-pic-note svg { flex: none; margin-top: 1px; color: var(--color-accent); }
.s-pic-trim { position: relative; height: 56px; padding: 6px 0; border-radius: 12px; background: var(--color-panel); border: 1px solid var(--color-line); margin-bottom: 8px; overflow: hidden; }
.s-pic-trim .s-wv { display: block; height: 100%; }
.s-pic-trim i { position: absolute; inset-block: 0; width: 10%; background: repeating-linear-gradient(135deg, color-mix(in srgb, var(--color-cream) 18%, transparent) 0 3px, transparent 3px 7px); }
.s-pic-trim .s-cut-l { left: 0; border-right: 3px solid var(--color-cream); }
.s-pic-trim .s-cut-r { right: 0; border-left: 3px solid var(--color-cream); }
.s-pic-bar { height: 8px; border-radius: 99px; background: var(--color-raised); overflow: hidden; }
