.s-pic-rounds { display: flex; justify-content: center; gap: 8px; margin-bottom: 10px; }
.s-pic-rounds i { display: grid; place-items: center; width: 28px; height: 28px; border-radius: 99px; font-size: 12px; font-weight: 800; font-style: normal; color: var(--color-muted); box-shadow: inset 0 0 0 1.5px var(--color-line); }
.s-pic-rounds i.gem { --gem: var(--color-part-3); color: var(--color-part-text-3); box-shadow: none; }
.s-pic-rounds i.s-now { color: var(--color-cream); box-shadow: inset 0 0 0 2px var(--color-accent); }
.s-pic-line { font-size: 15px; font-weight: 800; color: var(--color-cream); margin-bottom: 8px; }
