.s-tile { display: flex; flex-direction: column; gap: 6px; height: 100%; padding: 18px; border-radius: 28px; background: var(--color-panel); border: 1px solid var(--color-line); }
.s-tile:hover { border-color: var(--color-muted); }
.s-tile .s-pic { margin-bottom: 12px; height: 150px; min-height: 0; padding: 14px; gap: 6px; }
.s-tile > b { font-size: 21px; font-weight: 800; letter-spacing: -0.01em; display: flex; align-items: center; justify-content: space-between; gap: 8px; }
.s-tile > b svg { color: var(--color-muted); flex: none; }
