.s-who-ic { width: 36px; height: 36px; border-radius: 99px; display: grid; place-items: center; background: color-mix(in srgb, var(--c, var(--color-muted)) 18%, transparent); color: var(--ci, var(--color-muted)); }
.s-who { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; margin-top: 24px; }
