}
@media (min-width: 900px) {
    .s-tiles { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 18px; margin-top: 36px; }
    .s-tile { padding: 22px; }
    .s-tile-wide { grid-column: span 2; }
    .s-head-grid > .s-pic { min-height: 320px; padding: 32px; }
    .s-who { grid-template-columns: repeat(4, minmax(0, 1fr)); }
}

/* The shared harmony (/h/<id>): centred, the player as the hero with a row per part, the two
