.s-share-head { display: flex; align-items: center; gap: 12px; margin-bottom: 12px; }
.s-share-head .s-t { display: grid; gap: 2px; }
.s-share-head .s-share-time { margin-top: 0; text-align: start; }
.s-share-parts { display: grid; gap: 0; align-content: stretch; }
.s-share-parts:not(.hidden) { display: grid; }
.s-share-parts .s-disc { width: 24px; height: 24px; font-size: 11px; margin-block: 3px; }
.s-harmony-btns { justify-content: center; margin-top: 20px; }
.s-how { grid-template-columns: minmax(0, 1fr); }
.s-how > li { display: grid; gap: 4px; align-content: start; padding: 16px; border-radius: 22px; background: var(--color-ink); border: 1px solid var(--color-line); }
.s-how .s-disc { width: 32px; height: 32px; font-size: 14px; margin-bottom: 6px; }
.s-how b { font-size: 16px; font-weight: 750; }
.s-how > li > span:not(.s-disc) { font-size: 14px; line-height: 1.4; color: var(--color-muted); }
.s-harmony-band { text-align: center; }
.s-harmony-band .s-h2 { margin-inline: auto; }
.s-harmony .s-sung { justify-content: center; }
