.s-harmony + .s-harmony-band + .s-share-credits { justify-items: center; text-align: center; }
.s-harmony + .s-harmony-band + .s-share-credits .s-report { justify-self: center; }
.s-harmony-band .s-sub { margin-inline: auto; }
.s-harmony-band .s-how { text-align: start; }
@media (min-width: 640px) {
    .s-how { grid-template-columns: repeat(3, minmax(0, 1fr)); }
}
@media (min-width: 900px) {
    .s-harmony .s-share-player { max-width: 640px; margin-inline: auto; margin-top: 28px; }
}

/* About: Hillel's note, one readable column on a panel, signed. */
.s-letter-note { max-width: 680px; border-radius: 28px; padding: 26px 22px; background: var(--color-panel); border: 1px solid var(--color-line); }
.s-letter-note p { font-size: 18px; line-height: 1.65; margin-top: 16px; }
.s-letter-note p:first-child { margin-top: 0; }
.s-letter-note .s-sig { font-size: 24px; font-weight: 300; letter-spacing: -0.01em; margin-top: 24px; }
@media (min-width: 900px) {
    .s-letter-note { padding: 48px 56px; }
    .s-letter-note p { font-size: 19px; }
}
.s-quiet { display: flex; gap: 12px; align-items: flex-start; margin-top: 40px; padding: 14px 16px; border-radius: 16px; background: var(--color-raised); font-size: 15px; line-height: 1.5; }
.s-quiet svg { flex: none; margin-top: 2px; color: var(--color-muted); }
/* The free tools (site/tools, site/tool; docs/tools-plan.md): the H1 and one line, the tool right under it (above
   the fold on a phone), how to use it, and one way into the app, or "Open the app" for a visitor who's signed in. */
/* The tool bar under the site header on the tools' pages: the page's name, the tool's key control and the theme menu. */
.s-tbrand { display: flex; align-items: center; gap: 10px; min-height: 48px; border-top: 1px solid var(--color-line); border-bottom: 1px solid var(--color-line); }
.s-tbrand-end { margin-inline-start: auto; display: flex; align-items: center; gap: 8px; }
@media (min-width: 900px) { .s-tbrand { min-height: 56px; } }
.s-tmenu { position: relative; }
.s-tmenu > button { width: 44px; height: 44px; }
.s-tmenu-panel { position: absolute; z-index: 30; inset-inline-end: 0; top: calc(100% + 8px); width: min(300px, calc(100vw - 32px)); display: grid; gap: 8px; padding: 12px; border-radius: 18px; background: var(--color-panel); border: 1px solid var(--color-line); box-shadow: var(--lift); }
.s-tmenu-panel[hidden] { display: none; }
.s-tmenu-h { font-size: 13px; font-weight: 700; color: var(--color-muted); margin-top: 4px; }
.s-tmenu-swatches { display: grid; grid-template-columns: 1fr 1fr; gap: 6px; }
.s-tmenu-sw { display: flex; align-items: center; gap: 8px; min-height: 44px; padding: 6px 8px; border-radius: 12px; font-size: 13.5px; font-weight: 650; text-align: start; }
.s-tmenu-sw[aria-pressed="true"] { box-shadow: inset 0 0 0 2px var(--color-cream); }
.s-tmenu-chip { flex: none; width: 26px; height: 26px; border-radius: 99px; border: 1px solid var(--color-line); background: radial-gradient(circle at 50% 50%, var(--sw-a) 0 28%, transparent 30%), linear-gradient(135deg, var(--sw-l) 0 50%, var(--sw-d) 50% 100%); }
.s-tbrand-tool { border-bottom: 0; }
.s-tbrand-key:empty { display: none; }
/* The page's name, quiet, on one line. */
.s-tbrand-name { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 14px; line-height: 18px; font-weight: 600; color: var(--color-muted); }
.s-tool-more h1 { font-size: 28px; line-height: 1.1; font-weight: 800; letter-spacing: -0.02em; margin-top: 4px; text-wrap: balance; }
@media (min-width: 900px) { .s-tool-more h1 { font-size: 40px; } }
/* The site header and the tool bar above the tool (60 + 48 on a phone, 80 + 56 wide), with the installed app's inset. */
.s-tool { --tool-top: calc(108px + env(safe-area-inset-top)); }
@media (min-width: 900px) { .s-tool { --tool-top: calc(136px + env(safe-area-inset-top)); } }
/* The tool's room, held until its script has mounted it (page.js marks it data-state="ready"): before, the guide below
   showed in the first screen and then jumped down, a layout shift of 0.9 on a slow phone and 0.4 on a desktop
   (docs/performance.md, 2026-11-03). On a phone the tool fills the screen under the header and tool bar; on a wider screen it's
   its card's height, measured for each tool (tests/flows/tool_room_integration.py checks them against the real tools). */
.s-tool:not([data-state]) { min-height: max(calc(100svh - var(--tool-top)), var(--tool-room-phone, 0px)); }
/* On a phone a tool taller than the screen under the header and tool bar holds its own height (--tool-room-phone):
   the instrument tuners, with their strings, mount at 806 px (tool_room_integration at 390 x 844). */
.s-tool:is([data-tool="ukulele-tuner"], [data-tool="violin-tuner"], [data-tool="guitar-tuner"], [data-tool="bass-tuner"], [data-tool="cello-tuner"], [data-tool="viola-tuner"], [data-tool="mandolin-tuner"], [data-tool="banjo-tuner"]) { --tool-room-phone: 806px; }
@media (min-width: 768px) {
    .s-tool:not([data-state]) { min-height: var(--tool-room, 600px); }
    .s-tool[data-tool="tuner"] { --tool-room: 782px; }
    .s-tool[data-tool="metronome"] { --tool-room: 652px; }
    .s-tool[data-tool="vocal-range-test"] { --tool-room: 526px; }
    .s-tool[data-tool="pitch-pipe"] { --tool-room: 754px; }
    .s-tool[data-tool="tuning-forks"] { --tool-room: 552px; }
    .s-tool[data-tool="drone"] { --tool-room: 724px; }
    .s-tool[data-tool="chord-transposer"] { --tool-room: 584px; }
    .s-tool[data-tool="four-part-harmony"] { --tool-room: 700px; }
    .s-tool[data-tool="pitch-matching"] { --tool-room: 776px; }
    .s-tool[data-tool="note-frequency-chart"] { --tool-room: 654px; }
    .s-tool[data-tool="tap-tempo"] { --tool-room: 554px; }
    .s-tool[data-tool="mic-test"] { --tool-room: 524px; }
    .s-tool[data-tool="vocal-key-finder"] { --tool-room: 688px; }
    .s-tool[data-tool="just-intonation-tuner"] { --tool-room: 684px; }
    /* The tool variants (SitePages::TOOL_VARIANTS) hold their tool's room. */
    .s-tool:is([data-tool="ukulele-tuner"], [data-tool="violin-tuner"], [data-tool="guitar-tuner"], [data-tool="bass-tuner"], [data-tool="cello-tuner"], [data-tool="viola-tuner"], [data-tool="mandolin-tuner"], [data-tool="banjo-tuner"]) { --tool-room: 874px; } /* Instrument mode, with the strings */
    .s-tool[data-tool="voice-tuner"] { --tool-room: 782px; }
    .s-tool[data-tool="tanpura"] { --tool-room: 724px; }
    .s-tool[data-tool="432-hz-tuning-fork"] { --tool-room: 498px; } /* three forks on the shelf */
    .s-tool[data-tool^="warmups-"] { --tool-room: 732px; } /* every warm-up's player (oo-scale's 712 is within the check's slack) */
}
.s-thead { display: flex; align-items: flex-end; justify-content: space-between; gap: 16px; padding-top: 18px; }
.s-teyebrow { font-size: 14px; font-weight: 600; color: var(--color-muted); }
.s-thead h1 { font-size: 28px; line-height: 1.1; font-weight: 800; letter-spacing: -0.02em; margin-top: 4px; text-wrap: balance; }
@media (min-width: 900px) { .s-thead h1 { font-size: 40px; } }
.s-thead-hub { display: block; }
.s-thead-hub .s-lede { margin-top: 10px; max-width: 56ch; }
.s-thead-hub + section { margin-top: 0; padding-top: 24px; }
.s-tool-lede { margin-top: 10px; max-width: 64ch; }
.s-tool-more .s-kick { margin-top: 28px; }
/* How to use a tool (or learn a part): numbered steps, each number in a small round chip (the design's mockup). */
.s-tool-how { counter-reset: how; display: grid; gap: 12px; margin-top: 14px; max-width: 62ch; }
.s-tool-how li { counter-increment: how; display: grid; grid-template-columns: 28px 1fr; gap: 12px; line-height: 1.55; color: var(--color-muted); }
.s-tool-how li::before { content: counter(how); display: grid; place-items: center; width: 28px; height: 28px; border-radius: 99px; background: var(--color-raised); color: var(--color-cream); font-size: 14px; font-weight: 750; }
:root[data-skin="game"] body.s-arcade .s-tool-how li::before { border-radius: 0; }
.s-tool-related { margin-top: 24px; }
/* The tools hub (Hillel's tools page, 2026-11-12): the search and the groups as chips, Most used with its drawings, then each
   group: its name and line at left, its tools at right from 900 px. Labels never wrap. */
.s-th-search { max-width: 420px; }
/* Hidden by the search or a chip (js/public/tools/hub.js): the sections' own display mustn't keep them showing. */
.s-th-grp[hidden], .s-th-most-wrap[hidden], .s-th-none[hidden], .s-th-list > li[hidden] { display: none; }
.s-th-chips { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 16px; }
.s-th-chips .s-sh-filter.is-on { border-color: var(--color-cream); background: var(--color-cream); color: var(--color-ink); }
.s-th-chips .s-sh-filter.is-on span { color: inherit; opacity: .7; }
.s-th-chips .s-sh-filter i { background: var(--c, var(--color-muted)); }
.s-th-label { font-size: 12.5px; font-weight: 750; letter-spacing: .12em; text-transform: uppercase; color: var(--color-muted); }
.s-th-most-wrap { padding-top: 36px; }
.s-th-most { display: grid; gap: 14px; margin-top: 14px; }
@media (min-width: 760px) { .s-th-most { grid-template-columns: repeat(3, minmax(0, 1fr)); } }
.s-th-big { display: flex; flex-direction: column; gap: 8px; height: 100%; padding: 16px; border: 1px solid var(--color-line); border-radius: 22px; background: var(--color-panel); }
.s-th-big:hover { border-color: var(--color-muted); }
.s-th-pic { display: grid; place-items: center; gap: 12px; min-height: 112px; margin-bottom: 6px; padding: 18px 14px; border-radius: 14px; background: color-mix(in srgb, var(--color-cream) 7%, var(--color-panel)); }
/* The reading and its word each stay whole, and the word drops under the reading when both don't fit (Spanish in the game
   skin's wider face at 768: "Sol3–Re5" and "Contralto"). */
.s-th-pic-read { display: inline-flex; flex-wrap: wrap; align-items: baseline; gap: 2px 6px; max-width: 100%; }
.s-th-pic-read > * { white-space: nowrap; }
.s-th-pic-read b { font-size: 32px; line-height: 1; font-weight: 800; letter-spacing: -.02em; color: var(--color-cream); }
.s-th-pic-read em { font-style: normal; font-size: 13px; font-weight: 650; color: var(--color-muted); }
.s-th-pic-read .s-th-good { color: var(--color-good); }
.s-th-pic-read .s-th-part { color: var(--color-part-4); }
.s-th-ticks { display: flex; align-items: center; gap: 9px; height: 24px; }
.s-th-ticks i { width: 1px; height: 14px; background: var(--color-muted); opacity: .7; }
.s-th-ticks i.is-on { width: 3px; height: 24px; border-radius: 2px; background: var(--color-good); opacity: 1; }
.s-th-beats { display: flex; gap: 10px; }
.s-th-beats i { width: 11px; height: 11px; border-radius: 50%; background: var(--color-line); }
.s-th-beats i.is-on { width: 15px; height: 15px; margin-block: -2px; background: var(--color-part-1); }
.s-th-keys { display: flex; border: 1px solid var(--color-line); border-radius: 3px; overflow: hidden; }
.s-th-keys i { width: 11px; height: 18px; border-inline-end: 1px solid var(--color-line); background: var(--color-cream); opacity: .9; }
.s-th-keys i:last-child { border-inline-end: 0; }
.s-th-keys i.is-on { background: var(--color-part-4); opacity: 1; }
/* Open drops under the name when both don't fit (the game skin's wider face at 768: "Vocal range test"), and a name longer
   than its card (Spanish there) wraps between words: a card's heading, not a label. */
.s-th-big-head { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 4px 10px; }
.s-th-big-head b { min-width: 0; font-size: 18px; font-weight: 750; text-wrap: balance; }
.s-th-open { display: inline-flex; align-items: center; gap: 4px; font-size: 14px; font-weight: 650; white-space: nowrap; }
.s-th-line { font-size: 14.5px; line-height: 1.45; color: var(--color-muted); }
.s-th-groups { padding-top: 28px; }
.s-th-grp { display: grid; gap: 14px; padding-block: 26px; border-top: 1px solid var(--color-line); }
@media (min-width: 900px) { .s-th-grp { grid-template-columns: 240px minmax(0, 1fr); gap: 28px; } }
.s-th-grp-head h2 { display: flex; align-items: center; gap: 9px; font-size: 19px; line-height: 1.2; font-weight: 800; white-space: nowrap; }
.s-th-grp-head h2 i { flex: none; width: 9px; height: 9px; border-radius: 50%; background: var(--c); }
.s-th-grp-head p { margin-top: 6px; font-size: 14.5px; line-height: 1.45; color: var(--color-muted); max-width: 32ch; }
.s-th-list { display: grid; gap: 10px; align-content: start; }
@media (min-width: 640px) { .s-th-list { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (min-width: 1100px) { .s-th-list { grid-template-columns: repeat(3, minmax(0, 1fr)); } }
.s-th-card { display: flex; flex-direction: column; gap: 6px; height: 100%; min-height: 44px; padding: 14px 16px; border: 1px solid var(--color-line); border-radius: 16px; background: var(--color-panel); }
.s-th-card:hover { border-color: var(--color-muted); }
.s-th-card-top { display: flex; align-items: center; gap: 8px; }
