.s-xlights i::before { content: ''; position: absolute; top: -4px; left: 2px; width: 5px; height: 4px; border-radius: 1px; background: #3D5A4C; }
.s-xlights i:nth-child(4n+2) { top: 14px; } .s-xlights i:nth-child(4n+3) { top: 19px; } .s-xlights i:nth-child(4n) { top: 11px; }
.s-xlights i:nth-child(5n+2) { --b: #E9C46A; } .s-xlights i:nth-child(5n+3) { --b: #2BA58A; } .s-xlights i:nth-child(5n+4) { --b: #F7F1E6; } .s-xlights i:nth-child(5n) { --b: #7FA6E8; }
