@media (min-width: 600px) { .s-xcards { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (min-width: 900px) { .s-xcards { grid-template-columns: repeat(6, minmax(0, 1fr)); } .s-xcards > * { grid-column: span 2; }
    .s-xcards-tail > :nth-last-child(-n+4) { grid-column: span 3; } }
