.s-xbar { position: relative; height: 6px; border-radius: 3px; background: color-mix(in srgb, var(--color-cream) 13%, var(--color-panel)); }
.s-xbar::before { content: ''; position: absolute; left: var(--mid); top: -4px; bottom: -4px; width: 1px; background: color-mix(in srgb, var(--color-cream) 35%, transparent); }
.s-xbar i { position: absolute; top: 0; bottom: 0; left: var(--lo); right: calc(100% - var(--hi)); min-width: 6px; border-radius: 3px; background: var(--ci); transition: opacity .2s; }
.s-xpart > svg { color: var(--color-muted); }
