.s-xhead { display: flex; align-items: flex-end; min-height: 204px; margin: -26px -24px 0; padding: 22px 24px 18px; isolation: isolate; }
.s-xhead > .s-fpic-bg { position: absolute; inset: 0; z-index: -1; background: var(--tb); }
