.s-sh-search-sm { max-width: 320px; min-height: 44px; margin-top: 0; }
.s-sh-search-sm input { height: 40px; font-size: 15px; }
.s-sh-chips { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 18px; }
.s-sh-chip2, .s-sh-filter { display: inline-flex; align-items: center; gap: 8px; min-height: 40px; padding: 0 14px; border: 1px solid var(--color-line); border-radius: 999px; background: var(--color-panel); font-size: 14.5px; font-weight: 600; white-space: nowrap; }
.s-sh-chip2 i, .s-sh-filter i, .s-sh-letters li i { flex: none; width: 8px; height: 8px; border-radius: 50%; background: var(--dot, var(--tb)); }
.s-sh-chip2 span, .s-sh-filter span { font-weight: 500; color: var(--color-muted); font-variant-numeric: tabular-nums; }
.s-sh-chip2:hover { border-color: var(--color-cream); }
/* Each collection's dot (the chips, the A to Z): a brighter mark of its palette, so the five tell apart on cream. */
.s-tone-christmas { --dot: #C8323F; }
.s-tone-hymns { --dot: #8A4FB0; }
.s-tone-spirituals { --dot: #2F63B8; }
.s-tone-sea-shanties { --dot: #1E8C8C; }
.s-tone-rounds { --dot: #E0891E; }
.s-tone-jewish-songs { --dot: #3E5FC4; }
.s-tone-scottish-songs { --dot: #B24FC0; }
.s-tone-villancicos { --dot: #E2602A; }
.s-tone-thanksgiving-hymns { --dot: #B98A2A; }
.s-tone-shaker-songs { --dot: #4F8A9E; }
.s-tone-choral-classics { --dot: #A3607D; }
.s-tone-folk-songs { --dot: #6E8B3D; }
.s-tone-barbershop-songs { --dot: #B0304A; }
.s-tone-other { --dot: #9A9085; }
.s-sh-try .s-mixer { box-shadow: 0 24px 48px -28px rgb(60 40 10 / 0.35); }
@media (max-width: 639px) { .s-sh-try-k { display: none; } }
.s-sh-try-k { margin-inline-start: auto; font-size: 12px; font-weight: 700; letter-spacing: .14em; text-transform: uppercase; color: var(--color-muted); white-space: nowrap; }
/* A panel: inset, its own ground, as tall as what's in it; the one in season runs the full width with its sky. */
.s-sh-band { width: calc(100% - 32px); max-width: 1200px; margin: 40px auto 0; border-radius: 22px; box-shadow: inset 0 0 0 1px rgba(247, 241, 230, .08); }
.s-sh-band.s-sh-season { width: 100%; max-width: none; margin-top: 48px; border-radius: 0; box-shadow: none; }
/* A panel's motif keeps to its songs' side, behind them, never over its words; a phone's is shallower. */
.s-sh-band .s-tone-motif { height: 36px; }
/* The season's snow stays off the words (it read as punctuation on them): below the lights on a phone, the songs' side from 900. */
.s-sh-season .s-xsnow { -webkit-mask-image: linear-gradient(#000 0 96px, transparent 140px); mask-image: linear-gradient(#000 0 96px, transparent 140px); }
.s-sh-band-in { position: relative; z-index: 1; display: grid; grid-template-areas: "words" "songs" "all"; gap: 20px; padding: 56px 20px 24px; }
.s-sh-season .s-sh-band-in { max-width: 1200px; margin-inline: auto; padding: 64px 16px 48px; }
/* The page column's edges, from the hero to the A to Z (the review: the band sat 8 px inside them). */
.s-sh-words { grid-area: words; }
.s-sh-kick { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 12px; font-size: 12.5px; font-weight: 700; letter-spacing: .14em; text-transform: uppercase; color: var(--ta); }
.s-sh-chip { display: inline-flex; gap: 8px; padding: 4px 10px; border-radius: 999px; background: rgba(247, 241, 230, .12); color: var(--color-cream); font-weight: 600; letter-spacing: .02em; text-transform: none; white-space: nowrap; }
.s-sh-chip > span + span::before { content: '·'; margin-inline-end: 8px; }
.s-sh-band h2 { margin-top: 10px; font-size: clamp(26px, 6.5vw, 40px); line-height: 1.08; letter-spacing: -.02em; text-wrap: balance; }
.s-sh-band h2 em { white-space: nowrap; }
.s-sh-season h2 { margin-top: 14px; }
.s-sh-line { margin-top: 12px; max-width: 44ch; line-height: 1.55; color: var(--tm); }
.s-sh-songs { grid-area: songs; display: grid; gap: 10px; }
.s-sh-song { display: flex; align-items: center; gap: 12px; min-height: 60px; padding: 8px 10px 8px 16px; border-radius: 16px; background: var(--tl); box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--ta) 18%, transparent); }
.s-sh-song .s-play { width: 42px; height: 42px; }
.s-sh-song > a { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 2px; padding-block: 6px; color: var(--color-cream); }
.s-sh-song b { font-size: 16px; font-weight: 700; }
.s-sh-song a span { font-size: 13px; color: var(--tm); }
.s-sh-song > a:hover b { text-decoration: underline; text-underline-offset: 3px; }
.s-sh-all { grid-area: all; justify-content: center; min-height: 48px; white-space: nowrap; }
/* The collections as a grid of panels (Hillel's songbook design): each its palette, its title with a serif tail, "All N"
   at top right, one line, four songs (three on a phone); its motif along its top, behind. */
.s-sh-grid-head { display: grid; gap: 10px; }
.s-sh-grid-head h2 { margin-top: 8px; font-size: clamp(28px, 6vw, 40px); line-height: 1.1; letter-spacing: -.02em; text-wrap: balance; }
.s-sh-grid-head h2 em { white-space: nowrap; }
.s-sh-grid-note { color: var(--color-muted); }
.s-sh-choirs { margin-top: 8px; }
.s-sh-choirs svg { display: inline-block; vertical-align: -3px; }
.s-sh-grid { display: grid; gap: 16px; margin-top: 24px; }
.s-sh-panel { border-radius: var(--k-r-feature); box-shadow: inset 0 0 0 1px rgba(247, 241, 230, .08); }
/* Inset from the corners, so no rounded corner cuts it. */
.s-sh-panel .s-tone-motif { top: 10px; right: 22px; width: calc(100% - 44px); height: 30px; }
.s-sh-panel .s-tone-motif.s-hk { top: 8px; right: 22px; width: auto; height: 44px; aspect-ratio: 240 / 152; opacity: .94; }
.s-sh-panel .s-tone-motif.s-obj { top: 8px; right: 22px; width: auto; height: 44px; }
.s-sh-panel-in { position: relative; z-index: 1; padding: 44px 20px 20px; }
/* A panel's picture: one of its songs' featured pictures across its top, in place of a drawn motif (Hillel, 2026-11-18),
   fading into the panel's ground, its song named in a pill at its foot (a link to the song). */
/* A /songs panel's head: its title leads over one of its songs' pictures, quiet atmosphere fading into the panel's ground
   (Hillel, 2026-11-18), the song named small at the picture's top. */
.s-sh-pic-wrap { position: absolute; inset: 0 0 auto; height: 230px; }
.s-sh-pic { position: absolute; inset: 0; background: var(--tb); }
.s-sh-pic.s-fpic-bg::after { content: ''; position: absolute; inset: 0; pointer-events: none; background: linear-gradient(to bottom, transparent 0%, transparent 18%, color-mix(in srgb, var(--tb) 72%, transparent) 42%, color-mix(in srgb, var(--tb) 90%, transparent) 60%, var(--tb) 100%); }
.s-sh-pic-song { position: absolute; z-index: 2; inset-inline-start: 20px; top: 14px; display: inline-flex; align-items: center; min-height: 32px; padding: 0 12px; border-radius: 999px; background: color-mix(in srgb, var(--tb) 88%, transparent); color: #F7F1E6; font-size: 13px; font-weight: 700; white-space: nowrap; }
.s-sh-pic-song::after { content: ''; position: absolute; inset: -6px -2px; }
.s-sh-pic-song:hover { text-decoration: underline; text-underline-offset: 3px; }
.s-sh-panel-in.s-sh-panel-pictured { padding-top: 120px; }
.s-sh-panel-pictured h3 { text-shadow: 0 1px 2px rgb(0 0 0 / .5), 0 0 16px rgb(0 0 0 / .45); }
.s-sh-panel-top { display: flex; flex-wrap: wrap; align-items: baseline; justify-content: space-between; gap: 4px 12px; } /* wraps: a long Spanish heading in the arcade font pushed "All" off a phone */
.s-sh-panel h3 { font-size: clamp(24px, 6vw, 30px); line-height: 1.1; letter-spacing: -.02em; }
.s-sh-panel h3 em { white-space: nowrap; }
.s-sh-panel-all { flex: none; display: inline-flex; align-items: center; gap: 4px; min-height: 44px; font-size: 14.5px; font-weight: 700; color: var(--ta); white-space: nowrap; }
.s-sh-panel-all svg { display: inline-block; }
.s-sh-panel-all:hover { text-decoration: underline; text-underline-offset: 3px; }
.s-sh-panel .s-sh-line { margin-top: 4px; }
.s-sh-panel .s-sh-songs { margin-top: 18px; }
@media (max-width: 639px) { .s-sh-song:nth-child(n+4) { display: none; } }
/* Every song by letter (Hillel's songbook design): its filters and search narrow it in place (js/public/songbook.js). */
.s-sh-index-head { display: flex; flex-wrap: wrap; align-items: end; justify-content: space-between; gap: 16px; }
.s-sh-index h2 { margin-top: 8px; font-size: clamp(32px, 7vw, 48px); line-height: 1.05; letter-spacing: -.02em; }
.s-sh-filters { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; margin-top: 20px; padding-bottom: 20px; border-bottom: 1px solid var(--color-line); }
.s-sh-filter { cursor: pointer; color: var(--color-cream); }
.s-sh-filter[aria-pressed="true"] { border-color: var(--color-cream); background: var(--color-cream); color: var(--color-ink); }
.s-sh-filter[aria-pressed="true"] span { color: inherit; opacity: .7; }
.s-sh-shown { margin-inline-start: auto; font-size: 14px; color: var(--color-muted); white-space: nowrap; }
.s-sh-letters { columns: 1; column-gap: 28px; margin-top: 20px; }
@media (min-width: 560px) { .s-sh-letters { columns: 2; } }
.s-sh-letter { break-inside: avoid; padding-bottom: 18px; }
.s-sh-letter h3 { font-size: 30px; line-height: 1; color: #B4472E; }
.s-sh-letters ul { margin-top: 6px; }
.s-sh-letters li { border-bottom: 1px solid var(--color-line); }
.s-sh-letters li a { display: flex; align-items: baseline; gap: 10px; padding-block: 9px; font-size: 15px; }
.s-sh-letters li i { transform: translateY(-2px); }
.s-sh-letters li a:hover span { text-decoration: underline; text-underline-offset: 3px; }
.s-sh-none { margin-top: 16px; color: var(--color-muted); }
/* The close, left-aligned: the words and the one way on. */
/* A cream pill on the dark close in both modes (dark on near-black vanished in light mode). */
@media (min-width: 640px) {
    .s-sh-songs { grid-template-columns: repeat(2, minmax(0, 1fr)); }
    .s-sh-all { justify-self: start; }
}
@media (min-width: 900px) {
    .s-sh-hero { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 56px; align-items: start; padding-top: 48px; }
    .s-sh-grid-head { grid-template-columns: minmax(0, 1fr) auto; align-items: end; }
    .s-sh-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
    .s-sh-panel-in { padding: 48px 28px 28px; }
    .s-sh-panel-in.s-sh-panel-pictured { padding-top: 140px; }
    .s-sh-pic-wrap { height: 270px; }
    .s-sh-pic-song { inset-inline-start: 28px; }
    .s-sh-panel .s-tone-motif { width: 60%; }
    .s-sh-band-in { grid-template-columns: minmax(0, 38fr) minmax(0, 62fr); grid-template-areas: "words songs" "all songs"; gap: 16px 48px; padding: 44px 48px; }
    .s-sh-band .s-tone-motif { width: 62%; height: 40px; }
    .s-sh-band-in { padding-top: 44px; }
    .s-sh-season .s-sh-band-in { padding: 64px 16px 48px; }
    .s-sh-season .s-xsnow { -webkit-mask-image: linear-gradient(to right, transparent 0 42%, #000 58%); mask-image: linear-gradient(to right, transparent 0 42%, #000 58%); }
    .s-sh-words { align-self: end; }
    .s-sh-all { align-self: start; }
    .s-sh-letters { columns: 4; }
}
@media (max-width: 640px) { .s-xband { padding: 28px 22px; } .s-xband-go, .s-xband-go .btn-secondary { width: 100%; justify-content: center; } }
/* In season, the footer on the season's green, with its line in the serif. */
.s-xfoot {
    --color-cream: #F7F1E6; --color-muted: #C9D8CD; --color-accent: #E9C46A; --color-line: rgba(217, 227, 218, .18);
    margin-top: 96px; padding-top: 8px; border-radius: 36px 36px 0 0; background: #12372A; color: var(--color-cream);
}
.s-xfoot .s-foot-grid { border-top: 0; }
@media (max-width: 640px) { .s-xhero .s-actions > a { flex: 1 1 100%; justify-content: center; } }
.s-foot-xmas { margin-top: 14px; font-family: ui-serif, 'Iowan Old Style', 'Palatino Linotype', Palatino, Georgia, serif; font-style: italic; font-size: 22px; color: #E9C46A; }
/* About Stackapella below a tool or the hub (site/tools/_about; docs/tools/below-the-fold.md): the page's one accent
   block. One real screen (the help shot of the alto being recorded): on a phone cropped in CSS to its note lane (y 340
   to 980 of 1688, x 32 to 748 of 780; percent margins follow the width), on desktop its top in a phone frame. */
.s-about-panel { display: grid; grid-template-areas: "by" "h" "lede" "vis" "ben" "cta" "proof"; padding: 26px 20px 24px; border-radius: var(--k-r-feature); background: var(--color-raised); overflow: hidden; }
.s-about-by { grid-area: by; display: inline-flex; align-items: center; gap: 10px; font-size: 15px; font-weight: 800; }
.s-about h2 { grid-area: h; margin-top: 16px; font-size: 29px; line-height: 1.14; font-weight: 850; letter-spacing: -.015em; text-wrap: balance; }
.s-about h2.s-about-result { font-size: 21px; line-height: 1.3; letter-spacing: 0; }
.s-about-lede { grid-area: lede; margin-top: 12px; max-width: 44ch; font-size: 17px; line-height: 1.55; }
.s-about-vis { grid-area: vis; position: relative; margin-top: 24px; padding-bottom: 142px; }
.s-about-shot { aspect-ratio: 716 / 640; overflow: hidden; border-radius: var(--k-r-inner); background: var(--color-ink); }
.s-about-shot .s-appshot { display: block; width: 100%; }
.s-about-shot .s-appshot picture { width: 100%; }
.s-about-shot .s-appshot img { display: block; width: 108.94%; max-width: none; height: auto; margin-left: -4.47%; margin-top: -47.49%; border: 0; border-radius: 0; aspect-ratio: auto; }
.s-about-stack { position: absolute; right: -4px; bottom: 0; width: 218px; padding: 12px 12px 10px; border-radius: var(--k-r-card); background: var(--color-panel); border: 1px solid var(--color-edge); box-shadow: 0 18px 40px -14px rgb(0 0 0 / .6); }
.s-about-stack-h { font-size: 13px; font-weight: 800; }
.s-about-stack-h span { display: block; margin-top: 1px; font-size: 11.5px; font-weight: 500; color: var(--color-muted); }
.s-about-lane { display: grid; grid-template-columns: 8px 52px 1fr; align-items: center; gap: 7px; margin-top: 8px; }
.s-about-lane i { width: 8px; height: 8px; border-radius: 9px; background: var(--c); }
.s-about-lane b { font-size: 12px; font-weight: 750; }
.s-about-wave { width: 100%; height: 22px; color: var(--ci); }
.s-about-ben { grid-area: ben; display: grid; gap: 18px; margin-top: 26px; }
.s-about-ben li { display: grid; grid-template-columns: 40px 1fr; gap: 14px; align-items: start; }
.s-about-ben .s-who-ic { width: 40px; height: 40px; }
.s-about-ben b { display: block; font-size: 17px; font-weight: 750; line-height: 1.3; }
.s-about-ben li span:not(.s-who-ic) { display: block; margin-top: 2px; font-size: 15.5px; line-height: 1.5; color: var(--color-muted); }
.s-about-cta { grid-area: cta; display: grid; gap: 6px; margin-top: 28px; }
.s-about-cta .btn-primary { min-height: 54px; font-size: 17px; }
.s-about-cta .s-lk { justify-self: center; padding-block: 12px; margin-block: 0; }
.s-about-proof { grid-area: proof; display: flex; flex-wrap: wrap; gap: 8px 18px; margin-top: 18px; padding-top: 16px; border-top: 1px solid var(--color-edge); font-size: 14.5px; color: var(--color-muted); }
.s-about-proof li { display: inline-flex; align-items: center; gap: 6px; }
.s-about-proof svg { color: var(--color-good); flex: none; }
.s-about-proof a { text-decoration: underline; text-underline-offset: 3px; }
@media (min-width: 900px) {
    .s-about-panel { grid-template-columns: minmax(0, 1fr) 470px; grid-template-areas: "by vis" "h vis" "lede vis" "ben vis" "cta vis" "proof vis"; column-gap: 64px; align-items: start; padding: 56px 56px 48px; border-radius: var(--k-r-feature); }
    .s-about h2 { margin-top: 20px; font-size: 42px; }
    .s-about h2.s-about-result { font-size: 28px; }
    .s-about-lede { font-size: 19px; }
    .s-about-vis { align-self: stretch; height: 100%; min-height: 590px; margin-top: 0; padding: 0; }
    .s-about-shot { position: absolute; top: 0; right: 0; width: 330px; aspect-ratio: 780 / 1010; border-radius: var(--k-r-feature); border: 1px solid var(--color-edge); box-shadow: 0 30px 70px -24px rgb(0 0 0 / .6); }
    .s-about-shot .s-appshot img { width: 100%; margin: 0; }
    .s-about-stack { left: 0; right: auto; bottom: 8px; width: 262px; padding: 16px 16px 14px; border-radius: var(--k-r-card); }
    .s-about-stack-h { font-size: 14px; }
    .s-about-stack-h span { font-size: 12.5px; }
    .s-about-lane { grid-template-columns: 8px 62px 1fr; margin-top: 10px; }
    .s-about-lane b { font-size: 13px; }
    .s-about-wave { height: 26px; }
    .s-about-cta { grid-template-columns: auto auto; justify-content: start; align-items: center; gap: 22px; }
    .s-about-proof { margin-top: 30px; }
}
/* Between 900 and 1199 px the picture column narrows (380 px, its shot and song card smaller), so the words keep
   290 px or more and "Start the beginner course" stays on one line (game, 2026-11-12: 151 px at 1000). */
@media (min-width: 900px) and (max-width: 1199px) {
    .s-about-panel { grid-template-columns: minmax(0, 1fr) 380px; column-gap: 40px; padding: 48px 44px 40px; }
    .s-about-vis { min-height: 520px; }
    .s-about-shot { width: 280px; }
    .s-about-stack { width: 236px; }
}
/* More free tools (site/tools/_directory): the featured next tool, then every other live tool in five groups, each in
   its group's colour (always with the group's name). Tiles on a phone, one panel in three columns on desktop. */
.s-tdir-head { display: grid; gap: 4px; }
.s-tdir h2 { font-size: 26px; line-height: 1.15; font-weight: 850; letter-spacing: -.01em; }
.s-tdir-head p { font-size: 15.5px; color: var(--color-muted); }
.s-tdir-head .s-lk { justify-self: start; display: inline-flex; align-items: center; gap: 6px; margin-top: 2px; padding-block: 12px; margin-block: -4px; }
.s-tfeat { display: grid; grid-template-columns: 48px 1fr 24px; align-items: center; gap: 14px; margin-top: 18px; padding: 16px; border-radius: 20px; background: color-mix(in srgb, var(--c) 9%, var(--color-panel)); border: 1px solid color-mix(in srgb, var(--c) 38%, var(--color-edge)); }
.s-tfeat .s-who-ic { width: 48px; height: 48px; }
.s-tfeat b { display: block; font-size: 17px; font-weight: 750; line-height: 1.3; }
.s-tfeat b + span { display: block; margin-top: 2px; font-size: 15px; color: var(--color-muted); }
.s-tfeat > svg { color: var(--color-muted); }
.s-tdir-all { display: grid; gap: 22px; margin-top: 26px; }
.s-tdir-grp h3 { display: flex; align-items: center; gap: 8px; font-size: 12.5px; font-weight: 750; letter-spacing: .12em; text-transform: uppercase; color: var(--color-muted); }
.s-tdir-grp h3 i { width: 8px; height: 8px; border-radius: 9px; background: var(--c); }
.s-tdir-grp ul { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px; margin-top: 10px; }
.s-tdir-grp a { display: grid; grid-template-columns: 34px minmax(0, 1fr); align-items: center; gap: 10px; min-height: 60px; height: 100%; padding: 10px; border-radius: 16px; background: var(--color-panel); border: 1px solid var(--color-edge); }
.s-tdir-grp .s-who-ic { width: 34px; height: 34px; }
.s-tdir-grp b { font-size: 15px; font-weight: 700; line-height: 1.25; overflow-wrap: break-word; hyphens: auto; }
.s-tdir-grp b + span { display: none; }
:is(.s-tfeat, .s-tdir-grp a):focus-visible { outline: 2px solid var(--color-cream); outline-offset: 3px; }
@media (min-width: 900px) {
    .s-tdir-head { grid-template-columns: 1fr auto; align-items: end; }
    .s-tdir h2 { font-size: 34px; }
    .s-tdir-head .s-lk { grid-row: 1 / span 2; grid-column: 2; align-self: end; }
    .s-tfeat { grid-template-columns: 52px 1fr 24px; margin-top: 28px; padding: 18px 22px; }
    .s-tfeat .s-who-ic { width: 52px; height: 52px; }
    .s-tdir-all { display: block; columns: 3; column-gap: 40px; margin-top: 16px; padding: 26px 30px 12px; border-radius: 24px; background: var(--color-panel); border: 1px solid var(--color-edge); }
    .s-tdir-grp { break-inside: avoid; padding-bottom: 20px; }
    .s-tdir-grp ul { grid-template-columns: 1fr; gap: 2px; margin-top: 8px; }
    .s-tdir-grp a { grid-template-columns: 36px 1fr; gap: 12px; min-height: 56px; margin-inline: -10px; padding: 8px 10px; border: 0; border-radius: 14px; background: none; }
    .s-tdir-grp a:hover { background: var(--color-raised); }
    .s-tdir-grp .s-who-ic { width: 36px; height: 36px; }
    .s-tdir-grp b { display: block; font-size: 16px; }
