.s-arrow { display: inline-flex; align-items: center; gap: 8px; margin-top: 28px; font-weight: 650; color: var(--color-cream); padding-bottom: 4px; border-bottom: 1.5px solid currentColor; }
.s-arrow:hover { color: var(--color-part-ink-2); }
