.s-split { display: grid; grid-template-columns: minmax(0, 1fr); gap: 40px; align-items: center; }
/* A product card at real scale: a raised glass surface, never a hairline box. */
.s-card3d { border-radius: 28px; background: var(--color-panel); border: 1px solid var(--color-edge); padding: 22px; box-shadow: 0 1px 0 color-mix(in srgb, white 7%, transparent) inset, 0 40px 80px -40px rgb(0 0 0 / .45), 0 12px 24px -12px rgb(0 0 0 / .25); }
