.s-pricehead { display: grid; gap: 24px; padding-top: var(--k-hero-top); }
.s-pricehead h1 { font-size: clamp(38px, 9vw, 68px); line-height: 1.02; font-weight: 800; letter-spacing: -0.03em; text-wrap: balance; margin-top: 14px; max-width: 20ch; }
.s-pricehead-side { display: grid; gap: 12px; justify-items: start; }
.s-featurehead { padding-top: 28px; }
.s-featurehead h1 { font-size: clamp(38px, 9vw, 68px); line-height: 1.02; font-weight: 800; letter-spacing: -0.03em; text-wrap: balance; margin-top: 14px; max-width: 14ch; }
.s-featurehead .s-actions { margin-top: 28px; display: grid; gap: 10px; justify-items: start; }
.s-featurehead .s-actions p { font-size: 14px; color: var(--color-muted); }
.s-soonpill { margin-top: 18px; }
.s-soonpill .s-soon { font-size: 13px; padding: 6px 14px; border-radius: 99px; background: color-mix(in srgb, var(--color-part-2) 16%, transparent); color: var(--color-part-ink-2); }
.s-soonline { margin-top: 14px; font-size: 15.5px; line-height: 1.5; color: var(--color-muted); max-width: 52ch; }
