.cp-try .s-title { color: inherit; }
.cp-try :is(.cp-try-lead, .cp-try-after) { color: color-mix(in srgb, var(--cp-a-ink) 88%, transparent); }
.cp-try .cp-try-steps { gap: 18px; margin-top: 26px; }
.cp-try .cp-try-steps li { font-size: 18.5px; line-height: 1.55; }
.cp-try .cp-try-n { width: 34px; height: 34px; border-color: currentColor; color: inherit; }
.cp-try-lead { margin-top: 12px; font-size: 16px; line-height: 1.55; color: var(--color-muted); max-width: 60ch; }
.cp-try-steps { display: grid; gap: 14px; margin-top: 20px; }
.cp-try-steps li { display: grid; grid-template-columns: auto minmax(0, 1fr); gap: 14px; align-items: start; font-size: 17px; line-height: 1.5; }
.cp-try-n { display: grid; place-items: center; width: 30px; height: 30px; border-radius: 99px; font-size: 15px; font-weight: 800; border: 2px solid var(--cp-a); color: var(--color-cream); }
.cp-try-after { margin-top: 20px; font-size: 15px; line-height: 1.5; color: var(--color-muted); max-width: 60ch; }
.cp-facts { display: grid; grid-template-columns: minmax(0, 1fr); gap: 14px; margin-top: 22px; }
.cp-fact { display: flex; flex-direction: column; justify-content: space-between; gap: 14px; padding: 22px; border-radius: 22px; background: var(--color-panel); border: 1px solid var(--cp-line); }
.cp-fact p:first-child { font-size: 17px; line-height: 1.5; font-weight: 600; }
.cp-fact-src { font-size: 13px; color: var(--color-muted); }
.cp-fact-src a { text-decoration: underline; text-underline-offset: 3px; }
.cp-three { display: grid; grid-template-columns: minmax(0, 1fr); gap: 34px; }
