.cp-faq { margin-top: 18px; max-width: 760px; }
.cp-faq details { border-bottom: 1px solid var(--cp-line); }
.cp-faq summary { display: flex; align-items: center; justify-content: space-between; gap: 16px; min-height: 56px; padding-block: 16px; font-size: clamp(18px, 2vw, 21px); font-weight: 700; cursor: pointer; list-style: none; }
.cp-faq summary::-webkit-details-marker { display: none; }
.cp-faq-sign { flex: none; display: grid; place-items: center; width: 32px; height: 32px; border-radius: 99px; background: var(--fill-2, var(--color-raised)); transition: rotate .2s; }
.cp-faq details[open] .cp-faq-sign { rotate: 45deg; }
.cp-faq details p { padding-bottom: 18px; font-size: 17px; line-height: 1.6; color: var(--color-muted); max-width: 66ch; }
.cp-join { position: relative; background: var(--color-panel); }
.cp-join-card { margin-top: 16px; }
.cp-join-line { font-size: 20px; font-weight: 750; }
.cp-join-note { margin-top: 6px; font-size: 15px; color: var(--color-muted); }
.cp-join-btns { display: flex; flex-wrap: wrap; gap: 12px; margin-top: 22px; }
.cp-related-h { margin-top: 44px; }
.cp-related { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 14px; }
.cp-related a { display: inline-flex; align-items: center; gap: 8px; min-height: 44px; padding: 0 16px; border-radius: 99px; font-weight: 650; background: var(--fill-2, var(--color-raised)); }
.cp-related a:hover { background: var(--fill-3, var(--color-line)); }
