@media (min-width: 900px) {
    .cp-hero { padding-block: 32px 72px; }
    .cp-hero-grid { grid-template-columns: minmax(0, 1.05fr) minmax(0, .95fr); gap: 56px; }
    .cp-outcomes { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 26px 56px; }
    .cp-units { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 18px; }
    .cp-unit { padding: 28px; }
