    .cp-try { padding: 52px 56px; }
    .cp-try .cp-try-steps { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 24px 48px; }
    .cp-facts { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 18px; }
