@media (prefers-reduced-motion: reduce) { .cp-faq-sign { transition: none; } }
/* The units in one row of columns on a wide screen. */
@media (min-width: 1100px) { .cp-units { grid-auto-flow: column; grid-auto-columns: minmax(0, 1fr); grid-template-columns: none; } }
/* Questions beside their heading on a wide screen; the close as one centred block. */
@media (min-width: 960px) { .cp .cp-side { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 2fr); gap: 56px; align-items: start; } .cp .cp-side .cp-faq { margin-top: 0; } }
.cp-join-centred > .s-wrap { display: grid; justify-items: center; text-align: center; }
.cp-join-centred :is(.cp-join-btns, .cp-related) { justify-content: center; }
.cp-join-centred .cp-join-note { margin-inline: auto; }
/* 4 and 10: dark bands no taller than what's in them, and small words at a readable contrast. */
.cp .s-ink { padding-block: clamp(48px, 6vw, 72px); }
.cp { --color-muted: color-mix(in srgb, var(--color-cream) 80%, var(--color-ink)); }
.cp-head-note, .cp-fig-note, .cp-inside-score { font-size: 16px; }
/* A band's own padding is the section's: no second gap inside it. */
.cp .s-ink > .s-sec { padding-top: 0; }
.cp .cp-first { padding-top: 48px; }
@media (min-width: 900px) { .cp .cp-first { padding-top: 72px; } }
.cp .cp-join > .s-sec { padding-block: 56px 72px; }
.cp-faq + * { margin-top: 0; }
:root[data-skin="game"] body.s-arcade .cp-hero h1 { font-family: var(--a-display); font-weight: 400; text-transform: uppercase; letter-spacing: .01em; line-height: 1.02; font-size: clamp(36px, 8.5vw, 68px); font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade :is(.cp-unit, .cp-fact) { background: var(--a-panel); border-color: var(--a-line); }
:root[data-skin="game"] body.s-arcade .cp-unit-n { font-family: var(--a-hud); font-size: 9.5px; font-weight: 400; letter-spacing: .06em; font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade .cp-join { background: var(--a-bg-2, var(--a-panel)); }

/* A designed course page's shared pieces: a section's words beside a pair of figures (cp-pair), a row
   of small wordless figures with captions (cp-figs), and the dark band on singing it safely (cp-care,
   its icons in the page's --cp-care). */
.cp-pair { display: grid; grid-template-columns: minmax(0, 1fr); gap: 28px; align-items: center; }
.cp-pair-figs { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 14px; }
.cp-figs { display: grid; grid-template-columns: minmax(0, 1fr); gap: 14px; margin-top: 24px; }
.cp-fig { margin: 0; padding: 18px; border-radius: 20px; background: var(--color-panel); border: 1px solid var(--cp-line); }
.cp-fig svg { display: block; width: 100%; height: auto; overflow: visible; }
.cp-fig figcaption { margin-top: 10px; font-size: 14.5px; line-height: 1.45; color: var(--color-muted); }
.cp-fig figcaption b { display: block; font-size: 16px; color: var(--color-cream); }
.cp-fig-note { margin-top: 14px; font-size: 15.5px; line-height: 1.55; color: var(--color-muted); max-width: 60ch; }
.cp-care .s-lede { max-width: 52ch; }
.cp-care-points { display: grid; grid-template-columns: minmax(0, 1fr); gap: 12px; margin-top: 26px; }
.cp-care-points li { display: flex; gap: 12px; align-items: flex-start; padding: 16px 18px; border-radius: 16px; background: color-mix(in srgb, var(--color-cream) 6%, transparent); font-size: 16px; line-height: 1.45; }
.cp-care-points svg { flex: none; margin-top: 2px; color: var(--cp-care, var(--cp-a-text)); }
@media (min-width: 900px) {
    .cp-pair { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 56px; }
    .cp-figs { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 18px; }
    .cp-care-points { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 14px; }
}

/* Barbershop (site/courses/barbershop): "The Fifth Voice", a love letter (docs/course-pages-polish.md;
   docs/courses/barbershop-love-letter.md), set as an old barbershop and a quartet's playbill (Hillel's
   design, 2026-11-18). One drawing all the way down: one deep note's overtone ladder, evenly spaced, the
   barbershop seventh standing on rungs 4 to 7. Serious skin: paper, ink and barber red, Bodoni Moda for
   display (the design's 1910s sheet-music serif, self-hosted; large, bold, an italic end), Figtree labels and body; gold lettering only on the night
   grounds that are dark in every theme (the shop window, the tuner, 1941 to 1963, the green House Rules
   sign, the tag), so --bb-gold is one colour there, AA on each; the part colours fixed (bass navy,
   baritone green, lead gold, tenor rust). No barber pole and no pole stripes (Hillel: "remove the vertical
   barber pole at the top"). Game skin: "Ring Machine", Bungee display, Press Start readouts, a lock
   meter and a RING! burst, neon parts, square framed panels with hard shadows, the acts as stage tiles.
   Every demo's sound is js/public/barbershop.js, only when pressed. */
.cp-bb2 { --bb-paper: #f7f1e6; --bb-ink: #1e1a16; --bb-red: #a81e2b; --bb-muted: #5c544b; --bb-card: #fbf8f2;
    --bb-bass: #1f3a93; --bb-baritone: #27704a; --bb-lead: #865c04; --bb-tenor: #b5452f; --bb-ring: #c99a1e;
    --bb-night: #1e1915; --bb-night-ink: #f3ebdd; --bb-night-muted: #cfc4b3; --bb-gold: #e8c46f; --bb-gold-deep: #7a5a1c; --bb-sign: #1f3a2c; --bb-lock: #4fb57f;
    --bb-serif: "Bodoni Moda", ui-serif, "Iowan Old Style", "Palatino Linotype", Palatino, Georgia, serif; --cp-a: var(--bb-red); --cp-a-ink: #fff; --cp-a-text: var(--bb-red);
    background: var(--bb-paper); color: var(--bb-ink); }
:root:not([data-theme$="-light"]) .cp-bb2 { --bb-paper: #14110e; --bb-ink: #f3ebdd; --bb-red: #f28b82; --bb-muted: #b9ad9c; --bb-card: #1c1814;
    --bb-bass: #7c93e0; --bb-baritone: #4fb37e; --bb-lead: #d9a93a; --bb-tenor: #e0745a; --bb-ring: #e8c068; --bb-night: #0b0907; --cp-a: #c22131; --cp-a-text: #f28b82; }
:root[data-skin="game"]:not([data-theme$="-light"]) .cp-bb2 { --bb-paper: #0b0a14; --bb-ink: #ede9ff; --bb-red: #ff9dc4; --bb-muted: #b8b2d8; --bb-card: #120e24;
    --bb-bass: #a99bff; --bb-baritone: #4cf0b0; --bb-lead: #ffe45c; --bb-tenor: #ff8a5c; --bb-ring: #ffe45c; --cp-a: #ff5fd2; --cp-a-ink: #1a0414; --cp-a-text: #ff9dc4; }
:root[data-skin="game"] .cp-bb2 { --bb-night: #120e24; --bb-night-ink: #ede9ff; --bb-night-muted: #cfc8ff; --bb-gold: #ffe45c; --bb-gold-deep: #8f0e52; --bb-sign: #0a2219; --bb-lock: #4cf0b0; }
/* The night grounds are dark in every theme: their parts take the dark palette. */
:root:not([data-skin="game"]) :is(.cp-bb2-verse, .cp-bb2-tag, .cp-bb2-window) { --bb-bass: #7c93e0; --bb-baritone: #4fb37e; --bb-lead: #d9a93a; --bb-tenor: #e0745a; --bb-ring: #e8c068; }
:root[data-skin="game"][data-theme$="-light"] :is(.cp-bb2-verse, .cp-bb2-tag, .cp-bb2-window) { --bb-bass: #a99bff; --bb-baritone: #4cf0b0; --bb-lead: #ffe45c; --bb-tenor: #ff8a5c; --bb-ring: #ffe45c; }
.cp-bb2-v-tenor, .cp-bb2-rung-tenor { --part: var(--bb-tenor); } .cp-bb2-v-lead, .cp-bb2-rung-lead { --part: var(--bb-lead); }
.cp-bb2-v-baritone, .cp-bb2-rung-baritone { --part: var(--bb-baritone); } .cp-bb2-v-bass, .cp-bb2-rung-bass { --part: var(--bb-bass); }

/* Type. */
.cp-bb2-label { font-size: 12px; font-weight: 700; letter-spacing: .2em; text-transform: uppercase; color: var(--bb-red); }
:root[data-skin="game"] body.s-arcade .cp-bb2-label { font-family: "Stackapella Pixel", ui-monospace, monospace; font-size: 10px; letter-spacing: .06em; font-size-adjust: var(--arc-ex, none); }
.cp-bb2-h1, .cp-bb2-h2 { color: var(--bb-ink); text-wrap: balance; }
.cp-bb2-h1 { margin-top: 18px; font-family: var(--bb-serif); font-weight: 700; font-size: clamp(54px, 7.4vw, 112px); line-height: .92; letter-spacing: -0.025em; }
.cp-bb2-h1 em, .cp-bb2-h2 em { font-style: italic; font-weight: 500; color: var(--bb-red); }
.cp-bb2-h1 em { display: block; }
.cp-bb2-h2 { margin-top: 12px; font-family: var(--bb-serif); font-weight: 700; font-size: clamp(40px, 7vw, 84px); line-height: 1; letter-spacing: -0.02em; }
:root[data-skin="game"] body.s-arcade :is(.cp-bb2-h1, .cp-bb2-h2) { font-family: var(--a-display); font-weight: 400; letter-spacing: .01em; line-height: .92; text-transform: uppercase; font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade .cp-bb2-h2 em { font-style: normal; }
/* Bungee's CORNERSTONE is wider than a 320 phone at 40px. */
@media (max-width: 359px) { :root[data-skin="game"] body.s-arcade .cp-bb2-h2 { font-size: 34px; } }
:root[data-skin="game"] body.s-arcade .cp-bb2-h1 em { font-style: normal; color: var(--bb-lead); text-shadow: 0 0 22px color-mix(in srgb, var(--bb-lead) 60%, transparent); }
.cp-bb2-lede { margin-top: 18px; max-width: 58ch; font-size: 18px; line-height: 1.65; color: var(--bb-ink); }
.cp-bb2-note-small, .cp-bb2-quiet, .cp-bb2-soon { margin-top: 12px; font-size: 15px; line-height: 1.55; color: var(--bb-muted); max-width: 62ch; }
.cp-bb2 a:not([class*="btn"]) { color: inherit; text-decoration-color: color-mix(in srgb, var(--bb-red) 60%, transparent); text-underline-offset: 3px; }
.cp-bb2 a:not([class*="btn"]):hover, .cp-bb2 a:not([class*="btn"]):focus-visible { color: var(--bb-red); }
/* Numbered notes, and the list they point to. */
.s-cite { margin-left: 2px; font-size: .62em; line-height: 0; font-weight: 700; vertical-align: super; }
.cp-bb2 .s-cite a { padding: 0 2px; color: var(--bb-red); text-decoration: none; }
.cp-bb2-notes { padding-block: 8px 60px; }
.cp-bb2-notes summary { list-style: none; cursor: pointer; } .cp-bb2-notes summary::-webkit-details-marker { display: none; }
.cp-bb2-notes summary h2::after { content: " ▸"; } .cp-bb2-notes details[open] summary h2::after { content: ""; }
.cp-bb2-notes-n { color: var(--bb-muted); }
.cp-bb2-notes ol { margin-top: 14px; padding-left: 22px; list-style: decimal; columns: 2 320px; column-gap: 44px; font-size: 13.5px; line-height: 1.5; color: var(--bb-muted); }
.cp-bb2-notes h3 { margin-top: 22px; }
.cp-bb2-notes ul { display: grid; gap: 6px; margin-top: 10px; font-size: 13.5px; line-height: 1.5; color: var(--bb-muted); }
.cp-bb2-notes ul b { color: var(--bb-ink); }
.cp-bb2-also { padding-block: 48px 28px; }
.cp-bb2-notes li { margin-bottom: 6px; break-inside: avoid; scroll-margin-top: 90px; }
.cp-bb2-notes li:target { color: var(--bb-ink); background: color-mix(in srgb, var(--bb-ring) 22%, transparent); }

/* Buttons: the play control, the segmented toggle. Only Start is filled. */
.cp-bb2-ctas { display: flex; flex-wrap: wrap; align-items: center; gap: 14px; margin-top: 28px; }
.cp-bb2-center { justify-content: center; }
.cp-bb2-play { display: inline-flex; align-items: center; gap: 12px; min-height: 52px; padding: 0 22px 0 8px; border-radius: 99px; border: 2px solid var(--bb-ink); background: transparent; color: var(--bb-ink); font: 700 16px/1 Figtree, system-ui, sans-serif; white-space: nowrap; cursor: pointer; }
.cp-bb2-play:hover { background: color-mix(in srgb, var(--bb-ink) 8%, transparent); }
.cp-bb2 :is(.cp-bb2-play, .cp-bb2-seat, .cp-bb2-segs button, .cp-bb2-slider input, summary):focus-visible { outline: 3px solid var(--bb-red); outline-offset: 3px; }
.cp-bb2-play-icon { display: grid; place-items: center; flex: none; width: 38px; height: 38px; border-radius: 99px; background: var(--bb-red); }
.cp-bb2-play-icon::before { content: ""; margin-left: 3px; border-style: solid; border-width: 7px 0 7px 12px; border-color: transparent transparent transparent #fff; }
.cp-bb2-play[aria-pressed="true"] .cp-bb2-play-icon::before { margin: 0; width: 12px; height: 12px; border: 0; background: #fff; }
:root:not([data-theme$="-light"]) .cp-bb2-play-icon { background: #c22131; }
:root[data-skin="game"] body.s-arcade .cp-bb2-play { border-color: #ff9dc4; color: #ff9dc4; font-family: "Stackapella Pixel", ui-monospace, monospace; font-size: 11px; box-shadow: 0 0 18px -6px #ff5fd2; font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade .cp-bb2-play-icon { background: #ff5fd2; }
.cp-bb2-segs { display: inline-flex; padding: 3px; border-radius: 99px; border: 2px solid color-mix(in srgb, var(--bb-ink) 25%, transparent); }
.cp-bb2-segs button { min-height: 44px; padding: 0 20px; border-radius: 99px; background: transparent; color: var(--bb-ink); font: 700 15px/1 Figtree, system-ui, sans-serif; white-space: nowrap; cursor: pointer; }
.cp-bb2-segs [aria-pressed="true"] { background: var(--bb-ink); color: var(--bb-paper); }
:root[data-skin="game"] body.s-arcade .cp-bb2-segs { border-color: #a99bff; }
:root[data-skin="game"] body.s-arcade .cp-bb2-segs [aria-pressed="true"] { background: #a99bff; color: #0b0a14; }

/* The intro: a ticket, the words, and the ladder in an arched shop window. */
.cp-bb2-intro { padding: 22px 0 56px; overflow-x: clip; background: radial-gradient(60% 70% at 20% 30%, color-mix(in srgb, var(--bb-ring) 12%, var(--bb-paper)), var(--bb-paper) 70%); }
:root[data-skin="game"] body.s-arcade .cp-bb2-intro { background: radial-gradient(60% 70% at 78% 40%, color-mix(in srgb, #ff5fd2 14%, var(--bb-paper)), var(--bb-paper) 72%); }
.cp-bb2-intro-grid { display: grid; grid-template-columns: minmax(0, 1fr); gap: 44px; align-items: center; }
/* ADMIT ONE and the course, each on one line: side by side where they fit, the stub over the line on a phone. */
.cp-bb2-ticket { display: inline-grid; grid-auto-flow: column; margin-top: 22px; border: 1.5px solid var(--bb-red); color: var(--bb-red); font-size: 12px; font-weight: 700; line-height: 1; letter-spacing: .16em; text-transform: uppercase; }
.cp-bb2-ticket span { padding: 10px 14px; white-space: nowrap; }
.cp-bb2-ticket span + span { border-left: 1.5px dashed var(--bb-red); }
@media (max-width: 459px) { .cp-bb2-ticket { grid-auto-flow: row; } .cp-bb2-ticket span + span { border-left: 0; border-top: 1.5px dashed var(--bb-red); } }
:root[data-skin="game"] body.s-arcade .cp-bb2-ticket { border-color: #ff9dc4; color: #ff9dc4; font-family: "Stackapella Pixel", ui-monospace, monospace; font-size: 10px; letter-spacing: .04em; font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade .cp-bb2-ticket span + span { border-color: #ff9dc4; }
:root[data-skin="game"][data-theme$="-light"] body.s-arcade .cp-bb2-ticket, :root[data-skin="game"][data-theme$="-light"] body.s-arcade .cp-bb2-ticket span + span { border-color: #8f0e52; color: #8f0e52; }
.cp-bb2-ladder { margin: 0; }
.cp-bb2-window { position: relative; max-width: 500px; padding: clamp(64px, 14vw, 96px) clamp(18px, 4vw, 34px) 26px; border-radius: 50% 50% 10px 10px / 30% 30% 10px 10px; background: radial-gradient(90% 60% at 50% 8%, #4b3726, #251c15 62%, #1b1511); color: var(--bb-night-ink);
    box-shadow: inset 0 0 0 9px #2b2018, inset 0 0 0 10.5px var(--bb-gold), 0 30px 60px -30px #000a; }
/* The window's night as a solid colour under its gradient, so anything reading the background (a contrast check) finds the night. */
.cp-bb2-window { background-color: #1b1511; }
.cp-bb2-window-sign { padding-inline: 9%; text-align: center; font-family: var(--bb-serif); font-size: clamp(13px, 3.4vw, 16px); font-weight: 700; letter-spacing: .3em; text-transform: uppercase; color: var(--bb-gold); text-wrap: balance; }
.cp-bb2-window-sub { margin-top: 6px; text-align: center; font-family: var(--bb-serif); font-style: italic; font-size: 16px; color: #d8c9ad; }
.cp-bb2-window svg { display: block; width: 100%; height: auto; margin-top: 18px; overflow: visible; }
.cp-bb2-ladder figcaption { margin-top: 16px; max-width: 420px; font-size: 14px; line-height: 1.5; color: var(--bb-muted); }
.cp-bb2-rung-off { stroke: color-mix(in srgb, var(--bb-ink) 16%, transparent); stroke-width: 2; }
.cp-bb2-window .cp-bb2-rung-off { stroke: #f3ebdd2e; stroke-width: 1.5; }
.cp-bb2-rung-line { fill: none; stroke: var(--part); stroke-width: 5; stroke-linecap: round; stroke-linejoin: round; }
.cp-bb2-rung-wavy, [data-wavy] .cp-bb2-rung-straight { display: none; } [data-wavy] .cp-bb2-rung-wavy { display: inline; }
.cp-bb2-rung-n { font: 400 28px/1 var(--bb-serif); fill: var(--bb-muted); text-anchor: middle; font-variant-numeric: lining-nums tabular-nums; }
.cp-bb2-window .cp-bb2-rung-n { fill: #a99a82; }
.cp-bb2-rung[class*="-rung-"] .cp-bb2-rung-n { fill: var(--part); font-weight: 700; }
.cp-bb2-rung-part { font: 700 14px/1 Figtree, system-ui, sans-serif; letter-spacing: .14em; text-transform: uppercase; fill: var(--part); }
.cp-bb2-rung-root, .cp-bb2-fifth { font: italic 400 17px/1 var(--bb-serif); fill: #b8a98f; }
.cp-bb2-fifth { fill: var(--bb-gold); opacity: 0; transition: opacity .3s; }
.cp-bb2-note { fill: var(--part); }
.cp-bb2-wave { fill: none; stroke: var(--part); stroke-width: 2.5; stroke-linecap: round; opacity: 0; }
.cp-bb2-spark circle { fill: var(--bb-gold); opacity: .08; } .cp-bb2-spark path { fill: var(--bb-gold); opacity: .3; }
[data-ringing] .cp-bb2-wave { opacity: 1; }
[data-ringing] .cp-bb2-fifth { opacity: 1; }
[data-ringing] .cp-bb2-spark circle { opacity: .35; } [data-ringing] .cp-bb2-spark path { opacity: 1; }
:root[data-skin="game"] body.s-arcade :is(.cp-bb2-rung-line, .cp-bb2-note) { filter: drop-shadow(0 0 6px var(--part)); }
:root[data-skin="game"] body.s-arcade .cp-bb2-window { padding-top: 40px; border-radius: 0; background: var(--bb-night); box-shadow: inset 0 0 0 2px #a99bff, inset 0 0 0 8px var(--bb-night), inset 0 0 0 9px #ffe45c80, 6px 6px 0 var(--arc-shadow-c, #05030d); }
:root[data-skin="game"] body.s-arcade :is(.cp-bb2-window-sign, .cp-bb2-window-sub, .cp-bb2-rung-root, .cp-bb2-fifth) { font-family: "Stackapella Pixel", ui-monospace, monospace; font-style: normal; letter-spacing: .04em; font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade :is(.cp-bb2-window-sub, .cp-bb2-rung-root) { color: #cfc8ff; fill: #cfc8ff; font-size: 11px; }
:root[data-skin="game"] body.s-arcade .cp-bb2-fifth { font-size: 11px; }
:root[data-skin="game"] body.s-arcade .cp-bb2-rung-n { font-family: "Stackapella Pixel", ui-monospace, monospace; font-size: 16px; font-size-adjust: var(--arc-ex, none); }
@media (prefers-reduced-motion: no-preference) {
    [data-ringing] .cp-bb2-wave { animation: cp-bb2-out 1.1s ease-out infinite; transform-box: fill-box; transform-origin: left center; }
    [data-ringing] .cp-bb2-spark { animation: cp-bb2-glow 1.6s ease-in-out infinite; transform-box: fill-box; transform-origin: center; }
}
@keyframes cp-bb2-out { 0% { opacity: .2; transform: scale(.8); } 50% { opacity: 1; } 100% { opacity: .2; transform: scale(1.15); } }
@keyframes cp-bb2-glow { 50% { transform: scale(1.18); } }
/* One row while both fit; on the narrowest phones, and in game's wider Press Start labels, they wrap
   to two full rows rather than run past the edge. */
.cp-bb2-hero-ctas { flex-wrap: wrap; gap: 10px; }
.cp-bb2-hero-ctas > * { flex: 1 1 auto; justify-content: center; min-height: 48px; white-space: nowrap; }
.cp-bb2-hero-ctas .btn-primary { padding-inline: 16px; font-size: 15px; }
.cp-bb2-hero-ctas .cp-bb2-play { padding-inline: 6px 14px; gap: 6px; font-size: 15px; }
.cp-bb2-hero-ctas .cp-bb2-play-icon { width: 30px; height: 30px; }
@media (max-width: 419px) { .cp-bb2-hero-ctas .btn-primary svg { display: none; } }
.cp-bb2-quiet { font-size: 14px; }

/* Verse one: the tuner, a night band that is the instrument. */
.cp-bb2-verse { overflow-x: clip; padding-bottom: 40px; background: #1e1a16 radial-gradient(70% 60% at 50% 0%, #ffc88c10, transparent 70%); color: #f3ebdd; }
:root:not([data-theme$="-light"]) .cp-bb2-verse { background: #0b0907 radial-gradient(70% 60% at 50% 0%, #ffc88c0f, transparent 70%); }
:root[data-skin="game"] body.s-arcade .cp-bb2-verse { background: #120e24 radial-gradient(70% 60% at 50% 0%, #ff5fd214, transparent 70%); }
.cp-bb2-verse :is(.cp-bb2-h2, .cp-bb2-lede, .cp-bb2-tuner-try) { color: #f3ebdd; }
.cp-bb2-verse .cp-bb2-label, .cp-bb2-verse .s-cite a { color: var(--bb-gold); }
.cp-bb2-verse .cp-bb2-h2 em { color: var(--bb-tenor); }
.cp-bb2-verse .cp-bb2-play { color: #f3ebdd; border-color: #f3ebdd; }
.cp-bb2-verse .cp-bb2-play-icon { background: #c22131; }
.cp-bb2-verse :is(.cp-bb2-note-small, .cp-bb2-why) { color: #cfc4b3; }
.cp-bb2-why { margin-top: 14px; max-width: 64ch; font-size: 15.5px; line-height: 1.6; }
.cp-bb2-tuner-try { margin-top: 28px; max-width: 34ch; font-size: 20px; font-weight: 600; line-height: 1.45; }
.cp-bb2-tuner-row { display: grid; grid-template-columns: minmax(0, 1fr); gap: 18px; }
.cp-bb2-tuner-row .cp-bb2-ctas { margin-top: 18px; }
.cp-bb2-readout { display: flex; align-items: baseline; gap: 6px 12px; flex-wrap: wrap; color: #cfc4b3; font-size: 15px; }
.cp-bb2-readout b { font: 500 120px/.82 var(--bb-serif); letter-spacing: -0.03em; color: #f3ebdd; font-variant-numeric: lining-nums tabular-nums; transition: color .2s; }
[data-locked] .cp-bb2-readout b { color: var(--bb-lock); }
.cp-bb2-readout-game, .cp-bb2-stars, .cp-bb2-burst { display: none; }
.cp-bb2-rings { padding: 6px 14px; border-radius: 99px; background: var(--bb-lock); color: #0b0907; font-size: 14px; font-weight: 800; letter-spacing: .08em; text-transform: uppercase; }
/* The slider: its name and the third's cents over it, the track gold up to the thumb (green once it rings). */
.cp-bb2-slider { position: relative; display: block; margin-top: 44px; }
.cp-bb2-slider-head { display: flex; justify-content: space-between; align-items: baseline; gap: 12px; font-size: 13px; font-weight: 600; letter-spacing: .16em; text-transform: uppercase; color: #cfc4b3; }
.cp-bb2-cents { font: 700 24px/1 var(--bb-serif); letter-spacing: 0; text-transform: none; color: var(--bb-gold); white-space: nowrap; font-variant-numeric: lining-nums tabular-nums; }
[data-locked] .cp-bb2-cents { color: var(--bb-lock); }
.cp-bb2-slider { --bb-fill: var(--bb-gold); }
[data-locked] .cp-bb2-slider { --bb-fill: var(--bb-lock); }
.cp-bb2-slider input { -webkit-appearance: none; appearance: none; width: 100%; height: 44px; margin: 0; background: transparent; cursor: pointer; }
.cp-bb2-slider input::-webkit-slider-runnable-track { height: 6px; border-radius: 6px; background: linear-gradient(90deg, var(--bb-fill) calc(var(--bb-at, .75) * 100%), #f3ebdd38 0); }
.cp-bb2-slider input::-moz-range-track { height: 6px; border-radius: 6px; background: linear-gradient(90deg, var(--bb-fill) calc(var(--bb-at, .75) * 100%), #f3ebdd38 0); }
.cp-bb2-slider input::-webkit-slider-thumb { -webkit-appearance: none; width: 22px; height: 22px; margin-top: -8px; border: 0; border-radius: 99px; background: var(--bb-fill); box-shadow: 0 0 0 4px #1e1a16; }
.cp-bb2-slider input::-moz-range-thumb { width: 22px; height: 22px; border: 0; border-radius: 99px; background: var(--bb-fill); box-shadow: 0 0 0 4px #1e1a16; }
.cp-bb2-ticks { position: relative; height: 40px; font-size: 13px; color: #cfc4b3; font-variant-numeric: tabular-nums; }
.cp-bb2-ticks span { position: absolute; top: 0; translate: -50% 0; display: grid; justify-items: center; line-height: 1.3; }
.cp-bb2-ticks b { font-size: 11.5px; letter-spacing: .14em; text-transform: uppercase; }
.cp-bb2-tick-low { left: 11px; } .cp-bb2-tick-high { left: calc(100% - 11px); } .cp-bb2-tick-ring { left: calc(11px + (100% - 22px) * .4); color: var(--bb-lock); } .cp-bb2-tick-piano { left: calc(11px + (100% - 22px) * .75); }
.cp-bb2-beatwave { display: block; width: 100%; height: 160px; margin-top: 8px; }
.cp-bb2-beatwave path { fill: none; stroke: #e2735e; stroke-width: 1.6; vector-effect: non-scaling-stroke; }
[data-locked] .cp-bb2-beatwave path { stroke: var(--bb-lock); }
.cp-bb2-verse-end { padding-top: 6px; }
/* Game: a HUD readout, a three-star lock meter, and RING! when it locks. */
:root[data-skin="game"] body.s-arcade .cp-bb2-readout-game { display: inline; font: 400 14px/1 "Stackapella Pixel", ui-monospace, monospace; color: #ffe45c; }
:root[data-skin="game"] body.s-arcade .cp-bb2-readout b { font: 400 clamp(34px, 6vw, 48px)/1 "Stackapella Pixel", ui-monospace, monospace; color: #ffe45c; text-shadow: 0 0 16px #ffe45c; }
:root[data-skin="game"] body.s-arcade :is(.cp-bb2-readout-unit, .cp-bb2-rings) { display: none; }
:root[data-skin="game"] body.s-arcade .cp-bb2-stars { display: flex; gap: 8px; }
.cp-bb2-stars span { width: 34px; height: 34px; background: #ffffff24; clip-path: polygon(50% 0, 61% 36%, 100% 38%, 69% 61%, 80% 100%, 50% 77%, 20% 100%, 31% 61%, 0 38%, 39% 36%); transition: background .2s; }
