:root[data-skin="game"] body.s-arcade :is(.cp-bb2-cents, .cp-bb2-slider-head) { font-family: "Stackapella Pixel", ui-monospace, monospace; font-size: 11px; letter-spacing: .04em; font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade .cp-bb2-slider input::-webkit-slider-thumb { border-radius: 0; box-shadow: 0 0 0 4px #120e24, 0 0 14px 4px var(--bb-fill); }
:root[data-skin="game"] body.s-arcade .cp-bb2-beatwave path { stroke: #ff8a5c; } :root[data-skin="game"] body.s-arcade [data-locked] .cp-bb2-beatwave path { stroke: #4cf0b0; filter: drop-shadow(0 0 4px #4cf0b0); }

/* The chorus: the cornerstone chord, its seventh gliding from the piano's line onto rung 7, its cents
