.cp-bb2-glide-n { font: 700 clamp(84px, 13vw, 168px)/.85 var(--bb-serif); letter-spacing: -0.03em; color: var(--bb-ink); font-variant-numeric: lining-nums tabular-nums; }
.cp-bb2-glide-cap { margin-top: 12px; padding-bottom: 14px; border-bottom: 1px solid color-mix(in srgb, var(--bb-ink) 18%, transparent); font-size: 15px; line-height: 1.45; color: var(--bb-muted); }
