@keyframes cp-bb2-later { 0%, 99.9% { visibility: hidden; } 100% { visibility: visible; } }
@keyframes cp-bb2-sooner { 0%, 99.9% { visibility: visible; } 100% { visibility: hidden; } }
:root[data-skin="game"] body.s-arcade .cp-bb2-glide-n { font: 400 clamp(36px, 6vw, 60px)/1 "Stackapella Pixel", ui-monospace, monospace; color: #ffe45c; text-shadow: 0 0 16px #ffe45c; }
.cp-bb2-glide svg { display: block; width: 100%; max-width: 560px; height: auto; margin: 18px 0 0 auto; overflow: visible; }
.cp-bb2-piano-line { stroke: var(--bb-muted); stroke-width: 2; stroke-dasharray: 6 8; }
.cp-bb2-piano-n { font: 700 13px/1 Figtree, system-ui, sans-serif; letter-spacing: .14em; text-transform: uppercase; fill: var(--bb-muted); text-anchor: end; }
