@media (prefers-reduced-motion: reduce) { [data-gliding] .cp-bb2-glider { animation-timing-function: steps(1, end); } }
@media (max-width: 899px) { .cp-bb2-glide :is(.cp-bb2-rung-part, .cp-bb2-piano-n) { font-size: 19px; } .cp-bb2-glide .cp-bb2-rung-n { font-size: 34px; } }
.cp-bb2-margin { margin-top: 44px; padding-top: 26px; border-top: 1px solid color-mix(in srgb, var(--bb-ink) 18%, transparent); max-width: 52rem; }
.cp-bb2-margin p { font-family: var(--bb-serif); font-style: italic; font-size: clamp(20px, 2.4vw, 28px); line-height: 1.45; }

/* The bridge: whose sound this is, a row a year, the notes beside their years, and 1941 to 1963 on black. */
.cp-bb2-bridge { overflow-x: clip; background: color-mix(in srgb, var(--bb-ink) 5%, var(--bb-paper)); }
.cp-bb2-timeline { display: grid; margin-top: 40px; border-top: 2px solid var(--bb-ink); }
.cp-bb2-row { display: grid; grid-template-columns: minmax(0, 1fr); gap: 10px; padding: 28px 0; border-top: 1px solid color-mix(in srgb, var(--bb-ink) 14%, transparent); }
.cp-bb2-timeline > .cp-bb2-row:first-child { border-top: 0; }
