:root[data-skin="game"] body.s-arcade .cp-bb2-year { font-family: "Stackapella Pixel", ui-monospace, monospace; font-size: 18px; color: #ffe45c; font-size-adjust: var(--arc-ex, none); }
.cp-bb2-entry { font-size: 17px; line-height: 1.6; }
.cp-bb2-asides { display: grid; gap: 14px; margin-top: 8px; }
.cp-bb2-asides p { position: relative; padding-left: 20px; font-family: var(--bb-serif); font-style: italic; font-size: 17px; line-height: 1.5; color: var(--bb-muted); }
.cp-bb2-asides p::before { content: "✦" / ""; position: absolute; left: 0; top: 3px; font-size: 11px; font-style: normal; color: var(--bb-ink); }
/* 1941 to 1963: the span you scroll through, on black from edge to edge, its years in gold. */
.cp-bb2-span { --bb-span: #15110e; position: relative; margin: 26px 0 0; padding: 72px 0 52px; color: #f3ebdd; background: var(--bb-span); box-shadow: 0 0 0 100vmax var(--bb-span); clip-path: inset(0 -100vmax); }
