.cp-bb2-bar-line { display: flex; align-items: center; justify-content: center; gap: 16px; margin-top: 18px; font-size: 13px; font-weight: 700; letter-spacing: .2em; text-transform: uppercase; color: #f3ebdd; text-wrap: balance; }
.cp-bb2-bar-line::before, .cp-bb2-bar-line::after { content: ""; flex: 0 1 56px; min-width: 20px; height: 2px; background: var(--bb-gold); }
