.cp-bb2-span .cp-bb2-year { color: var(--bb-gold); }
.cp-bb2-span .cp-bb2-entry { color: #f3ebdd; }
.cp-bb2-span .s-cite a { color: var(--bb-gold); }
.cp-bb2-span + .cp-bb2-row { border-top: 0; }
.cp-bb2-pull { grid-column: 1 / -1; margin: 22px 0 4px; padding-top: 28px; border-top: 1px solid color-mix(in srgb, var(--bb-ink) 14%, transparent); }
.cp-bb2-pull p { max-width: 22ch; font-family: var(--bb-serif); font-style: italic; font-size: clamp(32px, 5vw, 60px); line-height: 1.1; letter-spacing: -0.01em; color: var(--bb-red); text-wrap: balance; }
:root[data-skin="game"] body.s-arcade .cp-bb2-pull p { font-family: var(--a-display); font-style: normal; text-transform: uppercase; color: #ffe45c; text-shadow: 0 0 18px #ffe45c80; font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade .cp-bb2-bar-years { font-family: var(--a-display); font-weight: 400; text-transform: uppercase; color: #ff9dc4; text-shadow: 3px 3px 0 #8f0e52; font-size-adjust: var(--arc-ex, none); }

/* Verse two: the course's phrase, a line a part, and the parts as a list beside it to bring one forward. */
.cp-bb2-inside .cp-bb2-h2 em { color: var(--bb-lead); }
.cp-bb2-phrase { margin: 40px 0 0; padding-bottom: 16px; }
.cp-bb2-phrase-row { display: grid; grid-template-columns: minmax(0, 1fr); gap: 26px; }
.cp-bb2-phrase-plot { position: relative; height: 300px; margin-bottom: 44px; }
.cp-bb2-guide { stroke: color-mix(in srgb, var(--bb-ink) 12%, transparent); stroke-width: 1; vector-effect: non-scaling-stroke; }
.cp-bb2-phrase-plot svg { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; }
.cp-bb2-vline { fill: none; stroke: var(--part); stroke-width: 3; stroke-linecap: round; stroke-linejoin: round; vector-effect: non-scaling-stroke; transition: opacity .3s, stroke-width .3s; }
.cp-bb2-vline.cp-bb2-v-lead { stroke-width: 6; }
.cp-bb2-vline.cp-bb2-solo { stroke-width: 7; } .cp-bb2-dim { opacity: .2; }
:root[data-skin="game"] body.s-arcade .cp-bb2-vline { filter: drop-shadow(0 0 5px var(--part)); }
.cp-bb2-seats { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 4px 18px; align-content: start; }
.cp-bb2-seat { display: flex; align-items: center; justify-content: space-between; gap: 10px; min-height: 46px; padding: 0 4px; border: 0; border-bottom: 2px solid transparent; background: transparent; color: var(--part); font: 700 18px/1 Figtree, system-ui, sans-serif; white-space: nowrap; text-align: start; cursor: pointer; }
.cp-bb2-seat::after { content: ""; flex: none; border-style: solid; border-width: 5px 0 5px 8px; border-color: transparent transparent transparent currentColor; }
.cp-bb2-seat:hover { background: color-mix(in srgb, var(--part) 8%, transparent); }
.cp-bb2-seat[aria-pressed="true"] { border-bottom-color: var(--part); }
.cp-bb2-seat[aria-pressed="true"]::after { width: 9px; height: 9px; border: 0; background: currentColor; }
.cp-bb2-seat-all { --part: var(--bb-red); grid-column: 1 / -1; }
:root[data-skin="game"] body.s-arcade .cp-bb2-seat { font-family: "Stackapella Pixel", ui-monospace, monospace; font-size: 11px; font-size-adjust: var(--arc-ex, none); }
.cp-bb2-head { position: absolute; top: -10px; bottom: -6px; left: 0; width: 2px; background: var(--bb-red); opacity: 0; pointer-events: none; }
@media (prefers-reduced-motion: no-preference) { [data-playing] .cp-bb2-head { opacity: 1; animation: cp-bb2-head var(--bb-len, 8s) linear both; } }
@keyframes cp-bb2-head { from { left: 0; } to { left: 100%; } }
.cp-bb2-lyric { position: absolute; left: 0; right: 0; bottom: -40px; display: flex; gap: 8px; }
.cp-bb2-lyric span { flex-basis: 0; min-width: max-content; font-family: var(--bb-serif); font-style: italic; font-size: 18px; color: var(--bb-muted); }
.cp-bb2-job { min-height: 1.6em; margin-top: 16px; font-size: 17px; font-weight: 600; line-height: 1.5; }

/* Tonight's bill: a framed playbill, its head centred, the acts in a ruled grid, admission at its foot. */
.cp-bb2-bill { max-width: 980px; margin-inline: auto; padding: 8px; border: 1px solid var(--bb-ink); background: var(--bb-card); box-shadow: inset 0 0 0 5px var(--bb-card), inset 0 0 0 6.5px var(--bb-ink), 0 36px 60px -36px #00000059; text-align: center; }
.cp-bb2-bill-head { padding: clamp(36px, 7vw, 60px) clamp(16px, 5vw, 48px) clamp(32px, 6vw, 48px); }
.cp-bb2-presents { font-size: 12px; font-weight: 700; letter-spacing: .3em; text-transform: uppercase; color: var(--bb-muted); }
.cp-bb2-bill-head .cp-bb2-label { margin-top: 10px; }
.cp-bb2-bill .cp-bb2-h2 { margin-inline: auto; max-width: 15ch; font-size: clamp(38px, 6vw, 72px); }
.cp-bb2-bill .cp-bb2-h2 em { color: var(--bb-ink); }
.cp-bb2-promises { display: grid; gap: 8px; max-width: 46ch; text-wrap: balance; margin: 24px auto 0; font-family: var(--bb-serif); font-style: italic; font-size: 19px; line-height: 1.45; color: var(--bb-muted); }
.cp-bb2-acts { display: grid; border-top: 2px solid var(--bb-ink); }
.cp-bb2-act { padding: 30px clamp(16px, 4vw, 44px); border-bottom: 2px solid var(--bb-ink); }
.cp-bb2-act summary { display: grid; justify-items: center; gap: 6px; list-style: none; cursor: pointer; }
.cp-bb2-act summary::-webkit-details-marker { display: none; }
.cp-bb2-act-n { font-size: 12px; font-weight: 700; letter-spacing: .24em; text-transform: uppercase; color: var(--bb-red); }
.cp-bb2-act h3 { font-family: var(--bb-serif); font-size: clamp(30px, 4vw, 40px); font-weight: 700; line-height: 1.1; }
:root[data-skin="game"] body.s-arcade .cp-bb2-act h3 { font-family: var(--a-display); font-weight: 400; text-transform: uppercase; font-size-adjust: var(--arc-ex, none); }
.cp-bb2-act-more { font-size: 14px; font-weight: 700; color: var(--bb-red); }
.cp-bb2-act-more::after { content: " ▸"; }
.cp-bb2-act[open] .cp-bb2-act-more { display: none; }
.cp-bb2-turns { display: grid; gap: 2px; margin-top: 18px; }
.cp-bb2-turns li { display: flex; align-items: baseline; gap: 10px; padding: 5px 0; font-size: 16.5px; text-align: start; }
.cp-bb2-seatdot { flex: none; align-self: center; width: 9px; height: 9px; border-radius: 99px; border: 1.5px solid var(--bb-ink); }
.cp-bb2-seatdot[class*="cp-bb2-v-"] { border-color: var(--part); background: var(--part); }
.cp-bb2-dots { flex: 1; min-width: 24px; border-bottom: 2px dotted color-mix(in srgb, var(--bb-ink) 35%, transparent); translate: 0 -4px; }
.cp-bb2-no { flex: none; font-size: 13px; font-weight: 600; letter-spacing: .06em; color: var(--bb-muted); font-variant-numeric: tabular-nums; }
.cp-bb2-free { flex: none; font-size: 14px; font-weight: 800; color: var(--bb-red) !important; text-decoration: none !important; }
.cp-bb2-free::after { content: " ▸"; }
.cp-bb2-bill-foot { padding: 16px 12px 10px; font-size: 12px; font-weight: 700; letter-spacing: .24em; text-transform: uppercase; color: var(--bb-muted); text-wrap: balance; }
/* Game: the playbill is a framed panel, the acts stage tiles. */
:root[data-skin="game"] body.s-arcade .cp-bb2-bill { border: 2px solid #ffe45c; box-shadow: 6px 6px 0 var(--arc-shadow-c, #05030d); }
:root[data-skin="game"] body.s-arcade .cp-bb2-bill .cp-bb2-h2 em { color: var(--bb-red); }
:root[data-skin="game"] body.s-arcade :is(.cp-bb2-presents, .cp-bb2-bill-foot) { font-family: "Stackapella Pixel", ui-monospace, monospace; font-size: 10px; letter-spacing: .06em; font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade .cp-bb2-acts { gap: 14px; padding: 6px; border-top: 0; }
:root[data-skin="game"] body.s-arcade .cp-bb2-act { padding: 20px 18px; border: 2px solid #a99bff; background: #120e24; box-shadow: 0 0 26px -12px #a99bff; }
:root[data-skin="game"] body.s-arcade .cp-bb2-dots { border-color: #ffffff2e; }
:root[data-skin="game"] body.s-arcade .cp-bb2-seatdot { border-radius: 0; }

/* What the app hears: the readout, and a held note on a meter just above where it rings. */
.cp-bb2-hears { display: grid; grid-template-columns: minmax(0, 1fr); gap: 36px; align-items: center; }
.cp-bb2-big { margin-top: 14px; font: 200 clamp(44px, 7vw, 84px)/1.02 Figtree, system-ui, sans-serif; letter-spacing: -0.03em; color: var(--bb-ink); text-wrap: balance; }
:root[data-skin="game"] body.s-arcade .cp-bb2-big { font-family: "Stackapella Pixel", ui-monospace, monospace; font-size: clamp(18px, 3.4vw, 34px); line-height: 1.5; color: #4cf0b0; text-shadow: 0 0 14px #4cf0b0; font-size-adjust: var(--arc-ex, none); }
.cp-bb2-dial { margin: 0; padding: clamp(20px, 4vw, 30px); border-radius: 18px; background: var(--bb-night); color: var(--bb-night-ink); }
.cp-bb2-dial-top { display: flex; justify-content: space-between; gap: 12px; font-size: 12.5px; font-weight: 600; letter-spacing: .18em; text-transform: uppercase; color: var(--bb-night-muted); }
.cp-bb2-dial-top b { color: var(--bb-gold); font-weight: 800; }
.cp-bb2-dial-scale { position: relative; margin: 44px 4px 0; }
.cp-bb2-dial svg { display: block; width: 100%; height: 72px; overflow: visible; }
.cp-bb2-dial-band { fill: color-mix(in srgb, var(--bb-lock) 22%, transparent); stroke: var(--bb-lock); stroke-width: 1.5; vector-effect: non-scaling-stroke; }
.cp-bb2-dial-pure { stroke: var(--bb-lock); stroke-width: 2; vector-effect: non-scaling-stroke; }
.cp-bb2-dial-tick { stroke: #f3ebdd59; stroke-width: 1.5; vector-effect: non-scaling-stroke; }
.cp-bb2-dial-mark { stroke: #e2735e; stroke-width: 4; vector-effect: non-scaling-stroke; }
.cp-bb2-dial-pill { position: absolute; bottom: 100%; translate: -50% -2px; padding: 5px 9px; border-radius: 99px; background: #e2735e; color: #1e1915; font-size: 14px; font-weight: 800; line-height: 1; white-space: nowrap; font-variant-numeric: lining-nums tabular-nums; }
.cp-bb2-dial-ends { display: flex; justify-content: space-between; align-items: baseline; margin-top: 10px; font-size: 13px; letter-spacing: .06em; color: var(--bb-night-muted); font-variant-numeric: tabular-nums; }
.cp-bb2-dial-ends b { font-size: 12.5px; font-weight: 800; letter-spacing: .18em; text-transform: uppercase; color: var(--bb-lock); }
.cp-bb2-dial-fall { margin-top: 18px; padding-top: 18px; border-top: 1px solid #f3ebdd24; font: italic 400 28px/1.2 var(--bb-serif); color: var(--bb-gold); }
.cp-bb2-dial-fall span { font-style: normal; }
:root[data-skin="game"] body.s-arcade .cp-bb2-dial { border-radius: 0; box-shadow: inset 0 0 0 2px #4cf0b0, 6px 6px 0 var(--arc-shadow-c, #05030d); }
:root[data-skin="game"] body.s-arcade :is(.cp-bb2-dial-top, .cp-bb2-dial-fall, .cp-bb2-dial-ends, .cp-bb2-dial-pill) { font-family: "Stackapella Pixel", ui-monospace, monospace; font-style: normal; font-size: 11px; letter-spacing: .04em; font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade .cp-bb2-dial-fall { font-size: 14px; }

/* The house rules: a green sign with a gold double frame and gold lettering. */
.cp-bb2-sign { padding: clamp(48px, 8vw, 64px) clamp(26px, 6vw, 64px) clamp(40px, 7vw, 56px); border-radius: 8px; background: var(--bb-sign); color: #f3ebdd; text-align: center;
    box-shadow: inset 0 0 0 10px var(--bb-sign), inset 0 0 0 12px var(--bb-gold), inset 0 0 0 17px var(--bb-sign), inset 0 0 0 18px color-mix(in srgb, var(--bb-gold) 55%, transparent); }
.cp-bb2-sign .cp-bb2-label { color: var(--bb-gold); }
.cp-bb2-sign .cp-bb2-h2 { color: var(--bb-gold); text-shadow: .035em .035em 0 #0d1d15; }
.cp-bb2-rules-grid { display: grid; grid-template-columns: minmax(0, 1fr); gap: 28px; margin-top: 36px; text-align: start; }
.cp-bb2-rules h3 { margin-top: 26px; font-size: 12.5px; font-weight: 800; letter-spacing: .18em; text-transform: uppercase; color: var(--bb-gold); }
.cp-bb2-rules h3:first-child { margin-top: 0; }
.cp-bb2-rules-grid p { margin-top: 10px; max-width: 52ch; font-size: 16.5px; line-height: 1.6; }
.cp-bb2-safety { display: grid; gap: 14px; margin-top: 12px; font-size: 16.5px; line-height: 1.55; }
.cp-bb2-safety li { display: grid; grid-template-columns: 40px minmax(0, 1fr); align-items: baseline; }
.cp-bb2-safety-n { font: 700 22px/1 var(--bb-serif); color: var(--bb-gold); }
:root[data-skin="game"] body.s-arcade .cp-bb2-sign { border-radius: 0; box-shadow: inset 0 0 0 2px #4cf0b0, inset 0 0 0 8px var(--bb-sign), inset 0 0 0 9px #ffe45c80, 6px 6px 0 var(--arc-shadow-c, #05030d); }
:root[data-skin="game"] body.s-arcade .cp-bb2-sign .cp-bb2-h2 { text-shadow: 3px 3px 0 #8f0e52; }
:root[data-skin="game"] body.s-arcade :is(.cp-bb2-rules h3, .cp-bb2-safety-n) { font-family: "Stackapella Pixel", ui-monospace, monospace; font-size: 10px; letter-spacing: .06em; font-size-adjust: var(--arc-ex, none); }

/* Questions: the heading at left, the answers under a heavy rule. */
.cp-bb2-fine { display: grid; grid-template-columns: minmax(0, 1fr); gap: 18px; padding-bottom: clamp(64px, 9vw, 104px); }
.cp-bb2 .cp-bb2-fine .cp-faq { margin-top: 0; max-width: none; border-top: 2px solid var(--bb-ink); }
.cp-bb2 .cp-faq summary, .cp-bb2 .cp-faq p { color: var(--bb-ink); }

/* The tag: the finale on a night stage, its headline in gold. */
.cp-bb2-tag { background: #160d0b radial-gradient(70% 90% at 50% 100%, #3a1418, #120c0a 70%); color: #f3ebdd; }
:root:not([data-theme$="-light"]):not([data-skin="game"]) .cp-bb2-tag { background: #0b0907 radial-gradient(70% 90% at 50% 100%, #2a1210, #0b0907 70%); }
:root[data-skin="game"] body.s-arcade .cp-bb2-tag { background: #0b0a14 radial-gradient(70% 90% at 50% 100%, color-mix(in srgb, #ff5fd2 22%, #0b0a14), #0b0a14 70%); }
.cp-bb2-tag-in { display: grid; justify-items: center; padding-bottom: clamp(64px, 9vw, 104px); text-align: center; }
.cp-bb2-tag .cp-bb2-lede { color: #f3ebdd; }
.cp-bb2-tag .cp-bb2-h2 { color: var(--bb-gold); text-shadow: .035em .035em 0 var(--bb-gold-deep); }
.cp-bb2-tag .cp-bb2-label { color: var(--bb-gold); }
.cp-bb2-tag .cp-bb2-lede { margin-inline: auto; }
.cp-bb2-tag .cp-bb2-play { color: #f3ebdd; border-color: #f3ebdd; }
.cp-bb2-tag .cp-bb2-soon { color: #cfc4b3; }
.cp-bb2-swipe { width: 100%; max-width: 896px; height: auto; margin-top: 44px; overflow: visible; }
.cp-bb2-sw { fill: none; stroke: var(--part); stroke-width: 6; stroke-linecap: round; }
.cp-bb2-sw.cp-bb2-v-baritone { stroke-width: 8; }
.cp-bb2-sw-n { font: 700 16px/1 Figtree, system-ui, sans-serif; letter-spacing: .12em; text-transform: uppercase; fill: var(--part); }
.cp-bb2-sw-word { font-family: var(--bb-serif); font-style: italic; font-size: 46px; fill: #f3ebdd; text-anchor: middle; }
/* On a phone the drawing is half size: the parts' names grow to stay readable beside their lines. */
@media (max-width: 599px) { .cp-bb2-sw-n { font-size: 21px; letter-spacing: .04em; } }
.cp-bb2-sw-spark { opacity: 0; }
[data-swiping] .cp-bb2-sw-spark { animation: cp-bb2-land 2.3s 3.3s both; }
@keyframes cp-bb2-land { from { opacity: 0; } 15%, 100% { opacity: 1; } }
.cp-bb2-tag-ctas { margin-top: 30px; }
.cp-bb2-tag-ctas > * { min-height: 56px; }
.cp-bb2-sw-head { stroke: #f3ebdd; stroke-width: 2; opacity: 0; }
@media (prefers-reduced-motion: no-preference) { [data-swiping] .cp-bb2-sw-head { opacity: 1; animation: cp-bb2-swipe 5.6s linear both; } }
@keyframes cp-bb2-swipe { from { transform: translateX(0); } to { transform: translateX(381px); } }
.cp-bb2-tag .cp-bb2-cta { min-height: 56px; padding-inline: 30px; background: #f3ebdd; color: #1e1a16; }
:root[data-skin="game"] body.s-arcade .cp-bb2-tag .cp-bb2-h2 { color: #ffe45c; text-shadow: 3px 3px 0 #8f0e52; }
:root[data-skin="game"] body.s-arcade .cp-bb2-tag .cp-bb2-cta { background: #ff5fd2; color: #1a0414; }

/* Game: the serious skin's serif italics become plain Figtree in lavender. */
:root[data-skin="game"] body.s-arcade :is(.cp-bb2-margin p, .cp-bb2-asides p, .cp-bb2-promises, .cp-bb2-lyric span, .cp-bb2-sw-word) { font-family: Figtree, system-ui, sans-serif; font-style: normal; font-weight: 500; color: #cfc8ff; fill: #cfc8ff; font-size-adjust: var(--arc-ex, none); }
/* Game light: the night grounds stay night, so their gold and words keep their dark-ground colours. */
:root[data-skin="game"][data-theme$="-light"] body.s-arcade .cp-bb2-span .cp-bb2-year { color: #ffe45c; }
:root[data-skin="game"][data-theme$="-light"] body.s-arcade .cp-bb2-span .cp-bb2-bar-years { color: #ff9dc4; }
:root[data-skin="game"][data-theme$="-light"] body.s-arcade .cp-bb2-bill { border-color: var(--arc-yellow, #7f5c00); }

@media (min-width: 900px) {
    .cp-bb2-intro { padding: 34px 0 88px; }
    .cp-bb2-intro-grid { grid-template-columns: minmax(0, 6fr) minmax(0, 5fr); gap: 56px; }
    .cp-bb2-ladder { justify-self: end; width: 100%; max-width: 500px; }
    .cp-bb2-hero-ctas { flex-wrap: wrap; gap: 14px; }
    .cp-bb2-hero-ctas > * { flex: none; min-height: 52px; }
    .cp-bb2-hero-ctas .btn-primary { padding-inline: revert-layer; font-size: revert-layer; }
    .cp-bb2-hero-ctas .cp-bb2-play { padding-inline: 8px 22px; gap: 12px; }
    .cp-bb2-hero-ctas .cp-bb2-play-icon { width: 38px; height: 38px; }
    .cp-bb2-readout b { font-size: 220px; }
    .cp-bb2-tuner-row { grid-template-columns: minmax(0, 1fr) auto; align-items: center; gap: 48px; }
    .cp-bb2-meter { text-align: right; } .cp-bb2-readout, .cp-bb2-stars { justify-content: flex-end; }
    .cp-bb2-readout { flex-direction: column; align-items: flex-end; gap: 14px; }
    .cp-bb2-chorus-grid { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); grid-template-areas: "head fig" "play fig"; gap: 26px 64px; align-items: start; }
    .cp-bb2-chorus-head { grid-area: head; } .cp-bb2-glide { grid-area: fig; } .cp-bb2-chorus-play { grid-area: play; }
    .cp-bb2-row { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr) minmax(0, 1fr); gap: 40px; align-items: start; }
    .cp-bb2-row .cp-bb2-entry { grid-column: 2; }
    .cp-bb2-asides { grid-column: 3; margin-top: 0; }
    .cp-bb2-year { font-size: 68px; }
    .cp-bb2-span .cp-bb2-row { grid-template-columns: 240px minmax(0, 1fr) minmax(0, .5fr); }
    .cp-bb2-span .cp-bb2-year { font-size: 56px; }
    .cp-bb2-phrase-row { grid-template-columns: minmax(0, 1fr) 160px; gap: 32px; }
    .cp-bb2-seats { grid-template-columns: minmax(0, 1fr); gap: 4px; }
    .cp-bb2-acts { grid-template-columns: repeat(2, minmax(0, 1fr)); }
    .cp-bb2-act:nth-child(odd) { border-right: 2px solid var(--bb-ink); }
    .cp-bb2-hears { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 64px; }
    .cp-bb2-rules-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 56px; }
    .cp-bb2-fine { grid-template-columns: minmax(0, .8fr) minmax(0, 1.6fr); gap: 56px; align-items: start; }
}

/* Yodeling (site/courses/yodeling): Hillel's design of 2026-11-18 (course-designs/yodeling), a climb up a Swiss hiking
   trail (docs/course-pages-polish.md; the facts: docs/courses/yodel-love-letter.md). Register as altitude: chest voice
   (red, --yo-chest) on the valley floor and head voice (blue, --yo-head) above the treeline, always named as well as
   coloured. Yellow Swiss hiking signs for the units, the harder two with a mountain path's white-red-white tip; every
   section's label a trail marker (the yellow diamond) with the real place and height the climb has reached, from Gonten
   to the Säntis. Grounds: paper for the hero, the pack and the summit, warm for the chest sections, sky for the head
   ones, night for the two voices and the app. The site's serif for display (--yo-serif), the system monospace for the
   trail's small print. Calm light and dark, and game mode's arcade: the same pieces in neon on the night, square edges
   and hard shadows. Body and the shared lesson list below <main> take the page's ground (body[data-course]). Sounds:
   js/public/yodeling.js. */
body[data-course="yodeling"] { --yo-paper: #f3ede2; --yo-warm: #efe3cf; --yo-sky: #e3eaf3; --yo-ink: #1e1814; --yo-muted: #5e554c; --yo-line: rgb(30 24 20 / .16);
    --yo-chest: #b8152b; --yo-head: #1f5fa8; --yo-night: #1e1814; --yo-night-ink: #f3ede2; --yo-night-muted: #c9bfb2; --yo-night-chest: #ff8a7a; --yo-night-head: #8cc4ff;
    --yo-far: #bac7d4; --yo-near: #1e1814; --yo-snow: #f9f5ef; --yo-sign: #f2c230; --yo-sign-ink: #1e1814; --yo-pole: #6e5a45; --yo-card: rgb(255 255 255 / .55);
    --yo-serif: ui-serif, "Iowan Old Style", "Palatino Linotype", Palatino, Georgia, "Times New Roman", serif; --yo-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
    background: var(--yo-paper); }
:root:not([data-theme$="-light"]) body[data-course="yodeling"] { --yo-paper: #14171c; --yo-warm: #1c1814; --yo-sky: #121a26; --yo-ink: #efe6d6; --yo-muted: #bdb3a5; --yo-line: rgb(239 230 214 / .16);
    --yo-chest: #ff8a7a; --yo-head: #8cc4ff; --yo-night: #0b0d11; --yo-far: #2b3747; --yo-near: #06080b; --yo-snow: #c9d3de; --yo-pole: #8a7560; --yo-card: rgb(255 255 255 / .05); }
:root[data-skin="game"] body[data-course="yodeling"] { --yo-paper: #0b0820; --yo-warm: #170a24; --yo-sky: #0d1534; --yo-ink: #ede9ff; --yo-muted: #b8b2d8; --yo-line: rgb(237 233 255 / .2);
    --yo-chest: #ff5fd2; --yo-head: #3be7ff; --yo-night: #05040f; --yo-night-ink: #ede9ff; --yo-night-muted: #b8b2d8; --yo-night-chest: #ff5fd2; --yo-night-head: #3be7ff;
    --yo-far: #1d1450; --yo-near: #05040f; --yo-snow: #3be7ff; --yo-sign: #ffe45c; --yo-sign-ink: #14122b; --yo-pole: #3a3555; --yo-card: #120d33; }
:root[data-skin="game"][data-theme$="-light"] body[data-course="yodeling"] { --yo-paper: #eaf6ff; --yo-warm: #f6e6f1; --yo-sky: #d9f3ff; --yo-ink: #14122b; --yo-muted: #34305a; --yo-line: rgb(20 18 43 / .2);
    --yo-chest: #a1127a; --yo-head: #00708a; --yo-far: #9fd6ea; --yo-near: #14122b; --yo-snow: #ffffff; --yo-card: #ffffff; }
.cp-yo3 { --cp-a: var(--yo-chest); --cp-a-text: var(--yo-chest); --cp-line: var(--yo-line); --color-muted: var(--yo-muted); color: var(--yo-ink); background: var(--yo-paper); }
.cp-yo3 :is(.cp-yo3-chest) { color: var(--yo-chest); stroke: var(--yo-chest); }
.cp-yo3 :is(.cp-yo3-head) { color: var(--yo-head); stroke: var(--yo-head); }
.cp-yo3 svg text { stroke: none; }
.cp-yo3 a:not([class*="btn"]) { color: inherit; text-underline-offset: 3px; }
.cp-yo3 .s-cite a { padding: 0 2px; color: var(--yo-chest); text-decoration: none; }
.cp-yo3 :is(.cp-yo3-sky, .cp-yo3-night) .s-cite a { color: var(--yo-head); }

/* Grounds, met at hard seams. */
.cp-yo3-warm { background: var(--yo-warm); }
.cp-yo3-sky { background: var(--yo-sky); }
.cp-yo3-paper, .cp-yo3-hero, .cp-yo3-summit { background: var(--yo-paper); }
.cp-yo3-night { --yo-ink: var(--yo-night-ink); --yo-muted: var(--yo-night-muted); --yo-chest: var(--yo-night-chest); --yo-head: var(--yo-night-head); --yo-line: rgb(243 237 226 / .18); --yo-card: rgb(255 255 255 / .06);
    background: var(--yo-night); color: var(--yo-ink); }
.cp-yo3-sec { padding-block: clamp(52px, 6vw, 80px); }
:root[data-skin="game"] body.s-arcade .cp-yo3 :is(.cp-yo3-warm, .cp-yo3-sky, .cp-yo3-night) { box-shadow: inset 0 2px 0 var(--yo-line); }

/* Type: the site's serif for display, a mono for the trail's small print. */
.cp-yo3-h1 { margin-top: 18px; font: 900 clamp(48px, 16vw, 64px)/.88 var(--yo-serif); letter-spacing: -0.035em; text-wrap: balance; }
@media (min-width: 640px) { .cp-yo3-h1 { font-size: clamp(64px, 10vw, 140px); } }
.cp-yo3-h2 { margin-top: 14px; font: 800 clamp(36px, 5.6vw, 64px)/1.02 var(--yo-serif); letter-spacing: -0.02em; text-wrap: balance; }
.cp-yo3-h2-head { font-weight: 400; font-style: italic; letter-spacing: -0.01em; }
.cp-yo3-lede { margin-top: 18px; max-width: 58ch; font-size: 18px; line-height: 1.62; }
.cp-yo3-body { margin-top: 14px; max-width: 62ch; font-size: 16px; line-height: 1.62; }
.cp-yo3-small, .cp-yo3-quiet { margin-top: 10px; max-width: 62ch; font-size: 15px; line-height: 1.55; color: var(--yo-muted); }
.cp-yo3-kick { font-size: 12px; font-weight: 700; letter-spacing: .16em; text-transform: uppercase; color: var(--yo-chest); }
:root[data-skin="game"] body.s-arcade .cp-yo3 :is(.cp-yo3-h1, .cp-yo3-h2) { font-family: var(--a-display); font-weight: 400; font-style: normal; letter-spacing: .01em; text-transform: uppercase; max-width: 100%; overflow-wrap: anywhere; font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade .cp-yo3 .cp-yo3-h1 { font-size: clamp(38px, 7vw, 84px); line-height: 1.04; }
:root[data-skin="game"] body.s-arcade .cp-yo3 .cp-yo3-h2 { font-size: clamp(26px, 4vw, 44px); line-height: 1.12; }
:root[data-skin="game"] body.s-arcade .cp-yo3 :is(.cp-yo3-year, .cp-yo3-bignums b, .cp-yo3-pack h3) { font-family: var(--a-display); font-weight: 400; font-style: normal; font-size: 24px; line-height: 1.2; text-transform: uppercase; font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade .cp-yo3 :is(.cp-yo3-kick, .cp-yo3-alt, .cp-yo3-sign small, .cp-yo3-sign-n, .cp-yo3-board span, .cp-yo3-key, .cp-yo3-where, .cp-yo3-pano-lane, .cp-yo3-pano-note) { font-family: var(--a-hud); font-size: 10px; letter-spacing: .03em; font-size-adjust: var(--arc-ex, none); }

/* The trail marker: a yellow diamond, the section's name, and where the climb has got to. */
.cp-yo3-mark { display: flex; flex-wrap: wrap; align-items: center; gap: 6px 12px; }
.cp-yo3-mark-head .cp-yo3-kick { color: var(--yo-head); }
.cp-yo3-diamond { flex: none; width: 13px; height: 13px; rotate: 45deg; background: var(--yo-sign); outline: 1px solid rgb(30 24 20 / .3); }
.cp-yo3-alt { margin-inline-start: auto; font: 500 12.5px/1.3 var(--yo-mono); color: var(--yo-muted); }
.cp-yo3-mark:not(:has(.cp-yo3-kick)) .cp-yo3-alt { margin-inline-start: 0; }
h2.cp-yo3-mark { font-size: inherit; }

/* Buttons: the play pill (a red disc), the picks. */
.cp-yo3-ctas, .cp-yo3-btns { display: flex; flex-wrap: wrap; align-items: center; gap: 12px; margin-top: 26px; }
.cp-yo3-btns { margin-top: 16px; }
.cp-yo3-center { justify-content: center; }
.cp-yo3-play { display: inline-flex; align-items: center; gap: 10px; min-height: 50px; padding: 0 20px 0 5px; border-radius: 99px; border: 2px solid var(--yo-ink); background: transparent; color: var(--yo-ink); font: 700 16px/1 Figtree, system-ui, sans-serif; white-space: nowrap; cursor: pointer; }
.cp-yo3-play:hover { background: color-mix(in srgb, var(--yo-ink) 8%, transparent); }
.cp-yo3-play-icon { display: grid; place-items: center; flex: none; width: 38px; height: 38px; border-radius: 99px; background: #b8152b; }
.cp-yo3-play-icon::before { content: ""; margin-left: 3px; border-style: solid; border-width: 7px 0 7px 11px; border-color: transparent transparent transparent #fff; }
.cp-yo3-play[aria-pressed="true"] .cp-yo3-play-icon::before { margin: 0; width: 12px; height: 12px; border: 0; background: #fff; }
.cp-yo3-pick { min-height: 44px; padding: 0 18px; border-radius: 99px; border: 2px solid color-mix(in srgb, var(--yo-ink) 30%, transparent); background: transparent; color: var(--yo-ink); font: 700 15px/1 Figtree, system-ui, sans-serif; white-space: nowrap; cursor: pointer; }
.cp-yo3-pick[aria-pressed="true"] { background: var(--yo-ink); color: var(--yo-paper); border-color: var(--yo-ink); }
.cp-yo3-night .cp-yo3-pick[aria-pressed="true"] { color: var(--yo-night); }
.cp-yo3 :is(.cp-yo3-play, .cp-yo3-pick, .cp-yo3-sign, summary, input):focus-visible { outline: 3px solid var(--yo-head); outline-offset: 3px; }
:root[data-skin="game"] body.s-arcade .cp-yo3 .cp-yo3-play { border-radius: 0; border-color: var(--yo-head); color: var(--yo-head); font-family: var(--a-hud); font-size: 10px; box-shadow: 4px 4px 0 var(--arc-shadow-c); font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade .cp-yo3 .cp-yo3-play-icon { border-radius: 0; background: var(--yo-chest); }
:root[data-skin="game"] body.s-arcade .cp-yo3 .cp-yo3-pick { border-radius: 0; font-family: var(--a-hud); font-size: 10px; font-size-adjust: var(--arc-ex, none); }

/* The hero: the copy beside the signpost, the outcomes, then the panorama. */
.cp-yo3-hero-grid { display: grid; gap: 44px; padding-top: 24px; }
.cp-yo3-hero-copy .cp-yo3-mark { margin-top: 20px; }
.cp-yo3-hero .cp-yo3-lede { font-size: 19px; max-width: 34em; }
.cp-yo3-post { position: relative; width: 100%; max-width: 470px; padding-bottom: 6px; }
.cp-yo3-pole { position: absolute; left: 34px; top: -12px; bottom: -40px; width: 16px; border-radius: 2px; background: var(--yo-pole); }
.cp-yo3-board { position: relative; display: flex; flex-wrap: wrap; justify-content: space-between; align-items: baseline; gap: 4px 12px; width: 88%; padding: 12px 18px; border: 2px solid #1e1814; background: #fff; color: #1e1814; }
.cp-yo3-board b { font-size: 19px; font-weight: 800; }
.cp-yo3-board span { font: 500 13px/1.3 var(--yo-mono); }
.cp-yo3-signs { position: relative; display: grid; gap: 10px; margin-top: 10px; }
.cp-yo3-sign { position: relative; display: flex; justify-content: space-between; align-items: center; gap: 12px; min-height: 60px; padding: 11px 64px 11px 18px; background: var(--yo-sign); color: var(--yo-sign-ink);
    clip-path: polygon(0 0, calc(100% - 26px) 0, 100% 50%, calc(100% - 26px) 100%, 0 100%); text-decoration: none; }
.cp-yo3 a.cp-yo3-sign { color: var(--yo-sign-ink); }
a.cp-yo3-sign:hover { filter: brightness(1.05); }
.cp-yo3-sign small { display: block; margin-bottom: 4px; font-size: 11px; font-weight: 700; letter-spacing: .14em; text-transform: uppercase; }
.cp-yo3-sign b { font-size: 19px; font-weight: 800; line-height: 1.15; }
.cp-yo3-sign-n { font: 700 14px/1 Figtree, system-ui, sans-serif; white-space: nowrap; }
.cp-yo3-tip { position: absolute; top: 0; right: 0; bottom: 0; width: 40px; background: linear-gradient(#fff 0 33%, #b8152b 33% 67%, #fff 67%); }
.cp-yo3-key { position: relative; margin: 18px 0 0 64px; font: 400 12px/1.5 var(--yo-mono); color: var(--yo-muted); }
:root[data-skin="game"] body.s-arcade .cp-yo3 .cp-yo3-board { border-radius: 0; box-shadow: 4px 4px 0 var(--arc-shadow-c); }
:root[data-skin="game"] body.s-arcade .cp-yo3 .cp-yo3-sign b { font-family: var(--a-display); font-weight: 400; font-size: 15px; font-size-adjust: var(--arc-ex, none); }
.cp-yo3-outcomes-wrap { padding-top: clamp(40px, 5vw, 56px); }
.cp-yo3-outcomes { display: grid; gap: 12px 32px; margin-top: 14px; font-size: 16px; line-height: 1.5; counter-reset: yo3; }
.cp-yo3-outcomes li { display: flex; gap: 12px; counter-increment: yo3; }
.cp-yo3-outcomes li::before { content: counter(yo3, decimal-leading-zero); font: 500 13px/1.9 var(--yo-mono); color: var(--yo-chest); }
.cp-yo3-outcomes li:nth-child(even)::before { color: var(--yo-head); }

/* The panorama: two lines for the voices, the call drawn between them and its echoes. */
.cp-yo3-pano { position: relative; height: clamp(220px, 24vw, 320px); margin: 40px 0 0; background: linear-gradient(var(--yo-paper), var(--yo-sky) 40%); }
.cp-yo3-pano svg { position: absolute; inset: 0; display: block; width: 100%; height: 100%; }
.cp-yo3-far { fill: var(--yo-far); }
.cp-yo3-near { fill: var(--yo-near); }
.cp-yo3-snow { fill: var(--yo-snow); }
.cp-yo3-line { fill: none; stroke-width: 1.5; stroke-dasharray: 3 6; vector-effect: non-scaling-stroke; }
.cp-yo3-seg { fill: none; stroke-width: 6; stroke-linecap: square; vector-effect: non-scaling-stroke; }
.cp-yo3-echo-1 .cp-yo3-seg { stroke-width: 3.5; opacity: .5; }
.cp-yo3-echo-2 .cp-yo3-seg { stroke-width: 2.5; opacity: .28; }
.cp-yo3-pano-lane, .cp-yo3-pano-note { position: absolute; font-size: 12px; line-height: 1; white-space: nowrap; }
.cp-yo3-pano-lane { left: max(16px, calc((100% - 1200px) / 2 + 16px)); font-weight: 700; letter-spacing: .16em; text-transform: uppercase; translate: 0 -150%; }
.cp-yo3-pano-head { top: 22.5%; color: var(--yo-head); }
.cp-yo3-pano-chest { top: 47.5%; color: var(--yo-chest); }
.cp-yo3-pano-note { font-family: var(--yo-mono); }
.cp-yo3-pano-call { top: 9%; left: 26%; }
.cp-yo3-pano-echo { top: 15%; left: 60%; color: var(--yo-muted); }
@media (prefers-reduced-motion: no-preference) {
    [data-calling] .cp-yo3-seg { animation: cp-yo3-sound .14s ease-out var(--at) both; }
}
@keyframes cp-yo3-sound { from { opacity: 0; } }
:root[data-skin="game"] body.s-arcade .cp-yo3 .cp-yo3-seg { filter: drop-shadow(0 0 5px currentColor); }
:root[data-skin="game"] body.s-arcade .cp-yo3 .cp-yo3-far { stroke: var(--yo-head); stroke-width: 1.5; vector-effect: non-scaling-stroke; }

/* Two voices in one throat: the two demos as cards. */
.cp-yo3-cols { display: grid; gap: 4px 56px; }
.cp-yo3-demos { display: grid; gap: 20px; margin-top: 40px; }
.cp-yo3-demo { padding: 26px 24px; border-radius: 24px; background: var(--yo-card); border: 1px solid var(--yo-line); }
.cp-yo3-demo h3 { font: italic 400 26px/1.2 var(--yo-serif); }
:root[data-skin="game"] body.s-arcade .cp-yo3 .cp-yo3-demo { border-radius: 0; border: 2px solid var(--yo-head); box-shadow: 6px 6px 0 var(--arc-shadow-c); }
:root[data-skin="game"] body.s-arcade .cp-yo3 .cp-yo3-demo h3 { font-family: var(--a-display); font-style: normal; font-size: 18px; text-transform: uppercase; font-size-adjust: var(--arc-ex, none); }
.cp-yo3-leap { display: block; width: 100%; max-width: 420px; margin-top: 18px; overflow: visible; }
.cp-yo3-break { fill: none; stroke: var(--yo-muted); stroke-width: 1.5; stroke-dasharray: 3 5; }
.cp-yo3-break-n, .cp-yo3-bar-n { font: 600 12px/1 Figtree, system-ui, sans-serif; fill: var(--yo-muted); }
.cp-yo3-break-n { text-anchor: end; }
.cp-yo3-bar { stroke-width: 10; stroke-linecap: round; }
.cp-yo3-bar-n { font-weight: 800; letter-spacing: .12em; text-transform: uppercase; }
.cp-yo3-bar-n.cp-yo3-chest { fill: var(--yo-chest); }
.cp-yo3-top { stroke: var(--yo-chest); transition: stroke .15s; }
.cp-yo3-top-chest { fill: var(--yo-chest); }
.cp-yo3-top-head { fill: var(--yo-head); display: none; }
[data-top="head"] .cp-yo3-top { stroke: var(--yo-head); }
[data-top="head"] .cp-yo3-top-head { display: inline; }
[data-top="head"] .cp-yo3-top-chest { display: none; }
.cp-yo3-answer { min-height: 1.6em; margin-top: 14px; font-size: 16px; line-height: 1.5; }
.cp-yo3-bonus { display: none; }
:root[data-skin="game"] body.s-arcade .cp-yo3 .cp-yo3-bonus:not([hidden]) { display: inline; font-family: var(--a-hud); font-size: 10px; color: var(--yo-sign); font-size-adjust: var(--arc-ex, none); }
.cp-yo3-traces { display: block; width: 100%; max-width: 360px; margin-top: 12px; }
.cp-yo3-traces path { fill: none; stroke: var(--yo-line); stroke-width: 4; stroke-linejoin: round; }
.cp-yo3-traces[data-shown] path { stroke: var(--yo-ink); }
.cp-yo3-trace-n { font: 800 15px/1 Figtree, system-ui, sans-serif; fill: var(--yo-muted); }

/* Calls from alp to alp: the dates along a dashed trail, alternating sides. */
.cp-yo3-story { position: relative; display: grid; gap: 28px; margin-top: 40px; padding-inline-start: 34px; }
.cp-yo3-story::before { content: ""; position: absolute; top: 6px; bottom: 6px; left: 6px; border-left: 3px dashed color-mix(in srgb, var(--yo-ink) 32%, transparent); }
.cp-yo3-story > li { position: relative; }
.cp-yo3-story > li > .cp-yo3-diamond { position: absolute; top: 10px; left: -34px; }
.cp-yo3-year { font: 800 38px/1 var(--yo-serif); color: var(--yo-chest); }
.cp-yo3-story > li:nth-child(odd) .cp-yo3-year { font-weight: 400; font-style: italic; color: var(--yo-head); }
.cp-yo3-story > li > p:not(.cp-yo3-year) { margin-top: 8px; max-width: 46ch; font-size: 16px; line-height: 1.6; }
.cp-yo3-bignums { display: flex; flex-wrap: wrap; gap: 8px 32px; }
.cp-yo3-bignums b { display: block; font: 800 44px/1 var(--yo-serif); color: var(--yo-head); }
.cp-yo3-bignums span { font-size: 15px; color: var(--yo-muted); }

/* Not only the Alps: three places across, under a dashed line. */
.cp-yo3-world { display: grid; gap: 28px; margin-top: 32px; padding-top: 24px; border-top: 2px dashed color-mix(in srgb, var(--yo-head) 55%, transparent); }
.cp-yo3-world li > p:last-child { font: italic 400 20px/1.45 var(--yo-serif); }
:root[data-skin="game"] body.s-arcade .cp-yo3 :is(.cp-yo3-world li > p:last-child, .cp-yo3-big-line) { font-family: inherit; font-style: normal; font-size: 16px; line-height: 1.6; }
.cp-yo3-where { margin-bottom: 8px; font: 500 12.5px/1.4 var(--yo-mono); color: var(--yo-head); }

/* The alphorn's notes over the keys. */
.cp-yo3-horn-row { display: grid; gap: 28px; margin-top: 32px; }
.cp-yo3-horn { margin: 0; padding: 22px 20px 16px; border-radius: 24px; background: var(--yo-card); border: 1px solid var(--yo-line); }
.cp-yo3-horn svg { display: block; width: 100%; height: auto; margin-top: 12px; overflow: visible; }
.cp-yo3-horn text { font: 700 18px/1 Figtree, system-ui, sans-serif; text-anchor: middle; fill: var(--yo-ink); }
.cp-yo3-horn-axis, .cp-yo3-horn-tick { stroke: var(--yo-ink); stroke-width: 2; }
.cp-yo3-horn .cp-yo3-horn-key { font-size: 17px; fill: var(--yo-muted); }
.cp-yo3-horn .cp-yo3-horn-cents { font: 500 14px/1 var(--yo-mono); fill: var(--yo-muted); }
.cp-yo3-horn-note circle { fill: var(--yo-ink); }
.cp-yo3-horn-odd circle { fill: var(--yo-chest); }
.cp-yo3-horn-gap { stroke: var(--yo-chest); stroke-width: 2; stroke-dasharray: 3 4; }
.cp-yo3-horn .cp-yo3-horn-nokey { font: 500 14px/1 var(--yo-mono); fill: var(--yo-chest); }
@media (prefers-reduced-motion: no-preference) {
    [data-playing] .cp-yo3-horn-note circle { animation: cp-yo3-lit .7s calc(.3s + var(--i) * .7s) both; }
}
@keyframes cp-yo3-lit { 0%, 100% { fill: var(--yo-ink); } 10%, 80% { fill: var(--yo-head); } }
:root[data-skin="game"] body.s-arcade .cp-yo3 .cp-yo3-horn { border-radius: 0; border: 2px solid var(--yo-chest); box-shadow: 6px 6px 0 var(--arc-shadow-c); }

/* Wordless, by heart: the archive's number, and the call fading like an echo. */
.cp-yo3-heart { display: grid; gap: 32px; align-items: center; }
.cp-yo3-big { margin-top: 18px; font: 400 clamp(88px, 13vw, 190px)/.9 Figtree, system-ui, sans-serif; letter-spacing: -0.05em; color: var(--yo-head); }
.cp-yo3-big-line { margin-top: 14px; max-width: 26em; font: italic 400 22px/1.4 var(--yo-serif); }
.cp-yo3-loba { display: flex; flex-direction: column; gap: 2px; font: italic 400 clamp(60px, 7.6vw, 108px)/1 var(--yo-serif); color: var(--yo-head); }
.cp-yo3-loba span { padding-inline-start: calc(var(--i) * 12%); font-size: calc(1em * (1 - var(--i) * .2)); opacity: calc(1 - var(--i) * .26); }
:root[data-skin="game"] body.s-arcade .cp-yo3 :is(.cp-yo3-big, .cp-yo3-loba) { font-family: var(--a-display); font-style: normal; font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade .cp-yo3 .cp-yo3-loba { font-size: clamp(32px, 5vw, 64px); }

/* The trail: each unit a sign, then its card, each higher than the one before. */
.cp-yo3-trail { display: grid; gap: 22px; margin-top: 40px; }
.cp-yo3-trail .cp-yo3-sign { max-width: 340px; min-height: 52px; }
.cp-yo3-trail .cp-yo3-sign { flex-direction: column; align-items: flex-start; justify-content: center; gap: 4px; padding-inline-end: 52px; }
.cp-yo3-trail .cp-yo3-sign b { font-size: 12.5px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; white-space: nowrap; }
.cp-yo3-trail .cp-yo3-sign-n { font-size: 13px; }
.cp-yo3-unit { margin-top: 10px; padding: 22px 22px 24px; border-radius: 20px; background: var(--yo-card); border: 1px solid var(--yo-line); }
.cp-yo3-unit h3 { font: 800 24px/1.15 var(--yo-serif); }
.cp-yo3-lessons { display: grid; gap: 7px; margin-top: 14px; padding-inline-start: 1.3em; list-style: decimal; font-size: 15px; line-height: 1.45; }
.cp-yo3-lessons li::marker { color: var(--yo-muted); font-variant-numeric: tabular-nums; }
.cp-yo3-free { display: inline-flex; margin-inline-start: 8px; padding: 2px 9px; border-radius: 99px; font-size: 11px; font-weight: 800; letter-spacing: .08em; text-transform: uppercase; vertical-align: 1px; color: #fff; background: #1d7a43; text-decoration: none; }
.cp-yo3 a.cp-yo3-free { color: #fff; }
:root[data-skin="game"] body.s-arcade .cp-yo3 .cp-yo3-unit { border-radius: 0; border: 2px solid var(--yo-line); box-shadow: 4px 4px 0 var(--arc-shadow-c); }
:root[data-skin="game"] body.s-arcade .cp-yo3 .cp-yo3-unit h3 { font-family: var(--a-display); font-weight: 400; font-size: 17px; text-transform: uppercase; font-size-adjust: var(--arc-ex, none); }

/* Your flip: the steps, the siren card, singing it safely. */
.cp-yo3-flip { display: grid; gap: 36px; }
.cp-yo3-steps { display: grid; gap: 14px; margin-top: 22px; counter-reset: yo3s; }
.cp-yo3-steps li { display: grid; grid-template-columns: 34px minmax(0, 1fr); gap: 12px; font-size: 17px; line-height: 1.55; counter-increment: yo3s; }
.cp-yo3-steps li::before { content: counter(yo3s); display: grid; place-items: center; width: 30px; height: 30px; margin-top: -1px; background: var(--yo-sign); color: var(--yo-sign-ink); font: 800 14px/1 Figtree, system-ui, sans-serif; }
.cp-yo3-strip { position: relative; margin-top: 16px; border-radius: 14px; background: color-mix(in srgb, var(--yo-ink) 5%, transparent); }
.cp-yo3-strip svg { display: block; width: 100%; height: 170px; }
.cp-yo3-strip path { fill: none; stroke-width: 4; stroke-linecap: round; stroke-linejoin: round; vector-effect: non-scaling-stroke; }
.cp-yo3-strip .cp-yo3-break { stroke-width: 1.5; }
.cp-yo3-strip [data-yo-note] { position: absolute; right: 10px; bottom: calc(var(--brk, 50%) + 4px); font: 700 13px/1 var(--yo-mono); color: var(--yo-muted); }
.cp-yo3-legend { display: flex; gap: 18px; margin-top: 10px; font-size: 13px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; }
.cp-yo3-legend span::before { content: ""; display: inline-block; width: 18px; height: 4px; margin-inline-end: 8px; vertical-align: middle; background: currentColor; }
.cp-yo3-slider { display: grid; gap: 8px; margin-top: 16px; font-size: 14px; font-weight: 700; }
.cp-yo3-slider input { width: 100%; min-height: 44px; accent-color: var(--yo-head); }
.cp-yo3-rules { margin-top: 44px; padding: 22px 24px; border: 2px solid var(--yo-ink); background: var(--yo-card); }
.cp-yo3-rules ul { display: grid; gap: 8px 32px; margin-top: 12px; font-size: 16px; line-height: 1.5; }
.cp-yo3-rules li { display: flex; gap: 10px; }
.cp-yo3-rules li::before { content: ""; flex: none; width: 10px; height: 10px; margin-top: .45em; rotate: 45deg; background: var(--yo-sign); outline: 1px solid rgb(30 24 20 / .3); }

/* What the app listens for: the words beside two real screens. */
.cp-yo3-app { display: grid; gap: 40px; align-items: center; }
.cp-yo3-meter { display: flex; gap: 6px; margin-top: 16px; }
.cp-yo3-meter span { width: 26px; height: 8px; border: 1.5px solid var(--yo-head); }
.cp-yo3-meter .cp-yo3-meter-on { background: var(--yo-head); }
.cp-yo3-shots { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 16px; align-items: start; }
.cp-yo3-shots > :nth-child(2) { margin-top: 48px; }
.cp-yo3-shots .s-appshot img { border-color: var(--yo-line); }

/* Your pack and the questions. */
.cp-yo3-pack { display: grid; gap: 32px; margin-top: 28px; }
.cp-yo3-pack h3 { font: 800 24px/1.2 var(--yo-serif); }
.cp-yo3-dash { display: grid; gap: 10px; margin-top: 14px; font-size: 16px; line-height: 1.5; }
.cp-yo3-dash li { display: flex; gap: 12px; }
.cp-yo3-dash li::before { content: ""; flex: none; width: 14px; height: 2px; margin-top: .75em; background: var(--yo-chest); }
.cp-yo3-songs { display: grid; gap: 12px; margin-top: 14px; }
.cp-yo3-songs li { display: grid; gap: 2px; padding-bottom: 12px; border-bottom: 1px solid var(--yo-line); }
.cp-yo3-songs b { font-size: 17px; }
.cp-yo3-songs span { font-size: 14.5px; color: var(--yo-muted); }
.cp-yo3-fine { display: grid; gap: 8px; margin-top: clamp(48px, 6vw, 72px); }
.cp-yo3 .cp-faq summary { min-height: 56px; }
.cp-yo3 .cp-faq-sign { background: color-mix(in srgb, var(--yo-ink) 8%, transparent); }

/* The summit, on the night under a ridge: the cross on the top, the call and its echo, the way in. */
.cp-yo3-summit { position: relative; padding-top: 48px; }
.cp-yo3-summit-range { position: absolute; inset: 0 0 auto; width: 100%; height: clamp(36px, 4.2vw, 60px); }
.cp-yo3-summit-range path { fill: var(--yo-paper); }
.cp-yo3-summit-in { position: relative; display: flex; flex-direction: column; align-items: center; padding-block: 40px clamp(64px, 8vw, 96px); text-align: center; }
.cp-yo3-summit-in .cp-yo3-lede { margin-inline: auto; }
.cp-yo3-cross { width: 26px; height: 42px; fill: var(--yo-ink); }
.cp-yo3-summit-in .cp-yo3-mark { flex-direction: column; justify-content: center; gap: 6px; margin-top: 16px; }
.cp-yo3-summit-in .cp-yo3-diamond { display: none; }
.cp-yo3-summit-in .cp-yo3-alt { margin-inline-start: 0; }
.cp-yo3-summit .cp-yo3-h2 { font-size: clamp(44px, 7vw, 96px); }
.cp-yo3-echo { display: flex; flex-direction: column; align-items: flex-end; width: min(100%, 560px); margin-top: -4px; font: 800 clamp(30px, 4.4vw, 56px)/.95 var(--yo-serif); color: var(--yo-muted); }
.cp-yo3-echo span { opacity: .6; } .cp-yo3-echo span + span { margin-inline-end: -40px; opacity: .32; font-size: .66em; }
:root:not([data-skin="game"]) .cp-yo3-night .btn-primary { --primary: #f3ede2; --primary-ink: #1e1814; }
:root[data-skin="game"] body.s-arcade .cp-yo3 .cp-yo3-echo { font-family: var(--a-hud); font-style: normal; font-size: 12px; font-size-adjust: var(--arc-ex, none); }

/* The courses to go on with, then the sources (open on a big screen). */
.cp-yo3-end { padding-block: 48px 56px; }
.cp-yo3-notes { margin-top: 40px; }
.cp-yo3-notes summary { display: flex; align-items: center; min-height: 44px; cursor: pointer; list-style: none; }
.cp-yo3-notes summary::-webkit-details-marker { display: none; }
.cp-yo3-notes ol { columns: 1; column-gap: 40px; margin-top: 12px; padding-inline-start: 1.6em; list-style: decimal; font-size: 14px; line-height: 1.5; color: var(--yo-muted); }
.cp-yo3-notes li { break-inside: avoid; padding-block: 3px; }
.cp-yo3-notes li:target { color: var(--yo-ink); font-weight: 700; }

/* The shared list of every lesson below <main>, on the page's ground with trail markers for its units. */
[data-lesson-pages][data-course="yodeling"] > .s-kick { color: var(--yo-chest); }
[data-lesson-pages][data-course="yodeling"] h3[data-unit] { display: flex; align-items: center; gap: 10px; }
[data-lesson-pages][data-course="yodeling"] h3[data-unit]::before { content: ""; width: 11px; height: 11px; rotate: 45deg; background: var(--yo-sign); outline: 1px solid rgb(30 24 20 / .3); }

@media (min-width: 640px) {
    .cp-yo3-outcomes { grid-template-columns: repeat(2, minmax(0, 1fr)); }
    .cp-yo3-pack { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 48px; }
    .cp-yo3-rules ul { grid-template-columns: repeat(2, minmax(0, 1fr)); }
    .cp-yo3-notes ol { columns: 2; }
}
@media (min-width: 900px) {
    .cp-yo3-hero-grid { grid-template-columns: minmax(0, 1.1fr) minmax(0, .9fr); gap: 56px; align-items: center; padding-top: 44px; }
    .cp-yo3-post { justify-self: end; }
    .cp-yo3-outcomes { grid-template-columns: repeat(4, minmax(0, 1fr)); }
    .cp-yo3-cols, .cp-yo3-demos { grid-template-columns: repeat(2, minmax(0, 1fr)); }
    .cp-yo3-demo { padding: 30px 32px; }
    .cp-yo3-story { grid-template-columns: repeat(2, minmax(0, 1fr)); grid-auto-rows: minmax(0, auto); gap: 0 88px; padding-inline-start: 0; }
    .cp-yo3-story::before { left: calc(50% - 1.5px); }
    .cp-yo3-story > li { grid-row: var(--i) / span 2; padding-bottom: 24px; }
    .cp-yo3-story > li:nth-child(odd) { grid-column: 1; }
    .cp-yo3-story > li:nth-child(odd) > .cp-yo3-diamond { left: auto; right: -51px; }
    .cp-yo3-story > li:nth-child(even) { grid-column: 2; }
    .cp-yo3-story > li:nth-child(even) > .cp-yo3-diamond { left: -51px; }
    .cp-yo3-world { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 40px; }
    .cp-yo3-horn-row { grid-template-columns: minmax(0, 1.6fr) minmax(0, 1fr); gap: 48px; align-items: center; }
    .cp-yo3-heart { grid-template-columns: minmax(0, 1.2fr) minmax(0, 1fr); gap: 48px; }
    .cp-yo3-trail { grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 18px; align-items: start; }
    .cp-yo3-trail > li { margin-top: calc((3 - var(--i)) * 44px); }
    .cp-yo3-flip { grid-template-columns: minmax(0, 1.05fr) minmax(0, .95fr); gap: 56px; align-items: start; }
    .cp-yo3-app { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 64px; }
    .cp-yo3-fine { grid-template-columns: minmax(0, .8fr) minmax(0, 1.4fr); gap: 56px; align-items: start; }
    .cp-yo3-fine .cp-faq { margin-top: 0; }
    .cp-yo3-rules ul { grid-template-columns: repeat(4, minmax(0, 1fr)); }
}
/* A narrow phone: the hero's actions take the width, and game mode's long play labels may take two lines, as the
   arcade's own buttons do, rather than push the page sideways. */
.cp-yo3 :is(.cp-yo3-hero-grid, .cp-yo3-horn-row, .cp-yo3-flip, .cp-yo3-app, .cp-yo3-heart) > * { min-width: 0; }
@media (max-width: 419px) {
    .cp-yo3-hero .cp-yo3-ctas > * { flex: 1 1 100%; justify-content: center; }
    .cp-yo3-hero .cp-yo3-ctas .btn-primary { padding-inline: 16px; }
    :root[data-skin="game"] body.s-arcade .cp-yo3 .cp-yo3-play { max-width: 100%; white-space: normal; text-align: start; line-height: 1.35; }
}
@media (max-width: 639px) {
    .cp-yo3-pano-call, .cp-yo3-pano-echo, .cp-yo3-pano-where { display: none; }
    .cp-yo3-pano-lane { font-size: 10.5px; translate: 0 50%; }
    .cp-yo3-pano .cp-yo3-echo-0 { transform: translateX(120px); }
    .cp-yo3-echo { align-items: center; }
    .cp-yo3-echo span + span { margin-inline-end: 0; }
    .cp-yo3-sign { padding-inline-end: 56px; }
    .cp-yo3-sign b { font-size: 17px; }
    .cp-yo3-shots { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 10px; }
    .cp-yo3-shots > :nth-child(2) { margin-top: 28px; }
}

/* Counterpoint (site/courses/counterpoint): "Point against point", after Hillel's design of 2026-11-18
   (course-designs/counterpoint): old printed music, hand-copied choir books and teaching books. Square
   notes on red four-line staves in every chart, one colour a voice (--v on .cp-cp2-v1 to v4: I ink,
   II red, III ochre, IV slate, only in the counting demo; --vt is the same voice as text, ochre a
   shade deeper so it reads), red Roman numerals and a short staff over each section, a big red
   capital on the leads, and EB Garamond for the display type (the site's serif stack behind it).
   The red is a token (--cpt-red, its staff --cpt-staff) for calm light and dark and the game skin.
   Calm dark is candlelit, never black. Game skin: "Point vs point", neon lanes on a dot grid, the
   notes as glowing blocks, Bungee headings and Press Start readouts, the history a high-score table.
   Sounds: js/public/counterpoint.js. */
.cp-cp2 { --cpt-bg: #f8f3eb; --cpt-surface: #f2ebdf; --cpt-deep: #ebe2d3; --cpt-card: #fcf9f3; --cpt-ink: #1c1613; --cpt-muted: #5a5049; --cpt-line: rgba(28, 22, 19, .15);
    --cpt-red: #a3232b; --cpt-staff: rgba(163, 35, 43, .4); --cpt-v1: var(--cpt-ink); --cpt-v2: var(--cpt-red); --cpt-v3: #c4972a; --cpt-gold: #7a5c0e; --cpt-v4: #4f6380;
    --cpt-night: #1c1613; --cpt-night-ink: #f3ecdf; --cpt-night-muted: #c9bfb1; --cpt-on-red: #fff;
    --cpt-serif: "EB Garamond", ui-serif, "Iowan Old Style", "Palatino Linotype", Palatino, Georgia, serif;
    --cp-a: var(--cpt-red); --cp-a-ink: #fff; --cp-a-text: var(--cpt-red); --cp-line: var(--cpt-line);
    background: var(--cpt-bg); color: var(--cpt-ink); }
:root:not([data-theme$="-light"]) .cp-cp2 { --cpt-bg: #17130f; --cpt-surface: #1d1813; --cpt-deep: #231d17; --cpt-card: #2a231c; --cpt-ink: #ede4d3; --cpt-muted: #b9ad99; --cpt-line: rgba(237, 228, 211, .16);
    --cpt-red: #ee7f75; --cpt-staff: rgba(238, 127, 117, .38); --cpt-v3: #e0b652; --cpt-gold: #e0b652; --cpt-v4: #8fb1d6;
    --cpt-night: #0f0c09; --cpt-night-ink: #ede4d3; --cpt-night-muted: #b9ad99; --cpt-on-red: #17130f; --cp-a: #b8323a; --cp-a-text: #ee7f75; }
