.cp-vi-big { margin-top: 40px; padding-top: 24px; border-top: 1px solid var(--vi-night-line); }
.cp-vi-big-n { display: flex; flex-wrap: wrap; align-items: baseline; gap: 0 14px; font-size: clamp(64px, 8vw, 88px); font-weight: 300; letter-spacing: -0.05em; line-height: 1; }
.cp-vi-big-to { font-size: .32em; letter-spacing: 0; color: var(--vi-night-body); }
.cp-vi-big-line { flex-basis: 100%; margin-top: 10px; font-size: 16px; letter-spacing: 0; line-height: 1.5; color: var(--vi-night-body); }
.cp-vi-big svg { width: 100%; height: 56px; margin-top: 18px; }
.cp-vibrato .cp-vi-big [data-vi-wave] { stroke: var(--vi-lilac); stroke-width: 2; }
.cp-vi-strip { display: flex; justify-content: space-between; gap: 12px; margin-top: 6px; padding-top: 8px; border-top: 1px solid var(--vi-night-dash); font-size: 11px; color: var(--vi-night-muted); }
