.cp-vi-strip span:not(:nth-child(2)) { flex: none; white-space: nowrap; }
.cp-vi-cards { display: grid; gap: 2px; align-self: start; }
.cp-vi-cards li { padding: 24px 26px; border-radius: 4px; background: var(--vi-night-card); }
.cp-vi-cards li:first-child { border-radius: 20px 20px 4px 4px; }
.cp-vi-cards li:last-child { border-radius: 4px 4px 20px 20px; }
.cp-vi-cards li > p:first-child { font-size: 18px; line-height: 1.5; }
.cp-vi-card-src { margin-top: 12px; font-size: 12px; letter-spacing: .06em; text-transform: uppercase; color: var(--vi-night-muted); }

/* Upstream: the years, a ruled row each, the year large at left. */
.cp-vi-years { margin-top: 40px; border-bottom: 1px solid var(--vi-row); }
.cp-vi-years li { display: grid; gap: 6px 32px; padding: 22px 0; border-top: 1px solid var(--vi-row); }
@media (min-width: 760px) { .cp-vi-years li { grid-template-columns: 220px minmax(0, 1fr); align-items: baseline; } }
.cp-vi-year { font-size: clamp(30px, 3.4vw, 40px); font-weight: 300; letter-spacing: -0.03em; line-height: 1.1; color: var(--vi-label); }
.cp-vi-years li > div > p:first-child { max-width: 46em; font-size: 17px; line-height: 1.55; text-wrap: pretty; }
.cp-vi-told { margin-top: 6px; font-size: 14px; color: var(--vi-muted); }
.cp-vi-told a { display: inline-block; padding-block: 12px; margin-block: -12px; }

/* On the bank: three ruled lists, then singing it safely on a lavender panel. */
.cp-vi-bank { display: grid; gap: 32px; margin-top: 36px; }
@media (min-width: 900px) { .cp-vi-bank { grid-template-columns: repeat(3, minmax(0, 1fr)); } }
.cp-vi-bank h3 { padding-bottom: 14px; border-bottom: 1px solid var(--vi-rule); font-size: 13px; font-weight: 700; letter-spacing: .16em; text-transform: uppercase; }
.cp-vi-ticks li { display: flex; gap: 12px; padding: 14px 0; border-bottom: 1px solid var(--vi-row); font-size: 16px; line-height: 1.5; }
.cp-vi-ticks svg { flex: none; margin-top: 4px; color: var(--vi-label); }
.cp-vi-songs li { display: grid; gap: 4px; padding: 14px 0; border-bottom: 1px solid var(--vi-row); }
.cp-vi-songs b { font-size: 16px; font-weight: 500; }
.cp-vi-songs span { font-size: 14px; color: var(--vi-muted); }
.cp-vi-calm { display: flex; flex-wrap: wrap; gap: 24px 48px; margin-top: 44px; padding: clamp(24px, 3vw, 36px); border-radius: 28px; background: var(--vi-lav); }
.cp-vi-calm > div { flex: 1 1 280px; }
.cp-vi-calm-points { flex: 2 1 400px; min-width: 0; }
.cp-vi-calm-h { margin: 12px 0; font-size: 30px; font-weight: 400; letter-spacing: -0.02em; }
.cp-vi-calm .cp-vi-side { font-size: 16px; }
.cp-vi-calm-points li { position: relative; padding: 13px 0 13px 20px; border-bottom: 1px solid var(--vi-lav-line); font-size: 16px; line-height: 1.5; }
.cp-vi-calm-points li::before { content: ""; position: absolute; inset-inline-start: 2px; top: 1.3em; width: 6px; height: 6px; border-radius: 99px; background: var(--vi-label); }

/* The questions beside their heading. */
.cp-vi-fine { display: grid; gap: 20px; }
@media (min-width: 960px) { .cp-vi-fine { grid-template-columns: minmax(0, 1fr) minmax(0, 2fr); gap: 64px; } }
.cp-vi-fine .cp-faq { margin-top: 0; max-width: none; }
