/* The close: centred on a lavender wash, a faint wave blooming behind its headline; then the sources. */
.cp-vi-close { position: relative; margin-top: clamp(64px, 8vw, 96px); padding: clamp(72px, 8vw, 96px) 0 72px; overflow: hidden; background: linear-gradient(180deg, var(--vi-paper), var(--vi-lav)); }
.cp-vi-close-wave { position: absolute; inset-inline: 0; top: 48px; width: 100%; height: 260px; }
.cp-vibrato .cp-vi-close-wave [data-vi-wave] { stroke: var(--vi-soft); stroke-width: 2; opacity: .6; }
