/* Game skin: the arcade's type, square frames with hard shadows, the waves in neon. */
:root[data-skin="game"] body.s-arcade .cp-vibrato :is(.cp-vi-h1, .cp-vi-title, .cp-vi-close-h, .cp-vi-kind-head h3, .cp-vi-unit h3, .cp-vi-calm-h, .cp-vi-deck-h, .cp-vi-big-n, .cp-vi-year) { font-family: var(--a-display); font-weight: 400; letter-spacing: .01em; text-transform: uppercase; font-size-adjust: var(--arc-ex, none); }
