:root[data-skin="game"] body.s-arcade .cp-vibrato :is(.cp-vi-trace, .cp-vi-trace-box, .cp-vi-kind, .cp-vi-kind-box, .cp-vi-unit, .cp-vi-deck, .cp-vi-deck-box, .cp-vi-cards li, .cp-vi-calm, .cp-vi-step, .cp-vi-hear, .cp-vi-free, .cp-related a) { border-radius: 0; }
:root[data-skin="game"] body.s-arcade .cp-vibrato :is(.cp-vi-trace, .cp-vi-deck) { border: 2px solid #3be7ff; box-shadow: 6px 6px 0 #ff5fd2; }
:root[data-skin="game"] body.s-arcade .cp-vibrato :is(.cp-vi-kind, .cp-vi-unit, .cp-vi-calm) { border: 2px solid var(--vi-label); box-shadow: 4px 4px 0 var(--vi-orange); }
:root[data-skin="game"] body.s-arcade .cp-vibrato :is(.cp-vi-hero, .cp-vi-close) { background: var(--vi-paper); }
:root[data-skin="game"]:not([data-theme$="-light"]) body.s-arcade .cp-vibrato [data-vi-wave] { filter: drop-shadow(0 0 4px var(--vi-line)); }
:root[data-skin="game"] body.s-arcade .cp-vi-river li { border-radius: 0; }
:root[data-skin="game"] body.s-arcade .cp-vibrato .cp-vi-wavy { text-decoration-style: wavy; }

/* Range and registers (site/courses/range-and-registers), after Hillel's design of 2026-11-18: reading down the page is
   like singing up a scale. A warm paper page in Figtree, thin headlines, mono labels and the site's serif for the old
   record (the archive and the margin notes). Chest voice is rust and head voice blue, the same way throughout, striped
   in both where either will do (the break), and always named in words too. Each section's label carries its note and
   hertz, a square below the break and a circle above it; a full-width striped band marks the break. The demos sit on
   the night (the shared deck, .cp-dk-*). Calm dark: the same page at night. Game skin: the arcade's ground, Bungee
   headings and pixel labels, square frames with hard shadows. No left-edge stripes: units and mechanisms carry their
   colour on top. Sounds: js/public/range-and-registers.js. */
.cp-rg { --rg-paper: #faf6f0; --rg-wash: #f1ebe1; --rg-card: #fff; --rg-ink: #1d1916; --rg-body: #3b3530; --rg-muted: #5e5650; --rg-line: #e6ded3; --rg-rule: #cfc4b5;
    --rg-rust: #b5481c; --rg-rust-text: #a6421a; --rg-rust-deep: #7e2f10; --rg-blue: #2e55c9; --rg-blue-text: #2e55c9; --rg-blue-deep: #1c3a99; --rg-mix-text: #82508a;
    --rg-rust-tint: #f2e6dc; --rg-rust-edge: #e5cdbb; --rg-blue-tint: #e6e9f5; --rg-blue-edge: #cbd3ee; --rg-on: #c98a00;
    --rg-night: #1b1620; --rg-night-deep: #120f16; --rg-night-ink: #f3eef6; --rg-night-body: #d6cedd; --rg-night-muted: #b8afc0; --rg-night-line: #2e2734; --rg-night-chip: #2a2331;
    --rg-chest-n: #e0834f; --rg-head-n: #8ea8f5; --rg-gold: #ffc66b;
    --rg-serif: ui-serif, "Iowan Old Style", "Palatino Linotype", Palatino, Georgia, serif;
    --rg-mono: var(--font-mono, ui-monospace, "SF Mono", Menlo, Consolas, monospace);
    --rg-hatch: repeating-linear-gradient(135deg, var(--rg-rust) 0 6px, var(--rg-blue) 6px 12px);
    --rg-hatch-soft: repeating-linear-gradient(135deg, var(--rg-rust-tint) 0 8px, var(--rg-blue-tint) 8px 16px);
    --cp-a-text: var(--rg-blue-text); --cp-line: var(--rg-rule);
    --color-cream: var(--rg-ink); --color-muted: var(--rg-muted); --fill-2: var(--rg-line);
    background: var(--rg-paper); color: var(--rg-ink); }
:root:not([data-theme$="-light"]) .cp-rg { --rg-paper: var(--color-ink); --rg-wash: color-mix(in srgb, #fff 4%, var(--color-ink)); --rg-card: color-mix(in srgb, #fff 6%, var(--color-ink)); --rg-ink: #f3ece2; --rg-body: #d8cec2; --rg-muted: #bcb0a2; --rg-line: #3a312b; --rg-rule: #4d4239;
    --rg-rust: #d0602f; --rg-rust-text: #f39a6c; --rg-rust-deep: #a8461b; --rg-blue: #5b7fe6; --rg-blue-text: #a3b8ff; --rg-blue-deep: #3f5fc4; --rg-mix-text: #dcaee0;
    --rg-rust-tint: #33231b; --rg-rust-edge: #5a3a2a; --rg-blue-tint: #1d2340; --rg-blue-edge: #34406e; --rg-on: #ffc66b;
    --rg-night: #120e16; --rg-night-deep: #0b090e; --rg-night-line: #2a2330; }
:root[data-skin="game"] .cp-rg { --rg-paper: #07060e; --rg-wash: #0c0a17; --rg-card: #12101e; --rg-ink: #ede9ff; --rg-body: #d2ccf0; --rg-muted: #b8b2d8; --rg-line: #2a2640; --rg-rule: #3a3560;
    --rg-rust: #ff7a3a; --rg-rust-text: #ff9a5a; --rg-rust-deep: #d9541c; --rg-blue: #3be7ff; --rg-blue-text: #3be7ff; --rg-blue-deep: #1fb4d9; --rg-mix-text: #ff9de6;
    --rg-rust-tint: #1d1020; --rg-rust-edge: #4a2430; --rg-blue-tint: #0b1626; --rg-blue-edge: #1f3b4a; --rg-on: #ffd84a;
    --rg-night: #0d0818; --rg-night-deep: #07040e; --rg-night-ink: #ede9ff; --rg-night-body: #d2ccf0; --rg-night-muted: #aaa4d0; --rg-night-line: #2a2240; --rg-night-chip: #1d1830;
    --rg-chest-n: #ff9a5a; --rg-head-n: #3be7ff; --rg-gold: #ffd84a; }
:root[data-skin="game"][data-theme$="-light"] .cp-rg { --rg-paper: #f4f1ff; --rg-wash: #ebe6ff; --rg-card: #fff; --rg-ink: #14122b; --rg-body: #2e2950; --rg-muted: #403a66; --rg-line: #d9d3f2; --rg-rule: #bdb5e3;
    --rg-rust: #b8450f; --rg-rust-text: #a23c0c; --rg-rust-deep: #7e2f10; --rg-blue: #1d47c4; --rg-blue-text: #1d47c4; --rg-blue-deep: #142f8a; --rg-mix-text: #8a1f6e;
    --rg-rust-tint: #f6e4da; --rg-rust-edge: #e8c6b2; --rg-blue-tint: #e2e7fb; --rg-blue-edge: #c3cdf2; --rg-on: #b38600; }
/* The page's paper under the footer too (calm light), so there's no seam below the page. */
:root:not([data-skin="game"])[data-theme$="-light"] body:has(main.cp-rg),
:root:not([data-skin="game"])[data-theme$="-light"] body[data-course="range-and-registers"] { background: #faf6f0; }
.cp-rg a:not([class*="btn"]) { color: inherit; text-underline-offset: 3px; }
.cp-rg .s-crumb, .cp-rg .s-crumb a { color: var(--rg-muted); }
.cp-rg .btn-lg { white-space: nowrap; }
.cp-rg-sec { padding-top: clamp(48px, 6vw, 72px); }
/* The climb lists every lesson as a link to its page, so the shared list of lesson pages under the page, and the related
   list's own All courses (the close's button says it), aren't shown twice. */
.cp-rg ~ [data-lesson-pages], .cp-rg-close .cp-related-all { display: none; }

/* Chest and head in words: rust and blue, and the old record's italics. */
.cp-rg-t-low, .cp-rg-t-chest { color: var(--rg-rust-text); }
.cp-rg-t-high, .cp-rg-t-head { color: var(--rg-blue-text); }
.cp-rg-lead .cp-rg-t-chest, .cp-rg-lead .cp-rg-t-head { font-weight: 550; }
.cp-rg-t-em { font-style: italic; }

/* Type. */
.cp-rg-h1 { margin-top: 24px; font-size: clamp(56px, 10vw, 128px); line-height: .92; font-weight: 300; letter-spacing: -0.045em; }
.cp-rg-h1 .cp-rg-t-low { display: inline-block; transform: translateY(.12em); }
.cp-rg-h1 .cp-rg-t-high { display: inline-block; transform: translateY(-.14em); }
.cp-rg-title { margin-top: 18px; font-size: clamp(38px, 5vw, 60px); line-height: 1; font-weight: 300; letter-spacing: -0.035em; text-wrap: balance; }
.cp-rg-serif { font-family: var(--rg-serif); font-size: clamp(42px, 6vw, 76px); letter-spacing: -0.02em; }
.cp-rg-body p, .cp-rg-body-p { font-size: 18px; line-height: 1.65; color: var(--rg-body); text-wrap: pretty; }
.cp-rg-body p + p { margin-top: 16px; }
.cp-rg-body-p { margin-top: 18px; }
.cp-rg-small { margin-top: 12px; font-size: 15px; line-height: 1.6; color: var(--rg-body); text-wrap: pretty; }

/* A section's label: its note and hertz (a square below the break, a circle above it), a rule, then its words. */
.cp-rg-kick { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 12px; font-family: var(--rg-mono); font-size: 12px; font-weight: 500; line-height: 1.4; letter-spacing: .08em; text-transform: uppercase; color: var(--rg-rust-text); }
.cp-rg-kick[data-side="head"] { color: var(--rg-blue-text); }
.cp-rg-mark { display: inline-flex; align-items: center; gap: 10px; white-space: nowrap; }
.cp-rg-mark i { flex: none; width: 8px; height: 8px; border-radius: 2px; background: currentColor; }
.cp-rg-kick[data-side="head"] .cp-rg-mark i { border-radius: 99px; }
.cp-rg-mark-line { width: 24px; height: 1px; background: currentColor; }

/* The hero: the headline low and high, the lead and the buttons, and the ruler under them. */
.cp-rg-hero { padding-top: 22px; border-bottom: 1px solid var(--rg-line); }
.cp-rg-hero-grid { display: grid; grid-template-columns: minmax(0, 1fr); gap: 28px 64px; margin-top: 28px; }
.cp-rg-hero .cp-hero-chip { margin-top: 0; background: var(--rg-card); border-color: var(--rg-line); color: var(--rg-ink); }
.cp-rg-hero .cp-hero-chip b { background: var(--rg-ink); color: var(--rg-paper); }
.cp-rg-lead { font-size: 18px; line-height: 1.6; color: var(--rg-body); text-wrap: pretty; }
.cp-rg-facts-row { display: flex; flex-wrap: wrap; gap: 8px 24px; margin-top: 20px; font-family: var(--rg-mono); font-size: 12px; letter-spacing: .04em; text-transform: uppercase; color: var(--rg-muted); }
.cp-rg-btns { display: flex; flex-wrap: wrap; gap: 12px; margin-top: 28px; }
.cp-rg-ruler { margin: 56px 0 0; padding-bottom: 28px; }
.cp-rg-ruler-ends { display: flex; justify-content: space-between; gap: 16px; font-size: 13px; line-height: 1.45; color: var(--rg-body); }
.cp-rg-ruler-ends p { max-width: 300px; }
.cp-rg-ruler-ends b { display: block; font-family: var(--rg-mono); font-size: 13px; font-weight: 500; color: var(--rg-rust-text); }
.cp-rg-ruler-high { text-align: right; }
.cp-rg-ruler-high b { color: var(--rg-blue-text); }
.cp-rg-ruler-art { position: relative; height: 150px; margin-top: 16px; }
.cp-rg-keyrow { position: absolute; inset: auto 0 22px; height: 96px; display: flex; align-items: flex-end; gap: 1px; }
.cp-rg-k { flex: 1; height: 66%; border-radius: 2px 2px 0 0; background: var(--rg-rust); }
.cp-rg-k-c { height: 100%; }
.cp-rg-k-black { height: 40%; }
.cp-rg-k-high { background: var(--rg-blue); }
.cp-rg-k-break { background: repeating-linear-gradient(180deg, var(--rg-rust) 0 4px, var(--rg-blue) 4px 8px); }
.cp-rg-stem { position: absolute; left: var(--at); top: 0; height: 32px; width: 1px; background: var(--rg-rust); }
.cp-rg-stem-short { top: 12px; height: 20px; opacity: .7; }
.cp-rg-stem-high { background: var(--rg-blue); }
.cp-rg-stem-mid { width: 0; background: none; border-left: 1px dashed var(--rg-ink); }
.cp-rg-midc { position: absolute; left: var(--at); top: -4px; translate: -50% 0; padding: 0 6px; background: var(--rg-paper); font-family: var(--rg-mono); font-size: 11px; color: var(--rg-ink); white-space: nowrap; text-transform: uppercase; }
.cp-rg-zone { position: absolute; left: var(--from); width: var(--width); top: 16px; display: flex; justify-content: center; }
.cp-rg-zone > span { padding: 0 4px; background: var(--rg-paper); font-family: var(--rg-mono); font-size: 10px; letter-spacing: .08em; text-transform: uppercase; color: var(--rg-muted); white-space: nowrap; }
.cp-rg-octs { position: absolute; inset: auto 0 0; height: 16px; font-family: var(--rg-mono); font-size: 11px; color: var(--rg-muted); }
.cp-rg-octs span { position: absolute; left: var(--at); translate: -50% 0; }
.cp-rg-octs span:last-child { translate: -85% 0; }
.cp-rg-ruler-cap { margin-top: 16px; font-size: 14px; color: var(--rg-muted); }

/* The featured demo, Up in chest, down in head, on the night (the shared deck). */
.cp-rg .cp-rg-deck { --pd-bg: var(--rg-night); --pd-edge: var(--rg-night-line); --pd-ink: var(--rg-night-ink); --pd-body: var(--rg-night-body); --pd-muted: var(--rg-night-muted); --pd-rose: var(--rg-head-n); --pd-gold: var(--rg-gold); --pd-staff: #231d29; }
.cp-rg-demosec .cp-rg-kick { margin-bottom: 16px; }
.cp-rg-deck .cp-dk-demo-bar { font-family: var(--rg-mono); font-weight: 500; letter-spacing: .12em; }
.cp-rg-roll { position: relative; padding-top: 34px; background: var(--rg-night-deep); }
@media (max-width: 639px) { .cp-rg .cp-rg-roll svg { height: 220px; } .cp-rg-map-bar span { display: none; } }
.cp-rg-bar { fill: var(--rg-chest-n); transition: fill .15s; }
.cp-rg-bar[data-head] { fill: color-mix(in srgb, var(--rg-head-n) 22%, var(--rg-night-deep)); stroke: var(--rg-head-n); stroke-width: 2; vector-effect: non-scaling-stroke; }
.cp-rg-bar[data-on] { fill: var(--rg-gold); stroke: var(--rg-gold); }
.cp-rg-band { fill: url(#rg-hatch); stroke: #6e6478; stroke-width: 1; stroke-dasharray: 4 4; vector-effect: non-scaling-stroke; }
.cp-rg-hatch-a { fill: rgb(224 131 79 / .16); }
.cp-rg-hatch-b { fill: rgb(142 168 245 / .16); }
.cp-rg-corner { position: absolute; top: 14px; font-family: var(--rg-mono); font-size: 10.5px; letter-spacing: .08em; text-transform: uppercase; }
