.cp-rg-deck .cp-dk-demo-h { font-weight: 700; letter-spacing: -0.025em; }
.cp-rg-two .cp-dk-play-icon { background: var(--rg-head-n); }
.cp-rg-slider { margin-top: 22px; }
.cp-rg-key { display: flex; flex-wrap: wrap; gap: 8px 20px; margin-top: 14px; font-size: 14px; color: var(--rg-night-body); }
