.cp-rg-sw-head { background: color-mix(in srgb, var(--rg-head-n) 22%, transparent); box-shadow: inset 0 0 0 1.5px var(--rg-head-n); }
.cp-rg-sw-band { background: repeating-linear-gradient(135deg, rgb(224 131 79 / .45) 0 3px, rgb(142 168 245 / .45) 3px 6px); outline: 1px dashed #6e6478; }

/* By the end: rising steps. */
.cp-rg-stairs { display: grid; gap: 28px; margin-top: 36px; }
.cp-rg-stairs li { display: flex; flex-direction: column; }
.cp-rg-stair-n { font-family: var(--rg-mono); font-size: 12px; color: var(--rg-rust-text); }
