.cp-rg-stairs p { margin: 8px 16px 14px 0; font-size: 18px; line-height: 1.45; text-wrap: pretty; }
.cp-rg-stair { display: block; height: 14px; border-top: 3px solid var(--rg-rust); background: var(--rg-rust-tint); }
.cp-rg-stair-0 { width: 40%; }
.cp-rg-stair-1 { width: 60%; border-top-color: var(--rg-mix-text); background: var(--rg-hatch-soft); }
.cp-rg-stair-2 { width: 80%; border-top-color: var(--rg-blue); background: var(--rg-blue-tint); }
.cp-rg-stair-3 { width: 100%; border-top-color: var(--rg-blue); background: linear-gradient(90deg, var(--rg-rust-tint), var(--rg-blue-tint)); }

/* In plain words: the mechanisms on one chart, the four described, and Ferrein's cord drawn as strings. */
.cp-rg-plain { margin-top: clamp(48px, 6vw, 72px); border-top: 1px solid var(--rg-line); }
.cp-rg-plain > .cp-rg-sec { padding-bottom: clamp(56px, 7vw, 80px); }
.cp-rg-two-col { display: grid; grid-template-columns: minmax(0, 1fr); gap: 24px 64px; }
.cp-rg-fig { margin: 44px 0 0; padding: 22px 18px 20px; border-radius: 20px; border: 1px solid var(--rg-line); background: var(--rg-card); }
.cp-rg-fig-top { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: center; gap: 8px 16px; font-family: var(--rg-mono); font-size: 11px; letter-spacing: .08em; text-transform: uppercase; color: var(--rg-muted); }
.cp-rg-approx { padding: 3px 10px; border: 1px dashed var(--rg-rule); border-radius: 99px; color: var(--rg-ink); }
.cp-rg-map-rows { position: relative; display: grid; gap: 4px; margin-top: 40px; }
.cp-rg-map-over { position: absolute; inset: -26px 0 22px 54px; pointer-events: none; }
.cp-rg-map-zone { position: absolute; left: var(--from); width: var(--width); top: 0; bottom: 0; border-inline: 1px dashed var(--rg-rule); background: repeating-linear-gradient(135deg, rgb(181 72 28 / .08) 0 6px, rgb(46 85 201 / .08) 6px 12px); }
.cp-rg-map-zone > span { position: absolute; left: 50%; top: 0; translate: -50% 0; padding: 0 4px; background: var(--rg-card); font-family: var(--rg-mono); font-size: 10px; letter-spacing: .06em; text-transform: uppercase; color: var(--rg-muted); white-space: nowrap; }
.cp-rg-map-row { display: grid; grid-template-columns: 42px minmax(0, 1fr); gap: 12px; align-items: center; }
.cp-rg-map-row b { font-family: var(--rg-mono); font-size: 20px; font-weight: 500; color: var(--rg-c); }
.cp-rg-map-track { position: relative; height: 34px; border-bottom: 1px solid var(--rg-line); }
.cp-rg-map-bar { position: absolute; top: 5px; height: 24px; left: var(--l); width: var(--w); display: flex; align-items: center; justify-content: center; border-radius: 12px; background: var(--rg-c);
    -webkit-mask-image: linear-gradient(90deg, transparent, #000 16%, #000 84%, transparent); mask-image: linear-gradient(90deg, transparent, #000 16%, #000 84%, transparent); }
.cp-rg-map-bar span { font-size: 12px; font-weight: 650; color: #fff; white-space: nowrap; }
/* Calm's dark themes: the register codes lighter, and the bars and Start here deeper, so their words keep AA. */
:root:not([data-theme$="-light"]):not([data-skin="game"]) .cp-rg-map-row b { color: color-mix(in srgb, var(--rg-c) 60%, #fff); }
:root:not([data-theme$="-light"]):not([data-skin="game"]) .cp-rg-map-bar { background: color-mix(in srgb, var(--rg-c) 70%, #000); }
:root:not([data-theme$="-light"]):not([data-skin="game"]) .cp-rg-start { background: var(--rg-rust-deep); }
/* Game's dark themes: the neon bars and Start here carry dark words. */
:root[data-skin="game"]:not([data-theme$="-light"]) body.s-arcade .cp-rg :is(.cp-rg-map-bar span, .cp-rg-lessons a.cp-rg-start) { color: #07060e; }
.cp-rg-m0 { --rg-c: var(--rg-rust-deep); --l: 0%; --w: 32%; }
.cp-rg-m1 { --rg-c: var(--rg-rust); --l: 8%; --w: 58%; }
.cp-rg-m2 { --rg-c: var(--rg-blue); --l: 32%; --w: 56%; }
.cp-rg-m3 { --rg-c: var(--rg-blue-deep); --l: 74%; --w: 26%; }
.cp-rg-map-axis { display: flex; justify-content: space-between; margin-left: 54px; padding-top: 6px; font-family: var(--rg-mono); font-size: 11px; letter-spacing: .06em; text-transform: uppercase; color: var(--rg-muted); }
.cp-rg-fig-cap { margin-top: 14px; font-size: 13.5px; line-height: 1.55; color: var(--rg-muted); }
.cp-rg-mechs { display: grid; grid-template-columns: minmax(0, 1fr); gap: 24px 32px; margin-top: 32px; }
.cp-rg-mechs li { padding-top: 14px; border-top: 3px solid var(--rg-c); }
.cp-rg-mechs h3 { font-size: 18px; font-weight: 650; }
.cp-rg-mechs p { margin-top: 8px; font-size: 15px; line-height: 1.55; color: var(--rg-body); }
.cp-rg-pair { display: grid; grid-template-columns: minmax(0, 1fr); gap: 40px 64px; margin-top: 52px; align-items: start; }
.cp-rg-cords { margin: 0; padding: 26px 20px; border-radius: 20px; background: var(--rg-wash); }
.cp-rg-serif-h { margin-top: 12px; font-family: var(--rg-serif); font-size: 28px; font-weight: 400; letter-spacing: -0.01em; }
.cp-rg-strings { display: flex; flex-direction: column; gap: 18px; margin-top: 26px; }
.cp-rg-strings li { transition: opacity .2s; }
.cp-rg-string-1 { width: 66.667%; }
.cp-rg-string-2 { width: 50%; }
.cp-rg-string { position: relative; display: block; height: 10px; }
.cp-rg-string::before { content: ""; position: absolute; inset: 4px 5px auto; height: 2px; background: var(--rg-ink); transition: background .15s, height .15s, top .15s; }
.cp-rg-string::after { content: ""; position: absolute; inset: 0; background: radial-gradient(circle 5px at 5px 50%, var(--rg-ink) 96%, transparent), radial-gradient(circle 5px at calc(100% - 5px) 50%, var(--rg-ink) 96%, transparent); }
.cp-rg-strings li[data-on] .cp-rg-string::before { top: 3px; height: 4px; background: var(--rg-on); }
.cp-rg-strings:has([data-on]) li:not([data-on]) { opacity: .35; }
.cp-rg-string-say { display: flex; justify-content: space-between; gap: 8px; margin-top: 6px; font-size: 13px; line-height: 1.4; color: var(--rg-body); }
.cp-rg-string-say b { flex: none; font-family: var(--rg-mono); font-weight: 500; }
.cp-rg-btns-s { margin-top: 24px; }
.cp-rg-hear { display: inline-flex; align-items: center; gap: 10px; min-height: 44px; padding: 5px 18px 5px 5px; border-radius: 99px; border: 1px solid var(--rg-rule); background: var(--rg-card); color: var(--rg-ink); font-size: 15px; font-weight: 650; white-space: nowrap; cursor: pointer; }
.cp-rg-hear:hover { border-color: var(--rg-ink); }
.cp-rg-hear:focus-visible { outline: 3px solid var(--rg-blue); outline-offset: 3px; }
.cp-rg-hear-icon { position: relative; flex: none; width: 32px; height: 32px; border-radius: 99px; background: var(--rg-ink); }
.cp-rg-hear-icon::after { content: ""; position: absolute; inset: 10px 9px 10px 12px; background: var(--rg-paper); clip-path: polygon(0 0, 100% 50%, 0 100%); }
.cp-rg-hear[aria-pressed="true"] .cp-rg-hear-icon::after { inset: 11px; clip-path: none; border-radius: 1px; }
.cp-rg-short h3 { font-size: 24px; font-weight: 500; }
.cp-rg-serif-p { margin-top: 16px; font-family: var(--rg-serif); font-size: 22px; line-height: 1.45; color: var(--rg-body); text-wrap: pretty; }

/* From the archive: an old printed record, a timeline, and each entry with its plate. */
.cp-rg-archive { background: var(--rg-wash); border-top: 1px solid var(--rg-rule); }
.cp-rg-archive > .cp-rg-sec { padding-bottom: clamp(56px, 7vw, 80px); }
.cp-rg-timeline { position: relative; height: 56px; margin: 44px 6px 0; }
.cp-rg-timeline::before { content: ""; position: absolute; inset: 20px -6px auto; height: 1px; background: var(--rg-ink); }
.cp-rg-timeline li { position: absolute; left: var(--at); top: 15px; width: 11px; height: 11px; translate: -50% 0; border-radius: 99px; background: var(--rg-ink); }
.cp-rg-timeline span { position: absolute; left: 50%; top: 19px; translate: -50% 0; font-family: var(--rg-mono); font-size: 11px; color: var(--rg-muted); }
.cp-rg-timeline li[data-up] span { top: -22px; }
.cp-rg-years { margin-top: 36px; border-top: 1px solid var(--rg-rule); }
.cp-rg-years > li { display: grid; grid-template-columns: minmax(0, 1fr); gap: 12px 40px; padding: 28px 0; border-bottom: 1px solid var(--rg-rule); }
.cp-rg-year-n { display: block; font-family: var(--rg-serif); font-size: clamp(48px, 6vw, 64px); font-weight: 300; line-height: .9; color: var(--rg-ink); font-variant-numeric: oldstyle-nums; }
.cp-rg-plate { display: block; margin-top: 10px; font-family: var(--rg-mono); font-size: 11px; letter-spacing: .12em; text-transform: uppercase; color: var(--rg-rust-text); }
.cp-rg-years h3 { font-family: var(--rg-serif); font-size: 25px; font-weight: 400; }
.cp-rg-years h3 + p { margin-top: 10px; max-width: 680px; font-size: 16px; line-height: 1.65; color: var(--rg-body); text-wrap: pretty; }

/* The break: chest below, head above, a striped band across the page. */
.cp-rg-break { padding: 48px 16px; background: repeating-linear-gradient(135deg, var(--rg-rust) 0 14px, var(--rg-blue) 14px 28px); }
.cp-rg-break-card { display: block; max-width: 560px; margin-inline: auto; padding: 22px 24px; border-radius: 16px; background: var(--rg-paper); text-align: center; }
.cp-rg-break-ends { display: flex; justify-content: center; gap: 10px; font-family: var(--rg-mono); font-size: 12px; letter-spacing: .12em; text-transform: uppercase; color: var(--rg-muted); }
.cp-rg-break-ends b { font-weight: 500; }
.cp-rg-chest-t { color: var(--rg-rust-text); }
.cp-rg-head-t { color: var(--rg-blue-text); }
.cp-rg-break-line { display: block; margin-top: 10px; font-family: var(--rg-serif); font-size: clamp(21px, 2.6vw, 26px); line-height: 1.3; text-wrap: balance; }

/* The two ends: the words, and a hertz meter on the night. */
.cp-rg-ends { display: grid; grid-template-columns: minmax(0, 1fr); gap: 48px 64px; align-items: center; }
.cp-rg-quote { margin-top: 32px; padding-top: 24px; border-top: 1px solid var(--rg-rule); }
.cp-rg-quote p { font-family: var(--rg-serif); font-size: clamp(21px, 2.4vw, 24px); font-style: italic; line-height: 1.4; }
.cp-rg-quote .s-cite { font-style: normal; }
.cp-rg-ends-in { padding: 24px 20px 26px; }
.cp-rg-meter { padding: 44px 18px 16px; border-radius: 14px; background: var(--rg-night-deep); }
.cp-rg-meter-track { position: relative; height: 56px; }
.cp-rg-meter-bar { position: absolute; inset: 22px 0 auto; height: 12px; border-radius: 6px; background: linear-gradient(90deg, var(--rg-chest-n) 0 45%, var(--rg-head-n) 57% 100%); }
.cp-rg-meter-mid { position: absolute; left: var(--mid); top: 10px; height: 36px; border-left: 1px dashed var(--rg-night-muted); }
.cp-rg-needle { position: absolute; left: var(--at); top: 6px; width: 4px; height: 44px; translate: -50% 0; border-radius: 2px; background: var(--rg-gold); transition: left .6s cubic-bezier(.3, .7, .2, 1); }
.cp-rg-needle b { position: absolute; bottom: calc(100% + 6px); left: 0; translate: calc(-1 * var(--at)) 0; font-family: var(--rg-mono); font-size: 13px; font-weight: 500; color: var(--rg-gold); white-space: nowrap; }
@media (prefers-reduced-motion: reduce) { .cp-rg-needle { transition: none; } }
.cp-rg-meter-axis { position: relative; height: 16px; margin-top: 6px; font-family: var(--rg-mono); font-size: 11px; color: var(--rg-night-muted); }
.cp-rg-meter-axis span { position: absolute; left: 0; }
.cp-rg-meter-axis span:nth-child(2) { left: var(--mid); translate: -50% 0; }
.cp-rg-meter-axis span:last-child { left: auto; right: 0; }
.cp-rg-readout { display: flex; flex-wrap: wrap; align-items: baseline; gap: 4px 14px; margin-top: 22px; }
.cp-rg-readout b { font-size: clamp(28px, 3.4vw, 36px); font-weight: 700; letter-spacing: -0.02em; font-variant-numeric: tabular-nums; }
.cp-rg-readout span { font-family: var(--rg-mono); font-size: 16px; color: var(--rg-gold); }
.cp-rg-end-low .cp-dk-play-icon { background: var(--rg-chest-n); }
.cp-rg-end-high .cp-dk-play-icon { background: var(--rg-head-n); }

/* The climb: the units as rising steps, each a colour on top and its kind in words, every lesson a link. */
.cp-rg-climb { margin-top: clamp(48px, 6vw, 72px); background: var(--rg-card); border-block: 1px solid var(--rg-line); }
.cp-rg-climb > .cp-rg-sec { padding-bottom: clamp(56px, 7vw, 80px); }
.cp-rg-headrow { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: flex-end; gap: 12px 24px; }
.cp-rg-count { font-family: var(--rg-mono); font-size: 12px; letter-spacing: .06em; text-transform: uppercase; color: var(--rg-muted); }
.cp-rg-units { display: grid; grid-template-columns: minmax(0, 1fr); gap: 16px; margin-top: 40px; align-items: start; }
.cp-rg-unit { position: relative; overflow: hidden; padding: 24px 22px 14px; border-radius: 18px; background: var(--rg-paper); --u-bar: var(--rg-rust); --u-text: var(--rg-rust-text); }
.cp-rg-unit::before { content: ""; position: absolute; inset: 0 0 auto; height: 4px; background: var(--u-bar); }
.cp-rg-unit[data-unit="2"] { --u-bar: var(--rg-hatch); --u-text: var(--rg-mix-text); }
.cp-rg-unit[data-unit="3"] { --u-bar: var(--rg-blue); --u-text: var(--rg-blue-text); }
.cp-rg-unit[data-unit="4"] { --u-bar: linear-gradient(90deg, var(--rg-rust), var(--rg-blue)); --u-text: var(--rg-blue-text); }
.cp-rg-unit-top { display: flex; justify-content: space-between; gap: 12px; font-family: var(--rg-mono); font-size: 11px; letter-spacing: .1em; text-transform: uppercase; color: var(--u-text); }
.cp-rg-unit h3 { margin-top: 14px; font-size: 21px; font-weight: 650; line-height: 1.25; }
.cp-rg-lessons { margin-top: 14px; font-size: 15px; }
.cp-rg-lessons li { display: flex; justify-content: space-between; align-items: center; gap: 8px; border-top: 1px solid var(--rg-line); }
.cp-rg-lessons li > :first-child { flex: 1; display: block; padding-block: 10px; }
.cp-rg-lessons a:not(.cp-rg-start) { text-decoration: none; }
.cp-rg-lessons a:not(.cp-rg-start):hover { text-decoration: underline; }
.cp-rg-start { position: relative; flex: none; padding: 4px 10px; border-radius: 99px; background: var(--rg-rust); font-size: 10.5px; font-weight: 750; letter-spacing: .08em; text-transform: uppercase; white-space: nowrap; text-decoration: none; }
.cp-rg .cp-rg-lessons a.cp-rg-start { color: #fff; }
.cp-rg-start::after { content: ""; position: absolute; inset: -10px -4px; }

/* Lesson 1 beside what the app hears. */
.cp-rg-first { display: grid; grid-template-columns: minmax(0, 1fr); gap: 40px 56px; align-items: start; }
.cp-rg-steps { display: flex; flex-direction: column; gap: 10px; margin-top: 26px; }
.cp-rg-steps li { display: flex; gap: 14px; align-items: flex-start; padding: 16px; border-radius: 14px; border: 1px solid var(--rg-line); background: var(--rg-card); font-size: 16px; line-height: 1.5; }
.cp-rg-steps .cp-rg-step-0 { background: var(--rg-rust-tint); border-color: var(--rg-rust-edge); }
.cp-rg-steps .cp-rg-step-1 { background: var(--rg-blue-tint); border-color: var(--rg-blue-edge); }
.cp-rg-step-n { flex: none; display: grid; place-items: center; width: 26px; height: 26px; border-radius: 99px; border: 1px solid var(--rg-ink); font-size: 13px; font-weight: 700; }
.cp-rg-step-0 .cp-rg-step-n { border-color: var(--rg-rust); background: var(--rg-rust); color: #fff; }
.cp-rg-step-1 .cp-rg-step-n { border-color: var(--rg-blue); background: var(--rg-blue); color: #fff; }
.cp-rg-note-p { margin-top: 16px; font-size: 14px; line-height: 1.6; color: var(--rg-muted); }
.cp-rg-inside { padding: 28px 24px; border-radius: 20px; border: 1px solid var(--rg-line); background: var(--rg-card); }
.cp-rg-h3 { font-size: 22px; font-weight: 550; }

/* Margin notes, in their own words. */
.cp-rg-words { display: grid; grid-template-columns: minmax(0, 1fr); gap: 0 48px; margin-top: 32px; }
.cp-rg-words li { padding: 24px 0; border-top: 1px solid var(--rg-rule); }
.cp-rg-word { font-family: var(--rg-serif); font-size: clamp(19px, 2vw, 22px); line-height: 1.4; text-wrap: pretty; }
.cp-rg-src { margin-top: 12px; font-family: var(--rg-mono); font-size: 12px; letter-spacing: .06em; text-transform: uppercase; color: var(--rg-muted); }

/* Before you begin: three ruled lists, singing it safely in rust. */
.cp-rg-kit { display: grid; grid-template-columns: minmax(0, 1fr); gap: 32px; margin-top: 30px; }
.cp-rg-kit h3 { padding-bottom: 12px; border-bottom: 1.5px solid var(--rg-ink); font-size: 13px; font-weight: 750; letter-spacing: .1em; text-transform: uppercase; }
.cp-rg-kit li { display: flex; gap: 12px; padding: 14px 0; border-bottom: 1px solid var(--rg-line); font-size: 16px; line-height: 1.45; }
.cp-rg-kit svg { flex: none; margin-top: 3px; color: var(--rg-blue-text); }
.cp-rg-safe h3 { border-color: var(--rg-rust); color: var(--rg-rust-text); }
.cp-rg-safe svg { color: var(--rg-rust-text); }

/* Questions beside their heading. */
.cp-rg-fine { display: grid; grid-template-columns: minmax(0, 1fr); gap: 16px 48px; padding-bottom: clamp(56px, 7vw, 84px); }
.cp-rg .cp-faq { max-width: none; margin-top: 0; }
.cp-rg .cp-faq details { border-color: var(--rg-rule); }
.cp-rg .cp-faq summary { font-weight: 500; }
.cp-rg .cp-faq details p { color: var(--rg-body); }

/* Back to the bottom: the close on the night, and the ruler again at its foot. */
.cp-rg-close { overflow: hidden; padding-top: clamp(64px, 8vw, 88px); background: var(--rg-night); color: var(--rg-night-ink); text-align: center;
    --primary: var(--rg-gold); --primary-ink: #1b1620; --primary-hover-to: #fff; --color-cream: var(--rg-night-ink); --btn-soft: rgb(255 255 255 / .1); --btn-soft-hover: rgb(255 255 255 / .16); --btn-soft-active: rgb(255 255 255 / .22); --btn-outline: inset 0 0 0 1.5px rgb(255 255 255 / .35); }
.cp-rg-close-kick { display: flex; justify-content: center; align-items: center; gap: 10px; font-family: var(--rg-mono); font-size: 12px; letter-spacing: .12em; text-transform: uppercase; color: var(--rg-chest-n); }
.cp-rg-close-kick i { flex: none; width: 8px; height: 8px; border-radius: 2px; background: currentColor; }
.cp-rg-close-h { margin-top: 18px; font-size: clamp(52px, 7vw, 96px); line-height: .95; font-weight: 300; letter-spacing: -0.045em; text-wrap: balance; }
.cp-rg-close-h .cp-rg-t-chest { color: var(--rg-chest-n); }
.cp-rg-close-h .cp-rg-t-head { color: var(--rg-head-n); }
.cp-rg-close-lead { max-width: 620px; margin: 22px auto 0; font-size: 18px; line-height: 1.6; color: var(--rg-night-body); }
.cp-rg-close-btns { justify-content: center; margin-top: 30px; }
.cp-rg-close-note { margin-top: 16px; font-size: 14px; color: var(--rg-night-muted); }
.cp-rg-close-rel { margin-top: 52px; font-family: var(--rg-mono); font-size: 12px; font-weight: 500; letter-spacing: .12em; text-transform: uppercase; color: var(--rg-night-muted); }
.cp-rg-close .cp-related { justify-content: center; }
.cp-rg-close .cp-related a { background: var(--rg-night-chip); color: var(--rg-night-ink); }
.cp-rg-close-keys { display: flex; align-items: flex-end; gap: 1px; height: 48px; margin-top: 52px; opacity: .55; }
.cp-rg-close-keys .cp-rg-k { --rg-rust: var(--rg-chest-n); --rg-blue: var(--rg-head-n); }

/* The sources: folded on a phone, open on a wide screen. */
.cp-rg-sources { padding-block: 40px 48px; }
.cp-rg-sources summary { display: flex; align-items: center; justify-content: space-between; gap: 16px; min-height: 44px; cursor: pointer; list-style: none; }
.cp-rg-sources summary::-webkit-details-marker { display: none; }
.cp-rg-sources h2 { font-size: 13px; font-weight: 650; letter-spacing: .18em; text-transform: uppercase; color: var(--rg-blue-text); }
.cp-rg-sources details[open] .cp-faq-sign { rotate: 45deg; }
.cp-rg-sources ol { margin-top: 16px; padding-left: 26px; list-style: decimal; font-size: 14px; line-height: 1.5; color: var(--rg-body); }
.cp-rg-sources li { margin-bottom: 8px; padding-left: 4px; break-inside: avoid; }
.cp-rg-sources li:target { background: var(--rg-blue-tint); }

@media (min-width: 600px) {
    .cp-rg-keyrow, .cp-rg-close-keys { gap: 2px; }
    .cp-rg-ruler-ends { gap: 24px; }
    .cp-rg-fig { padding: 28px 28px 24px; }
    .cp-rg-cords { padding: 32px; }
    .cp-rg-mechs { grid-template-columns: repeat(2, minmax(0, 1fr)); }
    .cp-rg-units { grid-template-columns: repeat(2, minmax(0, 1fr)); }
    .cp-rg-years > li { grid-template-columns: 150px minmax(0, 1fr); }
    .cp-rg-ends-in { padding: 28px 24px; }
    .cp-rg-inside { padding: 30px; }
    .cp-rg-break { padding-block: 44px; }
}
@media (min-width: 900px) {
    .cp-rg-hero-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); align-items: end; }
    .cp-rg-hero-side { padding-bottom: 8px; }
    .cp-rg-lead { font-size: 20px; }
    .cp-rg-ruler { margin-top: 48px; }
    .cp-rg-stairs { grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 0 4px; align-items: end; margin-top: 40px; }
    .cp-rg-stair { width: auto; height: 28px; }
    .cp-rg-stair-1 { height: 56px; }
    .cp-rg-stair-2 { height: 84px; }
    .cp-rg-stair-3 { height: 112px; }
    .cp-rg-two-col, .cp-rg-pair, .cp-rg-ends, .cp-rg-first, .cp-rg-words { grid-template-columns: repeat(2, minmax(0, 1fr)); }
    .cp-rg-two-col .cp-rg-body { padding-top: 34px; }
    .cp-rg-first .cp-rg-inside { margin-top: 40px; }
    .cp-rg-mechs { grid-template-columns: repeat(4, minmax(0, 1fr)); }
    .cp-rg-kit { grid-template-columns: repeat(3, minmax(0, 1fr)); }
    .cp-rg-fine { grid-template-columns: minmax(0, 1fr) minmax(0, 2fr); }
    .cp-rg-sources ol { columns: 2; column-gap: 48px; }
}
@media (min-width: 1100px) {
    .cp-rg-units { grid-template-columns: repeat(4, minmax(0, 1fr)); }
    .cp-rg-unit[data-unit="1"] { margin-top: 96px; }
    .cp-rg-unit[data-unit="2"] { margin-top: 64px; }
    .cp-rg-unit[data-unit="3"] { margin-top: 32px; }
    /* The archive as two columns of entries on a wide screen, each year over its plate, title and text. */
    .cp-rg-years { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); column-gap: 48px; border-top: 0; }
    .cp-rg-years > li { grid-template-columns: minmax(0, 1fr); gap: 10px; padding: 26px 0; border-top: 1px solid var(--rg-rule); border-bottom: 0; }
    .cp-rg-year { display: flex; align-items: baseline; gap: 16px; }
    .cp-rg-plate { margin-top: 0; }
    .cp-rg-year-n { font-size: 52px; }
    /* The demo's stage a little wider than tall on a wide screen. */
    .cp-rg .cp-rg-deck .cp-dk-stage { aspect-ratio: 2.6 / 1; }
    /* The margin notes three across. */
    .cp-rg-words { grid-template-columns: repeat(3, minmax(0, 1fr)); column-gap: 40px; }
    .cp-rg-word { font-size: 19px; }
}

/* Game skin: the arcade's ground, Bungee headings, pixel labels, square frames and hard shadows. */
:root[data-skin="game"] body.s-arcade .cp-rg :is(.cp-rg-h1, .cp-rg-title, .cp-rg-close-h, .cp-dk-demo-h) { font-family: var(--a-display); font-weight: 400; letter-spacing: .01em; text-transform: uppercase; font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade .cp-rg-h1 { font-size: clamp(44px, 8vw, 96px); line-height: 1; }
:root[data-skin="game"] body.s-arcade .cp-rg-title { font-size: clamp(30px, 4.6vw, 50px); }
:root[data-skin="game"] body.s-arcade .cp-rg-close-h { font-size: clamp(38px, 7vw, 84px); }
:root[data-skin="game"] body.s-arcade .cp-rg :is(.cp-rg-serif, .cp-rg-year-n, .cp-rg-serif-h, .cp-rg-years h3) { font-family: var(--a-display); font-style: normal; font-weight: 400; font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade .cp-rg :is(.cp-rg-kick, .cp-rg-fig-top, .cp-rg-plate, .cp-rg-unit-top, .cp-rg-count, .cp-rg-break-ends, .cp-rg-close-kick, .cp-rg-close-rel, .cp-rg-corner, .cp-dk-demo-bar, .cp-rg-src, .cp-rg-start) { font-family: var(--a-hud); font-size: 10px; font-weight: 400; letter-spacing: .04em; font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade .cp-rg :is(.cp-dk-demo, .cp-rg-fig, .cp-rg-cords, .cp-rg-unit, .cp-rg-inside, .cp-rg-steps li, .cp-rg-break-card, .cp-rg-hear, .cp-rg-meter, .cp-rg-roll, .cp-related a, .cp-rg-approx, .cp-rg-map-bar, .cp-rg-start) { border-radius: 0; }
:root[data-skin="game"] body.s-arcade .cp-rg :is(.cp-dk-demo) { border: 2px solid #3be7ff; box-shadow: 6px 6px 0 #ff5fd2; }
:root[data-skin="game"] body.s-arcade .cp-rg :is(.cp-rg-fig, .cp-rg-cords, .cp-rg-unit, .cp-rg-inside, .cp-rg-break-card) { border: 2px solid var(--rg-blue); box-shadow: 4px 4px 0 var(--rg-rust); }
:root[data-skin="game"] body.s-arcade .cp-rg :is(.cp-rg-bar[data-on], .cp-rg-needle) { filter: drop-shadow(0 0 6px var(--rg-gold)); }
:root[data-skin="game"] body.s-arcade .cp-rg-hear { font: 400 10px/1.4 var(--a-hud); }
:root[data-skin="game"][data-theme$="-light"] body.s-arcade .cp-rg :is(.cp-rg-bar[data-on], .cp-rg-needle) { filter: none; }
:root[data-skin="game"][data-theme$="-light"] body.s-arcade .cp-rg .cp-rg-year-n { color: var(--rg-ink); }

/* Gospel and soul runs (site/courses/gospel-runs), to Hillel's design of 2026-11-18: an 1870s songbook. Libre Caslon
   Display and Text for the headings, their second halves in italic, a drop cap on the lead, numbers and labels in the
   system monospace (docs/course-pages-polish.md, docs/courses/gospel-runs-love-letter.md). The hero's stairs (the major
   pentatonic from C4 to C5, F and B dashed gaps) rise in wine under the title, a dark band under them with the run's
   button; the demos sit in night-indigo decks (one run at three speeds, clean and smeared, the blue note's bend with its
   slider); the outcomes and the units step like stairs; the archive on music staves; the close dark with the stairs
   coming down beside it. Calm light and dark, and the game skin's night, square frames and arcade type. Sounds:
   js/public/gospel-runs.js. */
.cp-gospel { --gr-serif: 'Libre Caslon Text', ui-serif, 'Iowan Old Style', 'Palatino Linotype', Palatino, Georgia, serif;
    --gr-display: 'Libre Caslon Display', 'Libre Caslon Text', ui-serif, 'Iowan Old Style', 'Palatino Linotype', Palatino, Georgia, serif;
    --gr-mono: var(--font-mono, ui-monospace, 'SF Mono', Menlo, monospace);
    --gr-wash: color-mix(in srgb, #8a2d4b 7%, var(--color-ink)); --gr-tan: color-mix(in srgb, #8a5a2d 9%, var(--color-ink));
    --gr-card: color-mix(in srgb, #fff 55%, var(--color-ink)); --gr-rule: #d9cabd; --gr-ink: #221a1f; --gr-body: #3e3438; --gr-muted: #5a4e52;
    --gr-label: #8a2d4b; --gr-stair: #8a2d4b; --gr-tread: #b8576f; --gr-stair-ink: #fbf3ee; --gr-gap: #a98e8d; --gr-gap-ink: #6f5d61;
    --gr-gold: #f2c063; --gr-gold-ink: #221a1f; --gr-amber: #a8701a; --gr-free: #2c6b46;
    --gr-night: #221a1f; --gr-night-ink: #f3e9e1; --gr-night-body: #c9b8b2; --gr-night-chip: #3a2e32;
    --gr-deck: #18142a; --gr-deck-2: #221d3a; --gr-deck-ink: #ece6f2; --gr-deck-body: #c8c1d8; --gr-deck-muted: #a39cb8; --gr-deck-rule: rgb(255 255 255 / .1);
    --gr-blue: #8ea2ee; --gr-rose: #e9a8bd; --gr-bar: #b07a91;
    --cp-a: #8a2d4b; --cp-a-ink: #fff; --cp-a-text: #8a2d4b; --cp-line: var(--gr-rule); color: var(--gr-ink); }
:root:not([data-theme$="-light"]) .cp-gospel { --gr-wash: color-mix(in srgb, #e9a8bd 7%, var(--color-ink)); --gr-tan: color-mix(in srgb, #f2c063 6%, var(--color-ink));
    --gr-card: color-mix(in srgb, #fff 6%, var(--color-ink)); --gr-rule: color-mix(in srgb, #fff 16%, var(--color-ink)); --gr-ink: #f6eff1; --gr-body: #dccfd3; --gr-muted: #bfb0b5;
    --gr-label: #f2a7c0; --gr-stair: #8a2d4b; --gr-tread: #d0718f; --gr-gap: #8d7378; --gr-gap-ink: #c4b1b6; --gr-amber: #f2c063; --gr-free: #7fd49c;
    --gr-night: color-mix(in srgb, #8a2d4b 16%, var(--color-ink)); --gr-night-chip: color-mix(in srgb, #fff 12%, var(--gr-night));
    --cp-a-text: #f2a7c0; }
:root[data-skin="game"]:not([data-theme$="-light"]) .cp-gospel { --gr-wash: #0c0a17; --gr-tan: #0f0c1c; --gr-card: #12101e; --gr-rule: #2a2640; --gr-ink: #f7f4ff; --gr-body: #d2ccf0; --gr-muted: #b8b2d8;
    --gr-label: #ffd84a; --gr-stair: #ff5fd2; --gr-tread: #3be7ff; --gr-stair-ink: #07060e; --gr-gap: #6a6490; --gr-gap-ink: #b8b2d8; --gr-amber: #ffd84a; --gr-free: #a3e635;
    --gr-night: #07060e; --gr-night-chip: #1c1830; --gr-deck: #07060e; --gr-deck-2: #12101e; --gr-blue: #3be7ff; --gr-rose: #ff5fd2; --gr-bar: #3be7ff;
    --cp-a: #ffd84a; --cp-a-ink: #1a1404; --cp-a-text: #ffd84a; }
.cp-gospel > section:not(.cp-gr-hero, .cp-gr-demosec, .cp-gr-blue, .cp-gr-archive, .cp-gr-firstsec, .cp-gr-close, .cp-gr-sources, .cp-gr-kit, .cp-gr-intro) { padding-block: clamp(48px, 6vw, 72px) 0; }
.cp-gospel .s-cite a { padding: 0 2px; color: var(--gr-label); text-decoration: none; }
.cp-gospel :is(.cp-gr-deck, .cp-gr-band, .cp-gr-blue, .cp-gr-close) .s-cite a { color: var(--gr-gold); }
.cp-gospel :is(button, input, summary, a):focus-visible { outline: 3px solid var(--gr-label); outline-offset: 3px; }
.cp-gospel :is(.cp-gr-deck, .cp-gr-band, .cp-gr-blue, .cp-gr-close) :is(button, input, summary, a):focus-visible { outline-color: var(--gr-gold); }
.cp-gr-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

/* Type: Caslon headings, the second half in italic; labels in the monospace, tracked capitals. */
.cp-gr-kick { font: 500 12px/1.4 var(--gr-mono); letter-spacing: .14em; text-transform: uppercase; color: var(--gr-label); }
.cp-gr-h, .cp-gr-h1 { font-family: var(--gr-display); font-weight: 400; letter-spacing: -0.01em; text-wrap: balance; }
.cp-gr-h { margin-top: 14px; font-size: clamp(36px, 5.4vw, 64px); line-height: 1.02; }
:is(.cp-gr-h, .cp-gr-h1, .cp-gr-h3) em { font-family: var(--gr-serif); font-style: italic; font-size: .88em; }
.cp-gr-h3 { font-family: var(--gr-serif); font-weight: 400; font-size: clamp(25px, 3vw, 30px); line-height: 1.15; }
.cp-gr-body { margin-top: 18px; max-width: 60ch; font-size: clamp(16px, 1.9vw, 18px); line-height: 1.65; color: var(--gr-body); text-wrap: pretty; }
.cp-gr-sub { margin-top: 12px; max-width: 60ch; font-size: clamp(16px, 1.8vw, 18px); line-height: 1.5; color: var(--gr-muted); }
.cp-gr-small { margin-top: 6px; font-size: 16px; line-height: 1.55; color: var(--gr-muted); }
.cp-gr-note { margin-top: 14px; max-width: 62ch; font-size: 14px; line-height: 1.55; color: var(--gr-muted); }
.cp-gr-btns { display: flex; flex-wrap: wrap; gap: 12px; }
@media (max-width: 639px) { .cp-gr-btns { flex-direction: column; align-items: stretch; } .cp-gr-btns a { justify-content: center; } }
.cp-gospel :is(.btn-primary, .btn-secondary) { white-space: nowrap; }

/* The demo buttons: a pill with a round play mark (a square stop while it plays). */
.cp-gr-btn { display: inline-flex; align-items: center; gap: 10px; min-height: 44px; padding: 6px 20px 6px 6px; border-radius: 99px; font-family: inherit; font-size: 15px; font-weight: 600; line-height: 1.2; white-space: nowrap; cursor: pointer; }
.cp-gr-btn-icon { flex: none; display: grid; place-items: center; width: 32px; height: 32px; border-radius: 99px; }
@media (max-width: 399px) { .cp-gr-btn { gap: 8px; padding-right: 14px; font-size: 14px; } }
.cp-gr-btn-icon::before { content: ""; width: 0; height: 0; margin-left: 3px; border-block: 5.5px solid transparent; border-left: 9px solid currentColor; }
.cp-gr-btn[aria-pressed="true"] .cp-gr-btn-icon::before { width: 10px; height: 10px; margin: 0; border: 0; background: currentColor; }
.cp-gr-btn-gold { background: var(--gr-gold); color: var(--gr-gold-ink); }
.cp-gr-btn-gold .cp-gr-btn-icon { background: var(--gr-gold-ink); color: var(--gr-gold); }
.cp-gr-btn-gold:hover { background: color-mix(in srgb, var(--gr-gold) 88%, #fff); }
.cp-gr-btn-line { background: transparent; color: var(--gr-deck-ink); box-shadow: inset 0 0 0 1.5px var(--gr-deck-ink); }
.cp-gr-btn-line .cp-gr-btn-icon { background: var(--gr-rose); color: var(--gr-deck); }
.cp-gr-btn-line:hover { background: rgb(255 255 255 / .08); }

/* The hero: the trail and the size, the title over the low stairs, then a dark band with the run's button. */
.cp-gr-hero { background: var(--gr-wash); border-bottom: 1px solid var(--gr-rule); overflow: hidden; }
.cp-gr-hero-in { padding-top: 16px; }
.cp-gr-hero-top { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 4px 16px; }
.cp-gospel .s-crumb { color: var(--gr-muted); } .cp-gospel .s-crumb a { color: var(--gr-ink); font-weight: 500; }
.cp-gr-chip { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 10px; font: 500 12px/1.3 var(--gr-mono); letter-spacing: .06em; text-transform: uppercase; color: var(--gr-muted); }
.cp-gr-chip b { padding: 4px 10px; border-radius: 99px; background: var(--gr-ink); color: var(--gr-wash); font-weight: 500; }
.cp-gr-stage { position: relative; display: grid; gap: 22px; margin-top: 14px; }
.cp-gr-eyebrow { font: italic 400 clamp(17px, 2vw, 19px)/1.3 var(--gr-serif); color: var(--gr-label); }
.cp-gr-h1 { margin-top: 8px; font-size: clamp(48px, 8.4vw, 104px); line-height: .94; letter-spacing: -0.02em; }
.cp-gr-h1 em { display: block; }
.cp-gr-stairs { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)) minmax(0, .5fr) repeat(2, minmax(0, 1fr)) minmax(0, .5fr) minmax(0, 1fr); gap: 2px; align-items: end; height: clamp(240px, 52vw, 330px); }
.cp-gr-stair, .cp-gr-gap { display: flex; flex-direction: column; justify-content: space-between; align-items: flex-start; min-width: 0; height: calc(28% + var(--rise) * 10.2%); padding: 10px 6px 8px; border-radius: 4px 4px 0 0; text-align: left; }
.cp-gr-stair { border: 0; border-top: 6px solid var(--gr-tread); background: var(--gr-stair); color: var(--gr-stair-ink); cursor: pointer; transition: background .12s, border-color .12s; }
.cp-gr-stair:hover { background: color-mix(in srgb, var(--gr-stair) 88%, #fff); }
.cp-gr-stair[data-on] { background: var(--gr-gold); border-top-color: color-mix(in srgb, var(--gr-gold) 70%, #fff); color: var(--gr-gold-ink); }
.cp-gr-gap { border: 1.5px dashed var(--gr-gap); border-bottom: 0; color: var(--gr-gap-ink); }
:is(.cp-gr-stair, .cp-gr-gap) i { font: italic 400 clamp(19px, 3.2vw, 30px)/1 var(--gr-serif); }
.cp-gr-gap i { font-size: clamp(16px, 2.2vw, 20px); }
:is(.cp-gr-stair, .cp-gr-gap) > span { font: 500 10.5px/1.2 var(--gr-mono); letter-spacing: .06em; text-transform: uppercase; }
.cp-gr-off { display: none; }
.cp-gr-off::before { content: " \00b7  "; white-space: pre; }
@media (min-width: 640px) { .cp-gr-stairs { gap: 6px; } .cp-gr-stair, .cp-gr-gap { padding: 14px 12px 10px; } }
@media (min-width: 900px) {
    .cp-gr-hero-in { padding-top: 28px; }
    .cp-gr-stage { display: block; height: 440px; margin-top: 18px; }
    .cp-gr-hero-copy { position: absolute; inset: 0 auto auto 0; z-index: 1; max-width: 640px; pointer-events: none; }
    .cp-gr-stairs { position: absolute; inset: 0; height: auto; grid-template-columns: repeat(8, minmax(0, 1fr)); }
    .cp-gr-stair, .cp-gr-gap { height: calc(16% + var(--rise) * 10.7%); }
    .cp-gr-off { display: inline; }
}
.cp-gr-band { background: var(--gr-night); color: var(--gr-night-ink); }
.cp-gr-band-in { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 14px 28px; padding-block: 16px; }
.cp-gr-band-note { flex: 1 1 420px; max-width: 760px; font-size: 13.5px; line-height: 1.55; color: var(--gr-night-body); text-wrap: pretty; }
.cp-gr-band-key { color: var(--gr-night-ink); }

/* The lead with its drop cap, beside the facts and the ways in. */
.cp-gr-intro { display: grid; gap: 32px; padding-block: clamp(40px, 6vw, 64px) 8px; }
@media (min-width: 900px) { .cp-gr-intro { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 56px; align-items: center; } }
.cp-gr-lead { font: 400 clamp(19px, 2.2vw, 22px)/1.55 var(--gr-serif); color: var(--gr-body); text-wrap: pretty; }
.cp-gr-lead::first-letter { float: left; padding: 6px 10px 0 0; font: 400 76px/.8 var(--gr-display); color: var(--gr-label); }
.cp-gr-intro-side { display: grid; gap: 24px; }
.cp-gr-diamonds { display: grid; gap: 10px; font-size: 15px; color: var(--gr-body); }
.cp-gr-diamonds li, .cp-gr-ticks li { position: relative; padding-left: 22px; }
.cp-gr-diamonds li::before, .cp-gr-ticks li::before { content: ""; position: absolute; left: 1px; top: .5em; width: 7px; height: 7px; background: var(--gr-label); rotate: 45deg; }

/* The decks: night indigo, a mono bar, panels side by side with hairlines between. */
.cp-gr-demosec { padding-top: clamp(32px, 5vw, 48px); }
.cp-gr-deck { border-radius: 6px; overflow: hidden; background: var(--gr-deck); color: var(--gr-deck-ink); }
.cp-gr-deck-bar { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 6px 12px; padding: 14px 20px; border-bottom: 1px solid var(--gr-deck-rule); font: 500 11px/1.4 var(--gr-mono); letter-spacing: .12em; text-transform: uppercase; color: var(--gr-deck-muted); }
.cp-gr-live { display: inline-flex; align-items: center; gap: 8px; color: var(--gr-deck-ink); }
.cp-gr-live i { width: 7px; height: 7px; border-radius: 99px; background: var(--gr-rose); }
.cp-gr-panels { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 1px; background: var(--gr-deck-rule); }
.cp-gr-panels-two { grid-template-columns: repeat(2, minmax(0, 1fr)); }
.cp-gr-panel { padding: 22px 20px 16px; background: var(--gr-deck); }
.cp-gr-panel svg { display: block; width: 100%; height: auto; }
@media (max-width: 719px) { .cp-gr-panel { padding: 14px 10px 10px; } }
.cp-gr-row { stroke: rgb(255 255 255 / .1); stroke-width: 1; vector-effect: non-scaling-stroke; }
.cp-gr-through { fill: none; stroke: #7c6a8a; stroke-width: 1.2; vector-effect: non-scaling-stroke; }
.cp-gr-note { fill: var(--gr-bar); transition: fill .15s; }
.cp-gr-note[data-on] { fill: var(--gr-gold); }
.cp-gr-panel-foot { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: baseline; gap: 4px 12px; margin-top: 14px; padding-top: 10px; border-top: 1px solid rgb(255 255 255 / .14); }
.cp-gr-panel-foot span:first-child { font: italic 400 clamp(15px, 2.2vw, 22px)/1.2 var(--gr-serif); transition: color .15s; }
@media (max-width: 719px) { .cp-gr-panel-foot { margin-top: 8px; padding-top: 6px; } .cp-gr-panel-foot span + span { font-size: 10px; } }
.cp-gr-panel-foot span + span { font: 400 12px/1.3 var(--gr-mono); color: var(--gr-deck-muted); }
.cp-gr-panel[data-on] .cp-gr-panel-foot span:first-child { color: var(--gr-gold); }
.cp-gr-deck-cap { display: grid; gap: 28px; padding: clamp(22px, 3.4vw, 36px) clamp(18px, 3vw, 32px); border-top: 1px solid var(--gr-deck-rule); }
