@media (min-width: 1000px) { .cp-gr-goals { grid-template-columns: repeat(4, minmax(0, 1fr)); align-items: start; } .cp-gr-goals li:nth-child(2) { margin-top: 14px; } .cp-gr-goals li:nth-child(3) { margin-top: 28px; } .cp-gr-goals li:nth-child(4) { margin-top: 42px; } }
.cp-gr-goals li { padding-top: 14px; border-top: 2px solid var(--gr-ink); counter-increment: goal; }
.cp-gr-goals li::before { content: counter(goal, lower-roman) "."; display: block; font: 400 clamp(36px, 4vw, 44px)/1 var(--gr-display); color: var(--gr-label); }
