.cp-gr-mel-end { display: inline-block; translate: 0 1.2em; }
.cp-gr-melisma figcaption { margin-top: 8px; font: 500 12px/1.5 var(--gr-mono); letter-spacing: .06em; text-transform: uppercase; color: var(--gr-muted); }
