@media (min-width: 760px) and (max-width: 999px) { .cp-gr-years li { grid-template-columns: minmax(0, 220px) minmax(0, 1fr); } }
.cp-gr-staff { grid-column: 1 / -1; position: relative; height: 17px; background: repeating-linear-gradient(to bottom, color-mix(in srgb, var(--gr-muted) 45%, transparent) 0 1px, transparent 1px 4px); }
.cp-gr-staff i { position: absolute; left: 0; top: calc(10px - var(--k) * 2px); width: 14px; height: 10px; border-radius: 50%; background: var(--gr-label); rotate: -20deg; }
