.cp-gr-more { border-top: 1px solid var(--gr-rule); }
.cp-gr-more > summary { display: flex; align-items: center; justify-content: space-between; gap: 16px; min-height: 56px; font-size: 17px; font-weight: 600; color: var(--gr-label); cursor: pointer; list-style: none; }
