@media (min-width: 1000px) { .cp-gr-units { grid-template-columns: repeat(4, minmax(0, 1fr)); align-items: start; } .cp-gr-unit:nth-child(1) { margin-top: 72px; } .cp-gr-unit:nth-child(2) { margin-top: 48px; } .cp-gr-unit:nth-child(3) { margin-top: 24px; } }
