@media (max-width: 719px) { .cp-gr-unit:not(:first-child) .cp-gr-lessons { display: none; } }
.cp-gr-tail { margin-top: 14px; text-align: right; font: italic 400 16px/1.4 var(--gr-serif); color: var(--gr-muted); }

/* Lesson 1, set out as lining out, beside what the app listens for. */
.cp-gr-firstsec { margin-top: clamp(48px, 6vw, 72px); background: var(--gr-wash); border-block: 1px solid var(--gr-rule); }
.cp-gr-first { display: grid; gap: 36px; padding-bottom: clamp(48px, 6vw, 72px); }
@media (min-width: 960px) { .cp-gr-first { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 56px; align-items: start; } .cp-gr-inside { margin-top: 40px; } }
.cp-gr-lining { margin-top: 26px; border-top: 2px solid var(--gr-ink); }
.cp-gr-lining li { display: grid; grid-template-columns: 64px minmax(0, 1fr); gap: 12px; align-items: baseline; padding: 12px 0; border-bottom: 1px solid var(--gr-rule); }
