@media (min-width: 960px) { .cp-gr-fine { grid-template-columns: minmax(0, 1fr) minmax(0, 2fr); gap: 40px; } }
.cp-gr-faq-h { margin-top: 0; line-height: 1; }
.cp-gr-faq-h em { display: block; font-size: .6em; color: var(--gr-label); }
