/* The close: dark, the stairs coming down beside it. */
.cp-gr-close { margin-top: clamp(56px, 7vw, 80px); overflow: hidden; background: var(--gr-night); color: var(--gr-night-ink);
    --primary: var(--gr-gold); --primary-ink: var(--gr-gold-ink); --primary-hover-to: #fff; --btn-soft: transparent; --btn-soft-hover: rgb(255 255 255 / .08); --btn-outline: inset 0 0 0 1.5px var(--gr-night-ink); --color-cream: var(--gr-night-ink); }
