.cp-gr-close-copy { padding-bottom: clamp(8px, 4vw, 88px); }
.cp-gr-close .cp-gr-kick { color: var(--gr-gold); }
.cp-gr-h-close { font-size: clamp(48px, 5.6vw, 76px); line-height: .98; }
.cp-gr-close .cp-gr-body { margin-bottom: 28px; color: var(--gr-night-body); }
