.cp-gr-close-stairs { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 6px; align-items: end; height: clamp(220px, 40vw, 420px); }
.cp-gr-close-stairs span { height: calc(26% + var(--step) * 8.2%); padding: 14px 10px; border-top: 6px solid var(--gr-tread); background: var(--gr-stair); color: var(--gr-stair-ink); font: italic 400 clamp(19px, 2.4vw, 24px)/1 var(--gr-serif); }
.cp-gr-close-stairs span:first-child { border-top-color: var(--gr-gold); }

/* The sources: two columns, folded on a phone. */
.cp-gr-sources { padding-block: 32px 24px; }
.cp-gr-sources summary { display: flex; align-items: center; min-height: 44px; list-style: none; cursor: pointer; }
.cp-gr-sources summary::-webkit-details-marker { display: none; }
.cp-gr-sources summary h2::after { content: " +"; } .cp-gr-sources details[open] summary h2::after { content: ""; }
.cp-gr-sources ol { margin-top: 16px; padding-left: 24px; list-style: decimal; columns: 3 300px; column-gap: 40px; font-size: 13px; line-height: 1.55; color: var(--gr-muted); }
.cp-gr-sources li { margin-bottom: 6px; break-inside: avoid; scroll-margin-top: 90px; overflow-wrap: anywhere; }
.cp-gr-sources a { color: var(--gr-body); text-underline-offset: 3px; }

@media (prefers-reduced-motion: reduce) { .cp-gospel :is(.cp-gr-stair, .cp-gr-note, .cp-gr-seg, .cp-gr-bendline, .cp-gr-panel-foot span, .cp-gr-panel-name, .cp-faq-sign) { transition: none; } }

/* The game skin: the arcade's night, square frames with a hard offset shadow, arcade type for headings and labels. */
:root[data-skin="game"] body.s-arcade .cp-gospel :is(.cp-gr-h, .cp-gr-h1, .cp-gr-h3, .cp-gr-year, .cp-gr-big, .cp-gr-meter b) { font-family: var(--a-display); font-weight: 400; font-style: normal; letter-spacing: .01em; text-transform: uppercase; font-size-adjust: var(--arc-ex, none); }
