:root[data-skin="game"][data-theme$="-light"] body.s-arcade .cp-gospel :is(.cp-gr-h, .cp-gr-h1, .cp-gr-h3) em { color: var(--gr-label); }
:root[data-skin="game"] body.s-arcade .cp-gospel :is(.cp-gr-deck, .cp-gr-close) :is(.cp-gr-h, .cp-gr-h3) em { color: var(--gr-gold); }
:root[data-skin="game"] body.s-arcade .cp-gospel .cp-gr-blue .cp-gr-h em { color: var(--gr-blue); }
:root[data-skin="game"] body.s-arcade .cp-gospel .cp-gr-h1 { font-size: clamp(38px, 7vw, 76px); line-height: 1.02; }
:root[data-skin="game"] body.s-arcade .cp-gospel .cp-gr-h { font-size: clamp(28px, 4.4vw, 46px); }
:root[data-skin="game"] body.s-arcade .cp-gospel .cp-gr-h3 { font-size: clamp(20px, 2.4vw, 24px); }
:root[data-skin="game"] body.s-arcade .cp-gospel :is(.cp-gr-year, .cp-gr-big) { font-size: clamp(30px, 4vw, 42px); color: var(--gr-label); }
