:root[data-skin="game"] body.s-arcade .cp-gospel :is(.cp-gr-deck, .cp-gr-inside, .cp-gr-unit) { border-radius: 0; border: 2px solid #ffd84a; box-shadow: 6px 6px 0 #3be7ff; }
:root[data-skin="game"] body.s-arcade .cp-gospel .cp-gr-unit:not(.cp-gr-unit-night) { background: var(--a-panel, var(--gr-card)); color: var(--gr-ink); }
:root[data-skin="game"] body.s-arcade .cp-gospel .cp-gr-unit-n::before { display: none; }
:root[data-skin="game"] body.s-arcade .cp-gospel .cp-gr-unit-label { position: static; width: auto; height: auto; clip-path: none; font: 400 9.5px/1.4 var(--a-hud); letter-spacing: .06em; text-transform: uppercase; color: var(--gr-label); font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade .cp-gospel :is(.cp-gr-stair, .cp-gr-gap, .cp-gr-close-stairs span, .cp-gr-btn, .cp-gr-btn-icon, .cp-gr-chip b, .cp-gr-free, .cp-related a, .cp-gr-lane) { border-radius: 0; }
