:root[data-skin="game"] body.s-arcade .cp-gospel .cp-gr-btn { box-shadow: 4px 4px 0 #3be7ff; }
:root[data-skin="game"] body.s-arcade .cp-gospel .cp-gr-btn-line { box-shadow: inset 0 0 0 2px var(--gr-deck-ink), 4px 4px 0 #3be7ff; }
:root[data-skin="game"] body.s-arcade .cp-gospel .cp-gr-lead::first-letter { font-family: var(--a-display); font-size: 56px; font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade .cp-gospel :is(.cp-gr-lead, .cp-gr-fact, .cp-gr-mel, .cp-gr-tail, .cp-faq details p) { font-family: Figtree, system-ui, sans-serif; font-style: normal; font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade .cp-gospel .cp-gr-goals li::before { font-family: var(--a-display); font-size: 30px; font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade .cp-gospel :is(.cp-gr-eyebrow, .cp-gr-stair i, .cp-gr-gap i, .cp-gr-close-stairs span, .cp-gr-panel-foot span:first-child, .cp-gr-panel-name, .cp-gr-who, .cp-gr-years h3, .cp-gr-unit h3, .cp-gr-kit-grid h3) { font-family: var(--a-display); font-style: normal; font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade .cp-gospel :is(.cp-gr-stair i, .cp-gr-close-stairs span) { font-size: clamp(14px, 2vw, 22px); }

/* Diction for singers (site/courses/diction): a love letter in Vibrato's calm, light design
   (docs/course-pages-polish.md, docs/courses/diction-love-letter.md). The hero's vowel map (ee, ah and oo
   on the F2 and F1 plane, and the e of "head") in its own card with a legend; the featured deck (a vowel
   made of filters: the note's harmonics as lines, the two filters' shape over them); three cards on why
   sung words blur; the beat deck (the t on the click or just before it); thin headlines and quiet tracked
   labels in a deep teal ink; the archive on a wash, the units in a row. Game skin: square arcade frames on
   the night, gold and cyan. Sounds: js/public/diction.js. */
.cp-diction { --di-wash: color-mix(in srgb, #1d5e72 7%, var(--color-ink)); --di-card: #fff; --di-rule: color-mix(in srgb, #1d5e72 14%, #d8d6d2); --di-ink: #13202a; --di-body: #3c4a52; --di-muted: #51606a; --di-label: #1d5e72;
    --di-dot: #1d5e72; --di-ring: #a85a00; --di-free: #1f7a45;
    --cp-a: #1d5e72; --cp-a-ink: #fff; --cp-a-text: #1d5e72; color: var(--di-ink); }
:root:not([data-theme$="-light"]) .cp-diction { --di-wash: color-mix(in srgb, #8fd3e0 6%, var(--color-ink)); --di-card: color-mix(in srgb, #fff 5%, var(--color-ink)); --di-rule: color-mix(in srgb, #fff 16%, var(--color-ink)); --di-ink: #eef5f7; --di-body: #cfdde2; --di-muted: #b0c0c6; --di-label: #8fd3e0;
    --di-dot: #6cc4d6; --di-ring: #ffc66b; --di-free: #7fd49c; --cp-a-text: #8fd3e0; }
:root[data-skin="game"]:not([data-theme$="-light"]) .cp-diction { --di-wash: #0c0a17; --di-card: #12101e; --di-rule: #2a2640; --di-ink: #f7f4ff; --di-body: #d2ccf0; --di-muted: #b8b2d8; --di-label: #ffd84a;
    --di-dot: #3be7ff; --di-ring: #ff5fd2; --di-free: #a3e635; --cp-a: #ffd84a; --cp-a-ink: #1a1404; --cp-a-text: #ffd84a; }
.cp-diction > section:not(.cp-di-hero, .cp-dk-demosec, .cp-di-archive, .cp-di-climbsec, .cp-di-close, .cp-di-sources) { padding-block: clamp(56px, 9vw, 104px) 0; }
.cp-diction .cp-dk-demo-bar .cp-dk-live { white-space: nowrap; }
@media (max-width: 639px) { .cp-di-goals li { padding: 12px 0 14px; } .cp-di-goals p { margin-top: 8px; font-size: 16px; } .cp-di-steps li { padding: 12px 14px; } .cp-diction .cp-dk-demo-lead { font-size: 15px; } }

/* Type: light and calm. */
.cp-di-kick { font-size: 12.5px; font-weight: 600; letter-spacing: .24em; text-transform: uppercase; color: var(--di-label); }
:root[data-skin="game"] body.s-arcade .cp-di-kick { font-family: var(--a-hud); font-size: 9.5px; font-weight: 400; letter-spacing: .1em; font-size-adjust: var(--arc-ex, none); }
:root:not([data-skin="game"]) .cp-diction .cp-hero h1 { font-weight: 300; font-size: clamp(44px, 9.5vw, 88px); line-height: .98; letter-spacing: -0.045em; }
.cp-di-title { margin-top: 12px; font-size: clamp(32px, 5.6vw, 54px); line-height: 1.04; font-weight: 300; letter-spacing: -0.04em; text-wrap: balance; }
:root[data-skin="game"] body.s-arcade .cp-diction .cp-di-title { font-family: var(--a-display); font-weight: 400; letter-spacing: .01em; text-transform: uppercase; font-size: clamp(28px, 4.6vw, 44px); font-size-adjust: var(--arc-ex, none); }
.cp-di-h3 { font-size: 21px; font-weight: 500; letter-spacing: -0.015em; }
.cp-di-body { margin-top: 18px; max-width: 58ch; font-size: clamp(16px, 1.9vw, 18px); line-height: 1.65; color: var(--di-body); text-wrap: pretty; }
.cp-di-small { margin-top: 10px; font-size: 15px; line-height: 1.6; color: var(--di-body); }
.cp-di-note, .cp-di-quiet { margin-top: 14px; max-width: 60ch; font-size: 14px; line-height: 1.6; color: var(--di-muted); }
.cp-diction .s-cite a { padding: 0 2px; color: var(--di-label); text-decoration: none; }
.cp-diction .cp-dk-demo .s-cite a { color: var(--pd-gold); }
.cp-di-card { border-radius: 22px; background: var(--di-card); border: 1px solid var(--di-rule); }
.cp-diction :is(button, input, summary, a):focus-visible { outline: 3px solid var(--di-label); outline-offset: 3px; }

/* The hero: a wash, and the vowel map in its own card. */
:root:not([data-skin="game"]) .cp-di-hero { background: linear-gradient(180deg, var(--di-wash), color-mix(in srgb, var(--di-wash) 25%, var(--color-ink))); }
:root[data-skin="game"] body.s-arcade .cp-di-hero { background: radial-gradient(70% 80% at 72% 40%, color-mix(in srgb, #3be7ff 8%, var(--a-bg)), var(--a-bg)); }
:root:not([data-skin="game"]) .cp-diction .cp-hero-facts li { color: var(--di-muted); }
.cp-diction .cp-hero-card { background: var(--di-card); border-color: var(--di-rule); }
.cp-di-map { margin: 0; }
.cp-di-map-art { display: block; width: 100%; height: auto; max-height: 420px; }
.cp-di-grid { stroke: var(--di-rule); stroke-width: 1; }
.cp-di-tick { font: 500 14px/1 ui-monospace, "SF Mono", Menlo, monospace; fill: var(--di-muted); }
.cp-di-axis { font: 600 14px/1 Figtree, system-ui, sans-serif; fill: var(--di-body); }
.cp-di-tri { fill: color-mix(in srgb, var(--di-dot) 8%, transparent); stroke: var(--di-dot); stroke-width: 1.5; stroke-dasharray: 5 5; stroke-linejoin: round; }
.cp-di-dot { fill: var(--di-dot); stroke: var(--di-card); stroke-width: 3; }
.cp-di-ring { fill: none; stroke: var(--di-ring); stroke-width: 3; }
.cp-di-vname { font: 700 22px/1 Figtree, system-ui, sans-serif; fill: var(--di-ink); }
.cp-di-vname-head { font-size: 16px; font-weight: 600; fill: var(--di-body); }
.cp-diction .cp-hero-legend { color: var(--di-muted); border-color: var(--di-rule); }
.cp-di-key { width: 12px !important; height: 12px !important; }
.cp-di-key-dot { background: var(--di-dot); }
.cp-di-key-ring { background: none; border: 2.5px solid var(--di-ring); }
.cp-di-map-note { margin-top: 12px; font-size: 14px; line-height: 1.5; color: var(--di-muted); }
:root[data-skin="game"] body.s-arcade :is(.cp-di-dot, .cp-di-ring, .cp-di-tri) { filter: drop-shadow(0 0 4px var(--di-dot)); }
:root[data-skin="game"] body.s-arcade .cp-di-vname { font-family: var(--a-hud); font-size: 15px; font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade .cp-di-vname-head { font-size: 11px; }

/* The featured deck: the note's harmonics as lines, the filters' shape over them, the readout above. */
.cp-diction .cp-dk-demo { --pd-rose: #7fd3e0; --pd-gold: #ffc66b; }
:root[data-skin="game"] .cp-diction .cp-dk-demo { --pd-rose: #3be7ff; --pd-gold: #ffd84a; --pd-edge: #3be7ff66; box-shadow: 0 0 40px -16px #3be7ff; }
.cp-di-roll { position: relative; }
.cp-di-read { display: flex; flex-wrap: wrap; align-items: baseline; gap: 2px 14px; padding: 2px 4px 8px; font-variant-numeric: tabular-nums; }
.cp-di-read b { font-size: clamp(30px, 5vw, 44px); font-weight: 800; line-height: 1; color: var(--pd-gold); }
.cp-di-read span { font: 600 14px/1.3 ui-monospace, "SF Mono", Menlo, monospace; color: var(--pd-body); }
:root[data-skin="game"] body.s-arcade .cp-di-read b { font-family: var(--a-display); font-weight: 400; font-size-adjust: var(--arc-ex, none); }
.cp-di-hz { stroke: var(--pd-staff); stroke-width: 1; stroke-dasharray: 3 5; vector-effect: non-scaling-stroke; }
.cp-di-harm { stroke: var(--pd-gold); stroke-width: 3; stroke-linecap: round; vector-effect: non-scaling-stroke; transition: d .12s; }
.cp-di-curve { fill: color-mix(in srgb, var(--pd-rose) 14%, transparent); stroke: var(--pd-rose); stroke-width: 2.5; stroke-linejoin: round; vector-effect: non-scaling-stroke; }
:root[data-skin="game"] body.s-arcade .cp-di-curve { filter: drop-shadow(0 0 4px var(--pd-rose)); }
.cp-di-scale { position: relative; height: 20px; margin-top: 4px; font: 500 12px/1 ui-monospace, "SF Mono", Menlo, monospace; color: var(--pd-muted); }
.cp-di-scale span { position: absolute; top: 4px; left: calc(var(--at) * 100%); translate: calc(var(--at) * -100%) 0; white-space: nowrap; }
.cp-di-pick { margin-top: 0; }
.cp-di-pick + .cp-di-pick { margin-top: 14px; }
.cp-diction .cp-di-pick + .cp-dk-btns { margin-top: 18px; }
.cp-di-dkey { width: 22px; height: 10px; border-radius: 99px; }
.cp-dk-key .cp-di-dkey-line { width: 4px; height: 16px; background: var(--pd-gold); }
.cp-dk-key .cp-di-dkey-curve { height: 0; background: none; border-top: 3px solid var(--pd-rose); border-radius: 0; }
.cp-dk-key .cp-di-dkey-t { border-radius: 2px; background: repeating-linear-gradient(90deg, #c9d6db 0 2px, transparent 2px 4px); }
.cp-dk-key .cp-di-dkey-v { background: var(--pd-rose); }
.cp-dk-key .cp-di-dkey-beat { width: 0; height: 16px; background: none; border-left: 2px dashed var(--pd-muted); border-radius: 0; }
@media (min-width: 640px) { .cp-diction .cp-dk-big[aria-pressed="true"] { inset: 12px 12px auto auto; } }
@media (prefers-reduced-motion: reduce) { .cp-di-harm, .cp-di-t, .cp-di-v { transition: none; } .cp-di-v[data-on], .cp-di-beatline[data-on] { filter: none; } }

/* By the end: four ruled columns. */
.cp-di-goals { display: grid; gap: 0 24px; margin-top: 20px; }
@media (min-width: 720px) { .cp-di-goals { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (min-width: 1100px) { .cp-di-goals { grid-template-columns: repeat(4, minmax(0, 1fr)); } }
.cp-di-goals li { padding: 16px 0 20px; border-top: 1.5px solid var(--di-ink); }
.cp-di-n { font: 500 13px/1 ui-monospace, "SF Mono", Menlo, monospace; color: var(--di-label); }
.cp-di-goals p { margin-top: 12px; font-size: 17px; line-height: 1.45; }

/* In plain words: the heading beside its two paragraphs, three cards, then the beat deck beside timing and holding. */
.cp-di-plain-head { display: grid; gap: 4px 56px; }
@media (min-width: 960px) { .cp-di-plain-head { grid-template-columns: minmax(0, 5fr) minmax(0, 7fr); align-items: start; } .cp-di-plain-head .cp-di-body:first-child { margin-top: 30px; } }
.cp-di-blur-h { margin-top: clamp(36px, 5vw, 56px); }
.cp-di-nums { display: grid; gap: 12px; margin-top: 22px; }
@media (min-width: 760px) { .cp-di-nums { grid-template-columns: repeat(3, minmax(0, 1fr)); } }
.cp-di-num { padding: 22px 20px; }
.cp-di-big { font-size: clamp(36px, 4.4vw, 50px); font-weight: 200; line-height: 1; letter-spacing: -0.03em; font-variant-numeric: tabular-nums; color: var(--di-label); white-space: nowrap; }
.cp-di-num h4 { margin-top: 12px; font-size: 12.5px; font-weight: 700; letter-spacing: .14em; text-transform: uppercase; color: var(--di-ink); }
.cp-di-num h4 + p { margin-top: 8px; font-size: 14.5px; line-height: 1.55; color: var(--di-body); }
.cp-di-num:last-child { background: var(--di-wash); }
:root[data-skin="game"] body.s-arcade .cp-di-big { font-family: var(--a-display); font-weight: 400; font-size: clamp(26px, 3.4vw, 34px); font-size-adjust: var(--arc-ex, none); }
@media (max-width: 639px) { .cp-di-nums { gap: 8px; } .cp-di-num { padding: 16px; } .cp-di-big { font-size: 30px; } .cp-di-num h4 { margin-top: 8px; } .cp-di-num h4 + p { font-size: 14px; } }
.cp-di-pair { display: grid; gap: 28px; margin-top: 28px; }
@media (min-width: 960px) { .cp-di-pair { grid-template-columns: minmax(0, 6fr) minmax(0, 5fr); gap: 56px; align-items: start; } }
.cp-di-pair-text .cp-di-h3 + .cp-di-body { margin-top: 10px; }
.cp-di-hold-h { margin-top: 28px; }
@media (min-width: 960px) { .cp-di-pair-text { padding-top: 12px; } }
.cp-di-deck-in { padding: clamp(16px, 3vw, 26px); }
.cp-di-deck-in .cp-dk-btns { margin-top: 16px; }
.cp-di-beat-h { font-size: clamp(22px, 2.6vw, 28px); font-weight: 800; line-height: 1.1; letter-spacing: -0.02em; color: var(--pd-ink); }
:root[data-skin="game"] body.s-arcade .cp-di-beat-h { font-family: var(--a-display); font-weight: 400; text-transform: uppercase; letter-spacing: .01em; font-size-adjust: var(--arc-ex, none); }
.cp-di-beat-lead { margin: 10px 0 16px; font-size: 15px; line-height: 1.55; color: var(--pd-body); }
.cp-di-beat-roll { display: grid; grid-template-columns: 22px minmax(0, 1fr); gap: 8px; align-items: stretch; }
.cp-di-beat-roll svg { height: clamp(110px, 16vw, 150px); }
.cp-di-lanes { display: grid; grid-template-rows: 1fr 1fr; align-items: center; font-weight: 800; font-size: 15px; color: var(--pd-muted); }
.cp-di-lanes span[data-on] { color: var(--pd-gold); }
.cp-di-beatline { stroke: var(--pd-muted); stroke-width: 1.5; stroke-dasharray: 4 5; vector-effect: non-scaling-stroke; transition: stroke .1s; }
.cp-di-beatline[data-on] { stroke: var(--pd-gold); stroke-dasharray: none; filter: drop-shadow(0 0 4px var(--pd-gold)); }
.cp-di-t { fill: #c9d6db; opacity: .45; transition: opacity .1s; }
.cp-di-v { fill: var(--pd-rose); opacity: .45; transition: opacity .1s, fill .1s; }
.cp-di-t[data-on] { opacity: 1; }
.cp-di-v[data-on] { opacity: 1; fill: var(--pd-gold); filter: drop-shadow(0 0 5px var(--pd-gold)); }

/* From the archive: a wash, each year large and thin beside its story. */
.cp-di-archive { margin-top: clamp(56px, 9vw, 104px); background: var(--di-wash); border-block: 1px solid var(--di-rule); }
.cp-di-archive > .s-sec { padding-bottom: clamp(48px, 8vw, 96px); }
.cp-di-years { margin-top: 28px; }
.cp-di-years + .cp-di-more .cp-di-years, .cp-di-facts + .cp-di-more .cp-di-facts { margin-top: 0; }
.cp-di-more { border-top: 1px solid var(--di-rule); }
.cp-di-more > summary { display: flex; align-items: center; justify-content: space-between; gap: 16px; min-height: 56px; font-size: 17px; font-weight: 600; color: var(--di-label); cursor: pointer; list-style: none; }
.cp-di-more > summary::-webkit-details-marker { display: none; }
.cp-di-more[open] > summary .cp-faq-sign { rotate: 45deg; }
@media (min-width: 900px) { .cp-di-more { border-top: 0; } .cp-di-more > summary { display: none; } }
.cp-di-years li { display: grid; gap: 6px 40px; padding-block: 22px; border-top: 1px solid var(--di-rule); }
@media (min-width: 760px) { .cp-di-years li { grid-template-columns: 240px minmax(0, 1fr); } }
.cp-di-year { display: flex; flex-wrap: wrap; align-items: baseline; gap: 4px 12px; font-size: clamp(34px, 5vw, 48px); font-weight: 200; line-height: 1; letter-spacing: -0.03em; font-variant-numeric: tabular-nums; }
@media (min-width: 760px) { .cp-di-year { flex-direction: column; align-items: start; } }
.cp-di-place { font-size: 12.5px; font-weight: 600; line-height: 1.4; letter-spacing: .2em; text-transform: uppercase; color: var(--di-label); }
.cp-di-years h3 { font-size: 21px; font-weight: 500; letter-spacing: -0.015em; }
.cp-di-years h3 + p { margin-top: 8px; max-width: 68ch; font-size: 16px; line-height: 1.65; color: var(--di-body); }
@media (max-width: 639px) { .cp-di-years li { padding-block: 18px; } .cp-di-years h3 + p { font-size: 15.5px; line-height: 1.6; } .cp-di-year { font-size: 30px; } }
:root[data-skin="game"] body.s-arcade .cp-di-year { font-family: var(--a-display); font-weight: 400; font-size: clamp(24px, 3.6vw, 32px); color: #ffd84a; font-size-adjust: var(--arc-ex, none); }

/* The course: a white band, four unit cards in a row on a wide screen. */
.cp-di-climbsec { margin-top: clamp(56px, 9vw, 104px); background: var(--di-card); border-block: 1px solid var(--di-rule); }
:root[data-skin="game"] body.s-arcade .cp-di-climbsec { background: var(--a-panel, var(--di-card)); }
.cp-di-archive + .cp-di-climbsec { margin-top: 0; border-top: 0; }
.cp-di-head { display: flex; flex-wrap: wrap; align-items: baseline; justify-content: space-between; gap: 8px 24px; }
.cp-di-count { font-size: 14px; color: var(--di-muted); }
.cp-di-units { display: grid; gap: 14px; margin-top: 28px; padding-bottom: clamp(48px, 8vw, 96px); }
@media (min-width: 720px) { .cp-di-units { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (min-width: 1100px) { .cp-di-units { grid-template-columns: repeat(4, minmax(0, 1fr)); align-items: start; } .cp-di-unit { margin-top: calc(var(--step) * 22px); } }
.cp-di-unit { padding: 22px 20px; background: color-mix(in srgb, var(--di-wash) 55%, var(--di-card)); }
.cp-di-unit-n { display: flex; align-items: center; gap: 10px; font-size: 12px; font-weight: 600; letter-spacing: .18em; text-transform: uppercase; color: var(--di-muted); }
.cp-di-unit-dot { display: grid; place-items: center; width: 24px; height: 24px; border-radius: 99px; background: var(--di-label); color: var(--di-card); font-size: 12px; letter-spacing: 0; }
.cp-di-unit h3 { margin-top: 14px; font-size: 20px; font-weight: 500; letter-spacing: -0.01em; }
.cp-di-lessons { margin-top: 16px; border-top: 1px solid var(--di-rule); font-size: 14.5px; }
.cp-di-lessons li { display: flex; justify-content: space-between; align-items: center; gap: 8px; padding: 9px 0; border-bottom: 1px solid var(--di-rule); }
