/* The game skin: square arcade frames, as the stage card. */
:root[data-skin="game"] body.s-arcade .cp-diction :is(.cp-di-card, .cp-hero-card, .cp-dk-demo, .cp-di-steps li) { border-radius: 0; border: 2px solid #ffd84a; box-shadow: 6px 6px 0 #3be7ff; }
