.cp-dn-kick-amber { color: var(--dn-amber); }
.cp-dn-ipa { font-family: var(--dn-serif); font-style: italic; word-spacing: .16em; color: var(--dn-muted); }
.cp-dn-head { display: flex; flex-wrap: wrap; align-items: baseline; justify-content: space-between; gap: 6px 24px; }
.cp-dn-head .cp-dn-ipa { font-size: 19px; }
.cp-dn-sec { padding-top: clamp(64px, 9vw, 112px); }
.cp-dn-h2 { margin-top: 14px; font-family: var(--dn-serif); font-weight: 400; font-size: clamp(38px, 5.6vw, 64px); line-height: 1.05; letter-spacing: -0.01em; text-wrap: balance; }
.cp-dn-h2-wide { max-width: 22ch; }
.cp-dn-h3 { font-family: var(--dn-serif); font-weight: 400; font-size: clamp(25px, 2.6vw, 30px); line-height: 1.15; }
.cp-dn-serif { font-family: var(--dn-serif); font-weight: 400; }
