.cp-dn-lede { margin-top: 22px; max-width: 34em; font-size: clamp(17px, 1.7vw, 19px); line-height: 1.6; color: var(--dn-body); text-wrap: pretty; }
.cp-dn-card { border-radius: 28px; background: var(--dn-card); border: 1px solid var(--dn-rule); }
.cp-dn-btns { display: flex; flex-wrap: wrap; gap: 12px; margin-top: 28px; }
