@media (max-width: 639px) { .cp-dn-btns { flex-direction: column; align-items: stretch; } .cp-dn-btns > a { justify-content: center; } }

/* The hero: the headline's vowels in colour over their sounds, the vowel map in its card, the strip of the words sung. */
.cp-dn-hero { padding-block: 20px clamp(40px, 6vw, 64px); background: var(--dn-wash); border-bottom: 1px solid var(--dn-rule); }
