.cp-dn-chip { display: inline-flex; align-items: center; gap: 10px; padding: 4px 14px 4px 4px; border-radius: 99px; background: var(--dn-card); border: 1px solid var(--dn-rule); font-size: 13.5px; font-weight: 600; white-space: nowrap; }
.cp-dn-chip b { padding: 3px 10px; border-radius: 99px; background: var(--color-cream); color: var(--color-ink); font-size: 11.5px; font-weight: 800; letter-spacing: .08em; text-transform: uppercase; }
.cp-dn-h1 { margin-top: 26px; font-family: var(--dn-serif); font-weight: 400; font-size: clamp(60px, 11vw, 116px); line-height: .92; letter-spacing: -0.015em; }
