.cp-dn-dot { fill: var(--dn-a); stroke: var(--dn-card); stroke-width: 2.5; }
.cp-dn-ring { fill: var(--dn-card); stroke: var(--dn-amber); stroke-width: 2.5; }
.cp-dn-sym { font-family: var(--dn-serif); font-size: 30px; fill: var(--dn-ink); }
