.cp-dn-sym-head { font-size: 24px; fill: var(--dn-amber); }
.cp-dn-map-axis { display: grid; grid-template-columns: auto 1fr auto; gap: 12px; padding-inline-start: 12.5%; margin-top: 6px; font-size: 12.5px; color: var(--dn-muted); }
.cp-dn-map-axis span:nth-child(2) { text-align: center; }
.cp-dn-legend { display: grid; gap: 8px; margin-top: 16px; padding-top: 16px; border-top: 1px solid var(--dn-rule); font-size: 14px; }
.cp-dn-legend li { display: flex; align-items: center; gap: 9px; }
.cp-dn-key { flex: none; width: 11px; height: 11px; border-radius: 99px; }
.cp-dn-key-dot { background: var(--dn-a); }
.cp-dn-key-ring { border: 2.5px solid var(--dn-amber); }
.cp-dn-map-note { margin-top: 12px; font-size: 14px; line-height: 1.6; color: var(--dn-muted); }
@media (max-width: 639px) { .cp-dn-map-axis { display: flex; justify-content: space-between; padding-inline-start: 0; font-size: 12px; } .cp-dn-map-axis span:nth-child(2) { display: none; } }

.cp-dn-strip { margin: clamp(40px, 6vw, 64px) 0 0; padding-top: 24px; border-top: 1px solid var(--dn-rule); }
.cp-dn-strip-head { display: flex; flex-wrap: wrap; align-items: baseline; justify-content: space-between; gap: 10px 24px; }
.cp-dn-strip-key { display: flex; flex-wrap: wrap; gap: 6px 18px; font-size: 13.5px; color: var(--dn-muted); }
.cp-dn-strip-key span { display: inline-flex; align-items: center; gap: 8px; }
