@media (max-width: 639px) { .cp-dn-strip-row { gap: 2px; } .cp-dn-sc { width: 16px; } .cp-dn-sv { padding-inline-start: 4px; } .cp-dn-sv::after { margin-inline-start: -4px; } .cp-dn-sv b { font-size: 20px; } .cp-dn-sc b { font-size: 15px; } }

/* The demos: night screens in either mode, the harmonics in gold, the filters' shape in cyan. */
.cp-dn-demosec { padding-top: clamp(48px, 7vw, 80px); }
.cp-dn-deck { overflow: hidden; border-radius: 28px; background: var(--dn-night); color: var(--dn-n-ink); box-shadow: 0 40px 80px -50px rgb(26 21 32 / .7); }
