.cp-dn-read { display: flex; flex-wrap: wrap; align-items: baseline; gap: 4px 14px; font-variant-numeric: tabular-nums; }
.cp-dn-read b { font-family: var(--dn-serif); font-weight: 400; font-size: clamp(40px, 5.6vw, 58px); line-height: 1; color: var(--dn-gold); }
.cp-dn-read-key { font-family: var(--dn-serif); font-size: clamp(24px, 3vw, 30px); color: var(--dn-gold); }
.cp-dn-read .cp-dn-mono { font-size: 14px; color: var(--dn-n-body); }
.cp-dn-spec { display: block; width: 100%; height: clamp(150px, 24vw, 260px); margin-top: 10px; }
.cp-dn-hz { stroke: #3a3342; stroke-width: 1; stroke-dasharray: 3 4; vector-effect: non-scaling-stroke; }
