.cp-dn-harm { stroke: var(--dn-gold); stroke-width: 2.5; stroke-linecap: round; vector-effect: non-scaling-stroke; }
.cp-dn-scale { position: relative; height: 22px; margin-top: 6px; font: 500 12px/1 var(--dn-mono); color: var(--dn-n-muted); }
.cp-dn-scale span { position: absolute; top: 6px; left: calc(var(--at) * 100%); translate: calc(var(--at) * -100%) 0; white-space: nowrap; }
.cp-dn-deck-foot { display: grid; gap: 28px; padding: clamp(20px, 3vw, 34px); }
@media (min-width: 900px) { .cp-dn-deck-foot { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 40px; } }
.cp-dn-deck-h { font-family: var(--dn-serif); font-weight: 400; font-size: clamp(30px, 3.6vw, 42px); line-height: 1.08; color: var(--dn-n-ink); }
.cp-dn-deck-p { margin-top: 14px; font-size: 15.5px; line-height: 1.65; color: var(--dn-n-body); }
.cp-dn-deck .s-cite a { color: var(--dn-gold); }
.cp-dn-deck :is(button, a):focus-visible { outline-color: var(--dn-cyan); }
.cp-dn-pick { margin: 0; padding: 0; border: 0; }
.cp-dn-pick + .cp-dn-pick { margin-top: 10px; }
.cp-dn-pick legend { margin-bottom: 10px; font-size: 11.5px; font-weight: 700; letter-spacing: .2em; text-transform: uppercase; color: var(--dn-n-muted); }
.cp-dn-chip-b { display: inline-flex; align-items: baseline; gap: 7px; margin: 0 4px 8px 0; min-height: 44px; padding: 9px 16px; border-radius: 99px; border: 1px solid var(--dn-n-rule); background: transparent; color: var(--dn-n-ink); font-size: 15px; white-space: nowrap; cursor: pointer; }
.cp-dn-chip-b.cp-dn-mono { font-size: 13px; }
