.cp-dn-chip-b[aria-pressed="true"] { background: color-mix(in srgb, var(--dn-cyan) 22%, var(--dn-night)); border-color: var(--dn-n-ink); box-shadow: inset 0 0 0 1px var(--dn-n-ink); }
.cp-dn-chip-ipa { font-family: var(--dn-serif); font-size: 21px; line-height: 1; }
.cp-dn-plays { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 22px; }
.cp-dn-play { display: inline-flex; align-items: center; gap: 10px; min-height: 48px; padding: 0 20px 0 7px; border-radius: 99px; border: 1.5px solid var(--dn-n-ink); background: transparent; color: var(--dn-n-ink); font-size: 16px; font-weight: 650; white-space: nowrap; cursor: pointer; }
.cp-dn-play:hover { background: color-mix(in srgb, var(--dn-n-ink) 8%, transparent); }
.cp-dn-play-icon { position: relative; flex: none; width: 32px; height: 32px; border-radius: 99px; background: var(--dn-cyan); }
.cp-dn-play-icon::before { content: ""; position: absolute; inset-block-start: 10px; inset-inline-start: 12px; border-block: 6px solid transparent; border-inline-start: 10px solid var(--dn-night); }
.cp-dn-play[aria-pressed="true"] .cp-dn-play-icon::before { inset: 11px; border: 0; border-radius: 2px; background: var(--dn-night); }
.cp-dn-play-main { background: var(--dn-gold); border-color: var(--dn-gold); color: #1a1520; }
.cp-dn-play-main:hover { background: color-mix(in srgb, var(--dn-gold) 88%, #fff); }
.cp-dn-play-main .cp-dn-play-icon { background: #1a1520; }
.cp-dn-play-main .cp-dn-play-icon::before { border-inline-start-color: var(--dn-gold); }
.cp-dn-play-main[aria-pressed="true"] .cp-dn-play-icon::before { background: var(--dn-gold); }
.cp-dn-play-b .cp-dn-play-icon { background: var(--dn-gold); }
.cp-dn-say { min-height: 3.1em; margin-top: 14px; font-size: 15px; font-weight: 600; line-height: 1.5; color: var(--dn-gold); }
.cp-dn-dkeys { display: flex; flex-wrap: wrap; gap: 6px 18px; font-size: 13px; color: var(--dn-n-body); }
.cp-dn-dkeys span { display: inline-flex; align-items: center; gap: 8px; }
.cp-dn-dk { flex: none; }
.cp-dn-dk-line { width: 3px; height: 15px; background: var(--dn-gold); }
.cp-dn-dk-curve { width: 20px; border-top: 2.5px solid var(--dn-cyan); }
.cp-dn-dk-t { width: 14px; height: 12px; background: repeating-linear-gradient(90deg, #e8e2ee 0 1.5px, transparent 1.5px 3.5px); }
.cp-dn-dk-v { width: 22px; height: 9px; border-radius: 99px; background: var(--dn-cyan); }
.cp-dn-dk-beat { height: 15px; border-left: 1.5px dashed var(--dn-n-muted); }
.cp-dn-deck-note { margin-top: 12px; font-size: 13px; line-height: 1.55; color: var(--dn-n-muted); }

/* By the end: four ruled columns, each aim's sound over its words. */
.cp-dn-goals { display: grid; gap: 0 28px; margin-top: 22px; }
@media (min-width: 720px) { .cp-dn-goals { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (min-width: 1100px) { .cp-dn-goals { grid-template-columns: repeat(4, minmax(0, 1fr)); } }
.cp-dn-goals li { padding: 22px 0 26px; border-top: 1.5px solid var(--dn-ink); }
.cp-dn-glyph { font-family: var(--dn-serif); font-weight: 400; font-size: 46px; line-height: 1; color: var(--dn-a); white-space: nowrap; }
.cp-dn-goals p { margin-top: 16px; font-size: 17px; line-height: 1.5; }

/* In plain words: the sentence with its vowels gone, the heading beside its words, two cards, the beat deck beside its words. */
.cp-dn-gone { margin-top: 22px; padding: clamp(22px, 4vw, 40px); border-radius: 28px; background: var(--dn-card); border: 1px solid var(--dn-rule); }
.cp-dn-gone-k { font-size: 14px; color: var(--dn-muted); }
.cp-dn-gone-line { margin-top: 12px; font-family: var(--dn-serif); font-size: clamp(32px, 6vw, 66px); line-height: 1.1; letter-spacing: .01em; overflow-wrap: anywhere; }
.cp-dn-gone-whole { margin-top: 10px; font-family: var(--dn-serif); font-size: clamp(22px, 3vw, 30px); line-height: 1.25; color: var(--dn-muted); }
.cp-dn-gone-after { margin-top: 16px; font-size: 15px; line-height: 1.6; color: var(--dn-body); }
.cp-dn-split { display: grid; gap: 8px 56px; margin-top: clamp(48px, 7vw, 80px); }
@media (min-width: 960px) { .cp-dn-split { grid-template-columns: minmax(0, 5fr) minmax(0, 7fr); align-items: start; } .cp-dn-split .cp-dn-h2 { margin-top: 0; } .cp-dn-split .cp-dn-body:first-child { margin-top: 0; } }
.cp-dn-blur-h { margin-top: clamp(44px, 6vw, 64px); font-family: Figtree, system-ui, sans-serif; font-size: 22px; font-weight: 500; }
.cp-dn-blur { display: grid; gap: 14px; margin-top: 20px; }
@media (min-width: 760px) { .cp-dn-blur { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
.cp-dn-blur-card { display: grid; grid-template-columns: 76px minmax(0, 1fr); gap: 18px; padding: clamp(18px, 2.4vw, 26px); border-radius: 24px; }
.cp-dn-blur-card:last-child { background: var(--dn-wash); }
.cp-dn-zs { display: flex; flex-direction: column; font-family: var(--dn-serif); font-size: 42px; line-height: 1.05; color: var(--dn-a); }
.cp-dn-zs span + span { color: var(--dn-muted); }
.cp-dn-hz-big { font-family: var(--dn-serif); font-size: 40px; line-height: 1; color: var(--dn-a); }
.cp-dn-hz-big small { display: block; margin-top: 6px; font: 500 13px/1.3 var(--dn-mono); color: var(--dn-muted); }
.cp-dn-blur-card h4 { font-size: 12px; font-weight: 700; letter-spacing: .18em; text-transform: uppercase; }
.cp-dn-blur-card h4 + p { margin-top: 8px; font-size: 15px; line-height: 1.6; color: var(--dn-body); }
.cp-dn-pair { display: grid; gap: 32px; margin-top: 36px; }
@media (min-width: 960px) { .cp-dn-pair { grid-template-columns: minmax(0, 6fr) minmax(0, 5fr); gap: 48px; align-items: start; } .cp-dn-pair-text { padding-top: 12px; } }
.cp-dn-beat-in { padding: clamp(18px, 2.6vw, 26px); }
.cp-dn-beat .cp-dn-deck-h { font-size: clamp(26px, 2.8vw, 32px); }
.cp-dn-lanes { display: grid; grid-template-columns: 22px minmax(0, 1fr); gap: 22px 12px; align-items: center; margin-top: 18px; padding: 22px 18px; border-radius: 16px; background: var(--dn-well); }
.cp-dn-lane-n { font-size: 15px; font-weight: 800; color: var(--dn-n-muted); }
.cp-dn-lane-n[data-on] { color: var(--dn-gold); }
.cp-dn-track { position: relative; height: 30px; }
.cp-dn-track > i { position: absolute; display: block; }
.cp-dn-beatline { inset-block: -11px; width: 0; border-left: 1.5px dashed #5d5466; }
.cp-dn-beatline[data-on] { border-left-style: solid; border-color: var(--dn-gold); }
.cp-dn-t { inset-block: 2px; background: repeating-linear-gradient(90deg, #e8e2ee 0 1.5px, transparent 1.5px 3.5px); opacity: .7; }
.cp-dn-tv { inset-block: 2px; border-radius: 7px; background: var(--dn-cyan); opacity: .6; }
.cp-dn-track-b .cp-dn-tv { background: var(--dn-gold); }
.cp-dn-t[data-on], .cp-dn-tv[data-on] { opacity: 1; }
.cp-dn-ph { inset-block: -14px; left: calc(var(--p, 0) * 100%); width: 2px; margin-inline-start: -1px; border-radius: 1px; background: #fff; opacity: 0; }
.cp-dn-track[data-playing] .cp-dn-ph { opacity: 1; }
.cp-dn-pair-text .cp-dn-h3 + .cp-dn-body { margin-top: 10px; }
.cp-dn-hold-h { margin-top: 36px; }
.cp-dn-tiles { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 22px; }
.cp-dn-tiles span { display: grid; place-items: center; width: 50px; height: 50px; border-radius: 12px; border: 1.5px solid var(--dn-a); font-family: var(--dn-serif); font-size: 26px; color: var(--dn-a); }
.cp-dn-tiles .cp-dn-tile-air { border-style: dashed; border-color: var(--dn-muted); color: var(--dn-muted); }
.cp-dn-tiles-note { margin-top: 10px; font-size: 13.5px; color: var(--dn-muted); }

/* The archive: a hymnal page, each year large in the serif, its own words pulled out in italic. */
.cp-dn-archive { margin-top: clamp(72px, 10vw, 120px); padding-block: clamp(56px, 8vw, 104px); background: var(--dn-wash); border-block: 1px solid var(--dn-rule); }
.cp-dn-archive .cp-dn-h2 { padding-bottom: clamp(24px, 3vw, 40px); border-bottom: 2px solid var(--dn-ink); }
.cp-dn-years li { display: grid; gap: 10px 40px; padding-block: clamp(24px, 3vw, 38px); border-bottom: 1px solid var(--dn-rule); }
@media (min-width: 760px) { .cp-dn-years li { grid-template-columns: minmax(180px, 3fr) minmax(0, 7fr); } }
.cp-dn-year { display: flex; flex-wrap: wrap; align-items: baseline; gap: 4px 14px; font-family: var(--dn-serif); font-size: clamp(42px, 5vw, 60px); line-height: 1; font-variant-numeric: lining-nums; }
@media (min-width: 760px) { .cp-dn-year { flex-direction: column; align-items: start; gap: 10px; } }
.cp-dn-place { font-family: Figtree, system-ui, sans-serif; font-size: 12px; font-weight: 700; line-height: 1.4; letter-spacing: .2em; text-transform: uppercase; color: var(--dn-amber); }
.cp-dn-pull { margin: 0; }
.cp-dn-pull p { font-family: var(--dn-serif); font-style: italic; font-size: clamp(22px, 2.4vw, 28px); line-height: 1.3; text-wrap: balance; }
.cp-dn-years h3 { margin-top: 14px; font-size: 16px; font-weight: 700; }
.cp-dn-years h3 + p { margin-top: 6px; max-width: 70ch; font-size: 16px; line-height: 1.65; color: var(--dn-body); }
.cp-dn-years + .cp-dn-more .cp-dn-years, .cp-dn-facts + .cp-dn-more .cp-dn-facts { margin-top: 0; }
.cp-dn-more > summary { display: flex; align-items: center; justify-content: space-between; gap: 16px; min-height: 56px; border-bottom: 1px solid var(--dn-rule); font-size: 17px; font-weight: 600; color: var(--dn-a); cursor: pointer; list-style: none; }
.cp-dn-more > summary::-webkit-details-marker { display: none; }
.cp-dn-more[open] > summary .cp-faq-sign { rotate: 45deg; }
@media (min-width: 900px) { .cp-dn-more > summary { display: none; } }
@media (max-width: 639px) { .cp-dn-years h3 + p { font-size: 15.5px; line-height: 1.6; } }

/* The course: the climb in sounds, then four unit columns under one rule, each with its symbol. */
.cp-dn-count { font-size: 14px; color: var(--dn-muted); }
.cp-dn-climb { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 12px; margin-top: 18px; font-family: var(--dn-serif); font-size: clamp(20px, 2.2vw, 26px); color: var(--dn-a); }
.cp-dn-climb svg { color: var(--dn-muted); }
.cp-dn-units { display: grid; margin-top: 36px; border-top: 2px solid var(--dn-ink); }
@media (min-width: 720px) { .cp-dn-units { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (min-width: 1100px) { .cp-dn-units { grid-template-columns: repeat(4, minmax(0, 1fr)); } }
.cp-dn-unit { padding: 24px clamp(0px, 1.8vw, 22px) 28px; border-bottom: 1px solid var(--dn-rule); }
@media (min-width: 720px) { .cp-dn-unit { padding-inline: 22px; border-inline-end: 1px solid var(--dn-rule); } .cp-dn-unit:nth-child(2n) { border-inline-end: 0; } }
@media (min-width: 1100px) { .cp-dn-unit { border-bottom: 0; } .cp-dn-unit:nth-child(2n) { border-inline-end: 1px solid var(--dn-rule); } .cp-dn-unit:last-child { border-inline-end: 0; } }
.cp-dn-unit-n { font-size: 12px; font-weight: 600; letter-spacing: .2em; text-transform: uppercase; color: var(--dn-muted); }
.cp-dn-unit .cp-dn-glyph { margin-top: 18px; font-size: 56px; }
.cp-dn-unit h3 { margin-top: 18px; font-size: 21px; font-weight: 500; letter-spacing: -0.01em; }
.cp-dn-lessons { margin-top: 18px; border-top: 1px solid var(--dn-rule); font-size: 15px; }
.cp-dn-lessons li { display: flex; justify-content: space-between; align-items: center; gap: 8px; min-height: 44px; padding-block: 6px; border-bottom: 1px solid var(--dn-rule); }
.cp-dn-lesson { display: inline-flex; align-items: baseline; gap: 10px; }
.cp-dn-lesson .cp-dn-mono { font-size: 12px; color: var(--dn-muted); }
.cp-dn-lesson a { color: var(--dn-ink); text-decoration: underline 1.5px transparent; text-underline-offset: 4px; }
.cp-dn-lesson a:hover { color: var(--dn-a); text-decoration-color: currentColor; }
.cp-dn-free { display: inline-flex; align-items: center; min-height: 28px; padding: 0 10px; border-radius: 99px; background: var(--dn-free); color: var(--dn-free-ink); font-size: 11px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; white-space: nowrap; text-decoration: none; }
@media (max-width: 719px) { .cp-dn-unit:not(:first-child) .cp-dn-lessons { display: none; } }

/* Lesson 1: the line of Amazing Grace with its stresses and its light "the", the steps, beside what the app hears. */
.cp-dn-first { display: grid; gap: 32px; }
@media (min-width: 960px) { .cp-dn-first { grid-template-columns: minmax(0, 7fr) minmax(0, 5fr); gap: 56px; align-items: start; } }
.cp-dn-first-lead { margin-top: 14px; }
.cp-dn-line { margin: 26px 0 0; padding: 24px clamp(18px, 2.4vw, 26px) 18px; border-radius: 22px; }
.cp-dn-sylls { display: flex; flex-wrap: wrap; align-items: flex-end; gap: 14px clamp(10px, 1.4vw, 18px); }
.cp-dn-syl { display: inline-flex; flex-direction: column; }
.cp-dn-syl b { font-family: var(--dn-serif); font-weight: 400; font-size: clamp(24px, 2.6vw, 30px); line-height: 1.1; }
.cp-dn-syl i { margin-top: 4px; font-family: var(--dn-serif); font-size: 15.5px; color: var(--dn-muted); }
.cp-dn-syl-on b, .cp-dn-syl-on i { color: var(--dn-a); }
.cp-dn-syl-on b { font-weight: 700; }
.cp-dn-syl-light b { font-size: clamp(20px, 2.2vw, 24px); font-style: italic; color: var(--dn-amber); }
.cp-dn-syl-light i { color: var(--dn-amber); }
.cp-dn-hy { color: var(--dn-muted); font-weight: 400; }
.cp-dn-line figcaption { display: flex; flex-wrap: wrap; gap: 6px 20px; margin-top: 18px; padding-top: 14px; border-top: 1px solid var(--dn-rule); font-size: 13.5px; line-height: 1.5; color: var(--dn-muted); }
.cp-dn-line-key { display: inline-flex; flex-wrap: wrap; gap: 4px 14px; }
.cp-dn-line-key > span { display: inline-flex; align-items: center; gap: 7px; }
.cp-dn-lk { width: 10px; height: 10px; border-radius: 3px; }
.cp-dn-lk-on { background: var(--dn-a); }
.cp-dn-lk-light { border: 1.5px solid var(--dn-amber); border-radius: 99px; }
.cp-dn-steps { display: grid; gap: 10px; margin-top: 18px; }
.cp-dn-steps li { display: grid; grid-template-columns: 28px minmax(0, 1fr); gap: 14px; align-items: start; padding: 15px 18px; border-radius: 16px; background: var(--dn-card); border: 1px solid var(--dn-rule); }
.cp-dn-steps li:first-child { background: var(--dn-wash); border-color: color-mix(in srgb, var(--dn-a) 45%, transparent); }
.cp-dn-step-n { display: grid; place-items: center; width: 26px; height: 26px; border-radius: 99px; border: 1.5px solid var(--dn-a); font-size: 12px; font-weight: 700; color: var(--dn-a); }
.cp-dn-steps li:first-child .cp-dn-step-n { background: var(--dn-a); color: var(--dn-card); }
.cp-dn-steps p { font-size: 15.5px; line-height: 1.55; }
.cp-dn-inside { padding: clamp(22px, 3vw, 30px); }
@media (min-width: 960px) { .cp-dn-inside { margin-top: 58px; } }
.cp-dn-hears { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; margin: 18px 0 8px; }
.cp-dn-hears > div { padding: 12px 14px; border-radius: 12px; background: color-mix(in srgb, var(--dn-a) 11%, var(--dn-card)); }
.cp-dn-hears > .cp-dn-hears-ear { background: color-mix(in srgb, var(--dn-amber) 10%, var(--dn-card)); }
.cp-dn-hears dt { font-size: 11px; font-weight: 700; letter-spacing: .16em; text-transform: uppercase; color: var(--dn-a); }
.cp-dn-hears-ear dt { color: var(--dn-amber); }
.cp-dn-hears dd { margin-top: 3px; font-size: 15px; }

/* Margin notes: each fact beside its mark, in the serif, its source in the monospace. */
.cp-dn-facts { display: grid; gap: 0 48px; margin-top: 28px; }
@media (min-width: 900px) { .cp-dn-facts { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
.cp-dn-facts li { display: grid; grid-template-columns: 76px minmax(0, 1fr); gap: 18px; padding-block: 26px; border-top: 1px solid var(--dn-rule); }
.cp-dn-facts .cp-dn-glyph { font-size: 36px; }
.cp-dn-facts .cp-dn-glyph-words { width: min-content; font-size: 22px; line-height: 1.2; white-space: normal; }
.cp-dn-fact { font-family: var(--dn-serif); font-size: clamp(18px, 1.9vw, 20px); line-height: 1.5; }
.cp-dn-src { margin-top: 10px; font: 500 12px/1.4 var(--dn-mono); letter-spacing: .06em; text-transform: uppercase; color: var(--dn-muted); }
@media (max-width: 639px) { .cp-dn-facts li { grid-template-columns: 56px minmax(0, 1fr); gap: 14px; } .cp-dn-facts .cp-dn-glyph { font-size: 28px; } .cp-dn-facts .cp-dn-glyph-words { font-size: 18px; } }

/* Before you begin: three ruled columns, singing it safely in amber. */
.cp-dn-kit-grid { display: grid; gap: 28px; margin-top: 22px; }
@media (min-width: 900px) { .cp-dn-kit-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); } }
.cp-dn-kit-grid h3 { padding-bottom: 12px; border-bottom: 1.5px solid var(--dn-ink); font-size: 12.5px; font-weight: 700; letter-spacing: .16em; text-transform: uppercase; }
.cp-dn-ticks li { display: grid; grid-template-columns: 16px minmax(0, 1fr); gap: 10px; padding: 13px 0; border-bottom: 1px solid var(--dn-rule); font-size: 15px; line-height: 1.5; }
.cp-dn-ticks svg { margin-top: 3px; color: var(--dn-a); }
.cp-dn-safe .cp-dn-ticks svg { color: var(--dn-amber); }

/* Questions beside their heading. */
.cp-dn-fine { display: grid; gap: 18px; }
@media (min-width: 960px) { .cp-dn-fine { grid-template-columns: minmax(0, 4fr) minmax(0, 8fr); gap: 48px; align-items: start; } .cp-dn-fine .cp-dn-h2 { margin-top: 0; } }
.cp-dn-faq { max-width: none; margin-top: 0; border-top: 1px solid var(--dn-rule); }
.cp-dn-faq details { border-color: var(--dn-rule); }
.cp-dn-faq summary { font-weight: 500; }
.cp-dn-faq details p { color: var(--dn-body); }
.cp-dn-faq-links { display: flex; flex-wrap: wrap; gap: 4px 24px; padding-bottom: 20px; }
.cp-dn-faq-links .s-arrow { margin-top: 0; }

/* The close on the night, centred, then the courses that go with it. */
.cp-dn-close { margin-top: clamp(72px, 10vw, 120px); padding-block: clamp(64px, 10vw, 120px); background: var(--dn-night); color: var(--dn-n-ink); text-align: center; }
.cp-dn-close .cp-dn-kick { color: var(--dn-cyan); }
:root:not([data-theme$="-light"]) .cp-dn-close { border-block: 1px solid var(--dn-n-rule); }
.cp-dn-close-h { margin-top: 18px; font-family: var(--dn-serif); font-weight: 400; font-size: clamp(48px, 8.4vw, 100px); line-height: 1; text-wrap: balance; }
.cp-dn-close-h .cp-dn-it { color: var(--dn-gold); }
.cp-dn-close-ipa { margin-top: 16px; font-size: clamp(18px, 2vw, 23px); color: var(--dn-n-muted); }
.cp-dn-close-p { max-width: 36em; margin: 22px auto 0; font-size: clamp(16px, 1.7vw, 18px); line-height: 1.65; color: var(--dn-n-body); }
.cp-dn-close-btns { justify-content: center; }
:root:not([data-skin="game"]) .cp-dn-close .btn-primary { background: var(--dn-gold); border-color: var(--dn-gold); color: #1a1520; }
:root[data-skin="game"] body.s-arcade .cp-dn-close .btn-secondary { background: transparent; color: #3be7ff; box-shadow: inset 0 0 0 2px #3be7ff; } /* the band stays night in game's light themes too */
:root:not([data-skin="game"]) .cp-dn-close .btn-secondary { background: color-mix(in srgb, var(--dn-n-ink) 10%, var(--dn-night)); border-color: transparent; color: var(--dn-n-ink); }
.cp-dn-close-note { margin-top: 16px; font-size: 14px; color: var(--dn-n-muted); }
.cp-dn-close-rel { max-width: 1120px; margin: clamp(40px, 6vw, 56px) auto 0; padding-top: 32px; border-top: 1px solid var(--dn-n-rule); }
.cp-dn-close-rel .cp-dn-kick { color: var(--dn-n-muted); }
.cp-dn-close .cp-related { justify-content: center; }
.cp-dn-close .cp-related a { background: transparent; border: 1px solid var(--dn-n-rule); color: var(--dn-n-ink); white-space: nowrap; }
.cp-dn-close .cp-related a:hover { background: color-mix(in srgb, var(--dn-n-ink) 10%, transparent); }
.cp-dn-close .cp-related-all { display: none; }
.cp-dn-close :is(a, button):focus-visible { outline-color: var(--dn-cyan); }

/* The sources: folded on a phone, open from 900 px, in two columns. */
.cp-dn-sources { padding-block: 48px 24px; }
.cp-dn-sources summary { display: flex; align-items: center; min-height: 44px; list-style: none; cursor: pointer; }
.cp-dn-sources summary::-webkit-details-marker { display: none; }
.cp-dn-sources ol { margin-top: 16px; padding-inline-start: 22px; list-style: decimal; font-size: 14px; line-height: 1.55; color: var(--dn-body); }
@media (min-width: 900px) { .cp-dn-sources ol { columns: 2; column-gap: 48px; } }
.cp-dn-sources li { margin-bottom: 8px; break-inside: avoid; }
