.cp-fb-head { --fb-h: clamp(56px, 11.5vw, 160px); }
.cp-fb-head::before { inset-inline: -12px; }
.cp-fb .cp-hero .cp-fb-h1 { margin: 0; font-size: var(--fb-h); line-height: .92; text-wrap: nowrap; }
:root:not([data-skin="game"]) .cp-fb .cp-hero .cp-fb-h1 { font-size: var(--fb-h); font-weight: 300; line-height: .92; letter-spacing: -0.045em; }
.cp-fb-h1-hi, .cp-fb-h1-lo { display: flex; }
