.cp-fb-bar { display: block; width: 78%; height: .09em; border-radius: 99px; background: var(--fb-bar); }
.cp-fb-h1-lo .cp-fb-bar { width: 88%; transform-origin: left; rotate: 1.2deg; }
.cp-fb-step { flex: none; display: flex; flex-direction: column; justify-content: flex-end; gap: 4px; height: calc(var(--fb-h) * .8); margin-top: calc(var(--fb-h) * -.2); padding: 4px 0 4px 12px; border-left: 1.5px dashed var(--fb-red);
