:root[data-skin="game"] body.s-arcade .cp-fb-head { --fb-h: clamp(36px, 8.4vw, 104px); }
:root[data-skin="game"] body.s-arcade .cp-fb-step { margin-top: calc(var(--fb-h) * .1); height: calc(var(--fb-h) * .7); }
