:root[data-skin="game"] body.s-arcade .cp-fb-h1-lo { margin-top: .4em; }
:root[data-skin="game"] body.s-arcade .cp-fb-tag { font-family: var(--a-hud); font-size: 9.5px; font-size-adjust: var(--arc-ex, none); }
.cp-fb-hero-grid { display: grid; gap: 32px; margin-top: clamp(24px, 3vw, 32px); padding-bottom: clamp(44px, 5vw, 64px); }
@media (min-width: 900px) { .cp-fb-hero-grid { grid-template-columns: minmax(0, 1.05fr) minmax(0, .95fr); gap: 56px; align-items: start; } }
.cp-fb-hero-grid .s-lede { margin-top: 0; }
.cp-fb-call-top { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 4px 16px; margin-bottom: 10px; font-size: 12px; letter-spacing: .06em; text-transform: uppercase; color: var(--di-muted); }
.cp-fb-call-top .cp-fb-red { font-weight: 600; letter-spacing: .1em; }
.cp-fb .cp-fb-syl { font-family: var(--fb-serif); font-style: italic; font-weight: 400; font-size: 26px; }
:root[data-skin="game"] body.s-arcade .cp-fb .cp-fb-syl { font-family: var(--a-hud); font-style: normal; font-size: 15px; font-size-adjust: var(--arc-ex, none); }
.cp-fb-stepline { fill: none; }
.cp-fb [data-fb-note] { transition: filter .12s, stroke-width .12s; }
.cp-fb .cp-di-dot[data-on] { stroke: var(--di-ink); stroke-width: 2.5; filter: drop-shadow(0 0 6px var(--fb-bar)); }
.cp-fb .cp-di-ring[data-on] { stroke-width: 4.5; filter: drop-shadow(0 0 6px var(--di-ring)); }
.cp-fb-call-btns { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 12px; }
.cp-fb-callbtn { display: inline-flex; align-items: center; gap: 10px; min-height: 44px; padding: 0 18px 0 6px; border-radius: 99px; border: 1.5px solid var(--fb-red); background: var(--fb-red); color: var(--fb-on-red);
    font: 700 15px/1.2 Figtree, system-ui, sans-serif; white-space: nowrap; cursor: pointer; }
.cp-fb-callbtn-icon { display: grid; place-items: center; flex: none; width: 32px; height: 32px; border-radius: 99px; background: var(--fb-on-red); }
.cp-fb-callbtn-icon::before { content: ""; margin-left: 3px; border-style: solid; border-width: 6px 0 6px 10px; border-color: transparent transparent transparent var(--fb-red); }
