:root:not([data-skin="game"]) .cp-fb .cp-di-read b { font-family: var(--fb-serif); font-style: italic; font-weight: 400; font-size-adjust: var(--arc-ex, none); }
.cp-fb-band { fill: color-mix(in srgb, var(--pd-rose) 16%, transparent); stroke: var(--pd-rose); stroke-width: 1.5; stroke-dasharray: 4 5; vector-effect: non-scaling-stroke; }
