@media (max-width: 639px) { .cp-fb .cp-di-scale span:nth-child(even) { display: none; } }

/* The care, as a printed notice in the hero's copy column, under the way in: a double rule round it (an outline set off
   from the border, so the hero's wash shows between), the speaking distance drawn under its heading. */
.cp-fb-notice { margin: 34px 6px 6px; padding: clamp(20px, 2.6vw, 30px); border: 1px solid var(--di-ink); outline: 1px solid var(--di-ink); outline-offset: 5px;
    background: color-mix(in srgb, var(--di-card) 60%, transparent); }
.cp-fb-care-h { margin-top: 8px; font-size: clamp(25px, 2.5vw, 32px); font-weight: 300; line-height: 1.1; letter-spacing: -0.03em; text-wrap: balance; }
:root[data-skin="game"] body.s-arcade .cp-fb-care-h { font-family: var(--a-display); font-weight: 400; font-size: 20px; letter-spacing: .01em; text-transform: uppercase; font-size-adjust: var(--arc-ex, none); }
.cp-fb-across { display: grid; grid-template-columns: auto minmax(24px, 1fr) auto; align-items: center; gap: 4px 10px; margin-top: 16px; max-width: 420px; font: 400 12.5px/1.4 var(--fb-mono); color: var(--di-muted); }
.cp-fb-across i { border-top: 1.5px dashed var(--fb-red); }
.cp-fb-across b { grid-column: 1 / -1; justify-self: center; font-weight: 400; color: var(--fb-red); }
.cp-fb-care-lead { margin-top: 16px; font-size: 16.5px; line-height: 1.55; color: var(--di-ink); text-wrap: pretty; }
.cp-fb-roman { margin-top: 14px; counter-reset: fb-r; }
.cp-fb-roman li { display: grid; grid-template-columns: 34px minmax(0, 1fr); padding: 9px 0; border-top: 1px solid var(--di-rule); font-size: 14.5px; line-height: 1.5; color: var(--di-body); counter-increment: fb-r; }
.cp-fb-roman li::before { content: counter(fb-r, lower-roman); font: 500 13px/1.6 var(--fb-mono); color: var(--fb-red); }
.cp-fb-roman li:last-child { border-bottom: 1px solid var(--di-rule); }
.cp-fb-notice .cp-di-note { margin-top: 10px; }
:root[data-skin="game"] body.s-arcade .cp-fb-notice { border: 2px solid #ffd84a; outline: 0; box-shadow: 6px 6px 0 #3be7ff; background: var(--a-panel); margin-inline: 0; }

/* By the end, in the hero under the call's card: each outcome under a note bar, the four stepping down and in. */
.cp-fb-hero-side { display: grid; gap: clamp(28px, 3.4vw, 40px); align-content: start; }
.cp-fb-goals { display: grid; gap: 16px; margin-top: 16px; }
.cp-fb-goals li { display: grid; grid-template-columns: 34px minmax(0, 1fr); align-items: baseline; padding-left: calc(var(--i) * 18px); }
.cp-fb-note { grid-column: 1 / -1; display: block; width: min(60%, 200px); height: 8px; margin-bottom: 8px; border-radius: 99px; background: color-mix(in srgb, var(--fb-bar) calc(100% - var(--i) * 14%), var(--color-ink)); }
.cp-fb-goals p { font-size: 16px; line-height: 1.45; text-wrap: pretty; }
:root[data-skin="game"] body.s-arcade .cp-fb-note { border-radius: 0; box-shadow: 0 0 8px var(--fb-bar); }

/* In plain words: Garcia's line pulled out under the heading; then why loud is the risk on the loudness bar. */
.cp-fb-pull { margin: 28px 0 0; padding-top: 24px; border-top: 1px solid var(--di-ink); max-width: 30em; }
