.cp-fb-pull figcaption { margin-top: 12px; font-size: 12px; letter-spacing: .06em; text-transform: uppercase; color: var(--di-muted); }
:root[data-skin="game"] body.s-arcade .cp-fb-pull blockquote p { font-family: Figtree, system-ui, sans-serif; font-size-adjust: var(--arc-ex, none); }
.cp-fb-risk { margin-top: clamp(44px, 6vw, 72px); }
