/* From 900 px the heading and its words beside the loudness bar, the numbers under both. */
@media (min-width: 900px) {
    .cp-fb-risk { display: grid; grid-template-columns: minmax(0, 5fr) minmax(0, 6fr); grid-template-areas: "h bar" "say bar" "nums nums"; column-gap: 48px; align-items: end; }
