}
.cp-fb-loud { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); grid-template-rows: auto 10px auto; column-gap: 3px; margin-top: 24px; }
.cp-fb-loud-tag { grid-row: 1; align-self: end; padding: 6px 4px 7px; border: 1px solid; border-bottom: 0; border-radius: 10px 10px 0 0; font: 500 11px/1.3 var(--fb-mono); letter-spacing: .06em; text-align: center; text-transform: uppercase; }
