:root[data-skin="game"] body.s-arcade :is(.cp-fb-loud-tag, .cp-fb-loud-bar) { border-radius: 0; }
:root[data-skin="game"] body.s-arcade .cp-fb-loud-tag { font-family: var(--a-hud); font-size: 8.5px; font-size-adjust: var(--arc-ex, none); }

/* From the archive, on a dark ground in every skin: serif years, the place and its stop, the pull quotes. */
.cp-di-archive.cp-fb-archive { --di-ink: #fbf1ee; --di-body: #e4d7d4; --di-muted: #cdbdb9; --di-label: #ff9eab; --di-rule: rgb(255 255 255 / .14);
    background: var(--fb-night); border-block: 1px solid var(--di-rule); color: var(--di-ink); }
:root[data-skin="game"]:not([data-theme$="-light"]) .cp-di-archive.cp-fb-archive { --di-label: #ffd84a; }
.cp-fb-route { margin-top: 18px; font-size: 12.5px; letter-spacing: .04em; color: var(--di-muted); }
.cp-fb-archive .cp-di-year > span:first-child { font-family: var(--fb-serif); font-weight: 400; font-size: clamp(46px, 6vw, 76px); letter-spacing: -0.02em; color: #f4c46c; }
.cp-fb-archive .cp-di-place { font-family: var(--fb-mono); font-weight: 500; font-size: 12px; letter-spacing: .12em; }
.cp-fb-archive .cp-di-years li { padding-block: clamp(20px, 2.6vw, 30px); }
.cp-fb-pullq p { font-family: var(--fb-serif); font-style: italic; font-size: clamp(19px, 1.9vw, 23px); line-height: 1.3; color: var(--di-ink); text-wrap: pretty; }
.cp-fb-story h3 + p { margin-top: 8px; font-size: 15.5px; line-height: 1.6; }
/* Side by side from 760 px: the year, its place and the pulled-out words down the left, the story beside them. */
@media (min-width: 760px) {
    .cp-fb-archive .cp-di-years li.cp-fb-entry { grid-template-columns: minmax(0, 1fr) minmax(0, 2fr); grid-template-rows: auto 1fr; grid-template-areas: "year story" "pull story"; gap: 12px 44px; }
    .cp-fb-entry > .cp-di-year { grid-area: year; }
    .cp-fb-entry > .cp-fb-pullq { grid-area: pull; }
    .cp-fb-entry > .cp-fb-story { grid-area: story; }
}
.cp-fb-archive .cp-di-more { border-color: var(--di-rule); }
:root[data-skin="game"] body.s-arcade .cp-fb-archive .cp-di-year > span:first-child { font-family: var(--a-display); font-size: clamp(26px, 3.6vw, 36px); color: #ffd84a; font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade .cp-fb-pullq p { font-family: Figtree, system-ui, sans-serif; font-size-adjust: var(--arc-ex, none); }

/* The course: each unit's lessons as pills falling across the lines, a step in at a time, never wrapping. */
.cp-fb-count { margin-top: 12px; font-size: 13px; color: var(--di-muted); }
.cp-fb-units .cp-di-unit { display: flex; flex-direction: column; margin-top: 0; background: var(--di-card); }
.cp-fb-falls { margin-top: auto; padding-top: 16px; }
.cp-fb-falls li { display: flex; align-items: center; min-width: 0; height: 40px; padding-left: calc(var(--i) * 12px); border-bottom: 1px solid var(--fb-line); }
.cp-fb-pill { position: relative; display: inline-flex; align-items: center; gap: 8px; min-width: 0; max-width: 100%; height: 30px; padding: 0 12px; border-radius: 99px; border: 1.5px solid var(--fb-red);
    background: var(--di-card); color: var(--di-ink); font-size: 14px; font-weight: 500; white-space: nowrap; }
.cp-fb-pill-t { min-width: 0; overflow: hidden; text-overflow: ellipsis; }
.cp-fb-pill-go { background: var(--fb-red); color: var(--fb-on-red); font-weight: 650; text-decoration: none; }
.cp-fb-pill-go::after { content: ""; position: absolute; inset: -8px 0; }
.cp-fb-pill-go b { flex: none; padding: 2px 8px; border-radius: 99px; background: var(--fb-on-red); color: var(--fb-red); font-size: 10px; font-weight: 800; letter-spacing: .1em; text-transform: uppercase; }
.cp-fb-pill-go:hover { filter: brightness(1.08); }
:root[data-skin="game"] body.s-arcade :is(.cp-fb-pill, .cp-fb-pill-go b) { border-radius: 0; }

/* Lesson 1: its steps on a line, beside what the app hears and what's for your own ear. */
.cp-fb-steps { position: relative; margin-top: 24px; }
.cp-fb-steps::before { content: ""; position: absolute; left: 5px; top: 8px; bottom: 8px; width: 1.5px; background: var(--di-rule); }
.cp-fb-steps li { position: relative; display: grid; grid-template-columns: 30px minmax(0, 1fr); gap: 6px; padding: 12px 0 12px 26px; }
.cp-fb-steps li::before { content: ""; position: absolute; left: 0; top: 18px; width: 12px; height: 12px; border-radius: 99px; border: 1.5px solid var(--fb-red); background: var(--color-ink); }
.cp-fb-steps li:first-child::before { background: var(--fb-red); }
.cp-fb-steps .cp-di-n { padding-top: 4px; }
.cp-fb-steps p { font-size: 16.5px; line-height: 1.5; }
.cp-fb .cp-fb-inside { background: var(--di-wash); border-color: transparent; }
.cp-fb-hears { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; margin-top: 16px; }
.cp-fb-hears > div { padding: 12px 14px; border-radius: 12px; }
.cp-fb-hears-hears { background: var(--di-card); }
.cp-fb-hears-ear { border: 1.5px dashed color-mix(in srgb, var(--di-label) 60%, transparent); }
.cp-fb-hears dt { font-size: 11.5px; letter-spacing: .1em; text-transform: uppercase; color: var(--di-free); }
.cp-fb-hears-ear dt { color: var(--di-label); }
.cp-fb-hears dd { margin-top: 6px; font-size: 15px; line-height: 1.4; color: var(--di-ink); }
:root[data-skin="game"] body.s-arcade .cp-fb-hears > div { border-radius: 0; }
:root[data-skin="game"] body.s-arcade .cp-fb-steps li::before { border-radius: 0; }

/* The close on red, with the pitch lines behind it: the page's one accent block. */
.cp-di-close.cp-fb-close { --di-ink: #fff; --di-body: #fff; --di-muted: #ffe6e9; --di-label: #ffe6e9; --fb-line: rgb(255 255 255 / .13); --fb-gap: 52px;
    background: var(--fb-close); color: #fff; }
:root[data-skin="game"] body.s-arcade .cp-di-close.cp-fb-close { background: var(--fb-close); --fb-line: rgb(255 79 121 / .24); --di-label: #ffd84a; border-block: 2px solid #ff4f79; }
.cp-fb-close .cp-di-close-in { padding-block: clamp(48px, 6vw, 72px) clamp(44px, 5.5vw, 64px); }
.cp-fb-close .cp-di-related-h { margin-top: 28px; }
.cp-fb .cp-di-sources ol { columns: 3 280px; }
.cp-fb-close .btn-primary { --primary: #fff; --primary-ink: #7d1529; --primary-hover-to: #ffd9de; }
.cp-fb-close .btn-secondary { --btn-soft: rgb(255 255 255 / .12); --btn-soft-hover: rgb(255 255 255 / .2); --btn-soft-active: rgb(255 255 255 / .26); --btn-outline: inset 0 0 0 1.5px rgb(255 255 255 / .75); --color-cream: #fff; color: #fff; }
.cp-fb-close .cp-related a { background: rgb(255 255 255 / .14); color: #fff; }
.cp-fb-close .cp-related a:hover { background: rgb(255 255 255 / .24); }
.cp-fb-close .cp-related-all a { color: #fff; }
.cp-fb-close :is(button, a, summary):focus-visible { outline-color: #fff; }
.cp-fb .cp-di-close .cp-di-note { margin-inline: auto; }
:root[data-skin="game"] body.s-arcade .cp-fb-close .btn-primary { --primary: #ffd84a; --primary-ink: #1a1400; }
:root[data-skin="game"][data-theme] body.s-arcade .cp-fb-close .cp-join-btns .btn-secondary { background: transparent; color: #fff; box-shadow: inset 0 0 0 2px #fff; }

@media (prefers-reduced-motion: reduce) { .cp-fb [data-fb-note] { transition: none; } }

/* Singing in another language (site/courses/other-languages): Hillel's design (2026-11-18,
   ~/Code/course-designs/other-languages), a diction primer and a chant book. EB Garamond with its italics (the site's
   serif behind it), the site's monospace for syllables, respellings and labels, the device's own Japanese serif for
   kana (never a web font); labels in one red ink, as chant books rubricate. Japanese, Spanish, church Latin and
   Ukrainian each a hue (--ol-ja, --ol-es, --ol-la, --ol-uk, with a tint each): a hue class (.cp-ol-ja ...) sets --h and
   --ht for whatever's inside, the four first lines, the outcomes, the units, the archive's tags and the margin notes.
   The syllable boxes (.cp-ol-boxes) run through the page, each box's width its notes' length. Two dark decks on the
   night in every theme (the demos, js/public/other-languages.js). Calm light and dark from the theme's own ground and
   ink; game mode the same pieces in the arcade's neon, pixel headings, square frames and hard shadows. Every lesson is
   linked in its unit once the course has lesson pages, and then the shared list below the page is left out. */
.cp-ol { --ol-serif: 'EB Garamond', ui-serif, 'Iowan Old Style', 'Palatino Linotype', Palatino, Georgia, serif;
    --ol-kana: 'Hiragino Mincho ProN', 'Yu Mincho', YuMincho, 'Noto Serif JP', serif; --ol-mono: ui-monospace, 'SF Mono', Menlo, Consolas, monospace;
    --ol-red: #9b3a1a; --ol-ja: #9e3d52; --ol-ja-t: #fbe5e8; --ol-es: #0068a7; --ol-es-t: #e0eefb; --ol-la: #9e4421; --ol-la-t: #fbe6dd; --ol-uk: #855b00; --ol-uk-t: #f4ead2;
    --ol-wash: color-mix(in srgb, #9b3a1a 6%, var(--color-ink)); --ol-paper: color-mix(in srgb, #fff 55%, var(--color-ink)); --ol-rule: var(--color-line); --ol-frame: color-mix(in srgb, var(--color-cream) 75%, transparent);
    --ol-deck: #1d1613; --ol-deck-in: #140f0d; --ol-deck-edge: #3a2f29; --ol-deck-ink: #f7efe8; --ol-deck-body: #dacdc1; --ol-deck-muted: #b9ab9c; --ol-rose: #f6a3af; --ol-gold: #e5bf6d;
    --cp-line: var(--ol-rule); --cp-a: var(--ol-red); --cp-a-text: var(--ol-red); }
:root:not([data-theme$="-light"]) .cp-ol { --ol-red: #f0a77f; --ol-ja: #f6a3af; --ol-ja-t: #43262c; --ol-es: #86c5fa; --ol-es-t: #17304a; --ol-la: #f6a88d; --ol-la-t: #45271b; --ol-uk: #dbb970; --ol-uk-t: #3a2d10;
    --ol-wash: color-mix(in srgb, #f0a77f 6%, var(--color-ink)); --ol-paper: color-mix(in srgb, #fff 4%, var(--color-ink)); --ol-deck: #0f0b09; --ol-deck-in: #080605; }
:root[data-skin="game"] .cp-ol { --ol-serif: inherit; --ol-red: var(--arc-red); --ol-ja: var(--arc-pink); --ol-es: var(--arc-cyan); --ol-la: var(--arc-green); --ol-uk: var(--arc-yellow);
    --ol-ja-t: color-mix(in srgb, var(--arc-pink) 16%, var(--arc-panel)); --ol-es-t: color-mix(in srgb, var(--arc-cyan) 16%, var(--arc-panel)); --ol-la-t: color-mix(in srgb, var(--arc-green) 16%, var(--arc-panel)); --ol-uk-t: color-mix(in srgb, var(--arc-yellow) 16%, var(--arc-panel));
    --ol-wash: var(--arc-well); --ol-paper: var(--arc-panel); --ol-rule: var(--arc-line); --ol-frame: var(--arc-line);
    --ol-deck: #0d0818; --ol-deck-in: #070410; --ol-deck-edge: #ff4fa866; --ol-deck-ink: #f7f4ff; --ol-deck-body: #d2ccf0; --ol-deck-muted: #b8b2d8; --ol-rose: #ff4fa8; --ol-gold: #ffd84a; }
.cp-ol-ja { --h: var(--ol-ja); --ht: var(--ol-ja-t); } .cp-ol-es { --h: var(--ol-es); --ht: var(--ol-es-t); } .cp-ol-la { --h: var(--ol-la); --ht: var(--ol-la-t); } .cp-ol-uk { --h: var(--ol-uk); --ht: var(--ol-uk-t); }
.cp-ol-red { --h: var(--ol-red); --ht: color-mix(in srgb, var(--ol-red) 10%, var(--ol-paper)); } .cp-ol-mute { --h: var(--color-muted); --ht: var(--color-raised); }

/* Type: the book serif for headings, its italic for the second half, small tracked labels in the red ink. */
.cp-ol-sec { padding-top: clamp(56px, 7vw, 88px); }
.cp-ol-kick { font-size: 12px; font-weight: 700; letter-spacing: .2em; text-transform: uppercase; color: var(--h, var(--ol-red)); }
.cp-ol-tag { font: 500 12px/1.3 var(--ol-mono); letter-spacing: .12em; text-transform: uppercase; color: var(--h); }
.cp-ol-h1, .cp-ol-h2, .cp-ol-h3, .cp-ol-deck-h, .cp-ol-song, .cp-ol-word-name > span:first-child, .cp-ol-join, .cp-ol-unit-body h3, .cp-ol-years h3, .cp-ol-ask-big, .cp-ol-year { font-family: var(--ol-serif); font-weight: 400; }
.cp-ol-h1 { margin-top: 28px; font-size: clamp(56px, 9.4vw, 116px); line-height: .94; letter-spacing: -0.025em; }
.cp-ol-h1 .cp-ol-mk-em { display: block; font-style: italic; color: var(--ol-red); }
.cp-ol-h2 { margin-top: 12px; font-size: clamp(34px, 4.4vw, 52px); line-height: 1.06; letter-spacing: -0.015em; text-wrap: balance; }
.cp-ol-h2-big { font-size: clamp(40px, 5.6vw, 68px); line-height: 1.02; }
.cp-ol-h2 em { font-style: italic; }
.cp-ol-plain .cp-ol-h2 em, .cp-ol-ladder-text .cp-ol-h2 em { display: block; }
.cp-ol-h3 { font-size: clamp(26px, 3vw, 32px); line-height: 1.15; }
.cp-ol-body { margin-top: 16px; font-size: 17px; line-height: 1.7; color: var(--color-muted); max-width: 64ch; text-wrap: pretty; }
.cp-ol-small { margin-top: 14px; font-size: 14.5px; line-height: 1.6; color: var(--color-muted); max-width: 62ch; text-wrap: pretty; }
.cp-ol-center { text-align: center; margin-inline: auto; }
.cp-ol .s-cite a { color: var(--ol-red); }

/* The hero: a primer's ruled page in the wash, the copy at left and the mora map's card at right. */
.cp-ol-hero { padding-block: 16px clamp(48px, 5vw, 64px); border-bottom: 1px solid var(--ol-rule);
    background: repeating-linear-gradient(180deg, transparent 0 63px, color-mix(in srgb, var(--ol-red) 12%, transparent) 63px 64px) var(--ol-wash); }
.cp-ol-hero-grid { display: grid; gap: 40px; }
@media (min-width: 960px) { .cp-ol-hero-grid { grid-template-columns: minmax(0, 1.12fr) minmax(0, .88fr); gap: 56px; align-items: center; } }
.cp-ol-pills { display: flex; flex-wrap: wrap; align-items: center; gap: 10px 14px; margin-top: 18px; }
.cp-ol-chip { display: inline-flex; align-items: center; gap: 8px; padding: 4px 12px 4px 4px; border: 1px solid var(--ol-frame); border-radius: 99px; background: var(--color-panel); font-size: 13px; font-weight: 650; white-space: nowrap; }
.cp-ol-chip b { padding: 3px 10px; border-radius: 99px; background: var(--color-cream); color: var(--color-ink); font-size: 11px; letter-spacing: .1em; text-transform: uppercase; }
.cp-ol-codes { display: inline-flex; gap: 0; font: 500 12.5px/1 var(--ol-mono); letter-spacing: .08em; white-space: nowrap; }
.cp-ol-codes span { color: var(--h); }
.cp-ol-codes span + span::before { content: "·"; margin-inline: 8px; color: var(--color-muted); }
.cp-ol-lede { margin-top: 28px; font-size: clamp(18px, 1.6vw, 20px); line-height: 1.6; max-width: 34em; text-wrap: pretty; }
.cp-ol-facts { display: flex; flex-wrap: wrap; gap: 6px 22px; margin-top: 22px; font-size: 14px; color: var(--color-muted); }
.cp-ol-facts li { display: inline-flex; align-items: center; gap: 9px; }
.cp-ol-facts li::before { content: ""; flex: none; width: 7px; height: 7px; background: var(--ol-red); }
.cp-ol-btns { display: flex; flex-wrap: wrap; gap: 12px; margin-top: 30px; }
.cp-ol-btns a { white-space: nowrap; }
@media (max-width: 599px) { .cp-ol-btns a { flex: 1 1 100%; justify-content: center; } }
.cp-ol-quiet { margin-top: 14px; font-size: 14px; color: var(--color-muted); }

.cp-ol-fig { padding: clamp(20px, 3vw, 30px); border: 1px solid var(--ol-rule); border-radius: 4px; background: var(--ol-paper); box-shadow: 0 30px 60px -36px rgb(60 30 10 / .45); }
.cp-ol-fig-head { display: flex; justify-content: space-between; gap: 12px; font: 500 12px/1.3 var(--ol-mono); letter-spacing: .14em; text-transform: uppercase; color: var(--ol-red); }
.cp-ol-fig-head span + span { color: var(--h); }
.cp-ol-words li { margin-top: 24px; }
.cp-ol-word-name { display: flex; align-items: baseline; gap: 12px; }
.cp-ol-word-name > span:first-child { font-size: 25px; line-height: 1; }
.cp-ol-kana { font-family: var(--ol-kana); font-size: 15px; color: var(--color-muted); }
.cp-ol-word-count { margin-inline-start: auto; font: 500 13px/1 var(--ol-mono); color: var(--color-muted); white-space: nowrap; }
.cp-ol-morae { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 6px 8px; margin-top: 10px; }
.cp-ol-mora { display: grid; place-items: center; min-height: 44px; border: 1px solid var(--ol-ja); background: var(--ol-ja-t); font: 500 17px/1 var(--ol-mono); }
.cp-ol-brace { grid-column: span var(--span); height: 9px; border: 1.5px solid var(--color-cream); border-top: 0; }
.cp-ol-fig figcaption { margin-top: 24px; padding-top: 16px; border-top: 1px solid var(--ol-rule); }
.cp-ol-legend { display: flex; flex-wrap: wrap; gap: 6px 22px; font-size: 13px; color: var(--color-muted); }
.cp-ol-legend li { display: inline-flex; align-items: center; gap: 8px; }
.cp-ol-key-mora { width: 14px; height: 12px; border: 1px solid var(--ol-ja); background: var(--ol-ja-t); }
.cp-ol-key-brace { width: 16px; height: 7px; border: 1.5px solid var(--color-cream); border-top: 0; }
.cp-ol-fig-note { margin-top: 10px; font-family: var(--ol-serif); font-size: 17.5px; line-height: 1.5; text-wrap: pretty; }

/* The syllable boxes: a box a sung sound, as wide as its notes (--len, in beats) where the row allows, a gap a rest,
   a dotted line inside where the note changes on the same vowel; what it sounds like under it. A row too narrow for
   its boxes at their least wraps whole boxes onto the next line. */
.cp-ol-boxes { display: flex; flex-wrap: wrap; gap: 10px 6px; }
.cp-ol-box { flex: var(--len) 1 0%; min-width: min-content; display: grid; align-content: start; gap: 7px; text-align: center; }
.cp-ol-rest { flex: var(--len) 1 0%; min-width: 10px; }
.cp-ol-box-in { position: relative; display: grid; place-items: center; min-height: 54px; padding: 0 10px; border: 1px solid var(--h); background: var(--ht); font: 400 24px/1 var(--ol-serif); white-space: nowrap; }
.cp-ol-boxes[lang="ja"] .cp-ol-box-in { font-family: var(--ol-kana); font-size: 22px; }
.cp-ol-box-in i { position: absolute; inset-block: 0; inset-inline-start: calc(var(--at) * 100%); width: 2px; background: linear-gradient(var(--h) 0 11px, transparent 11px calc(100% - 11px), var(--h) calc(100% - 11px)); }
.cp-ol-tie .cp-ol-box-in { background: color-mix(in srgb, var(--h) 22%, var(--ht)); }
.cp-ol-box small { min-height: 1.3em; font: 400 12.5px/1.3 var(--ol-mono); color: var(--color-muted); }
.cp-ol-tie small { color: var(--h); }
/* A phone: each box as wide as its beats on one fixed scale (never narrower than its words), so a line too long for
   the screen wraps without stretching a lone box across the row. */
@media (max-width: 639px) { .cp-ol-box, .cp-ol-rest { flex: 0 0 auto; width: calc(var(--len) * 2.2rem); } .cp-ol-boxes { gap: 10px 5px; } .cp-ol-box-in { padding-inline: 6px; font-size: 21px; } }

/* The four first lines. */
.cp-ol-lines-head { display: grid; gap: 14px; padding-bottom: 28px; border-bottom: 1.5px solid var(--color-cream); }
@media (min-width: 900px) { .cp-ol-lines-head { grid-template-columns: minmax(0, 1fr) minmax(0, 380px); gap: 48px; align-items: end; } .cp-ol-lines-head .cp-ol-small { margin-top: 0; } }
.cp-ol-line { display: grid; gap: 14px; padding-block: 20px; border-bottom: 1px solid var(--ol-rule); }
@media (min-width: 900px) { .cp-ol-line { grid-template-columns: 210px minmax(0, 1fr); gap: 24px; align-items: start; } }
.cp-ol-line-name { display: grid; gap: 6px; }
.cp-ol-song { font-size: 26px; line-height: 1.1; }

/* The featured deck and the ladder's: the night in every theme, a stage inside, the notes in the page's rose. */
.cp-ol-demosec { padding-top: clamp(56px, 7vw, 88px); }
.cp-ol-deck { border: 1px solid var(--ol-deck-edge); border-radius: 6px; background: var(--ol-deck); color: var(--ol-deck-ink); box-shadow: 0 30px 70px -36px rgb(30 15 5 / .7); overflow: hidden; }
.cp-ol-demosec .cp-ol-deck { max-width: 920px; margin-inline: auto; }
.cp-ol-deck-bar { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 6px 14px; padding: 14px 22px; border-bottom: 1px solid var(--ol-deck-edge); font-size: 12px; font-weight: 700; letter-spacing: .18em; text-transform: uppercase; color: var(--ol-deck-muted); }
@media (min-width: 360px) { .cp-ol-deck-bar > span { white-space: nowrap; } }
.cp-ol-live { display: inline-flex; align-items: center; gap: 10px; color: var(--ol-deck-ink); }
.cp-ol-live i { width: 8px; height: 8px; background: var(--ol-rose); }
.cp-ol-ladder .cp-ol-live i { background: var(--ol-gold); }
.cp-ol-stage { position: relative; margin: clamp(12px, 2vw, 20px); padding: clamp(14px, 2.4vw, 24px); border-radius: 4px; background: var(--ol-deck-in); }
.cp-ol-stage svg { display: block; width: 100%; height: auto; }
.cp-ol-stage g[hidden] { display: none; }
.cp-ol-read { display: flex; justify-content: space-between; align-items: baseline; gap: 12px; margin-bottom: 4px; }
.cp-ol-read b { font-family: var(--ol-serif); font-style: italic; font-weight: 400; font-size: clamp(26px, 3.4vw, 36px); line-height: 1; color: var(--ol-rose); }
.cp-ol-read span { font-family: var(--ol-kana); font-size: clamp(15px, 1.8vw, 20px); color: var(--ol-deck-muted); letter-spacing: .1em; }
