.cp-ol-page { max-width: 1120px; margin: 40px auto 0; padding: 4px clamp(18px, 4vw, 48px) 8px; border: 1px solid var(--ol-rule); background: var(--ol-paper); }
.cp-ol-years > li { display: grid; gap: 14px; padding-block: 30px; border-top: 1px solid var(--ol-rule); }
