    .cp-ol-page { padding-block: 8px; background: linear-gradient(90deg, transparent calc(50% - .5px), var(--ol-rule) calc(50% - .5px) calc(50% + .5px), transparent calc(50% + .5px)) var(--ol-paper); }
    .cp-ol-years { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); column-gap: clamp(64px, 7vw, 96px); }
    .cp-ol-years > li { align-content: start; gap: 6px; padding-block: 22px; }
