.cp-ol-unit { border: 1px solid var(--ol-frame); border-radius: 4px; background: var(--ol-paper); overflow: hidden; }
.cp-ol-unit-head { display: flex; justify-content: space-between; align-items: flex-start; gap: 10px; padding: 18px 20px; border-bottom: 1px solid var(--ol-frame); background: var(--ht); }
