.cp-ol-lessons { margin-top: 16px; }
.cp-ol-lessons li { border-top: 1px solid var(--ol-rule); }
.cp-ol-lessons li > a, .cp-ol-lessons li:not(:has(a)) { display: flex; align-items: center; gap: 12px; min-height: 44px; font-size: 15px; }
