.cp-ol-lesson-n { flex: none; font: 400 13px/1 var(--ol-mono); color: var(--color-muted); }

/* Unit 4's ladder: the words beside the deck; ten rounds of the template's figure on one time axis, each round a
   step lower than the last while drifting flat, the true key a dashed line. */
.cp-ol-laddersec { margin-top: clamp(56px, 7vw, 88px); border-top: 1px solid var(--ol-rule); }
.cp-ol-ladder-grid { display: grid; gap: 32px; }
@media (min-width: 960px) { .cp-ol-ladder-grid { grid-template-columns: minmax(0, 5fr) minmax(0, 6fr); gap: 56px; align-items: start; } }
.cp-ol-ladder-in { padding: clamp(18px, 3vw, 26px); }
.cp-ol-ladder-stage { margin: 18px 0 0; }
.cp-ol-true { stroke: var(--ol-deck-muted); stroke-width: 1.5; stroke-dasharray: 5 5; opacity: .7; }
.cp-ol-true[data-on] { stroke: var(--ol-gold); opacity: 1; stroke-width: 2.5; }
.cp-ol-note { fill: var(--ol-gold); opacity: .45; transition: opacity .1s; }
.cp-ol-note[data-on] { opacity: 1; }
.cp-ol-rnd[data-on] .cp-ol-note:not([data-on]) { opacity: .75; }
.cp-ol-rnd { transition: transform .45s ease; }
.cp-ol-ladder[data-drift="flat"] .cp-ol-rnd { transform: translateY(calc(var(--k) * 2.5px)); }
.cp-ol-tempo { font: 500 11px/1 var(--ol-mono); fill: var(--ol-deck-muted); }
.cp-ol-figwords { display: flex; flex-wrap: wrap; justify-content: center; gap: 4px 18px; margin-top: 10px; font-family: var(--ol-serif); font-size: 26px; color: var(--ol-deck-body); }
.cp-ol-figwords span[data-on] { color: var(--ol-gold); }
.cp-ol-pick-row { margin-top: 12px; }
@media (max-width: 639px) { .cp-ol-tempo { font-size: 18px; } }

/* Lesson 1: the three steps, the first in Japanese's tint, beside what the app listens for. */
.cp-ol-first { display: grid; gap: 40px; }
@media (min-width: 960px) { .cp-ol-first { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 56px; align-items: start; } .cp-ol-inside { margin-top: 28px; } }
.cp-ol-steps { display: grid; gap: 8px; margin-top: 22px; }
.cp-ol-steps li { display: flex; align-items: center; gap: 16px; padding: 14px 18px; border: 1px solid var(--ol-rule); border-radius: 4px; background: var(--ol-paper); }
.cp-ol-steps li.cp-ol-ja { border-color: var(--h); background: var(--ht); }
.cp-ol-step-n { flex: none; display: grid; place-items: center; width: 30px; height: 30px; border: 1px solid var(--ol-frame); border-radius: 99px; font-size: 14px; font-weight: 650; }
.cp-ol-steps li.cp-ol-ja .cp-ol-step-n { border-color: var(--h); background: var(--h); color: var(--color-ink); }
.cp-ol-steps p { font-size: 15.5px; line-height: 1.5; }
.cp-ol-inside { padding: clamp(22px, 3.4vw, 34px); border: 1px solid var(--ol-frame); border-radius: 4px; background: var(--ol-paper); }

/* Margin notes: a pilcrow in each note's language hue, the note in the serif, its source in small capitals. */
