.cp-ol-note-src { margin-top: 10px; font: 400 11.5px/1.4 var(--ol-mono); letter-spacing: .1em; text-transform: uppercase; color: var(--color-muted); }
.cp-ol-notes + .cp-ol-more, .cp-ol-more .cp-ol-notes { margin-top: 0; }

/* Before you begin: three ruled columns. */
.cp-ol-kit { display: grid; gap: 32px; margin-top: 20px; }
