/* The close: Sakura's three boxes, "not sa-ku-ruh." with ruh struck through in red, then the way in. */
.cp-ol-close { margin-top: clamp(56px, 7vw, 88px); padding-bottom: clamp(48px, 6vw, 72px); border-top: 1px solid var(--ol-rule); background: var(--ol-wash); text-align: center; }
.cp-ol-close-in { display: grid; justify-items: center; }
.cp-ol-join { display: flex; flex-wrap: wrap; justify-content: center; align-items: center; gap: 12px 36px; margin-top: 26px; }
.cp-ol-join-boxes { display: flex; gap: 6px; }
.cp-ol-join-boxes span { display: grid; place-items: center; min-width: 1.6em; padding: 4px 12px; border: 1px solid var(--h); background: var(--ht); font-size: clamp(48px, 6vw, 72px); line-height: 1; }
.cp-ol-join-rest { font-size: clamp(40px, 5.2vw, 66px); line-height: 1.1; color: var(--color-muted); }
.cp-ol-join-rest .cp-ol-mk-em { font-style: italic; color: var(--color-cream); }
.cp-ol-join-rest .cp-ol-mk-struck { text-decoration: line-through 4px var(--ol-red); text-decoration-skip-ink: none; }
.cp-ol-close .cp-ol-body { margin-inline: auto; }
.cp-ol-btns-c { justify-content: center; }
.cp-ol-related-h { margin-top: 44px; }
.cp-ol .cp-related { justify-content: center; }
.cp-ol .cp-related a { border: 1px solid var(--ol-frame); background: var(--ol-paper); white-space: nowrap; }
/* A phone under 360 px (game's wider type, Spanish's longer words): the close's buttons and chips keep their one line
   by giving up some padding, never wrapping a label. */
