@media (max-width: 359px) { .cp-ol-btns a { padding-inline: 14px; gap: 6px; } .cp-ol .cp-related a { padding-inline: 11px; gap: 6px; } }

/* The sources: one list, two columns on a wide screen, folded on a phone. */
.cp-ol-sources { padding-block: 40px 8px; }
.cp-ol-sources summary { display: flex; align-items: center; min-height: 44px; cursor: pointer; list-style: none; }
.cp-ol-sources summary::-webkit-details-marker { display: none; }
.cp-ol-sources ol { margin-top: 14px; padding-inline-start: 22px; list-style: decimal; font-size: 14px; line-height: 1.55; color: var(--color-muted); }
@media (min-width: 900px) { .cp-ol-sources ol { columns: 2; column-gap: 48px; } }
.cp-ol-sources li { break-inside: avoid; padding-block: 3px; }
.cp-ol-sources a { text-decoration: underline; text-decoration-color: color-mix(in srgb, currentColor 35%, transparent); text-underline-offset: 3px; }
.cp-ol-sources li:target { color: var(--color-cream); }

@media (prefers-reduced-motion: reduce) { .cp-ol-tone, .cp-ol-slot, .cp-ol-note, .cp-ol-rnd { transition: none; } .cp-ol-tone[data-on] { filter: none; } }

/* Game mode: the same pieces in the arcade. Pixel headings and labels, reading text in the readable face; square
   frames with hard shadows; the decks the arcade's night with neon notes. */
:root[data-skin="game"] body.s-arcade :is(.cp-ol-h1, .cp-ol-h2, .cp-ol-h3, .cp-ol-deck-h, .cp-ol-join, .cp-ol-unit-body h3, .cp-ol-years h3, .cp-ol-read b) { font-family: var(--a-display); font-weight: 400; font-style: normal; letter-spacing: .01em; text-transform: uppercase; font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade .cp-ol-h1 { font-size: clamp(34px, 6.4vw, 72px); line-height: 1.05; text-shadow: .06em .06em 0 var(--arc-shade); }
:root[data-skin="game"] body.s-arcade :is(.cp-ol-h1 .cp-ol-mk-em, .cp-ol-h2 em, .cp-ol-join-rest .cp-ol-mk-em) { font-style: normal; }
:root[data-skin="game"] body.s-arcade :is(.cp-ol-h2, .cp-ol-h2-big) { font-size: clamp(26px, 3.6vw, 40px); line-height: 1.12; }
:root[data-skin="game"] body.s-arcade :is(.cp-ol-h3, .cp-ol-deck-h, .cp-ol-unit-body h3, .cp-ol-years h3, .cp-ol-read b) { font-size: clamp(18px, 2vw, 22px); line-height: 1.25; }
:root[data-skin="game"] body.s-arcade :is(.cp-ol-kick, .cp-ol-tag, .cp-ol-fig-head, .cp-ol-unit-n, .cp-ol-deck-bar, .cp-ol-when b, .cp-ol-kit h3, .cp-ol-asks h4 b, .cp-ol-pick legend) { font-family: var(--a-hud); font-weight: 400; letter-spacing: .06em; font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade :is(.cp-ol-fig, .cp-ol-deck, .cp-ol-asks, .cp-ol-page, .cp-ol-unit, .cp-ol-inside, .cp-ol-steps li, .cp-ol-stage, .cp-ol-box-in, .cp-ol-mora, .cp-ol-join-boxes span, .cp-ol-chip, .cp-ol-chip b, .cp-ol .cp-related a) { border-radius: 0; }
:root[data-skin="game"] body.s-arcade :is(.cp-ol-fig, .cp-ol-deck, .cp-ol-asks, .cp-ol-page, .cp-ol-unit, .cp-ol-inside) { border: var(--arc-edge-w, 2px) solid var(--arc-line); box-shadow: var(--arc-shadow); }
:root[data-skin="game"] body.s-arcade .cp-ol-deck { border-color: var(--ol-rose); box-shadow: var(--arc-shadow), 0 0 36px -14px var(--ol-rose); }
:root[data-skin="game"] body.s-arcade .cp-ol-ladder { border-color: var(--ol-gold); box-shadow: var(--arc-shadow), 0 0 36px -14px var(--ol-gold); }
:root[data-skin="game"] body.s-arcade :is(.cp-ol-hero, .cp-ol-archive, .cp-ol-close) { background: color-mix(in srgb, var(--arc-well) 70%, transparent); }
:root[data-skin="game"] body.s-arcade .cp-ol-box-in, :root[data-skin="game"] body.s-arcade .cp-ol-mora { border-width: 2px; }
:root[data-skin="game"] body.s-arcade :is(.cp-ol-tone[data-on], .cp-ol-note[data-on]) { filter: drop-shadow(0 0 6px currentColor); }
:root[data-skin="game"] body.s-arcade :is(.cp-ol-syl, .cp-ol-slotname, .cp-ol-wordname, .cp-ol-figwords) { font-family: var(--a-hud); font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade .cp-ol-syl { font-size: 22px; }
:root[data-skin="game"] body.s-arcade .cp-ol-slotname { font-size: 18px; }
:root[data-skin="game"] body.s-arcade .cp-ol-wordname { font-size: 15px; }
:root[data-skin="game"] body.s-arcade .cp-ol-figwords { font-size: 16px; }
:root[data-skin="game"] body.s-arcade .cp-ol-big { border-radius: 0; box-shadow: var(--arc-shadow); }
:root[data-skin="game"] body.s-arcade :is(.cp-ol-big-icon, .cp-ol-play-icon) { border-radius: 0; }
:root[data-skin="game"] body.s-arcade :is(.cp-ol-play, .cp-ol-pickb) { border-radius: 0; border-width: 2px; }
:root[data-skin="game"] body.s-arcade .cp-ol-steps li.cp-ol-ja .cp-ol-step-n { color: var(--arc-bg); }
@media (max-width: 639px) { :root[data-skin="game"] body.s-arcade .cp-ol-syl { font-size: 32px; } :root[data-skin="game"] body.s-arcade .cp-ol-slotname { font-size: 26px; } :root[data-skin="game"] body.s-arcade .cp-ol-wordname { font-size: 22px; } }

/* Breath and stamina (site/courses/breath-and-stamina), after Hillel's design of 2026-11-18: built around breath
   itself. A warm paper page in Figtree with mono labels: the held note on a seconds scale in the hero, the singer's
   comma as the breath mark, a bar on each section's label that fills a little more down the page (js/public/
   breath-and-stamina.js fills it as it comes into view), a night panel for the demo and the pacing, a pale teal panel
   for what the app hears, and a teal close with a breathing guide. Calm dark: the same page at night. Game skin: neon on
   the arcade's ground, Bungee headings and pixel labels, square frames with hard shadows. Motion is still under reduced
   motion (the end state). */
.cp-br { --br-paper: #f8f4ee; --br-card: #fff; --br-ink: #1e1915; --br-body: #3d3630; --br-muted: #5c544c; --br-faint: #6b6259; --br-line: #e0d7cb; --br-rule: #1e1915; --br-track: #ebe4da; --br-dash: #cfc5b8;
    --br-teal: #17675f; --br-teal-2: #2e8a7f; --br-gold: #e9b92f; --br-rust: #b5452e; --br-rust-text: #a83f2a; --br-label: #17675f; --br-tint: #e4efec; --br-tint-line: #c6dcd6; --br-pale: #cfe3de;
    --br-night: #17120f; --br-night-card: #241e1a; --br-night-deep: #0f0b09; --br-night-ink: #f4efe8; --br-night-body: #d3cabf; --br-night-muted: #a99f94; --br-night-line: #3a302a; --br-night-edge: #4a3f38; --br-mint: #7fd1c4; --br-pink: #f07a8a;
    --br-close: #17675f; --br-close-ink: #fff; --br-close-soft: #cde9e3; --br-orb: #e9f5f2; --br-orb-ring: #6fb3a8;
    --br-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
    --cp-a: var(--br-teal); --cp-a-ink: #fff; --cp-a-text: var(--br-label); --cp-line: var(--br-line);
    --color-cream: var(--br-ink); --color-muted: var(--br-muted); --fill-2: var(--br-track); --fill-3: var(--br-line);
    background: var(--br-paper); color: var(--br-ink); padding-bottom: 8px; }
:root:not([data-theme$="-light"]) .cp-br { --br-paper: var(--color-ink); --br-card: var(--color-panel); --br-ink: #f3ece2; --br-body: #d8cec2; --br-muted: #bcb0a2; --br-faint: #ab9f91; --br-line: #3a3029; --br-rule: #f3ece2; --br-track: #2d251f; --br-dash: #54483f;
    --br-teal: #2fa597; --br-teal-2: #3f9e93; --br-rust: #d0603f; --br-rust-text: #ff9a7f; --br-label: #7fd1c4; --br-tint: #13221f; --br-tint-line: #24403a; --br-pale: #24403a;
    --br-night: #0c0907; --br-night-card: #1d1814; --br-night-deep: #070504; --br-close: #145a53; --br-orb: #d9efe9; }
:root[data-skin="game"] .cp-br { --br-paper: #07060e; --br-card: #12101e; --br-ink: #ede9ff; --br-body: #d2ccf0; --br-muted: #b8b2d8; --br-faint: #aaa4d0; --br-line: #2a2640; --br-rule: #3be7ff; --br-track: #1d1a33; --br-dash: #3a3560;
    --br-teal: #45e3a5; --br-teal-2: #3be7ff; --br-gold: #ffd84a; --br-rust: #ff5fd2; --br-rust-text: #ff9de6; --br-label: #3be7ff; --br-tint: #0b1626; --br-tint-line: #1f3b4a; --br-pale: #1f3b4a;
    --br-night: #05040a; --br-night-card: #12101e; --br-night-deep: #020106; --br-night-ink: #ede9ff; --br-night-body: #d2ccf0; --br-night-muted: #aaa4d0; --br-night-line: #2a2640; --br-night-edge: #3be7ff66; --br-mint: #3be7ff; --br-pink: #ff5fd2;
    --br-close: #0b1a2e; --br-close-soft: #b9f4ff; --br-orb: #45e3a5; --br-orb-ring: #3be7ff;
    --cp-a: #45e3a5; --cp-a-ink: #04140d; }
:root[data-skin="game"][data-theme$="-light"] .cp-br { --br-paper: #f4f1ff; --br-card: #fff; --br-ink: #14122b; --br-body: #2e2950; --br-muted: #403a66; --br-faint: #4d4775; --br-line: #d9d3f2; --br-rule: #14122b; --br-track: #e6e1fa; --br-dash: #bdb5e3;
    --br-teal: #00708a; --br-teal-2: #0a8fa8; --br-gold: #b38600; --br-rust: #b0157a; --br-rust-text: #b0157a; --br-label: #00708a; --br-tint: #e3f4f7; --br-tint-line: #bfe1e8; --br-pale: #bfe1e8;
    --br-close: #00606f; --br-close-soft: #d4f6fb; --br-orb: #e3f4f7; --br-orb-ring: #9fe3ef; --cp-a: #00708a; --cp-a-ink: #fff; }
.cp-br a:not([class*="btn"]) { color: inherit; text-underline-offset: 3px; }
.cp-br .s-crumb, .cp-br .s-crumb a { color: var(--br-muted); }
.cp-br .btn-lg { white-space: nowrap; }
.cp-br-sec { padding-top: clamp(72px, 10vw, 128px); }

/* Type: heavy tight Figtree, and mono labels. */
.cp-br-h1 { margin-top: 18px; font-size: clamp(54px, 14vw, 132px); line-height: .88; font-weight: 800; letter-spacing: -0.05em; text-wrap: balance; }
.cp-br-title { margin-top: 18px; font-size: clamp(38px, 6.4vw, 60px); line-height: .96; font-weight: 800; letter-spacing: -0.04em; text-wrap: balance; }
.cp-br-sidelead, .cp-br-lead { font-size: 17px; line-height: 1.6; color: var(--br-body); text-wrap: pretty; }
.cp-br-small { margin-top: 20px; max-width: 580px; font-size: 14px; line-height: 1.55; color: var(--br-muted); }
.cp-br-label, .cp-br-eyebrow, .cp-br-kick, .cp-br-meta, .cp-br-unit-n, .cp-br-step-n { font-family: var(--br-mono); font-size: 12px; font-weight: 500; letter-spacing: .12em; text-transform: uppercase; }
.cp-br-label { color: var(--br-faint); }
.cp-br-comma { font-family: Figtree, system-ui, sans-serif; font-weight: 800; color: var(--br-rust); letter-spacing: 0; }
.cp-br-headrow { display: grid; grid-template-columns: minmax(0, 1fr); gap: 16px; }
.cp-br-headrow .cp-br-sidelead { margin-top: 0; }

/* The running label: its number, a bar that fills a little more each section down the page, and its word. */
.cp-br-kick { display: flex; align-items: center; gap: 14px; color: var(--br-label); }
.cp-br-kbar { position: relative; flex: none; width: 72px; height: 6px; border-radius: 3px; background: var(--br-track); overflow: hidden; }
.cp-br-kbar::after { content: ""; position: absolute; inset: 0 auto 0 0; width: var(--k); border-radius: 3px; background: var(--br-teal); transition: width 1.2s cubic-bezier(.3, .6, .3, 1); }
.cp-br-kbar[data-wait]::after { width: 0; }
@media (prefers-reduced-motion: reduce) { .cp-br-kbar::after { transition: none; } }

/* The hero: the eyebrow with its breath mark, the headline, the lead and the buttons, and the held note. */
.cp-br-hero { padding-top: 22px; }
.cp-br-hero-grid { display: grid; grid-template-columns: minmax(0, 1fr); gap: 24px; margin-top: 32px; }
.cp-br-eyebrow { color: var(--br-label); line-height: 1.6; }
.cp-br-eyebrow .cp-br-comma { display: inline-block; margin-inline-end: 10px; font-size: 28px; line-height: 0; vertical-align: -1px; }
.cp-br-btns { display: flex; flex-wrap: wrap; gap: 12px; margin-top: 26px; }
.cp-br-btns > * { flex: 1 1 auto; justify-content: center; }
.cp-br-held { margin-top: 52px; }
.cp-br-held-top { display: flex; justify-content: space-between; gap: 16px; margin-bottom: 10px; font-family: var(--br-mono); font-size: 12px; color: var(--br-faint); }
.cp-br-held-phase { color: var(--br-label); }
.cp-br-held-top b { font-weight: 600; color: var(--br-ink); }
.cp-br-held-track { position: relative; height: 56px; }
.cp-br-held-track::before { content: ""; position: absolute; inset: 27px 0 auto; height: 2px; background: repeating-linear-gradient(90deg, var(--br-dash) 0 6px, transparent 6px 12px); }
.cp-br-held-fill { position: absolute; left: 0; top: 18px; height: 20px; width: var(--at); border-radius: 10px 0 0 10px; background: var(--br-teal); }
.cp-br-held-cap { position: absolute; top: 4px; left: var(--at); width: 4px; height: 48px; border-radius: 2px; background: var(--br-ink); transition: opacity .3s; }
.cp-br-held-ring { position: absolute; left: -6px; top: 16px; width: 24px; height: 24px; border-radius: 99px; border: 2px solid var(--br-teal); opacity: 0; }
.cp-br-held[data-phase="in"] .cp-br-held-ring { opacity: 1; }
.cp-br-held[data-phase="in"] .cp-br-held-fill, .cp-br-held[data-phase="hold"] .cp-br-held-fill { border-radius: 10px; }
.cp-br-held:is([data-phase="in"], [data-phase="hold"]) :is(.cp-br-held-cap, .cp-br-held-foot b) { opacity: 0; }
.cp-br-held-ticks { display: grid; grid-template-columns: repeat(15, minmax(0, 1fr)); margin-top: 8px; font-family: var(--br-mono); font-size: 9.5px; color: var(--br-faint); }
.cp-br-held-ticks li { padding: 6px 0 0 3px; border-left: 1px solid var(--br-line); white-space: nowrap; }
.cp-br-held-ticks li:nth-child(even) { color: transparent; }
.cp-br-held-foot { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 6px 24px; margin-top: 18px; font-size: 14px; line-height: 1.5; color: var(--br-muted); }
.cp-br-held-foot b { font-weight: 600; color: var(--br-ink); transition: opacity .3s; }

/* The demo, End on purpose: a night panel in every look (a demo stays the night cabinet). */
.cp-br-demosec { margin-top: clamp(56px, 8vw, 96px); }
.cp-br-demo { border-radius: 24px; overflow: hidden; background: var(--br-night); color: var(--br-night-ink); border: 1px solid var(--br-night-line); }
.cp-br-demo-bar { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 6px 16px; padding: 14px 20px; border-bottom: 1px solid var(--br-night-line); font-family: var(--br-mono); font-size: 12px; letter-spacing: .1em; text-transform: uppercase; color: var(--br-night-muted); }
.cp-br-demo-live { display: inline-flex; align-items: center; gap: 8px; white-space: nowrap; }
.cp-br-dot { width: 7px; height: 7px; border-radius: 99px; background: var(--br-pink); }
.cp-br-demo-in { display: grid; grid-template-columns: minmax(0, 1fr); gap: 32px; padding: 28px 20px 26px; }
.cp-br-demo-h { font-size: clamp(34px, 5vw, 44px); line-height: 1; font-weight: 800; letter-spacing: -0.03em; }
.cp-br-demo-lead { margin-top: 16px; font-size: 16px; line-height: 1.6; color: var(--br-night-body); }
.cp-br-pick { margin: 26px 0 0; padding: 0; border: 0; }
.cp-br-pick legend { padding: 0; font-family: var(--br-mono); font-size: 11.5px; letter-spacing: .12em; text-transform: uppercase; color: var(--br-night-muted); }
.cp-br-pick-row { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 12px; }
.cp-br-hear, .cp-br-guess { display: inline-flex; align-items: center; justify-content: center; gap: 10px; min-height: 44px; border-radius: 99px; border: 1px solid var(--br-night-edge); background: transparent; color: var(--br-night-ink); font-size: 15px; font-weight: 650; white-space: nowrap; }
.cp-br-hear { padding: 5px 18px 5px 5px; }
.cp-br-hear:hover, .cp-br-guess:hover { border-color: var(--br-pink); }
.cp-br-hear-icon { position: relative; flex: none; width: 32px; height: 32px; border-radius: 99px; background: var(--br-pink); }
.cp-br-hear-icon::after { content: ""; position: absolute; inset: 10px 9px 10px 12px; background: var(--br-night); clip-path: polygon(0 0, 100% 50%, 0 100%); }
.cp-br-hear[aria-pressed="true"] .cp-br-hear-icon::after { inset: 11px; clip-path: none; border-radius: 1px; }
.cp-br-guess { min-width: 64px; padding: 0 20px; font-weight: 750; }
.cp-br-guess[data-right] { background: #17675f; border-color: #17675f; color: #fff; }
.cp-br-guess[data-right]::before { content: "\2713"; }
.cp-br-guess[data-wrong] { border-color: var(--br-pink); }
.cp-br-guess[data-wrong]::before { content: "\2715"; color: var(--br-pink); }
.cp-br-heard { margin-top: 12px; max-width: 46ch; font-size: 14px; line-height: 1.45; color: var(--br-night-body); }
.cp-br-heard:empty { display: none; }
.cp-br-roll { padding: 18px 16px 8px; border-radius: 16px; background: var(--br-night-deep); }
.cp-br-roll-top { display: flex; justify-content: space-between; gap: 12px; min-height: 18px; font-family: var(--br-mono); font-size: 12px; color: var(--br-night-muted); }
.cp-br-roll-top span:last-child { color: var(--br-night-ink); font-variant-numeric: tabular-nums; }
.cp-br-roll svg { display: block; width: 100%; height: auto; margin-top: 4px; overflow: visible; }
.cp-br-roll-staff, .cp-br-roll-tick { stroke: var(--br-night-line); stroke-width: 1.5; fill: none; }
.cp-br-roll-band { fill: var(--br-pink); opacity: .16; }
.cp-br-roll-band[data-on] { fill: var(--br-mint); opacity: .45; }
.cp-br-roll-note { fill: var(--br-night-line); }
.cp-br-roll-note[data-on] { fill: color-mix(in srgb, var(--br-gold) 35%, var(--br-night-line)); }
.cp-br-roll-vowel { font: 500 14px/1 var(--br-mono); fill: var(--br-night-muted); }
.cp-br-roll-line { stroke: var(--br-pink); stroke-width: 3; stroke-linecap: round; }
.cp-br-roll-letgo { font: 500 12px/1 var(--br-mono); letter-spacing: .1em; text-transform: uppercase; fill: var(--br-pink); text-anchor: middle; }
.cp-br-roll-count { fill: var(--br-night-line); }
.cp-br-roll-count[data-on] { fill: var(--br-gold); }
.cp-br-roll-n { font: 500 12px/1 var(--br-mono); fill: var(--br-night-muted); }
@media (max-width: 599px) { .cp-br-roll :is(.cp-br-roll-letgo, .cp-br-roll-n, .cp-br-roll-vowel) { font-size: 20px; } }
.cp-br-roll-trace { fill: none; stroke: var(--br-gold); stroke-width: 6; stroke-linecap: round; stroke-linejoin: round; }
.cp-br-roll-head { fill: var(--br-gold); stroke: var(--br-night-deep); stroke-width: 3; }
.cp-br-hold-row { display: flex; flex-wrap: wrap; align-items: center; gap: 14px 20px; margin-top: 20px; }
.cp-br-press { display: inline-flex; align-items: center; gap: 12px; min-height: 60px; padding: 10px 26px 10px 10px; border: 0; border-radius: 99px; background: var(--br-gold); color: #17120f; font-size: 18px; font-weight: 800; white-space: nowrap; touch-action: none; user-select: none; -webkit-user-select: none; -webkit-touch-callout: none; }
.cp-br-press-icon { position: relative; flex: none; width: 40px; height: 40px; border-radius: 99px; background: #17120f; }
.cp-br-press-icon::after { content: ""; position: absolute; inset: 13px 12px 13px 16px; background: var(--br-gold); clip-path: polygon(0 0, 100% 50%, 0 100%); }
.cp-br-press[aria-pressed="true"] { background: color-mix(in srgb, var(--br-gold) 60%, #fff); }
.cp-br-press[data-on] { box-shadow: 0 0 32px var(--br-gold); }
@media (prefers-reduced-motion: no-preference) { .cp-br-press[data-on] { --color-accent: var(--br-gold); animation: celebrate-glow 1s 2; } }
.cp-br-say { flex: 1 1 240px; max-width: 360px; font-size: 14px; font-weight: 600; line-height: 1.45; color: var(--br-gold); }
.cp-br-demo-note { margin-top: 16px; font-size: 13px; line-height: 1.6; color: var(--br-night-muted); }
.cp-br-demo-note b { font-weight: 650; color: var(--br-night-body); }
.cp-br-demo-note a { color: var(--br-night-body); text-decoration: underline; }

/* 01, the ending: two pitch lines, one sagging, one stopping clean. */
.cp-br-ends { display: grid; grid-template-columns: minmax(0, 1fr); gap: 16px; margin-top: 32px; }
.cp-br-end { margin: 0; padding: 22px; border-radius: 20px; background: var(--br-card); border: 1px solid var(--br-line); }
.cp-br-end-good { padding: 21px; border: 2px solid var(--br-teal); }
.cp-br-end svg { display: block; width: 100%; height: auto; }
.cp-br-end-ref { stroke: var(--br-dash); stroke-width: 1.5; stroke-dasharray: 4 6; fill: none; }
.cp-br-end-sag { fill: none; stroke: var(--br-rust); stroke-width: 10; stroke-linecap: round; }
.cp-br-end-crack { fill: none; stroke: var(--br-rust); stroke-width: 4; stroke-dasharray: 2 8; stroke-linecap: round; }
.cp-br-end-steady { fill: none; stroke: var(--br-teal); stroke-width: 10; stroke-linecap: round; }
.cp-br-end-air { fill: none; stroke: var(--br-teal); stroke-opacity: .2; stroke-width: 10; }
.cp-br-end-stop { stroke: var(--br-ink); stroke-width: 4; stroke-linecap: round; }
.cp-br-end-label { font: 500 13px/1 var(--br-mono); fill: var(--br-faint); text-anchor: end; }
.cp-br-end-label-air { fill: var(--br-label); text-anchor: middle; }
.cp-br-end figcaption { margin-top: 14px; font-size: 15px; line-height: 1.5; color: var(--br-muted); }
.cp-br-end-head { display: flex; flex-wrap: wrap; align-items: baseline; justify-content: space-between; gap: 4px 16px; margin-bottom: 6px; }
.cp-br-end-head b { font-size: 22px; font-weight: 800; letter-spacing: -0.01em; color: var(--br-ink); }
.cp-br-end-tag { font-family: var(--br-mono); font-size: 12px; color: var(--br-label); }
.cp-br-end-tag-out { color: var(--br-rust-text); }

/* 02, by the end: ruled rows, each with its bar a step fuller. */
.cp-br-aims { margin-top: 32px; border-top: 1px solid var(--br-rule); }
.cp-br-aims li { display: grid; grid-template-columns: 40px minmax(0, 1fr); gap: 10px 16px; align-items: center; padding: 22px 0; border-bottom: 1px solid var(--br-line); }
.cp-br-aim-n { font-family: var(--br-mono); font-size: 14px; color: var(--br-faint); }
.cp-br-aims p { font-size: 19px; font-weight: 600; line-height: 1.32; letter-spacing: -0.015em; text-wrap: pretty; }
.cp-br-aim-bar { grid-column: 2; position: relative; height: 10px; border-radius: 6px; background: var(--br-track); overflow: hidden; }
.cp-br-aim-bar::after { content: ""; position: absolute; inset: 0 auto 0 0; width: var(--k); border-radius: 6px; background: var(--br-teal); }

/* 03, the course: four phrases with breath marks between, every lesson a link to its page. */
.cp-br-meta { color: var(--br-muted); letter-spacing: .04em; text-transform: none; font-size: 13px; }
.cp-br-map-lead { font-size: 16px; }
.cp-br-map-lead .cp-br-comma { font-size: 1.3em; line-height: 0; }
.cp-br-map { display: grid; grid-template-columns: minmax(0, 1fr); gap: 44px 28px; margin-top: 40px; }
.cp-br-unit { --u: var(--br-teal); position: relative; }
.cp-br-unit-2 { --u: var(--br-teal-2); } .cp-br-unit-3 { --u: var(--br-gold); } .cp-br-unit-4 { --u: var(--br-rust); }
.cp-br-phrase { position: relative; display: flex; align-items: center; gap: 4px; height: 40px; padding-right: 30px; }
.cp-br-phrase span { flex: 1; height: 14px; border-radius: 3px; background: var(--u); }
.cp-br-phrase .cp-br-comma { position: absolute; right: 6px; top: -10px; font-size: 44px; line-height: 1; }
.cp-br-unit-n { margin-top: 16px; color: var(--br-rust-text); }
.cp-br-unit h3 { margin-top: 8px; font-size: 24px; font-weight: 800; letter-spacing: -0.02em; line-height: 1.15; }
.cp-br-unit-say { margin-top: 8px; font-size: 15px; line-height: 1.5; color: var(--br-muted); }
.cp-br-lessons { margin-top: 16px; border-top: 1px solid var(--br-line); }
.cp-br-lessons li { border-bottom: 1px solid var(--br-line); }
.cp-br-lessons :is(a, li > b) { display: flex; flex-direction: column; gap: 3px; min-height: 44px; padding: 12px 0; text-decoration: none; }
.cp-br-lessons b { font-size: 16px; font-weight: 700; }
.cp-br-lessons span { font-size: 13.5px; line-height: 1.4; color: var(--br-faint); }
.cp-br-lessons a:hover b, .cp-br-lessons a:focus-visible b { color: var(--br-label); text-decoration: underline; text-underline-offset: 3px; }

/* 04, pacing: a night band, the set drawn as a row, and the rules. */
.cp-br-band { margin-top: clamp(72px, 10vw, 128px); padding-block: clamp(64px, 9vw, 110px); background: var(--br-night); color: var(--br-night-ink); }
.cp-br-band .cp-br-kick { color: var(--br-mint); }
.cp-br-band .cp-br-kbar { background: var(--br-night-line); }
.cp-br-band .cp-br-kbar::after { background: var(--br-mint); }
.cp-br-band .cp-br-sidelead { color: var(--br-night-body); }
.cp-br-pace { margin: 40px 0 0; padding: 22px 20px; border-radius: 20px; background: var(--br-night-card); }
.cp-br-pace figcaption { font-family: var(--br-mono); font-size: 12px; letter-spacing: .08em; text-transform: uppercase; color: var(--br-night-muted); }
.cp-br-pace-row { display: flex; flex-wrap: wrap; align-items: center; gap: 10px 8px; margin-top: 20px; }
.cp-br-pace-breath { flex: none; display: inline-block; width: 18px; height: 18px; border-radius: 99px; border: 2px solid var(--br-mint); }
.cp-br-pace-hold { flex: none; display: inline-block; width: 56px; height: 14px; border-radius: 7px; background: var(--br-gold); }
.cp-br-pace-rest { flex: none; display: inline-block; width: 72px; height: 14px; border-radius: 7px; border: 1.5px dashed var(--br-night-muted); }
.cp-br-pace-key { display: flex; flex-wrap: wrap; gap: 10px 28px; margin-top: 22px; font-size: 14px; line-height: 1.4; color: var(--br-night-body); }
.cp-br-pace-key li { display: flex; align-items: center; gap: 8px; }
.cp-br-pace-key .cp-br-pace-breath { width: 14px; height: 14px; }
.cp-br-pace-key :is(.cp-br-pace-hold, .cp-br-pace-rest) { width: 36px; height: 12px; }
.cp-br-rules { display: grid; grid-template-columns: minmax(0, 1fr); gap: 0 48px; margin-top: 36px; }
.cp-br-rules li { display: flex; gap: 16px; padding: 20px 0; border-top: 1px solid var(--br-night-line); font-size: 16px; line-height: 1.5; }
.cp-br-rules span { flex: none; padding-top: 2px; font-family: var(--br-mono); font-size: 13px; color: var(--br-mint); }

/* 05, try one now: four steps, each with a bar that is the step (warm up, breathe in, sing, stop). */
.cp-br-steps { display: grid; grid-template-columns: minmax(0, 1fr); gap: 28px 24px; margin-top: 32px; }
.cp-br-step-mark { display: flex; align-items: center; height: 28px; }
.cp-br-step-mark::before { content: ""; width: 100%; height: 14px; border-radius: 7px; background: var(--br-teal); }
.cp-br-step-1 .cp-br-step-mark::before { height: 6px; border-radius: 3px; background: repeating-linear-gradient(90deg, var(--br-teal) 0 10px, transparent 10px 16px); }
.cp-br-step-2 .cp-br-step-mark::before { height: 24px; border-radius: 12px; background: linear-gradient(90deg, var(--br-tint), var(--br-teal)); }
.cp-br-step-4 .cp-br-step-mark::before { background: linear-gradient(90deg, var(--br-teal) 60%, var(--br-ink) 60% 63%, var(--br-pale) 63%); }
.cp-br-step-n { margin-top: 16px; color: var(--br-label); }
.cp-br-steps li > p:last-child { margin-top: 10px; font-size: 17px; line-height: 1.5; text-wrap: pretty; }

/* 06, listening: what the app hears, beside a sample result card (labelled as a sample). */
.cp-br-listen { display: grid; grid-template-columns: minmax(0, 1fr); gap: 36px; padding: 34px 20px; border-radius: 28px; background: var(--br-tint); }
.cp-br-listen .cp-br-kbar { background: var(--br-tint-line); }
.cp-br-hears { margin-top: 26px; }
.cp-br-hears li { display: flex; justify-content: space-between; align-items: baseline; gap: 16px; padding: 13px 0; border-bottom: 1px solid var(--br-tint-line); font-size: 16px; line-height: 1.45; }
.cp-br-by { flex: none; font-family: var(--br-mono); font-size: 12px; color: var(--br-label); white-space: nowrap; }
.cp-br-by-you { color: var(--br-rust-text); }
.cp-br-sample { margin: 0; padding: 24px 22px; border-radius: 20px; background: var(--br-card); box-shadow: 0 24px 60px -30px color-mix(in srgb, var(--br-teal) 55%, transparent); }
.cp-br-sample-top { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: center; gap: 8px 12px; font-family: var(--br-mono); font-size: 12px; letter-spacing: .08em; text-transform: uppercase; color: var(--br-faint); }
.cp-br-sample-tag { padding: 3px 10px; border-radius: 99px; border: 1.5px dashed var(--br-rust-text); color: var(--br-rust-text); font-weight: 600; }
.cp-br-sample-title { margin-top: 18px; font-size: 18px; font-weight: 700; }
.cp-br-sample-n { display: flex; flex-wrap: wrap; align-items: baseline; gap: 4px 10px; margin-top: 4px; font-size: 16px; color: var(--br-muted); }
.cp-br-sample-n b { font-size: 64px; font-weight: 800; line-height: 1; letter-spacing: -0.04em; color: var(--br-ink); }
.cp-br-sample-bar { position: relative; display: block; height: 16px; margin-top: 22px; border-radius: 8px; background: var(--br-track); }
.cp-br-sample-bar::before { content: ""; position: absolute; inset: 0 auto 0 0; width: var(--at); border-radius: 8px 0 0 8px; background: var(--br-teal); }
.cp-br-sample-bar::after { content: ""; position: absolute; top: -6px; left: var(--at); width: 3px; height: 28px; border-radius: 2px; background: var(--br-ink); }
.cp-br-sample-scale { display: flex; justify-content: space-between; margin-top: 10px; font-family: var(--br-mono); font-size: 11.5px; color: var(--br-faint); }
.cp-br-sample-end { margin-top: 20px; padding-top: 16px; border-top: 1px solid var(--br-track); font-size: 15px; color: var(--br-body); }

/* 07, why it works: three facts under heavy rules, each with its source. */
.cp-br-facts { display: grid; grid-template-columns: minmax(0, 1fr); gap: 32px 40px; margin-top: 32px; }
.cp-br-facts li { padding-top: 18px; border-top: 4px solid var(--br-rule); }
.cp-br-facts h3 { font-size: 30px; font-weight: 800; line-height: 1; letter-spacing: -0.03em; }
.cp-br-facts li > p { margin-top: 14px; font-size: 16px; line-height: 1.55; color: var(--br-body); text-wrap: pretty; }
.cp-br-facts .cp-br-src { margin-top: 14px; font-family: var(--br-mono); font-size: 11.5px; letter-spacing: .06em; text-transform: uppercase; color: var(--br-faint); }
.cp-br-src a:hover, .cp-br-src a:focus-visible { color: var(--br-label); }

/* 08, before you start: who, what you need, and the songs. */
.cp-br-who { display: grid; grid-template-columns: minmax(0, 1fr); gap: 32px 40px; margin-top: 32px; }
.cp-br-lines li { padding: 15px 0; border-bottom: 1px solid var(--br-line); font-size: 17px; line-height: 1.5; }
.cp-br-lines { margin-top: 6px; }
.cp-br-songs { align-self: start; padding: 22px 24px 10px; border-radius: 20px; background: var(--br-card); border: 1px solid var(--br-line); }
.cp-br-songs .cp-br-label { color: var(--br-rust-text); }
.cp-br-songs li { padding: 14px 0; border-bottom: 1px solid var(--br-track); }
.cp-br-songs li:last-child { border-bottom: 0; }
.cp-br-songs b { display: block; font-size: 17px; font-weight: 700; }
.cp-br-songs li span { display: block; margin-top: 2px; font-size: 14px; color: var(--br-faint); }

/* 09, questions, beside their heading. */
.cp-br-fine { display: grid; grid-template-columns: minmax(0, 1fr); gap: 24px; }
.cp-br-fine .cp-faq { margin-top: 0; max-width: none; border-top: 1px solid var(--br-rule); }
.cp-br-fine .cp-faq details p { color: var(--br-muted); }

/* The close: take a breath, with a breathing guide that grows, holds and shrinks. */
.cp-br-closesec { padding-top: clamp(72px, 10vw, 128px); }
.cp-br-close { --primary: #fff; --primary-ink: #14201e; --primary-hover-to: #cde9e3; --color-cream: #fff; --btn-soft: rgb(255 255 255 / .14); --btn-soft-hover: rgb(255 255 255 / .22); --btn-soft-active: rgb(255 255 255 / .3); --btn-outline: inset 0 0 0 1.5px rgb(255 255 255 / .5);
    display: grid; grid-template-columns: minmax(0, 1fr); gap: 40px; padding: 44px 22px; border-radius: 28px; background: var(--br-close); color: var(--br-close-ink); overflow: hidden; }
.cp-br-kick-close { color: var(--br-close-soft); }
.cp-br-close-h { margin-top: 16px; font-size: clamp(52px, 9vw, 88px); font-weight: 800; line-height: .92; letter-spacing: -0.05em; }
.cp-br-close-lead { margin-top: 20px; max-width: 520px; font-size: 18px; line-height: 1.6; color: var(--br-close-ink); }
.cp-br-close-note { margin-top: 16px; font-size: 14px; line-height: 1.5; color: var(--br-close-soft); }
.cp-br-guide { display: flex; flex-direction: column; align-items: center; gap: 20px; }
.cp-br-guide-ring { display: grid; place-items: center; width: 220px; height: 220px; border-radius: 99px; border: 1.5px dashed var(--br-orb-ring); }
.cp-br-guide-orb { width: 186px; height: 186px; border-radius: 99px; background: var(--br-orb); transform: scale(.72); }
.cp-br-guide-cues { display: flex; flex-wrap: wrap; justify-content: center; gap: 4px 16px; font-family: var(--br-mono); font-size: 13px; letter-spacing: .14em; text-transform: uppercase; color: var(--br-close-soft); text-align: center; }
@media (prefers-reduced-motion: no-preference) {
    .cp-br-guide-orb { animation: cp-br-breathe 10s ease-in-out infinite; }
    .cp-br-guide-cues { position: relative; display: block; width: 100%; height: 1.5em; }
    .cp-br-guide-cues span { position: absolute; inset: 0; opacity: 0; animation: 10s linear infinite; }
    .cp-br-guide-cues span:nth-child(1) { animation-name: cp-br-cue-in; }
    .cp-br-guide-cues span:nth-child(2) { animation-name: cp-br-cue-hold; }
    .cp-br-guide-cues span:nth-child(3) { animation-name: cp-br-cue-out; }
}
@keyframes cp-br-breathe { 0% { transform: scale(.45); } 40%, 50% { transform: scale(1); } 100% { transform: scale(.45); } }
@keyframes cp-br-cue-in { 0%, 38% { opacity: 1; } 40%, 100% { opacity: 0; } }
@keyframes cp-br-cue-hold { 0%, 39% { opacity: 0; } 41%, 48% { opacity: 1; } 50%, 100% { opacity: 0; } }
@keyframes cp-br-cue-out { 0%, 49% { opacity: 0; } 51%, 97% { opacity: 1; } 100% { opacity: 0; } }
.cp-br-more { display: flex; flex-wrap: wrap; align-items: center; gap: 12px 16px; margin-top: 28px; }
.cp-br-more .cp-related { margin-top: 0; }
/* The map above lists every lesson as a link to its page, so the shared list of lesson pages under the page, and the
   related list's own All courses (the close's button says it), aren't shown twice. */
.cp-br-more .cp-related-all, .cp-br ~ [data-lesson-pages] { display: none; }

@media (min-width: 600px) {
    .cp-br-btns > * { flex: 0 0 auto; }
    .cp-br-held-ticks { font-size: 11px; }
    .cp-br-held-ticks li { padding-left: 4px; }
    .cp-br-held-ticks li:nth-child(even) { color: inherit; }
    .cp-br-kbar { width: 120px; }
    .cp-br-demo-bar { padding: 16px 28px; }
    .cp-br-pace { padding: 30px 32px; }
    .cp-br-pace-hold { width: 96px; }
    .cp-br-pace-rest { width: 120px; }
}
@media (min-width: 700px) {
    .cp-br-ends { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 20px; }
    .cp-br-map { grid-template-columns: repeat(2, minmax(0, 1fr)); }
    .cp-br-steps { grid-template-columns: repeat(2, minmax(0, 1fr)); }
    .cp-br-end { padding: 28px; } .cp-br-end-good { padding: 27px; }
}
@media (min-width: 900px) {
    .cp-br-hero-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 40px 56px; align-items: end; margin-top: 44px; }
    .cp-br-hero-side { padding-bottom: 10px; }
    .cp-br-lead { font-size: 19px; }
    .cp-br-held { margin-top: 72px; }
    .cp-br-headrow { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 48px; align-items: end; }
    .cp-br-headrow-map { grid-template-columns: minmax(0, 1fr) auto; }
    .cp-br-sidelead { font-size: 18px; }
    .cp-br-demo-in { grid-template-columns: minmax(0, 1fr) minmax(0, 1.35fr); gap: 48px; padding: 44px 40px 40px; }
    .cp-br-roll { padding: 26px 24px 12px; }
    .cp-br-ends { margin-top: 48px; }
    .cp-br-aims { margin-top: 40px; }
    .cp-br-aims li { grid-template-columns: 80px minmax(0, 1fr) minmax(0, .8fr); gap: 24px; padding: 26px 0; }
    .cp-br-aims p { font-size: 24px; }
    .cp-br-aim-bar { grid-column: auto; height: 12px; }
    .cp-br-pace { margin-top: 56px; }
    .cp-br-rules { grid-template-columns: repeat(2, minmax(0, 1fr)); margin-top: 40px; }
    .cp-br-steps { margin-top: 48px; }
    .cp-br-listen { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 56px; align-items: center; padding: 64px 56px; }
    .cp-br-sample { padding: 28px; }
    .cp-br-facts { grid-template-columns: repeat(3, minmax(0, 1fr)); margin-top: 48px; }
    .cp-br-who { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr) minmax(0, .9fr); margin-top: 44px; }
    .cp-br-fine { grid-template-columns: minmax(0, .7fr) minmax(0, 1.3fr); gap: 48px; align-items: start; }
    .cp-br-close { grid-template-columns: minmax(0, 1.3fr) minmax(0, 1fr); gap: 48px; align-items: center; padding: 80px 56px; }
    .cp-br-guide-ring { width: 260px; height: 260px; }
    .cp-br-guide-orb { width: 220px; height: 220px; }
}
@media (min-width: 1100px) {
    .cp-br-map { grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 0; margin-top: 44px; }
    .cp-br-unit { padding-right: 28px; }
    .cp-br-phrase { padding-right: 0; }
    .cp-br-phrase .cp-br-comma { right: -22px; top: -12px; }
    .cp-br-unit-say { min-height: 68px; }
    .cp-br-steps { grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 24px; }
}

/* The game skin: the arcade's Bungee headings and pixel labels, square frames with hard shadows, the same words. */
:root[data-skin="game"] body.s-arcade .cp-br :is(.cp-br-h1, .cp-br-title, .cp-br-demo-h, .cp-br-close-h, .cp-br-facts h3, .cp-br-sample-n b) { font-family: var(--a-display); font-weight: 400; letter-spacing: .01em; text-transform: uppercase; font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade .cp-br-title { font-size: clamp(30px, 5.4vw, 50px); line-height: 1; }
:root[data-skin="game"] body.s-arcade .cp-br-close-h { font-size: clamp(38px, 7vw, 72px); }
:root[data-skin="game"] body.s-arcade .cp-br :is(.cp-br-label, .cp-br-eyebrow, .cp-br-kick, .cp-br-unit-n, .cp-br-step-n, .cp-br-demo-bar, .cp-br-pick legend, .cp-br-held-top, .cp-br-pace figcaption, .cp-br-sample-top, .cp-br-by, .cp-br-end-tag, .cp-br-roll-top) { font-family: "Stackapella Pixel", ui-monospace, monospace; font-size: 9.5px; line-height: 1.7; letter-spacing: .06em; font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade .cp-br :is(.cp-br-demo, .cp-br-roll, .cp-br-end, .cp-br-listen, .cp-br-sample, .cp-br-songs, .cp-br-pace, .cp-br-close, .cp-br-hear, .cp-br-guess, .cp-br-press, .cp-br-sample-tag, .cp-related a) { border-radius: 0; }
:root[data-skin="game"] body.s-arcade .cp-br :is(.cp-br-demo, .cp-br-close) { border: 2px solid #3be7ff; box-shadow: 6px 6px 0 #ff5fd2; }
:root[data-skin="game"] body.s-arcade .cp-br :is(.cp-br-end, .cp-br-sample, .cp-br-songs, .cp-br-listen) { border: 2px solid var(--br-label); box-shadow: 4px 4px 0 var(--br-rust); }
:root[data-skin="game"] body.s-arcade .cp-br :is(.cp-br-held-fill, .cp-br-roll-trace, .cp-br-phrase span) { filter: drop-shadow(0 0 6px var(--br-teal)); }
:root[data-skin="game"] body.s-arcade .cp-br-press { box-shadow: 4px 4px 0 #ff5fd2; }
:root[data-skin="game"][data-theme$="-light"] body.s-arcade .cp-br :is(.cp-br-held-fill, .cp-br-roll-trace, .cp-br-phrase span) { filter: none; }

/* Perfect your pitch (site/courses/perfect-your-pitch): an archery range, after Hillel's design (2026-11-18,
   ~/Code/course-designs/perfect-your-pitch). A cream sports-poster page: heavy italic headlines, tracked labels with a
   gold dot ringed in red, the board's colours (gold, red, blue, black, white) for the four ends, and the cents measure
   in a quiet monospace (the system's: no new font). The hero is the headline beside Bullseye, lesson 1's game, on its
   dark stage in every look; the cents ruler under them. Two dark bands (On target, The readout). Calm dark: the same
   range at dusk, candle-warm. Game skin: neon rings and glowing arrows on a night range, Bungee and Press Start.
   Sounds: js/public/perfect-your-pitch.js (one at a time, through js/public/demo-player.js). */
.cp-pt2, body:has(main.cp-pt2) { --pt-paper: #faf6f0; --pt-card: #fff; --pt-ink: #1c1613; --pt-body: #4a4038; --pt-muted: #645850; --pt-line: #e6dccd; --pt-label: #1e2d5e; --pt-num: #1e2d5e;
    --pt-gold: #f2c94c; --pt-red: #e03a3a; --pt-red-text: #b42323; --pt-blue: #2a8fd6; --pt-navy: #1e2d5e; --pt-black: #1c1613; --pt-white: #fbf8f2; --pt-tick: #1f7a45;
    --pt-sol: #1e2d5e; --pt-sol-ink: #fff; --pt-rule: #1c1613;
    --pt-band: #17110e; --pt-band-ink: #faf6f0; --pt-band-body: #d3c9bd; --pt-band-card: #231b17; --pt-band-muted: #b9ab9c; --pt-band-label: #f2c94c; --pt-band-edge: #3a3029;
    --pt-stage: #141010; --pt-stage-edge: #2a2320; --pt-stage-ink: #faf6f0; --pt-stage-body: #d3c9bd; --pt-stage-muted: #b9aea2;
    --pt-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
    --cp-a: #1e2d5e; --cp-a-ink: #fff; --cp-a-text: #1e2d5e; --cp-line: var(--pt-line); }
.cp-pt2 { background: var(--pt-paper); color: var(--pt-ink); }
:root:not([data-theme$="-light"]) .cp-pt2, :root:not([data-theme$="-light"]) body:has(main.cp-pt2) { --pt-paper: #15110e; --pt-card: #1f1915; --pt-ink: #f3ece2; --pt-body: #d8cec2; --pt-muted: #b3a797; --pt-line: #3a3029; --pt-label: #f2c94c; --pt-num: #9fb6f2;
    --pt-red-text: #ff8f80; --pt-white: #ece6da; --pt-black: #0e0b09; --pt-tick: #7fd49c; --pt-band: #221a15; --pt-band-card: #2d241e; --pt-band-edge: #46392f;
    --pt-sol: #3651a0; --pt-rule: #b3a797; --pt-stage: #0d0a08; --pt-stage-edge: #3a3029; --cp-a: #2c4688; --cp-a-text: #f2c94c; }
:root[data-skin="game"] .cp-pt2, :root[data-skin="game"] body:has(main.cp-pt2) { --pt-paper: #07060e; --pt-card: #12101e; --pt-ink: #ede9ff; --pt-body: #d2ccf0; --pt-muted: #b8b2d8; --pt-line: #2a2640; --pt-label: #3be7ff; --pt-num: #ffd84a;
    --pt-gold: #ffd84a; --pt-red: #ff5fd2; --pt-red-text: #ff9de6; --pt-blue: #3be7ff; --pt-navy: #12101e; --pt-black: #0b0718; --pt-white: #1b1036; --pt-tick: #a3e635;
    --pt-sol: #12101e; --pt-sol-ink: #3be7ff; --pt-rule: #3be7ff;
    --pt-band: #0c0a17; --pt-band-ink: #ede9ff; --pt-band-body: #d2ccf0; --pt-band-card: #16133a; --pt-band-muted: #b8b2d8; --pt-band-label: #ffd84a; --pt-band-edge: #3be7ff55;
    --pt-stage: #0b0820; --pt-stage-edge: #3be7ff66; --pt-stage-ink: #ede9ff; --pt-stage-body: #d2ccf0; --pt-stage-muted: #b8b2d8;
    --cp-a: #ffd84a; --cp-a-ink: #1a1400; --cp-a-text: #ffd84a; }
:root[data-skin="game"][data-theme$="-light"] .cp-pt2, :root[data-skin="game"][data-theme$="-light"] body:has(main.cp-pt2) { --pt-paper: #f4f1ff; --pt-card: #fff; --pt-ink: #14122b; --pt-body: #2e2950; --pt-muted: #403a66; --pt-line: #d9d3f2; --pt-label: #00708a; --pt-num: #b0157a;
    --pt-red-text: #b0157a; --pt-white: #fff; --pt-black: #14122b; --pt-tick: #3d7a00; --pt-sol: #fff; --pt-sol-ink: #00708a; --pt-rule: #14122b;
    --pt-band: #14122b; --pt-band-card: #201d40; --cp-a: #b0157a; --cp-a-ink: #fff; --cp-a-text: #b0157a; }
/* The page's ground runs on under the footer, with no seam; the shared lesson list isn't repeated (every lesson is
   linked in Four ends: the view says @section('lesson-pages-inline'), and this hides the list until the shared
   layout reads it). */
body:has(main.cp-pt2) { background: var(--pt-paper); }
main.cp-pt2 ~ [data-lesson-pages] { display: none; }
.cp-pt2 [hidden] { display: none !important; }
/* A link to the demo (/courses/perfect-your-pitch#bullseye, the launch post's) lands on the board and its mic
   button, clear of the sticky header. */
#bullseye { scroll-margin-top: 88px; }
.cp-pt2-demo { scroll-margin-top: 12px; }
/* Bullseye in the shared demo slot (the How to sing in tune guide): the deck alone, without the course page's paper. */
.s-ptslot { background: none; }
/* A guide's demo sits in the reading column: no section padding of its own, and a taller stage than
   16:9 so the learn demo's controls fit the narrower column. */
.s-gdemo .s-demosec { padding-inline: 0; }
.s-gdemo .s-demohead .s-title { font-size: clamp(1.6rem, 1.2rem + 1.4vw, 2.2rem); }
@media (min-width: 640px) { .s-gdemo .s-demo:not(.s-demo-fit) .s-demo-stage { aspect-ratio: 4 / 3; } }
.cp-pt2 a:not([class*="btn"]) { color: inherit; text-underline-offset: 3px; }
.cp-pt2 .s-crumb, .cp-pt2 .s-crumb a { color: var(--pt-muted); }
.cp-pt2 .s-cite a { padding: 0 2px; color: var(--pt-red-text); text-decoration: none; }
.cp-pt2 > section:not(.cp-pt2-band, .cp-pt2-close, .cp-pt2-hero, .cp-pt2-notes) { padding-block: clamp(56px, 9vw, 120px) 0; }

/* Type: sports-poster italics, tracked labels with the gold, and the measures in monospace. */
.cp-pt2-kick { display: inline-flex; gap: 8px; align-items: center; font-size: 12px; font-weight: 800; letter-spacing: .22em; text-transform: uppercase; color: var(--pt-label); }
.cp-pt2-kick::before { content: ""; flex: none; width: 10px; height: 10px; border-radius: 99px; background: var(--pt-gold); box-shadow: 0 0 0 2px var(--pt-red); }
.cp-pt2-h1, .cp-pt2-h2, .cp-pt2 h3 { font-weight: 900; font-style: italic; color: var(--pt-ink); text-wrap: balance; }
.cp-pt2-h1 { margin-top: 18px; font-size: clamp(60px, 8.6vw, 124px); line-height: .88; letter-spacing: -0.055em; }
.cp-pt2-h2 { margin-top: 12px; font-size: clamp(38px, 5.4vw, 66px); line-height: .98; letter-spacing: -0.05em; }
.cp-pt2-lede { margin-top: 22px; max-width: 56ch; font-size: clamp(17px, 2vw, 19px); line-height: 1.6; color: var(--pt-body); text-wrap: pretty; }
.cp-pt2-small, .cp-pt2-quiet { margin-top: 14px; max-width: 62ch; font-size: 15px; line-height: 1.6; color: var(--pt-muted); text-wrap: pretty; }
.cp-pt2-mono { font: 500 13px/1.45 var(--pt-mono); color: var(--pt-muted); }
:root[data-skin="game"] body.s-arcade :is(.cp-pt2-h1, .cp-pt2-h2, .cp-pt2 h3) { font-family: var(--a-display); font-style: normal; font-weight: 400; letter-spacing: .01em; text-transform: uppercase; font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade .cp-pt2-h1 { font-size: clamp(44px, 6.4vw, 84px); line-height: .98; }
:root[data-skin="game"] body.s-arcade .cp-pt2-h2 { font-size: clamp(28px, 4.4vw, 50px); max-width: 100%; overflow-wrap: anywhere; }
:root[data-skin="game"] body.s-arcade .cp-pt2 h3 { font-size: 20px; }
:root[data-skin="game"] body.s-arcade :is(.cp-pt2-kick, .cp-pt2-mono) { font-family: var(--a-hud); font-size: 10px; letter-spacing: .05em; font-size-adjust: var(--arc-ex, none); }

/* Buttons: the play control (a round icon in the target's red, a stop square while it sounds); labels never wrap. */
.cp-pt2-ctas, .cp-pt2-btns { display: flex; flex-wrap: wrap; align-items: center; gap: 12px; margin-top: 30px; }
.cp-pt2-btns { margin-top: 18px; }
.cp-pt2-play { display: inline-flex; align-items: center; gap: 10px; min-height: 48px; padding: 0 20px 0 6px; border-radius: 99px; border: 1.5px solid currentColor; background: transparent; color: inherit; font: 700 16px/1 Figtree, system-ui, sans-serif; white-space: nowrap; cursor: pointer; }
.cp-pt2-play:hover { background: color-mix(in srgb, currentColor 10%, transparent); }
.cp-pt2-play[aria-busy="true"] { cursor: progress; opacity: .8; }
.cp-pt2-play-icon { display: grid; place-items: center; flex: none; width: 34px; height: 34px; border-radius: 99px; background: #c42b2b; color: #fff; }
.cp-pt2-play-icon:empty::before { content: ""; margin-left: 3px; border-style: solid; border-width: 6px 0 6px 10px; border-color: transparent transparent transparent #fff; }
.cp-pt2-play[aria-pressed="true"] .cp-pt2-play-icon::before { content: ""; margin: 0; width: 11px; height: 11px; border: 0; background: #fff; }
.cp-pt2-play[aria-pressed="true"] .cp-pt2-play-icon svg { display: none; }
.cp-pt2-play-sm { min-height: 44px; padding-right: 16px; font-size: 14px; }
.cp-pt2-play-sm .cp-pt2-play-icon { width: 30px; height: 30px; }
.cp-pt2 :is(.cp-pt2-play, .cp-pt2-ear, summary, input, a):focus-visible { outline: 3px solid var(--pt-gold); outline-offset: 3px; }
:root[data-skin="game"] body.s-arcade .cp-pt2-play { border: 2px solid #3be7ff; color: #3be7ff; font: 400 10px/1.3 var(--a-hud); box-shadow: 0 0 16px -6px #3be7ff; }
:root[data-skin="game"][data-theme$="-light"] body.s-arcade .cp-pt2-play:not(.cp-pt2-demo *, .cp-pt2-band *) { border-color: #00708a; color: #00708a; }
:root[data-skin="game"] body.s-arcade .cp-pt2-play-icon { background: #ff5fd2; color: #1a0414; }
:root[data-skin="game"] body.s-arcade .cp-pt2-play-icon:empty::before { border-left-color: #1a0414; }
:root[data-skin="game"] body.s-arcade .cp-pt2-play[aria-pressed="true"] .cp-pt2-play-icon::before { background: #1a0414; }

/* The hero: the words beside Bullseye, then the cents ruler. Its full stop is a small bullseye. */
.cp-pt2-hero { padding-top: 20px; }
.cp-pt2-hero-grid { display: grid; grid-template-columns: minmax(0, 1fr); gap: 36px; align-items: center; margin-top: 18px; }
.cp-pt2-stop { display: inline-block; width: .13em; height: .13em; margin-left: .13em; border-radius: 99px; vertical-align: .04em; background: var(--pt-gold);
    box-shadow: 0 0 0 .035em var(--pt-red), 0 0 0 .07em var(--pt-blue), 0 0 0 .1em var(--pt-black), 0 0 0 .12em var(--pt-white); }
:root[data-skin="game"] body.s-arcade .cp-pt2-stop { margin-left: .3em; box-shadow: 0 0 0 .05em var(--pt-red), 0 0 0 .1em var(--pt-blue), 0 0 .3em .1em #ffd84a88; }
.cp-pt2-chips { display: flex; flex-wrap: wrap; gap: 6px 22px; margin-top: 24px; font: 500 13px/1.4 var(--pt-mono); color: var(--pt-muted); }
:root[data-skin="game"] body.s-arcade .cp-pt2-chips { font-family: var(--a-hud); font-size: 10px; font-size-adjust: var(--arc-ex, none); }
.cp-pt2-ruler { margin: clamp(44px, 6vw, 72px) 0 0; }
.cp-pt2-scale { position: relative; display: flex; justify-content: space-between; align-items: flex-end; height: 34px; border-bottom: 1px solid var(--pt-rule); }
.cp-pt2-tick { flex: none; width: 1px; height: 10px; background: var(--pt-rule); }
.cp-pt2-tick-quarter { height: 20px; }
.cp-pt2-tick-zero { width: 4px; height: 34px; background: var(--pt-gold); }
.cp-pt2-mark { position: absolute; bottom: 0; width: 12px; height: 12px; margin-left: -6px; border-radius: 99px; translate: 0 50%; box-shadow: 0 0 0 2px var(--pt-paper); }
.cp-pt2-ruler-n { display: flex; justify-content: space-between; gap: 8px; margin-top: 10px; font: 500 12px/1.3 var(--pt-mono); color: var(--pt-muted); }
.cp-pt2-ruler-n b { color: var(--pt-ink); font-weight: 700; }
:root[data-skin="game"] body.s-arcade .cp-pt2-ruler-n { font-family: var(--a-hud); font-size: 9px; font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade .cp-pt2-tick-zero { box-shadow: 0 0 10px #ffd84a; }
@media (max-width: 479px) { .cp-pt2-ruler-n span:nth-child(2), .cp-pt2-ruler-n span:nth-child(4) { display: none; } }

/* The board's rings, wherever they're drawn (the board, the close's badge). */
.cp-pt2-ring { stroke: rgba(0, 0, 0, .2); stroke-width: .8; }
.cp-pt2-w { fill: var(--pt-white); } .cp-pt2-k { fill: var(--pt-black); stroke: rgba(255, 255, 255, .35); } .cp-pt2-b { fill: var(--pt-blue); } .cp-pt2-r { fill: var(--pt-red); } .cp-pt2-g { fill: var(--pt-gold); }
:root[data-skin="game"] body.s-arcade .cp-pt2-ring { fill: transparent; stroke-width: 2.2; }
:root[data-skin="game"] body.s-arcade .cp-pt2-w { stroke: #fdf4ff; } :root[data-skin="game"] body.s-arcade .cp-pt2-k { stroke: #8f7cc4; }
:root[data-skin="game"] body.s-arcade .cp-pt2-b { stroke: #3be7ff; filter: drop-shadow(0 0 4px #3be7ff); }
:root[data-skin="game"] body.s-arcade .cp-pt2-r { stroke: #ff5fd2; filter: drop-shadow(0 0 4px #ff5fd2); }
:root[data-skin="game"] body.s-arcade .cp-pt2-g { fill: #ffd84a; stroke: #ffd84a; filter: drop-shadow(0 0 8px #ffd84a); }
/* A ring's colour as a dot, a chip or a mark: the gold with dark words, the others deep enough for white ones. */
:is(.cp-pt2-ringdot, .cp-pt2-dots > span, .cp-pt2-chip, .cp-pt2-mark).cp-pt2-g, .cp-pt2-chip-g { background: var(--pt-gold); color: #1c1613; }
:is(.cp-pt2-ringdot, .cp-pt2-dots > span).cp-pt2-r, .cp-pt2-chip-r { background: #c42b2b; color: #fff; }
:is(.cp-pt2-ringdot, .cp-pt2-dots > span).cp-pt2-b, .cp-pt2-chip-b { background: #1f6fb0; color: #fff; }
:is(.cp-pt2-ringdot, .cp-pt2-dots > span).cp-pt2-k, .cp-pt2-chip-k { background: #0e0b09; color: #fff; box-shadow: inset 0 0 0 1px rgba(255, 255, 255, .4); }
:root[data-skin="game"] body.s-arcade :is(.cp-pt2-chip-r, .cp-pt2-dots > .cp-pt2-r, .cp-pt2-ringdot.cp-pt2-r) { background: #ff5fd2; color: #1a0414; }
:root[data-skin="game"] body.s-arcade :is(.cp-pt2-chip-b, .cp-pt2-dots > .cp-pt2-b, .cp-pt2-ringdot.cp-pt2-b) { background: #3be7ff; color: #04161a; }

/* Bullseye, live: a dark stage in every look. Beside the hero's words it stacks the board over its words; in the
   guide's slot the board sits beside them from 900 px. */
.cp-pt2-demo { border-radius: 22px; overflow: hidden; background: var(--pt-stage); border: 1px solid var(--pt-stage-edge); color: var(--pt-stage-ink); }
.cp-pt2-demo-bar { display: flex; flex-wrap: wrap; gap: 4px 12px; align-items: center; justify-content: space-between; padding: 12px 20px; border-bottom: 1px solid var(--pt-stage-edge); font: 600 12px/1.4 var(--pt-mono); color: var(--pt-stage-muted); }
.cp-pt2-live { display: inline-flex; align-items: center; gap: 10px; letter-spacing: .16em; text-transform: uppercase; color: var(--pt-stage-ink); }
.cp-pt2-rec { width: 8px; height: 8px; border-radius: 99px; background: #e03a3a; }
.cp-pt2-demo-in { display: grid; grid-template-columns: minmax(0, 1fr); gap: 8px 40px; padding: 18px 20px 26px; align-items: center; }
.cp-pt2-board { display: flex; flex-direction: column; align-items: center; }
.cp-pt2-board svg { display: block; width: 100%; max-width: 330px; height: auto; margin-inline: auto; overflow: visible; }
.cp-pt2-board .cp-pt2-k { stroke: rgba(255, 255, 255, .3); }
.cp-pt2-board .cp-pt2-w { fill: #fbf8f2; }
.cp-pt2-cross { stroke: rgba(28, 22, 19, .35); stroke-width: 1; stroke-dasharray: 2 4; }
.cp-pt2-reach-n { font: 700 11px/1 var(--pt-mono); fill: #1c1613; text-anchor: end; }
.cp-pt2-side { font: 700 11px/1 var(--pt-mono); letter-spacing: .16em; text-transform: uppercase; fill: var(--pt-stage-muted); text-anchor: middle; }
.cp-pt2-dart circle { fill: #fff; stroke: #141010; stroke-width: 3; filter: drop-shadow(0 2px 3px rgba(0, 0, 0, .5)); }
.cp-pt2-dart-out circle { fill: rgba(255, 255, 255, .78); }
[data-pt-dart="live"] circle { fill: transparent; stroke: #fff; stroke-width: 3; filter: none; }
@media (prefers-reduced-motion: no-preference) {
    .cp-pt2-dart:not([data-pt-dart="live"]) { animation: cp-pt2-land .25s ease-out both; }
    .cp-pt2-chip { animation: cp-pt2-land .25s ease-out both; }
}
@keyframes cp-pt2-land { from { opacity: 0; } }
/* Each landed dart's cents, in its ring's colour, and the sample round said as one. */
.cp-pt2-chips-darts { display: flex; flex-wrap: wrap; justify-content: center; gap: 6px; min-height: 28px; margin-top: 12px; }
.cp-pt2-chips-darts:empty { display: none; }
.cp-pt2-chip { padding: 6px 10px; border-radius: 99px; font: 700 13px/1 var(--pt-mono); }
.cp-pt2-sampletag { order: 2; display: inline-flex; align-items: center; gap: 8px; margin-top: 10px; padding: 5px 12px; border-radius: 99px; border: 1px dashed currentColor; font: 600 11.5px/1.3 var(--pt-mono); letter-spacing: .08em; text-transform: uppercase; color: var(--pt-gold); }
:root[data-skin="game"][data-theme$="-light"] .cp-pt2-sampletag:not(.cp-pt2-demo *, .cp-pt2-band *) { color: #6e5500; }
.cp-pt2-demo-h { font-size: clamp(28px, 3.4vw, 36px); line-height: 1.02; letter-spacing: -0.04em; font-weight: 900; font-style: italic; color: var(--pt-stage-ink) !important; }
.cp-pt2-demo-lead { margin-top: 10px; max-width: 52ch; font-size: 15.5px; line-height: 1.6; color: var(--pt-stage-body); }
.cp-pt2-demo .cp-pt2-play { color: var(--pt-stage-ink); }
.cp-pt2-ear { min-height: 44px; padding: 0 4px; border: 0; background: none; color: var(--pt-stage-ink); font: 600 15px/1.2 Figtree, system-ui, sans-serif; text-decoration: underline; text-underline-offset: 4px; white-space: nowrap; cursor: pointer; }
.cp-pt2-say { min-height: 1.5em; margin-top: 12px; font: 600 14px/1.5 var(--pt-mono); color: var(--pt-gold); }
.cp-pt2-say:empty { display: none; }
.cp-pt2-private { display: flex; gap: 8px; align-items: flex-start; margin-top: 14px; max-width: 56ch; font-size: 12.5px; line-height: 1.55; color: var(--pt-stage-muted); }
.cp-pt2-private svg { flex: none; margin-top: 2px; }
.cp-pt2-pull { margin-top: 18px; padding-top: 16px; border-top: 1px solid var(--pt-stage-edge); }
.cp-pt2-pull h3 { font-size: 24px; color: var(--pt-stage-ink); outline: none; }
.cp-pt2-why { margin-bottom: 10px; font-size: 15px; font-weight: 600; color: #f2c94c; }
.cp-pt2-why:empty { display: none; }
.cp-pt2-slider { display: grid; gap: 6px; margin-top: 14px; font-size: 14px; font-weight: 600; color: var(--pt-stage-body); }
.cp-pt2-slider input { width: 100%; height: 34px; accent-color: #f2c94c; cursor: pointer; }
:root[data-skin="game"] body.s-arcade .cp-pt2-demo { box-shadow: 0 0 34px -14px #3be7ff; }
:root[data-skin="game"] body.s-arcade .cp-pt2-demo-bar { font-family: var(--a-hud); font-size: 9.5px; color: #ffd84a; font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade .cp-pt2-board .cp-pt2-ring { fill: #0b0820; }
:root[data-skin="game"] body.s-arcade .cp-pt2-board .cp-pt2-g { fill: #ffd84a; }
:root[data-skin="game"] body.s-arcade .cp-pt2-cross { stroke: rgba(237, 233, 255, .3); }
:root[data-skin="game"] body.s-arcade .cp-pt2-reach-n { fill: #ede9ff; paint-order: stroke; stroke: #0b0820; stroke-width: 3px; }
:root[data-skin="game"] body.s-arcade .cp-pt2-dart circle { filter: drop-shadow(0 0 5px #ffd84a); }
:root[data-skin="game"] body.s-arcade :is(.cp-pt2-chip, .cp-pt2-sampletag) { font-family: var(--a-hud); font-size: 9px; font-weight: 400; font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade .cp-pt2-ear { color: #ff9de6; }
:root[data-skin="game"] body.s-arcade .cp-pt2-say { font: 400 11px/1.6 var(--a-hud); color: #ffd84a; }
:root[data-skin="game"] body.s-arcade .cp-pt2-demo-h { font-family: var(--a-display); font-style: normal; font-weight: 400; text-transform: uppercase; letter-spacing: .01em; font-size-adjust: var(--arc-ex, none); }
/* Pull it in, by ear: the target hidden (blurred away) while you pull, and the win. Serious: a calm
   line in gold. Game: an arcade BULLSEYE! that pops in (still, with reduced motion). */
.cp-pt2-board svg { transition: filter .4s, opacity .4s; }
.cp-pt2-demo[data-pulling] .cp-pt2-board svg { filter: blur(18px); opacity: .3; }
.cp-pt2-win { margin-top: 16px; padding: 16px 18px; border-radius: 16px; border: 1px solid var(--pt-gold); background: color-mix(in srgb, var(--pt-gold) 10%, transparent); }
.cp-pt2-win-h { font-size: 24px; font-weight: 900; font-style: italic; color: var(--pt-stage-ink); }
.cp-pt2-win-say { margin-top: 4px; font-size: 16px; color: var(--pt-stage-body); }
.cp-pt2-win .cp-pt2-btns { margin-top: 12px; }
:root[data-skin="game"] body.s-arcade .cp-pt2-win { border: 2px solid #ffd84a; background: #ffd84a14; box-shadow: 0 0 28px -8px #ffd84a; }
:root[data-skin="game"] body.s-arcade .cp-pt2-win-h { font: 400 clamp(26px, 6vw, 40px)/1.1 var(--a-display); font-style: normal; text-transform: uppercase; color: #ffd84a; text-shadow: 0 0 14px #ffd84a99; }
@media (prefers-reduced-motion: no-preference) {
    :root[data-skin="game"] body.s-arcade .cp-pt2-win:not([hidden]) .cp-pt2-win-h { animation: cp-pt2-pop .5s cubic-bezier(.2, 1.6, .4, 1) both; }
}
@media (prefers-reduced-motion: reduce) { .cp-pt2-board svg { transition: none; } }
@keyframes cp-pt2-pop { from { transform: scale(.4); opacity: 0; } to { transform: scale(1); opacity: 1; } }
/* The mic picker (js/public/mic-pick.js): quiet, under the mic button, once there's a choice. */
.cp-pt2-mic-pick { display: flex; align-items: center; gap: 8px; margin-top: 12px; font-size: 14px; font-weight: 600; color: var(--pt-stage-muted); }
.cp-pt2-mic-pick select { min-width: 0; max-width: 100%; min-height: 40px; padding: 0 30px 0 12px; border-radius: 10px; border: 1px solid var(--pt-stage-edge); background: transparent; color: var(--pt-stage-ink); font: 500 14px/1.2 Figtree, system-ui, sans-serif; text-overflow: ellipsis; }
.cp-pt2-mic-pick select option { color: #1c1613; background: #fff; }
.cp-pt2 .cp-pt2-mic-pick select:focus-visible { outline: 3px solid var(--pt-gold); outline-offset: 2px; }

/* Aim: the outcomes as a scorecard, an end a column, each with its ring's dot, its number and its unit. */
.cp-pt2-headrow { display: flex; flex-wrap: wrap; align-items: flex-end; justify-content: space-between; gap: 12px 32px; }
.cp-pt2-score { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); margin-top: 36px; border: 2px solid var(--pt-rule); border-radius: 4px; background: var(--pt-card); overflow: hidden; }
.cp-pt2-score li { display: flex; flex-direction: column; gap: 14px; margin: 0 -1px -1px 0; padding: 18px 16px 20px; border-right: 1px solid var(--pt-rule); border-bottom: 1px solid var(--pt-rule); }
.cp-pt2-score-top { display: flex; align-items: center; justify-content: space-between; gap: 12px; font: 700 12px/1 var(--pt-mono); letter-spacing: .1em; text-transform: uppercase; }
.cp-pt2-ringdot { flex: none; width: 22px; height: 22px; border-radius: 99px; box-shadow: 0 0 0 3px var(--pt-card), 0 0 0 4px var(--pt-rule) !important; }
.cp-pt2-num { font-size: 40px; line-height: .85; font-weight: 900; font-style: italic; letter-spacing: -0.05em; color: var(--pt-num); }
.cp-pt2-score .cp-pt2-num { font-size: 56px; }
.cp-pt2-score-aim { font-size: 16px; line-height: 1.5; text-wrap: pretty; }
.cp-pt2-score .cp-pt2-mono { margin-top: auto; font-size: 12px; }
:root[data-skin="game"] body.s-arcade .cp-pt2-num { font: 400 24px/1 var(--a-hud); text-shadow: 0 0 14px currentColor; }
:root[data-skin="game"] body.s-arcade .cp-pt2-score { border-color: #ffd84a88; border-radius: 0; box-shadow: 0 0 22px -12px #ffd84a; }
:root[data-skin="game"] body.s-arcade .cp-pt2-score li { border-color: #ffd84a55; }
:root[data-skin="game"] body.s-arcade .cp-pt2-score-top { font-family: var(--a-hud); font-size: 9px; font-weight: 400; font-size-adjust: var(--arc-ex, none); }

/* The anchor point: the scale do to high do at its real heights, a row a semitone, each step in its own column (its
   tap area the column's width and 44 px tall, so no two touch), the half steps one row apart. */
.cp-pt2-pair { display: grid; grid-template-columns: minmax(0, 1fr); gap: 32px; align-items: center; }
.cp-pt2-card { margin: 0; border-radius: 20px; background: var(--pt-card); border: 1px solid var(--pt-line); }
.cp-pt2-tap { display: inline-flex; align-items: center; gap: 8px; margin-top: 24px; font: 600 13px/1.4 var(--pt-mono); color: var(--pt-label); }
.cp-pt2-ladder { padding: 24px 24px 18px; }
.cp-pt2-lad { display: grid; grid-template-columns: 26px repeat(8, minmax(0, 1fr)); grid-template-rows: repeat(13, 28px); align-items: center; }
.cp-pt2-lad-n { grid-column: 1; font: 500 11px/1 var(--pt-mono); color: var(--pt-muted); }
.cp-pt2-rung { grid-column: 2 / -1; height: 1px; background: var(--pt-line); }
.cp-pt2-rung-home { height: 2px; background: var(--pt-gold); }
.cp-pt2-sol { position: relative; z-index: 1; display: grid; place-items: center; justify-self: stretch; height: 44px; margin-block: -8px; padding: 0; border: 0; background: none; cursor: pointer; }
/* Each step's tap area is at least 44 px wide as well as tall, wider than its column where the column is narrower (a
   phone): centred, except the half steps' pairs (mi and fa, ti and high do), which a semitone apart sit one row apart,
   so mi and ti reach left and fa and high do reach right, and no two areas ever meet. */
.cp-pt2-sol::before { content: ""; position: absolute; inset-block: 0; left: 50%; width: max(100%, 44px); translate: -50% 0; }
.cp-pt2-sol:is([data-pt-step="4"], [data-pt-step="11"])::before { left: auto; right: 0; translate: none; }
.cp-pt2-sol:is([data-pt-step="5"], [data-pt-step="12"])::before { left: 0; translate: none; }
.cp-pt2-sol > span { display: grid; place-items: center; width: min(100%, 46px); height: 26px; border-radius: 99px; background: var(--pt-sol); border: 2px solid var(--pt-sol); color: var(--pt-sol-ink); font: 700 13px/1 Figtree, system-ui, sans-serif; transition: background .15s, border-color .15s; }
.cp-pt2-sol-home > span { background: var(--pt-gold); border-color: var(--pt-red); color: #1c1613; }
.cp-pt2-sol:is([aria-pressed="true"], [data-lit]) > span { background: var(--pt-gold); border-color: var(--pt-gold); color: #1c1613; box-shadow: 0 0 0 4px color-mix(in srgb, var(--pt-gold) 35%, transparent); }
.cp-pt2-sol:hover > span { border-color: var(--pt-gold); }
.cp-pt2-sol:focus-visible { outline: none; }
.cp-pt2-sol:focus-visible > span { outline: 3px solid var(--pt-gold); outline-offset: 2px; }
.cp-pt2-ladder figcaption { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 4px 16px; margin-top: 14px; font: 500 12px/1.4 var(--pt-mono); color: var(--pt-muted); }
:root[data-skin="game"] body.s-arcade .cp-pt2-sol > span { border-radius: 0; border-color: var(--pt-sol-ink); box-shadow: 0 0 10px -3px var(--pt-sol-ink); font: 400 9px/1 var(--a-hud); font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade .cp-pt2-sol-home > span, :root[data-skin="game"] body.s-arcade .cp-pt2-sol:is([aria-pressed="true"], [data-lit]) > span { border-color: #ffd84a; background: #ffd84a; color: #1a1400; box-shadow: 0 0 14px #ffd84a; }
:root[data-skin="game"] body.s-arcade .cp-pt2-ladder figcaption { font-family: var(--a-hud); font-size: 9px; font-size-adjust: var(--arc-ex, none); }

/* On target and the readout: the dark bands. The beats card: one second of the two tones, the gap on a slider. */
.cp-pt2-band { margin-top: clamp(56px, 9vw, 120px); background: var(--pt-band); color: var(--pt-band-ink); }
.cp-pt2-band > .s-sec { padding-block: clamp(56px, 9vw, 112px); }
.cp-pt2-band .cp-pt2-kick { color: var(--pt-band-label); }
.cp-pt2-band :is(.cp-pt2-h2, h3) { color: var(--pt-band-ink); }
.cp-pt2-band .cp-pt2-lede { color: var(--pt-band-body); }
.cp-pt2-band .cp-pt2-small { color: var(--pt-band-muted); }
.cp-pt2-band .s-cite a { color: var(--pt-band-label); }
.cp-pt2-band .cp-pt2-play { color: var(--pt-band-ink); }
.cp-pt2-three { display: grid; grid-template-columns: auto minmax(0, 1fr); gap: 18px; align-items: start; margin-top: 30px; padding-top: 24px; border-top: 1px solid var(--pt-band-edge); font-size: 15.5px; line-height: 1.6; color: var(--pt-band-body); }
.cp-pt2-three b { font-size: 72px; line-height: .8; font-weight: 900; font-style: italic; letter-spacing: -0.05em; color: var(--pt-gold); }
:root[data-skin="game"] body.s-arcade .cp-pt2-three b { font: 400 56px/1 var(--a-display); text-shadow: 0 0 18px #ffd84a; }
.cp-pt2-beatcard { padding: 22px; border-radius: 18px; background: var(--pt-band-card); border: 1px solid var(--pt-band-edge); transition: border-color .2s; }
.cp-pt2-beatcard[data-still] { border-color: var(--pt-gold); }
.cp-pt2-beat-top { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 4px 12px; font: 500 13px/1.4 var(--pt-mono); color: var(--pt-band-muted); }
.cp-pt2-beat-top b { font-weight: 700; color: var(--pt-band-ink); }
[data-still] .cp-pt2-beat-top b { color: var(--pt-gold); }
.cp-pt2-beatcard svg { display: block; width: 100%; height: 110px; margin-top: 14px; }
.cp-pt2-beatcard path { fill: none; stroke: var(--pt-band-body); stroke-width: 1.6; vector-effect: non-scaling-stroke; }
[data-still] path { stroke: var(--pt-gold); stroke-width: 2.2; }
.cp-pt2-gap { display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: center; gap: 14px; margin-top: 14px; font: 500 13px/1.3 var(--pt-mono); color: var(--pt-band-muted); }
.cp-pt2-gap input { width: 100%; height: 44px; accent-color: var(--pt-gold); cursor: pointer; }
.cp-pt2-gap output { min-width: 5ch; text-align: right; font-variant-numeric: tabular-nums; color: var(--pt-band-ink); }
.cp-pt2-hint { font-size: 14px; line-height: 1.5; color: var(--pt-band-muted); }
:root[data-skin="game"] body.s-arcade .cp-pt2-band { box-shadow: inset 0 1px 0 #3be7ff, inset 0 -1px 0 #ff5fd2; }
:root[data-skin="game"] body.s-arcade .cp-pt2-beatcard { border-radius: 0; box-shadow: 0 0 24px -12px #3be7ff; }
:root[data-skin="game"] body.s-arcade .cp-pt2-beatcard path { filter: drop-shadow(0 0 4px currentColor); stroke: #3be7ff; }
:root[data-skin="game"] body.s-arcade .cp-pt2-beatcard[data-still] path { stroke: #ffd84a; }
:root[data-skin="game"] body.s-arcade :is(.cp-pt2-beat-top, .cp-pt2-gap) { font-family: var(--a-hud); font-size: 9.5px; font-size-adjust: var(--arc-ex, none); }

/* Four ends: the units as score cards, each under a band in its ring's colour, every lesson linked to its page. */
.cp-pt2-ends { display: grid; grid-template-columns: minmax(0, 1fr); gap: 14px; margin-top: 36px; }
.cp-pt2-end { position: relative; display: flex; flex-direction: column; overflow: hidden; padding: 30px 22px 22px; border-radius: 16px; background: var(--pt-card); border: 1px solid var(--pt-line); }
.cp-pt2-end::before { content: ""; position: absolute; inset: 0 0 auto; height: 10px; background: var(--ring); }
.cp-pt2-end-g { --ring: var(--pt-gold); } .cp-pt2-end-r { --ring: var(--pt-red); } .cp-pt2-end-b { --ring: var(--pt-blue); } .cp-pt2-end-k { --ring: var(--pt-black); }
:root:not([data-theme$="-light"]) .cp-pt2-end-k::before { box-shadow: inset 0 -1px 0 var(--pt-line); }
.cp-pt2-end-top { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
.cp-pt2-end-n { font: 700 12px/1.3 var(--pt-mono); letter-spacing: .1em; text-transform: uppercase; color: var(--pt-label); }
.cp-pt2-end-count { font: 500 12px/1.3 var(--pt-mono); color: var(--pt-muted); }
.cp-pt2-end h3 { margin-top: 14px; font-size: 26px; line-height: 1.1; letter-spacing: -0.035em; }
.cp-pt2-end .cp-pt2-small { margin-top: 10px; font-size: 14px; }
.cp-pt2-lessons { display: grid; margin-top: 16px; padding-top: 10px; border-top: 1px solid var(--pt-line); font-size: 15px; line-height: 1.35; }
.cp-pt2-lessons li { display: flex; gap: 12px; align-items: center; min-height: 36px; }
.cp-pt2-lessons li > span:last-child { display: flex; flex-wrap: wrap; align-items: center; gap: 4px 8px; }
.cp-pt2-lessons a:not(.cp-pt2-free) { display: inline-flex; align-items: center; min-height: 36px; text-decoration: underline; text-decoration-color: color-mix(in srgb, currentColor 30%, transparent); }
.cp-pt2-lessons a:not(.cp-pt2-free):hover { text-decoration-color: currentColor; }
.cp-pt2-ln { flex: none; width: 28px; font: 500 12px/1 var(--pt-mono); color: var(--pt-muted); }
.cp-pt2-ln::before { content: "→"; }
.cp-pt2-free { padding: 4px 9px; border-radius: 99px; background: var(--pt-gold); color: #1c1613 !important; font: 700 10.5px/1.2 var(--pt-mono); letter-spacing: .08em; text-transform: uppercase; text-decoration: none !important; white-space: nowrap; }
:root[data-skin="game"] body.s-arcade .cp-pt2-end { border-radius: 0; border: 2px solid #ffd84a55; box-shadow: 0 0 22px -12px #ffd84a; }
:root[data-skin="game"] body.s-arcade .cp-pt2-end-n { font: 400 10px/1.4 var(--a-hud); letter-spacing: .04em; color: #ffd84a; font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"][data-theme$="-light"] body.s-arcade .cp-pt2-end-n { color: #6e5500; }
:root[data-skin="game"] body.s-arcade .cp-pt2-ln::before { content: none; }
:root[data-skin="game"] body.s-arcade .cp-pt2-free { background: #a3e635; color: #0b0a18 !important; font-family: var(--a-hud); font-size: 8px; font-weight: 400; letter-spacing: .02em; font-size-adjust: var(--arc-ex, none); }

/* A clean landing: a scoop and a clean start as pitch over time, each playable; then four steps on a line. */
.cp-pt2-traces { display: grid; grid-template-columns: minmax(0, 1fr); gap: 12px; margin: 0; }
.cp-pt2-trace { display: grid; gap: 10px; justify-items: start; padding: 14px 14px 12px; border-radius: 14px; background: var(--pt-card); border: 1px solid var(--pt-line); }
.cp-pt2-trace-top { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 4px 12px; width: 100%; font: 500 12px/1.3 var(--pt-mono); }
.cp-pt2-trace-top b { font-weight: 700; color: var(--pt-ink); }
.cp-pt2-trace-scoop .cp-pt2-trace-top span { color: var(--pt-red-text); }
.cp-pt2-trace-clean .cp-pt2-trace-top span { color: var(--pt-label); }
.cp-pt2-trace svg { display: block; width: 100%; height: auto; }
.cp-pt2-trace-band { fill: var(--pt-gold); opacity: .35; }
.cp-pt2-trace-note { stroke: #c9a43a; stroke-dasharray: 3 3; }
.cp-pt2-trace-line { fill: none; stroke-width: 3; stroke-linecap: round; stroke-linejoin: round; }
.cp-pt2-trace-scoop .cp-pt2-trace-line { stroke: var(--pt-red); }
.cp-pt2-trace-clean .cp-pt2-trace-line { stroke: var(--pt-num); }
.cp-pt2-traces figcaption { grid-column: 1 / -1; font-size: 12px; }
:root[data-skin="game"] body.s-arcade .cp-pt2-trace { border-radius: 0; border: 2px solid #3be7ff55; }
:root[data-skin="game"] body.s-arcade .cp-pt2-trace-line { filter: drop-shadow(0 0 4px currentColor); }
:root[data-skin="game"] body.s-arcade .cp-pt2-trace-top { font-family: var(--a-hud); font-size: 9px; font-size-adjust: var(--arc-ex, none); }
.cp-pt2-steps { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); column-gap: 20px; margin-top: 48px; border-top: 1px solid var(--pt-line); }
.cp-pt2-steps li { position: relative; display: grid; grid-template-columns: minmax(0, 1fr); align-content: start; padding: 24px 0 16px; }
.cp-pt2-steps li::before { content: ""; position: absolute; top: -7px; left: 0; width: 13px; height: 13px; border-radius: 99px; background: var(--pt-num); }
.cp-pt2-steps .cp-pt2-step-first::before { background: var(--pt-red); }
.cp-pt2-steps .cp-pt2-num { font-size: 44px; }
.cp-pt2-start { display: block; margin-top: 10px; font: 700 11px/1.3 var(--pt-mono); letter-spacing: .12em; text-transform: uppercase; color: var(--pt-red-text); }
.cp-pt2-steps p { margin-top: 10px; font-size: 16px; line-height: 1.5; text-wrap: pretty; }
.cp-pt2-first > .cp-pt2-small { margin-top: 32px; }
:root[data-skin="game"] body.s-arcade .cp-pt2-start { font: 400 9px/1.6 var(--a-hud); letter-spacing: .04em; }

/* The readout: a sample round's meters (said so), each bar the board's rings across 50 flat to 50 sharp. */
.cp-pt2-readout { padding: 6px 22px 4px; border-radius: 18px; background: var(--pt-band-card); border: 1px solid var(--pt-band-edge); }
.cp-pt2-readout .cp-pt2-sampletag { margin-top: 14px; color: var(--pt-band-label); }
.cp-pt2-meter { padding: 16px 0; border-bottom: 1px solid var(--pt-band-edge); }
.cp-pt2-meter-top { display: flex; align-items: baseline; justify-content: space-between; gap: 12px; }
.cp-pt2-meter-top b { font-size: 16px; font-weight: 700; color: var(--pt-band-ink); }
.cp-pt2-meter-top span { font: 700 14px/1.2 var(--pt-mono); color: var(--pt-band-label); }
.cp-pt2-meter-bar { position: relative; display: block; height: 8px; margin-top: 12px; border-radius: 99px;
    background: linear-gradient(90deg, var(--pt-blue) 0 25%, var(--pt-red) 25% 40%, var(--pt-gold) 40% 60%, var(--pt-red) 60% 75%, var(--pt-blue) 75%); }
.cp-pt2-meter-bar > span { position: absolute; left: var(--at); top: -5px; width: 4px; height: 18px; margin-left: -2px; border-radius: 2px; background: var(--pt-band-ink); box-shadow: 0 0 0 1.5px var(--pt-band-card); }
.cp-pt2-meter-note { margin-top: 8px; font-size: 13px; line-height: 1.45; color: var(--pt-band-muted); }
.cp-pt2-readout-sum { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 10px 16px; padding: 16px 0 14px; font: 600 14px/1.4 var(--pt-mono); color: var(--pt-band-ink); }
.cp-pt2-dots { display: flex; gap: 6px; }
.cp-pt2-dots > span { width: 14px; height: 14px; border-radius: 99px; }
:root[data-skin="game"] body.s-arcade .cp-pt2-readout { border-radius: 0; box-shadow: 0 0 24px -12px #ffd84a; }
:root[data-skin="game"] body.s-arcade :is(.cp-pt2-meter-top span, .cp-pt2-readout-sum) { font-family: var(--a-hud); font-size: 9.5px; font-weight: 400; font-size-adjust: var(--arc-ex, none); }

/* From the range: the facts, each under its label and an arrow. */
.cp-pt2-facts { display: grid; grid-template-columns: minmax(0, 1fr); gap: 36px; margin-top: 36px; }
.cp-pt2-fact-head { display: flex; align-items: center; gap: 12px; font: 700 12px/1.2 var(--pt-mono); letter-spacing: .1em; text-transform: uppercase; color: var(--pt-red-text); }
.cp-pt2-fact-head span { flex: none; }
.cp-pt2-fact-arrow { flex: 1; min-width: 40px; height: 12px; }
.cp-pt2-line { stroke: var(--pt-num); stroke-width: 2; vector-effect: non-scaling-stroke; }
.cp-pt2-tip { fill: var(--pt-num); }
.cp-pt2-fact { margin-top: 18px; font-size: 19px; line-height: 1.5; text-wrap: pretty; }
.cp-pt2-src { margin-top: 14px; font: 600 12px/1.4 var(--pt-mono); letter-spacing: .08em; text-transform: uppercase; color: var(--pt-muted); }
:root[data-skin="game"] body.s-arcade :is(.cp-pt2-fact-head, .cp-pt2-src) { font-family: var(--a-hud); font-size: 9px; font-weight: 400; font-size-adjust: var(--arc-ex, none); }

/* Your kit: who, what you need, and the navy card of singing safely and the songs. */
.cp-pt2-kit-grid { display: grid; grid-template-columns: minmax(0, 1fr); gap: 32px; margin-top: 36px; align-items: start; }
.cp-pt2-kit-h { padding-bottom: 12px; border-bottom: 2px solid var(--pt-rule); font: 700 12px/1.3 var(--pt-mono) !important; letter-spacing: .12em; text-transform: uppercase; color: var(--pt-label) !important; }
.cp-pt2-ticks li { display: flex; gap: 12px; padding-block: 14px; border-bottom: 1px solid var(--pt-line); font-size: 16px; line-height: 1.5; }
.cp-pt2-tickdot { flex: none; width: 10px; height: 10px; margin: 7px 2px 0; border-radius: 99px; background: var(--pt-gold); box-shadow: 0 0 0 2px var(--pt-red); }
.cp-pt2-rules { padding: 24px; border-radius: 20px; background: #1e2d5e; color: #eef0f7; }
.cp-pt2-rules h3 { font: 700 12px/1.3 var(--pt-mono) !important; letter-spacing: .12em; text-transform: uppercase; color: #f2c94c !important; }
.cp-pt2-rules ul { display: grid; gap: 10px; margin-top: 12px; font-size: 15px; line-height: 1.5; }
.cp-pt2-rules ul + h3 { margin-top: 24px; }
.cp-pt2-rules b { color: #fff; }
.cp-pt2-rules span { color: #c3cae2; }
:root[data-skin="game"] body.s-arcade .cp-pt2-rules { background: var(--pt-card); color: var(--pt-ink); box-shadow: inset 0 0 0 2px #ffd84a; border-radius: 0; }
:root[data-skin="game"] body.s-arcade .cp-pt2-rules :is(b, span) { color: inherit; }
:root[data-skin="game"] body.s-arcade .cp-pt2-rules h3 { font: 400 10px/1.5 var(--a-hud) !important; letter-spacing: .04em; color: var(--pt-num) !important; }
:root[data-skin="game"] body.s-arcade .cp-pt2-kit-h { font: 400 10px/1.5 var(--a-hud) !important; letter-spacing: .04em; }

/* Questions, the close and the sources. */
.cp-pt2-fine { display: grid; grid-template-columns: minmax(0, 1fr); gap: 12px; }
.cp-pt2 .cp-faq summary, .cp-pt2 .cp-faq p { color: var(--pt-ink); }
.cp-pt2 .cp-faq p { color: var(--pt-body); }
.cp-pt2-close { margin-top: clamp(56px, 9vw, 120px); background: radial-gradient(ellipse at 50% 100%, color-mix(in srgb, var(--pt-gold) 30%, var(--pt-paper)), var(--pt-paper) 65%); }
.cp-pt2-close-in { display: grid; justify-items: center; text-align: center; padding-block: 64px 72px; }
.cp-pt2-badge { width: 88px; height: 88px; }
.cp-pt2-close-h { margin-top: 22px; font-size: clamp(56px, 8vw, 104px); line-height: .9; }
.cp-pt2-close .cp-pt2-lede { margin-inline: auto; text-wrap: balance; }
.cp-pt2-close :is(.cp-pt2-ctas, .cp-related) { justify-content: center; }
.cp-pt2-related-h { margin-top: 48px; font-style: normal !important; }
.cp-pt2 .cp-related a { background: var(--pt-card); border: 1px solid var(--pt-line); color: var(--pt-ink); }
@media (prefers-reduced-motion: no-preference) { .cp-pt2-badge { animation: cp-pt2-pulse 3s ease-in-out infinite; } }
@keyframes cp-pt2-pulse { 50% { transform: scale(1.05); } }
:root[data-skin="game"] body.s-arcade .cp-pt2-close { background: radial-gradient(70% 90% at 50% 100%, color-mix(in srgb, #ffd84a 16%, var(--pt-paper)), var(--pt-paper) 70%); }
.cp-pt2-notes { padding-block: 8px 56px; }
.cp-pt2-notes summary { display: flex; align-items: center; min-height: 44px; list-style: none; cursor: pointer; }
.cp-pt2-notes summary::-webkit-details-marker { display: none; }
.cp-pt2-notes summary h2::after { content: "▸"; margin-left: 4px; } .cp-pt2-notes details[open] summary h2::after { content: ""; }
.cp-pt2-notes ol { margin-top: 12px; padding-left: 22px; list-style: decimal; columns: 2 320px; column-gap: 44px; font-size: 13.5px; line-height: 1.5; color: var(--pt-muted); }
.cp-pt2-notes li { margin-bottom: 6px; break-inside: avoid; scroll-margin-top: 90px; }

/* A phone: the targets 44 px, the ladder's columns as wide as they go, a little tighter all round. */
@media (max-width: 639px) {
    .cp-pt2-ctas > a { flex: 1 1 100%; justify-content: center; }
