    .cp-pt2-ladder { padding: 18px 12px 14px; }
    .cp-pt2-lad { grid-template-columns: 20px repeat(8, minmax(0, 1fr)); grid-template-rows: repeat(13, 26px); }
    .cp-pt2-lessons li, .cp-pt2-lessons a:not(.cp-pt2-free) { min-height: 44px; }
    .cp-pt2-three b { font-size: 60px; }
    .cp-pt2-beatcard { padding: 18px 16px; }
    .cp-pt2-beatcard svg { height: 84px; }
