}
@media (max-width: 379px) { :root[data-skin="game"] body.s-arcade .cp-pt2-play { gap: 8px; padding-right: 12px; font-size: 8px; } }
@media (min-width: 560px) { .cp-pt2-traces { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (min-width: 640px) {
    .cp-pt2-ends { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (min-width: 900px) {
    .cp-pt2-hero { padding-top: 40px; }
    .cp-pt2-demo-in { grid-template-columns: minmax(0, 5fr) minmax(0, 6fr); padding: 28px 40px 36px; }
    .cp-pt2-pair { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 56px; }
    .cp-pt2-first-top { align-items: end; }
    .cp-pt2-ladder { padding: 28px 28px 22px; }
    .cp-pt2-ends { gap: 16px; margin-top: 44px; }
    .cp-pt2-steps { grid-template-columns: repeat(4, minmax(0, 1fr)); margin-top: 60px; }
    .cp-pt2-steps li { padding: 30px 24px 26px 0; }
    .cp-pt2-score { grid-template-columns: repeat(4, minmax(0, 1fr)); }
    .cp-pt2-score li { gap: 16px; padding: 22px 22px 24px; }
    .cp-pt2-facts { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 40px; margin-top: 44px; }
    .cp-pt2-fact { font-size: 20px; }
    .cp-pt2-kit-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 32px; margin-top: 44px; }
