}
@media (min-width: 1200px) { .cp-pt2-ends { grid-template-columns: repeat(4, minmax(0, 1fr)); } }

/* Ear training (site/courses/ear-training): Hillel's design (2026-11-18, ~/Code/course-designs/ear-training), the page
   climbing a scale, each section a step from 1 do to 8 do, "Home again". The theme's tokens and the system's serif
   (no new font) in calm light and dark; each leap its own colour (--et-three, --et-four, --et-five) on the ladder, the
   cards and the board. Bright or dark is split down the middle, warm and night, in every theme. The shared Name that
   leap (site/courses/_ear-leap) keeps its own block below; every lesson is listed and linked in the course's stairs,
   so course.blade.php's list of lesson pages after this page is left out here. Game mode restyles the same pieces. */
.cp-ear { --et-serif: ui-serif, "Iowan Old Style", "Palatino Linotype", Palatino, Georgia, serif; --et-accent: var(--s-hl-em); --et-three: #b85618; --et-four: var(--color-cream); --et-five: #6d4fd0;
    --et-warm: #f6e3c8; --et-warm-ink: #2b1f14; --et-warm-muted: #5c4630; --et-warm-third: #b85618; --et-night: #1b1620; --et-night-ink: #f3ede6; --et-night-muted: #c9bfd3; --et-night-third: #b49cff; }
:root:not([data-theme$="-light"]) .cp-ear { --et-three: #f0a35e; --et-five: #b49cff; --et-warm: #3a2919; --et-warm-ink: #f6e3c8; --et-warm-muted: #dcc4a4; --et-warm-third: #f0a35e; --et-night: #120e16; }
:root[data-skin="game"] .cp-ear { --et-serif: inherit; --et-accent: var(--arc-yellow); --et-three: var(--arc-yellow); --et-four: var(--arc-cyan); --et-five: var(--arc-pink);
    --et-warm: color-mix(in srgb, var(--arc-yellow) 12%, var(--arc-bg)); --et-warm-ink: var(--color-cream); --et-warm-muted: var(--color-muted); --et-warm-third: var(--arc-yellow); --et-night: var(--arc-well); --et-night-ink: var(--color-cream); --et-night-muted: var(--color-muted); --et-night-third: var(--arc-pink); }
:root[data-skin="game"][data-theme$="-light"] .cp-ear { --et-three: #8a5a00; --et-four: #006b85; --et-five: #b0166e; --et-warm-third: #8a5a00; --et-night: #1b1620; --et-night-ink: #f3ede6; --et-night-muted: #c9bfd3; --et-night-third: #ff8ad0; }
.cp-et-three { --c: var(--et-three); } .cp-et-four { --c: var(--et-four); } .cp-et-five { --c: var(--et-five); }
.cp-ear ~ [data-lesson-pages] { display: none; }

/* Type: the serif for headings and sung words, small tracked labels, each section's step. */
.cp-et-h2, .cp-et-hero h1, .cp-et-colour-h, .cp-et-dark-big, .cp-et-join, .cp-et-glyph, .cp-et-unit-deg, .cp-et-card h3, .cp-et-unit-card h3, .cp-et-try-n, .cp-et-found { font-family: var(--et-serif); font-weight: 400; }
.cp-et-h2 { margin-top: 20px; font-size: clamp(38px, 5vw, 64px); line-height: 1.02; letter-spacing: -0.03em; text-wrap: balance; }
.cp-et-h2-s { margin-top: 8px; font-size: clamp(34px, 4vw, 48px); }
.cp-et-kick { font-size: 12px; font-weight: 700; letter-spacing: .16em; text-transform: uppercase; color: var(--et-accent); }
.cp-et-p { margin-top: 18px; font-size: 17px; line-height: 1.6; color: var(--color-muted); max-width: 56ch; text-wrap: pretty; }
.cp-et-fine { margin-top: 20px; font-size: 14.5px; line-height: 1.6; color: var(--color-muted); max-width: 70ch; }
.cp-et-sec { padding-top: clamp(72px, 9vw, 120px); }
.cp-et-step { display: flex; align-items: center; gap: 12px; font-size: 12px; font-weight: 650; letter-spacing: .16em; text-transform: uppercase; color: var(--color-muted); }
.cp-et-step-n { flex: none; display: grid; place-items: center; width: 30px; height: 30px; border-radius: 99px; background: var(--color-cream); color: var(--color-ink); font-size: 13px; letter-spacing: 0; }
.cp-et-step em { font-family: var(--et-serif); font-size: 18px; font-weight: 400; letter-spacing: 0; text-transform: none; color: var(--et-accent); }
.cp-et-btns { display: flex; flex-wrap: wrap; gap: 12px; margin-top: 32px; }
.cp-et-btns > a { white-space: nowrap; }
@media (max-width: 639px) {
    .cp-et-btns { flex-direction: column; align-items: stretch; }
    .cp-et-btns > a { justify-content: center; width: 100%; }
}

/* The hero: the words at left, the leap ladder at right. */
.cp-et-hero { padding-top: 20px; }
.cp-et-top { display: grid; grid-template-columns: minmax(0, 1fr); gap: 40px 56px; margin-top: 28px; }
.cp-et-eyebrow { display: flex; flex-wrap: wrap; align-items: center; gap: 10px 14px; font-size: 12px; font-weight: 700; letter-spacing: .16em; text-transform: uppercase; color: var(--et-accent); }
.cp-et-open { padding: 6px 12px; border-radius: 99px; background: var(--et-accent); color: var(--color-ink); white-space: nowrap; }
.cp-et-size { white-space: nowrap; }
.cp-et-hero h1 { margin-top: 24px; font-size: clamp(60px, 8.4vw, 112px); line-height: .94; letter-spacing: -0.035em; }
.cp-et-hero h1 em, .cp-et-join em { font-style: italic; color: var(--et-accent); }
.cp-et-lead { margin-top: 26px; font-size: clamp(18px, 1.6vw, 20px); line-height: 1.6; color: var(--color-muted); max-width: 36ch; text-wrap: pretty; }
.cp-et-facts { display: flex; flex-wrap: wrap; gap: 8px 0; margin-top: 22px; font-size: 14px; font-weight: 550; color: var(--color-muted); }
.cp-et-facts li + li::before { content: "/"; margin-inline: 14px; color: var(--color-line); }
@media (max-width: 639px) {
    .cp-et-facts { display: grid; gap: 4px; }
    .cp-et-facts li + li::before { content: none; }
}

/* The leap ladder: rungs do to do, the leaps as dotted arcs, each song a button beside the note it lands on. */
.cp-et-ladder { margin: 0; padding: 22px 22px 18px; border-radius: 24px; background: var(--color-panel); border: 1px solid var(--color-edge); box-shadow: 0 30px 60px -40px rgb(60 40 20 / .35); }
.cp-et-ladder-head { display: flex; flex-wrap: wrap; align-items: baseline; justify-content: space-between; gap: 4px 16px; }
.cp-et-ladder-head .cp-et-kick { color: var(--color-muted); }
.cp-et-hint { font-family: var(--et-serif); font-style: italic; font-size: 15px; color: var(--color-muted); }
.cp-et-ladder-in { position: relative; margin-top: 10px; }
.cp-et-ladder-art { position: relative; }
.cp-et-ladder-art svg { display: block; width: 100%; height: auto; overflow: visible; }
.cp-et-rung { stroke: var(--color-edge); stroke-width: 1.5; }
.cp-et-arc { fill: none; stroke: var(--c); stroke-width: 2.5; stroke-linecap: round; stroke-dasharray: 2 7; }
.cp-et-arc-hit { fill: none; stroke: transparent; stroke-width: 22; cursor: pointer; pointer-events: stroke; }
.cp-et-dot { fill: var(--c); }
.cp-et-dot-from { fill: var(--color-panel); stroke: var(--c); stroke-width: 3; }
.cp-et-home { fill: var(--color-cream); }
.cp-et-ladder[data-on="three"] .cp-et-three .cp-et-arc, .cp-et-ladder[data-on="four"] .cp-et-four .cp-et-arc, .cp-et-ladder[data-on="five"] .cp-et-five .cp-et-arc { stroke-dasharray: none; stroke-width: 3.5; }
.cp-et-rung-n { position: absolute; inset-inline-start: 0; translate: 0 -50%; display: flex; gap: 5px; font-size: 15px; white-space: nowrap; pointer-events: none; }
.cp-et-rung-n b { font-weight: 650; }
.cp-et-rung-n em { font-family: var(--et-serif); font-style: italic; color: var(--color-muted); }
.cp-et-home-n { position: absolute; inset-inline-start: 21.15%; translate: -50% 16px; font-size: 11.5px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; pointer-events: none; }
.cp-et-tag { position: absolute; translate: 0 -50%; display: grid; justify-items: start; gap: 1px; min-height: 44px; padding: 5px 12px 5px 10px; border-radius: 14px; background: var(--color-panel); border: 1px solid var(--color-edge); color: var(--color-cream); text-align: start; line-height: 1.2; cursor: pointer; }
.cp-et-tag b { display: flex; align-items: center; gap: 6px; font-size: 13px; font-weight: 700; white-space: nowrap; }
.cp-et-tag b::before { content: ""; flex: none; width: 10px; height: 10px; border-radius: 99px; background: var(--c); }
.cp-et-tag i { padding-inline-start: 16px; font-family: var(--et-serif); font-size: 14px; color: var(--color-muted); white-space: nowrap; }
.cp-et-tag:hover { background: var(--fill-2, var(--color-raised)); }
.cp-et-tag:focus-visible { outline: 3px solid var(--color-cream); outline-offset: 2px; }
.cp-et-tag[aria-pressed="true"] { border-color: var(--c); box-shadow: 0 0 0 2px var(--c); }
@media (max-width: 479px) {
    .cp-et-ladder { padding: 16px 14px 12px; }
    .cp-et-rung-n { font-size: 13px; }
    .cp-et-tag { padding: 4px 9px 4px 8px; border-radius: 12px; }
    .cp-et-tag b { font-size: 12px; }
    .cp-et-tag i { font-size: 12.5px; }
    :root[data-skin="game"] body.s-arcade .cp-et-tag i { font-size: 11.5px; }
}
/* A ladder too narrow for a song's button beside its note (calm under 360 px, game's wider type under 480 px): the
   buttons sit in a row under the ladder, each with its leap's colour, as the design's own legend. */
@media (max-width: 359px) {
    .cp-et-ladder-in { display: flex; flex-wrap: wrap; gap: 8px; }
    .cp-et-ladder-art { flex: 0 0 100%; margin-bottom: 18px; }
    .cp-et-tag { position: static; translate: none; }
}
@media (max-width: 479px) {
    :root[data-skin="game"] body.s-arcade .cp-et-ladder-in { display: flex; flex-wrap: wrap; gap: 10px; }
    :root[data-skin="game"] body.s-arcade .cp-et-ladder-art { flex: 0 0 100%; margin-bottom: 18px; }
    :root[data-skin="game"] body.s-arcade .cp-et-tag { position: static; translate: none; }
}

/* 1 do: the shared game, its step above it; its bar's two labels and its song buttons each on one line (Hillel's
   narrow fixes), a label that doesn't fit going to the next line whole. Under 360 px game's wide type can't fit a song
   button's words on one line, so there they wrap. */
.cp-et-game .cp-dk-demo { margin-top: 18px; }
.cp-et-game .cp-dk-demo-bar { flex-wrap: wrap; row-gap: 4px; }
.cp-et-game .cp-dk-demo-bar > span { white-space: nowrap; }
@media (min-width: 360px) { .cp-et-game .cp-dk-hear { white-space: nowrap; } }

/* 2 re: what you leave with, four across under a rule. */
.cp-et-outcomes { display: grid; grid-template-columns: minmax(0, 1fr); gap: 0 40px; margin-top: 40px; border-top: 1px solid var(--color-cream); }
.cp-et-outcomes li { padding-block: 24px; border-bottom: 1px solid var(--color-edge); }
.cp-et-glyph { display: block; font-size: 40px; line-height: 1.1; font-style: italic; color: var(--et-accent); white-space: nowrap; }
.cp-et-outcomes p { margin-top: 14px; font-family: var(--et-serif); font-size: 19px; line-height: 1.5; }

/* 3 mi: the openings, each word at the height of its note. */
.cp-et-split { display: grid; grid-template-columns: minmax(0, 1fr); gap: 0 56px; }
.cp-et-cards { display: grid; grid-template-columns: minmax(0, 1fr); gap: 20px; margin-top: 40px; }
.cp-et-card { padding: 22px 24px 26px; border-radius: 20px; background: var(--color-panel); border: 1px solid var(--color-edge); }
.cp-et-card-head { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
.cp-et-card-song { font-size: 12px; font-weight: 700; letter-spacing: .14em; text-transform: uppercase; color: var(--color-muted); }
.cp-et-round { flex: none; display: grid; place-items: center; width: 44px; height: 44px; border-radius: 99px; border: 1.5px solid var(--color-cream); color: var(--color-cream); }
.cp-et-round:hover { background: var(--fill-2, var(--color-raised)); }
.cp-et-round:focus-visible, .cp-et-hear:focus-visible { outline: 3px solid currentColor; outline-offset: 3px; }
.cp-et-round-icon { width: 0; height: 0; margin-inline-start: 3px; border-block: 6px solid transparent; border-inline-start: 10px solid currentColor; }
.cp-et-round[aria-pressed="true"] .cp-et-round-icon, .cp-et-hear[aria-pressed="true"] .cp-et-hear-icon { width: 10px; height: 10px; margin: 0; border: 0; border-radius: 2px; background: currentColor; }
.cp-et-sheet { margin: 14px 0 0; }
.cp-et-sheet-in { position: relative; height: 136px; }
.cp-et-line { position: absolute; inset-inline: 0; height: 1px; background: var(--color-edge); }
.cp-et-sheet-arc { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; }
.cp-et-sheet-arc path { fill: none; stroke: var(--c); stroke-width: 1.6; stroke-linecap: round; stroke-dasharray: 2 4; }
.cp-et-word { position: absolute; translate: 0 -55%; padding-inline: 3px; border-radius: 6px; font-family: var(--et-serif); font-size: 17px; font-style: italic; line-height: 1.2; color: var(--color-muted); white-space: nowrap; }
.cp-et-word-leap { font-size: 19px; font-weight: 650; color: var(--color-cream); text-decoration: underline 2px var(--c); text-underline-offset: 4px; }
.cp-et-slur { width: 8px; height: 8px; padding: 0; translate: 2px -50%; border-radius: 99px; background: var(--color-muted); }
.cp-et-word[data-on] { background: color-mix(in srgb, var(--c) 22%, transparent); color: var(--color-cream); }
.cp-et-slur[data-on] { background: var(--c); }
.cp-et-card h3 { margin-top: 14px; font-size: 28px; line-height: 1.15; letter-spacing: -0.01em; }
.cp-et-card-note { margin-top: 8px; font-size: 15px; line-height: 1.5; color: var(--color-muted); }
.cp-et-card-note i { font-family: var(--et-serif); white-space: nowrap; }

/* 4 fa: bright or dark, warm and night side by side, the third dropping. */
.cp-et-colour { display: grid; grid-template-columns: minmax(0, 1fr); margin-top: clamp(72px, 9vw, 120px); }
.cp-et-bright { background: var(--et-warm); color: var(--et-warm-ink); --t: var(--et-warm-third); }
.cp-et-dark { background: var(--et-night); color: var(--et-night-ink); --t: var(--et-night-third); }
.cp-et-bright .cp-et-p { color: var(--et-warm-muted); }
.cp-et-dark .cp-et-p { color: var(--et-night-muted); }
.cp-et-half { padding: clamp(56px, 8vw, 112px) 16px; max-width: 600px; }
.cp-et-bright .cp-et-step { color: var(--et-warm-muted); }
.cp-et-bright .cp-et-step-n { background: var(--et-warm-ink); color: var(--et-warm); }
.cp-et-bright .cp-et-step em { color: var(--et-warm-ink); }
.cp-et-colour-h, .cp-et-dark-big { margin-top: 24px; font-size: clamp(72px, 10vw, 132px); line-height: .95; letter-spacing: -0.04em; }
.cp-et-dark-big { margin-top: 0; font-style: italic; }
.cp-et-chord { display: grid; grid-template-columns: 40px auto; grid-template-rows: auto auto; align-items: end; gap: 14px 24px; margin: 40px 0 0; }
.cp-et-stack { grid-row: 1 / 3; position: relative; width: 34px; height: 154px; }
.cp-et-stack i { position: absolute; inset-inline-start: 0; width: 34px; height: 34px; border-radius: 99px; background: currentColor; top: var(--y); }
.cp-et-c-so { --y: 0px; }
.cp-et-c-do { --y: 120px; }
[data-et-chord="major"] .cp-et-c-third { --y: 50px; background: var(--t) !important; }
[data-et-chord="minor"] .cp-et-c-third { --y: 84px; background: var(--t) !important; }
[data-et-chord="minor"][data-raised] .cp-et-c-third { --y: 50px; }
.cp-et-c-ghost { --y: 50px; background: none !important; border: 2px dashed currentColor; opacity: .55; }
.cp-et-chord figcaption { font-size: 14px; line-height: 1.4; }
.cp-et-chord figcaption b { display: block; font-size: 16px; font-weight: 700; }
.cp-et-chord figcaption span { font-family: var(--et-serif); font-style: italic; }
.cp-et-hear { justify-self: start; display: inline-flex; align-items: center; gap: 8px; min-height: 44px; padding: 0 18px 0 14px; border-radius: 99px; border: 1.5px solid currentColor; font-size: 15px; font-weight: 700; white-space: nowrap; }
.cp-et-hear:hover { background: color-mix(in srgb, currentColor 10%, transparent); }
.cp-et-hear-icon { width: 0; height: 0; border-block: 6px solid transparent; border-inline-start: 10px solid currentColor; }
.cp-et-chord[data-playing] .cp-et-stack i:not(.cp-et-c-ghost) { box-shadow: 0 0 0 4px color-mix(in srgb, currentColor 25%, transparent); }
@media (prefers-reduced-motion: no-preference) {
    .cp-et-stack i { transition: top .35s cubic-bezier(.3, .7, .3, 1); }
}

/* 5 so: the course, four units rising like stairs, every lesson linked with its first line. */
.cp-et-split-end { align-items: end; }
.cp-et-stairs { display: grid; grid-template-columns: minmax(0, 1fr); gap: 36px 16px; margin-top: 48px; align-items: start; }
.cp-et-unit-top { display: flex; align-items: baseline; justify-content: space-between; gap: 12px; padding-bottom: 8px; border-bottom: 2px solid var(--color-cream); }
.cp-et-unit-deg { font-size: 48px; line-height: 1; }
.cp-et-unit-deg em { font-size: 20px; font-style: italic; color: var(--et-accent); }
.cp-et-unit-n { font-size: 12px; font-weight: 700; letter-spacing: .14em; text-transform: uppercase; color: var(--color-muted); white-space: nowrap; }
.cp-et-unit-card { padding: 20px 20px 10px; border: 1px solid var(--color-edge); border-top: 0; border-radius: 0 0 16px 16px; background: var(--color-panel); }
.cp-et-unit-card h3 { font-size: 26px; line-height: 1.15; }
.cp-et-unit-say { margin-top: 10px; font-size: 14.5px; line-height: 1.5; color: var(--color-muted); }
.cp-et-lessons { margin-top: 14px; }
.cp-et-lessons li { display: grid; grid-template-columns: 28px minmax(0, 1fr); gap: 8px; padding-block: 12px; border-top: 1px dashed var(--color-edge); }
.cp-et-num { padding-top: 2px; font-size: 12px; font-variant-numeric: tabular-nums; color: var(--color-muted); }
.cp-et-lesson { display: block; }
.cp-et-lesson a, .cp-et-lesson > b { font-size: 15.5px; font-weight: 700; }
.cp-et-lesson a { display: inline-block; padding-block: 10px; margin-block: -10px; text-decoration: underline; text-decoration-color: color-mix(in srgb, var(--color-cream) 30%, transparent); text-underline-offset: 4px; }
.cp-et-lesson a:hover { text-decoration-color: currentColor; }
.cp-et-lesson .s-free { margin-inline-start: 8px; vertical-align: 2px; }
.cp-et-line-text { display: block; margin-top: 4px; font-size: 13.5px; line-height: 1.45; color: var(--color-muted); }

/* Inside lesson 1. */
.cp-et-inside { display: grid; grid-template-columns: minmax(0, 1fr); gap: 32px 64px; align-items: start; }
.cp-et-try li { display: grid; grid-template-columns: 52px minmax(0, 1fr); gap: 12px; padding-block: 22px; border-top: 1px solid var(--color-edge); }
.cp-et-try li:last-child { border-bottom: 1px solid var(--color-edge); }
.cp-et-try-n { font-size: 38px; line-height: 1; font-style: italic; color: var(--et-accent); }
.cp-et-try p { font-family: var(--et-serif); font-size: 19px; line-height: 1.5; }

/* 6 la: what the app listens for, on the dark band, beside the sample board. */
.cp-et-mic { margin-top: clamp(72px, 9vw, 120px); padding-block: clamp(64px, 9vw, 120px); background: var(--k-band); color: var(--k-band-ink); }
.cp-et-mic-in { display: grid; grid-template-columns: minmax(0, 1fr); gap: 40px 72px; align-items: center; }
.cp-et-mic .cp-et-p, .cp-et-mic .cp-et-fine, .cp-et-mic .cp-et-step { color: var(--k-band-muted); }
.cp-et-step-ink .cp-et-step-n { background: var(--k-band-ink); color: var(--k-band); }
.cp-et-step-ink em { color: var(--s-hl-em-on-ink); }
.cp-et-board { margin: 0; padding: 22px clamp(18px, 2.4vw, 28px) 24px; border-radius: 24px; background: color-mix(in srgb, #000 30%, var(--k-band)); border: 1px solid var(--k-band-line); --c: var(--et-board-dart, #f0a35e); }
.cp-et-sample { display: flex; flex-wrap: wrap; align-items: baseline; gap: 6px 10px; font-size: 14px; line-height: 1.45; color: var(--k-band-muted); }
.cp-et-sample b { padding: 3px 10px; border-radius: 99px; background: var(--k-band-ink); color: var(--k-band); font-size: 12px; font-weight: 800; letter-spacing: .08em; text-transform: uppercase; white-space: nowrap; }
.cp-et-board-head { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 6px 16px; margin-top: 18px; font-size: 12px; font-weight: 700; letter-spacing: .14em; text-transform: uppercase; color: var(--k-band-muted); }
.cp-et-board-in { position: relative; height: 200px; margin-top: 10px; }
.cp-et-board-rung { position: absolute; inset-inline: 0; translate: 0 -50%; display: flex; align-items: center; gap: 12px; }
.cp-et-board-rung b { flex: none; width: 52px; font-size: 13px; font-weight: 600; color: var(--k-band-muted); }
.cp-et-board-rung b em { font-style: normal; }
.cp-et-board-rung::after { content: ""; flex: 1; height: 1px; background: var(--k-band-line); }
.cp-et-band { position: absolute; inset-inline: 64px 0; top: 38%; height: 24%; border-radius: 10px; border: 1px solid #f0a35e; background: rgb(240 163 94 / .16); }
.cp-et-dart { position: absolute; width: 18px; height: 18px; border-radius: 99px; translate: -50% -50%; left: calc(64px + (100% - 64px) * var(--x)); background: #f0a35e; box-shadow: 0 0 0 5px rgb(240 163 94 / .2); }
.cp-et-dart-off { background: #b49cff; box-shadow: 0 0 0 5px rgb(180 156 255 / .2); }
.cp-et-found { margin-top: 18px; padding-top: 16px; border-top: 1px solid var(--k-band-line); font-size: 26px; line-height: 1.25; }

/* 7 ti: who it's for and what you need, in ruled lists, the songs in their own card. */
.cp-et-kit { display: grid; grid-template-columns: minmax(0, 1fr); gap: 40px; margin-top: 40px; }
.cp-et-rules { margin-top: 14px; border-top: 1.5px solid var(--color-cream); }
.cp-et-rules li { padding-block: 14px; border-bottom: 1px dashed var(--color-edge); font-size: 16px; line-height: 1.5; }
.cp-et-gap { margin-top: 32px; }
.cp-et-songs { padding: 24px; border-radius: 20px; background: var(--color-panel); border: 1px solid var(--color-edge); align-self: start; }
.cp-et-songs ul { display: grid; gap: 8px; margin-top: 14px; }
.cp-et-songs b { font-family: var(--et-serif); font-size: 18px; font-weight: 400; }
.cp-et-songs span { font-size: 13.5px; color: var(--color-muted); }

/* The facts, three across between two rules. */
.cp-et-notes { display: grid; grid-template-columns: minmax(0, 1fr); gap: 0 40px; margin-top: 16px; border-block: 1px solid var(--color-cream); }
.cp-et-notes li { padding-block: 24px; }
.cp-et-notes li + li { border-top: 1px solid var(--color-edge); }
.cp-et-notes p { font-family: var(--et-serif); font-size: 20px; font-style: italic; line-height: 1.5; }

/* Questions beside their heading. */
.cp-et-faq { display: grid; grid-template-columns: minmax(0, 1fr); gap: 8px 56px; align-items: start; }
.cp-et-faq .cp-et-h2 { margin-top: 0; }

/* 8 do: home again, the scale climbed. */
.cp-et-close { display: grid; justify-items: center; text-align: center; }
.cp-et-climb { display: flex; align-items: flex-end; gap: 8px; height: 76px; margin-bottom: 20px; }
.cp-et-climb i { width: 13px; height: 13px; border-radius: 99px; background: var(--color-line); }
.cp-et-climb i:first-child { background: var(--color-cream); }
.cp-et-climb i:last-child { background: var(--et-accent); }
.cp-et-climb i:nth-child(2) { margin-bottom: 9px; } .cp-et-climb i:nth-child(3) { margin-bottom: 18px; } .cp-et-climb i:nth-child(4) { margin-bottom: 27px; }
.cp-et-climb i:nth-child(5) { margin-bottom: 36px; } .cp-et-climb i:nth-child(6) { margin-bottom: 45px; } .cp-et-climb i:nth-child(7) { margin-bottom: 54px; } .cp-et-climb i:nth-child(8) { margin-bottom: 63px; }
.cp-et-close .cp-et-step { justify-content: center; }
.cp-et-close .cp-et-step-n { background: var(--et-accent); color: var(--color-ink); }
.cp-et-join { margin-top: 16px; font-size: clamp(60px, 9vw, 128px); line-height: .98; letter-spacing: -0.04em; }
.cp-et-close .cp-et-p { margin-inline: auto; max-width: 44ch; font-size: 19px; }
.cp-et-note { margin-top: 12px; font-size: 14.5px; color: var(--color-muted); }
.cp-et-close .cp-et-btns, .cp-et-close .cp-related { justify-content: center; }
.cp-et-related-h { margin-top: 56px; color: var(--color-muted); }

/* The sources. */
.cp-et-sources { padding-top: 56px; }
.cp-et-sources .cp-et-kick { color: var(--color-muted); }
.cp-et-sources ol { margin-top: 10px; display: grid; gap: 6px; padding-inline-start: 20px; list-style: decimal; font-size: 14px; color: var(--color-muted); }
.cp-et-sources a { text-decoration: underline; text-underline-offset: 3px; }

@media (min-width: 600px) {
    .cp-et-half { padding-inline: 40px; }
    .cp-et-stairs { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (min-width: 900px) {
    .cp-et-hero { padding-top: 32px; }
    .cp-et-top { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); align-items: center; margin-top: 40px; }
    .cp-et-outcomes { grid-template-columns: repeat(4, minmax(0, 1fr)); }
    .cp-et-outcomes li { border-bottom: 0; }
    .cp-et-split { grid-template-columns: minmax(0, 1.25fr) minmax(0, 1fr); align-items: end; }
    .cp-et-split .cp-et-p { margin-top: 0; }
    .cp-et-cards { grid-template-columns: repeat(3, minmax(0, 1fr)); }
    .cp-et-colour { grid-template-columns: repeat(2, minmax(0, 1fr)); }
    .cp-et-bright .cp-et-half { justify-self: end; text-align: end; padding-inline: 40px 48px; }
    .cp-et-bright .cp-et-step, .cp-et-bright .cp-et-chord { justify-content: end; }
    .cp-et-bright .cp-et-p { margin-inline-start: auto; }
    .cp-et-bright .cp-et-chord { grid-template-columns: auto 40px; }
    .cp-et-bright .cp-et-stack { grid-column: 2; }
    .cp-et-bright .cp-et-chord figcaption, .cp-et-bright .cp-et-hear { grid-column: 1; justify-self: end; }
    .cp-et-dark .cp-et-half { padding-inline: 48px 40px; }
    .cp-et-dark .cp-et-dark-big { margin-top: 54px; }
    .cp-et-inside { grid-template-columns: minmax(0, .9fr) minmax(0, 1.1fr); }
    .cp-et-mic-in { grid-template-columns: repeat(2, minmax(0, 1fr)); }
    .cp-et-kit { grid-template-columns: repeat(3, minmax(0, 1fr)); }
    .cp-et-notes { grid-template-columns: repeat(3, minmax(0, 1fr)); }
    .cp-et-notes li + li { border-top: 0; }
    .cp-et-faq { grid-template-columns: minmax(0, .4fr) minmax(0, .6fr); }
}
@media (min-width: 1100px) {
    .cp-et-stairs { grid-template-columns: repeat(4, minmax(0, 1fr)); }
    .cp-et-unit:nth-child(1) { margin-top: 144px; }
    .cp-et-unit:nth-child(2) { margin-top: 96px; }
    .cp-et-unit:nth-child(3) { margin-top: 48px; }
}
@media (max-width: 899px) {
    .cp-et-dark .cp-et-dark-big { font-size: clamp(56px, 16vw, 96px); }
    .cp-et-colour-h { font-size: clamp(56px, 16vw, 96px); }
}

/* The game skin: the arcade's pixel headings and HUD labels, square framed panels with hard shadows, the leaps in
   neon, the scale's steps as HUD chips. */
:root[data-skin="game"] body.s-arcade :is(.cp-et-h2, .cp-et-hero h1, .cp-et-colour-h, .cp-et-dark-big, .cp-et-join, .cp-et-unit-deg, .cp-et-glyph, .cp-et-found) { font-family: var(--arc-pixel); font-weight: 400; font-style: normal; letter-spacing: 0; font-size-adjust: .58; --arc-ex: .58; line-height: 1.2; text-shadow: .06em .06em 0 var(--arc-shade); }
:root[data-skin="game"] body.s-arcade .cp-et-hero h1 { font-size: clamp(34px, 5vw, 60px); }
:root[data-skin="game"] body.s-arcade :is(.cp-et-h2, .cp-et-found) { font-size: clamp(22px, 3vw, 34px); }
:root[data-skin="game"] body.s-arcade :is(.cp-et-colour-h, .cp-et-dark-big, .cp-et-join) { font-size: clamp(30px, 5vw, 56px); }
:root[data-skin="game"] body.s-arcade :is(.cp-et-unit-deg, .cp-et-glyph) { font-size: 24px; }
:root[data-skin="game"] body.s-arcade :is(.cp-et-kick, .cp-et-step, .cp-et-eyebrow, .cp-et-unit-n, .cp-et-card-song, .cp-et-sample b, .cp-et-board-head) { font-family: var(--a-hud); font-weight: 400; font-size: 11px; font-size-adjust: var(--arc-ex, none); letter-spacing: .06em; }
:root[data-skin="game"] body.s-arcade :is(.cp-et-ladder, .cp-et-card, .cp-et-unit-card, .cp-et-board, .cp-et-songs) { border: var(--arc-edge-w, 2px) solid var(--arc-line); border-radius: 0; box-shadow: var(--arc-shadow); }
:root[data-skin="game"] body.s-arcade :is(.cp-et-tag, .cp-et-open, .cp-et-band, .cp-et-hear, .cp-et-sample b, .cp-et-step-n, .cp-et-word) { border-radius: 0; }
:root[data-skin="game"] body.s-arcade .cp-et-tag { border: 2px solid var(--c); box-shadow: 3px 3px 0 var(--arc-shadow-c); }
:root[data-skin="game"] body.s-arcade .cp-et-tag b { font-family: var(--a-hud); font-weight: 400; font-size: 10px; font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade .cp-et-dot { filter: drop-shadow(0 0 5px var(--c)); }
:root[data-skin="game"] body.s-arcade .cp-et-open { color: var(--arc-hazard-ink); }
:root[data-skin="game"][data-theme$="-light"] body.s-arcade .cp-et-open { color: #fff; }
:root[data-skin="game"] body.s-arcade :is(.cp-et-bright, .cp-et-dark) { border-block: 2px solid var(--arc-line); }
:root[data-skin="game"] body.s-arcade .cp-et-unit-top { border-bottom-color: var(--et-accent); }

/* Folk and early music (site/courses/folk-and-early-music), after Hillel's design (2026-11-18): an old printed ballad
   sheet. Headings in IM Fell English and its small caps (self-hosted, shared), key words in madder red, double rules and
   framed cards on the theme's own ground; text in Figtree. The four shape notes (fa a triangle, sol an oval, la a
   square, mi a diamond) are one piece, .cp-fo-sh[data-sh], drawn by clip-path; mi, the bright note, is red. The hero's
   broadside on wooden boards, Now Playing on the shared deck (.cp-dk) with the line as shape notes and the drone bar
   that turns red while it sounds (js/public/folk-and-early-music.js). Calm light and dark from the theme's tokens; game:
   a neon tavern on the arcade's (pink for the red, yellow for the ink, square frames with hard shadows). */
.cp-folk { --fo-serif: 'IM Fell English', 'Iowan Old Style', 'Palatino Linotype', Palatino, Georgia, ui-serif, serif; --fo-sc-face: 'IM Fell English SC', var(--fo-serif);
    --fo-red: #9b3222; --fo-shape: var(--color-cream); --fo-rule: color-mix(in srgb, var(--color-cream) 85%, transparent); --fo-hair: color-mix(in srgb, var(--color-cream) 16%, transparent);
    --fo-sheet: #f2e8d6; --fo-card: var(--color-panel);
    --fo-paper: #f3ebd9; --fo-paper-2: #e8dcc0; --fo-ink: #2a2118; --fo-svg-red: #9b3a28; --fo-wood: #6e4a2e; --fo-wood-2: #5a3b23;
    --cp-a: #9b3222; --cp-a-ink: #fff; --cp-a-text: #9b3222; }
:root:not([data-theme$="-light"]) .cp-folk { --fo-red: #f0a58f; --cp-a-text: #f0a58f; --fo-sheet: color-mix(in srgb, var(--color-panel) 86%, #b98a5c); --fo-wood: #3a281a; --fo-wood-2: #2e2014; }
.cp-folk .s-ink { --fo-red: #f0a58f; --fo-shape: var(--color-cream); --fo-rule: color-mix(in srgb, var(--color-cream) 70%, transparent); --fo-hair: color-mix(in srgb, var(--color-cream) 16%, transparent); --cp-a-text: #f0a58f; }
:root[data-skin="game"] .cp-folk { --fo-red: var(--arc-pink); --cp-a: var(--arc-pink); --cp-a-text: var(--arc-pink); --fo-shape: var(--arc-yellow); --fo-rule: var(--arc-yellow); --fo-hair: var(--arc-line); --fo-sheet: var(--arc-panel); --fo-card: var(--arc-panel); }
:root[data-skin="game"]:not([data-theme$="-light"]) .cp-folk { --fo-paper: #120c22; --fo-paper-2: #0a0716; --fo-ink: #ffd84a; --fo-svg-red: #ff5fd2; --fo-wood: #1b1036; --fo-wood-2: #140b28; }
:root[data-skin="game"] .cp-folk .s-ink { --fo-red: var(--arc-pink); --fo-shape: var(--arc-yellow); --cp-a-text: var(--arc-pink); }

/* Type: the Fell for headings, its small caps for labels, the arcade's faces in game. */
.cp-fo-sc { font-family: var(--fo-sc-face); font-size: 15px; letter-spacing: .08em; line-height: 1.35; }
.cp-fo-red { color: var(--fo-red); }
.cp-fo-star { color: var(--fo-red); font-size: .8em; }
.cp-fo-kick { display: inline-flex; flex-wrap: wrap; gap: 8px; align-items: baseline; font-family: var(--fo-sc-face); font-size: 18px; letter-spacing: .08em; color: var(--fo-red); }
.cp-fo-title { margin-top: 6px; font-family: var(--fo-serif); font-weight: 400; font-size: clamp(36px, 6.4vw, 72px); line-height: 1.02; letter-spacing: -0.01em; text-wrap: balance; }
.cp-fo-title em, .cp-fo-h1b { font-style: italic; }
.cp-fo-label { display: block; font-size: 12px; font-weight: 800; letter-spacing: .14em; text-transform: uppercase; color: var(--fo-red); }
.cp-fo-lede { margin-top: 18px; max-width: 52ch; font-size: 18px; line-height: 1.6; color: color-mix(in srgb, var(--color-cream) 86%, var(--color-ink)); text-wrap: pretty; }
.cp-fo-quiet { margin-top: 16px; max-width: 56ch; font-size: 15px; line-height: 1.6; color: var(--color-muted); }
.cp-fo-sec { padding-top: clamp(72px, 10vw, 128px); }
.cp-folk :is(a, button):focus-visible { outline: 3px solid var(--ring, var(--color-accent)); outline-offset: 3px; }
:root[data-skin="game"] body.s-arcade .cp-folk :is(.cp-fo-sc, .cp-fo-kick, .cp-fo-label) { font-family: var(--a-hud); font-size: 10px; letter-spacing: .06em; text-transform: uppercase; line-height: 1.6; font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade .cp-folk :is(.cp-fo-title, .cp-fo-h1, .cp-fo-demo-h, .cp-fo-tunes-h) { font-family: var(--a-display); font-weight: 400; font-style: normal; text-transform: uppercase; letter-spacing: .01em; text-shadow: 3px 3px 0 var(--arc-shadow-c); font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade .cp-folk :is(.cp-fo-title em, .cp-fo-h1b) { font-style: normal; color: var(--arc-pink); }

/* The shape notes: one piece, sized by --sz. */
.cp-fo-sh { --sz: 18px; display: inline-block; flex: none; width: var(--sz); height: var(--sz); background: var(--fo-shape); vertical-align: middle; }
.cp-fo-sh[data-sh="fa"] { clip-path: polygon(0 100%, 100% 0, 100% 100%); }
.cp-fo-sh[data-sh="sol"] { width: calc(var(--sz) * 1.12); clip-path: ellipse(50% 50% at 50% 50%); }
.cp-fo-sh[data-sh="la"] { width: calc(var(--sz) * .9); height: calc(var(--sz) * .9); }
.cp-fo-sh[data-sh="mi"] { clip-path: polygon(50% 0, 100% 50%, 50% 100%, 0 50%); }
.cp-fo-sh.cp-fo-is-red { background: var(--fo-red); }

/* The hero: the strap with the trail, the headline and the broadside on its boards, the shape key, the drone. */
.cp-fo-hero { padding-top: clamp(20px, 3vw, 36px); }
.cp-fo-strap { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 4px 16px; padding-block: 4px; border-top: 3px double var(--fo-rule); border-bottom: 1px solid var(--fo-rule); }
.cp-fo-strap .cp-fo-sc { display: flex; flex-wrap: wrap; gap: 2px 8px; align-items: baseline; }
.cp-fo-top { display: grid; gap: 36px; padding-block: clamp(28px, 4vw, 48px) 40px; }
.cp-fo-h1 { font-family: var(--fo-serif); font-weight: 400; font-size: clamp(64px, 13vw, 140px); line-height: .92; letter-spacing: -0.02em; }
.cp-fo-h1a { display: block; }
.cp-fo-h1a::first-letter { color: var(--fo-red); }
.cp-fo-h1b { display: block; margin-top: .04em; }
.cp-fo-lead { margin-top: 26px; max-width: 34em; font-size: clamp(18px, 1.8vw, 21px); line-height: 1.55; color: color-mix(in srgb, var(--color-cream) 88%, var(--color-ink)); text-wrap: pretty; }
.cp-fo-facts { display: flex; flex-wrap: wrap; gap: 4px 14px; margin-top: 18px; font-size: 15px; color: var(--color-muted); }
.cp-fo-btns { display: flex; flex-wrap: wrap; gap: 12px; margin-top: 28px; }
.cp-fo-art { margin: 0; }
.cp-fo-wall { position: relative; max-width: 560px; margin-inline: auto; padding: 26px 22px; border-radius: 20px; background: repeating-linear-gradient(180deg, var(--fo-wood) 0 46px, var(--fo-wood-2) 46px 48px), linear-gradient(90deg, #0003, transparent 30%, #0002); background-blend-mode: multiply; box-shadow: 0 30px 60px -36px rgb(0 0 0 / .7); }
