.cp-fo-cloud { fill: var(--fo-paper-2); stroke: var(--fo-ink); stroke-width: 1.6; }
.cp-fo-gull { fill: none; stroke: var(--fo-ink); stroke-width: 1.8; stroke-linecap: round; }
.cp-fo-mast { stroke: var(--fo-ink); stroke-width: 4; }
.cp-fo-sail { stroke: var(--fo-ink); stroke-width: 2.4; stroke-linejoin: round; }
