.cp-fo-tack-11 { top: 32px; left: 36px; } .cp-fo-tack-12 { top: 24px; right: 38px; } .cp-fo-tack-21 { bottom: 24px; left: 32px; } .cp-fo-tack-22 { bottom: 32px; right: 34px; }
:root[data-skin="game"] body.s-arcade :is(.cp-fo-shape, .cp-fo-hull, .cp-fo-mast) { filter: drop-shadow(0 0 4px #ffd84a); }
:root[data-skin="game"] body.s-arcade .cp-fo-caption { font-family: inherit; font-style: normal; }
.cp-fo-caption { margin-top: 14px; text-align: center; font-family: var(--fo-serif); font-style: italic; font-size: 17px; line-height: 1.45; color: color-mix(in srgb, var(--color-cream) 80%, var(--color-ink)); text-wrap: balance; }
