.cp-fo-drone-says span:last-child { text-align: end; }

/* Now Playing: the shared deck in tavern wood, the brick's light rose and old brass; the line as shape notes. */
.cp-folk .cp-dk-demo { --pd-bg: #1d1814; --pd-edge: #3f342c; --pd-ink: #f6eee2; --pd-body: #e3d8ca; --pd-muted: #c2b5a5; --pd-rose: #eaa48c; --pd-gold: #e2c98e; --pd-bar: #4b3e33; --pd-staff: #3a302a; }
:root[data-skin="game"] .cp-folk .cp-dk-demo { --pd-rose: #ff5fd2; --pd-gold: #ffd84a; }
:root[data-skin="game"] body.s-arcade .cp-folk :is(.cp-dk-demo, .cp-fo-roll, .cp-dk-play, .cp-dk-hear) { border-radius: 0; }
:root[data-skin="game"] body.s-arcade .cp-folk .cp-dk-demo { border: 2px solid #ffd84a; box-shadow: 6px 6px 0 #ff5fd2; }
.cp-fo-demosec { margin-top: clamp(40px, 6vw, 72px); }
.cp-fo-demo-h { font-family: var(--fo-serif); font-weight: 400; letter-spacing: -0.01em; }
.cp-folk .cp-dk-btns > * { white-space: nowrap; }
.cp-folk .cp-dk-play-b .cp-dk-play-icon { background: var(--pd-gold); }
.cp-fo-pick { align-items: center; gap: 10px 16px; }
.cp-fo-pick > * { white-space: nowrap; }
.cp-fo-switch { --fill-3: #4a4352; --fill-4: #5d5566; --selected: var(--pd-rose); --selected-ink: #1a1420; --knob-off: #d9d0dc;
    display: inline-flex; align-items: center; gap: 10px; min-height: 44px; padding: 0 6px; border: 0; border-radius: 99px; background: transparent; color: var(--pd-body); font: 600 14px/1.2 Figtree, system-ui, sans-serif; white-space: nowrap; cursor: pointer; text-align: start; }
:root[data-skin="game"] body.s-arcade .cp-fo-switch { font: 400 10px/1.4 var(--a-hud); }
.cp-fo-roll { position: relative; margin: 0; padding: 20px 14px 14px; border-radius: 16px; background: color-mix(in srgb, var(--pd-bg) 60%, #000); }
.cp-fo-notes { --step: 20px; --sz: 20px; display: grid; grid-template-columns: repeat(var(--n, 10), minmax(0, 1fr)); }
.cp-fo-notes li { display: grid; justify-items: center; gap: 8px; min-width: 0; }
.cp-fo-col { position: relative; display: block; width: 100%; height: calc(var(--step) * 6 + var(--sz)); background: linear-gradient(var(--pd-staff), var(--pd-staff)) 0 calc(100% - var(--sz) / 2) / 100% 1px no-repeat, linear-gradient(var(--pd-staff), var(--pd-staff)) 0 calc(100% - var(--sz) / 2 - var(--step) * 2) / 100% 1px no-repeat, linear-gradient(var(--pd-staff), var(--pd-staff)) 0 calc(100% - var(--sz) / 2 - var(--step) * 3) / 100% 1px no-repeat, linear-gradient(var(--pd-staff), var(--pd-staff)) 0 calc(100% - var(--sz) / 2 - var(--step) * 5) / 100% 1px no-repeat; }
.cp-fo-col .cp-fo-sh { --sz: inherit; position: absolute; left: 50%; bottom: calc(var(--s) * var(--step)); translate: -50% 0; background: var(--pd-ink); transition: scale .18s ease, background-color .18s, opacity .18s; }
.cp-fo-notes [data-fo-sixth] .cp-fo-v-bright { background: var(--pd-rose); }
.cp-fo-notes [data-fo-sixth] .cp-fo-v-dark { background: var(--pd-gold); }
.cp-fo-demo[data-sixth="bright"] .cp-fo-v-dark, .cp-fo-demo[data-sixth="dark"] .cp-fo-v-bright { display: none; }
.cp-fo-demo[data-sixth="bright"] [data-fo-sixth] .cp-fo-v-dark, .cp-fo-demo[data-sixth="dark"] [data-fo-sixth] .cp-fo-v-bright { display: block; opacity: .25; }
.cp-fo-notes li[data-on] .cp-fo-sh { scale: 1.3; }
.cp-fo-notes li[data-on]:not([data-fo-sixth]) .cp-fo-sh { background: #fff; }
.cp-fo-demo[data-sixth="bright"] [data-fo-sixth][data-on] .cp-fo-v-dark, .cp-fo-demo[data-sixth="dark"] [data-fo-sixth][data-on] .cp-fo-v-bright { scale: 1; }
.cp-fo-word { font-family: var(--fo-serif); font-size: clamp(12px, 1.6vw, 18px); line-height: 1.2; color: var(--pd-muted); white-space: nowrap; }
.cp-fo-notes [data-fo-sixth] .cp-fo-word { color: var(--pd-rose); }
.cp-fo-demo[data-sixth="dark"] [data-fo-sixth] .cp-fo-word { color: var(--pd-gold); }
.cp-fo-notes [data-on] .cp-fo-word { color: #fff; }
.cp-fo-roll-drone { display: block; height: 6px; margin-top: 14px; border-radius: 99px; background: var(--pd-staff); transition: background-color .2s; }
.cp-fo-demo[data-playing] .cp-fo-roll-drone { background: #c8432c; }
:root[data-skin="game"] .cp-fo-demo[data-playing] .cp-fo-roll-drone { background: #ff5fd2; box-shadow: 0 0 10px #ff5fd2; }
.cp-fo-legend { display: flex; flex-wrap: wrap; gap: 6px 22px; margin-top: 14px; font-size: 14px; color: var(--pd-body); }
.cp-fo-legend span { display: inline-flex; align-items: center; gap: 8px; }
.cp-fo-legend .cp-fo-sh { --sz: 13px; }
.cp-fo-legend .cp-fo-sh[data-sh="mi"] { background: var(--pd-rose); }
.cp-fo-legend .cp-fo-sh[data-sh="fa"] { background: var(--pd-gold); }
.cp-fo-legend-drone { width: 18px; height: 4px; border-radius: 99px; background: var(--pd-muted); }
:root[data-skin="game"] body.s-arcade .cp-fo-word { font-family: inherit; font-size: clamp(12px, 1.6vw, 17px); }
@media (prefers-reduced-motion: reduce) { .cp-fo-col .cp-fo-sh, .cp-fo-roll-drone { transition: none; } .cp-fo-notes [data-on] .cp-fo-sh { scale: 1; } }

/* The ballad: the outcomes as stanzas, two by two at every width. */
.cp-fo-ballad { text-align: center; }
.cp-fo-ballad .cp-fo-kick { justify-content: center; }
.cp-fo-stanzas { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 0 clamp(16px, 4vw, 48px); margin-top: clamp(28px, 4vw, 48px); border-top: 1px solid var(--fo-rule); text-align: start; }
.cp-fo-stanzas li { padding: clamp(18px, 2.4vw, 28px) 0; border-bottom: 1px solid var(--fo-hair); }
.cp-fo-stanza-n { display: flex; align-items: center; gap: 10px; font-family: var(--fo-serif); font-size: clamp(22px, 2.4vw, 28px); color: var(--fo-red); }
