:root[data-skin="game"] body.s-arcade .cp-fo-stanzas p { font-family: inherit; font-style: normal; font-size: clamp(17px, 2vw, 20px); }
:root[data-skin="game"] body.s-arcade .cp-fo-stanza-n { font-family: var(--a-display); font-size-adjust: var(--arc-ex, none); }

/* The old scales: the words beside two framed cards, each scale rising in shapes. */
.cp-fo-modes { display: grid; gap: 36px; align-items: center; }
.cp-fo-mode-cards { display: grid; gap: 16px; }
.cp-fo-card { background: var(--fo-card); border: 3px double var(--fo-rule); }
:root[data-skin="game"] body.s-arcade .cp-fo-card { border: 2px solid var(--arc-yellow); box-shadow: var(--arc-shadow); }
.cp-fo-mode { margin: 0; padding: 22px 20px; }
.cp-fo-ladder { --step: 9px; --sz: 18px; position: relative; height: calc(var(--step) * 12 + var(--sz) + 6px); border-bottom: 1px solid var(--fo-hair); }
.cp-fo-ladder .cp-fo-sh { position: absolute; bottom: calc(var(--s) * var(--step) + 6px); inset-inline-start: calc(var(--i) * (100% - var(--sz)) / 7); }
.cp-fo-ghost { opacity: .3; }
.cp-fo-mode figcaption { display: grid; gap: 6px; margin-top: 16px; }
