.cp-fo-mode figcaption > span:last-child { font-size: 15px; line-height: 1.55; color: var(--color-muted); }
:root[data-skin="game"] body.s-arcade .cp-fo-mode b { font-family: var(--a-display); font-size: 20px; text-transform: uppercase; font-size-adjust: var(--arc-ex, none); }

/* Grace notes: the ornaments on a four-line staff, its lines red as the chant books print them. */
.cp-fo-grace { margin-top: clamp(72px, 10vw, 128px); padding-block: clamp(64px, 8vw, 104px); }
.cp-fo-grace-head { display: grid; gap: 10px 48px; align-items: end; }
.cp-fo-grace-head .cp-fo-lede { margin-top: 0; }
.cp-fo-orns { display: grid; gap: 18px; margin-top: 36px; }
.cp-fo-orn { margin: 0; padding: 24px 28px 26px; border: 1px solid var(--color-line); border-radius: 6px; background: color-mix(in srgb, var(--color-cream) 3%, transparent); }
:root[data-skin="game"] body.s-arcade .cp-fo-orn { border-radius: 0; border: 2px solid var(--arc-pink); box-shadow: var(--arc-shadow); }
.cp-fo-chant { display: block; width: 100%; height: auto; }
.cp-fo-chant-line { stroke: color-mix(in srgb, #d0533b 75%, transparent); stroke-width: 1.2; }
.cp-fo-neume { fill: var(--color-cream); }
.cp-fo-grace-n { fill: #eaa48c; }
:root[data-skin="game"] .cp-fo-grace-n { fill: var(--arc-pink); }
:root[data-skin="game"] .cp-fo-neume:not(.cp-fo-grace-n) { fill: var(--arc-yellow); }
.cp-fo-orn figcaption { margin-top: 18px; }
.cp-fo-orn figcaption b { font-family: var(--fo-serif); font-weight: 400; font-size: 30px; }
.cp-fo-orn figcaption em { margin-inline-start: 8px; font-family: var(--fo-serif); font-style: italic; font-size: 17px; color: var(--fo-red); }
.cp-fo-orn figcaption > span { display: block; margin-top: 8px; font-size: 15.5px; line-height: 1.6; color: var(--color-muted); }
:root[data-skin="game"] body.s-arcade .cp-fo-orn figcaption b { font-family: var(--a-display); font-size: 20px; text-transform: uppercase; font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade .cp-fo-orn figcaption em { font-family: inherit; font-style: normal; }

/* Four verses: the units as printed columns on one framed sheet, the lessons numbered through. */
.cp-fo-verses-head { display: flex; flex-wrap: wrap; align-items: flex-end; justify-content: space-between; gap: 8px 24px; }
.cp-fo-verses-head .cp-fo-title { max-width: 16ch; }
.cp-fo-count { font-size: 15px; color: var(--color-muted); }
.cp-fo-sheet { display: grid; margin-top: 32px; padding: 6px 22px; background: var(--fo-sheet); border: 3px double var(--fo-rule); box-shadow: 0 0 0 4px var(--fo-sheet), 0 0 0 5px var(--fo-rule), 0 30px 50px -40px rgb(0 0 0 / .5); }
:root[data-skin="game"] body.s-arcade .cp-fo-sheet { border: 2px solid var(--arc-yellow); box-shadow: var(--arc-shadow-lg); }
.cp-fo-verse { padding: 24px 0; border-bottom: 1px solid var(--fo-hair); }
.cp-fo-verse:last-child { border-bottom: 0; }
.cp-fo-verse-top { display: flex; align-items: flex-start; justify-content: space-between; gap: 12px; }
.cp-fo-verse-top .cp-fo-sh { --sz: 26px; }
.cp-fo-verse h3 { margin-top: 8px; font-family: var(--fo-serif); font-weight: 400; font-size: 30px; line-height: 1.1; }
:root[data-skin="game"] body.s-arcade .cp-fo-verse h3 { font-family: var(--a-display); font-size: 20px; text-transform: uppercase; font-size-adjust: var(--arc-ex, none); }
.cp-fo-verse-say { margin-top: 10px; padding-bottom: 16px; border-bottom: 1px solid var(--fo-hair); font-size: 14.5px; line-height: 1.55; color: var(--color-muted); }
.cp-fo-lessons { display: grid; gap: 4px; margin-top: 14px; font-size: 15.5px; }
.cp-fo-lessons li { display: grid; grid-template-columns: 26px minmax(0, 1fr); align-items: baseline; min-height: 30px; }
.cp-fo-lesson-n { font-family: var(--fo-serif); font-size: 15px; color: var(--fo-red); }
.cp-fo-lessons .s-free { margin-inline-start: 6px; padding: 1px 8px; font-size: 10.5px; white-space: nowrap; }
.cp-fo-lessons a { color: inherit; text-decoration: underline 1px color-mix(in srgb, var(--color-cream) 22%, transparent); text-underline-offset: 4px; }
.cp-fo-lessons a:hover { text-decoration-color: var(--fo-red); }
:root[data-skin="game"] body.s-arcade .cp-fo-lesson-n { font-family: var(--a-hud); font-size: 9px; font-size-adjust: var(--arc-ex, none); }

/* Strike up: lesson 1's call and answer beside the steps in roman numerals. */
.cp-fo-strike { display: grid; gap: 40px; }
.cp-fo-call { margin-top: 30px; padding-block: 24px; border-block: 1px solid var(--fo-rule); }
.cp-fo-quote { margin-top: 6px; font-family: var(--fo-serif); font-style: italic; font-size: clamp(24px, 3vw, 34px); line-height: 1.25; }
.cp-fo-call .cp-fo-label + .cp-fo-quote { margin-bottom: 18px; }
.cp-fo-echo { margin-bottom: 0 !important; color: var(--color-muted); }
:root[data-skin="game"] body.s-arcade .cp-fo-quote { font-family: inherit; font-style: normal; }
.cp-fo-steps { align-self: center; border-top: 1px solid var(--fo-rule); border-bottom: 1px solid var(--fo-rule); }
.cp-fo-steps li { display: grid; grid-template-columns: 64px minmax(0, 1fr); gap: 8px; padding: 20px 0; border-bottom: 1px solid var(--fo-hair); }
.cp-fo-steps li:last-child { border-bottom: 0; }
.cp-fo-step-n { font-family: var(--fo-serif); font-size: 32px; line-height: 1; color: var(--fo-red); }
.cp-fo-steps p { font-size: 17px; line-height: 1.55; }
.cp-fo-steps .cp-fo-label { margin-bottom: 4px; }
:root[data-skin="game"] body.s-arcade .cp-fo-step-n { font-family: var(--a-display); font-size: 22px; font-size-adjust: var(--arc-ex, none); }

/* The ear: what the app listens for, beside a real screen of lesson 1 and how a take is said. */
.cp-fo-ear { margin-top: clamp(72px, 10vw, 128px); padding-block: clamp(64px, 8vw, 104px); }
.cp-fo-ear-in { display: grid; gap: 40px; align-items: center; }
.cp-fo-rows { margin-top: 26px; border-top: 1px solid var(--fo-hair); }
.cp-fo-rows > div { display: grid; grid-template-columns: 96px minmax(0, 1fr); gap: 12px; padding: 16px 0; border-bottom: 1px solid var(--fo-hair); }
.cp-fo-rows dt { color: var(--fo-red); font-size: 18px; }
.cp-fo-rows dd { font-size: 16px; line-height: 1.5; }
.cp-fo-ear-side { display: grid; gap: 18px; justify-items: center; }
.cp-fo-ear-side .s-appshot { max-width: 340px; margin: 0; }
.cp-fo-said { width: 100%; padding: 22px 26px; border-radius: 6px; background: var(--color-cream); color: var(--color-ink); }
.cp-fo-said .cp-fo-label { color: #9b3222; }
:root:not([data-theme$="-light"]) .cp-fo-said .cp-fo-label { color: #9b3222; }
.cp-fo-said-q { margin-top: 8px; font-family: var(--fo-serif); font-size: clamp(20px, 2.2vw, 26px); line-height: 1.3; }
.cp-fo-said-n { margin-top: 10px; font-size: 14px; color: color-mix(in srgb, var(--color-ink) 72%, var(--color-cream)); }
:root[data-skin="game"] body.s-arcade .cp-fo-said { border-radius: 0; border: 2px solid var(--arc-yellow); background: var(--arc-panel); color: var(--color-cream); box-shadow: var(--arc-shadow); }
:root[data-skin="game"] body.s-arcade .cp-fo-said .cp-fo-label { color: var(--arc-pink); }
:root[data-skin="game"] body.s-arcade .cp-fo-said-q { font-family: inherit; font-size: 18px; }

/* From the old books: the facts as clippings, a headword in red over each, the source under it. */
.cp-fo-clippings { display: grid; gap: 28px; margin-top: 36px; }
.cp-fo-clip { padding: 30px 28px 24px; background: var(--fo-sheet); border-top: 3px double var(--fo-rule); box-shadow: 0 18px 30px -24px rgb(0 0 0 / .55); }
.cp-fo-clip:nth-child(1) { rotate: -1deg; } .cp-fo-clip:nth-child(3) { rotate: .6deg; }
:root[data-skin="game"] body.s-arcade .cp-fo-clip { rotate: none; border: 2px solid var(--arc-pink); box-shadow: var(--arc-shadow); }
.cp-fo-clip-word { font-family: var(--fo-serif); font-size: clamp(44px, 5vw, 60px); line-height: 1; color: var(--fo-red); }
.cp-fo-clip-text { margin-top: 14px; font-family: var(--fo-serif); font-size: 20px; line-height: 1.45; }
.cp-fo-clip-src { margin-top: 14px; font-size: 12.5px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--color-muted); }
.cp-fo-clip-src a { display: inline-block; padding-block: 12px; margin-block: -12px; color: inherit; text-underline-offset: 3px; }
.cp-fo-clip-src a:hover { color: var(--fo-red); }
:root[data-skin="game"] body.s-arcade :is(.cp-fo-clip-word) { font-family: var(--a-display); font-size: 34px; font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade .cp-fo-clip-text { font-family: inherit; font-size: 18px; }

/* Before you sing: who and what you need, singing safely, and the table of the tunes. */
.cp-fo-singer-grid { display: grid; gap: 36px; margin-top: 36px; }
.cp-fo-list { margin-top: 12px; border-top: 1px solid var(--fo-rule); }
.cp-fo-list li { display: flex; gap: 12px; align-items: flex-start; padding: 14px 0; border-bottom: 1px solid var(--fo-hair); font-size: 16px; line-height: 1.5; }
.cp-fo-list svg { flex: none; margin-top: 3px; color: var(--color-part-ink-3); }
.cp-fo-list li:has(> svg + *) svg, .cp-fo-singer-grid > div:nth-child(2) .cp-fo-list svg { color: var(--fo-red); }
.cp-fo-gap { margin-top: 32px; }
.cp-fo-tunes { padding: 24px 22px; align-self: start; }
.cp-fo-tunes-h { text-align: center; font-family: var(--fo-sc-face); font-weight: 400; font-size: 22px; letter-spacing: .06em; color: var(--fo-red); }
.cp-fo-tunes-sub { margin-top: 2px; text-align: center; font-size: 13px; color: var(--color-muted); }
.cp-fo-tunes ol { margin-top: 16px; border-top: 1px solid var(--fo-hair); }
.cp-fo-tunes li { display: grid; grid-template-columns: 70px minmax(0, 1fr); gap: 8px; padding: 14px 0; border-bottom: 1px solid var(--fo-hair); }
.cp-fo-tunes li:last-child { border-bottom: 0; }
.cp-fo-when { font-family: var(--fo-serif); font-size: 17px; color: var(--fo-red); }
.cp-fo-tunes b { display: block; font-family: var(--fo-serif); font-style: italic; font-weight: 400; font-size: 20px; line-height: 1.2; }
.cp-fo-tunes li span span { display: block; margin-top: 3px; font-size: 13.5px; line-height: 1.45; color: var(--color-muted); }
:root[data-skin="game"] body.s-arcade :is(.cp-fo-when, .cp-fo-tunes b) { font-family: inherit; font-style: normal; }
:root[data-skin="game"] body.s-arcade .cp-fo-tunes-h { font-size: 18px; }

/* Asked at the bar: the questions beside their heading, and all hands. */
.cp-fo-fine { display: grid; gap: 18px; }
.cp-folk .cp-fo-fine .cp-faq { margin-top: 0; max-width: none; border-top: 1px solid var(--fo-rule); }
.cp-folk .cp-fo-fine .cp-faq summary { font-family: var(--fo-serif); font-weight: 400; font-size: clamp(21px, 2.4vw, 27px); }
.cp-folk .cp-fo-fine .cp-faq-sign { width: 34px; height: 34px; background: transparent; border: 1.5px solid var(--color-cream); }
:root[data-skin="game"] body.s-arcade .cp-folk .cp-fo-fine .cp-faq summary { font-family: inherit; }
.cp-fo-close { padding-block: clamp(80px, 11vw, 136px) clamp(56px, 7vw, 88px); }
.cp-fo-close-in { display: grid; justify-items: center; text-align: center; }
.cp-fo-close-shapes { display: flex; gap: 12px; margin-bottom: 18px; }
.cp-fo-close-shapes .cp-fo-sh { --sz: 20px; }
.cp-fo-join { font-size: clamp(56px, 10vw, 112px); }
.cp-fo-close .cp-fo-lede { margin-inline: auto; max-width: 46ch; }
.cp-fo-close .cp-join-btns { justify-content: center; }
.cp-fo-related { width: 100%; max-width: 720px; margin-top: 52px; padding-top: 28px; border-top: 1px solid var(--fo-rule); display: grid; justify-items: center; }
.cp-fo-related .cp-related { justify-content: center; }

@media (max-width: 599px) {
    .cp-fo-notes { --step: 14px; --sz: 15px; }
    .cp-fo-roll { padding-inline: 6px; }
    .cp-fo-word { font-size: 11px; }
    :root[data-skin="game"] body.s-arcade .cp-fo-word { font-size: 11px; }
    .cp-fo-notes { padding-bottom: 1.4em; }
    .cp-fo-notes li:nth-child(even) .cp-fo-word { position: relative; top: 1.35em; }
    .cp-fo-btns > a, .cp-fo-close .cp-join-btns > a { flex: 1 1 100%; }
    .cp-fo-facts { display: grid; gap: 4px; }
    .cp-fo-facts .cp-fo-star { display: none; }
    .cp-fo-stanza-n { gap: 8px; }
    .cp-fo-stanza-n .cp-fo-sh { --sz: 16px; }
    .cp-fo-steps li { grid-template-columns: 48px minmax(0, 1fr); }
    .cp-fo-step-n { font-size: 26px; }
    .cp-fo-rows > div { grid-template-columns: 76px minmax(0, 1fr); }
    .cp-fo-orn { padding: 18px 16px 20px; }
    .cp-fo-sheet { padding-inline: 18px; }
    .cp-fo-lessons { gap: 0; }
    .cp-fo-lessons li { min-height: 44px; align-items: center; }
}
@media (min-width: 640px) {
    .cp-fo-key-list { grid-template-columns: repeat(4, minmax(0, 1fr)); }
    .cp-fo-mode-cards { grid-template-columns: repeat(2, minmax(0, 1fr)); }
    .cp-fo-clippings { grid-template-columns: repeat(2, minmax(0, 1fr)); }
    .cp-fo-sheet { grid-template-columns: repeat(2, minmax(0, 1fr)); column-gap: 28px; }
    .cp-fo-verse:nth-child(-n+2) { border-bottom: 1px solid var(--fo-hair); }
    .cp-fo-verse:nth-child(n+3) { border-bottom: 0; }
}
@media (min-width: 900px) {
    .cp-fo-top { grid-template-columns: minmax(0, 1.05fr) minmax(0, .95fr); gap: 56px; align-items: center; }
    .cp-fo-key { grid-template-columns: minmax(0, 1fr) minmax(0, 3fr); gap: 24px; align-items: start; }
    .cp-fo-modes { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 56px; }
    .cp-fo-grace-head { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); }
    .cp-fo-orns { grid-template-columns: repeat(2, minmax(0, 1fr)); }
    .cp-fo-strike { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 56px; align-items: start; }
    .cp-fo-ear-in { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 56px; }
    .cp-fo-clippings { grid-template-columns: repeat(3, minmax(0, 1fr)); }
    .cp-fo-singer-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 40px; }
    .cp-fo-fine { grid-template-columns: minmax(0, .9fr) minmax(0, 1.1fr); gap: 56px; align-items: start; }
}
@media (min-width: 1100px) {
    .cp-fo-sheet { grid-template-columns: repeat(4, minmax(0, 1fr)); column-gap: 0; padding: 0; }
    .cp-fo-verse, .cp-fo-verse:nth-child(-n+2) { padding: 28px 26px; border-bottom: 0; border-inline-start: 1px solid var(--fo-hair); }
    .cp-fo-verse:first-child { border-inline-start: 0; }
}

/* Pop and country styling (site/courses/pop-and-country), after Hillel's design (2026-11-18): a vinyl double album. A
   magenta sleeve with its record half out over a spine strip; headings in a heavy slab (Alfa Slab One, self-hosted, one
   weight, with heavy fallbacks), small labels in the system monospace; Now playing as a dark deck; the four moves as
   cards; "Small and light" and what the app listens for on the record's black; the units as sides A to D; the facts as
   liner notes; the credits as one ruled row. Tokens: the magenta and the record's colours, for calm light and dark and
   for game mode (the arcade's pink, its type, square framed panels). The record holds still under reduced motion. */
.cp-pop {
    --pc-slab: 'Alfa Slab One', 'Rockwell Extra Bold', 'Arial Black', 'Helvetica Neue', sans-serif;
    --pc-mono: var(--font-mono, ui-monospace, 'SF Mono', SFMono-Regular, Menlo, Consolas, monospace);
    --pc-mag: #c2255c; --pc-mag-ink: #fff; --pc-mag-text: #a91f50; --pc-mag-soft: #f6e7e0; --pc-label: #765900;
    --pc-vinyl: #1a1415; --pc-groove: #262022; --pc-centre: #e8553a; --pc-gold: #f5c25b;
    --pc-band: #171211; --pc-band-ink: #f3e9df; --pc-band-body: #d8cdcf; --pc-band-muted: #b9aeb0; --pc-band-line: #33292b;
    --pc-deck: #1c1517; --pc-well: #120d0f; --pc-bar: #4a3f45; --pc-rose: #f06598; --pc-card: var(--color-panel);
    --pc-side-1: #c2255c; --pc-side-1-ink: #fff; --pc-side-1-text: #7a2443;
    --pc-side-2: #c8432a; --pc-side-2-ink: #fff; --pc-side-2-text: #9a3a22;
    --pc-side-3: #d9a520; --pc-side-3-ink: #1e1715; --pc-side-3-text: #7a5c00;
    --pc-side-4: #1e1715; --pc-side-4-ink: #faf5ef; --pc-side-4-text: var(--color-muted);
}
:root:not([data-theme$="-light"]) .cp-pop {
    --pc-mag-text: #ff8fb5; --pc-mag-soft: color-mix(in srgb, #c2255c 16%, var(--color-panel)); --pc-label: #f5c25b;
    --pc-band: color-mix(in srgb, var(--color-panel) 55%, #0b0809); --pc-deck: #1c1517;
    --pc-side-1-text: #ff8fb5; --pc-side-2-text: #ff9a7a; --pc-side-3-text: #f5c25b;
    --pc-side-4: #f3e9df; --pc-side-4-ink: #1e1715;
}
:root[data-skin="game"] body.s-arcade .cp-pop {
    --pc-slab: var(--a-display); --pc-mono: var(--a-hud);
    --pc-mag: var(--a-pink); --pc-mag-ink: var(--a-pink-ink); --pc-mag-text: var(--a-pink); --pc-mag-soft: var(--a-raised); --pc-label: var(--a-pink);
    --pc-centre: var(--a-yellow); --pc-band: var(--a-bg-2); --pc-deck: #0d0818; --pc-well: #07050d; --pc-rose: #ff5fd2; --pc-card: var(--a-panel);
    --pc-side-1: var(--a-pink); --pc-side-1-ink: var(--a-pink-ink); --pc-side-1-text: var(--a-pink);
    --pc-side-2: var(--a-cyan); --pc-side-2-ink: #07060e; --pc-side-2-text: var(--color-part-ink-3);
    --pc-side-3: var(--a-yellow); --pc-side-3-ink: var(--a-yellow-ink); --pc-side-3-text: var(--color-part-ink-2);
    --pc-side-4: var(--color-part-4); --pc-side-4-ink: var(--color-part-text-4); --pc-side-4-text: var(--color-part-ink-4);
}
:root[data-skin="game"][data-theme$="-light"] body.s-arcade .cp-pop { --pc-band: #171427; }
/* The page lists every lesson in its tracklist, linked (lesson-pages-inline), so the shared list isn't repeated below. */
.cp-pop ~ [data-lesson-pages] { display: none; }

.cp-pop :is(a, button, summary):focus-visible { outline: 3px solid var(--pc-mag-text); outline-offset: 3px; }
.cp-pop-sec { padding-top: var(--k-sec); }
.cp-pop-kick { font-family: var(--pc-mono); font-size: 12px; font-weight: 500; letter-spacing: .14em; text-transform: uppercase; color: var(--pc-label); }
.cp-pop-title { font-family: var(--pc-slab); font-weight: 400; font-size: clamp(38px, 5vw, 64px); line-height: 1.02; letter-spacing: -0.01em; text-wrap: balance; }
.cp-pop-kick + .cp-pop-title { margin-top: 14px; }
.cp-pop-intro { margin-top: 18px; max-width: 34em; font-size: 18px; line-height: 1.6; color: var(--color-muted); text-wrap: pretty; }
.cp-pop-head-row { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: flex-end; gap: 16px 40px; }
.cp-pop-head-row .cp-pop-intro { margin-top: 0; max-width: 30em; }
.cp-pop-size { font-family: var(--pc-mono); font-size: 13px; color: var(--color-muted); }

/* The hero: the words, then the album; side by side from 900 px. */
.cp-pop-hero { overflow: hidden; }
.cp-pop-hero-grid { display: grid; grid-template-columns: minmax(0, 1fr); gap: clamp(40px, 5vw, 56px); align-items: center; padding-block: var(--k-hero-top) clamp(48px, 6vw, 72px); }
@media (min-width: 900px) { .cp-pop-hero-grid { grid-template-columns: minmax(0, 1.05fr) minmax(0, 1fr); } }
.cp-pop-chip { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 10px; margin-top: 22px; font-family: var(--pc-mono); font-size: 12px; letter-spacing: .08em; text-transform: uppercase; color: var(--color-muted); }
.cp-pop-chip b { padding: 4px 10px; border-radius: 99px; background: var(--color-cream); color: var(--color-ink); font-weight: 500; }
.cp-pop-h1 { margin-top: 20px; font-family: var(--pc-slab); font-weight: 400; font-size: clamp(50px, 7vw, 88px); line-height: .95; letter-spacing: -0.01em; text-wrap: balance; }
.cp-pop-h1 em { font-style: normal; color: var(--pc-mag-text); }
.cp-pop-lede { margin-top: 26px; max-width: 34em; font-size: clamp(17px, 1.4vw, 19px); line-height: 1.6; color: var(--color-muted); text-wrap: pretty; }
.cp-pop-btns { display: flex; flex-wrap: wrap; gap: 12px; margin-top: 30px; }
.cp-pop-btns .btn-lg { white-space: nowrap; }
@media (max-width: 479px) { .cp-pop-btns { flex-direction: column; } .cp-pop-btns .btn-lg { justify-content: center; } }

/* The album: the sleeve in front, the record half out of it to the right. */
.cp-pop-album { position: relative; width: 100%; max-width: 560px; aspect-ratio: 1.39; justify-self: center; }
.cp-pop-record { position: absolute; top: 2.8%; right: 0; width: 68%; aspect-ratio: 1; border-radius: 50%;
    background: radial-gradient(circle, var(--pc-vinyl) 0 1.6%, var(--pc-centre) 1.8% 17%, var(--pc-vinyl) 17.4% 18.4%, transparent 18.6%),
        conic-gradient(from 20deg, transparent 0 8%, rgb(255 255 255 / .10) 13%, transparent 20% 58%, rgb(255 255 255 / .07) 63%, transparent 70%),
        repeating-radial-gradient(circle, var(--pc-vinyl) 0 2px, var(--pc-groove) 2px 3px);
    box-shadow: 0 0 0 1px rgb(255 255 255 / .06), 0 20px 40px rgb(30 23 21 / .25); }
@media (prefers-reduced-motion: no-preference) { .cp-pop-record { animation: cp-pop-spin 9s linear infinite; } }
@keyframes cp-pop-spin { to { transform: rotate(360deg); } }
.cp-pop-sleeve { position: relative; z-index: 1; display: flex; flex-direction: column; justify-content: space-between; width: 72%; aspect-ratio: 1; padding: 7%; overflow: hidden; border-radius: 6px; background: var(--pc-mag); color: var(--pc-mag-ink); box-shadow: 0 24px 50px rgb(120 20 60 / .28); }
.cp-pop-sleeve-ring { position: absolute; left: 12%; top: 10%; width: 76%; aspect-ratio: 1; border-radius: 50%; border: 1.5px solid color-mix(in srgb, currentColor 12%, transparent); }
.cp-pop-sleeve-row { display: flex; justify-content: space-between; gap: 8px; font-family: var(--pc-mono); font-size: clamp(8px, 1.6vw, 11px); letter-spacing: .08em; text-transform: uppercase; }
.cp-pop-sleeve-mid { position: relative; }
.cp-pop-sleeve-title { font-family: var(--pc-slab); font-size: clamp(30px, 5vw, 58px); line-height: .92; }
.cp-pop-sleeve-title span { display: block; }
.cp-pop-sleeve-sub { margin-top: 10px; font-size: clamp(12px, 1.6vw, 15px); font-weight: 700; letter-spacing: .02em; }
.cp-pop-sleeve-line { display: block; width: 100%; height: auto; margin-top: 8px; overflow: visible; }
.cp-pop-sleeve-line path { fill: none; stroke: currentColor; stroke-width: 3; stroke-linecap: round; }
/* The spine: a dark strip with the album's facts. */
.cp-pop-spine { background: var(--pc-band); color: var(--pc-band-ink); }
.cp-pop-spine ul { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 28px; padding-block: 14px; font-family: var(--pc-mono); font-size: 12px; letter-spacing: .1em; text-transform: uppercase; }
.cp-pop-spine li { display: inline-flex; align-items: center; gap: 28px; }
.cp-pop-spine li + li::before { content: ""; width: 7px; height: 7px; border-radius: 99px; background: var(--pc-rose); }
@media (max-width: 639px) { .cp-pop-spine ul { gap: 6px 16px; } .cp-pop-spine li { gap: 16px; } }

/* Now playing: the dark deck, the same in every look but game's. */
.cp-pop-deck { border-radius: 24px; overflow: hidden; background: var(--pc-deck); color: var(--pc-band-ink); box-shadow: 0 30px 60px rgb(30 23 21 / .18); }
.cp-pop-deck-bar { display: flex; justify-content: space-between; gap: 16px; padding: 16px 24px; border-bottom: 1px solid var(--pc-band-line); font-family: var(--pc-mono); font-size: 12px; letter-spacing: .12em; text-transform: uppercase; color: var(--pc-band-muted); }
.cp-pop-live { display: inline-flex; align-items: center; gap: 8px; color: var(--pc-band-ink); }
.cp-pop-dot { width: 8px; height: 8px; border-radius: 99px; background: var(--pc-rose); }
.cp-pop-deck-in { display: grid; grid-template-columns: minmax(0, 1fr); gap: 32px 40px; padding: clamp(20px, 3.4vw, 40px); }
@media (min-width: 900px) { .cp-pop-deck-in { grid-template-columns: minmax(0, 1fr) minmax(0, 1.7fr); } }
.cp-pop-deck-h { font-family: var(--pc-slab); font-weight: 400; font-size: clamp(32px, 3.2vw, 44px); line-height: 1; color: var(--pc-band-ink); }
.cp-pop-deck-lead { margin-top: 18px; font-size: 16px; line-height: 1.6; color: var(--pc-band-body); text-wrap: pretty; }
.cp-pop-sides { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 22px; }
.cp-pop-side { display: inline-flex; align-items: center; gap: 10px; min-height: 46px; padding: 6px 18px 6px 6px; border-radius: 99px; border: 1.5px solid #5a4c50; background: transparent; color: var(--pc-band-ink); font: 600 15px/1.2 var(--font-sans); white-space: nowrap; cursor: pointer; }
.cp-pop-side:hover { border-color: var(--pc-band-ink); }
.cp-pop-side-b:hover, .cp-pop-side-b[aria-pressed="true"] { border-color: var(--pc-rose); }
.cp-pop-icon { position: relative; flex: none; width: 32px; height: 32px; border-radius: 99px; background: #cfc6c8; }
.cp-pop-side-b .cp-pop-icon { background: var(--pc-rose); }
.cp-pop-icon::before { content: ""; position: absolute; inset: 0; margin: auto; width: 11px; height: 12px; translate: 1px 0; background: var(--pc-deck); clip-path: polygon(0 0, 100% 50%, 0 100%); }
[aria-pressed="true"] > .cp-pop-icon::before { width: 10px; height: 10px; translate: 0; clip-path: none; }
.cp-pop-say { margin-top: 16px; min-height: 1.5em; font-size: 14px; font-weight: 600; color: var(--pc-gold); }
.cp-pop-roll { padding: 20px 20px 14px; border-radius: 16px; background: var(--pc-well); }
.cp-pop-roll-stage { position: relative; height: clamp(140px, 18vw, 200px); }
.cp-pop-roll-stage svg { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; }
.cp-pop-rule { stroke: #2a2124; stroke-width: 1; vector-effect: non-scaling-stroke; }
.cp-pop-bar { fill: var(--pc-bar); transition: fill .15s; }
.cp-pop-bar[data-on] { fill: #7a6670; }
.cp-pop-trace { fill: none; stroke: var(--pc-rose); stroke-width: 3; stroke-linecap: round; stroke-linejoin: round; vector-effect: non-scaling-stroke; }
.cp-pop-playhead { position: absolute; top: -6px; bottom: -6px; left: var(--x, 0%); width: 2px; margin-left: -1px; border-radius: 1px; background: var(--pc-gold); }
.cp-pop-words { position: relative; height: 46px; margin-top: 10px; }
.cp-pop-words span { position: absolute; top: 0; left: var(--at); font-size: 15px; font-weight: 700; white-space: nowrap; color: #a59a9d; transition: color .15s; }
.cp-pop-words .cp-pop-word-low { top: 22px; }
.cp-pop-words span[data-on] { color: #fff; }
@media (max-width: 639px) {
    .cp-pop-roll { padding: 16px 14px 12px; }
    .cp-pop-words { height: 40px; }
    .cp-pop-words span { font-size: 13px; }
    .cp-pop-words .cp-pop-word-low { top: 19px; }
}
.cp-pop-pick { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 22px; padding: 0; border: 0; }
.cp-pop-pick legend { float: left; width: 100%; margin-bottom: 4px; font-family: var(--pc-mono); font-size: 12px; letter-spacing: .12em; text-transform: uppercase; color: var(--pc-band-muted); }
.cp-pop-move-chip { display: inline-flex; align-items: center; gap: 8px; min-height: 44px; padding: 0 14px 0 12px; border-radius: 99px; border: 1.5px solid #4a3e43; background: transparent; color: var(--pc-band-body); font: 600 14px/1.2 var(--font-sans); white-space: nowrap; cursor: pointer; }
.cp-pop-move-chip[aria-pressed="true"] { border-color: var(--pc-rose); background: #3a1d2a; color: #ffe6ef; }
.cp-pop-tick { position: relative; flex: none; width: 16px; height: 16px; border-radius: 4px; border: 1.5px solid #a59a9d; }
[aria-pressed="true"] > .cp-pop-tick { border-color: var(--pc-rose); background: var(--pc-rose); }
[aria-pressed="true"] > .cp-pop-tick::after { content: ""; position: absolute; left: 4px; top: 1px; width: 4px; height: 8px; border: solid var(--pc-deck); border-width: 0 2px 2px 0; rotate: 45deg; }
.cp-pop-count { margin-top: 14px; font-size: 14px; color: var(--pc-band-body); }
.cp-pop-note { margin-top: 6px; font-size: 13.5px; line-height: 1.5; color: var(--pc-band-muted); }
/* By the end, you can: two ruled columns under the deck. */
.cp-pop-outcomes-h { margin-top: clamp(48px, 6vw, 64px); }
