.cp-pop-mini { width: 26px; height: 26px; border-radius: 50%; background: radial-gradient(circle, var(--pc-mag-soft) 0 12%, var(--pc-centre) 14% 40%, var(--pc-vinyl) 42%); }
.cp-pop-move-art .cp-pop-mini { position: absolute; top: 12px; right: 14px; }
