.cp-pop-hear { display: inline-flex; align-self: flex-start; align-items: center; gap: 8px; min-height: 44px; margin-top: 10px; padding: 4px 16px 4px 5px; border-radius: 99px; border: 1.5px solid var(--pc-mag-text); background: transparent; color: var(--pc-mag-text); font: 700 14px/1.2 var(--font-sans); white-space: nowrap; cursor: pointer; }
.cp-pop-hear .cp-pop-icon { width: 30px; height: 30px; background: var(--pc-mag); }
