.cp-pop-hear:hover, .cp-pop-hear[aria-pressed="true"] { background: var(--pc-mag); border-color: var(--pc-mag); color: var(--pc-mag-ink); }
.cp-pop-hear:hover .cp-pop-icon, .cp-pop-hear[aria-pressed="true"] .cp-pop-icon { background: var(--pc-mag-ink); }
.cp-pop-hear:hover .cp-pop-icon::before, .cp-pop-hear[aria-pressed="true"] .cp-pop-icon::before { background: var(--pc-mag); }

/* The record's black bands: Small and light, and what the app listens for. */
.cp-pop-band { margin-top: var(--k-sec); padding-block: clamp(64px, 8vw, 96px); background: var(--pc-band); color: var(--pc-band-ink); }
.cp-pop-band .cp-pop-intro { color: var(--pc-band-body); }
.cp-pop-band-in { display: grid; grid-template-columns: minmax(0, 1fr); gap: 48px 56px; align-items: center; }
@media (min-width: 900px) { .cp-pop-band-in { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); } }
.cp-pop-sticker { display: block; width: 168px; height: 168px; margin-top: 28px; rotate: -10deg; }
.cp-pop-sticker-disc { fill: var(--pc-gold); }
.cp-pop-sticker-ring { fill: none; stroke: var(--pc-band); stroke-width: 1.5; }
.cp-pop-sticker-arc { font-family: var(--pc-mono); font-size: 13px; letter-spacing: 2.6px; text-transform: uppercase; fill: #171211; }
