.cp-pop-care-list li { display: flex; gap: 20px; padding-block: 22px; border-top: 1px solid var(--pc-band-line); }
.cp-pop-care-tag { flex: none; min-width: 76px; padding-top: 3px; font-family: var(--pc-mono); font-size: 13px; letter-spacing: .08em; text-transform: uppercase; color: var(--pc-gold); }
