/* The tracklist: four sides, each a card with its record label letter and its tracks. */
.cp-pop-discs { display: grid; grid-template-columns: minmax(0, 1fr); gap: 20px; margin-top: 40px; }
@media (min-width: 600px) { .cp-pop-discs { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (min-width: 1100px) { .cp-pop-discs { grid-template-columns: repeat(4, minmax(0, 1fr)); } }
.cp-pop-disc { --side: var(--pc-side-1); --side-ink: var(--pc-side-1-ink); --side-text: var(--pc-side-1-text);
    display: flex; flex-direction: column; gap: 14px; padding: 24px; border-radius: 18px; border: 1px solid var(--k-line); background: var(--pc-card); }
