/* The bonus track: the one magenta card. */
.cp-pop-try { position: relative; overflow: hidden; display: grid; grid-template-columns: minmax(0, 1fr); gap: 28px; padding: clamp(28px, 5vw, 56px); border-radius: 24px; background: var(--pc-mag); color: var(--pc-mag-ink); }
