.cp-pop-take { display: grid; grid-template-columns: minmax(0, 1fr); gap: 20px; margin: 0; padding: 24px; border-radius: 20px; border: 1px solid var(--pc-band-line); background: color-mix(in srgb, var(--pc-band) 93%, #fff); }
.cp-pop-take-head { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 6px 12px; font-family: var(--pc-mono); font-size: 12px; letter-spacing: .1em; text-transform: uppercase; color: var(--pc-band-muted); }
.cp-pop-sample { margin-right: 8px; padding: 2px 8px; border-radius: 99px; background: var(--pc-gold); color: #171211; font-weight: 500; }
.cp-pop-take-art { display: block; width: 100%; height: auto; }
.cp-pop-take-bar { fill: none; stroke: var(--pc-bar); stroke-width: 8; stroke-linecap: round; }
