@media (max-width: 479px) { .cp-pop .cp-pop-close .cp-join-btns { flex-direction: column; } .cp-pop .cp-pop-close .cp-join-btns .btn-lg { justify-content: center; } }
.cp-pop .cp-pop-close .cp-related { display: grid; gap: 0; margin-top: 14px; border-top: 1px solid var(--k-line-strong); }
.cp-pop .cp-pop-close .cp-related a { display: flex; gap: 16px; min-height: 64px; padding: 0; border-radius: 0; border-bottom: 1px solid var(--k-line-strong); background: none; font-size: 18px; font-weight: 700; }
