:root[data-skin="game"] body.s-arcade .cp-pop .cp-pop-sticker-word { font-family: var(--a-display); font-size: 18px; text-transform: uppercase; font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade .cp-pop .cp-pop-sticker-arc { font-size: 9px; letter-spacing: 1.4px; font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade .cp-pop :is(.cp-pop-deck, .cp-pop-move, .cp-pop-disc, .cp-pop-liner, .cp-pop-try, .cp-pop-take, .cp-pop-roll, .cp-pop-sleeve, .cp-pop-side, .cp-pop-move-chip, .cp-pop-hear, .cp-pop-chip b, .cp-pop-start, .cp-pop-sample) { border-radius: 0; }
:root[data-skin="game"] body.s-arcade .cp-pop :is(.cp-pop-move, .cp-pop-disc, .cp-pop-liner) { border: 2px solid var(--a-line-2); box-shadow: 4px 4px 0 var(--arc-shadow-c, #05030d); }
:root[data-skin="game"] body.s-arcade .cp-pop :is(.cp-pop-deck, .cp-pop-take) { border: 2px solid var(--a-pink); box-shadow: 6px 6px 0 var(--a-cyan); }
:root[data-skin="game"] body.s-arcade .cp-pop .cp-pop-try { box-shadow: 6px 6px 0 var(--a-cyan); }
:root[data-skin="game"] body.s-arcade .cp-pop .cp-pop-sleeve { box-shadow: 6px 6px 0 var(--a-cyan); }
:root[data-skin="game"] body.s-arcade .cp-pop .cp-pop-record { box-shadow: 0 0 0 2px var(--a-pink), 0 0 30px -6px var(--a-pink); }
:root[data-skin="game"] body.s-arcade .cp-pop :is(.cp-pop-trace, .cp-pop-move-line) { filter: drop-shadow(0 0 4px var(--pc-rose)); }
:root[data-skin="game"] body.s-arcade .cp-pop .cp-pop-close .cp-related a { border-radius: 0; }
/* A button's label never wraps: the pixel face is wide, so a narrow phone sets the page's big buttons a step smaller. */
@media (max-width: 419px) { :root[data-skin="game"] body.s-arcade .cp-pop :is(.cp-pop-btns, .cp-join-btns) .btn-lg { padding-inline: 12px; font-size: 11.5px; } }

/* The course pages' featured demo deck (first Pop's Plain to styled, then Improvising's A part above): a dark deck under the hero in every look (the record's own
   black), the line's notes as bars on four staff lines, the guide's trace drawn over them in the
   page's rose, each word lit as it's sung, and the moves as chips. Sounds: js/public/pop-and-country.js. */
.cp-dk-demosec { position: relative; z-index: 1; margin-top: clamp(28px, 4vw, 44px); }
.cp-dk-demo { --pd-bg: #1a1420; --pd-edge: #3a2f44; --pd-ink: #fbf3f6; --pd-body: #e2d6de; --pd-muted: #c3b5bf; --pd-rose: #ff7aa8; --pd-gold: #ffc66b; --pd-bar: #4a3d55; --pd-staff: #34293e;
    border-radius: 24px; border: 1px solid var(--pd-edge); background: var(--pd-bg); color: var(--pd-ink); box-shadow: 0 24px 60px -30px rgb(0 0 0 / .55); overflow: hidden; }
:root[data-skin="game"] .cp-dk-demo { --pd-bg: #0d0818; --pd-edge: #ff5fd266; --pd-rose: #ff5fd2; --pd-gold: #ffd84a; --pd-bar: #2b2240; --pd-staff: #221a36; box-shadow: 0 0 40px -16px #ff5fd2; }
.cp-dk-demo-bar { display: flex; justify-content: space-between; gap: 12px; padding: 12px 20px; border-bottom: 1px solid var(--pd-edge); font-size: 12px; font-weight: 800; letter-spacing: .16em; text-transform: uppercase; color: var(--pd-muted); }
.cp-dk-live { display: inline-flex; align-items: center; gap: 8px; color: var(--pd-ink); }
