@media (min-width: 900px) { .cp-dk-demo-in { grid-template-columns: minmax(0, 5fr) minmax(0, 7fr); align-items: start; } }
.cp-dk-demo-h { font-size: clamp(30px, 4vw, 44px); font-weight: 900; line-height: 1; letter-spacing: -0.03em; color: var(--pd-ink); }
.cp-dk-demo-lead { margin-top: 14px; font-size: 16px; line-height: 1.6; color: var(--pd-body); text-wrap: pretty; }
.cp-dk-btns { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 20px; }
.cp-dk-play, .cp-dk-hear { display: inline-flex; align-items: center; gap: 10px; min-height: 48px; padding: 0 18px 0 6px; border-radius: 99px; border: 1.5px solid currentColor; background: transparent; color: inherit; font: 700 15px/1.2 Figtree, system-ui, sans-serif; cursor: pointer; text-align: start; }
