/* Find your comfortable note (js/public/demos/comfortable-note.js): the note found, big, on a ladder of
   two octaves from C3 to C5, the Listen button (mic only on a tap), the mic picker, and the privacy line. */
/* Find your comfortable note (js/public/demos/comfortable-note.js): the app's own card (js/public/voice-capture.js),
   on the page like the mixer demos; the still frame is only its outline and first words. */
.s-capture { display: grid; gap: 12px; width: min(100%, 28rem); margin-inline: auto; }
.s-capture-still { display: grid; justify-items: center; gap: 6px; padding: 20px 20px 28px; border: 1px solid var(--color-line); border-radius: 24px; background: var(--color-panel); text-align: center; }
.s-capture-still-h { margin-top: 10px; font-size: 18px; font-weight: 700; color: var(--color-cream); }
.s-capture-still-sub { font-size: 14px; color: var(--color-muted); }
.s-cb-say.s-capture-say { min-height: 0; color: var(--color-cream); text-align: center; }
.s-capture-say:empty { display: none; }
.s-note-private { display: flex; align-items: flex-start; justify-content: center; gap: 8px; font-size: 13.5px; line-height: 1.5; color: var(--color-muted); }
.s-note-private svg { flex: none; margin-top: 2px; }
:root[data-skin="game"] body.s-arcade .s-capture-still { border-radius: 0; }
/* Before the start, a scrim over the whole stage so the start reads as a cover, not a stray pill. */
.s-demo:not([data-state="live"]) .s-demo-stage::after { content: ""; position: absolute; inset: 0; z-index: 1; border-radius: inherit; background: rgb(12 9 16 / .38); pointer-events: none; }
.s-demo-start { z-index: 2; }
:root[data-skin="game"] body.s-arcade .s-demo-start { color: #1a1400; text-transform: uppercase; }
.s-demo-fit .s-mixer { margin-top: 0; }
.s-demo-fit .s-demo-stage { border-radius: 24px; }
@media (min-width: 900px) { .s-demo-fit .s-demo-stage { border-radius: 36px; } }
:root[data-skin="game"] body.s-arcade .s-demo-fit .s-demo-stage { border-radius: 0; }
/* One caption per demo: the deck's and the mixer's own fine print gives way to the slot's caption. */
.s-demo .cp-dk-note { display: none; }
/* Name that leap's still frame shows a leap, 1 up to 4, before anything plays. */
.s-demo:not([data-state="live"]) .cp-ear-rung:is([data-ear-rung="1"], [data-ear-rung="4"]) { fill: var(--pd-gold); }
/* The game skin's arcade frame for what sits in the slot: square, a bright frame, a hard shadow. */
:root[data-skin="game"] body.s-arcade .s-demo :is(.cp-dk-demo, .s-mixer) { border-radius: 0; border: 2px solid #3be7ff; box-shadow: 6px 6px 0 #ff5fd2; }
:root[data-skin="game"] body.s-arcade .s-demo :is(.cp-dk-play, .cp-dk-hear, .cp-dk-chip, .cp-dk-roll) { border-radius: 0; }
/* The deck as a screen (Improvising, Hillel 2026-11-01): within the content width, a 16:9 stage of the
   lane and the words with one big play in its middle (it steps to the corner while it plays), and the
   caption and the other ways to play underneath. */
.cp-dk-screen { max-width: 960px; margin-inline: auto; }
.cp-dk-stage { position: relative; margin: clamp(12px, 2.4vw, 22px) clamp(12px, 2.4vw, 22px) 0; }
.cp-dk-stage .cp-dk-roll { display: flex; flex-direction: column; justify-content: center; }
@media (min-width: 640px) {
    .cp-dk-stage { aspect-ratio: 16 / 9; }
    .cp-dk-stage .cp-dk-roll { height: 100%; }
    .cp-dk-stage .cp-dk-roll svg { flex: 1; height: auto; min-height: 0; }
}
.cp-dk-big { position: absolute; inset: 50% auto auto 50%; translate: -50% -50%; display: inline-flex; align-items: center; gap: 12px; min-height: 64px; padding: 0 26px 0 10px; border-radius: 99px; border: 0; background: var(--pd-gold); color: #1a1420; font: 800 18px/1.1 Figtree, system-ui, sans-serif; box-shadow: 0 18px 40px -14px rgb(0 0 0 / .7); cursor: pointer; transition: inset .25s, translate .25s, min-height .25s; }
.cp-dk-big-icon { display: grid; place-items: center; width: 46px; height: 46px; border-radius: 99px; background: #1a1420; }
.cp-dk-big-icon::before { content: ""; margin-left: 4px; border-style: solid; border-width: 8px 0 8px 13px; border-color: transparent transparent transparent var(--pd-gold); }
.cp-dk-big[aria-pressed="true"] { inset: auto 12px 12px auto; translate: 0 0; min-height: 48px; font-size: 15px; }
.cp-dk-big[aria-pressed="true"] .cp-dk-big-icon { width: 32px; height: 32px; }
.cp-dk-big[aria-pressed="true"] .cp-dk-big-icon::before { margin: 0; width: 11px; height: 11px; border: 0; background: var(--pd-gold); }
.cp-dk-demo .cp-dk-big:focus-visible { outline: 3px solid #fff; outline-offset: 3px; }
.cp-dk-caption { display: grid; gap: 18px 40px; padding: clamp(18px, 3vw, 28px) clamp(18px, 3vw, 32px) clamp(20px, 3vw, 30px); }
@media (min-width: 900px) { .cp-dk-caption { grid-template-columns: minmax(0, 5fr) minmax(0, 6fr); } }
.cp-dk-caption .cp-dk-btns { margin-top: 0; }
:root[data-skin="game"] body.s-arcade .cp-dk-big { font: 400 12px/1.4 var(--a-hud); }
@media (max-width: 639px) { .cp-dk-big { position: static; translate: none; margin: 14px 0 0; width: 100%; justify-content: center; } .cp-dk-big[aria-pressed="true"] { inset: auto; } }
@media (prefers-reduced-motion: reduce) { .cp-dk-big { transition: none; } }
/* The deck's sliders (Vibrato's own wave), and its still centre line, the note the wave goes round. */
.cp-dk-centre { stroke: var(--pd-muted); stroke-dasharray: 6 6; }
.cp-dk-sliders { display: grid; gap: 14px; margin-top: 18px; }
@media (min-width: 600px) { .cp-dk-sliders { grid-template-columns: 1fr 1fr; } }
.cp-dk-slider { display: grid; gap: 8px; font-size: 14px; font-weight: 700; color: var(--pd-body); }
.cp-dk-slider output { margin-inline-start: 6px; color: var(--pd-gold); }
.cp-dk-slider input { width: 100%; min-height: 32px; accent-color: var(--pd-rose); }
.cp-dk-demo .cp-dk-slider input:focus-visible { outline: 3px solid var(--pd-gold); outline-offset: 3px; }
/* Ear training's Name that leap: a ladder of eight scale steps, the leap's two notes lit and joined
   once it's named, and the answers as chips that turn green or rose. */
:is(.cp-ear, .s-demo-leap) .cp-dk-demo { --pd-rose: #5fc7c7; --pd-gold: #ffc66b; }
:root[data-skin="game"] :is(.cp-ear, .s-demo-leap) .cp-dk-demo { --pd-rose: #a3e635; --pd-edge: #a3e63566; box-shadow: 0 0 40px -16px #a3e635; }
.cp-ear-roll { position: relative; display: grid; justify-items: center; }
.cp-ear-roll svg { width: min(100%, 260px); height: auto; }
.cp-ear-round { justify-self: start; font-size: 12px; font-weight: 800; letter-spacing: .16em; text-transform: uppercase; color: var(--pd-muted); }
.cp-ear-n { font: 700 14px/1 Figtree, system-ui, sans-serif; fill: var(--pd-muted); }
.cp-ear-rung { fill: var(--pd-bar); }
.cp-ear-rung[data-on] { fill: var(--pd-gold); }
.cp-ear-pick { min-width: 88px; justify-content: center; font-weight: 800; }
.cp-ear-pick:disabled { cursor: default; }
.cp-ear-pick[data-right] { border-color: #6fdc8c; background: color-mix(in srgb, #6fdc8c 18%, transparent); color: var(--pd-ink); }
.cp-ear-pick[data-wrong] { border-color: #ff8f8f; background: color-mix(in srgb, #ff8f8f 16%, transparent); color: var(--pd-ink); }
.cp-ear-next { border-color: var(--pd-gold); color: var(--pd-ink); font-weight: 800; }
.cp-ear-next[hidden] { display: none; }
.cp-dk-demo .cp-dk-hear { color: var(--pd-body); }
.cp-dk-demo .cp-dk-pick .cp-dk-hear { min-height: 44px; font-size: 14px; }

/* Sight-singing (site/courses/sight-singing): Hillel's design (2026-11-18, ~/Code/course-designs/sight-singing), the music
   itself as the design. The page climbs a scale, each section labelled with its note (do to ti, the close the high do), on
   a warm paper with ink, Guido of Arezzo's red F line and yellow C line, a blue for do, and red ink for the margin notes
   (--ss-red, AA on every ground it sits on, in calm light and dark and in game mode). The design's Newsreader is the
   system's serif here (no font loaded). The sol-fa ladder at its real semitone heights; the strip of stave under the hero;
   Find do as a page of sheet music, each note a button drawn in the song pages' engraved outlines, its stave lines drawn
   here so the notes space out with the width (on a phone the line takes two systems, the second with its own clef); the
   story as six bars between barlines; the outcomes rising do to so with the half step at fa; the units as lines of bars
   with shape-note heads; the hymn board. Every lesson is linked in the bars, so the course's own list after the page is
   left out (@section lesson-pages-inline). Game skin: the arcade's night, pixel headings, square frames with hard
   shadows, and PRESS START on the demo; the music keeps its ink in the arcade's colours. Sounds: js/public/sight-singing.js. */
:is(.cp-ss, body[data-course="sight-singing"]) {
    --ss-serif: ui-serif, "Iowan Old Style", "Palatino Linotype", Palatino, Georgia, serif;
    --ss-paper: #f7f3ea; --ss-sheet: #fffdf8; --ss-band: #efe8da; --ss-ink: #1d1a16; --ss-body: #3d372f; --ss-muted: #5e574d;
    --ss-rule: #d9d1c2; --ss-rule-2: #e3dccf; --ss-blue: #3357b1; --ss-blue-ink: #fff; --ss-red: #a8321f; --ss-yellow: #e2a91e; --ss-gold: #b07d00;
    --ss-board: #2a241f; --ss-board-ink: #f7f3ea; --ss-board-muted: #c9bfae; --ss-board-rule: #4a423b;
    --ss-shadow: 0 30px 60px -30px rgb(60 45 20 / .25);
}
:root:not([data-theme$="-light"]) :is(.cp-ss, body[data-course="sight-singing"]) {
    --ss-paper: #1a1814; --ss-sheet: #221f1a; --ss-band: #26221c; --ss-ink: #f2ede4; --ss-body: #d9d2c5; --ss-muted: #b9b0a1;
    --ss-rule: #3a352d; --ss-rule-2: #332e27; --ss-blue: #9fb3ff; --ss-blue-ink: #10142a; --ss-red: #ff8a7a; --ss-yellow: #f2c14e; --ss-gold: #f2c14e;
    --ss-board: #0f0d0b; --ss-board-ink: #f2ede4; --ss-board-muted: #c9bfae; --ss-board-rule: #3a352d;
    --ss-shadow: 0 30px 60px -30px rgb(0 0 0 / .6);
}
:root[data-skin="game"] :is(.cp-ss, body[data-course="sight-singing"]) {
    --ss-serif: inherit;
    --ss-paper: var(--a-bg); --ss-sheet: var(--a-panel); --ss-band: var(--a-bg-2); --ss-ink: var(--a-ink); --ss-body: var(--a-ink); --ss-muted: var(--a-muted);
    --ss-rule: var(--a-line); --ss-rule-2: var(--a-line); --ss-blue: var(--a-cyan); --ss-blue-ink: #04121a; --ss-red: var(--a-red); --ss-yellow: var(--a-yellow); --ss-gold: var(--a-yellow);
    --ss-board: var(--a-raised); --ss-board-ink: var(--a-ink); --ss-board-muted: var(--a-muted); --ss-board-rule: var(--a-line-2);
    --ss-shadow: 6px 6px 0 var(--arc-shadow-c, #05030d);
}
:root[data-skin="game"][data-theme$="-light"] :is(.cp-ss, body[data-course="sight-singing"]) { --ss-blue: #006b85; --ss-blue-ink: #fff; --ss-gold: #8a5a00; --ss-yellow: #b88400; --ss-board: #1c1830; --ss-board-ink: #f7f4ff; --ss-board-muted: #cfc8ff; --ss-board-rule: #3a3555; }
body[data-course="sight-singing"] { background: var(--ss-paper); }
.cp-ss { --cp-a: var(--ss-blue); --cp-a-ink: var(--ss-blue-ink); --cp-a-text: var(--ss-blue); --cp-line: var(--ss-rule);
    --selected: var(--ss-blue); --selected-ink: var(--ss-blue-ink);
    background: var(--ss-paper); color: var(--ss-ink); }
.cp-ss :is(summary, a, button):focus-visible { outline: 3px solid var(--ss-blue); outline-offset: 3px; }

/* Type: the serif, light, for headings, sol-fa names and numbers; small tracked labels. */
.cp-ss-sec { padding-top: clamp(80px, 10vw, 120px); }
.cp-ss-step { display: flex; flex-wrap: wrap; align-items: center; gap: 4px 12px; font-size: 12px; font-weight: 600; letter-spacing: .16em; text-transform: uppercase; color: var(--ss-muted); }
.cp-ss-step a { color: inherit; text-decoration: underline 1px; text-underline-offset: 3px; padding-block: 12px; margin-block: -12px; }
.cp-ss-step a:hover { color: var(--ss-blue); }
.cp-ss-sol { font-family: var(--ss-serif); font-style: italic; font-size: 22px; font-weight: 400; letter-spacing: 0; text-transform: none; line-height: 1; color: var(--ss-blue); }
.cp-ss-label { font-size: 12px; font-weight: 600; letter-spacing: .16em; text-transform: uppercase; color: var(--ss-muted); }
.cp-ss-h2, .cp-ss-hero h1, .cp-ss-join { font-family: var(--ss-serif); font-weight: 300; color: var(--ss-ink); text-wrap: balance; }
.cp-ss-h2 { margin-top: 12px; font-size: clamp(40px, 5.5vw, 72px); line-height: 1.02; letter-spacing: -0.02em; max-width: 16ch; }
.cp-ss-h2-wide { max-width: 22ch; }
:is(.cp-ss-h2, .cp-ss-hero h1, .cp-ss-join) em { font-style: italic; }
.cp-ss-hero h1 em, .cp-ss-join em { color: var(--ss-blue); }
.cp-ss-lead { margin-top: 28px; max-width: 560px; font-size: clamp(17px, 1.6vw, 19px); line-height: 1.6; color: var(--ss-body); text-wrap: pretty; }
.cp-ss-head-split { display: flex; flex-wrap: wrap; align-items: end; justify-content: space-between; gap: 20px 40px; }
.cp-ss-aside { max-width: 460px; font-size: 16px; line-height: 1.6; color: var(--ss-body); text-wrap: pretty; }
.cp-ss-sub { max-width: 340px; font-size: 15px; line-height: 1.6; color: var(--ss-muted); }
.cp-ss-fine, .cp-ss-quiet { margin-top: 6px; font-size: 13.5px; line-height: 1.55; color: var(--ss-muted); }
.cp-ss-btns { display: flex; flex-wrap: wrap; gap: 12px; margin-top: 32px; }
.cp-ss-btns > * { white-space: nowrap; }
@media (max-width: 639px) {
    .cp-ss-btns { flex-direction: column; align-items: stretch; }
    .cp-ss-btns > :is(a, button) { justify-content: center; width: 100%; }
}

/* do: the hero, the words beside the sol-fa ladder, then the strip of stave. */
.cp-ss-hero { padding-top: 32px; }
.cp-ss-hero-grid { display: grid; grid-template-columns: minmax(0, 1fr); gap: 48px 56px; align-items: center; margin-top: 28px; }
@media (min-width: 900px) { .cp-ss-hero-grid { grid-template-columns: minmax(0, 1.08fr) minmax(0, 1fr); } }
.cp-ss-hero h1 { margin-top: 18px; font-size: clamp(60px, 9vw, 124px); line-height: .92; letter-spacing: -0.03em; }
.cp-ss-facts { display: flex; flex-wrap: wrap; gap: 6px 22px; margin-top: 24px; font-size: 14px; color: var(--ss-muted); }
.cp-ss-facts li { display: flex; align-items: center; gap: 8px; }
.cp-ss-facts li::before { content: ""; width: 5px; height: 5px; border-radius: 99px; background: currentColor; opacity: .7; }

.cp-ss-ladder { --sem: 40px; margin: 0; padding: 28px 28px 22px; border: 1px solid var(--ss-rule-2); border-radius: 4px; background: var(--ss-sheet); box-shadow: var(--ss-shadow); }
@media (max-width: 899px) { .cp-ss-ladder { --sem: 44px; } }
.cp-ss-ladder-head { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: baseline; gap: 4px 16px; font-size: 14px; color: var(--ss-muted); }
.cp-ss-rungs { position: relative; height: calc(12 * var(--sem)); margin: calc(var(--sem) / 2 + 8px) 44px calc(var(--sem) / 2 + 8px) 64px; border-inline: 2px solid var(--ss-ink); }
.cp-ss-rung { position: absolute; inset-inline: -64px 0; top: calc(var(--at) * 100%); translate: 0 -50%; display: flex; align-items: center; gap: 14px; height: var(--sem); padding: 0; border: 0; background: none; color: var(--ss-ink); cursor: pointer; font: inherit; }
.cp-ss-rung-name { flex: none; width: 46px; text-align: end; font-family: var(--ss-serif); font-style: italic; font-size: 20px; line-height: 1; }
.cp-ss-rung-line { flex: 1; height: 1px; background: currentColor; }
.cp-ss-rung-home { color: var(--ss-blue); }
.cp-ss-rung-home .cp-ss-rung-name { font-size: 22px; font-weight: 600; }
.cp-ss-rung-home .cp-ss-rung-line { height: 3px; }
.cp-ss-rung:hover .cp-ss-rung-line { height: 3px; }
.cp-ss-rung[aria-pressed="true"] .cp-ss-rung-name { font-weight: 700; text-decoration: underline 2px; text-underline-offset: 4px; }
.cp-ss-half { position: absolute; inset-inline-end: -30px; top: calc(var(--to) * 100%); width: 10px; height: calc((var(--from) - var(--to)) * 100%); border: 2px solid var(--ss-red); border-inline-start: 0; pointer-events: none; }
.cp-ss-dot { position: absolute; inset-inline-start: 50%; top: calc(var(--dot, 1) * 100%); width: 16px; height: 16px; margin: -8px 0 0 -8px; border-radius: 99px; background: var(--ss-yellow); box-shadow: 0 0 0 6px color-mix(in srgb, var(--ss-yellow) 28%, transparent); pointer-events: none; transition: top .25s ease; }
.cp-ss-ladder:not([data-rung]) .cp-ss-dot { display: none; }
@media (prefers-reduced-motion: reduce) { .cp-ss-dot { transition: none; } }
.cp-ss-ladder figcaption { padding-top: 16px; border-top: 1px solid var(--ss-rule-2); font-size: 13px; line-height: 1.55; color: var(--ss-muted); }
.cp-ss-legend { display: flex; flex-wrap: wrap; gap: 6px 20px; margin-bottom: 8px; color: var(--ss-ink); }
.cp-ss-legend li { display: flex; align-items: center; gap: 8px; }
.cp-ss-key-home { width: 20px; height: 3px; background: var(--ss-blue); }
.cp-ss-key-half { width: 8px; height: 12px; border: 2px solid var(--ss-red); border-inline-start: 0; }

.cp-ss-strip { margin-top: 72px; background: repeating-linear-gradient(to bottom, var(--ss-rule) 0 1px, transparent 1px 12px) 0 20px / 100% 49px no-repeat; }
.cp-ss-strip-svg { display: block; overflow: visible; }
.cp-ss-ink { fill: var(--ss-ink); }
.cp-ss-blue { fill: var(--ss-blue); }
.cp-ss-faint { fill: var(--ss-rule); }
.cp-ss-strip-half line { stroke: var(--ss-red); stroke-width: 1.5; }

/* re: Find do, a page of sheet music. */
.cp-ss-demosec .cp-ss-head-split { margin-bottom: 28px; }
.cp-ss-demo { --u: 1px; border: 1px solid var(--ss-rule); border-radius: 4px; background: var(--ss-sheet); box-shadow: var(--ss-shadow); }
@media (max-width: 639px) { .cp-ss-demo { --u: .82px; } }
.cp-ss-demo-bar { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: center; gap: 6px 16px; padding: 16px 28px; border-bottom: 1px solid var(--ss-rule-2); font-size: 12px; font-weight: 600; letter-spacing: .16em; text-transform: uppercase; }
.cp-ss-live { display: flex; align-items: center; gap: 8px; }
.cp-ss-live i { width: 8px; height: 8px; border-radius: 99px; background: var(--ss-red); }
.cp-ss-keyname { color: var(--ss-muted); white-space: nowrap; }
.cp-ss-demo [data-for] { display: none; }
.cp-ss-demo[data-key="c"] [data-for="c"], .cp-ss-demo[data-key="d"] [data-for="d"], .cp-ss-demo[data-key="f"] [data-for="f"], .cp-ss-demo[data-key="g"] [data-for="g"] { display: inline; }
.cp-ss-sheet { padding: 28px 28px 12px; }
.cp-ss-stave { display: flex; flex-wrap: wrap; row-gap: 20px; }
/* The stave's five lines, the top one (F) Guido's red, drawn behind the clef and each note; a staff space is 16u. */
.cp-ss-clef, .cp-ss-note {
    background:
        linear-gradient(var(--ss-red), var(--ss-red)) 0 calc(36 * var(--u) - 1.2px) / 100% 2.4px no-repeat,
        repeating-linear-gradient(to bottom, var(--ss-ink) 0 1.2px, transparent 1.2px calc(16 * var(--u))) 0 calc(36 * var(--u) - .6px) / 100% calc(64 * var(--u) + 1.2px) no-repeat;
}
.cp-ss-clef { flex: none; width: calc(104 * var(--u)); }
.cp-ss-clef svg, .cp-ss-note svg { display: block; height: calc(140 * var(--u)); overflow: visible; }
.cp-ss-clef svg { width: 100%; }
.cp-ss-clef-again, .cp-ss-break { display: none; }
.cp-ss-note { position: relative; flex: 1 1 0; min-width: 44px; padding: 0 0 6px; border: 0; color: var(--ss-ink); cursor: pointer; font: inherit; }
.cp-ss-note:last-child::after { content: ""; position: absolute; inset-inline-end: 0; top: calc(36 * var(--u) - .6px); width: 9px; height: calc(64 * var(--u) + 1.2px); box-sizing: border-box; border-inline: 1.5px solid var(--ss-ink); border-inline-end-width: 5px; }
.cp-ss-note svg { width: calc(68 * var(--u)); margin-inline: auto; }
.cp-ss-head, .cp-ss-stem { fill: var(--ss-ink); }
.cp-ss-c-line { fill: var(--ss-yellow); }
.cp-ss-ring { fill: none; stroke: none; stroke-width: 2.5; }
.cp-ss-name { display: block; min-height: 32px; padding-top: 4px; font-family: var(--ss-serif); font-style: italic; font-size: 24px; line-height: 1.1; color: var(--ss-ink); }
.cp-ss-note[data-degree="0"] .cp-ss-name { color: var(--ss-blue); }
.cp-ss-demo[data-names="off"] .cp-ss-name { visibility: hidden; }
.cp-ss-note:hover .cp-ss-head { fill: var(--ss-blue); }
.cp-ss-note[data-on] :is(.cp-ss-head, .cp-ss-stem) { fill: var(--ss-gold); }
.cp-ss-note[data-on] .cp-ss-ring { stroke: var(--ss-gold); }
.cp-ss-note[data-right] :is(.cp-ss-head, .cp-ss-stem) { fill: var(--ss-blue); }
.cp-ss-note[data-right] .cp-ss-ring { stroke: var(--ss-blue); }
.cp-ss-note[data-wrong] :is(.cp-ss-head, .cp-ss-stem) { fill: var(--ss-red); }
.cp-ss-note[data-wrong] .cp-ss-ring { stroke: var(--ss-red); stroke-dasharray: 4 4; }
.cp-ss-note:is([data-right], [data-wrong]) .cp-ss-name { visibility: visible; font-weight: 700; }
.cp-ss-note[data-wrong] .cp-ss-name { color: var(--ss-red); }
.cp-ss-note:focus-visible { outline-offset: -3px; }
/* A phone: the line in two systems, four notes and then three, the second with its clef and key signature again. */
@media (max-width: 639px) {
    .cp-ss-sheet { padding-inline: 16px; }
    .cp-ss-break { display: block; flex: 0 0 100%; height: 0; }
    .cp-ss-clef-again { display: block; }
}
.cp-ss-guido { display: flex; flex-wrap: wrap; align-items: center; gap: 6px 8px; margin-top: 10px; font-size: 13px; color: var(--ss-muted); }
.cp-ss-key-f, .cp-ss-key-c { width: 18px; height: 3px; background: var(--ss-red); }
.cp-ss-key-c { background: var(--ss-yellow); }
.cp-ss-demo-foot { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 16px 24px; padding: 20px 28px; border-top: 1px solid var(--ss-rule-2); background: var(--ss-paper); }
.cp-ss-controls { display: flex; flex-wrap: wrap; align-items: center; gap: 12px; }
.cp-ss-play, .cp-ss-newkey { display: inline-flex; align-items: center; gap: 10px; min-height: 48px; border-radius: 99px; font: 600 15px/1.2 Figtree, system-ui, sans-serif; white-space: nowrap; cursor: pointer; }
.cp-ss-play { padding: 8px 22px 8px 10px; border: 0; background: var(--ss-ink); color: var(--ss-paper); }
.cp-ss-play-icon { display: grid; place-items: center; width: 30px; height: 30px; border-radius: 99px; background: var(--ss-yellow); }
.cp-ss-play-icon::before { content: ""; margin-inline-start: 3px; border-block: 6px solid transparent; border-inline-start: 10px solid #1d1a16; }
.cp-ss-play[aria-pressed="true"] .cp-ss-play-icon::before { width: 10px; height: 10px; margin: 0; border: 0; border-radius: 2px; background: #1d1a16; }
.cp-ss-stop, .cp-ss-play[aria-pressed="true"] .cp-ss-go { display: none; }
.cp-ss-play[aria-pressed="true"] .cp-ss-stop { display: inline; }
.cp-ss-newkey { padding: 0 20px; border: 1.5px solid var(--ss-ink); background: var(--ss-sheet); color: var(--ss-ink); }
.cp-ss-newkey:hover, .cp-ss-play:hover { filter: brightness(1.08); }
.cp-ss-switch { --fill-3: var(--ss-rule); --fill-4: var(--ss-muted); --knob-off: var(--ss-muted);
    display: inline-flex; align-items: center; gap: 10px; min-height: 44px; padding: 0 4px; border: 0; background: none; color: var(--ss-ink); font: 500 14px/1.2 Figtree, system-ui, sans-serif; cursor: pointer; text-align: start; }
.cp-ss-said { max-width: 440px; }
.cp-ss-say { font-size: 15px; font-weight: 600; line-height: 1.45; }
@media (max-width: 639px) {
    .cp-ss-demo-bar, .cp-ss-demo-foot { padding-inline: 16px; }
    .cp-ss-controls > :is(.cp-ss-play, .cp-ss-newkey) { flex: 1 1 auto; justify-content: center; }
}

/* mi: the story, six bars between barlines. */
.cp-ss-story .cp-ss-head-split { margin-top: 12px; }
.cp-ss-story .cp-ss-h2 { margin-top: 0; max-width: 14ch; }
.cp-ss-bars { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 320px), 1fr)); margin-top: 48px; border-top: 1px solid var(--ss-ink); border-inline-end: 2px solid var(--ss-ink); }
.cp-ss-bar { padding: 24px 28px 32px; border-inline-start: 1px solid var(--ss-ink); border-bottom: 1px solid var(--ss-rule); }
.cp-ss-bar-top { display: flex; justify-content: space-between; align-items: baseline; gap: 12px; }
.cp-ss-year { font-family: var(--ss-serif); font-size: 40px; font-weight: 300; line-height: 1.1; color: var(--ss-blue); }
.cp-ss-bar-n { font-size: 12px; color: var(--ss-muted); white-space: nowrap; }
.cp-ss-bar h3 { margin-top: 0; font-size: 18px; font-weight: 600; }
.cp-ss-bar > p:last-child { margin-top: 8px; font-size: 15px; line-height: 1.6; color: var(--ss-body); text-wrap: pretty; }
.cp-ss-fig { display: flex; flex-wrap: wrap; align-content: center; align-items: center; min-height: 64px; margin: 18px 0; }
@media (max-width: 479px) { .cp-ss-bar { padding-inline: 20px; } }
.cp-ss-fig-guido { flex-direction: column; align-items: stretch; justify-content: center; gap: 12px; margin-inline-start: 16px; }
.cp-ss-gl { position: relative; height: 1px; background: var(--ss-ink); }
.cp-ss-gl b { position: absolute; inset-inline-start: -16px; top: -9px; font-size: 12px; font-weight: 700; line-height: 1; }
.cp-ss-gl-c { height: 2.5px; background: var(--ss-yellow); }
.cp-ss-gl-f { height: 2.5px; background: var(--ss-red); }
.cp-ss-fig-fasola { gap: 4px clamp(8px, 2.6vw, 14px); border-block: 1px solid var(--ss-rule); font-family: var(--ss-serif); font-style: italic; font-size: 24px; }
.cp-ss-fig-shapes { height: 84px; }
.cp-ss-fig-shapes svg { display: block; height: 84px; width: auto; max-width: 100%; }
.cp-ss-fig-curwen { font-family: var(--ss-serif); font-size: clamp(20px, 5.4vw, 26px); letter-spacing: .04em; white-space: pre; }
.cp-ss-fig-kodaly { gap: 4px clamp(12px, 4vw, 22px); }
.cp-ss-fig-kodaly span { display: grid; gap: 2px; }
.cp-ss-fig-kodaly small { font-size: 13px; color: var(--ss-muted); }
.cp-ss-fig-kodaly i { font-family: var(--ss-serif); font-size: 22px; }
.cp-ss-fig-numbers { gap: 4px clamp(10px, 3.4vw, 18px); font-size: 26px; font-weight: 500; }
.cp-ss-fig-numbers i { font-family: var(--ss-serif); font-size: 24px; }
.cp-ss-fig-rule { width: 1px; height: 28px; background: var(--ss-rule); }

/* fa: the outcomes, rising like the scale, do to so, the half step at fa. */
.cp-ss-aims { display: flex; flex-wrap: wrap; align-items: flex-end; gap: 32px 20px; margin-top: 56px; }
.cp-ss-aim { position: relative; flex: 1 1 180px; padding-top: 14px; border-top: 1px solid var(--ss-ink); }
@media (min-width: 900px) { .cp-ss-aim { margin-bottom: calc(var(--rise) * 20px); } }
.cp-ss-aim-home { border-top: 3px solid var(--ss-blue); }
.cp-ss-aim-n { display: block; font-family: var(--ss-serif); font-style: italic; font-size: 40px; line-height: 1; }
.cp-ss-aim-home .cp-ss-aim-n { color: var(--ss-blue); }
.cp-ss-aim p { margin-top: 12px; font-size: 16px; line-height: 1.5; text-wrap: pretty; }
.cp-ss-aim-tag { position: absolute; inset-inline-end: 0; top: -24px; display: flex; align-items: center; gap: 6px; font-size: 11px; font-weight: 600; letter-spacing: .1em; text-transform: uppercase; color: var(--ss-red); }
.cp-ss-aim-tag::before { content: ""; width: 7px; height: 10px; border: 2px solid currentColor; border-inline-start: 0; }

/* so: the lessons, each unit a line of bars marked with a shape-note head. */
.cp-ss-unitsec { margin-top: clamp(80px, 10vw, 120px); padding-bottom: clamp(80px, 10vw, 120px); background: var(--ss-sheet); border-block: 1px solid var(--ss-rule-2); }
.cp-ss-units { display: grid; gap: 44px; margin-top: 56px; }
.cp-ss-unit { display: grid; grid-template-columns: minmax(0, 1fr); gap: 20px 40px; align-items: start; }
@media (min-width: 900px) { .cp-ss-unit { grid-template-columns: minmax(0, 1fr) minmax(0, 2fr); } }
.cp-ss-unit-head { display: grid; grid-template-columns: 44px minmax(0, 1fr); gap: 4px 14px; }
.cp-ss-shape { grid-row: span 3; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 1px; width: 44px; height: 44px; border: 1px solid var(--ss-rule); border-radius: 99px; }
.cp-ss-shape i { display: none; background: var(--ss-ink); }
.cp-ss-shape i:first-child { display: block; }
.cp-ss-shape-oval i:first-child { width: 18px; height: 12px; border-radius: 50%; rotate: -20deg; }
.cp-ss-shape-diamond i:first-child { width: 13px; height: 13px; rotate: 45deg; }
.cp-ss-shape-triangle i:first-child { width: 16px; height: 14px; clip-path: polygon(0 100%, 100% 100%, 100% 0); }
.cp-ss-shape-rect i:first-child { width: 16px; height: 12px; }
.cp-ss-shape-chord i { display: block; width: 13px; height: 8px; border-radius: 50%; }
.cp-ss-unit-n { align-self: center; font-size: 12px; font-weight: 600; letter-spacing: .16em; text-transform: uppercase; color: var(--ss-muted); }
.cp-ss-unit-n em { font-family: var(--ss-serif); font-size: 15px; font-weight: 400; letter-spacing: 0; text-transform: none; }
.cp-ss-unit h3 { font-size: 22px; font-weight: 600; line-height: 1.25; }
.cp-ss-unit-say { grid-column: 2; margin-top: 4px; font-size: 15px; line-height: 1.55; color: var(--ss-muted); text-wrap: pretty; }
.cp-ss-lessons { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); border-block: 1px solid var(--ss-ink); border-inline-end: 4px double var(--ss-ink); }
@media (min-width: 640px) { .cp-ss-lessons { grid-template-columns: repeat(4, minmax(0, 1fr)); } }
@media (max-width: 639px) { .cp-ss-lessons li:nth-child(-n+2) { border-bottom: 1px solid var(--ss-ink); } }
.cp-ss-lesson { display: flex; flex-direction: column; gap: 8px; height: 100%; min-height: 120px; padding: 14px 16px 16px; border-inline-start: 1px solid var(--ss-ink); color: var(--ss-ink); }
a.cp-ss-lesson:hover { background: var(--ss-paper); }
a.cp-ss-lesson:hover b { text-decoration: underline 1px; text-underline-offset: 3px; }
.cp-ss-lesson-top { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: center; gap: 6px; padding-bottom: 14px; font-size: 12px; font-weight: 600; color: var(--ss-muted); font-variant-numeric: tabular-nums; }
.cp-ss-free { padding: 3px 8px; border-radius: 99px; background: var(--ss-blue); color: var(--ss-blue-ink); font-size: 10px; letter-spacing: .12em; text-transform: uppercase; white-space: nowrap; }
.cp-ss-lesson b { font-size: 16px; font-weight: 600; line-height: 1.3; }
.cp-ss-lesson-line { font-size: 13px; line-height: 1.45; color: var(--ss-muted); }

/* la: the science, numbered i to iv. */
.cp-ss-cards { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 440px), 1fr)); gap: 0 56px; margin-top: 56px; }
.cp-ss-cards li { display: grid; grid-template-columns: 48px minmax(0, 1fr); gap: 0 16px; padding: 28px 0 40px; border-top: 1px solid var(--ss-ink); }
.cp-ss-roman { font-family: var(--ss-serif); font-style: italic; font-size: 32px; line-height: 1; color: var(--ss-blue); }
.cp-ss-cards h3 { font-size: 21px; font-weight: 600; line-height: 1.25; }
.cp-ss-cards p { margin-top: 10px; font-size: 16px; line-height: 1.65; color: var(--ss-body); text-wrap: pretty; }

/* ti: what the app listens for, and the notes in the margin in red ink. */
.cp-ss-band { margin-top: clamp(40px, 6vw, 80px); padding-bottom: clamp(80px, 10vw, 112px); background: var(--ss-band); border-block: 1px solid var(--ss-rule); }
.cp-ss-band-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 420px), 1fr)); gap: 48px 72px; }
.cp-ss-measures { margin-top: 28px; max-width: 30ch; font-family: var(--ss-serif); font-size: clamp(21px, 2.2vw, 26px); line-height: 1.45; text-wrap: pretty; }
.cp-ss-margin { display: grid; gap: 24px; align-content: start; padding-top: 24px; border-top: 1.5px solid var(--ss-red); }
.cp-ss-margin li { color: var(--ss-red); }
.cp-ss-margin p { display: inline; font-family: var(--ss-serif); font-style: italic; font-size: 19px; line-height: 1.5; text-wrap: pretty; }
.cp-ss-margin-n { margin-inline-end: 8px; font-size: 12px; font-weight: 700; }
.cp-ss-margin-n .s-cite { margin: 0; font-size: 12px; vertical-align: baseline; line-height: 1; }
.cp-ss-margin-n .s-cite + .s-cite::before { content: "·"; margin-inline: 4px; }
.cp-ss-margin-n .s-cite a { color: inherit; }

/* Before you begin: who, what you need, singing safely, and the hymn board. */
.cp-ss-begin-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 300px), 1fr)); gap: 40px 32px; align-items: start; margin-top: 48px; }
.cp-ss-col-h { padding-bottom: 12px; border-bottom: 1px solid var(--ss-ink); font-size: 12px; font-weight: 700; letter-spacing: .14em; text-transform: uppercase; }
.cp-ss-col-h-next { margin-top: 32px; }
.cp-ss-rows li { padding: 14px 0; border-bottom: 1px solid var(--ss-rule); font-size: 16px; line-height: 1.5; }
.cp-ss-board { padding: 24px 24px 8px; border-radius: 4px; background: var(--ss-board); color: var(--ss-board-ink); }
.cp-ss-board .cp-ss-col-h { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 4px 12px; border-color: var(--ss-board-rule); }
.cp-ss-board .cp-ss-col-h span + span { color: var(--ss-board-muted); }
.cp-ss-board li { display: grid; grid-template-columns: 44px minmax(0, 1fr); gap: 0 12px; padding: 16px 0; border-bottom: 1px solid var(--ss-board-rule); }
.cp-ss-board li:last-child { border-bottom: 0; }
.cp-ss-board-n { font-family: var(--ss-serif); font-size: 30px; line-height: 1; }
.cp-ss-board b { display: block; font-family: var(--ss-serif); font-size: 21px; font-weight: 400; line-height: 1.2; }
.cp-ss-board li span:not(.cp-ss-board-n) { display: block; margin-top: 2px; font-size: 13px; color: var(--ss-board-muted); }
.cp-ss-board > p { padding: 4px 0 16px; font-size: 12.5px; color: var(--ss-board-muted); }

/* Questions, beside their heading. */
.cp-ss-faqsec { display: grid; grid-template-columns: minmax(0, 1fr); gap: 32px 64px; }
@media (min-width: 900px) { .cp-ss-faqsec { grid-template-columns: minmax(0, 1fr) minmax(0, 2fr); } }
.cp-ss-faqsec .cp-faq { max-width: none; margin-top: 0; border-top: 1px solid var(--ss-ink); }
.cp-ss-faqsec .cp-faq details { border-color: var(--ss-rule); }
.cp-ss-faqsec .cp-faq summary { min-height: 64px; font-size: 19px; font-weight: 600; }
.cp-ss-faqsec .cp-faq-sign { background: none; border: 1px solid var(--ss-ink); }
.cp-ss-faqsec .cp-faq details p { color: var(--ss-body); }

/* do, high: the close, centred, the top of the ladder. */
.cp-ss-close { margin-top: clamp(80px, 10vw, 120px); padding-bottom: 96px; background: var(--ss-sheet); border-top: 1px solid var(--ss-rule-2); text-align: center; }
.cp-ss-close .cp-ss-step { justify-content: center; }
.cp-ss-join { margin-top: 20px; font-size: clamp(60px, 10vw, 140px); line-height: .95; letter-spacing: -0.03em; }
.cp-ss-close .cp-ss-lead { margin-inline: auto; margin-top: 24px; }
.cp-ss-close-btns { justify-content: center; align-items: center; }
.cp-ss-close .cp-ss-fine { margin-top: 16px; }
.cp-ss-all { display: inline-flex; align-items: center; justify-content: center; gap: 6px; min-height: 44px; padding-inline: 8px; font-weight: 600; text-decoration: underline 1px; text-underline-offset: 4px; }
.cp-ss-all:hover { color: var(--ss-blue); }
.cp-ss-related-h { margin-top: 64px; }
.cp-ss-close .cp-related { justify-content: center; margin-top: 16px; }
.cp-ss-close .cp-related a { border: 1px solid var(--ss-rule); background: var(--ss-paper); }
/* All courses sits beside Hear do; the related list's own link would say it twice. */
.cp-ss-close .cp-related-all { display: none; }

.cp-ss-sources { padding-block: 64px; }
.cp-ss-sources summary { display: flex; align-items: center; min-height: 44px; cursor: pointer; list-style: none; }
.cp-ss-sources summary::-webkit-details-marker { display: none; }
.cp-ss-sources summary h2::after { content: " +"; }
.cp-ss-sources details[open] summary h2::after { content: none; }
.cp-ss-sources ol { margin-top: 20px; padding-inline-start: 28px; list-style: decimal; columns: 2 360px; column-gap: 56px; font-size: 14px; line-height: 1.5; color: var(--ss-body); }
.cp-ss-sources li { break-inside: avoid; padding-bottom: 8px; }
.cp-ss-sources a { text-decoration: underline 1px var(--ss-rule); text-underline-offset: 3px; }
.cp-ss-sources a:hover { color: var(--ss-blue); }

/* Game mode: the arcade's night (or its light), pixel caps for the headings and labels, square frames with hard shadows,
   and PRESS START on the demo. The music keeps its staves and notes, in the arcade's ink. */
:root[data-skin="game"] body.s-arcade .cp-ss :is(.cp-ss-h2, .cp-ss-join, h1#page-h) { font-family: var(--a-display); font-weight: 400; letter-spacing: .01em; text-transform: uppercase; line-height: 1.08; font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade .cp-ss h1#page-h { font-size: clamp(40px, 6.4vw, 84px); }
:root[data-skin="game"] body.s-arcade .cp-ss :is(.cp-ss-h2) { font-size: clamp(28px, 4.4vw, 52px); }
:root[data-skin="game"] body.s-arcade .cp-ss .cp-ss-join { font-size: clamp(40px, 7vw, 96px); }
:root[data-skin="game"] body.s-arcade .cp-ss :is(.cp-ss-step, .cp-ss-label, .cp-ss-demo-bar, .cp-ss-col-h, .cp-ss-unit-n, .cp-ss-aim-tag, .cp-ss-free, .cp-ss-bar-n) { font-family: var(--a-hud); font-size: 9.5px; font-weight: 400; letter-spacing: .08em; line-height: 1.6; font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade .cp-ss .cp-ss-step { color: var(--a-yellow); }
:root[data-skin="game"] body.s-arcade .cp-ss :is(.cp-ss-ladder, .cp-ss-demo, .cp-ss-board) { border: 2px solid var(--a-cyan); border-radius: 0; box-shadow: 6px 6px 0 var(--a-pink); }
:root[data-skin="game"] body.s-arcade .cp-ss :is(.cp-ss-play, .cp-ss-newkey, .cp-ss-free, .cp-ss-shape, .cp-related a) { border-radius: 0; }
:root[data-skin="game"] body.s-arcade .cp-ss .cp-ss-play { background: var(--a-yellow); color: var(--a-yellow-ink); font: 400 11px/1.4 var(--a-hud); text-transform: uppercase; box-shadow: 4px 4px 0 var(--arc-shadow-c, #05030d); }
:root[data-skin="game"] body.s-arcade .cp-ss .cp-ss-play-icon { background: var(--a-yellow-ink); border-radius: 0; }
:root[data-skin="game"] body.s-arcade .cp-ss .cp-ss-play-icon::before { border-inline-start-color: var(--a-yellow); }
:root[data-skin="game"] body.s-arcade .cp-ss .cp-ss-play[aria-pressed="true"] .cp-ss-play-icon::before { background: var(--a-yellow); }
:root[data-skin="game"] body.s-arcade .cp-ss :is(.cp-ss-newkey, .cp-ss-switch) { font: 400 10px/1.4 var(--a-hud); }
:root[data-skin="game"] body.s-arcade .cp-ss .cp-ss-newkey { border: 2px solid var(--a-cyan); background: transparent; box-shadow: 3px 3px 0 var(--arc-shadow-c, #05030d); }
:root[data-skin="game"] body.s-arcade .cp-ss :is(.cp-ss-bar, .cp-ss-cards li, .cp-ss-rows li, .cp-ss-aim, .cp-ss-lesson) { border-color: var(--a-line-2); }
:root[data-skin="game"] body.s-arcade .cp-ss :is(.cp-ss-bars, .cp-ss-lessons, .cp-ss-col-h) { border-color: var(--a-cyan); }
:root[data-skin="game"] body.s-arcade .cp-ss .cp-ss-year { font-family: var(--a-display); font-size: 30px; text-transform: none; font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade .cp-ss .cp-ss-aim-home, :root[data-skin="game"] body.s-arcade .cp-ss .cp-ss-aim-home .cp-ss-aim-n { border-top-color: var(--a-yellow); color: var(--a-yellow); }
@media (prefers-reduced-motion: no-preference) { :root[data-skin="game"] body.s-arcade .cp-ss-play[aria-pressed="false"] .cp-ss-go { animation: s-demo-blink 1.1s steps(2, start) infinite; } }

/* A cappella bass (site/courses/a-cappella-bass): be the floor, after Hillel's design (2026-11-18): a record
   sleeve in amber on near-black. A heavy headline (Figtree 800, our closest to the design's extra-wide face), a
   serif for the history and the science, a monospace for frequencies and the track labels ("Side A · Track 1").
   The floor is a near-black band: under the hero's headline (harmonic 1, with harmonics 2 to 6 as lines above it,
   spaced as heard), behind the featured demo, under the units' last step, behind the liner notes and under the
   close. The story is a stack of 78s; the units step down like a walking bass onto the band. Calm light is the
   design's paper; calm dark keeps the band darker than the page. Game skin: the arcade's night, pixel type,
   square frames with hard shadows, neon discs, and PRESS START on the demo. Sounds: js/public/a-cappella-bass.js. */
.cp-acb { --acb-paper: #f3eee4; --acb-paper-2: #ebe4d6; --acb-ink: #1b1712; --acb-body: #3a332a; --acb-muted: #4a4339; --acb-rule: #cfc5b3; --acb-strong: #1b1712;
    --acb-amber-t: #8a5a12; --acb-octave: #b9ae9b; --acb-groove-a: #1b1712; --acb-groove-b: #2e2820;
    --acb-band: #1b1712; --acb-band-ink: #efe7d8; --acb-band-body: #d8cfbf; --acb-band-muted: #b9ae9b; --acb-band-rule: #3a332a; --acb-band-edge: #6b6153;
    --acb-amber: #e0a245; --acb-amber-ink: #1b1712;
    --acb-serif: ui-serif, "Iowan Old Style", "Palatino Linotype", Palatino, Georgia, serif; --acb-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
    --cp-a: var(--acb-amber-t); --cp-a-ink: #fff; --cp-a-text: var(--acb-amber-t); --cp-line: var(--acb-rule);
    background: var(--acb-paper); color: var(--acb-ink); }
:root:not([data-theme$="-light"]) .cp-acb { --acb-paper: #15120e; --acb-paper-2: #1e1a14; --acb-ink: #efe7d8; --acb-body: #d8cfbf; --acb-muted: #b9ae9b; --acb-rule: #3a332a; --acb-strong: #efe7d8;
    --acb-amber-t: #e0a245; --acb-octave: #5e564a; --acb-groove-a: #2a241c; --acb-groove-b: #3a332a; --acb-band: #0a0806; --acb-band-rule: #2e281f; }
:root[data-skin="game"]:not([data-theme$="-light"]) .cp-acb { --acb-paper: var(--a-bg); --acb-paper-2: var(--a-panel); --acb-ink: #f7f4ff; --acb-body: #d2ccf0; --acb-muted: #b8b2d8; --acb-rule: #2a2640; --acb-strong: #3be7ff;
    --acb-amber-t: #ffd84a; --acb-octave: #6f6a99; --acb-groove-a: #12101e; --acb-groove-b: #2a2640;
    --acb-band: #05030d; --acb-band-ink: #f7f4ff; --acb-band-body: #d2ccf0; --acb-band-muted: #b8b2d8; --acb-band-rule: #2a2640; --acb-band-edge: #6f6a99; --acb-amber: #ffd84a; --acb-amber-ink: #1a1400; }

/* Type: the heavy headline, the serif, the monospace labels. */
