.cp-acb-strip { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 6px 24px; padding-block: 14px; border-bottom: 1px solid var(--acb-band-rule); font: 12px/1.6 var(--acb-mono); letter-spacing: .03em; color: var(--acb-band-muted); }
