@media (max-width: 599px) { .cp-acb-btns > a { flex: 1 1 100%; justify-content: center; } }
.cp-acb-facts { display: grid; gap: 2px; margin-top: 20px; font-size: 14px; line-height: 1.6; color: var(--acb-band-muted); }
.cp-acb-quiet { margin-top: 14px; font-size: 14px; line-height: 1.5; color: var(--acb-band-muted); }

/* The hero: the trail and the course's size, then the headline standing on the floor with the harmonic lines above. */
.cp-acb-hero { padding-top: clamp(20px, 4vw, 48px); }
