.cp-acb-demo { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 360px), 1fr)); gap: clamp(32px, 5vw, 64px); align-items: end; padding-block: clamp(40px, 5vw, 64px) clamp(56px, 7vw, 96px); }
