.cp-acb :is(.cp-acb-play, .cp-acb-hear) { display: inline-flex; align-items: center; gap: 12px; min-height: 52px; padding: 8px 22px 8px 8px; border-radius: 99px; background: var(--acb-amber); color: var(--acb-amber-ink); font-size: 16px; font-weight: 700; white-space: nowrap; cursor: pointer; }
