@keyframes cp-acb-breathe { 0%, 100% { box-shadow: 0 0 0 0 color-mix(in srgb, var(--acb-amber) 55%, transparent); } 50% { box-shadow: 0 0 0 10px color-mix(in srgb, var(--acb-amber) 0%, transparent); } }
