.cp-acb-demo-note { max-width: 60ch; font-size: 12px; line-height: 1.7; letter-spacing: 0; text-transform: none; color: var(--acb-band-muted); }
.cp-acb-chords { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); border-left: 1px solid var(--acb-band-rule); }
