.cp-acb-chord-name b { display: block; font-size: 17px; }
.cp-acb-chord[data-on] .cp-acb-chord-name b::before { content: ""; display: inline-block; width: 8px; height: 8px; margin-right: 8px; border-radius: 99px; background: var(--acb-amber); vertical-align: middle; }
.cp-acb-chord-name span { font-size: 13px; color: var(--acb-band-muted); }

/* Sections on the paper. */
.cp-acb-sec { padding-top: clamp(64px, 9vw, 128px); }
.cp-acb-head { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: end; gap: 16px 24px; }
