/* The story: a stack of 78s, each with its year, the line on its label, and the entry. */
.cp-acb-story .cp-acb-h2 { max-width: 12ch; }
.cp-acb-discs > li { display: grid; grid-template-columns: 76px minmax(0, 1fr); grid-template-areas: "disc when" "entry entry"; gap: 18px 20px; align-items: center; padding-block: 28px; border-bottom: 1px solid var(--acb-rule); }
@media (min-width: 900px) { .cp-acb-discs > li { grid-template-columns: 120px minmax(0, 1fr) minmax(0, 1.25fr); grid-template-areas: "disc when entry"; gap: 40px; align-items: start; padding-block: 32px; } }
