}
.cp-acb-disc { --label: #efe7d8; position: relative; grid-area: disc; width: 100%; aspect-ratio: 1; border-radius: 50%;
    background: radial-gradient(circle closest-side, var(--label) 0 39%, transparent 40%), conic-gradient(from 20deg, transparent 0 8%, #ffffff1f 13%, transparent 19% 58%, #ffffff14 63%, transparent 69%), repeating-radial-gradient(circle closest-side, var(--acb-groove-a) 0 2px, var(--acb-groove-b) 2px 3px);
    box-shadow: 0 0 0 1px var(--acb-rule); }
.cp-acb-disc::after { content: ""; position: absolute; inset: 0; width: 6%; height: 6%; margin: auto; border-radius: 50%; background: #1b1712; }
.cp-acb-disc-1 { --label: #b9ae9b; }
.cp-acb-disc-2 { --label: #e0a245; }
@keyframes cp-acb-spin { to { rotate: 360deg; } }
@media (prefers-reduced-motion: no-preference) { .cp-acb-discs > li:hover .cp-acb-disc { animation: cp-acb-spin 1.8s linear infinite; } }
.cp-acb-when { grid-area: when; }
.cp-acb-year { font-size: clamp(44px, 5vw, 64px); font-weight: 300; line-height: 1; letter-spacing: -0.02em; }
.cp-acb-label { margin-top: 8px; color: var(--acb-amber-t); }
.cp-acb-entry { grid-area: entry; }
.cp-acb-entry h3 { font-size: 20px; font-weight: 700; line-height: 1.3; }
.cp-acb-entry p { margin-top: 8px; font-family: var(--acb-serif); font-size: 18px; line-height: 1.55; color: var(--acb-body); text-wrap: pretty; }

/* By the end: four ruled columns with big light numbers. */
.cp-acb-aims { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 240px), 1fr)); gap: 32px; margin-top: 40px; }
.cp-acb-aims li { padding-top: 16px; border-top: 2px solid var(--acb-strong); }
.cp-acb-aim-n { display: block; font-size: 56px; font-weight: 300; line-height: 1; color: var(--acb-amber-t); }
.cp-acb-aims p { margin-top: 16px; font-size: 18px; line-height: 1.45; text-wrap: pretty; }

/* The units: four steps down like a walking bass, the last resting on the floor band. */
.cp-acb-unitsec { margin-top: clamp(64px, 9vw, 128px); padding-top: clamp(64px, 9vw, 128px); background: var(--acb-paper-2); }
.cp-acb-unitsec .cp-acb-h2 { max-width: 14ch; }
.cp-acb-units-note { max-width: 300px; font: italic 18px/1.45 var(--acb-serif); color: var(--acb-muted); }
.cp-acb-steps { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 240px), 1fr)); gap: 40px 20px; align-items: end; margin-top: 56px; }
@media (min-width: 1024px) { .cp-acb-steps { grid-template-columns: repeat(4, minmax(0, 1fr)); } .cp-acb-step { margin-bottom: calc(var(--step) * 56px); } }
.cp-acb-step-n { padding-top: 14px; border-top: 4px solid var(--acb-strong); color: var(--acb-amber-t); }
.cp-acb-step h3 { margin-top: 8px; font-size: 28px; font-weight: 800; line-height: 1.1; letter-spacing: -0.02em; }
.cp-acb-step-say { margin-top: 8px; font-size: 15px; line-height: 1.5; color: var(--acb-muted); }
.cp-acb-lessons { margin-top: 16px; font-size: 15px; }
.cp-acb-lessons li { display: flex; justify-content: space-between; align-items: center; gap: 8px; min-height: 42px; padding-block: 8px; border-top: 1px solid var(--acb-rule); }
.cp-acb-lesson-last { font-weight: 700; }
.cp-acb-free { flex: none; padding: 4px 8px; border-radius: 99px; background: var(--acb-band); color: var(--acb-amber); font: 600 11px/1.2 var(--acb-mono); letter-spacing: .04em; text-transform: uppercase; white-space: nowrap; }
.cp-acb-landing { margin-top: 24px; }
.cp-acb-landing .cp-acb-strip { border-bottom: 0; }

/* The science: The note that isn't there with its demo, then four ruled notes, two a row. */
.cp-acb-science .cp-acb-h2 { max-width: 16ch; }
.cp-acb-mf { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 420px), 1fr)); gap: clamp(32px, 5vw, 64px); margin-top: 48px; padding-block: 32px 48px; border-top: 2px solid var(--acb-strong); }
.cp-acb-mf h3 { margin-bottom: 12px; font-size: 28px; font-weight: 800; line-height: 1.1; letter-spacing: -0.02em; }
.cp-acb-mf-try { margin-top: 20px; font-size: 15px; line-height: 1.55; color: var(--acb-muted); }
.cp-acb-mf-card { display: flex; flex-direction: column; gap: 20px; padding: clamp(20px, 3vw, 28px); border-radius: 12px; background: var(--acb-band); color: var(--acb-band-ink); }
.cp-acb-bars { display: flex; align-items: flex-end; gap: 10px; height: 180px; border-bottom: 4px solid var(--acb-amber); }
.cp-acb-bar { flex: 1; height: var(--h); border-radius: 3px 3px 0 0; background: var(--acb-band-muted); transition: opacity .25s; }
.cp-acb-bar-fund { background: var(--acb-amber); }
.cp-acb-bar[data-off] { opacity: .15; outline: 1px dashed var(--acb-amber); outline-offset: -1px; }
.cp-acb-hz { display: flex; gap: 10px; margin-top: -8px; font-size: 13px; letter-spacing: 0; color: var(--acb-band-ink); }
.cp-acb-hz span { flex: 1; text-align: center; }
.cp-acb-hz span:first-child { color: var(--acb-amber); }
.cp-acb-mf-act { display: flex; flex-wrap: wrap; align-items: center; gap: 10px 14px; }
.cp-acb-mf-state { letter-spacing: 0; text-transform: none; color: var(--acb-band-muted); }
.cp-acb-mf-state[data-on] { color: var(--acb-amber); }
.cp-acb-mf-say { font-size: 15px; line-height: 1.5; color: var(--acb-band-ink); }
.cp-acb-mf-say:empty { display: none; }
.cp-acb-sci { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 340px), 1fr)); column-gap: clamp(32px, 5vw, 64px); }
.cp-acb-sci li { padding-block: 28px 40px; border-top: 1px solid var(--acb-strong); }
.cp-acb-sci h3 { margin-bottom: 12px; font-size: 22px; font-weight: 700; line-height: 1.25; }

/* Liner notes: the band, what the app listens for at left, the notes in two ruled columns. */
.cp-acb-liner { margin-top: clamp(24px, 4vw, 48px); padding-block: clamp(64px, 9vw, 128px); }
.cp-acb-liner-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 360px), 1fr)); gap: clamp(40px, 6vw, 96px); }
.cp-acb-inside { margin-top: 40px; padding-top: 20px; border-top: 1px solid var(--acb-band-rule); }
.cp-acb-inside p { margin-top: 12px; font-size: 18px; line-height: 1.6; color: var(--acb-band-body); text-wrap: pretty; }
.cp-acb-notes { columns: 2 260px; column-gap: 40px; column-rule: 1px solid var(--acb-band-rule); font-family: var(--acb-serif); font-size: 18px; line-height: 1.55; }
.cp-acb-notes li { margin-bottom: 24px; break-inside: avoid; }

/* Before you begin: three ruled columns. */
.cp-acb-begin-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 280px), 1fr)); gap: 40px; margin-top: 48px; }
.cp-acb-col-h { padding-bottom: 12px; border-bottom: 2px solid var(--acb-strong); font: 600 12px/1.5 var(--acb-mono); letter-spacing: .06em; text-transform: uppercase; }
.cp-acb-col-safe { border-bottom-color: var(--acb-amber-t); color: var(--acb-amber-t); }
.cp-acb-songs-h { margin-top: 32px; }
.cp-acb-rows li { padding-block: 14px; border-bottom: 1px solid var(--acb-rule); font-size: 16px; line-height: 1.5; }
.cp-acb-songs b { display: block; }
.cp-acb-songs span { font-size: 14px; color: var(--acb-muted); }

/* Questions beside their heading, the answers in the serif. */
.cp-acb-fine { display: grid; gap: 24px 40px; }
@media (min-width: 900px) { .cp-acb-fine { grid-template-columns: minmax(0, 1fr) minmax(0, 2fr); align-items: start; } }
.cp-acb .cp-faq { margin-top: 0; max-width: none; border-top: 2px solid var(--acb-strong); }
.cp-acb .cp-faq details { border-color: var(--acb-rule); }
.cp-acb .cp-faq summary { font-size: 20px; }
.cp-acb .cp-faq-sign { background: transparent; box-shadow: inset 0 0 0 1px var(--acb-rule); }
.cp-acb .cp-faq details p { padding-right: clamp(0px, 4vw, 48px); font-family: var(--acb-serif); font-size: 19px; line-height: 1.55; color: var(--acb-body); }

/* The close: three lines for the parts above, "Hold the group up." on the floor, which is you. */
.cp-acb-close { margin-top: clamp(64px, 9vw, 128px); }
.cp-acb-parts { display: flex; flex-direction: column; gap: 14px; }
.cp-acb-parts li { display: flex; align-items: center; gap: 12px; font: 12px/1.2 var(--acb-mono); color: var(--acb-muted); }
.cp-acb-parts li span { flex: none; width: 76px; }
.cp-acb-parts li::after { content: ""; flex: 1; border-top: 1px solid var(--acb-octave); }
.cp-acb-close-h { max-width: 9ch; margin-top: 40px; padding-bottom: .17em; font-size: clamp(56px, 10vw, 152px); line-height: .84; }
.cp-acb-related { display: flex; flex-wrap: wrap; align-items: center; gap: 12px; padding-block: 24px 40px; border-top: 1px solid var(--acb-band-rule); }
.cp-acb-related h3 { margin-right: 8px; color: var(--acb-band-muted); }
.cp-acb .cp-related { margin-top: 0; }
.cp-acb .cp-related a { white-space: nowrap; color: var(--acb-band-ink); background: transparent; box-shadow: inset 0 0 0 1px var(--acb-band-rule); }
.cp-acb .cp-related a:hover { background: color-mix(in srgb, var(--acb-band-ink) 8%, transparent); }
.cp-acb .cp-related-all { display: none; } /* the close's own All courses button says it */

/* Sources: one numbered list in two columns, folded on a phone. */
.cp-acb-sources { padding-block: clamp(56px, 7vw, 96px); }
.cp-acb-sources summary { display: flex; align-items: center; justify-content: space-between; min-height: 44px; padding-bottom: 8px; border-bottom: 2px solid var(--acb-strong); list-style: none; cursor: pointer; }
.cp-acb-sources summary::-webkit-details-marker { display: none; }
.cp-acb-sources summary::after { content: "+"; font: 18px/1 var(--acb-mono); color: var(--acb-muted); }
.cp-acb-sources details[open] summary::after { content: "\2212"; }
.cp-acb-sources h2 { font-weight: 600; color: var(--acb-ink); }
.cp-acb-sources ol { margin-top: 16px; padding-left: 28px; list-style: decimal; columns: 2 360px; column-gap: 48px; font-size: 14px; line-height: 1.5; color: var(--acb-body); }
.cp-acb-sources li { margin-bottom: 8px; padding-left: 4px; break-inside: avoid; }
.cp-acb-sources a { text-decoration: underline; text-decoration-color: var(--acb-rule); text-underline-offset: 3px; }

/* Game skin: the arcade's night, pixel type for the headings and the labels (the reading stays readable),
   square frames with hard shadows, neon discs and lines, and PRESS START on the demo. Scoped to main.cp-acb under
   :not(.s-calm) so they outrank the arcade's own rules for every page's main h1; the discs carry -ring, the
   arcade's hook for a circle that stays round. */
:root[data-skin="game"] body.s-arcade:not(.s-calm) main.cp-acb :is(h1, .cp-acb-h2, .cp-acb-close-h, .cp-acb-year, .cp-acb-aim-n) { font-family: var(--a-display); font-weight: 400; letter-spacing: .01em; text-transform: uppercase; font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade:not(.s-calm) main.cp-acb .cp-acb-hero h1 { font-size: clamp(48px, 10.5vw, 150px); line-height: .9; text-shadow: 4px 4px 0 #ff5fd2, 8px 8px 0 var(--arc-shadow-c, #05030d); }
:root[data-skin="game"] body.s-arcade:not(.s-calm) main.cp-acb .cp-acb-h2 { font-size: clamp(28px, 4.6vw, 58px); line-height: 1; }
:root[data-skin="game"] body.s-arcade:not(.s-calm) main.cp-acb .cp-acb-close-h { font-size: clamp(40px, 8vw, 120px); line-height: .92; text-shadow: 4px 4px 0 #ff5fd2; }
:root[data-skin="game"] body.s-arcade:not(.s-calm) main.cp-acb .cp-acb-year { font-size: clamp(30px, 3.6vw, 44px); color: var(--acb-amber-t); }
:root[data-skin="game"] body.s-arcade:not(.s-calm) main.cp-acb :is(.cp-acb-kick, .cp-acb-col-h, .cp-acb-step-n, .cp-acb-label, .cp-acb-line span, .cp-acb-strip, .cp-acb-free, .cp-acb-top .cp-acb-mono, .cp-acb-head .cp-acb-mono, .cp-acb-related h3, .cp-acb-sources h2, .cp-acb-parts li, .cp-acb-note, .cp-acb-hz, .cp-acb-mf-state) { font-family: var(--a-hud); font-size: 9.5px; font-weight: 400; letter-spacing: .06em; line-height: 1.7; font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade:not(.s-calm) main.cp-acb :is(.cp-acb-play, .cp-acb-hear, .cp-acb-mf-card, .cp-acb-note, .cp-acb-free, .cp-related a, .cp-acb-bar) { border-radius: 0; }
:root[data-skin="game"] body.s-arcade:not(.s-calm) main.cp-acb :is(.cp-acb-play, .cp-acb-hear) { text-transform: uppercase; box-shadow: 4px 4px 0 var(--arc-shadow-c, #05030d); }
:root[data-skin="game"] body.s-arcade:not(.s-calm) main.cp-acb .cp-acb-floor { border-top: 2px solid #3be7ff; }
:root[data-skin="game"] body.s-arcade:not(.s-calm) main.cp-acb :is(.cp-acb-mf-card, .cp-acb-chords) { border: 2px solid #3be7ff; box-shadow: 6px 6px 0 #ff5fd2; }
:root[data-skin="game"] body.s-arcade:not(.s-calm) main.cp-acb .cp-acb-disc { box-shadow: 0 0 0 2px #3be7ff, 0 0 18px -4px #3be7ff; }
:root[data-skin="game"] body.s-arcade:not(.s-calm) main.cp-acb .cp-acb-line-chord { border-top-color: var(--acb-amber-t); }
@media (prefers-reduced-motion: no-preference) { :root[data-skin="game"] body.s-arcade:not(.s-calm) main.cp-acb .cp-acb-play[aria-pressed="false"] .cp-acb-go { animation: s-demo-blink 1.1s steps(2, start) infinite; } }
:root[data-skin="game"] body.s-arcade:not(.s-calm) main.cp-acb .cp-acb-floor .btn-secondary { background: transparent; color: #3be7ff; box-shadow: inset 0 0 0 2px #3be7ff; } /* the band stays night in game's light themes too */
:root[data-skin="game"] body.s-arcade:not(.s-calm) main.cp-acb .cp-acb-hear { gap: 8px; padding-right: 14px; font-size: clamp(11px, 3.4vw, 14px); letter-spacing: 0; }
:root[data-skin="game"][data-theme$="-light"] body.s-arcade:not(.s-calm) main.cp-acb :is(.cp-acb-mf-card, .cp-acb-chords) { border-color: #076f88; box-shadow: 6px 6px 0 #c81872; }
:root[data-skin="game"][data-theme$="-light"] body.s-arcade:not(.s-calm) main.cp-acb .cp-acb-hero h1 { text-shadow: 4px 4px 0 #f0b8d6; }
:root[data-skin="game"][data-theme$="-light"] body.s-arcade:not(.s-calm) main.cp-acb .cp-acb-close-h { text-shadow: 4px 4px 0 #f0b8d6; }
/* Musical theatre (site/courses/musical-theatre): Hillel's design (2026-11-18, ~/Code/course-designs/musical-theatre),
   a Victorian Savoy Theatre programme. Headings in Bodoni Moda (self-hosted, above) with the site's serif behind it, the
   last words of each set in italic; tracked red labels; cream paper, theatre red, footlight gold. The hero's tilted
   playbill (the units as acts, a stamp, footlights); the demo in a gilt proscenium between red curtains, fourteen lamps
   on two rows lit as they're sung; the programme notes as dated rows; the overture on a dark band, No. 1 to 4; the
   running order, one column an act; the science by seat; backstage with notes pinned to a call-board; the company as a
   cast list with dotted leaders; the musical numbers in a double-ruled box; the interval's questions; the curtain call
   between curtains over footlights. Calm light and dark set the page's tokens on the body, so the header and the
   footer share the page's ground; game mode maps them to the arcade's and keeps its night screens. Sounds:
   js/public/musical-theatre.js. */
body:is([data-course="musical-theatre"], :has(main.cp-mt)) {
    --mt-serif: 'Bodoni Moda', ui-serif, Georgia, 'Times New Roman', serif;
    --mt-page: #f9f5ef; --mt-wash: #f6efe5; --mt-alt: #fdfaf5; --mt-paper: #fdf9f1; --mt-ink: #221a17; --mt-body: #4a403b;
    --mt-muted: #5f544d; --mt-rule: #e4d9cc; --mt-red: #a3202f; --mt-gold: #8a6416; --mt-lamp: #f5c84b; --mt-leader: #b8a998;
    --mt-tint: #f7ece9; --mt-start: #1f6b45; --mt-shadow: rgb(60 30 20 / .45);
    /* The night: the demo's deck, the overture, backstage and the curtain call. */
    --mt-night: #1b1418; --mt-night-2: #231a20; --mt-night-ink: #f3ebe3; --mt-night-body: #e5dcd5; --mt-night-muted: #b3a6a8;
    --mt-night-rule: #4a3c42; --mt-night-gold: #f5c84b; --mt-frame: #b8862b; --mt-curtain: #a3202f; --mt-curtain-d: #6a111c;
    --mt-curtain-m: #7d1622; --mt-apron: #5a4128; --mt-apron-d: #3d2c1c; --mt-bulb-off: #4a3c42; --mt-paper-ink: #2a211c;
    --mt-pin: #efe6d6;
}
:root:not([data-skin="game"]) body:is([data-course="musical-theatre"], :has(main.cp-mt)) {
    --color-ink: var(--mt-page); --color-panel: var(--mt-alt); --color-raised: var(--mt-wash); --color-cream: var(--mt-ink);
    --color-muted: var(--mt-muted); --color-line: var(--mt-rule); --color-edge: var(--mt-rule);
    --fill: color-mix(in srgb, var(--mt-ink) 6%, transparent); --fill-2: color-mix(in srgb, var(--mt-ink) 9%, transparent); --fill-3: color-mix(in srgb, var(--mt-ink) 12%, transparent);
    --primary: var(--mt-ink); --primary-ink: var(--mt-page); --primary-hover-to: var(--mt-page);
    --btn-soft: transparent; --btn-soft-hover: var(--fill-2); --btn-soft-active: var(--fill-3);
    --btn-outline: inset 0 0 0 1.5px var(--mt-ink); --btn-outline-pressed: inset 0 0 0 1.5px var(--mt-ink);
    --ring: var(--mt-red);
    background: var(--mt-page); color: var(--mt-ink);
}
:root:not([data-skin="game"]):not([data-theme$="-light"]) body:is([data-course="musical-theatre"], :has(main.cp-mt)) {
    --mt-page: #16110f; --mt-wash: #1e1814; --mt-alt: #1a1411; --mt-paper: #241d19; --mt-ink: #f3ebe3; --mt-body: #d9cfc6;
    --mt-muted: #bcafa4; --mt-rule: #3b312b; --mt-red: #ff9488; --mt-gold: #e0b04a; --mt-leader: #6d5f55; --mt-tint: #2b1d1c;
    --mt-shadow: rgb(0 0 0 / .6); --mt-night: #0e0a0c; --mt-night-2: #150f12; --mt-pin: #e6dccb;
    color-scheme: dark;
}
/* Game mode: the arcade's ground, panels and words, pink for the labels; the night screens stay night. */
:root[data-skin="game"] body.s-arcade:is([data-course="musical-theatre"], :has(main.cp-mt)) {
    --mt-serif: var(--a-display); --mt-page: var(--a-bg); --mt-wash: transparent; --mt-alt: transparent; --mt-paper: var(--a-panel);
    --mt-ink: var(--a-ink); --mt-body: var(--a-ink); --mt-muted: var(--a-muted); --mt-rule: var(--a-line-2); --mt-red: var(--a-pink);
    --mt-gold: var(--a-cyan); --mt-leader: var(--a-line-2); --mt-tint: color-mix(in srgb, var(--a-pink) 10%, var(--a-panel)); --mt-start: var(--color-good);
    --mt-night: #07060e; --mt-night-2: #0c0a17; --mt-night-rule: #2a2640; --mt-night-gold: #ffd84a; --mt-night-muted: #b1abc9;
    --mt-frame: #3be7ff; --mt-curtain: #c2268f; --mt-curtain-d: #5e0f48; --mt-curtain-m: #8a1a6a; --mt-apron: #1d1840; --mt-apron-d: #12102a;
    --mt-bulb-off: #2a2640;
}
/* The running order lists every lesson, so the shared list under the page isn't drawn (until the view's
   lesson-pages-inline section reaches it). */
body:is([data-course="musical-theatre"], :has(main.cp-mt)) [data-lesson-pages] { display: none; }

.cp-mt { --cp-a: var(--mt-red); --cp-a-ink: #fff; --cp-a-text: var(--mt-red); --cp-line: var(--mt-rule); color: var(--mt-ink); }
.cp-mt :is(summary, a, button, input):focus-visible { outline: 3px solid var(--mt-red); outline-offset: 3px; }

/* Type: the labels tracked capitals in red, the headings Bodoni with their last words in italic. */
.cp-mt-kick { font-size: 12px; font-weight: 700; letter-spacing: .24em; text-transform: uppercase; color: var(--mt-red); }
.cp-mt-title, .cp-mt-h1 { font-family: var(--mt-serif); font-weight: 500; letter-spacing: -0.01em; text-wrap: balance; }
.cp-mt-title { margin-top: 16px; font-size: clamp(38px, 5vw, 60px); line-height: 1.02; }
.cp-mt-h1 { margin-top: 20px; font-size: clamp(50px, 7.4vw, 104px); line-height: .95; letter-spacing: -0.02em; }
:is(.cp-mt-title, .cp-mt-h1) em { font-style: italic; }
.cp-mt-h1 em { color: var(--mt-red); }
.cp-mt .s-cite a { padding: 0 2px; color: var(--mt-red); font-weight: 700; text-decoration: none; }
.cp-mt-orn { display: flex; align-items: center; gap: 10px; font-size: 9px; letter-spacing: .3em; color: var(--mt-gold); }
.cp-mt-orn::before, .cp-mt-orn::after { content: ""; flex: 1; height: 1px; background: var(--mt-ink); }
:root[data-skin="game"] body.s-arcade .cp-mt-kick { font-family: var(--a-hud); font-size: 9.5px; font-weight: 400; letter-spacing: .08em; line-height: 1.6; font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade :is(.cp-mt-title, .cp-mt-h1) { font-weight: 400; text-transform: uppercase; letter-spacing: .01em; line-height: 1.04; font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade .cp-mt-h1 { font-size: clamp(36px, 6vw, 72px); text-shadow: 3px 3px 0 var(--a-pink), 6px 6px 0 var(--arc-shadow-c, #05030d); }
:root[data-skin="game"] body.s-arcade .cp-mt-title { font-size: clamp(28px, 4.2vw, 46px); }
:root[data-skin="game"] body.s-arcade :is(.cp-mt-title, .cp-mt-h1) em { font-style: normal; color: var(--a-yellow); }
:root[data-skin="game"][data-theme$="-light"] body.s-arcade :is(.cp-mt-title, .cp-mt-h1) em { color: var(--a-pink); }

/* The hero: the words beside the tilted playbill, on the wash. */
.cp-mt-hero { padding-block: 24px clamp(56px, 7vw, 76px); background: var(--mt-wash); border-block: 1px solid var(--mt-rule); }
.cp-mt-hero-grid { display: grid; gap: 48px; align-items: center; margin-top: clamp(20px, 3vw, 36px); }
@media (min-width: 960px) { .cp-mt-hero-grid { grid-template-columns: minmax(0, 1.25fr) minmax(0, 1fr); gap: 56px; } }
.cp-mt-lead { margin-top: 26px; max-width: 34em; font-size: clamp(17px, 1.6vw, 19px); line-height: 1.6; color: var(--mt-body); text-wrap: pretty; }
.cp-mt-btns { display: flex; flex-wrap: wrap; gap: 12px; margin-top: 30px; }
.cp-mt-btns > a { white-space: nowrap; }
@media (max-width: 479px) { .cp-mt-btns { flex-direction: column; align-items: stretch; } .cp-mt-btns > a { justify-content: center; } }
.cp-mt-quiet { margin-top: 12px; font-size: 14.5px; color: var(--mt-muted); }
.cp-mt-facts { display: flex; flex-wrap: wrap; gap: 6px 0; margin-top: 26px; font-size: 14px; color: var(--mt-muted); }
.cp-mt-facts li { display: inline-flex; align-items: center; }
.cp-mt-facts li + li::before { content: "◆"; margin-inline: 14px; font-size: 9px; color: var(--mt-gold); }
.cp-mt-bill-wrap { display: flex; justify-content: center; padding: 14px 20px 14px 12px; }
.cp-mt-bill { width: 100%; max-width: 420px; padding: 30px clamp(18px, 4vw, 30px) 22px; background: var(--mt-paper); color: var(--mt-ink); text-align: center;
    border: 1px solid var(--mt-ink); outline: 6px double var(--mt-ink); outline-offset: 6px; rotate: 1.2deg; box-shadow: 0 30px 60px -30px var(--mt-shadow); }
.cp-mt-bill-kick { font-size: 11px; font-weight: 700; letter-spacing: .32em; text-transform: uppercase; }
.cp-mt-bill-presents { margin-top: 10px; font-family: var(--mt-serif); font-style: italic; font-size: 17px; color: var(--mt-muted); }
.cp-mt-bill-name { margin-top: 4px; font-family: var(--mt-serif); font-weight: 800; font-size: clamp(34px, 4.4vw, 44px); line-height: .95; text-transform: uppercase; text-wrap: balance; }
.cp-mt-bill-acts { margin: 10px 0 18px; font-family: var(--mt-serif); font-style: italic; font-size: 16px; color: var(--mt-red); }
.cp-mt-bill .cp-mt-orn { margin-block: 0 14px; }
.cp-mt-bill-list { display: grid; gap: 8px; margin-bottom: 16px; text-align: start; font-size: 14px; }
.cp-mt-bill-list li { display: grid; grid-template-columns: 58px minmax(0, 1fr) auto; gap: 10px; align-items: baseline; }
.cp-mt-bill-list b { font-family: var(--mt-serif); font-weight: 700; color: var(--mt-red); white-space: nowrap; }
.cp-mt-bill-list i { font-size: 13px; color: var(--mt-muted); text-align: end; }
@media (max-width: 420px) { .cp-mt-bill-list li { grid-template-columns: 52px minmax(0, 1fr); } .cp-mt-bill-list i { grid-column: 2; text-align: start; } }
.cp-mt-bill-credit { margin-top: 12px; font-size: 12px; letter-spacing: .12em; line-height: 1.7; text-transform: uppercase; }
.cp-mt-stamp { display: inline-block; margin-top: 14px; padding: 5px 12px; border: 1.5px solid var(--mt-red); color: var(--mt-red); font-size: 11px; font-weight: 800; letter-spacing: .24em; text-transform: uppercase; rotate: -3deg; }
.cp-mt-bill-lights { display: flex; justify-content: space-between; margin-top: 18px; padding-inline: 4px; }
.cp-mt-bill-lights i, .cp-mt-foot i { width: 8px; height: 8px; border-radius: 99px; background: var(--mt-lamp); box-shadow: 0 0 8px var(--mt-lamp); }
:root[data-skin="game"] body.s-arcade .cp-mt-bill { rotate: 0deg; outline: none; border: 2px solid var(--a-cyan); box-shadow: 6px 6px 0 var(--a-pink); }
:root[data-skin="game"] body.s-arcade :is(.cp-mt-bill-name, .cp-mt-bill-list b) { font-family: var(--a-display); font-weight: 400; font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade :is(.cp-mt-bill-presents, .cp-mt-bill-acts) { font-family: inherit; font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade .cp-mt-bill-list b { font-size: 12px; }
:root[data-skin="game"] body.s-arcade :is(.cp-mt-stamp, .cp-mt-bill-lights i, .cp-mt-foot i) { border-radius: 0; }

/* Two notes, fourteen syllables: a gilt proscenium, a red valance and curtains, the lamps on two rows, the footlights
   on the apron, and the deck under it with the words and the controls. */
.cp-mt-demosec { padding-top: clamp(64px, 8vw, 88px); }
.cp-mt-demohead { margin-bottom: 28px; text-align: center; }
.cp-mt-demohead .cp-mt-title { margin-top: 10px; }
.cp-mt-frame { padding: 10px; border-radius: 14px 14px 4px 4px; background: var(--mt-frame); box-shadow: 0 40px 80px -40px rgb(35 26 32 / .7); color: var(--mt-night-ink); }
.cp-mt-frame > .cp-mt-valance { border-radius: 8px 8px 0 0; }
.cp-mt-frame > .cp-mt-deck { border-radius: 0 0 2px 2px; }
.cp-mt-valance { height: 34px; background: radial-gradient(circle at 50% 0, var(--mt-curtain) 17px, transparent 18px) 0 0 / 36px 30px repeat-x, linear-gradient(var(--mt-curtain-m), var(--mt-curtain-m)) 0 0 / 100% 12px no-repeat, var(--mt-night); }
.cp-mt-boards { display: flex; background: var(--mt-night); }
.cp-mt-curtain { flex: none; width: clamp(18px, 3vw, 34px); background: repeating-linear-gradient(90deg, var(--mt-curtain-d) 0, var(--mt-curtain) 9px, var(--mt-curtain-m) 17px); }
.cp-mt-curtain-r { background: repeating-linear-gradient(90deg, var(--mt-curtain-m) 0, var(--mt-curtain) 8px, var(--mt-curtain-d) 17px); }
.cp-mt-stage { flex: 1; min-width: 0; padding: clamp(18px, 3vw, 28px) clamp(12px, 3vw, 28px) 0; }
.cp-mt-stagebar { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 6px 12px; margin-bottom: 26px; font-size: 11px; font-weight: 700; letter-spacing: .2em; text-transform: uppercase; }
.cp-mt-stagebar span:first-child { color: var(--mt-night-gold); }
.cp-mt-stagebar span + span { color: var(--mt-night-muted); }
.cp-mt-lamps { display: grid; gap: 22px; }
@media (min-width: 760px) { .cp-mt-lamps { grid-template-columns: 1fr 1fr; gap: 0; } .cp-mt-half + .cp-mt-half { grid-template-columns: 0 repeat(7, minmax(0, 1fr)); } .cp-mt-half + .cp-mt-half .cp-mt-pitch { visibility: hidden; } }
.cp-mt-half { position: relative; display: grid; grid-template-columns: 30px repeat(7, minmax(0, 1fr)); grid-template-rows: 30px 10px 30px 40px; }
.cp-mt-half::before, .cp-mt-half::after { content: ""; position: absolute; inset-inline: 0; border-top: 1px dashed var(--mt-night-rule); }
.cp-mt-half::before { top: 15px; }
.cp-mt-half::after { top: 55px; }
.cp-mt-pitch { grid-column: 1; grid-row: 1; align-self: center; position: relative; z-index: 1; width: max-content; padding-inline-end: 4px; background: var(--mt-night); font-size: 12px; font-weight: 700; color: var(--mt-night-muted); }
.cp-mt-pitch-lo { grid-row: 3; }
.cp-mt-col { grid-row: 1 / -1; display: grid; grid-template-rows: subgrid; justify-items: center; position: relative; z-index: 1; }
.cp-mt-bulb { grid-row: 3; align-self: center; width: 18px; height: 18px; border-radius: 99px; background: var(--mt-bulb-off); transition: background-color .12s, box-shadow .12s; }
.cp-mt-col[data-high] .cp-mt-bulb { grid-row: 1; }
.cp-mt-col b { grid-row: 4; align-self: end; font-size: clamp(13px, 1.4vw, 15px); font-weight: 600; color: var(--mt-night-muted); white-space: nowrap; transition: color .12s; }
.cp-mt-col[data-on] .cp-mt-bulb { background: var(--mt-night-gold); box-shadow: 0 0 14px var(--mt-night-gold), 0 0 4px #fff; }
.cp-mt-col[data-on] b { color: var(--mt-night-gold); }
.cp-mt-play { display: inline-flex; align-items: center; gap: 14px; min-height: 60px; margin: 30px auto; padding: 10px 26px 10px 10px; border-radius: 99px; background: var(--mt-night-gold); color: #1b1418; font-size: 18px; font-weight: 800; white-space: nowrap; cursor: pointer; }
.cp-mt-stage { display: flex; flex-direction: column; }
.cp-mt-play-icon { position: relative; flex: none; width: 40px; height: 40px; border-radius: 99px; background: #1b1418; }
.cp-mt-play-icon::before { content: ""; position: absolute; inset: 13px auto auto 16px; border-block: 7px solid transparent; border-inline-start: 11px solid var(--mt-night-gold); }
.cp-mt-play[aria-pressed="true"] .cp-mt-play-icon::before { inset: 14px auto auto 14px; width: 12px; height: 12px; border: 0; background: var(--mt-night-gold); }
.cp-mt-stop, .cp-mt-play[aria-pressed="true"] .cp-mt-go { display: none; }
.cp-mt-play[aria-pressed="true"] .cp-mt-stop { display: inline; }
@media (prefers-reduced-motion: no-preference) {
    .cp-mt-play:not([data-played])[aria-pressed="false"] { animation: cp-mt-breathe 2.6s ease-in-out infinite; }
}
@keyframes cp-mt-breathe { 0%, 100% { box-shadow: 0 0 0 0 color-mix(in srgb, var(--mt-night-gold) 45%, transparent); } 50% { box-shadow: 0 0 0 10px transparent; } }
.cp-mt-foot { display: flex; justify-content: space-around; align-items: center; height: 14px; padding-inline: 40px; background: linear-gradient(var(--mt-apron), var(--mt-apron-d)); }
.cp-mt-frame .cp-mt-foot i { width: 6px; height: 6px; box-shadow: 0 -4px 10px var(--mt-lamp); }
.cp-mt-deck { display: grid; gap: 28px 36px; padding: 32px clamp(18px, 3vw, 40px) 36px; background: var(--mt-night-2); }
@media (min-width: 860px) { .cp-mt-deck { grid-template-columns: minmax(0, 1fr) minmax(0, 1.1fr); } }
.cp-mt-deck-lead { font-size: 16px; line-height: 1.65; color: var(--mt-night-body); text-wrap: pretty; }
.cp-mt-frame .s-cite a { color: var(--mt-night-gold); }
.cp-mt-controls { display: grid; gap: 18px; }
.cp-mt-tempo { display: grid; gap: 6px; }
.cp-mt-tempo-top { display: flex; justify-content: space-between; gap: 12px; font-size: 14px; color: var(--mt-night-muted); }
.cp-mt-tempo-top output { color: var(--mt-night-gold); font-weight: 700; }
.cp-mt-tempo input { width: 100%; min-height: 44px; accent-color: #f08a7a; }
.cp-mt-ends { display: flex; justify-content: space-between; gap: 12px; margin-top: -6px; font-size: 13px; color: var(--mt-night-muted); }
.cp-mt-style legend { margin-bottom: 10px; font-size: 11px; font-weight: 700; letter-spacing: .2em; text-transform: uppercase; color: var(--mt-night-muted); }
.cp-mt-chips { display: flex; flex-wrap: wrap; gap: 8px; }
.cp-mt-chip { display: inline-flex; align-items: center; gap: 8px; min-height: 44px; padding: 0 16px; border-radius: 99px; border: 1.5px solid var(--mt-night-rule); color: #fff; font-size: 14px; font-weight: 600; white-space: nowrap; cursor: pointer; }
.cp-mt-chip[aria-pressed="true"] { border-color: var(--mt-night-gold); background: color-mix(in srgb, var(--mt-night-gold) 16%, transparent); }
.cp-mt-tick { width: 14px; height: 14px; flex: none; border-radius: 99px; border: 1.5px solid #fff; }
.cp-mt-chip[aria-pressed="true"] .cp-mt-tick { border-color: var(--mt-night-gold); background: var(--mt-night-gold); box-shadow: inset 0 0 0 2px var(--mt-night-2); }
.cp-mt-say { font-size: 15px; font-weight: 700; color: var(--mt-night-gold); }
.cp-mt-demo-note { font-size: 12.5px; line-height: 1.6; color: var(--mt-night-muted); }
@media (prefers-reduced-motion: reduce) { .cp-mt-bulb, .cp-mt-col b { transition: none; } .cp-mt-col[data-on] .cp-mt-bulb { box-shadow: none; } }
:root[data-skin="game"] body.s-arcade .cp-mt-frame { border-radius: 0; box-shadow: 6px 6px 0 var(--a-pink); }
:root[data-skin="game"] body.s-arcade .cp-mt-frame > * { border-radius: 0; }
:root[data-skin="game"] body.s-arcade :is(.cp-mt-play, .cp-mt-play-icon, .cp-mt-chip, .cp-mt-tick, .cp-mt-bulb) { border-radius: 0; }
:root[data-skin="game"] body.s-arcade .cp-mt-play { text-transform: uppercase; box-shadow: 4px 4px 0 #05030d; font-family: var(--a-hud); font-size: 12px; font-weight: 400; font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade :is(.cp-mt-stagebar, .cp-mt-style legend) { font-family: var(--a-hud); font-size: 9px; font-weight: 400; letter-spacing: .06em; font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade .cp-mt-chip { font: 400 10px/1.4 var(--a-hud); font-size-adjust: var(--arc-ex, none); }
@media (prefers-reduced-motion: no-preference) {
    :root[data-skin="game"] body.s-arcade .cp-mt-play:not([data-played])[aria-pressed="false"] { animation: none; }
    :root[data-skin="game"] body.s-arcade .cp-mt-play[aria-pressed="false"] .cp-mt-go { animation: s-demo-blink 1.1s steps(2, start) infinite; }
}

/* The story: the heading held beside dated rows. */
.cp-mt-story { display: grid; gap: 28px 48px; padding-block: clamp(56px, 8vw, 96px); }
@media (min-width: 960px) { .cp-mt-story { grid-template-columns: minmax(0, 1fr) minmax(0, 2fr); align-items: start; } .cp-mt-side { position: sticky; top: 110px; } }
.cp-mt-years-wrap { border-top: 2px solid var(--mt-ink); }
.cp-mt-years li { display: grid; gap: 8px 24px; padding: 28px 0; border-bottom: 1px solid var(--mt-rule); }
@media (min-width: 640px) { .cp-mt-years li { grid-template-columns: minmax(0, 150px) minmax(0, 1fr); } }
.cp-mt-year { font-family: var(--mt-serif); font-style: italic; font-size: clamp(38px, 4vw, 48px); line-height: 1; color: var(--mt-red); font-variant-numeric: lining-nums; }
.cp-mt-years h3 { font-family: var(--mt-serif); font-weight: 600; font-size: clamp(21px, 2.2vw, 24px); line-height: 1.2; }
.cp-mt-years h3 + p { margin-top: 10px; max-width: 62ch; font-size: 16px; line-height: 1.65; color: var(--mt-body); text-wrap: pretty; }
:root[data-skin="game"] body.s-arcade .cp-mt-year { font: 400 15px/1.4 var(--a-hud); font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade :is(.cp-mt-years h3, .cp-mt-card h3, .cp-mt-act h3, .cp-mt-cast-top b) { font-family: var(--font-sans); font-weight: 750; font-size-adjust: var(--arc-ex, none); }

/* A fold: on a phone the rest of a long list waits under its line; open from 900 px. */
.cp-mt-more summary { display: flex; align-items: center; justify-content: space-between; gap: 12px; min-height: 52px; border-bottom: 1px solid var(--mt-rule); font-size: 14px; font-weight: 600; color: var(--mt-red); list-style: none; cursor: pointer; }
.cp-mt-more summary::-webkit-details-marker, .cp-mt-sources summary::-webkit-details-marker { display: none; }
.cp-mt-sign::before { content: "+"; font-size: 18px; font-weight: 400; }
details[open] > summary .cp-mt-sign::before { content: "\2212"; }
@media (min-width: 900px) { .cp-mt-more > summary { display: none; } }

/* The overture: a dark band, four numbered columns ruled in gold. */
.cp-mt-overture { padding-block: clamp(64px, 8vw, 96px); background: var(--mt-night); color: var(--mt-night-ink); }
.cp-mt-overture .cp-mt-kick { color: var(--mt-night-gold); }
.cp-mt-aims { display: grid; gap: 32px; margin-top: 44px; }
@media (min-width: 640px) { .cp-mt-aims { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (min-width: 1040px) { .cp-mt-aims { grid-template-columns: repeat(4, minmax(0, 1fr)); } }
.cp-mt-aims li { padding-top: 20px; border-top: 1px solid var(--mt-night-gold); }
.cp-mt-aim-n { font-family: var(--mt-serif); font-style: italic; font-size: 22px; color: var(--mt-night-gold); }
.cp-mt-aim-n + p { margin-top: 14px; font-size: 17px; line-height: 1.55; color: var(--mt-night-body); }
:root[data-skin="game"] body.s-arcade .cp-mt-aim-n { font: 400 12px/1.4 var(--a-hud); font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade :is(.cp-mt-overture, .cp-mt-band) .cp-mt-title em { color: var(--a-yellow); }

/* The running order: one ruled frame, a column an act, its lessons linked. */
.cp-mt-order { padding-block: clamp(64px, 8vw, 96px); background: var(--mt-alt); }
.cp-mt-orderhead { display: flex; flex-wrap: wrap; align-items: flex-end; justify-content: space-between; gap: 16px; margin-bottom: 44px; }
.cp-mt-count { font-size: 14px; color: var(--mt-muted); }
.cp-mt-acts { display: grid; border: 1px solid var(--mt-ink); }
@media (min-width: 640px) { .cp-mt-acts { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (min-width: 1040px) { .cp-mt-acts { grid-template-columns: repeat(4, minmax(0, 1fr)); } }
.cp-mt-act { padding: 28px 24px; border-bottom: 1px solid var(--mt-rule); }
@media (min-width: 640px) { .cp-mt-act:nth-child(odd) { border-inline-end: 1px solid var(--mt-rule); } }
@media (min-width: 1040px) { .cp-mt-act { border-bottom: 0; border-inline-end: 1px solid var(--mt-rule); } .cp-mt-act:last-child { border-inline-end: 0; } }
.cp-mt-numeral { font-family: var(--mt-serif); font-weight: 800; font-size: 56px; line-height: .9; color: var(--mt-red); }
.cp-mt-act-name { margin-top: 14px; font-size: 11px; font-weight: 700; letter-spacing: .24em; text-transform: uppercase; white-space: nowrap; }
.cp-mt-act h3 { margin-top: 6px; font-family: var(--mt-serif); font-weight: 600; font-size: 24px; line-height: 1.15; }
.cp-mt-act-say { margin-top: 10px; font-size: 14.5px; line-height: 1.55; color: var(--mt-muted); }
.cp-mt-lessons { margin-top: 20px; font-size: 15px; }
.cp-mt-lessons li { display: flex; align-items: center; justify-content: space-between; gap: 8px; border-top: 1px solid var(--mt-rule); }
.cp-mt-lessons :is(a, span:first-child) { display: flex; align-items: center; min-height: 44px; padding-block: 6px; }
.cp-mt-lessons a { color: var(--mt-ink); text-decoration: underline; text-decoration-color: transparent; text-underline-offset: 4px; }
.cp-mt-lessons a:hover { color: var(--mt-red); text-decoration-color: currentColor; }
.cp-mt-song :is(a, span:first-child) { font-family: var(--mt-serif); font-style: italic; font-size: 17px; }
.cp-mt-start { flex: none; padding: 3px 8px; border-radius: 99px; background: var(--mt-start); color: #fff; font-size: 10px; font-weight: 800; letter-spacing: .12em; text-transform: uppercase; white-space: nowrap; }
:root[data-skin="game"] body.s-arcade .cp-mt-order { background: transparent; }
:root[data-skin="game"] body.s-arcade .cp-mt-acts { border: 2px solid var(--a-cyan); box-shadow: 6px 6px 0 var(--a-pink); background: var(--a-panel); }
:root[data-skin="game"] body.s-arcade .cp-mt-numeral { font-family: var(--a-display); font-weight: 400; font-size: 44px; font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade .cp-mt-act-name { font: 400 9.5px/1.6 var(--a-hud); letter-spacing: .06em; color: var(--a-cyan); font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade .cp-mt-song :is(a, span:first-child) { font-family: inherit; font-style: normal; font-weight: 700; font-size: inherit; font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"][data-theme$="-light"] body.s-arcade .cp-mt-start { color: #fff; }
:root[data-skin="game"] body.s-arcade .cp-mt-start { border-radius: 0; color: #07060e; font: 400 8.5px/1.5 var(--a-hud); letter-spacing: .04em; font-size-adjust: var(--arc-ex, none); }

/* The science, by seat: ruled cards two across; the course's own card is yours. */
.cp-mt-science { padding-block: clamp(64px, 8vw, 96px); }
.cp-mt-scihead { display: grid; gap: 18px 48px; align-items: end; margin-bottom: 44px; }
@media (min-width: 900px) { .cp-mt-scihead { grid-template-columns: minmax(0, 1.6fr) minmax(0, 1fr); } }
.cp-mt-scilead { font-size: 16px; line-height: 1.6; color: var(--mt-muted); }
.cp-mt-cards { display: grid; gap: 0 48px; }
@media (min-width: 760px) { .cp-mt-cards { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
.cp-mt-card { padding: 24px 0 36px; border-top: 2px solid var(--mt-ink); }
.cp-mt-tier { font-size: 11px; font-weight: 700; letter-spacing: .2em; text-transform: uppercase; color: var(--mt-red); }
.cp-mt-card h3 { margin-top: 10px; font-family: var(--mt-serif); font-weight: 600; font-size: clamp(24px, 2.6vw, 28px); line-height: 1.15; }
.cp-mt-card h3 + p { margin-top: 12px; font-size: 16px; line-height: 1.65; color: var(--mt-body); text-wrap: pretty; }
.cp-mt-card-ours { align-self: start; margin-bottom: 36px; padding: 24px 26px 30px; border: 1.5px solid var(--mt-red); background: var(--mt-tint); }
.cp-mt-science .cp-mt-more > .cp-mt-cards { margin-top: 28px; }
@media (min-width: 900px) { .cp-mt-science .cp-mt-more > .cp-mt-cards { margin-top: 0; } }
:root[data-skin="game"] body.s-arcade .cp-mt-tier { font: 400 9px/1.6 var(--a-hud); letter-spacing: .06em; font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade .cp-mt-card-ours { border: 2px solid var(--a-pink); box-shadow: 4px 4px 0 var(--arc-shadow-c, #05030d); }

/* Backstage: what the app listens for in a ruled box, the notes pinned to the call-board. */
.cp-mt-band { padding-block: clamp(64px, 8vw, 96px); background: var(--mt-night-2); color: var(--mt-night-ink); }
.cp-mt-band-grid { display: grid; gap: 48px 56px; }
@media (min-width: 960px) { .cp-mt-band-grid { grid-template-columns: minmax(0, 1fr) minmax(0, 1.15fr); align-items: start; } }
.cp-mt-band .cp-mt-kick, .cp-mt-band .cp-mt-more summary { color: var(--mt-night-gold); }
.cp-mt-listens { margin-top: 36px; padding: 26px 28px; border: 1px solid var(--mt-night-rule); }
.cp-mt-listens p { margin-top: 14px; font-size: 17px; line-height: 1.65; color: var(--mt-night-body); text-wrap: pretty; }
.cp-mt-board-kick { margin-bottom: 14px; font-size: 11px; font-weight: 700; letter-spacing: .24em; text-transform: uppercase; color: var(--mt-night-muted); }
.cp-mt-board { display: grid; gap: 12px; }
.cp-mt-board li { padding: 22px 24px; background: var(--mt-pin); color: var(--mt-paper-ink); font-size: 16px; line-height: 1.6; rotate: -.6deg; }
.cp-mt-board li:nth-child(even) { rotate: .5deg; }
.cp-mt-board .s-cite a { color: #a3202f; }
.cp-mt-band .cp-mt-more summary { border-color: var(--mt-night-rule); }
.cp-mt-band .cp-mt-more > .cp-mt-board { margin-top: 12px; }
:root[data-skin="game"] body.s-arcade .cp-mt-board li { rotate: 0deg; border: 2px solid var(--a-yellow); background: #12101e; color: #f7f4ff; box-shadow: 4px 4px 0 #05030d; }
:root[data-skin="game"] body.s-arcade .cp-mt-board .s-cite a { color: #ffd84a; }

/* The company: a cast list, each name's dotted leader running to the part. */
.cp-mt-companysec { padding-block: clamp(64px, 9vw, 104px); background: var(--mt-alt); }
:root[data-skin="game"] body.s-arcade .cp-mt-companysec { background: transparent; }
.cp-mt-narrow { max-width: 868px; }
.cp-mt-companysec .cp-mt-kick, .cp-mt-companysec .cp-mt-title { text-align: center; }
.cp-mt-companysec > div > .cp-mt-orn { justify-content: center; margin: 18px 0 30px; }
.cp-mt-companysec > div > .cp-mt-orn::before, .cp-mt-companysec > div > .cp-mt-orn::after { content: none; }
.cp-mt-cast li { padding: 18px 0; border-bottom: 1px solid var(--mt-rule); }
.cp-mt-cast-top { display: flex; flex-wrap: wrap; align-items: baseline; gap: 4px 12px; }
.cp-mt-cast-top b { font-family: var(--mt-serif); font-weight: 600; font-size: clamp(20px, 2.4vw, 24px); }
.cp-mt-leader { flex: 1 1 24px; min-width: 24px; translate: 0 -5px; border-bottom: 2px dotted var(--mt-leader); }
.cp-mt-cast-top i { font-family: var(--mt-serif); font-style: italic; font-size: 18px; color: var(--mt-red); text-align: end; }
.cp-mt-cast-more { display: flex; flex-wrap: wrap; gap: 4px 16px; margin-top: 6px; font-size: 14.5px; line-height: 1.55; color: var(--mt-muted); }
.cp-mt-cast-years { min-width: 110px; font-weight: 600; color: var(--mt-ink); font-variant-numeric: tabular-nums; }
.cp-mt-cast-more > span:last-child { flex: 1 1 300px; }
:root[data-skin="game"] body.s-arcade .cp-mt-cast-top i { font-family: inherit; font-style: normal; font-weight: 700; font-size: 14px; font-size-adjust: var(--arc-ex, none); }

/* Before you begin: three ruled columns, then the musical numbers in a double-ruled box. */
.cp-mt-begin { padding-block: clamp(64px, 8vw, 96px) 0; }
.cp-mt-begin-grid { display: grid; gap: 40px; margin-top: 48px; }
@media (min-width: 900px) { .cp-mt-begin-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); } }
.cp-mt-colhead { padding-bottom: 12px; border-bottom: 2px solid var(--mt-ink); font-size: 12px; font-weight: 700; letter-spacing: .2em; text-transform: uppercase; }
.cp-mt-ticks li { display: grid; grid-template-columns: 16px minmax(0, 1fr); gap: 12px; padding: 14px 0; border-bottom: 1px solid var(--mt-rule); font-size: 15.5px; line-height: 1.5; }
.cp-mt-ticks svg { margin-top: 3px; color: var(--mt-red); }
.cp-mt-warn i { font-style: normal; font-weight: 800; color: var(--mt-red); text-align: center; }
.cp-mt-numbers { margin-top: 64px; padding: 28px clamp(18px, 3vw, 32px); border: 1px solid var(--mt-ink); outline: 4px double var(--mt-ink); outline-offset: 4px; background: var(--mt-alt); }
.cp-mt-numbers .cp-mt-colhead { padding: 0; border: 0; text-align: center; }
.cp-mt-numbers ul { display: grid; gap: 20px 32px; margin-top: 22px; }
@media (min-width: 640px) { .cp-mt-numbers ul { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (min-width: 1040px) { .cp-mt-numbers ul { grid-template-columns: repeat(4, minmax(0, 1fr)); } }
.cp-mt-numbers b { display: block; font-family: var(--mt-serif); font-style: italic; font-weight: 400; font-size: 21px; line-height: 1.3; }
.cp-mt-numbers li span { display: block; margin-top: 4px; font-size: 13.5px; color: var(--mt-muted); }
.cp-mt-numbers > p { margin-top: 22px; font-size: 13px; color: var(--mt-muted); text-align: center; }
:root[data-skin="game"] body.s-arcade .cp-mt-numbers { outline: none; border: 2px solid var(--a-cyan); box-shadow: 6px 6px 0 var(--a-pink); background: var(--a-panel); }
:root[data-skin="game"] body.s-arcade .cp-mt-numbers b { font-family: inherit; font-style: normal; font-weight: 700; font-size: 16px; font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade :is(.cp-mt-colhead, .cp-mt-board-kick) { font: 400 9.5px/1.6 var(--a-hud); letter-spacing: .06em; font-size-adjust: var(--arc-ex, none); }

/* The interval: the questions beside their heading, each a Bodoni line with a round sign. */
.cp-mt-fine { display: grid; gap: 28px 48px; padding-block: clamp(56px, 7vw, 80px) clamp(64px, 9vw, 104px); }
@media (min-width: 960px) { .cp-mt-fine { grid-template-columns: minmax(0, 1fr) minmax(0, 2fr); } }
.cp-mt .cp-faq { margin-top: 0; max-width: none; border-top: 2px solid var(--mt-ink); }
.cp-mt .cp-faq details { border-color: var(--mt-rule); }
.cp-mt .cp-faq summary { padding-block: 22px; font-family: var(--mt-serif); font-weight: 600; font-size: clamp(19px, 2vw, 22px); }
.cp-mt .cp-faq-sign { width: 32px; height: 32px; background: transparent; border: 1px solid var(--mt-ink); }
.cp-mt .cp-faq details p { margin-top: -6px; padding-bottom: 24px; max-width: 680px; font-size: 16.5px; line-height: 1.65; color: var(--mt-body); }
:root[data-skin="game"] body.s-arcade .cp-mt .cp-faq summary { font-family: var(--font-sans); font-weight: 750; font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade .cp-mt .cp-faq-sign { border-radius: 0; }

/* The curtain call: a dark stage between curtains, the valance above and the footlights below. */
.cp-mt-close { position: relative; overflow: hidden; background: var(--mt-night); color: var(--mt-night-ink); }
.cp-mt-close .cp-mt-valance { position: relative; height: 40px; background: radial-gradient(circle at 50% 0, var(--mt-curtain) 20px, transparent 21px) 0 0 / 44px 36px repeat-x, linear-gradient(var(--mt-curtain-m), var(--mt-curtain-m)) 0 0 / 100% 14px no-repeat; }
.cp-mt-drape { position: absolute; inset-block: 0; inset-inline-start: 0; width: 12%; background: repeating-linear-gradient(90deg, var(--mt-curtain-d) 0, var(--mt-curtain) 14px, var(--mt-curtain-m) 28px); border-end-end-radius: 60% 30%; }
.cp-mt-drape-r { inset-inline: auto 0; background: repeating-linear-gradient(90deg, var(--mt-curtain-m) 0, var(--mt-curtain) 14px, var(--mt-curtain-d) 28px); border-end-end-radius: 0; border-end-start-radius: 60% 30%; }
.cp-mt-close-in { position: relative; display: grid; justify-items: center; width: min(900px, 100% - 24% - 32px); padding-block: 72px 80px; padding-inline: 0; text-align: center; }
.cp-mt-close .cp-mt-kick, .cp-mt-close .cp-mt-title em { color: var(--mt-night-gold); }
.cp-mt-close .cp-mt-title { margin-top: 20px; font-size: clamp(40px, 6vw, 84px); line-height: .98; }
.cp-mt-close-body { margin-top: 24px; max-width: 560px; font-size: 18px; line-height: 1.6; color: var(--mt-night-body); }
.cp-mt-close .cp-mt-btns { justify-content: center; }
.cp-mt-close .btn-primary { --primary: var(--mt-night-gold); --primary-ink: #1b1418; --primary-hover-to: #fff; }
.cp-mt-close .btn-secondary { --btn-soft: transparent; --btn-soft-hover: rgb(255 255 255 / .1); --btn-soft-active: rgb(255 255 255 / .16); --btn-outline: inset 0 0 0 1.5px var(--mt-night-ink); --btn-outline-pressed: inset 0 0 0 1.5px var(--mt-night-ink); color: var(--mt-night-ink); }
.cp-mt-close-note { margin-top: 18px; font-size: 14px; color: var(--mt-night-muted); }
.cp-mt-related-h { margin-top: 44px; font-size: 11px; }
.cp-mt-close .cp-related { justify-content: center; }
.cp-mt-close .cp-related a { background: transparent; border: 1px solid var(--mt-night-rule); color: var(--mt-night-ink); white-space: nowrap; }
.cp-mt-close .cp-related a:hover { border-color: var(--mt-night-gold); }
.cp-mt-close .cp-related-all { display: none; }
.cp-mt-close .cp-mt-foot { position: relative; height: 18px; padding-inline: 14%; }
.cp-mt-close .cp-mt-foot i { box-shadow: 0 -6px 16px var(--mt-lamp); }
@media (max-width: 639px) { .cp-mt-drape { width: 8%; } .cp-mt-close-in { width: calc(100% - 16% - 24px); } }
/* A narrow phone: the curtains a strip each, so the call and its buttons keep the page's own gutters. */
@media (max-width: 400px) { .cp-mt-drape { width: 10px; } .cp-mt-close-in { width: calc(100% - 28px); } }
.cp-mt-close-in { grid-template-columns: minmax(0, 1fr); }
:root[data-skin="game"] body.s-arcade .cp-mt-close .btn-primary { --primary: #ffd84a; }
:root[data-skin="game"] body.s-arcade .cp-mt-close .cp-related a { border-radius: 0; }

/* The sources, two columns, folded on a phone. */
.cp-mt-sources { padding-block: 72px 56px; }
.cp-mt-sources summary { display: flex; align-items: center; gap: 12px; min-height: 44px; list-style: none; cursor: pointer; color: var(--mt-red); }
.cp-mt-sources summary h2 span { letter-spacing: .1em; }
@media (min-width: 900px) { .cp-mt-sources summary .cp-mt-sign { display: none; } }
.cp-mt-sources ol { margin-top: 18px; padding-inline-start: 30px; list-style: decimal; columns: 2 420px; column-gap: 48px; font-size: 14px; line-height: 1.5; color: var(--mt-muted); }
.cp-mt-sources li { padding-block: 4px; break-inside: avoid; scroll-margin-top: 90px; }
.cp-mt-sources a { color: var(--mt-ink); text-decoration: underline; text-decoration-color: var(--mt-leader); text-underline-offset: 3px; overflow-wrap: anywhere; }

/* Scat singing (site/courses/scat): a jazz record, after Hillel's design of 2026-11-18 (course-designs/scat). A 1920s
   Chicago display face (Big Shoulders Display) for headlines, an italic serif (Instrument Serif) for syllables and
   liner notes, the site's sans for reading, and a typewriter mono for the small print. One colour code: the twelve-bar
   card's chords, I ochre (home), IV blue (away), V red (the turn back), each with its numeral or a word beside it, on
   the units' sleeves, the outcomes' numbers and the story's record labels (--sc-i, --sc-iv, --sc-v, their ink on top
   (-on) and their shade for words on the page (-text); the fourth sleeve and number are ink). Calm light is the paper
   sleeve, calm dark the same record in a dark room (the ink sleeve turns cream), game dark the arcade's night with the
   chords in neon; game light keeps the light palette with the arcade's type and square frames. Sounds:
   js/public/scat.js. The page's ground runs under the footer (body:has), and the lesson list below it is left out
   (the sleeves link every lesson). */
:is(.cp-sc, body:has(.cp-sc)) {
    --sc-paper: #f8f4ee; --sc-paper-2: #efe8dd; --sc-ink: #1d1915; --sc-body: #3d3731; --sc-body-2: #4a433c; --sc-muted: #5c544b;
    --sc-rule: rgb(29 25 21 / .14); --sc-staff: rgb(29 25 21 / .12); --sc-label: #9a3b12;
    --sc-night: #1d1915; --sc-night-2: #13100d; --sc-night-ink: #f8f4ee; --sc-night-body: #cfc9c0; --sc-night-muted: #a8a29a; --sc-night-rule: rgb(248 244 238 / .16);
    --sc-gold: #ebb353; --sc-and: #f66e5c; --sc-rec: #e95145; --sc-sleeve: #1d1915; --sc-sleeve-edge: transparent;
    --sc-i: #dea645; --sc-i-on: #1d1915; --sc-i-text: #9c6a00;
    --sc-iv: #1a609e; --sc-iv-on: #fff; --sc-iv-text: #1a609e;
    --sc-v: #ba3728; --sc-v-on: #fff; --sc-v-text: #c44132;
    --sc-ink-fill: #1d1915; --sc-ink-on: #f8f4ee; --sc-ink-text: #1d1915;
    --sc-ochre: #ebb353; --sc-ochre-ink: #1d1915; --sc-ochre-stop: #a62f1e;
    --sc-display: 'Big Shoulders Display', 'Arial Narrow', 'Roboto Condensed', 'Helvetica Neue', Impact, sans-serif;
    --sc-serif: 'Instrument Serif', 'Iowan Old Style', Georgia, 'Times New Roman', serif;
    --sc-mono: ui-monospace, 'SF Mono', Menlo, Consolas, monospace;
}
:root:not([data-theme$="-light"]) :is(.cp-sc, body:has(.cp-sc)) {
    --sc-paper: #15120f; --sc-paper-2: #1e1a16; --sc-ink: #f3ede4; --sc-body: #d8d0c4; --sc-body-2: #cdc4b7; --sc-muted: #b5ab9e;
    --sc-rule: rgb(243 237 228 / .14); --sc-staff: rgb(243 237 228 / .14); --sc-label: #f0a878;
    --sc-night: #0c0a08; --sc-night-2: #050403; --sc-sleeve: #26211c; --sc-sleeve-edge: rgb(243 237 228 / .1);
    --sc-i-text: #ebb353; --sc-iv: #2265a8; --sc-iv-text: #8fb6e0; --sc-v-text: #f08470;
    --sc-ink-fill: #ece5da; --sc-ink-on: #1d1915; --sc-ink-text: #f3ede4;
}
:root[data-skin="game"]:not([data-theme$="-light"]) :is(.cp-sc, body:has(.cp-sc)) {
    --sc-paper: var(--a-bg, #0c0820); --sc-paper-2: var(--a-panel, #12101e); --sc-ink: #f7f4ff; --sc-body: #d2ccf0; --sc-body-2: #d2ccf0; --sc-muted: #b8b2d8;
    --sc-rule: #2a2640; --sc-staff: #2f2a4f; --sc-label: #3be7ff;
    --sc-night: #07051a; --sc-night-2: #030210; --sc-gold: #ffd84a; --sc-and: #ff5fd2; --sc-rec: #ff5fd2; --sc-sleeve: var(--a-panel, #12101e);
    --sc-i: #ffd84a; --sc-i-on: #1a1400; --sc-i-text: #ffd84a;
    --sc-iv: #3be7ff; --sc-iv-on: #001a20; --sc-iv-text: #3be7ff;
    --sc-v: #ff5fd2; --sc-v-on: #1a0414; --sc-v-text: #ff5fd2;
    --sc-ink-fill: #f7f4ff; --sc-ink-on: #12082a; --sc-ink-text: #f7f4ff;
    --sc-ochre: #ffd84a; --sc-ochre-ink: #1a1400; --sc-ochre-stop: #c4127f;
}
body:has(.cp-sc) { background-color: var(--sc-paper); }
.cp-sc { color: var(--sc-ink); --cp-a: var(--sc-label); --cp-a-text: var(--sc-label); --cp-line: var(--sc-rule); }
.cp-sc ~ [data-lesson-pages], [data-lesson-pages][data-course="scat"] { display: none; }
.cp-sc :is(a, button, summary):focus-visible { outline: 3px solid var(--sc-label); outline-offset: 3px; }
.cp-sc :is(.cp-sc-demosec, .cp-sc-band) :is(a, button, summary):focus-visible { outline-color: var(--sc-gold); }
.cp-sc-close :is(a, button):focus-visible { outline-color: var(--sc-ochre-ink); }

/* Type: the condensed display, the italic serif, the typewriter labels. */
.cp-sc-display { font-family: var(--sc-display); font-weight: 900; text-transform: uppercase; letter-spacing: -.01em; }
.cp-sc-serif { font-family: var(--sc-serif); font-style: italic; font-weight: 400; }
.cp-sc-mono { font-family: var(--sc-mono); font-weight: 600; letter-spacing: .12em; text-transform: uppercase; }
.cp-sc-kick { margin: 0; font: 600 12px/1.5 var(--sc-mono); letter-spacing: .18em; text-transform: uppercase; color: var(--sc-label); }
.cp-sc-h2 { margin: 14px 0 0; font-size: clamp(46px, 6vw, 80px); line-height: .9; text-wrap: balance; }
.cp-sc-body { margin-top: 20px; max-width: 42ch; font-size: 17px; line-height: 1.6; color: var(--sc-body); text-wrap: pretty; }
.cp-sc .s-cite a { color: var(--sc-label); }
.cp-sc-btns { display: flex; flex-wrap: wrap; gap: 12px; }
@media (max-width: 599px) { .cp-sc-btns { flex-direction: column; align-items: stretch; } .cp-sc-btns > a { justify-content: center; } }

/* The hero: the words, then the record (its sleeve, the disc peeking out). */
.cp-sc-hero { border-top: 1px solid var(--sc-rule); overflow: hidden; }
.cp-sc-hero-in { display: grid; gap: 56px; padding-block: 28px 72px; }
@media (min-width: 960px) { .cp-sc-hero-in { grid-template-columns: minmax(0, 1.05fr) minmax(0, .95fr); align-items: center; padding-block: 44px 96px; } }
.cp-sc-hero-words { display: flex; flex-direction: column; gap: 26px; min-width: 0; }
.cp-sc-hero-words .s-crumb { margin: 0; }
.cp-sc-eyebrow { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 14px; }
.cp-sc-cat { padding: 5px 9px; border-radius: 3px; background: var(--sc-ink); color: var(--sc-paper); letter-spacing: .12em; }
.cp-sc-h1 { margin: 0; font-size: clamp(76px, 12vw, 168px); line-height: .82; text-wrap: balance; }
.cp-sc-stop { color: var(--sc-v-text); }
.cp-sc-syls { display: flex; flex-wrap: wrap; align-items: flex-end; gap: 14px 22px; }
.cp-sc-syls li { display: flex; flex-direction: column; gap: 6px; }
.cp-sc-syls .cp-sc-serif { font-size: 34px; line-height: 1; }
.cp-sc-syls .cp-sc-mono { font-size: 10px; color: var(--sc-muted); }
.cp-sc-syl-bar { height: 8px; width: 104px; border-radius: 2px; background: var(--sc-i); }
.cp-sc-syl-1 .cp-sc-syl-bar { width: 52px; background: var(--sc-v); }
.cp-sc-syl-2 .cp-sc-syl-bar { width: 34px; background: var(--sc-ink); }
.cp-sc-syl-2 .cp-sc-serif::after { content: "."; color: var(--sc-v-text); }
.cp-sc-lead { max-width: 540px; font-size: 19px; line-height: 1.6; color: var(--sc-body); text-wrap: pretty; }
.cp-sc-quiet { font-size: 14.5px; color: var(--sc-muted); }
.cp-sc-facts { display: flex; flex-wrap: wrap; gap: 6px 22px; font-size: 14px; color: var(--sc-muted); }
.cp-sc-facts li + li { display: flex; align-items: center; gap: 22px; }
.cp-sc-facts li + li::before { content: ""; width: 1px; height: 14px; background: var(--sc-rule); }
@media (max-width: 599px) { .cp-sc-facts { flex-direction: column; gap: 4px; } .cp-sc-facts li + li::before { display: none; } }
.cp-sc-record { position: relative; margin: 0; padding-right: min(12%, 70px); min-width: 0; }
.cp-sc-disc { position: absolute; right: 0; top: 4%; width: 80%; aspect-ratio: 1; display: grid; place-items: center; border-radius: 50%;
    background: radial-gradient(closest-side, transparent 60%, rgb(255 255 255 / .05) 72%, transparent 84%), repeating-radial-gradient(circle, #161310 0 1.5px, #221d19 1.5px 3.5px);
    box-shadow: 0 20px 50px rgb(0 0 0 / .25), inset 0 0 0 1px rgb(255 255 255 / .06); }
:root:not([data-theme$="-light"]) .cp-sc-disc { background: radial-gradient(closest-side, transparent 60%, rgb(255 255 255 / .07) 72%, transparent 84%), repeating-radial-gradient(circle, #241f1b 0 1.5px, #3a332c 1.5px 3.5px); box-shadow: 0 20px 50px rgb(0 0 0 / .5), inset 0 0 0 1px rgb(255 255 255 / .14); }
.cp-sc-disc-label { display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 2px; width: 34%; aspect-ratio: 1; border-radius: 50%; background: var(--sc-v); color: var(--sc-v-on); text-align: center; }
.cp-sc-disc-label b { font-size: clamp(11px, 1.4vw, 15px); font-weight: 800; letter-spacing: .08em; }
.cp-sc-disc-label .cp-sc-mono { font-size: clamp(6px, .7vw, 8px); font-weight: 500; letter-spacing: .1em; }
.cp-sc-disc-label i { width: 8px; height: 8px; margin-top: 6px; border-radius: 50%; background: var(--sc-paper); }
.cp-sc-sleeve12 { position: relative; display: flex; flex-direction: column; gap: 16px; padding: clamp(16px, 3vw, 30px); background: var(--sc-sleeve); color: #f8f4ee; box-shadow: 0 30px 60px rgb(29 25 21 / .28), inset 0 0 0 1px var(--sc-sleeve-edge); }
@media (min-width: 600px) { .cp-sc-sleeve12 { aspect-ratio: 1; } }
.cp-sc-sleeve12-top { display: flex; justify-content: space-between; gap: 12px; font-size: 10px; letter-spacing: .16em; color: #b9b4ad; }
.cp-sc-sleeve12-h { font-size: clamp(40px, 5.4vw, 64px); line-height: .85; }
.cp-sc-bars { flex: 1; display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); grid-auto-rows: minmax(58px, 1fr); gap: 5px; min-height: 0; }
.cp-sc-job-home { --job: var(--sc-i); --job-on: var(--sc-i-on); --job-text: var(--sc-i-text); }
.cp-sc-job-away { --job: var(--sc-iv); --job-on: var(--sc-iv-on); --job-text: var(--sc-iv-text); }
.cp-sc-job-turn { --job: var(--sc-v); --job-on: var(--sc-v-on); --job-text: var(--sc-v-text); }
.cp-sc-job-ink { --job: var(--sc-ink-fill); --job-on: var(--sc-ink-on); --job-text: var(--sc-ink-text); }
.cp-sc-bar { display: flex; flex-direction: column; justify-content: space-between; gap: 4px; min-width: 0; padding: 7px 8px; background: var(--job); color: var(--job-on); }
.cp-sc-bar > .cp-sc-mono { font-size: 9px; letter-spacing: .08em; }
.cp-sc-bar-chord { display: flex; align-items: baseline; flex-wrap: wrap; gap: 0 5px; }
.cp-sc-bar-chord b { font-size: clamp(20px, 2.4vw, 30px); font-weight: 800; line-height: 1; }
.cp-sc-bar-chord .cp-sc-mono { font-size: 10px; letter-spacing: .04em; }
.cp-sc-legend { display: flex; flex-wrap: wrap; gap: 6px 14px; font-size: 11.5px; color: #d6d0c8; }
.cp-sc-legend li { display: flex; align-items: center; gap: 6px; }
.cp-sc-legend i { width: 10px; height: 10px; background: var(--job); }
.cp-sc-caption { margin-top: 14px; max-width: 440px; font-size: 13px; line-height: 1.5; color: var(--sc-muted); }

/* Straight or swung?: the night band, the deck with the feel's readout and the three feels, the lane of one bar (a
   tile a note: left when it starts, width how long, higher for the higher note; the long notes ochre, the short red,
   the one sounding cream), the counts with each "and" in red, and the one big play. */
.cp-sc-demosec { background: var(--sc-night); color: var(--sc-night-ink); }
.cp-sc-demo-in { display: flex; flex-direction: column; gap: 36px; padding-block: clamp(56px, 8vw, 88px); }
.cp-sc-demo-head { display: grid; gap: 20px 40px; align-items: end; }
@media (min-width: 900px) { .cp-sc-demo-head { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
.cp-sc-demosec .cp-sc-h2 { font-size: clamp(56px, 7vw, 96px); line-height: .85; }
.cp-sc-live { display: flex; align-items: center; gap: 10px; color: var(--sc-gold); }
.cp-sc-rec { width: 8px; height: 8px; flex: none; border-radius: 50%; background: var(--sc-rec); }
.cp-sc-demo-lead { max-width: 520px; font-size: 17px; line-height: 1.6; color: var(--sc-night-body); text-wrap: pretty; }
.cp-sc-deck { display: flex; flex-direction: column; gap: 20px; padding: 24px clamp(14px, 3vw, 36px) 28px; background: var(--sc-night-2); border: 1px solid var(--sc-night-rule); }
.cp-sc-deck-top { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 14px 16px; }
.cp-sc-readout { font-size: 12px; letter-spacing: .14em; color: var(--sc-gold); }
.cp-sc-readout span { display: none; }
[data-feel="straight"] .cp-sc-show-straight, [data-feel="swung"] .cp-sc-show-swung, [data-feel="soloist"] .cp-sc-show-soloist { display: inline; }
.cp-sc-seg { display: flex; gap: 4px; padding: 4px; border-radius: 999px; background: rgb(248 244 238 / .07); }
.cp-sc-seg button { min-height: 44px; padding: 0 18px; border-radius: 999px; font-size: 14px; font-weight: 650; white-space: nowrap; color: var(--sc-night-body); }
.cp-sc-seg button:hover { color: var(--sc-night-ink); }
.cp-sc-seg button[aria-pressed="true"] { background: var(--sc-night-ink); color: var(--sc-night-2); }
@media (max-width: 599px) { .cp-sc-seg { width: 100%; } .cp-sc-seg button { flex: 1; padding: 0 8px; } }
.cp-sc-lane { position: relative; height: clamp(124px, 15vw, 160px); margin: 8px 4px 0; }
.cp-sc-beat { position: absolute; top: 0; bottom: 0; left: calc(var(--x) * 1%); width: 1px; background: var(--sc-night-rule); }
.cp-sc-notes { position: absolute; inset: 0; }
.cp-sc-note { --x: var(--x-swung); --w: var(--w-swung); --th: clamp(50px, 7vw, 64px); position: absolute; left: calc(var(--x) * 1%); bottom: calc((100% - var(--th)) * var(--rise) / 100);
    width: calc(var(--w) * 1% - 4px); height: var(--th); margin-inline-start: 2px; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 3px; overflow: hidden;
    background: var(--sc-i); color: var(--sc-i-on); transition: left .5s cubic-bezier(.3, .7, .2, 1), width .5s cubic-bezier(.3, .7, .2, 1), background-color .12s, transform .12s, box-shadow .12s; }
.cp-sc-short { background: var(--sc-v); color: var(--sc-v-on); }
.cp-sc-note .cp-sc-serif { font-size: clamp(16px, 2.2vw, 22px); line-height: 1; }
.cp-sc-note .cp-sc-mono { font-size: 10px; letter-spacing: .04em; }
.cp-sc-note[data-on] { background: var(--sc-night-ink); color: var(--sc-night-2); transform: scale(1.06); box-shadow: 0 0 0 3px rgb(248 244 238 / .25), 0 10px 30px rgb(0 0 0 / .5); }
[data-feel="straight"] :is(.cp-sc-note, .cp-sc-count) { --x: var(--x-straight); --w: var(--w-straight); }
[data-feel="soloist"] :is(.cp-sc-note, .cp-sc-count) { --x: var(--x-soloist); --w: var(--w-soloist); }
.cp-sc-head { position: absolute; top: -8px; bottom: -4px; left: calc(var(--at, 0) * 1%); width: 2px; background: var(--sc-gold); opacity: 0; pointer-events: none; }
.cp-sc-head[data-on] { opacity: 1; }
.cp-sc-counts { position: relative; height: 18px; margin: -6px 4px 0; }
.cp-sc-count { --x: var(--x-swung); position: absolute; left: calc(var(--x) * 1%); translate: -50% 0; font-size: 13px; font-weight: 700; letter-spacing: 0; color: var(--sc-night-muted); }
.cp-sc-count:first-child { translate: 0 0; }
.cp-sc-and { color: var(--sc-and); transition: left .5s cubic-bezier(.3, .7, .2, 1); }
.cp-sc-deck-foot { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 18px 24px; }
.cp-sc-deck-foot > div { flex: 1 1 320px; max-width: 600px; }
.cp-sc-play { display: inline-flex; align-items: center; gap: 14px; min-height: 60px; padding: 8px 26px 8px 8px; border-radius: 999px; background: var(--sc-gold); color: #1d1915; font-size: 17px; font-weight: 700; white-space: nowrap; }
.cp-sc-play:hover { background: color-mix(in srgb, var(--sc-gold) 88%, #fff); }
.cp-sc-play-icon { display: grid; place-items: center; flex: none; width: 44px; height: 44px; border-radius: 50%; background: #1d1915; }
.cp-sc-play-icon::before { content: ""; margin-left: 3px; border-left: 13px solid var(--sc-gold); border-block: 8px solid transparent; }
.cp-sc-play[aria-pressed="true"] .cp-sc-play-icon::before { width: 13px; height: 13px; margin: 0; border: 0; background: var(--sc-gold); }
.cp-sc-halt, .cp-sc-play[aria-pressed="true"] .cp-sc-go { display: none; }
.cp-sc-play[aria-pressed="true"] .cp-sc-halt { display: inline; }
@keyframes cp-sc-invite { 0% { box-shadow: 0 0 0 0 rgb(235 179 83 / .55); } 70%, 100% { box-shadow: 0 0 0 14px rgb(235 179 83 / 0); } }
@media (prefers-reduced-motion: no-preference) { .cp-sc-deck:not([data-sc-played]) .cp-sc-play { animation: cp-sc-invite 2.4s ease-out infinite; } }
@media (prefers-reduced-motion: reduce) { .cp-sc-note, .cp-sc-and { transition: none; } .cp-sc-note[data-on] { transform: none; } }
.cp-sc-say { font-size: 15.5px; font-weight: 600; color: var(--sc-night-ink); }
.cp-sc-demo-note { margin-top: 6px; font-size: 13px; line-height: 1.55; color: var(--sc-night-muted); }
.cp-sc-demosec .s-cite a, .cp-sc-band .s-cite a { color: var(--sc-gold); }

/* The story: Side A's tracklist beside its heading (held in place on a wide screen). */
.cp-sc-story { display: grid; gap: 36px 56px; padding-block: clamp(64px, 9vw, 112px) clamp(32px, 5vw, 72px); }
@media (min-width: 960px) { .cp-sc-story { grid-template-columns: minmax(0, 1fr) minmax(0, 2fr); } .cp-sc-story-head { position: sticky; top: 104px; align-self: start; } }
.cp-sc-tracks { border-top: 2px solid var(--sc-ink); }
.cp-sc-tracks li { display: grid; grid-template-columns: 34px minmax(0, 1fr); gap: 10px 16px; padding: 26px 0; border-bottom: 1px solid var(--sc-rule); }
.cp-sc-tracks li:last-child { border-bottom: 0; }
.cp-sc-tracks li > div { grid-column: 2; }
@media (min-width: 640px) { .cp-sc-tracks li { grid-template-columns: 44px 120px minmax(0, 1fr); gap: 20px; padding: 28px 0; } .cp-sc-tracks li > div { grid-column: 3; grid-row: 1; } }
.cp-sc-track-n { padding-top: 10px; font-size: 12px; color: var(--sc-label); }
.cp-sc-track-when { display: flex; align-items: center; gap: 14px; }
@media (min-width: 640px) { .cp-sc-track-when { flex-direction: column; align-items: flex-start; gap: 10px; } }
.cp-sc-year { font-size: 52px; font-weight: 800; line-height: 1; }
.cp-sc-label { display: grid; place-items: center; width: 36px; height: 36px; flex: none; border-radius: 50%; background: repeating-radial-gradient(circle, #1d1915 0 1px, #2c2622 1px 2.5px); box-shadow: inset 0 0 0 1px rgb(255 255 255 / .08); }
.cp-sc-label::after { content: ""; width: 14px; height: 14px; border-radius: 50%; background: var(--job); }
.cp-sc-tracks h3 { font-size: 20px; font-weight: 600; letter-spacing: -.01em; }
.cp-sc-tracks p:not(.cp-sc-track-when) { margin-top: 8px; max-width: 66ch; font-size: 15.5px; line-height: 1.65; color: var(--sc-body-2); text-wrap: pretty; }

/* By the end: four bars of music, a staff over each, bar lines between and the double bar at the end. */
.cp-sc-aimsec { padding-block: clamp(40px, 6vw, 56px) clamp(64px, 9vw, 120px); }
.cp-sc-aims { display: grid; margin-top: 36px; border-left: 2px solid var(--sc-ink); border-right: 6px double var(--sc-ink); }
@media (min-width: 720px) { .cp-sc-aims { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (min-width: 1100px) { .cp-sc-aims { grid-template-columns: repeat(4, minmax(0, 1fr)); } }
.cp-sc-aims li { display: flex; flex-direction: column; gap: 12px; padding: 88px 22px 18px; background: repeating-linear-gradient(to bottom, transparent 0 13px, var(--sc-staff) 13px 14px) top / 100% 70px no-repeat; }
@media (min-width: 720px) and (max-width: 1099px) { .cp-sc-aims li:nth-child(odd) { border-right: 1px solid var(--sc-rule); } }
@media (min-width: 1100px) { .cp-sc-aims li:not(:last-child) { border-right: 1px solid var(--sc-rule); } }
.cp-sc-aim-n { font-size: 40px; font-weight: 800; line-height: 1; color: var(--job-text); }
.cp-sc-aims p { font-size: 17px; line-height: 1.5; }

/* The lessons: a four-record set on the second paper, each unit a sleeve in its chord's colour, its lessons the
   tracks on the back, each a link to its page. */
.cp-sc-unitsec { background: var(--sc-paper-2); }
.cp-sc-unitsec > .s-wrap { display: flex; flex-direction: column; gap: 44px; padding-block: clamp(64px, 9vw, 104px); }
.cp-sc-unithead { display: flex; flex-wrap: wrap; align-items: flex-end; justify-content: space-between; gap: 16px 24px; }
.cp-sc-unithead .cp-sc-h2 { max-width: 820px; }
.cp-sc-unitcount { font-size: 12px; color: var(--sc-muted); }
.cp-sc-sleeves { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 240px), 1fr)); gap: 18px; }
.cp-sc-sleeve { display: flex; flex-direction: column; background: var(--sc-paper); box-shadow: 0 1px 0 var(--sc-rule); }
.cp-sc-sleeve-front { position: relative; display: flex; flex-direction: column; justify-content: space-between; gap: 18px; aspect-ratio: 1.6; padding: 20px; overflow: hidden; background: var(--job); color: var(--job-on); }
@media (min-width: 600px) { .cp-sc-sleeve-front { aspect-ratio: 1.15; } }
.cp-sc-sleeve-top { position: relative; display: flex; justify-content: space-between; gap: 8px; font-size: 10px; letter-spacing: .16em; }
.cp-sc-sleeve-n { position: absolute; right: -14px; bottom: -34px; font-size: 190px; line-height: 1; opacity: .16; }
.cp-sc-sleeve h3 { position: relative; font-size: clamp(34px, 3.4vw, 40px); font-weight: 800; line-height: .92; overflow-wrap: anywhere; }
.cp-sc-sleeve-back { display: flex; flex-direction: column; gap: 14px; padding: 18px 20px 20px; }
.cp-sc-sleeve-back > p { font-size: 14px; line-height: 1.55; color: var(--sc-body-2); }
.cp-sc-tracklist li { border-top: 1px solid var(--sc-rule); }
.cp-sc-tracklist :is(a, li:not(:has(a))) { display: flex; align-items: center; gap: 12px; min-height: 44px; padding-block: 8px; font-size: 14px; color: var(--sc-ink); }
.cp-sc-tracklist a:hover > span:nth-child(2) { text-decoration: underline; text-underline-offset: 3px; }
.cp-sc-tracklist .cp-sc-mono { flex: none; width: 22px; font-size: 11px; letter-spacing: 0; color: var(--sc-muted); }
.cp-sc-start { flex: none; margin-inline-start: auto; padding: 4px 7px; border-radius: 3px; background: var(--sc-v); color: var(--sc-v-on); font: 700 9px/1.2 var(--sc-mono); letter-spacing: .12em; text-transform: uppercase; white-space: nowrap; }

/* The science: four cards in one ruled frame, each with a small drawing of what it says. */
.cp-sc-science { padding-block: clamp(64px, 9vw, 112px); }
.cp-sc-cards { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 440px), 1fr)); gap: 1px; margin-top: 44px; background: var(--sc-rule); border: 1px solid var(--sc-rule); }
.cp-sc-card { display: flex; flex-direction: column; gap: 18px; padding: clamp(22px, 3vw, 32px); background: var(--sc-paper); }
.cp-sc-card h3 { font-size: 22px; font-weight: 600; letter-spacing: -.01em; }
.cp-sc-card > p { font-size: 15.5px; line-height: 1.65; color: var(--sc-body-2); text-wrap: pretty; }
.cp-sc-fig { display: flex; flex-direction: column; justify-content: center; gap: 8px; height: 96px; }
.cp-sc-fig p { display: flex; align-items: center; gap: 10px; }
:is(.cp-sc-fig-0, .cp-sc-fig-1) p > .cp-sc-mono { flex: none; width: 72px; font-size: 10px; letter-spacing: .08em; color: var(--sc-muted); }
.cp-sc-runs, .cp-sc-marks { position: relative; flex: 1; height: 14px; }
.cp-sc-runs i { position: absolute; inset-block: 0; left: calc(var(--a) * 1%); width: calc((var(--b) - var(--a)) * 1% - 3px); background: var(--sc-ink); }
.cp-sc-runs .cp-sc-off { opacity: .45; }
.cp-sc-solo i { background: var(--sc-i); }
.cp-sc-solo .cp-sc-off { opacity: 1; background: var(--sc-v); }
.cp-sc-runs s { position: absolute; inset-block: -5px; left: calc(var(--a) * 1% - 2px); border-left: 1px dashed var(--sc-ink); }
.cp-sc-marks { border-bottom: 1px solid var(--sc-rule); }
.cp-sc-marks i { position: absolute; bottom: 0; left: calc(var(--a) * 1%); width: 3px; height: 14px; background: var(--sc-ink); }
.cp-sc-doubled .cp-sc-marks i { background: var(--sc-v-text); }
.cp-sc-fig-1 { gap: 10px; }
.cp-sc-fours { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 4px; }
.cp-sc-fours li { display: flex; flex-direction: column; gap: 2px; padding: 10px; background: var(--sc-ink-fill); color: var(--sc-ink-on); }
.cp-sc-fours li.cp-sc-partner { background: var(--sc-iv); color: var(--sc-iv-on); }
.cp-sc-fours .cp-sc-mono { font-size: 10px; letter-spacing: .08em; }
.cp-sc-fig .cp-sc-keys { position: relative; align-items: flex-end; gap: 0; height: 96px; }
.cp-sc-keys > :is(.cp-sc-key-b, .cp-sc-key-w) { display: flex; align-items: flex-end; justify-content: center; width: 46px; height: 88px; padding-bottom: 8px; font-size: 10px; letter-spacing: 0; }
.cp-sc-key-b { background: #1d1915; color: #f8f4ee; box-shadow: inset 0 0 0 1px rgb(248 244 238 / .14); }
.cp-sc-key-w { background: #fbf8f3; color: #1d1915; border: 1px solid #1d1915; border-left: 0; }
.cp-sc-blue { position: absolute; left: 35px; top: 4px; width: 22px; height: 22px; border-radius: 50%; background: var(--sc-iv); box-shadow: 0 0 0 4px var(--sc-paper); }
.cp-sc-keys .cp-sc-serif { align-self: center; margin-inline-start: 18px; font-size: 24px; line-height: 1.1; color: var(--sc-iv-text); }

/* Liner notes: the night band, what the app listens for beside the back of a sleeve. */
.cp-sc-band { background: var(--sc-night); color: var(--sc-night-ink); }
.cp-sc-band-in { display: grid; gap: 48px 56px; padding-block: clamp(64px, 9vw, 104px); }
@media (min-width: 960px) { .cp-sc-band-in { grid-template-columns: minmax(0, 1fr) minmax(0, 2fr); } }
.cp-sc-band .cp-sc-kick { color: var(--sc-gold); }
.cp-sc-listens { display: flex; flex-direction: column; gap: 14px; margin-top: 40px; padding-top: 22px; border-top: 1px solid var(--sc-night-rule); }
.cp-sc-listens > p:not(.cp-sc-listens-no) { font-size: 16px; line-height: 1.6; color: var(--sc-night-body); }
.cp-sc-listens li, .cp-sc-listens-no { display: flex; gap: 14px; padding: 11px 0; font-size: 16px; line-height: 1.5; }
.cp-sc-listens li { border-bottom: 1px solid var(--sc-night-rule); }
.cp-sc-listens svg { flex: none; margin-top: 4px; color: var(--sc-gold); }
.cp-sc-no { flex: none; width: 16px; font-weight: 700; text-align: center; color: var(--sc-and); }
.cp-sc-listens-no { color: var(--sc-night-muted); }
.cp-sc-sleeveback { display: flex; flex-direction: column; gap: 24px; padding: clamp(22px, 3vw, 40px); border: 1px solid var(--sc-night-rule); }
.cp-sc-sleeveback-top { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 8px 16px; padding-bottom: 14px; border-bottom: 3px double rgb(248 244 238 / .3); font-size: 10px; letter-spacing: .16em; color: var(--sc-night-muted); }
.cp-sc-liner { columns: 2 240px; column-gap: 36px; column-rule: 1px solid var(--sc-night-rule); font: 20px/1.45 var(--sc-serif); color: #efeae2; }
.cp-sc-liner p { margin: 0 0 18px; break-inside: avoid; }
.cp-sc-liner .s-cite { font-family: var(--font-sans, system-ui), system-ui, sans-serif; }

/* Before you begin: the personnel, three ruled columns. */
.cp-sc-begin { padding-block: clamp(64px, 9vw, 112px) clamp(40px, 6vw, 80px); }
.cp-sc-begin-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 280px), 1fr)); gap: 36px; margin-top: 44px; }
.cp-sc-begin-grid h3 { padding-bottom: 12px; border-bottom: 2px solid var(--sc-ink); font-size: 12px; font-weight: 700; letter-spacing: .16em; }
.cp-sc-ticks li { display: flex; gap: 12px; padding: 14px 0; border-bottom: 1px solid var(--sc-rule); font-size: 15px; line-height: 1.5; }
.cp-sc-ticks svg { flex: none; margin-top: 3px; color: var(--sc-label); }
.cp-sc-songs-h { padding-top: 28px; }
.cp-sc-songs li { display: flex; flex-direction: column; gap: 3px; padding: 14px 0; border-bottom: 1px solid var(--sc-rule); font-size: 15px; }
.cp-sc-songs b { font-weight: 600; }
.cp-sc-songs span { font-size: 13.5px; color: var(--sc-muted); }

/* Questions beside their heading. */
.cp-sc-fine { display: grid; gap: 24px 48px; padding-block: clamp(40px, 6vw, 56px) clamp(64px, 9vw, 112px); }
@media (min-width: 960px) { .cp-sc-fine { grid-template-columns: minmax(0, 1fr) minmax(0, 2fr); } }
.cp-sc .cp-faq { max-width: none; margin-top: 0; border-top: 2px solid var(--sc-ink); }
.cp-sc .cp-faq summary { min-height: 68px; font-size: 19px; font-weight: 600; }
.cp-sc .cp-faq-sign { background: color-mix(in srgb, var(--sc-ink) 8%, transparent); }
.cp-sc .cp-faq details[open] .cp-faq-sign { background: var(--sc-ink); color: var(--sc-paper); }
.cp-sc .cp-faq details p { padding-right: 48px; font-size: 16px; line-height: 1.65; color: var(--sc-body-2); }

/* Your turn: the page's one ochre block, the band's bars and yours, centred; its buttons in ink. */
.cp-sc-close { --primary: #1d1915; --primary-ink: #f8f4ee; --primary-hover-to: #000; --btn-soft: rgb(29 25 21 / .1); --btn-soft-hover: rgb(29 25 21 / .16); --btn-soft-active: rgb(29 25 21 / .22); background: var(--sc-ochre); color: var(--sc-ochre-ink); }
.cp-sc-close .btn-secondary { color: var(--sc-ochre-ink); }
:root[data-skin="game"][data-theme] body.s-arcade .cp-sc-close :is(.btn-secondary, .cp-join-btns .btn-secondary) { background: transparent; color: var(--sc-ochre-ink); box-shadow: inset 0 0 0 2px var(--sc-ochre-ink); } /* over the game join buttons' cyan: the band is ochre */
/* Game's light themes: the headline's full stop a deeper red, AA on the light ground at the pixel heading's size. */
:root[data-skin="game"][data-theme$="-light"] .cp-sc { --sc-v-text: #a8301f; }
.cp-sc-close-in { display: flex; flex-direction: column; align-items: center; gap: 28px; padding-block: clamp(64px, 9vw, 96px); text-align: center; }
.cp-sc-close .cp-sc-kick { color: inherit; }
.cp-sc-close-h { margin: 0; font-size: clamp(88px, 16vw, 220px); line-height: .8; }
.cp-sc-close-h .cp-sc-stop { color: var(--sc-ochre-stop); }
.cp-sc-trade { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 4px; width: min(100%, 640px); }
@media (min-width: 600px) { .cp-sc-trade { grid-template-columns: repeat(4, minmax(0, 1fr)); } }
.cp-sc-trade > span { display: flex; flex-direction: column; gap: 4px; padding: 14px 12px; background: #1d1915; color: #f8f4ee; text-align: start; }
.cp-sc-trade .cp-sc-mono { font-size: 11px; }
.cp-sc-trade .cp-sc-serif { font-size: 20px; line-height: 1.15; }
.cp-sc-trade > .cp-sc-yours { background: #f8f4ee; color: #1d1915; outline: 2px dashed #1d1915; outline-offset: -2px; }
.cp-sc-close-body { max-width: 560px; font-size: 19px; line-height: 1.55; text-wrap: pretty; }
.cp-sc-close .cp-sc-btns { justify-content: center; }
@media (max-width: 599px) { .cp-sc-close .cp-sc-btns { width: 100%; } }
.cp-sc-close-note { font-size: 14px; }
.cp-sc-related-h { margin-top: 16px; }
.cp-sc-close .cp-related { justify-content: center; margin-top: 0; }
.cp-sc-close .cp-related a { background: rgb(29 25 21 / .1); color: #1d1915; }
.cp-sc-close .cp-related a:hover { background: rgb(29 25 21 / .16); }
.cp-sc .cp-related-all { display: none; }

/* The sources: discography and studies, two columns, numbered as the notes are. */
.cp-sc-sources { padding-block: clamp(56px, 8vw, 88px) 48px; }
.cp-sc-sources summary { display: flex; align-items: center; min-height: 44px; list-style: none; cursor: pointer; }
.cp-sc-sources summary::-webkit-details-marker { display: none; }
.cp-sc-sources summary h2::after { content: " +"; }
.cp-sc-sources details[open] summary h2::after { content: ""; }
.cp-sc-sources ol { margin-top: 20px; padding-inline-start: 22px; list-style: decimal; columns: 2 380px; column-gap: 48px; font-size: 13.5px; line-height: 1.5; color: var(--sc-body); }
.cp-sc-sources li { margin-bottom: 9px; break-inside: avoid; scroll-margin-top: 90px; }
.cp-sc-sources a { color: inherit; text-decoration: underline; text-decoration-color: var(--sc-rule); text-underline-offset: 3px; overflow-wrap: anywhere; }
.cp-sc-sources a:hover { text-decoration-color: currentColor; }

/* The game skin: the arcade's pixel headings with their hard drop, the HUD's face for the small print, square frames on
   hard shadows (the records stay round), the deck in the cabinet's neon, and PRESS START blinking until pressed. */
:root[data-skin="game"] body.s-arcade .cp-sc .cp-sc-display { font-family: var(--arc-pixel); font-weight: 400; letter-spacing: 0; font-size-adjust: .58; --arc-ex: .58; line-height: 1.15; text-shadow: .06em .06em 0 var(--arc-shade); }
:root[data-skin="game"] body.s-arcade .cp-sc-h1 { font-size: clamp(36px, 7vw, 76px); }
:root[data-skin="game"] body.s-arcade .cp-sc :is(.cp-sc-h2, .cp-sc-demosec .cp-sc-h2) { font-size: clamp(24px, 4vw, 44px); }
:root[data-skin="game"] body.s-arcade .cp-sc-close-h { font-size: clamp(40px, 9vw, 100px); }
:root[data-skin="game"] body.s-arcade .cp-sc :is(.cp-sc-sleeve12-h, .cp-sc-sleeve h3) { font-size: clamp(18px, 2.2vw, 26px); }
:root[data-skin="game"] body.s-arcade .cp-sc :is(.cp-sc-year, .cp-sc-aim-n) { font-size: 26px; }
:root[data-skin="game"] body.s-arcade .cp-sc .cp-sc-bar-chord b { font-size: clamp(14px, 1.6vw, 18px); }
:root[data-skin="game"] body.s-arcade .cp-sc .cp-sc-sleeve-n { font-size: 120px; }
:root[data-skin="game"] body.s-arcade .cp-sc :is(.cp-sc-mono, .cp-sc-kick, .cp-sc-start) { font-family: var(--a-hud); font-weight: 400; letter-spacing: .04em; font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade .cp-sc .cp-sc-note .cp-sc-serif { font-family: var(--a-hud); font-style: normal; font-size: 13px; font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade .cp-sc :is(.cp-sc-cat, .cp-sc-seg, .cp-sc-seg button, .cp-sc-play, .cp-sc-play-icon, .cp-sc-start, .cp-sc-syl-bar, .cp-faq-sign, .cp-related a) { border-radius: 0; }
:root[data-skin="game"] body.s-arcade .cp-sc :is(.cp-sc-sleeve12, .cp-sc-sleeve, .cp-sc-sleeveback) { border: 2px solid var(--a-line-2); box-shadow: 4px 4px 0 var(--arc-shadow-c, #05030d); }
:root[data-skin="game"] body.s-arcade .cp-sc .cp-sc-deck { border: 2px solid #3be7ff; box-shadow: 6px 6px 0 #ff5fd2; }
:root[data-skin="game"] body.s-arcade .cp-sc .cp-sc-play { background: #ffd84a; color: #1a1400; text-transform: uppercase; box-shadow: 4px 4px 0 #05030d; animation: none; }
:root[data-skin="game"] body.s-arcade .cp-sc .cp-sc-note[data-on] { box-shadow: 0 0 0 2px #1a1400, 0 0 18px var(--sc-gold); }
:root[data-skin="game"] body.s-arcade main.cp-sc :is(.cp-sc-disc, .cp-sc-disc-label, .cp-sc-disc-label i, .cp-sc-label, .cp-sc-blue, .cp-sc-rec),
:root[data-skin="game"][data-gs] body.s-arcade:not(.s-calm) main.cp-sc :is(.cp-sc-disc, .cp-sc-disc-label, .cp-sc-disc-label i, .cp-sc-label, .cp-sc-blue, .cp-sc-rec) { border-radius: 50%; }
:root[data-skin="game"] body.s-arcade main.cp-sc .cp-sc-label::after { border-radius: 50%; }
@media (prefers-reduced-motion: no-preference) { :root[data-skin="game"] body.s-arcade .cp-sc-play[aria-pressed="false"] .cp-sc-go { animation: s-demo-blink 1.1s steps(2, start) infinite; } }

/* Improvising a harmony (site/courses/improvising-harmony): Hillel's "tunebook" design (2026-11-18,
   ~/Code/course-designs/improvising-harmony). The shaped note heads of the old shape-note songbooks (four-shape: fa a
   triangle, sol an oval, la a square, mi a diamond), ruled staff lines behind the hero and an italic serif (Libre Caslon
   Text) for each heading's key words, beside the course's glowing lights. The player and the two dark bands stay the
   night in every theme (a screen, as the cabinet does); the rest reads the theme's own ground, ink and lines. Game: the
   arcade's pixel headings, square corners, yellow lights and cyan tune. */
.cp-imp {
    --ih-serif: 'Libre Caslon Text', ui-serif, 'Iowan Old Style', 'Palatino Linotype', Palatino, Georgia, serif;
    --ih-em: #8f5300; --ih-shape: #d27c06; --ih-staff: color-mix(in srgb, var(--color-cream) 7%, transparent);
    --ih-day: #636a96; --ih-glow: #e8900f; --ih-rub: #d2432f;
    --ih-night: #17121b; --ih-night-2: #211a27; --ih-n-ink: #f4eee6; --ih-n-muted: #bdb3aa; --ih-n-line: rgb(244 238 230 / .1);
    --ih-lit: #f5b547; --ih-lit-ink: #1c1714; --ih-tune: #7d6da9; --ih-miss: #f07b6a;
    --ih-try: #e3901c; --ih-try-ink: #1c1714;
    --ih-r: 24px; --ih-r-s: 16px;
}
:root:not([data-theme$="-light"]) .cp-imp { --ih-em: #f2b04a; --ih-shape: #f0a43a; --ih-day: #9097c8; --ih-glow: #f5b547; --ih-night: #1f1925; --ih-night-2: #2a2231; }
:root[data-skin="game"] .cp-imp { --ih-lit: #ffd84a; --ih-tune: #2fb8cc; --ih-night: #0b0a17; --ih-night-2: #151227; --ih-r: 0px; --ih-r-s: 0px; --ih-em: var(--a-pink); --ih-shape: var(--a-yellow); --ih-glow: var(--a-yellow); }
:root[data-skin="game"][data-theme$="-light"] .cp-imp { --ih-shape: #b07c00; --ih-glow: #d79a00; }
body:has(.cp-imp) { background: var(--color-ink); }
/* The page's own index lists every lesson's page, so the shared list below it is left out (the lesson-pages-inline
   section says so once the shared partial reads it). */
.cp-imp ~ [data-lesson-pages] { display: none; }

/* The shapes: a note head each, sized by font-size. */
.cp-imp-shape { display: inline-block; flex: none; width: 1em; height: 1em; background: var(--ih-shape); }
.cp-imp-fa { clip-path: polygon(50% 4%, 97% 92%, 3% 92%); }
.cp-imp-sol { clip-path: ellipse(50% 40% at 50% 50%); }
.cp-imp-la { clip-path: inset(8%); }
.cp-imp-mi { clip-path: polygon(50% 0, 100% 50%, 50% 100%, 0 50%); }

/* Type: a heavy sans heading with its key words in the italic serif. */
.cp-imp :is(.cp-imp-h1, .cp-imp-h2) em { font-family: var(--ih-serif); font-style: italic; font-weight: 400; letter-spacing: -0.01em; color: var(--ih-em); }
.cp-imp-h1 { margin-top: 18px; font-size: clamp(56px, 9.4vw, 124px); line-height: .94; font-weight: 900; letter-spacing: -0.05em; text-wrap: balance; }
.cp-imp-h1 em { padding-inline-end: .06em; }
.cp-imp-h2 { margin-top: 10px; font-size: clamp(36px, 5vw, 64px); line-height: 1.02; font-weight: 900; letter-spacing: -0.04em; text-wrap: balance; }
.cp-imp-h2-s { font-size: clamp(30px, 3.8vw, 46px); }
.cp-imp-kick { font-size: 12px; font-weight: 700; letter-spacing: .16em; text-transform: uppercase; color: var(--s-hl-em); }
.cp-imp-ruled { padding-bottom: 16px; border-bottom: 1.5px solid var(--color-cream); }
.cp-imp-lede { margin-top: 20px; font-size: clamp(18px, 1.5vw, 20px); line-height: 1.6; max-width: 56ch; text-wrap: pretty; }
.cp-imp-p { margin-top: 14px; font-size: 15.5px; line-height: 1.6; color: var(--color-muted); max-width: 60ch; }
.cp-imp-sec { padding-block: clamp(56px, 7vw, 96px); }

/* The hero, on ruled staff lines that fade into the page. */
.cp-imp-hero { padding-top: 8px; padding-bottom: clamp(40px, 6vw, 72px); background: linear-gradient(to bottom, transparent 40%, var(--color-ink) 92%), repeating-linear-gradient(to bottom, transparent 0 27px, var(--ih-staff) 27px 28px); }
.cp-imp-top { display: grid; grid-template-columns: minmax(0, 1fr); gap: 24px; margin-top: 18px; }
.cp-imp-chip { display: inline-flex; align-items: center; gap: 10px; padding: 4px 14px 4px 4px; border: 1px solid var(--k-line-strong); border-radius: 99px; background: var(--color-panel); font-size: 13.5px; font-weight: 650; white-space: nowrap; }
.cp-imp-chip b { padding: 3px 10px; border-radius: 99px; background: var(--color-cream); color: var(--color-ink); font-size: 11px; font-weight: 800; letter-spacing: .1em; text-transform: uppercase; }
.cp-imp-lead { font-size: clamp(18px, 1.6vw, 20px); line-height: 1.55; color: var(--color-muted); max-width: 54ch; text-wrap: pretty; }
.cp-imp-btns { display: flex; flex-wrap: wrap; gap: 12px; margin-top: 24px; }
.cp-imp-btns > a { white-space: nowrap; }
.cp-imp-facts { display: flex; flex-wrap: wrap; row-gap: 4px; margin-top: 20px; font-size: 14px; color: var(--color-muted); }
.cp-imp-facts li { white-space: nowrap; }
.cp-imp-facts li:not(:last-child)::after { content: "\00b7"; margin-inline: 12px; opacity: .7; }
@media (max-width: 639px) {
    .cp-imp-btns { flex-direction: column; align-items: stretch; }
    .cp-imp-btns > a { justify-content: center; width: 100%; }
}
@media (min-width: 900px) {
    .cp-imp-top { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 64px; align-items: end; }
    .cp-imp-top-r { padding-bottom: 14px; }
}

/* The player: the night in every theme, the lane on its eight rows, its plays beside the lights steps. */
.cp-imp-player { --color-cream: var(--ih-n-ink); --color-muted: var(--ih-n-muted); margin-top: clamp(32px, 4.4vw, 52px); border-radius: var(--ih-r); background: var(--ih-night); color: var(--ih-n-ink); box-shadow: 0 30px 60px -36px rgb(30 18 8 / .55); }
:root:not([data-theme$="-light"]) .cp-imp-player { border: 1px solid var(--ih-n-line); box-shadow: none; }
.cp-imp-bar { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 6px 20px; padding: 16px clamp(18px, 2.4vw, 28px); border-bottom: 1px solid var(--ih-n-line); font-size: 12px; font-weight: 700; letter-spacing: .14em; text-transform: uppercase; color: var(--ih-n-muted); }
.cp-imp-live { display: inline-flex; align-items: center; gap: 10px; color: var(--ih-n-ink); }
.cp-imp-live i { width: 8px; height: 8px; border-radius: 99px; background: var(--ih-lit); box-shadow: 0 0 8px var(--ih-lit); }
.cp-imp-fig { margin: 0; padding: 22px clamp(14px, 2.4vw, 28px) 6px; }
.cp-imp-board { --rh: 30px; --nh: 16px; display: grid; grid-template-columns: 52px minmax(0, 1fr); column-gap: 14px; }
.cp-imp-rows { grid-column: 1; grid-row: 1; display: grid; grid-template-rows: repeat(8, var(--rh)); font-size: 13px; color: var(--ih-n-muted); }
.cp-imp-rows li { display: flex; align-items: center; gap: 8px; }
.cp-imp-rows .cp-imp-shape { font-size: 9px; --ih-shape: var(--ih-n-muted); }
.cp-imp-lane { grid-column: 2; grid-row: 1; position: relative; height: calc(var(--rh) * 8); background: repeating-linear-gradient(to bottom, transparent 0 calc(var(--rh) / 2 - .5px), var(--ih-n-line) calc(var(--rh) / 2 - .5px) calc(var(--rh) / 2 + .5px), transparent calc(var(--rh) / 2 + .5px) var(--rh)); }
.cp-imp-note { --fill: var(--ih-tune); --edge: 0 solid transparent; --glow: none; --o: 1; position: absolute; top: calc(var(--row) * var(--rh) + (var(--rh) - var(--nh)) / 2); height: var(--nh); }
.cp-imp-note::before { content: ""; position: absolute; inset-block: 0; inset-inline: 0 4px; border-radius: 99px; border: var(--edge); background: var(--fill); filter: var(--glow); opacity: var(--o); transition: opacity .2s, background-color .2s; }
.cp-imp-part { --fill: var(--ih-lit); --glow: drop-shadow(0 0 7px rgb(245 181 71 / .6)); z-index: 1; }
.cp-imp-alt { display: none; }
.cp-imp-ph { position: absolute; z-index: 2; inset-block: -6px; inset-inline-start: calc(var(--p, 0) * 100%); width: 2px; margin-inline-start: -1px; border-radius: 1px; background: var(--ih-n-ink); opacity: 0; }
.cp-imp-player[data-playing] .cp-imp-ph { opacity: .85; }
.cp-imp-words { grid-column: 2; position: relative; height: 42px; margin-top: 10px; font-size: 14px; font-weight: 700; color: var(--ih-n-muted); }
.cp-imp-words span { position: absolute; top: 0; white-space: nowrap; transition: color .15s; }
.cp-imp-words .cp-imp-w1 { top: 20px; }
.cp-imp-words [data-on] { color: var(--ih-lit); }
/* The lights steps: fading, you choose (every other note of the chord too), lights off. */
.cp-imp-player[data-stage="1"] .cp-imp-half { --o: .55; --glow: none; }
.cp-imp-player[data-stage="1"] .cp-imp-dim { --o: .25; --glow: none; }
.cp-imp-player[data-stage="1"] .cp-imp-off { --fill: transparent; --edge: 1.5px dashed rgb(245 181 71 / .55); --glow: none; }
.cp-imp-player[data-stage="2"] .cp-imp-alt { display: block; }
.cp-imp-player[data-stage="2"] :is(.cp-imp-alt, .cp-imp-part) { --fill: rgb(245 181 71 / .22); --edge: 1.5px solid rgb(245 181 71 / .7); --glow: none; }
.cp-imp-player[data-stage="3"] .cp-imp-part { visibility: hidden; }
/* Playing: the tune's notes and words light as they sound; with the part (or your turn) its notes too. */
.cp-imp-player[data-playing] .cp-imp-tune:not([data-on]) { --o: .5; }
.cp-imp-player:is([data-mode="both"], [data-mode="you"]):not([data-stage="3"]) .cp-imp-part[data-on] { --fill: var(--ih-lit); --edge: 0 solid transparent; --o: 1; --glow: drop-shadow(0 0 12px rgb(245 181 71 / .9)); }
.cp-imp-player[data-mode="tune"] .cp-imp-part { --o: .3; --glow: none; }
.cp-imp-controls { display: grid; grid-template-columns: minmax(0, 1fr); gap: 26px; padding: 22px clamp(18px, 2.4vw, 28px) 28px; border-top: 1px solid var(--ih-n-line); }
.cp-imp-plays { display: flex; flex-wrap: wrap; gap: 10px; }
.cp-imp-play { display: inline-flex; align-items: center; gap: 10px; min-height: 48px; padding: 0 18px 0 7px; border-radius: 99px; border: 1px solid rgb(244 238 230 / .24); color: var(--ih-n-ink); font-size: 15px; font-weight: 700; white-space: nowrap; }
.cp-imp-play:hover { background: rgb(244 238 230 / .07); }
.cp-imp-play:focus-visible, .cp-imp-steps button:focus-visible { outline: 3px solid var(--ih-lit); outline-offset: 2px; }
.cp-imp-play-icon { position: relative; flex: none; width: 34px; height: 34px; border-radius: 99px; background: var(--ih-lit); }
.cp-imp-play-icon::before { content: ""; position: absolute; inset-block-start: 11px; inset-inline-start: 13px; border-block: 6px solid transparent; border-inline-start: 10px solid var(--ih-lit-ink); }
.cp-imp-play[aria-pressed="true"] .cp-imp-play-icon::before { inset: 12px; border: 0; border-radius: 2px; background: var(--ih-lit-ink); }
.cp-imp-say { margin-top: 14px; font-size: 15px; font-weight: 600; color: var(--ih-n-ink); }
.cp-imp-note-p { margin-top: 6px; font-size: 14px; line-height: 1.55; color: var(--ih-n-muted); max-width: 60ch; }
.cp-imp-kick-lit { color: var(--ih-lit); }
.cp-imp-steps { display: grid; grid-template-columns: repeat(4, minmax(max-content, 1fr)); gap: 4px; margin-top: 12px; padding: 4px; border-radius: 14px; background: rgb(244 238 230 / .07); overflow-x: auto; scrollbar-width: none; }
.cp-imp-steps button { min-height: 44px; padding: 0 12px; border-radius: 10px; font-size: 14px; font-weight: 650; white-space: nowrap; color: var(--ih-n-muted); }
.cp-imp-steps button:hover { color: var(--ih-n-ink); }
.cp-imp-steps [aria-pressed="true"] { background: var(--ih-lit); color: var(--ih-lit-ink); box-shadow: 0 1px 2px rgb(0 0 0 / .4); }
.cp-imp-stage-say { margin-top: 14px; font-size: 16px; line-height: 1.5; color: var(--ih-n-ink); }
@media (min-width: 900px) { .cp-imp-controls { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 48px; } }
@media (max-width: 639px) {
    .cp-imp-board { --rh: 24px; --nh: 13px; grid-template-columns: 40px minmax(0, 1fr); column-gap: 8px; }
    .cp-imp-rows { font-size: 12px; }
    .cp-imp-rows li { gap: 6px; }
    .cp-imp-words { height: 36px; font-size: 12px; }
    .cp-imp-words .cp-imp-w1 { top: 17px; }
    .cp-imp-note::before { inset-inline-end: 2px; }
    .cp-imp-steps button { padding: 0 10px; font-size: 13px; }
}
@media (max-width: 359px) {
    .cp-imp-board { grid-template-columns: 12px minmax(0, 1fr); }
    .cp-imp-rows span { display: none; }
    .cp-imp-words { font-size: 11px; }
}

/* By the end: four outcomes numbered by the shapes, a quiet line on what they are. */
.cp-imp-outcomes { display: grid; grid-template-columns: minmax(0, 1fr); column-gap: 40px; }
.cp-imp-outcomes li { padding-block: 22px; border-bottom: 1px solid var(--k-line-strong); font-size: 17px; line-height: 1.5; text-wrap: pretty; }
.cp-imp-mark { display: flex; align-items: center; gap: 12px; margin-bottom: 12px; font-size: 20px; }
.cp-imp-mark span, .cp-imp-era, .cp-imp-num, .cp-imp-index-note, .cp-imp-tag { font-family: var(--ih-serif); font-style: italic; }
.cp-imp-mark span { font-size: 17px; color: var(--color-muted); }
.cp-imp-small { margin-top: 20px; font-size: 13.5px; line-height: 1.5; color: var(--color-muted); }
@media (min-width: 640px) { .cp-imp-outcomes { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (min-width: 1024px) { .cp-imp-outcomes { grid-template-columns: repeat(4, minmax(0, 1fr)); } .cp-imp-outcomes li { border-bottom: 0; } .cp-imp-small { padding-top: 16px; border-top: 1px solid var(--k-line-strong); } }

/* The one rule: its words beside two small lanes, a third over mi and a fourth over so (ti a struck-out ghost). */
.cp-imp-rule { display: grid; grid-template-columns: minmax(0, 1fr); gap: 36px; }
.cp-imp-figs { display: grid; grid-template-columns: minmax(0, 1fr); gap: 14px; align-content: start; }
.cp-imp-card { margin: 0; padding: 20px 22px; border: 1px solid var(--k-line-strong); border-radius: var(--ih-r-s); background: var(--color-panel); }
.cp-imp-mini { --rh: 40px; position: relative; height: calc(var(--rh) * 4); }
.cp-imp-mini-row { position: absolute; inset-inline: 0; top: calc(var(--row) * var(--rh)); display: flex; align-items: center; gap: 10px; height: var(--rh); font-size: 12px; color: var(--color-muted); }
.cp-imp-mini-row::after { content: ""; flex: 1; height: 1px; background: var(--k-line-strong); }
.cp-imp-mini-note { position: absolute; inset-inline-start: 22%; width: 52%; top: calc(var(--row) * var(--rh) + var(--rh) / 2 - 10px); height: 20px; border-radius: 99px; background: var(--ih-day); }
.cp-imp-mini-lit { background: var(--ih-glow); box-shadow: 0 0 18px -2px var(--ih-glow); }
.cp-imp-mini-rub { background: none; border: 1.5px dashed var(--color-muted); }
.cp-imp-mini-rub::after { content: ""; position: absolute; inset-inline: -6%; top: 50%; height: 2px; border-radius: 1px; background: var(--ih-rub); rotate: -8deg; }
.cp-imp-tag { position: absolute; inset-inline-end: 0; top: calc(var(--row) * var(--rh)); display: flex; align-items: center; height: var(--rh); padding-inline-start: 6px; background: var(--color-panel); font-size: 16px; color: var(--ih-em); }
.cp-imp-card figcaption { margin-top: 12px; font-size: 14px; line-height: 1.5; color: var(--color-muted); }
.cp-imp-card figcaption b { display: block; font-size: 15px; color: var(--color-cream); }
@media (min-width: 480px) { .cp-imp-figs { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (min-width: 900px) { .cp-imp-rule { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 64px; align-items: center; } }

/* The index: every lesson numbered through the course by unit, each linked to its page, a sketch of each unit's parts. */
.cp-imp-index { padding-block: clamp(56px, 7vw, 96px); border-block: 1px solid var(--k-line); background: color-mix(in srgb, var(--color-panel) 75%, var(--color-ink)); }
.cp-imp-index-head { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: end; gap: 12px 32px; }
.cp-imp-index-note { font-size: 18px; color: var(--color-muted); }
.cp-imp-units { display: grid; grid-template-columns: minmax(0, 1fr); gap: 48px 64px; margin-top: clamp(32px, 4vw, 52px); }
.cp-imp-unit-head { display: flex; justify-content: space-between; align-items: end; gap: 16px; padding-bottom: 14px; border-bottom: 1.5px solid var(--color-cream); }
.cp-imp-unit h3 { margin-top: 4px; font-size: clamp(22px, 2.2vw, 26px); font-weight: 800; letter-spacing: -0.02em; line-height: 1.2; }
.cp-imp-sketch { display: grid; gap: 4px; flex: none; width: 84px; margin-bottom: 6px; }
.cp-imp-sketch i { height: 5px; border-radius: 99px; background: var(--ih-day); }
.cp-imp-unit[data-unit="1"] .cp-imp-sketch i:nth-child(1), .cp-imp-unit[data-unit="2"] .cp-imp-sketch i:nth-child(2) { background: var(--ih-glow); box-shadow: 0 0 6px var(--ih-glow); }
