.cp-imp-unit[data-unit="3"] .cp-imp-sketch i:is(:nth-child(1), :nth-child(3)) { background: color-mix(in srgb, var(--ih-glow) 45%, transparent); }
.cp-imp-unit[data-unit="4"] .cp-imp-sketch i:nth-child(1) { background: none; border: 1px dashed var(--ih-glow); }
.cp-imp-unit[data-unit="4"] .cp-imp-sketch i:nth-child(2) { background: none; border: 1px dashed var(--color-muted); }
.cp-imp-unit-say { margin-top: 14px; font-size: 15px; line-height: 1.5; color: var(--color-muted); }
.cp-imp-lessons { margin-top: 6px; }
.cp-imp-lessons li { position: relative; display: grid; grid-template-columns: 34px minmax(0, 1fr) auto; gap: 10px; align-items: start; padding-block: 13px; border-bottom: 1px dashed var(--k-line-strong); }
.cp-imp-num { font-size: 17px; line-height: 1.3; color: var(--color-muted); }
.cp-imp-lesson a, .cp-imp-lesson b { font-size: 16px; font-weight: 700; color: var(--color-cream); }
.cp-imp-lesson a::after { content: ""; position: absolute; inset: 0; }
.cp-imp-lesson a:hover, .cp-imp-lesson a:focus-visible { text-decoration: underline 2px var(--ih-shape); text-underline-offset: 4px; }
.cp-imp-sub { display: block; margin-top: 2px; font-size: 14px; color: var(--color-muted); }
.cp-imp-lessons .s-free { margin-top: 2px; white-space: nowrap; }
@media (min-width: 900px) { .cp-imp-units { grid-template-columns: repeat(2, minmax(0, 1fr)); } }

/* Try this now: the course's one strong block, a strip of lesson 1's long-note step over it. */
.cp-imp-try { --color-cream: var(--ih-try-ink); --color-muted: color-mix(in srgb, var(--ih-try-ink) 82%, var(--ih-try)); border-radius: var(--ih-r); background: var(--ih-try); color: var(--ih-try-ink); overflow: hidden; }
.cp-imp-try .cp-imp-h2 em { color: inherit; }
.cp-imp-strip { margin: 0; padding: 26px clamp(18px, 4vw, 56px) 14px; border-bottom: 1.5px solid var(--ih-try-ink); background: repeating-linear-gradient(to bottom, transparent 0 19px, rgb(28 23 20 / .14) 19px 20px); }
.cp-imp-strip-lane { position: relative; height: 80px; }
.cp-imp-strip-note { position: absolute; top: calc(var(--row) * 10px + 1px); height: 8px; border-radius: 99px; background: var(--ih-try-ink); clip-path: inset(0 3px 0 0 round 99px); }
.cp-imp-strip-held { background: #fff6dc; box-shadow: 0 0 14px 2px rgb(255 246 220 / .8); clip-path: none; }
.cp-imp-strip-held b { position: absolute; inset-inline-start: 0; bottom: 100%; padding-bottom: 3px; font-size: 12px; font-weight: 800; }
.cp-imp-try-in { display: grid; grid-template-columns: minmax(0, 1fr); gap: 28px; padding: clamp(26px, 4vw, 56px); }
.cp-imp-try-lead { margin-top: 18px; font-size: 16px; line-height: 1.55; }
.cp-imp-try-after { margin-top: 18px; font-size: 14px; line-height: 1.55; max-width: 52ch; }
.cp-imp-try-steps li { display: grid; grid-template-columns: 26px minmax(0, 1fr); gap: 14px; padding-block: 16px; border-top: 1px solid rgb(28 23 20 / .28); font-size: 16px; line-height: 1.55; }
.cp-imp-try-steps .cp-imp-shape { margin-top: 2px; font-size: 22px; --ih-shape: var(--ih-try-ink); }
@media (min-width: 900px) { .cp-imp-try-in { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 64px; } }

/* The night bands: what the app listens for beside a sample take, and the close. */
.cp-imp-dark { --color-cream: var(--ih-n-ink); --color-muted: var(--ih-n-muted); --k-line-strong: rgb(244 238 230 / .2); --primary: var(--ih-lit); --primary-ink: var(--ih-lit-ink); --btn-soft: rgb(244 238 230 / .1); --btn-soft-hover: rgb(244 238 230 / .16); --fill-2: rgb(244 238 230 / .09); --fill-3: rgb(244 238 230 / .14); padding-block: clamp(64px, 8vw, 112px); background: var(--ih-night); color: var(--ih-n-ink); }
.cp-imp-dark .cp-imp-h2 em { color: var(--ih-lit); }
.cp-imp-hears { display: grid; grid-template-columns: minmax(0, 1fr); gap: 40px; align-items: center; }
.cp-imp-take { margin: 0; padding: 22px 24px; border: 1px solid var(--ih-n-line); border-radius: var(--ih-r-s); background: var(--ih-night-2); }
.cp-imp-take-head { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 4px 16px; font-size: 12px; font-weight: 700; letter-spacing: .14em; text-transform: uppercase; color: var(--ih-n-muted); }
.cp-imp-take-head b { padding: 2px 8px; border-radius: 6px; background: rgb(244 238 230 / .12); color: var(--ih-n-ink); }
.cp-imp-take-lane { position: relative; height: 92px; margin-top: 22px; background: linear-gradient(var(--ih-n-line), var(--ih-n-line)) 0 50% / 100% 1px no-repeat; }
.cp-imp-take-note, .cp-imp-take-tune { position: absolute; height: 10px; border-radius: 99px; border-inline-end: 3px solid transparent; background-clip: padding-box; }
.cp-imp-take-note { top: 8px; background-color: var(--ih-lit); }
.cp-imp-take-miss { background: none; border: 1.5px dashed var(--ih-miss); }
.cp-imp-take-tune { bottom: 8px; background-color: var(--ih-tune); }
.cp-imp-take-pulled::after { content: ""; position: absolute; inset-inline: 0; bottom: 14px; height: 8px; border-radius: 99px; background: var(--ih-miss); }
.cp-imp-take-pulled b { position: absolute; inset-inline-end: 0; bottom: 26px; padding-inline-start: 14px; white-space: nowrap; font-size: 12px; font-weight: 700; color: var(--ih-miss); }
.cp-imp-take-pulled b::before { content: "\2193"; position: absolute; inset-inline-start: 0; }
.cp-imp-take-foot { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: end; gap: 14px 24px; margin-top: 20px; padding-top: 18px; border-top: 1px solid var(--ih-n-line); }
.cp-imp-score b { display: block; font-size: 44px; font-weight: 900; line-height: 1; letter-spacing: -0.03em; font-variant-numeric: tabular-nums; }
.cp-imp-score span { font-size: 14px; color: var(--ih-n-muted); }
.cp-imp-legend { display: flex; flex-wrap: wrap; gap: 6px 16px; font-size: 13px; color: var(--ih-n-ink); }
.cp-imp-legend li { display: inline-flex; align-items: center; gap: 7px; }
.cp-imp-legend i { width: 16px; height: 6px; border-radius: 99px; }
.cp-imp-key-1 { background: var(--ih-lit); }
.cp-imp-key-2 { background: var(--ih-miss); }
.cp-imp-key-3 { background: var(--ih-tune); }
.cp-imp-sample-note { margin-top: 14px; font-size: 13px; color: var(--ih-n-muted); }
@media (min-width: 900px) { .cp-imp-hears { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 64px; } }

/* About harmony singing: the three checked facts as a timeline, each era on its shape. */
.cp-imp-time { display: grid; grid-template-columns: minmax(0, 1fr); gap: 32px; margin-top: 36px; }
.cp-imp-time li { position: relative; padding-top: 26px; font-size: 16.5px; line-height: 1.55; }
.cp-imp-time li::before { content: ""; position: absolute; inset-inline: 0; top: 9px; height: 1.5px; background: var(--color-cream); }
.cp-imp-time .cp-imp-shape { position: absolute; inset-inline-start: 0; top: 0; font-size: 20px; }
.cp-imp-era { margin-bottom: 8px; font-size: clamp(30px, 3vw, 38px); line-height: 1.1; font-style: normal; color: var(--ih-em); }
/* A numbered note: a 44 px tap that never moves its line (padding cancelled by margin). */
.cp-imp .s-cite a { display: inline-block; padding: 12px 4px; margin: -12px -4px; color: var(--ih-em); }
@media (min-width: 900px) { .cp-imp-time { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 48px 40px; } }

/* Why it works: four ruled columns, each rule in plain words over the checked fact behind it. */
.cp-imp-why-list { display: grid; grid-template-columns: minmax(0, 1fr); gap: 0 32px; margin-top: 36px; border-top: 1.5px solid var(--color-cream); }
.cp-imp-why-list li { padding-block: 24px; border-bottom: 1px solid var(--k-line-strong); }
.cp-imp-why-list h3 { font-size: 20px; font-weight: 800; letter-spacing: -0.015em; line-height: 1.25; }
.cp-imp-why-plain { margin-top: 10px; font-size: 16px; line-height: 1.55; text-wrap: pretty; }
.cp-imp-why-fact { margin-top: 14px; padding-top: 14px; border-top: 1px dashed var(--k-line-strong); font-family: var(--ih-serif); font-style: italic; font-size: 15px; line-height: 1.6; color: var(--color-muted); }
@media (min-width: 640px) { .cp-imp-why-list { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (min-width: 1100px) { .cp-imp-why-list { grid-template-columns: repeat(4, minmax(0, 1fr)); } .cp-imp-why-list li { border-bottom: 0; } }

/* Lesson 1, step by step: its why and cards at left, its three sung steps as a numbered tunebook list at right. */
.cp-imp-one { display: grid; grid-template-columns: minmax(0, 1fr); gap: 32px; }
.cp-imp-one-why { margin-top: 22px; font-family: var(--ih-serif); font-style: italic; font-size: clamp(19px, 1.7vw, 22px); line-height: 1.5; color: var(--ih-em); }
.cp-imp-one-cards { display: grid; gap: 10px; margin-top: 22px; }
.cp-imp-one-cards li { display: grid; gap: 2px; padding: 14px 18px; border: 1px solid var(--k-line-strong); border-radius: var(--ih-r-s); background: var(--color-panel); font-size: 14.5px; line-height: 1.45; color: var(--color-muted); }
.cp-imp-one-cards b { font-size: 15.5px; color: var(--color-cream); }
.cp-imp-one-steps { align-self: center; border-top: 1.5px solid var(--color-cream); }
.cp-imp-one-steps li { display: grid; grid-template-columns: 22px 28px minmax(0, 1fr); gap: 12px; align-items: baseline; padding-block: 20px; border-bottom: 1px solid var(--k-line-strong); font-size: 17px; line-height: 1.55; }
.cp-imp-one-steps .cp-imp-shape { font-size: 18px; align-self: start; margin-top: 4px; }
.cp-imp-one-steps .cp-imp-num { font-size: 22px; }
@media (min-width: 900px) { .cp-imp-one { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 64px; } }

/* The one Sources list. */
.cp-imp-sources { padding-block: 8px clamp(56px, 7vw, 88px); }
.cp-imp-sources ol { margin-top: 16px; padding-inline-start: 22px; list-style: decimal; column-gap: 40px; font-size: 14px; line-height: 1.5; color: var(--color-muted); }
.cp-imp-sources li { padding-block: 6px; break-inside: avoid; }
.cp-imp-sources a { color: var(--color-muted); text-decoration: underline 1px; text-underline-offset: 3px; padding-block: 12px; margin-block: -12px; }
.cp-imp-sources a:hover { color: var(--color-cream); }
@media (min-width: 900px) { .cp-imp-sources ol { columns: 2; } }

/* Who it's for, what you need and singing safely, beside the songs. */
.cp-imp-about { display: grid; grid-template-columns: minmax(0, 1fr); gap: 40px; align-items: start; }
.cp-imp-lists { display: grid; gap: 36px; }
.cp-imp-list li { display: grid; grid-template-columns: 18px minmax(0, 1fr); gap: 12px; padding-block: 13px; border-bottom: 1px solid var(--k-line-strong); font-size: 16px; line-height: 1.5; }
.cp-imp-list .cp-imp-shape { margin-top: 6px; font-size: 10px; }
.cp-imp-songs { padding: 26px 28px; border: 1px solid var(--k-line-strong); border-radius: var(--ih-r); background: var(--color-panel); }
.cp-imp-songs ol { margin-top: 10px; }
.cp-imp-songs li { display: grid; grid-template-columns: 30px minmax(0, 1fr); gap: 10px; padding-block: 13px; border-bottom: 1px dashed var(--k-line-strong); }
.cp-imp-songs li:last-child { border-bottom: 0; }
.cp-imp-songs b { display: block; font-size: 16px; }
.cp-imp-songs li > span > span { font-size: 14px; color: var(--color-muted); }
@media (min-width: 900px) { .cp-imp-about { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 64px; } }

/* Questions beside their heading. */
.cp-imp-faq { display: grid; grid-template-columns: minmax(0, 1fr); gap: 12px 64px; }
.cp-imp-faq .cp-faq { max-width: none; }
.cp-imp-faq .cp-faq details[open] .cp-faq-sign { background: var(--color-cream); color: var(--color-ink); }
@media (min-width: 960px) { .cp-imp-faq { grid-template-columns: minmax(0, 1fr) minmax(0, 2fr); align-items: start; } .cp-imp-faq .cp-faq { margin-top: 14px; } }

/* The close: centred on the night, a small lane over it. */
.cp-imp-join { text-align: center; }
.cp-imp-join-mark { display: grid; gap: 7px; width: 120px; margin-inline: auto; margin-bottom: 26px; }
.cp-imp-join-mark i { height: 10px; border-radius: 99px; background: var(--ih-tune); }
.cp-imp-join-mark i:nth-child(1) { background: none; border: 1.5px dashed var(--ih-lit); }
.cp-imp-join-mark i:nth-child(2) { background: var(--ih-lit); box-shadow: 0 0 14px var(--ih-lit); }
.cp-imp-join .cp-join-btns, .cp-imp-join .cp-related { justify-content: center; }
.cp-imp-join .cp-join-btns > a { white-space: nowrap; }
.cp-imp-join .cp-imp-kick { margin-top: 48px; color: var(--ih-n-muted); }
.cp-imp-join .cp-related a svg { color: var(--ih-lit); }
/* The close's own button already leads to all the courses. */
.cp-imp-join .cp-related-all { display: none; }
@media (max-width: 639px) { .cp-imp-join .cp-join-btns { flex-direction: column; align-items: stretch; } .cp-imp-join .cp-join-btns > a { justify-content: center; } }

/* Reduced motion: the lights switch at once. */
@media (prefers-reduced-motion: reduce) { .cp-imp-note::before, .cp-imp-words span { transition: none; } }

/* The game skin: the arcade's own heading sizes (the shared [data-gs] rules), their key words in its pink, square
   corners, yellow lights. */
:root[data-skin="game"] body.s-arcade .cp-imp :is(.cp-imp-h1, .cp-imp-h2) em { font-family: inherit; font-style: normal; font-weight: inherit; letter-spacing: inherit; }
:root[data-skin="game"] body.s-arcade .cp-imp-dark .cp-imp-h2 em { color: var(--a-yellow); }
:root[data-skin="game"] body.s-arcade .cp-imp-words { font-size: 11px; }
@media (max-width: 639px) { :root[data-skin="game"] body.s-arcade .cp-imp-words { font-size: 9px; } }
:root[data-skin="game"] body.s-arcade :is(.cp-imp-chip, .cp-imp-chip b, .cp-imp-take-head b) { border-radius: 0; }
:root[data-skin="game"] body.s-arcade :is(.cp-imp-player, .cp-imp-card, .cp-imp-songs, .cp-imp-take) { border: var(--arc-edge-w, 2px) solid var(--arc-line); box-shadow: var(--arc-shadow); }
:root[data-skin="game"] body.s-arcade :is(.cp-imp-play, .cp-imp-steps, .cp-imp-steps button) { border-radius: 0; }
:root[data-skin="game"] body.s-arcade :is(.cp-imp-bar, .cp-imp-play, .cp-imp-steps button, .cp-imp-kick) { font-family: var(--a-hud); font-weight: 400; font-size-adjust: var(--arc-ex, none); letter-spacing: .06em; }
:root[data-skin="game"] body.s-arcade .cp-imp-play { font-size: 11px; }
:root[data-skin="game"] body.s-arcade .cp-imp-steps { grid-template-columns: repeat(2, minmax(0, 1fr)); }
/* On the night bands the arcade's outlined secondary takes its cyan in every theme, as it does on a dark ground. */
:root[data-skin="game"][data-gs] body.s-arcade:not(.s-calm) .cp-imp-dark .btn-secondary { color: #3be7ff; border-color: #3be7ff; box-shadow: inset 0 0 0 2px #3be7ff; }
@media (max-width: 359px) { :root[data-skin="game"] body.s-arcade .cp-imp-play { padding-inline-end: 12px; font-size: 10px; } }
:root[data-skin="game"] body.s-arcade .cp-imp-steps button { font-size: 10px; }
:root[data-skin="game"] body.s-arcade .cp-imp-top { align-items: center; }
:root[data-skin="game"] body.s-arcade :is(.cp-imp-mark span, .cp-imp-era, .cp-imp-num, .cp-imp-index-note, .cp-imp-tag, .cp-imp-why-fact, .cp-imp-one-why) { font-family: inherit; font-style: normal; }
:root[data-skin="game"] body.s-arcade .cp-imp-one-cards li { border-radius: 0; }

/* Backing vocals (site/courses/backing-vocals): Hillel's design (2026-11-18, ~/Code/course-designs/backing-vocals),
   the backing parts as stacked coloured lanes, like a multitrack. The parts' own colours (s-v1 pad, s-v2 doo-wop, s-v3
   answers, s-v4 a real song: --c, --ci, --ct) and the theme's tokens only, so calm light and dark and game all draw it.
   The hero's "behind" with a copy in each backing part's colour; Shenandoah's lanes in one panel with a playhead (still
   under reduced motion); the units with their strips; a sample result card; the setlist beside singing safely;
   Amazing Grace's four parts on the dark band; every lesson's page (course.blade.php's nav) in four unit columns. */
.cp-bv-hero { padding-top: 20px; }
.cp-bv-top { display: grid; grid-template-columns: minmax(0, 1fr); gap: 28px; margin-top: 24px; }
.cp-bv-open { display: inline-flex; align-items: center; gap: 8px; padding: 6px 13px; border-radius: 99px; background: color-mix(in srgb, var(--color-good) 16%, var(--color-ink)); color: var(--color-cream); font-size: 13.5px; font-weight: 650; white-space: nowrap; }
.cp-bv-open-dot { flex: none; width: 8px; height: 8px; border-radius: 99px; background: var(--color-good); }
.cp-bv-hero h1 { margin-top: 20px; font-size: clamp(50px, 12.5vw, 96px); line-height: .95; font-weight: 900; letter-spacing: -0.045em; }
.cp-bv-line { display: block; }
.cp-bv-behind { padding-inline-end: .14em; text-shadow: .04em .04em 0 var(--color-part-3), .08em .08em 0 var(--color-part-2), .12em .12em 0 var(--color-part-1); }
.cp-bv-lead { font-size: clamp(17px, 1.6vw, 19px); line-height: 1.55; color: var(--color-muted); max-width: 52ch; text-wrap: pretty; }
.cp-bv-btns { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 24px; }
.cp-bv-btns > a { white-space: nowrap; }
@media (max-width: 639px) {
    .cp-bv-btns { flex-direction: column; align-items: stretch; }
    .cp-bv-btns > a { justify-content: center; width: 100%; }
}
@media (prefers-reduced-motion: no-preference) {
    .cp-bv-open-dot { animation: cp-bv-pulse 2s ease-in-out infinite; }
    .cp-bv-panel:not([data-playing]) .cp-bv-ph { animation: cp-bv-sweep 15.24s linear infinite; }
}
@keyframes cp-bv-pulse { 50% { opacity: .35; } }
@keyframes cp-bv-sweep { from { left: 0%; } to { left: 100%; } }

/* The multitrack: names in a column, a lane a row, the bar lines and the playhead over every lane. */
.cp-bv-panel { margin-top: clamp(36px, 5vw, 56px); padding: clamp(18px, 2.4vw, 28px); border-radius: 22px; background: var(--color-panel); border: 1px solid var(--color-edge); box-shadow: 0 30px 60px -40px rgb(60 40 20 / .35); }
.cp-bv-panel-head { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 20px; margin-bottom: 22px; }
.cp-bv-panel-head .s-kick { flex: 1 1 auto; }
.cp-bv-quiet { color: var(--color-muted); letter-spacing: .1em; }
.cp-bv-panel-note { font-size: 14px; color: var(--color-muted); }
.cp-bv-play { display: inline-flex; align-items: center; gap: 10px; min-height: 44px; padding: 0 18px 0 7px; border-radius: 99px; background: var(--fill-2, var(--color-raised)); color: var(--color-cream); font-size: 15px; font-weight: 700; white-space: nowrap; }
.cp-bv-play:hover { background: var(--fill-3, var(--color-line)); }
.cp-bv-play:focus-visible { outline: 3px solid var(--color-cream); outline-offset: 2px; }
.cp-bv-play-icon { position: relative; flex: none; width: 30px; height: 30px; border-radius: 99px; background: var(--color-cream); }
.cp-bv-play-icon::before { content: ""; position: absolute; inset-block-start: 9px; inset-inline-start: 11px; border-block: 6px solid transparent; border-inline-start: 10px solid var(--color-ink); }
.cp-bv-play[aria-pressed="true"] .cp-bv-play-icon::before { inset: 10px; border: 0; border-radius: 2px; background: var(--color-ink); }
.cp-bv-fig { margin: 0; }
.cp-bv-tracks { container-type: inline-size; display: grid; grid-template-columns: max-content minmax(0, 1fr); gap: 10px 14px; }
.cp-bv-name { grid-column: 1; display: flex; align-items: center; height: 34px; font-size: 13px; font-weight: 700; color: var(--ci, var(--color-cream)); }
.cp-bv-lane { grid-column: 2; position: relative; z-index: 1; height: 34px; }
.cp-bv-is-lead { --c: var(--color-cream); --ci: var(--color-cream); --ct: var(--color-ink); }
.cp-bv-seg { position: absolute; inset-block: 0; display: flex; align-items: center; padding-inline: 6px 3px; overflow: hidden; white-space: nowrap; border-radius: 8px; border-inline-end: 3px solid transparent; background: var(--c); background-clip: padding-box; color: var(--ct); font-size: 12px; font-weight: 700; transition: opacity .08s; }
.cp-bv-grid { grid-column: 2; position: relative; z-index: 0; pointer-events: none; background-image: repeating-linear-gradient(to right, var(--color-edge) 0 1px, transparent 1px 25%); }
.cp-bv-over { grid-column: 2; position: relative; z-index: 2; pointer-events: none; }
.cp-bv-ph { position: absolute; inset-block: -8px; inset-inline-start: calc(var(--p, 0) * 100%); width: 2px; margin-inline-start: -1px; border-radius: 1px; background: var(--color-cream); }
.cp-bv-panel[data-playing] .cp-bv-lane .cp-bv-seg { opacity: .45; }
.cp-bv-panel[data-playing] .cp-bv-lane .cp-bv-seg[data-on] { opacity: 1; }
/* A word shows only where its note is wide enough for all of it (js/public/backing-vocals.js measures; a phone: the
   long notes' alone), never cut. */
.cp-bv-seg[data-cut] > span { visibility: hidden; }
@container (max-width: 560px) {
    .cp-bv-name, .cp-bv-lane { height: 28px; }
    .cp-bv-name { font-size: 12px; }
    .cp-bv-seg { border-radius: 6px; border-inline-end-width: 2px; }
}
.cp-bv-source { margin-top: 18px; font-size: 13.5px; line-height: 1.5; color: var(--color-muted); max-width: 80ch; }
.cp-bv-learn { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 210px), 1fr)); gap: 16px 28px; margin-top: 22px; padding-top: 22px; border-top: 1px solid var(--color-edge); }
.cp-bv-learn li { display: flex; gap: 10px; font-size: 15px; line-height: 1.5; color: var(--color-muted); }
.cp-bv-learn b { color: var(--color-cream); }
.cp-bv-key { flex: none; width: 10px; height: 10px; margin-top: 6px; border-radius: 3px; background: var(--c); }

/* The sections. */
.cp-bv-sec { padding-top: clamp(64px, 9vw, 120px); }
.cp-bv-h2 { font-size: clamp(32px, 4vw, 48px); line-height: 1.02; font-weight: 800; letter-spacing: -0.035em; text-wrap: balance; }
.cp-bv-h2-s { margin-top: 14px; font-size: clamp(28px, 3.4vw, 40px); line-height: 1.05; }
.cp-bv-h2-l { margin-top: 16px; font-size: clamp(38px, 5vw, 64px); line-height: .98; letter-spacing: -0.045em; font-weight: 900; }
.cp-bv-p { margin-top: 16px; font-size: 17px; line-height: 1.6; color: var(--color-muted); max-width: 56ch; text-wrap: pretty; }
.cp-bv-num { flex: none; width: 24px; font-size: 13px; font-weight: 600; font-variant-numeric: tabular-nums; letter-spacing: .04em; color: var(--color-muted); }

/* The units: a ruled list, each unit's number in its colour beside a strip of its technique, its lessons at right. */
.cp-bv-units-head { display: flex; flex-wrap: wrap; align-items: end; justify-content: space-between; gap: 12px 16px; }
.cp-bv-count { font-size: 13px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--color-muted); }
.cp-bv-units { margin-top: 32px; border-top: 1px solid var(--color-cream); }
.cp-bv-unit { display: grid; grid-template-columns: minmax(0, 1fr); gap: 22px 48px; padding-block: 32px; border-bottom: 1px solid var(--color-edge); }
.cp-bv-unit-head { display: flex; align-items: baseline; gap: 14px; }
.cp-bv-unit-n { font-size: 56px; font-weight: 900; line-height: .9; letter-spacing: -0.05em; color: var(--ci); font-variant-numeric: tabular-nums; }
.cp-bv-unit h3 { font-size: 24px; font-weight: 800; letter-spacing: -0.02em; }
.cp-bv-unit-sub { margin-top: 4px; font-size: 15px; line-height: 1.45; color: var(--color-muted); }
.cp-bv-strip { display: grid; gap: 6px; margin-top: 22px; background-image: repeating-linear-gradient(to right, var(--color-edge) 0 1px, transparent 1px 25%); }
.cp-bv-strip-lane { position: relative; height: 16px; }
.cp-bv-strip-lane i { position: absolute; inset-block: 0; border-radius: 5px; border-inline-end: 3px solid transparent; background: var(--c); background-clip: padding-box; }
.cp-bv-strip .cp-bv-ghost { --c: color-mix(in srgb, var(--color-cream) 16%, transparent); }
.cp-bv-strip .cp-bv-is-lead { --c: color-mix(in srgb, var(--color-cream) 55%, transparent); }
.cp-bv-lessons li { display: flex; flex-wrap: wrap; align-items: center; gap: 6px 14px; min-height: 46px; padding-block: 8px; border-bottom: 1px dashed var(--color-edge); font-size: 16px; }
.cp-bv-lessons a { padding-block: 10px; margin-block: -10px; font-weight: 550; text-decoration: underline; text-decoration-color: color-mix(in srgb, var(--color-cream) 30%, transparent); text-underline-offset: 4px; }
.cp-bv-lessons a:hover { text-decoration-color: currentColor; }
.cp-bv-lessons .s-free { margin: 0; }

/* What the app listens for, beside the sample card. */
.cp-bv-hears { display: grid; grid-template-columns: minmax(0, 1fr); gap: 36px 72px; align-items: start; }
.cp-bv-card { padding: clamp(20px, 2.5vw, 28px); border-radius: 22px; background: var(--color-panel); border: 1px solid var(--color-edge); }
.cp-bv-sample { display: flex; flex-wrap: wrap; align-items: baseline; gap: 6px 10px; font-size: 14px; line-height: 1.45; color: var(--color-muted); }
.cp-bv-sample b { padding: 3px 10px; border-radius: 99px; background: var(--fill-2, var(--color-raised)); color: var(--color-cream); font-size: 12px; font-weight: 800; letter-spacing: .08em; text-transform: uppercase; white-space: nowrap; }
.cp-bv-dots { display: grid; grid-template-columns: repeat(12, minmax(0, 1fr)); gap: 6px; margin-top: 20px; }
.cp-bv-dots li { aspect-ratio: 1; border-radius: 99px; background: var(--c); border: 2px solid var(--c); }
.cp-bv-dots .cp-bv-miss { background: transparent; border-color: var(--color-line); }
.cp-bv-stats { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 16px; margin-top: 24px; }
.cp-bv-stats b { display: block; font-size: 40px; font-weight: 900; line-height: 1; letter-spacing: -0.04em; font-variant-numeric: tabular-nums; }
.cp-bv-stats small { font-size: 20px; font-weight: 700; letter-spacing: -0.01em; color: var(--color-muted); }
.cp-bv-stats span { display: block; margin-top: 6px; font-size: 14px; color: var(--color-muted); }
.cp-bv-phones { margin-top: 22px; padding-top: 18px; border-top: 1px solid var(--color-edge); font-size: 14.5px; line-height: 1.5; color: var(--color-muted); }
.cp-bv-phones b { color: var(--color-cream); }

/* The setlist, numbered, beside singing safely. */
.cp-bv-songs { display: grid; grid-template-columns: minmax(0, 1fr); gap: 40px 72px; }
.cp-bv-setlist { margin-top: 16px; border-top: 1px solid var(--color-cream); }
.cp-bv-setlist li { display: grid; grid-template-columns: 28px minmax(0, 1fr); gap: 2px 14px; align-items: baseline; padding-block: 14px; border-bottom: 1px solid var(--color-edge); }
.cp-bv-setlist b { font-size: 18px; font-weight: 700; letter-spacing: -0.01em; }
.cp-bv-credit { grid-column: 2; font-size: 14px; line-height: 1.45; color: var(--color-muted); }
.cp-bv-safe { display: grid; gap: 14px; margin-top: 16px; padding: 22px; border-radius: 18px; background: color-mix(in srgb, var(--color-cream) 6%, var(--color-ink)); font-size: 16px; line-height: 1.45; }
.cp-bv-safe li { display: flex; gap: 10px; align-items: flex-start; }
.cp-bv-safe svg { flex: none; margin-top: 2px; color: var(--color-part-ink-2); }

/* New to harmony: the dark band, Amazing Grace's four parts beside the words. */
.cp-bv-today { margin-top: clamp(64px, 9vw, 120px); }
.cp-bv-today-in { display: grid; grid-template-columns: minmax(0, 1fr); gap: 40px 72px; align-items: center; }
.cp-bv-grace { margin: 0; padding: clamp(18px, 2.4vw, 26px); border-radius: 22px; background: color-mix(in srgb, var(--color-cream) 6%, transparent); }
.cp-bv-grace .s-kick { margin-bottom: 18px; }
.cp-bv-tracks-sm .cp-bv-name { height: 28px; color: var(--color-muted); }
.cp-bv-tracks-sm .cp-bv-lane { height: 28px; }
.cp-bv-tracks-sm .cp-bv-seg { border-radius: 7px; font-size: 11.5px; }
.cp-bv-grid-3 { background-image: repeating-linear-gradient(to right, color-mix(in srgb, var(--color-cream) 14%, transparent) 0 1px, transparent 1px 25%); }

/* The length pass (Hillel, 2026-11-18): lesson 1 to try, why it works, the archive, who and what you need, the questions,
   the close and the Sources, in the same lanes and part colours. */
/* Try it now: lesson 1's words beside four takes, each numbered on a lane block in a part's colour. */
.cp-bv-try { display: grid; grid-template-columns: minmax(0, 1fr); gap: 28px 72px; align-items: start; }
.cp-bv-takes { display: grid; gap: 10px; }
.cp-bv-takes li { display: flex; gap: 16px; align-items: flex-start; padding: 14px 18px 14px 14px; border-radius: 16px; background: var(--color-panel); border: 1px solid var(--color-edge); font-size: 16.5px; line-height: 1.5; }
.cp-bv-take { flex: none; display: grid; place-items: center; width: 44px; height: 28px; border-radius: 8px; background: var(--c); color: var(--ct); font-size: 14px; font-weight: 800; font-variant-numeric: tabular-nums; }
.cp-bv-after { margin-top: 18px; font-size: 15px; line-height: 1.55; color: var(--color-muted); max-width: 62ch; text-wrap: pretty; }

/* Why it works: the panel of lesson 1's three lanes (the chords as blocks naming their notes, the pad's note filled in its
   colour), then three points in columns, each over a strip of its idea. */
.cp-bv-why-h { margin-top: 14px; max-width: 18ch; }
.cp-bv-panel-why { margin-top: 32px; }
.cp-bv-panel-why > .s-kick { margin-bottom: 18px; }
.cp-bv-grid-8, .cp-bv-strip-8 { background-image: repeating-linear-gradient(to right, var(--color-edge) 0 1px, transparent 1px 12.5%); }
.cp-bv-lane-ghost .cp-bv-seg { background: color-mix(in srgb, var(--color-cream) 14%, transparent); color: var(--color-cream); font-weight: 600; }
.cp-bv-name-chords, .cp-bv-lane-chords { height: 64px; }
.cp-bv-chord { position: absolute; inset-block: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 1px; border-inline-end: 3px solid transparent; background-clip: padding-box; }
.cp-bv-chord::before { content: ""; position: absolute; inset: 0; z-index: -1; border-radius: 8px; border: 1px solid var(--color-line); background: var(--color-panel); }
.cp-bv-chord > span { padding: 0 6px; border-radius: 99px; font-size: 12px; line-height: 18px; font-weight: 650; color: var(--color-muted); }
.cp-bv-chord > .cp-bv-shared { background: var(--c); color: var(--ct); font-weight: 800; }
.cp-bv-points { display: grid; grid-template-columns: minmax(0, 1fr); gap: 36px 40px; margin-top: 40px; }
.cp-bv-points .cp-bv-strip { position: relative; height: 60px; margin-top: 0; align-content: end; }
/* Two notes side by side read as one number ("1 4" as 14): a comma between them, on this page. */
.cp-bv .s-cite + .s-cite::before { content: ","; }
.cp-bv-points h3 { display: flex; align-items: baseline; gap: 10px; margin-top: 18px; font-size: 21px; font-weight: 800; letter-spacing: -0.02em; color: var(--ci); }
.cp-bv-points h3 .cp-bv-num { width: auto; }
.cp-bv-points p { margin-top: 8px; font-size: 16px; line-height: 1.6; color: var(--color-muted); text-wrap: pretty; }
.cp-bv-strip-cut { position: absolute; inset-block: -6px; inset-inline-start: 75%; width: 2px; margin-inline-start: -1px; border-radius: 1px; background: var(--color-cream); }

/* The archive as a session: a track a row, its name and key in the part's colour, its facts as clips with a coloured
   header, like a region in a recording. */
.cp-bv-session { margin-top: 32px; border-top: 1px solid var(--color-cream); }
.cp-bv-track { display: grid; grid-template-columns: minmax(0, 1fr); gap: 14px 28px; padding-block: 22px; border-bottom: 1px solid var(--color-edge); }
.cp-bv-track-name { display: flex; align-items: center; gap: 10px; font-size: 18px; font-weight: 800; letter-spacing: -0.01em; color: var(--ci); }
.cp-bv-track-name .cp-bv-key { margin-top: 0; }
.cp-bv-clips { display: grid; grid-template-columns: repeat(auto-fill, minmax(min(100%, 280px), 1fr)); gap: 12px; }
.cp-bv-clip { overflow: hidden; border-radius: 14px; border: 1px solid color-mix(in srgb, var(--c) 45%, transparent); background: color-mix(in srgb, var(--c) 9%, var(--color-panel)); }
.cp-bv-clip-tag { padding: 5px 14px; background: var(--c); color: var(--ct); font-size: 12.5px; font-weight: 800; letter-spacing: .08em; text-transform: uppercase; }
.cp-bv-clip-text { padding: 12px 16px 16px; font-size: 15.5px; line-height: 1.55; text-wrap: pretty; }

/* Who it's for and what you need, as ruled rows over the setlist and singing safely. */
.cp-bv-rules { margin-top: 16px; border-top: 1px solid var(--color-cream); }
.cp-bv-rules li { padding-block: 13px; border-bottom: 1px solid var(--color-edge); font-size: 16.5px; line-height: 1.5; }

/* The questions beside their heading. */
.cp-bv-faq { display: grid; grid-template-columns: minmax(0, 1fr); gap: 8px 72px; align-items: start; }
.cp-bv-faq .cp-faq { margin-top: 0; }

/* The close: the hero's lanes again, the guide's and yours, beside the way in. */
.cp-bv-close { display: grid; grid-template-columns: minmax(0, 1fr); gap: 32px 64px; align-items: center; margin-top: 0; }
.cp-bv-close .cp-bv-btns { margin-top: 24px; }
.cp-bv-join { margin-top: 12px; font-size: 14px; color: var(--color-muted); }
.cp-bv-tracks-close .cp-bv-name, .cp-bv-tracks-close .cp-bv-lane { height: 30px; }
.cp-bv-more { margin-top: 40px; }

/* The Sources, numbered, folded on a phone. */
.cp-bv-sources { padding-block: clamp(56px, 7vw, 96px) 24px; }
.cp-bv-sources summary { display: flex; align-items: center; justify-content: space-between; gap: 16px; min-height: 44px; padding-bottom: 8px; border-bottom: 1px solid var(--color-cream); list-style: none; cursor: pointer; }
.cp-bv-sources summary::-webkit-details-marker { display: none; }
.cp-bv-sources details[open] .cp-faq-sign { rotate: 45deg; }
.cp-bv-sources h2 span { color: var(--color-muted); }
.cp-bv-sources ol { margin-top: 16px; padding-inline-start: 28px; list-style: decimal; columns: 2 360px; column-gap: 48px; font-size: 14px; line-height: 1.5; color: var(--color-muted); }
.cp-bv-sources li { margin-bottom: 8px; padding-inline-start: 4px; break-inside: avoid; }
.cp-bv-sources a { color: var(--color-cream); text-decoration: underline; text-decoration-color: var(--color-line); text-underline-offset: 3px; }
.cp-bv-sources a:hover { text-decoration-color: currentColor; }

/* Every lesson's page (course.blade.php's nav, after this page): plain links in four unit columns, each headed in its
   unit's colour. */
.cp-bv ~ [data-lesson-pages] > h3 { margin-top: 26px; padding-top: 12px; border-top: 3px solid var(--c); font-size: 14px; color: var(--color-muted); }
.cp-bv ~ [data-lesson-pages] > h3:nth-of-type(4n+1) { --c: var(--color-part-1); }
.cp-bv ~ [data-lesson-pages] > h3:nth-of-type(4n+2) { --c: var(--color-part-2); }
.cp-bv ~ [data-lesson-pages] > h3:nth-of-type(4n+3) { --c: var(--color-part-3); }
.cp-bv ~ [data-lesson-pages] > h3:nth-of-type(4n+4) { --c: var(--color-part-4); }
.cp-bv ~ [data-lesson-pages] .s-cards { display: flex; flex-direction: column; gap: 6px; margin-top: 8px; }
.cp-bv ~ [data-lesson-pages] .s-card,
:root[data-skin='game'][data-gs] body.s-arcade .cp-bv ~ [data-lesson-pages] .s-card { gap: 3px; height: auto; padding: 8px 0; border: 0; border-radius: 0; background: none; box-shadow: none; }
.cp-bv ~ [data-lesson-pages] .s-card b { font-size: 15.5px; font-weight: 700; }
.cp-bv ~ [data-lesson-pages] .s-card:hover b { text-decoration: underline; text-underline-offset: 3px; }
.cp-bv ~ [data-lesson-pages] .s-card span:not(.s-soon) { font-size: 14px; line-height: 1.4; }

@media (min-width: 600px) {
    .cp-bv-setlist li { grid-template-columns: 28px minmax(0, 1fr) auto; }
    .cp-bv-credit { grid-column: 3; max-width: 44ch; text-align: end; font-size: 13.5px; }
    .cp-bv ~ [data-lesson-pages] { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); column-gap: 32px; align-items: start; }
    .cp-bv ~ [data-lesson-pages] > h2 { grid-column: 1 / -1; }
    .cp-bv ~ [data-lesson-pages] > h3:nth-of-type(odd), .cp-bv ~ [data-lesson-pages] > ul:nth-of-type(odd) { grid-column: 1; }
    .cp-bv ~ [data-lesson-pages] > h3:nth-of-type(even), .cp-bv ~ [data-lesson-pages] > ul:nth-of-type(even) { grid-column: 2; }
    .cp-bv ~ [data-lesson-pages] > h3:nth-of-type(-n+2) { grid-row: 2; }
    .cp-bv ~ [data-lesson-pages] > ul:nth-of-type(-n+2) { grid-row: 3; }
    .cp-bv ~ [data-lesson-pages] > h3:nth-of-type(n+3) { grid-row: 4; }
    .cp-bv ~ [data-lesson-pages] > ul:nth-of-type(n+3) { grid-row: 5; }
}
@media (min-width: 900px) {
    .cp-bv-hero { padding-top: 32px; }
    .cp-bv-top { grid-template-columns: minmax(0, 1.05fr) minmax(0, .95fr); align-items: end; gap: 40px 64px; margin-top: 28px; }
    .cp-bv-top > :last-child { padding-bottom: 8px; }
    .cp-bv-unit { grid-template-columns: repeat(2, minmax(0, 1fr)); }
    .cp-bv-hears { grid-template-columns: repeat(2, minmax(0, 1fr)); }
    .cp-bv-songs { grid-template-columns: minmax(0, 2fr) minmax(0, 1fr); }
    .cp-bv-today-in { grid-template-columns: repeat(2, minmax(0, 1fr)); }
    .cp-bv-try { grid-template-columns: minmax(0, .85fr) minmax(0, 1.15fr); }
    .cp-bv-points { grid-template-columns: repeat(3, minmax(0, 1fr)); }
    .cp-bv-track { grid-template-columns: 150px minmax(0, 1fr); align-items: start; }
    .cp-bv-track-name { padding-top: 4px; }
    .cp-bv-clips { grid-template-columns: repeat(3, minmax(0, 1fr)); }
    .cp-bv-faq { grid-template-columns: minmax(0, 1fr) minmax(0, 1.6fr); }
    .cp-bv-close { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); }
    .cp-bv ~ [data-lesson-pages] { grid-template-columns: repeat(4, minmax(0, 1fr)); }
    .cp-bv ~ [data-lesson-pages] > h3:nth-of-type(n) { grid-row: 2; }
    .cp-bv ~ [data-lesson-pages] > ul:nth-of-type(n) { grid-row: 3; }
    .cp-bv ~ [data-lesson-pages] > h3:nth-of-type(1), .cp-bv ~ [data-lesson-pages] > ul:nth-of-type(1) { grid-column: 1; }
    .cp-bv ~ [data-lesson-pages] > h3:nth-of-type(2), .cp-bv ~ [data-lesson-pages] > ul:nth-of-type(2) { grid-column: 2; }
    .cp-bv ~ [data-lesson-pages] > h3:nth-of-type(3), .cp-bv ~ [data-lesson-pages] > ul:nth-of-type(3) { grid-column: 3; }
    .cp-bv ~ [data-lesson-pages] > h3:nth-of-type(4), .cp-bv ~ [data-lesson-pages] > ul:nth-of-type(4) { grid-column: 4; }
}

/* The game skin: the arcade's pixel headings and HUD labels, square lanes and cards (the shared course rule squares
   the rest), the hero's "behind" dropping its copies in hard pixel steps. */
:root[data-skin="game"] body.s-arcade :is(.cp-bv-h2, .cp-bv-unit-n, .cp-bv-stats b) { font-family: var(--arc-pixel); font-weight: 400; letter-spacing: 0; font-size-adjust: .58; --arc-ex: .58; line-height: 1.25; text-shadow: .06em .06em 0 var(--arc-shade); }
:root[data-skin="game"] body.s-arcade .cp-bv-h2 { font-size: clamp(22px, 3vw, 34px); }
:root[data-skin="game"] body.s-arcade .cp-bv-h2-l { font-size: clamp(24px, 3.6vw, 40px); }
:root[data-skin="game"] body.s-arcade .cp-bv-behind { text-shadow: .06em .06em 0 var(--color-part-3), .12em .12em 0 var(--color-part-2), .18em .18em 0 var(--color-part-1); }
:root[data-skin="game"] body.s-arcade :is(.cp-bv-count, .cp-bv-sample b, .cp-bv-open, .cp-bv-clip-tag) { font-family: var(--a-hud); font-weight: 400; font-size: 11px; font-size-adjust: var(--arc-ex, none); letter-spacing: .06em; }
:root[data-skin='game'][data-gs] body.s-arcade:not(.s-calm) .cp-bv-unit h3 { font-size: 17px; line-height: 1.35; }
:root[data-skin="game"] body.s-arcade :is(.cp-bv-panel, .cp-bv-card, .cp-bv-clip) { border: var(--arc-edge-w, 2px) solid var(--arc-line); box-shadow: var(--arc-shadow); }
:root[data-skin="game"] body.s-arcade :is(.cp-bv-seg, .cp-bv-strip-lane i, .cp-bv-key, .cp-bv-take, .cp-bv-chord > span, .cp-bv-takes li, .cp-bv-clip) { border-radius: 0; }
:root[data-skin="game"] body.s-arcade .cp-bv-chord::before { border-radius: 0; }
:root[data-skin="game"] body.s-arcade .cp-bv-points h3 { font-size: 18px; }

/* Humming and lip trills (site/courses/humming-and-lip-trills): Hillel's design (2026-11-18,
   ~/Code/course-designs/humming-and-lip-trills), the course's four sounds, each with its own colour and line shape: lip
   trill (s-v1, bubbles on a roller coaster), "ng" siren (s-v2, a glide), hum (s-v3, a buzzing line) and "ah" (s-v4, a
   ribbon that widens), the part tokens (--c, --ci) and the theme's only, so calm light and dark and game all draw them.
   The hero's ribbon with its sweeping line (still under reduced motion, held by its pause button); the units with
   their shapes; the facts led by their big words; a sample take beside what the app listens for; singing safely beside
   its scale; the beginner course on a dark band in every look, beside Amazing Grace's four parts; every lesson's page
   in four unit columns (in place of the shared list: the view's lesson-pages-inline); the sources. The length pass
   (2026-11-19) adds how each sound works, the dated story on one ribbon, the first lesson to try, who it's for,
   questions and a close. */
.cp-hum-hero { padding-top: 20px; }
.cp-hum-top { display: grid; grid-template-columns: minmax(0, 1fr); gap: 36px; align-items: center; }
.cp-hum-open { display: inline-flex; align-items: center; gap: 8px; margin-top: 18px; padding: 6px 14px; border-radius: 99px; background: color-mix(in srgb, var(--color-good) 16%, var(--color-ink)); color: var(--color-cream); font-size: 13.5px; font-weight: 650; white-space: nowrap; }
.cp-hum-open-dot { flex: none; width: 8px; height: 8px; border-radius: 99px; border: 2px solid var(--color-good); }
.cp-hum-hero h1 { margin-top: 20px; font-size: clamp(42px, 10vw, 68px); line-height: 1.02; font-weight: 800; letter-spacing: -0.035em; text-wrap: balance; }
.cp-hum-em { color: var(--ci); }
.cp-hum-lead { margin-top: 22px; font-size: clamp(17px, 1.6vw, 19px); line-height: 1.6; color: var(--color-muted); max-width: 50ch; text-wrap: pretty; }
.cp-hum-line { margin-top: 12px; font-size: 15px; color: var(--color-muted); }
.cp-hum-btns { display: flex; flex-wrap: wrap; gap: 12px; margin-top: 26px; }
.cp-hum-btns > a { white-space: nowrap; }
@media (max-width: 639px) {
    .cp-hum-btns { flex-direction: column; align-items: stretch; }
    .cp-hum-btns > a { justify-content: center; width: 100%; }
}

/* The ribbon's card: the play button, its name and the pause at the top, the ribbon, each sound's name under its part. */
.cp-hum-ribbon { margin: 0; padding: clamp(16px, 2.4vw, 24px) clamp(16px, 2.4vw, 24px) clamp(20px, 2.6vw, 28px); border-radius: 28px; background: var(--color-panel); border: 1px solid var(--color-edge); box-shadow: 0 30px 60px -30px rgb(60 40 20 / .25); }
.cp-hum-ribbon-head { display: flex; align-items: center; gap: 12px; }
.cp-hum-ribbon-name { display: flex; flex: 1 1 auto; flex-wrap: wrap; align-items: baseline; justify-content: space-between; gap: 2px 14px; min-width: 0; }
.cp-hum-ribbon-name b { font-size: 14px; font-weight: 650; }
.cp-hum-ribbon-name span { font-size: 13px; line-height: 1.35; color: var(--color-muted); }
.cp-hum-play { display: inline-flex; align-items: center; gap: 10px; min-height: 44px; padding: 0 18px 0 7px; border-radius: 99px; background: var(--fill-2, var(--color-raised)); color: var(--color-cream); font-size: 15px; font-weight: 700; white-space: nowrap; }
.cp-hum-play:hover { background: var(--fill-3, var(--color-line)); }
.cp-hum-play:focus-visible, .cp-hum-still:focus-visible { outline: 3px solid var(--color-cream); outline-offset: 2px; }
.cp-hum-play-icon { position: relative; flex: none; width: 30px; height: 30px; border-radius: 99px; background: var(--color-cream); }
.cp-hum-play-icon::before { content: ""; position: absolute; inset-block-start: 9px; inset-inline-start: 11px; border-block: 6px solid transparent; border-inline-start: 10px solid var(--color-ink); }
.cp-hum-play[aria-pressed="true"] .cp-hum-play-icon::before { inset: 10px; border: 0; border-radius: 2px; background: var(--color-ink); }
.cp-hum-still { display: grid; place-items: center; flex: none; width: 44px; height: 44px; border-radius: 99px; background: var(--fill-2, var(--color-raised)); color: var(--color-cream); }
.cp-hum-still span { width: 10px; height: 12px; border-inline: 3px solid currentColor; }
.cp-hum-still[aria-pressed="true"] { background: var(--color-cream); color: var(--color-ink); }
.cp-hum-stage { position: relative; margin-top: 8px; }
.cp-hum-stage svg, .cp-hum-unit-top svg, .cp-hum-take-art svg { display: block; width: 100%; height: auto; overflow: visible; }
.cp-hum-base { fill: none; stroke: var(--color-edge); stroke-width: 1.5; stroke-dasharray: 3 6; }
.cp-hum-shape-line { fill: none; stroke: var(--c); stroke-linecap: round; stroke-linejoin: round; }
.cp-hum-shape-dots { fill: color-mix(in srgb, var(--c) 14%, var(--color-panel)); stroke: var(--c); stroke-width: 2.5; }
.cp-hum-shape-fill { fill: var(--c); }
.cp-hum-is-trill .cp-hum-shape-line { stroke-width: 2; opacity: .45; }
.cp-hum-is-siren .cp-hum-shape-line { stroke-width: 7; }
.cp-hum-is-hum .cp-hum-shape-line { stroke-width: 4; }
.cp-hum-unit .cp-hum-is-siren .cp-hum-shape-line { stroke-width: 6; }
.cp-hum-unit .cp-hum-is-hum .cp-hum-shape-line { stroke-width: 3.5; }
.cp-hum-unit .cp-hum-shape-dots { stroke-width: 2.2; fill: var(--color-panel); }
.cp-hum-ph { position: absolute; inset-block: 4px; inset-inline-start: calc(var(--p, .036) * 100%); width: 2px; margin-inline-start: -1px; border-radius: 1px; background: var(--color-cream); opacity: 0; pointer-events: none; }
.cp-hum-ribbon[data-playing] .cp-hum-ph { opacity: .6; }
@media (prefers-reduced-motion: no-preference) {
    .cp-hum-ribbon:not([data-playing], [data-still]) .cp-hum-ph { animation: cp-hum-sweep 7s linear infinite; }
}
@media (prefers-reduced-motion: reduce) { .cp-hum-still { display: none; } }
@keyframes cp-hum-sweep { 0% { inset-inline-start: 3.6%; opacity: 0; } 6%, 94% { opacity: .3; } 100% { inset-inline-start: 96.4%; opacity: 0; } }
.cp-hum-sounds { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 10px; margin-top: 4px; padding-inline: 3.6%; }
.cp-hum-sounds li { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.cp-hum-sounds b { font-size: clamp(16px, 4.4vw, 22px); font-weight: 800; letter-spacing: -0.02em; line-height: 1.15; color: var(--ci); }
.cp-hum-sounds span { font-size: 13px; line-height: 1.35; color: var(--color-muted); }

/* The sections. */
.cp-hum-sec { padding-top: clamp(64px, 9vw, 112px); }
.cp-hum-sec2 { padding-top: clamp(48px, 7vw, 88px); }
.cp-hum-head { display: flex; flex-wrap: wrap; align-items: baseline; justify-content: space-between; gap: 8px 16px; }
.cp-hum-count { font-size: 14px; color: var(--color-muted); }
.cp-hum-h2 { margin-top: 12px; max-width: 26ch; font-size: clamp(30px, 3.6vw, 42px); line-height: 1.1; font-weight: 800; letter-spacing: -0.025em; text-wrap: balance; }
.cp-hum-h2-l { max-width: none; font-size: clamp(38px, 5vw, 60px); line-height: 1.04; letter-spacing: -0.035em; }
.cp-hum-p { margin-top: 16px; font-size: 16px; line-height: 1.65; color: var(--color-muted); max-width: 60ch; text-wrap: pretty; }

/* The units: each card topped by its sound's shape in a wash of its colour, then what it teaches and its lessons. */
.cp-hum-units { display: grid; grid-template-columns: minmax(0, 1fr); gap: 16px; margin-top: 32px; }
.cp-hum-unit { display: flex; flex-direction: column; overflow: hidden; border-radius: 22px; background: var(--color-panel); border: 1px solid var(--color-edge); }
.cp-hum-unit-top { display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: baseline; gap: 0 12px; padding: 18px 18px 10px; background: color-mix(in srgb, var(--c) 13%, var(--color-panel)); }
.cp-hum-unit-top svg { grid-column: 1 / -1; margin-top: 6px; }
.cp-hum-unit-n { font-size: 12px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; color: var(--ci); }
.cp-hum-glyph { font-size: 26px; font-weight: 800; line-height: 1; letter-spacing: -0.02em; color: var(--ci); }
.cp-hum-unit-body { display: flex; flex: 1; flex-direction: column; gap: 12px; padding: 20px 22px 24px; }
.cp-hum-unit h3 { font-size: 21px; font-weight: 800; letter-spacing: -0.015em; }
.cp-hum-unit-say { font-size: 15px; line-height: 1.5; color: var(--color-muted); text-wrap: pretty; }
.cp-hum-lessons { display: grid; margin-top: 6px; padding-top: 8px; border-top: 1px solid var(--color-edge); }
.cp-hum-lessons li { display: flex; align-items: center; gap: 10px; min-height: 44px; font-size: 15px; line-height: 1.3; }
.cp-hum-n { flex: none; display: grid; place-items: center; width: 22px; height: 22px; border-radius: 99px; border: 1.5px solid var(--ci); color: var(--ci); font-size: 11px; font-weight: 700; }
.cp-hum-lessons a { min-width: 0; padding-block: 11px; margin-block: -11px; text-decoration: underline; text-decoration-color: color-mix(in srgb, var(--color-cream) 25%, transparent); text-underline-offset: 4px; }
.cp-hum-lessons a:hover { text-decoration-color: currentColor; }
.cp-hum-lessons .s-free { flex: none; margin: 0; white-space: nowrap; }

/* Did you know: each fact under its big word, in its sound's colour. */
.cp-hum-know { padding-top: clamp(64px, 9vw, 112px); }
.cp-hum-know::before { content: ""; display: block; margin-bottom: clamp(56px, 7vw, 72px); border-top: 1px solid var(--color-edge); }
.cp-hum-facts { display: grid; grid-template-columns: minmax(0, 1fr); gap: 32px 40px; margin-top: 32px; }
.cp-hum-facts li { display: flex; flex-direction: column; gap: 14px; }
.cp-hum-word { font-size: clamp(36px, 4vw, 44px); font-weight: 800; font-style: italic; line-height: 1.05; letter-spacing: -0.03em; color: var(--ci); }
.cp-hum-fact { font-size: 16px; line-height: 1.6; color: var(--color-muted); text-wrap: pretty; }
.cp-hum .s-cite a { padding: 0 2px; color: var(--color-cream); text-decoration: none; }

/* What the app listens for, beside the sample take: the ribbon, the line sung along it, each note on or off, the stop. */
.cp-hum-hears { display: grid; grid-template-columns: minmax(0, 1fr); gap: 40px 56px; align-items: center; }
.cp-hum-big { margin-top: 18px; font-size: 18px; line-height: 1.65; max-width: 56ch; text-wrap: pretty; }
.cp-hum-take { margin: 0; padding: clamp(18px, 2.4vw, 22px); border-radius: 24px; background: var(--color-panel); border: 1px solid var(--color-edge); }
.cp-hum-take-head { display: flex; flex-wrap: wrap; align-items: baseline; gap: 6px 10px; font-size: 13.5px; color: var(--color-muted); }
.cp-hum-take-head b { padding: 3px 10px; border-radius: 99px; background: var(--fill-2, var(--color-raised)); color: var(--color-cream); font-size: 11.5px; font-weight: 800; letter-spacing: .08em; text-transform: uppercase; white-space: nowrap; }
.cp-hum-take-art { position: relative; margin-top: 12px; }
.cp-hum-take-target { fill: none; stroke: color-mix(in srgb, var(--color-cream) 13%, transparent); stroke-width: 14; stroke-linecap: round; stroke-linejoin: round; }
.cp-hum-take-sung { fill: none; stroke: var(--color-part-3); stroke-width: 3.5; stroke-linecap: round; }
.cp-hum-take-on { fill: var(--color-part-3); }
.cp-hum-take-off { fill: var(--color-panel); stroke: var(--color-part-1); stroke-width: 2.2; }
.cp-hum-take-gap { fill: none; stroke: var(--color-part-1); stroke-width: 1.5; stroke-dasharray: 3 3; }
.cp-hum-take-stop { position: absolute; translate: -50% -100%; font-size: 13px; font-weight: 650; line-height: 1; color: var(--color-part-ink-1); }
.cp-hum-take-key { display: flex; flex-wrap: wrap; gap: 6px 18px; margin-top: 12px; font-size: 13px; color: var(--color-muted); }
.cp-hum-take-key li { display: inline-flex; align-items: center; gap: 7px; }
.cp-hum-take-key i { flex: none; width: 10px; height: 10px; border-radius: 99px; background: var(--color-part-3); }
.cp-hum-take-key li:nth-child(2) i { background: transparent; border: 2px solid var(--color-part-1); }
.cp-hum-take-key li:nth-child(3) i { width: 0; height: 14px; border-radius: 0; background: none; border-inline-start: 2px dashed var(--color-part-1); }
.cp-hum-take-foot { display: flex; flex-wrap: wrap; align-items: baseline; justify-content: space-between; gap: 6px 12px; margin-top: 14px; padding-top: 14px; border-top: 1px solid var(--color-edge); }
.cp-hum-take-foot b { font-size: 22px; font-weight: 800; letter-spacing: -0.02em; }
.cp-hum-take-foot span { font-size: 14px; color: var(--color-muted); }

/* Singing safely: the tips beside the scale, quiet to medium kept, forced never. */
.cp-hum-safe { display: grid; grid-template-columns: minmax(0, 1fr); gap: 28px 40px; align-items: center; padding: clamp(24px, 3vw, 32px); border-radius: 24px; background: color-mix(in srgb, var(--color-part-1) 8%, var(--color-ink)); }
.cp-hum-safe .s-kick { color: var(--color-part-ink-1); }
.cp-hum-tips { display: grid; gap: 12px; margin-top: 16px; }
.cp-hum-tips li { position: relative; padding-inline-start: 30px; font-size: 16px; line-height: 1.5; }
.cp-hum-tips li::before { content: ""; position: absolute; inset-inline-start: 0; top: 3px; width: 18px; height: 18px; box-sizing: border-box; border-radius: 99px; border: 2px solid var(--color-part-ink-1); }
.cp-hum-scale-bar, .cp-hum-scale-words { display: grid; grid-template-columns: minmax(0, 2.4fr) minmax(0, 1fr); gap: 6px; }
.cp-hum-scale-bar { height: 14px; }
.cp-hum-scale-bar i { border-radius: 7px; }
.cp-hum-scale-bar .cp-hum-scale-ok { background: var(--color-part-3); }
.cp-hum-scale-bar .cp-hum-scale-no { background: repeating-linear-gradient(45deg, color-mix(in srgb, var(--color-cream) 20%, transparent) 0 6px, color-mix(in srgb, var(--color-cream) 7%, transparent) 6px 12px); }
.cp-hum-scale-words { margin-top: 10px; font-size: 13.5px; line-height: 1.35; color: var(--color-muted); }
.cp-hum-scale-words .cp-hum-scale-ok { font-weight: 700; color: var(--color-part-ink-3); }

/* New to harmony: the dark band (the site's .s-ink, dark in every look), the beginner course beside Amazing Grace's four
   parts. */
.cp-hum .cp-hum-today { margin-top: clamp(72px, 9vw, 104px); padding-block: clamp(64px, 8vw, 104px); }
.cp-hum-today-in { display: grid; grid-template-columns: minmax(0, 1fr); gap: 40px 56px; align-items: center; }
.cp-hum-satb { margin: 0; padding: clamp(18px, 2.4vw, 24px); border-radius: 24px; background: color-mix(in srgb, var(--color-cream) 6%, transparent); }
.cp-hum-satb ul { display: grid; gap: 10px; }
.cp-hum-satb li { display: grid; grid-template-columns: 72px minmax(0, 1fr); align-items: center; gap: 12px; }
.cp-hum-satb span { font-size: 14px; font-weight: 600; color: var(--color-muted); }
.cp-hum-satb svg { display: block; width: 100%; height: 56px; overflow: visible; }
.cp-hum-satb path { fill: none; stroke: var(--c); stroke-width: 8; stroke-linecap: round; stroke-linejoin: round; }
.cp-hum-satb figcaption { margin-top: 16px; font-size: 13.5px; line-height: 1.45; color: var(--color-muted); }
/* The band takes the theme's dark twin (web/tool/themes.py); its primary button follows it, light on the dark. */
:root:not([data-skin="game"]) .cp-hum .s-ink .btn-primary { --primary: var(--color-cream); --primary-ink: var(--color-ink); }

/* How each sound works: four cards, each topped by its sound in its colour, its plain words, then the fact. */
.cp-hum-science { display: grid; grid-template-columns: minmax(0, 1fr); gap: 16px; margin-top: 32px; }
.cp-hum-science li { display: flex; flex-direction: column; gap: 14px; padding: 22px; border-radius: 22px; background: color-mix(in srgb, var(--c) 9%, var(--color-panel)); border: 1px solid color-mix(in srgb, var(--c) 22%, var(--color-edge)); }
.cp-hum-science-name { display: flex; align-items: baseline; gap: 10px; }
.cp-hum-science-name b { font-size: 26px; font-weight: 800; line-height: 1; letter-spacing: -0.02em; color: var(--ci); }
.cp-hum-science-name span { font-size: 13px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--ci); }
.cp-hum-science-lead { font-size: 17px; line-height: 1.5; font-weight: 600; text-wrap: pretty; }
.cp-hum-science-fact { padding-top: 14px; border-top: 1px solid color-mix(in srgb, var(--c) 25%, var(--color-edge)); font-size: 15px; line-height: 1.6; color: var(--color-muted); text-wrap: pretty; }

/* The dated story: the years down one ribbon, each stop a dot in its sound's colour. */
.cp-hum-story { display: grid; grid-template-columns: minmax(0, 1fr); gap: 32px 56px; align-items: start; }
.cp-hum-years { position: relative; display: grid; gap: 28px; padding-inline-start: 34px; }
.cp-hum-years::before { content: ""; position: absolute; inset-block: 10px; inset-inline-start: 8px; width: 3px; border-radius: 2px; background: linear-gradient(to bottom, var(--color-part-2), var(--color-part-3), var(--color-part-1), var(--color-part-4), var(--color-part-1)); }
.cp-hum-years li { position: relative; }
.cp-hum-years li::before { content: ""; position: absolute; top: 8px; inset-inline-start: -33px; width: 17px; height: 17px; box-sizing: border-box; border-radius: 99px; border: 3px solid var(--c); background: var(--color-ink); }
.cp-hum-year { font-size: clamp(30px, 3.4vw, 40px); font-weight: 800; line-height: 1; letter-spacing: -0.03em; font-variant-numeric: tabular-nums; color: var(--ci); }
.cp-hum-year-text { margin-top: 8px; font-size: 16px; line-height: 1.6; color: var(--color-muted); max-width: 62ch; text-wrap: pretty; }

/* Try it now: the first lesson on a card, its roller coaster across the top, its steps numbered under it. */
.cp-hum-try { padding: clamp(24px, 3.4vw, 44px); border-radius: 28px; background: color-mix(in srgb, var(--c) 8%, var(--color-panel)); border: 1px solid var(--color-edge); }
.cp-hum-try .s-kick { color: var(--ci); }
.cp-hum-try-art { margin: 24px 0 0; }
.cp-hum-try-art svg { display: block; width: 100%; height: auto; overflow: visible; }
.cp-hum-try .cp-hum-shape-dots { fill: var(--color-panel); }
.cp-hum-try-steps { display: grid; grid-template-columns: minmax(0, 1fr); gap: 18px 40px; margin-top: 28px; }
.cp-hum-try-steps li { display: grid; grid-template-columns: auto minmax(0, 1fr); gap: 14px; align-items: start; }
.cp-hum-try-steps .cp-hum-n { width: 30px; height: 30px; font-size: 14px; border-width: 2px; }
.cp-hum-try-steps p { font-size: 16.5px; line-height: 1.55; text-wrap: pretty; }
.cp-hum-try-steps p span { color: var(--color-muted); }
.cp-hum-try-steps b { display: block; font-size: 17px; }

/* Who it's for: three lines, each marked with a short ribbon in a sound's colour. */
.cp-hum-who { display: grid; grid-template-columns: minmax(0, 1fr); gap: 18px 32px; margin-top: 20px; }
.cp-hum-who li { display: grid; grid-template-columns: 28px minmax(0, 1fr); gap: 14px; align-items: start; }
.cp-hum-who-mark { height: 6px; margin-top: 11px; border-radius: 3px; background: var(--c); }
.cp-hum-who p { font-size: 17px; line-height: 1.55; text-wrap: pretty; }

/* The close: the four sounds over the call, centred. */
.cp-hum-close { display: grid; justify-items: center; text-align: center; padding: clamp(36px, 5vw, 64px) clamp(20px, 4vw, 48px); border-radius: 28px; background: var(--color-panel); border: 1px solid var(--color-edge); }
.cp-hum-close-sounds { display: flex; flex-wrap: wrap; justify-content: center; gap: 6px 18px; font-size: clamp(22px, 3vw, 30px); font-weight: 800; letter-spacing: -0.02em; }
.cp-hum-close-sounds b { color: var(--ci); }
.cp-hum-close .cp-hum-h2 { margin-inline: auto; }
.cp-hum-close .cp-hum-p { margin-inline: auto; }
.cp-hum-close-note { margin-top: 8px; font-size: 14px; color: var(--color-muted); }
.cp-hum-close .cp-hum-btns { justify-content: center; }

/* Every lesson's page, by unit: four columns, each headed in its unit's colour. */
.cp-hum-reads { display: grid; grid-template-columns: minmax(0, 1fr); gap: 32px 24px; margin-top: 28px; }
.cp-hum-reads h3 { display: flex; flex-wrap: wrap; align-items: baseline; gap: 4px 10px; padding-bottom: 12px; border-bottom: 2px solid var(--c); font-size: 15px; font-weight: 700; }
.cp-hum-reads-glyph { font-weight: 800; color: var(--ci); }
.cp-hum-reads a { display: flex; flex-direction: column; gap: 3px; padding-block: 14px; border-bottom: 1px solid var(--color-edge); }
.cp-hum-reads b { font-size: 16px; font-weight: 700; }
.cp-hum-reads a span { font-size: 14px; line-height: 1.4; color: var(--color-muted); }
.cp-hum-reads a:hover b { text-decoration: underline; text-underline-offset: 3px; }
.cp-hum-sources { padding-top: 48px; }
.cp-hum-sources ol { display: grid; gap: 8px; margin-top: 14px; padding-inline-start: 1.4em; list-style: decimal; font-size: 14px; line-height: 1.5; color: var(--color-muted); }
.cp-hum-sources a { text-decoration: underline; text-underline-offset: 3px; overflow-wrap: anywhere; }

/* Four units or four columns of lessons: one, two, then all four across, never three and one alone. */
@media (min-width: 600px) {
    .cp-hum-units, .cp-hum-reads, .cp-hum-science, .cp-hum-try-steps { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (min-width: 1100px) {
    .cp-hum-units, .cp-hum-reads, .cp-hum-science { grid-template-columns: repeat(4, minmax(0, 1fr)); }
}
@media (min-width: 900px) {
    .cp-hum-facts { grid-template-columns: repeat(3, minmax(0, 1fr)); }
    .cp-hum-hero { padding-top: 32px; }
    .cp-hum-hero h1 { font-size: clamp(48px, 5.4vw, 68px); }
    .cp-hum-sounds b { font-size: clamp(16px, 1.6vw, 22px); }
    .cp-hum-top { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 56px; }
    .cp-hum-hears, .cp-hum-today-in { grid-template-columns: repeat(2, minmax(0, 1fr)); }
    .cp-hum-safe { grid-template-columns: repeat(2, minmax(0, 1fr)); }
    .cp-hum-story { grid-template-columns: minmax(0, 2fr) minmax(0, 3fr); }
    .cp-hum-story > div { position: sticky; top: 96px; }
    .cp-hum-who { grid-template-columns: repeat(3, minmax(0, 1fr)); }
}

/* The game skin: the arcade's display and HUD type, square cards, scale and pills (the shared course rule squares the
   rest), the panels framed like the stage card. */
:root[data-skin="game"] body.s-arcade .cp-hum-hero h1 { font-family: var(--a-display); font-weight: 400; text-transform: uppercase; letter-spacing: .01em; line-height: 1.04; font-size: clamp(34px, 7vw, 58px); font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade :is(.cp-hum-h2, .cp-hum-take-foot b) { font-family: var(--arc-pixel); font-weight: 400; letter-spacing: 0; font-size-adjust: .58; --arc-ex: .58; line-height: 1.3; text-shadow: .06em .06em 0 var(--arc-shade); }
:root[data-skin="game"] body.s-arcade .cp-hum-h2 { font-size: clamp(22px, 3vw, 32px); }
:root[data-skin="game"] body.s-arcade .cp-hum-take-foot b { font-size: 16px; }
:root[data-skin="game"] body.s-arcade :is(.cp-hum-glyph, .cp-hum-sounds b, .cp-hum-word, .cp-hum-reads-glyph, .cp-hum-science-name b, .cp-hum-year, .cp-hum-close-sounds) { font-family: var(--a-display); font-weight: 400; font-style: normal; letter-spacing: 0; font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade :is(.cp-hum-count, .cp-hum-take-head b, .cp-hum-open, .cp-hum-unit-n) { font-family: var(--a-hud); font-weight: 400; font-size: 11px; font-size-adjust: var(--arc-ex, none); letter-spacing: .06em; }
:root[data-skin="game"] body.s-arcade :is(.cp-hum-ribbon, .cp-hum-unit, .cp-hum-take, .cp-hum-science li, .cp-hum-try, .cp-hum-close) { border-radius: 0; border: var(--arc-edge-w, 2px) solid var(--arc-line); box-shadow: var(--arc-shadow); }
:root[data-skin="game"] body.s-arcade :is(.cp-hum-safe, .cp-hum-satb, .cp-hum-take-head b, .cp-hum-open, .cp-hum-play, .cp-hum-scale-bar i, .cp-hum-who-mark, .cp-hum-years::before) { border-radius: 0; }
:root[data-skin="game"] body.s-arcade .cp-hum-years li::before { border-radius: 0; }

/* Live looping (site/courses/live-looping): Hillel's design (2026-11-18, ~/Code/course-designs/live-looping), a song
   built from tracks on repeat, one colour per track. The design's rust, ochre, teal and deep teal are the site's parts 1
   to 4 (s-v1 to s-v4: --c, --ci, --ct; the warm light theme's are those very colours), so calm light and dark and game
   all draw them. Its JetBrains Mono is the system's monospace. The hero's loop rings with a playhead (still under
   reduced motion) and the play bubble at their centre; what you'll learn under a bar a track; the units as a track
   arrangement of lesson blocks; a sample take on a dark card; singing safely beside the numbered songs; the beginner
   course on the dark band; every lesson's page by unit. In calm light, the take card and the band are dark: .cp-ll-dark
   turns the theme's own ink and words round (its parts lightened, its button light), so any light theme gets them. */
.cp-ll {
    --ll-mono: ui-monospace, SFMono-Regular, Menlo, Consolas, "Liberation Mono", monospace;
    --ll-gut: 16px;
    --ll-dark: var(--color-cream); --ll-light: var(--color-ink);
    --ll-p1: var(--color-part-1); --ll-p2: var(--color-part-2); --ll-p3: var(--color-part-3); --ll-p4: var(--color-part-4);
}
:root[data-theme$="-light"]:not([data-skin="game"]) .cp-ll-dark {
    --color-cream: var(--ll-light); --color-ink: var(--ll-dark); --color-panel: var(--ll-dark); --s-ink-bg: var(--ll-dark);
    --color-raised: color-mix(in srgb, var(--ll-light) 10%, var(--ll-dark));
    --color-muted: color-mix(in srgb, var(--ll-light) 76%, var(--ll-dark));
    --color-edge: color-mix(in srgb, var(--ll-light) 18%, var(--ll-dark)); --color-line: color-mix(in srgb, var(--ll-light) 18%, var(--ll-dark));
    --fill-2: color-mix(in srgb, var(--ll-light) 12%, transparent);
    --primary: var(--ll-light); --primary-ink: var(--ll-dark); --primary-hover-to: var(--ll-dark);
    --color-part-1: color-mix(in oklab, var(--ll-p1) 58%, white); --color-part-2: color-mix(in oklab, var(--ll-p2) 58%, white);
    --color-part-3: color-mix(in oklab, var(--ll-p3) 58%, white); --color-part-4: color-mix(in oklab, var(--ll-p4) 52%, white);
    --color-part-ink-1: var(--color-part-1); --color-part-ink-2: var(--color-part-2); --color-part-ink-3: var(--color-part-3); --color-part-ink-4: var(--color-part-4);
    color-scheme: dark;
}
.cp-ll-mono { font-family: var(--ll-mono); font-size: 12px; font-weight: 500; letter-spacing: .05em; text-transform: uppercase; color: var(--color-muted); }
.cp-ll-kick { font-family: var(--ll-mono); font-size: 12px; font-weight: 600; letter-spacing: .08em; text-transform: uppercase; color: var(--color-part-ink-2); }
.cp-ll-h2 { margin-top: 12px; font-size: clamp(30px, 4vw, 44px); line-height: 1.05; font-weight: 800; letter-spacing: -0.03em; text-wrap: balance; }
.cp-ll-h2-l { font-size: clamp(38px, 5vw, 60px); line-height: 1; letter-spacing: -0.035em; }
.cp-ll-p { margin-top: 16px; font-size: 17px; line-height: 1.6; color: var(--color-muted); max-width: 56ch; text-wrap: pretty; }
.cp-ll-sec { position: relative; padding-block: clamp(44px, 6vw, 56px); }
.cp-ll-ruled::before { content: ""; position: absolute; inset-block-start: 0; inset-inline: var(--ll-gut); height: 1px; background: var(--color-edge); }
.cp-ll ~ [data-lesson-pages] { display: none; }

/* The hero: the words at left, the loop at right (stacked on a phone). */
.cp-ll-hero { display: grid; grid-template-columns: minmax(0, 1fr); gap: 40px; align-items: center; padding-block: 20px 56px; }
.cp-ll-copy { display: flex; flex-direction: column; gap: 22px; min-width: 0; }
.cp-ll-copy .s-crumb { margin: 0; }
.cp-ll-meta { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 12px; }
.cp-ll-open { display: inline-flex; align-items: center; gap: 7px; padding: 5px 12px; border-radius: 99px; background: color-mix(in srgb, var(--color-good) 16%, var(--color-ink)); color: var(--color-cream); font-size: 13.5px; font-weight: 700; white-space: nowrap; }
.cp-ll-open-dot { flex: none; width: 8px; height: 8px; border-radius: 99px; background: var(--color-good); }
.cp-ll-hero h1 { font-size: clamp(42px, 10vw, 72px); line-height: .98; font-weight: 800; letter-spacing: -0.035em; text-wrap: balance; }
.cp-ll-word { color: var(--ci); }
.cp-ll-lead { font-size: clamp(17px, 1.7vw, 20px); line-height: 1.55; color: var(--color-muted); max-width: 30em; text-wrap: pretty; }
.cp-ll-btns { display: flex; flex-wrap: wrap; align-items: center; gap: 12px; }
.cp-ll-btns > a { white-space: nowrap; }
.cp-ll-free { font-size: 14px; color: var(--color-muted); }
@media (max-width: 639px) {
    .cp-ll-btns { flex-direction: column; align-items: stretch; }
    .cp-ll-btns > a { justify-content: center; width: 100%; }
    .cp-ll-free { text-align: center; }
}

/* The loop: a ring a track, outside in, each note an arc round it; the playhead turns at the song's speed. */
.cp-ll-loop { display: flex; flex-direction: column; align-items: center; gap: 20px; margin: 0; }
.cp-ll-rings { position: relative; width: 100%; max-width: 440px; aspect-ratio: 1; }
.cp-ll-svg { display: block; width: 100%; height: 100%; transform: rotate(-90deg); overflow: visible; }
.cp-ll-track, .cp-ll-arc { fill: none; stroke-width: 24; }
.cp-ll-track { stroke: color-mix(in srgb, var(--c) 14%, transparent); }
.cp-ll-arc { stroke: var(--c); transition: opacity .08s; }
.cp-ll-loop[data-playing] .cp-ll-arc { opacity: .2; }
.cp-ll-loop[data-playing] .cp-ll-ring[data-in] .cp-ll-arc { opacity: .48; }
.cp-ll-loop[data-playing] .cp-ll-ring[data-in] .cp-ll-arc[data-on] { opacity: 1; }
.cp-ll-ph { position: absolute; inset: 0; pointer-events: none; transform: rotate(calc(var(--p, .078) * 1turn)); }
.cp-ll-ph i { position: absolute; inset-inline-start: calc(50% - 1.5px); inset-block-start: -2%; width: 3px; height: 52%; border-radius: 2px; background: var(--color-cream); }
.cp-ll-ph i::before { content: ""; position: absolute; inset-block-start: -5px; inset-inline-start: -4.5px; width: 12px; height: 12px; border-radius: 99px; background: var(--color-cream); }
@media (prefers-reduced-motion: no-preference) {
    .cp-ll-loop:not([data-playing]) .cp-ll-ph { animation: cp-ll-turn var(--ll-turn, 20s) linear infinite; }
    .cp-ll-open-dot { animation: cp-ll-pulse 2s ease-in-out infinite; }
}
@keyframes cp-ll-turn { from { transform: rotate(0turn); } to { transform: rotate(1turn); } }
@keyframes cp-ll-pulse { 50% { opacity: .35; } }
.cp-ll-play { --bubble: var(--primary); --bubble-ink: var(--primary-ink); position: absolute; inset-block-start: 50%; inset-inline-start: 50%; z-index: 1; display: grid; place-items: center; width: 21%; min-width: 56px; aspect-ratio: 1; transform: translate(-50%, -50%); }
[dir="rtl"] .cp-ll-play { transform: translate(50%, -50%); }
.cp-ll-play:focus-visible { outline: 3px solid var(--color-cream); outline-offset: 4px; }
.cp-ll-play-icon { width: 34%; aspect-ratio: 1; background: currentColor; clip-path: polygon(22% 8%, 92% 50%, 22% 92%); }
.cp-ll-play[aria-pressed="true"] .cp-ll-play-icon { width: 28%; clip-path: inset(0 round 3px); }
.cp-ll-legend { display: flex; flex-wrap: wrap; justify-content: center; align-items: center; gap: 8px 20px; font-size: 14px; font-weight: 650; }
.cp-ll-legend li { display: flex; align-items: center; gap: 7px; white-space: nowrap; }
.cp-ll-swatch { flex: none; width: 12px; height: 12px; border-radius: 3px; background: var(--c); }
.cp-ll-source { max-width: 54ch; font-size: 13.5px; line-height: 1.5; color: var(--color-muted); text-align: center; text-wrap: pretty; }

/* What you'll learn: a bar a track. */
.cp-ll-learn { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 230px), 1fr)); gap: 28px 20px; margin-top: 28px; }
.cp-ll-learn li { display: flex; flex-direction: column; gap: 12px; }
.cp-ll-bar { height: 8px; border-radius: 4px; background: var(--c); }
.cp-ll-learn h3 { font-size: 18px; font-weight: 700; }
.cp-ll-learn p { font-size: 16px; line-height: 1.5; color: var(--color-muted); }

/* The units as a track arrangement: a lane a unit, a block a lesson, "Your song" spanning the end in every colour. */
.cp-ll-units-head { display: flex; flex-wrap: wrap; align-items: end; justify-content: space-between; gap: 12px 16px; }
.cp-ll-arrange { container: ll-arrange / inline-size; display: grid; gap: 22px; margin-top: 28px; padding: clamp(16px, 2.2vw, 24px); border-radius: 20px; background: var(--color-panel); border: 1px solid var(--color-edge); }
.cp-ll-unit h3 { display: flex; flex-wrap: wrap; align-items: baseline; gap: 4px 12px; font-size: 18px; font-weight: 700; }
.cp-ll-track-n { font-family: var(--ll-mono); font-size: 12px; font-weight: 600; letter-spacing: .05em; text-transform: uppercase; color: var(--ci); }
.cp-ll-blocks { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 150px), 1fr)); gap: 6px; margin-top: 10px; }
.cp-ll-block { display: flex; flex-direction: column; justify-content: space-between; gap: 6px; height: 100%; min-height: 60px; padding: 10px 12px; border-radius: 8px; background: var(--c); color: var(--ct); font-size: 15px; font-weight: 650; line-height: 1.25; }
.cp-ll-block-n { font-family: var(--ll-mono); font-size: 11px; font-weight: 600; letter-spacing: .06em; text-transform: uppercase; }
a.cp-ll-block:hover .cp-ll-block-t { text-decoration: underline; text-underline-offset: 3px; }
a.cp-ll-block:focus-visible { outline: 3px solid var(--color-cream); outline-offset: 2px; }
.cp-ll-first .cp-ll-block { box-shadow: 0 0 0 3px var(--color-panel), 0 0 0 5px var(--c); }
.cp-ll-all .cp-ll-block { background: linear-gradient(90deg, var(--color-part-1) 0 25%, var(--color-part-2) 25% 50%, var(--color-part-3) 50% 75%, var(--color-part-4) 75%) bottom / 100% 5px no-repeat, var(--color-cream); color: var(--color-ink); padding-bottom: 15px; }
@container ll-arrange (min-width: 306px) { .cp-ll-all { grid-column: span 2; } }

/* What the app listens for, beside the sample take. */
.cp-ll-hears { display: grid; grid-template-columns: minmax(0, 1fr); gap: 36px 48px; align-items: center; }
.cp-ll-take { padding: clamp(20px, 2.6vw, 28px); border-radius: 20px; background: var(--color-panel); border: 1px solid var(--color-edge); color: var(--color-cream); }
.cp-ll-sample { display: flex; flex-wrap: wrap; align-items: baseline; gap: 6px 10px; font-size: 13.5px; line-height: 1.45; color: var(--color-muted); }
.cp-ll-sample b { padding: 3px 10px; border-radius: 99px; background: var(--fill-2, var(--color-raised)); color: var(--color-cream); font-family: var(--ll-mono); font-size: 11.5px; font-weight: 600; letter-spacing: .06em; text-transform: uppercase; white-space: nowrap; }
.cp-ll-dots { display: grid; grid-template-columns: repeat(12, minmax(0, 1fr)); gap: clamp(4px, 1vw, 8px); margin-top: 22px; }
.cp-ll-dots li { aspect-ratio: 1; border-radius: 99px; background: var(--c); border: 2px solid var(--c); }
.cp-ll-dots .cp-ll-miss { background: transparent; border-color: var(--color-muted); }
.cp-ll-stat { margin-top: 22px; font-size: clamp(24px, 3vw, 30px); font-weight: 800; line-height: 1.1; letter-spacing: -0.02em; }
.cp-ll-stat2 { margin-top: 6px; font-size: 18px; color: var(--color-muted); }

/* Singing safely beside the songs, each numbered. */
.cp-ll-notes { display: grid; grid-template-columns: minmax(0, 1fr); gap: 40px 48px; }
.cp-ll-n { flex: none; font-family: var(--ll-mono); font-size: 12px; font-weight: 600; color: var(--color-part-ink-1); }
.cp-ll-safe { display: grid; gap: 12px; margin-top: 18px; font-size: 16px; line-height: 1.5; }
.cp-ll-safe li { display: flex; align-items: baseline; gap: 12px; }
.cp-ll-songs { margin-top: 10px; font-size: 16px; }
.cp-ll-songs li { display: grid; grid-template-columns: 28px minmax(0, 1fr); gap: 2px 12px; align-items: baseline; padding-block: 11px; border-bottom: 1px solid var(--color-edge); }
.cp-ll-songs li:last-child { border-bottom: 0; }
.cp-ll-songs .cp-ll-n { color: var(--color-muted); }
.cp-ll-songs b { font-weight: 700; }
.cp-ll-credit { grid-column: 2; font-size: 14px; line-height: 1.45; color: var(--color-muted); }

/* The beginner course on the dark band, beside its map in the app. */
.cp-ll > .cp-ll-today { margin-top: 0; padding-block: clamp(56px, 8vw, 96px); }
.cp-ll-today-in { display: grid; grid-template-columns: minmax(0, 1fr); gap: 40px 56px; align-items: center; }
.cp-ll-today .cp-ll-p { color: var(--color-muted); max-width: 46ch; }
.cp-ll-today .cp-ll-btns { margin-top: 26px; }
.cp-ll-shot .s-appshot img { border-radius: 20px; }

/* Every lesson's page, by unit. */
.cp-ll-chips { margin-top: 18px; }
.cp-ll-every-grid { display: grid; grid-template-columns: minmax(0, 1fr); gap: 36px 48px; margin-top: 28px; }
.cp-ll-every h3 { display: flex; align-items: center; gap: 10px; padding-bottom: 10px; font-size: 16px; font-weight: 700; }
.cp-ll-every .cp-ll-swatch { width: 10px; height: 10px; border-radius: 2px; }
.cp-ll-every ul a { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 4px 16px; align-items: center; padding-block: 12px; border-top: 1px solid var(--color-edge); }
.cp-ll-every ul b { font-weight: 650; }
.cp-ll-every ul span { grid-column: 1; font-size: 14px; line-height: 1.4; color: var(--color-muted); }
.cp-ll-every ul svg { grid-column: 2; grid-row: 1 / 3; color: var(--color-muted); }
[dir="rtl"] .cp-ll-every ul svg { transform: scaleX(-1); }
.cp-ll-every ul a:hover b { text-decoration: underline; text-underline-offset: 3px; }

@media (min-width: 760px) {
    .cp-ll-every-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
    .cp-ll-songs li { grid-template-columns: 28px minmax(0, 1fr) auto; }
    .cp-ll-credit { grid-column: 3; text-align: end; max-width: 30ch; }
}
@media (min-width: 900px) {
    .cp-ll { --ll-gut: 40px; }
    .cp-ll-hero { grid-template-columns: minmax(0, 1.05fr) minmax(0, .95fr); gap: 48px; padding-block: 40px 72px; }
    .cp-ll-hears, .cp-ll-notes, .cp-ll-today-in { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}

/* The game skin: pixel headings and HUD labels, square blocks, bars and swatches, framed panels, and the play disc the
   arcade's own (flat, its yellow). */
:root[data-skin="game"] body.s-arcade .cp-ll-h2 { font-family: var(--arc-pixel); font-weight: 400; letter-spacing: 0; font-size-adjust: .58; --arc-ex: .58; line-height: 1.25; font-size: clamp(22px, 3vw, 34px); text-shadow: .06em .06em 0 var(--arc-shade); }
:root[data-skin="game"] body.s-arcade :is(.cp-ll-mono, .cp-ll-kick, .cp-ll-track-n, .cp-ll-block-n, .cp-ll-sample b, .cp-ll-open, .cp-ll-n) { font-family: var(--a-hud); font-weight: 400; font-size: 11px; font-size-adjust: var(--arc-ex, none); letter-spacing: .06em; }
:root[data-skin="game"] body.s-arcade :is(.cp-ll-arrange, .cp-ll-take) { border: var(--arc-edge-w, 2px) solid var(--arc-line); border-radius: 0; box-shadow: var(--arc-shadow); }
:root[data-skin="game"] body.s-arcade :is(.cp-ll-block, .cp-ll-bar, .cp-ll-swatch, .cp-ll-sample b, .cp-ll-open) { border-radius: 0; }
:root[data-skin="game"] body.s-arcade .cp-ll-first .cp-ll-block { box-shadow: 0 0 0 3px var(--color-panel), 0 0 0 5px var(--a-yellow); }
:root[data-skin="game"] body.s-arcade .cp-ll-play { --bubble: var(--a-yellow); --bubble-ink: var(--a-yellow-ink); background: var(--a-yellow); color: var(--a-yellow-ink); border: 0; box-shadow: 4px 4px 0 var(--arc-shade, #000); }
:root[data-skin="game"] body.s-arcade .cp-ll-play::before { display: none; }
:root[data-skin="game"] body.s-arcade .cp-ll-ph i, :root[data-skin="game"] body.s-arcade .cp-ll-ph i::before { background: var(--a-yellow); }
:root[data-skin="game"] body.s-arcade .cp-ll-arc { filter: drop-shadow(0 0 4px color-mix(in srgb, var(--c) 60%, transparent)); }

/* The length pass (2026-11-19): the science and the story from the course's facts, the first lesson to try, who it's
   for, Questions, a close and the Sources, in the page's own language (mono labels, a colour a track). */
.cp-ll-card { padding: clamp(20px, 2.6vw, 28px); border-radius: 20px; background: var(--color-panel); border: 1px solid var(--color-edge); }
.cp-ll-card .cp-ll-p:first-child { margin-top: 0; }
.cp-ll-card-h { font-size: 18px; font-weight: 700; }
.cp-ll-small { margin-top: 12px; font-size: 14px; line-height: 1.5; color: var(--color-muted); }
.cp-ll-science { display: grid; grid-template-columns: minmax(0, 1fr); gap: 20px; margin-top: 28px; }
.cp-ll-ms { display: grid; gap: 18px; margin-bottom: 20px; }
.cp-ll-ms li { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 8px 16px; align-items: baseline; }
.cp-ll-ms span { font-size: 15px; color: var(--color-muted); }
.cp-ll-ms b { font-size: clamp(24px, 3vw, 32px); font-weight: 800; letter-spacing: -0.02em; color: var(--ci); font-variant-numeric: tabular-nums; white-space: nowrap; }
.cp-ll-ms i { grid-column: 1 / -1; height: 14px; border-radius: 4px; background: color-mix(in srgb, var(--c) 16%, transparent); }
/* Each bar to scale on one 160 ms axis: reacting fills it, an ensemble's 30 to 50 ms is the band from 19% to 31%. */
.cp-ll-ms-react i { background: var(--c); }
.cp-ll-ms-together i { background: linear-gradient(90deg, var(--c) 0 19%, color-mix(in srgb, var(--c) 45%, transparent) 19% 31%, color-mix(in srgb, var(--c) 16%, transparent) 31%); }
.cp-ll-chords { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 6px; margin-block: 16px 20px; }
.cp-ll-chords li { display: flex; flex-direction: column; justify-content: space-between; gap: 6px; min-height: 76px; padding: 10px 12px; border-radius: 8px; background: var(--c); color: var(--ct); }
.cp-ll-chords b { font-size: 26px; font-weight: 800; }
.cp-ll-chords span { font-family: var(--ll-mono); font-size: 12px; font-weight: 600; letter-spacing: .06em; text-transform: uppercase; }
.cp-ll-story { display: grid; grid-template-columns: minmax(0, 1fr); gap: 36px 48px; margin-top: 32px; }
.cp-ll-story-h { padding-bottom: 12px; border-bottom: 1px solid var(--color-cream); }
.cp-ll-years li { display: grid; grid-template-columns: 112px minmax(0, 1fr); gap: 6px 20px; padding-block: 18px; border-bottom: 1px solid var(--color-edge); }
.cp-ll-year { font-family: var(--ll-mono); font-size: 13px; font-weight: 600; letter-spacing: .04em; color: var(--ci); padding-top: 3px; }
.cp-ll-years h4 { font-size: 17px; font-weight: 700; }
.cp-ll-years p:not(.cp-ll-year) { margin-top: 6px; font-size: 15.5px; line-height: 1.55; color: var(--color-muted); }
.cp-ll .s-cite a { color: var(--color-part-ink-1); text-decoration: none; padding: 6px 3px; }
.cp-ll-try { display: grid; grid-template-columns: minmax(0, 1fr); gap: 32px 48px; align-items: start; }
.cp-ll-before { margin-top: 24px; }
.cp-ll-cards { display: grid; gap: 12px; margin-top: 12px; }
.cp-ll-cards li, .cp-ll-ticks li { display: flex; gap: 12px; align-items: baseline; font-size: 16px; line-height: 1.5; }
.cp-ll-cards p { color: var(--color-muted); }
.cp-ll-cards b { display: block; color: var(--color-cream); }
.cp-ll-steps { display: grid; gap: 18px; margin-bottom: 22px; }
.cp-ll-steps li { display: flex; gap: 14px; align-items: baseline; font-size: 16.5px; line-height: 1.55; }
.cp-ll-who { display: grid; grid-template-columns: minmax(0, 1fr); gap: 36px 48px; }
.cp-ll-ticks { display: grid; gap: 14px; margin-top: 18px; }
.cp-ll-ticks .cp-ll-swatch, .cp-ll-cards .cp-ll-swatch { transform: translateY(1px); }
.cp-ll-faq .cp-faq { margin-top: 24px; }
.cp-ll-close { display: grid; justify-items: center; text-align: center; padding-block: clamp(56px, 8vw, 96px); }
.cp-ll-close .cp-ll-p { margin-inline: auto; }
.cp-ll-close .cp-ll-btns { justify-content: center; margin-top: 28px; }
.cp-ll-sources { column-gap: 48px; margin-top: 20px; font-size: 14.5px; line-height: 1.5; }
.cp-ll-sources li { display: flex; gap: 12px; align-items: baseline; padding-block: 5px; break-inside: avoid; }
.cp-ll-sources a { color: var(--color-muted); text-decoration: underline; text-decoration-color: color-mix(in srgb, var(--color-cream) 30%, transparent); text-underline-offset: 3px; overflow-wrap: anywhere; }
.cp-ll-sources a:hover { color: var(--color-cream); }
@media (max-width: 559px) { .cp-ll-years li { grid-template-columns: minmax(0, 1fr); } }
@media (min-width: 760px) { .cp-ll-sources { columns: 2; } }
@media (min-width: 900px) {
    .cp-ll-science, .cp-ll-story, .cp-ll-try, .cp-ll-who { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
:root[data-skin="game"] body.s-arcade :is(.cp-ll-year, .cp-ll-chords span) { font-family: var(--a-hud); font-weight: 400; font-size: 11px; font-size-adjust: var(--arc-ex, none); letter-spacing: .06em; }
:root[data-skin="game"] body.s-arcade .cp-ll-card { border: var(--arc-edge-w, 2px) solid var(--arc-line); border-radius: 0; box-shadow: var(--arc-shadow); }
:root[data-skin="game"] body.s-arcade :is(.cp-ll-chords li, .cp-ll-ms i) { border-radius: 0; }
:root[data-skin="game"] body.s-arcade .cp-ll-chords b { font-family: var(--arc-pixel); font-weight: 400; font-size: 20px; font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade .cp-ll-close .cp-ll-h2-l { font-size: clamp(24px, 3.6vw, 40px); }


/* Blues singing (site/courses/blues-singing): Hillel's design of 2026-11-18, 1920s Chicago sheet music. Ink on paper with
   a sheet-music navy for the answer line and the blue note, a gold for the labels, and the system serif for display (no
   new fonts). The hero's words beside our own sheet-music panel for Shorty George Blues (a paper behind it, tilted); what
   you'll learn as the song's twelve bars on a paper band (your line filled, the band's turn left open, the B line in
   navy); the history beside its dates on a line, then its last sentence set large; the units as cards with big numerals
   (unit 2 the navy one); what the app hears beside a sample take on the band; safety beside the songs with their years.
   Calm light and dark; game skin: the arcade's night, square frames with hard shadows, the HUD's labels. */
.cp-bl { --bl-serif: ui-serif, "Iowan Old Style", "Palatino Linotype", Palatino, Georgia, serif;
    --bl-band: #efe7d9; --bl-rule: #d9ccb6; --bl-card: #fff; --bl-body: #3d352f; --bl-muted: #5a5048; --bl-gold: #7c5f07;
    --bl-blue: #2d3a86; --bl-blue-text: #2d3a86; --bl-blue-ink: #f3ead8; --bl-fill: #1c1612; --bl-fill-ink: #f3ead8; --bl-paper: #e9dfcb;
    --bl-navy: #26306f; --bl-navy-ink: #f3ead8; --bl-navy-gold: #d8c48f; --bl-start: #2b6a33; --bl-start-ink: #fff;
    --cp-a: var(--bl-blue); --cp-a-ink: #fff; --cp-a-text: var(--bl-gold); }
:root:not([data-theme$="-light"]) .cp-bl { --bl-band: #211b15; --bl-rule: #3d342a; --bl-card: #1d1813; --bl-body: #ddd4c8; --bl-muted: #bcb1a3; --bl-gold: #e6c162;
    --bl-blue: #3e4fae; --bl-blue-text: #aeb9ff; --bl-blue-ink: #f6f0e6; --bl-fill: #efe6d7; --bl-fill-ink: #1c1612; --bl-paper: #3a3126;
    --bl-start: #8fd19a; --bl-start-ink: #10240f; --cp-a-text: var(--bl-gold); }
:root[data-skin="game"]:not([data-theme$="-light"]) .cp-bl { --bl-band: var(--a-bg-2, #0c0a17); --bl-rule: var(--a-line-2, #3a3555); --bl-card: var(--a-panel); --bl-body: var(--a-ink); --bl-muted: var(--a-muted); --bl-gold: #ffd84a;
    --bl-blue: #3be7ff; --bl-blue-text: #3be7ff; --bl-blue-ink: #04161b; --bl-fill: #ffd84a; --bl-fill-ink: #1a1400; --bl-paper: #ff5fd2;
    --bl-navy: #12101e; --bl-navy-ink: #f7f4ff; --bl-navy-gold: #ffd84a; --bl-start: #a3e635; --bl-start-ink: #102000; }
.cp-bl em { font-family: var(--bl-serif); font-style: italic; font-weight: 400; color: var(--bl-blue-text); letter-spacing: -0.01em; }

/* Type: the gold tracked labels and the serif headings; the game skin's HUD and marquee faces. */
.cp-bl-kick { font-size: 12.5px; font-weight: 700; letter-spacing: .16em; text-transform: uppercase; color: var(--bl-gold); }
