/* Lesson 1: its steps as four bars in a row, the last (you sing) the navy one, then what's kept and the start. */
.cp-bl-first { padding-block: 0 clamp(64px, 9vw, 104px); }
.cp-bl-steps { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 230px), 1fr)); gap: 10px; }
.cp-bl-step { --s-bg: var(--bl-fill); --s-ink: var(--bl-fill-ink); display: flex; flex-direction: column; gap: 12px; padding: 18px 18px 20px; border-radius: 4px; background: var(--s-bg); color: var(--s-ink); }
.cp-bl-step-last { --s-bg: var(--bl-blue); --s-ink: var(--bl-blue-ink); }
.cp-bl-step-top { display: flex; align-items: baseline; gap: 12px; }
.cp-bl-step-n { font-family: var(--bl-serif); font-size: 34px; font-weight: 600; line-height: 1; }
.cp-bl-step-kind { font-size: 12px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; }
.cp-bl-step-text { font-size: 15.5px; line-height: 1.55; text-wrap: pretty; }
.cp-bl-step-score { margin-top: auto; padding-top: 10px; border-top: 1px solid color-mix(in srgb, var(--s-ink) 30%, transparent); font-size: 13.5px; line-height: 1.45; }
.cp-bl-first-foot { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 16px 32px; margin-top: 24px; }
.cp-bl-kept { max-width: 40em; font-size: 15.5px; line-height: 1.6; color: var(--bl-body); }
.cp-bl-first-foot .btn-secondary { white-space: nowrap; }

/* Before you begin: who and what you need above safety and the songs. */
.cp-bl-two-h { grid-column: 1 / -1; margin-bottom: -24px; }
@media (min-width: 900px) { .cp-bl-two { row-gap: 40px; } .cp-bl-two-h { margin-bottom: -16px; } }
.cp-bl-ticks svg { color: var(--bl-blue-text); }
.cp-bl-two h3.cp-bl-safe-h { margin-top: 0; }

/* The questions beside their heading (after the beginner course's band, so its Start and the close's are apart), the
   close as one centred block, and the sources. */
.cp-bl-faq { display: grid; grid-template-columns: minmax(0, 1fr); gap: 28px 64px; padding-block: clamp(64px, 8vw, 96px) 0; }
@media (min-width: 900px) { .cp-bl-faq { grid-template-columns: minmax(0, 4fr) minmax(0, 7fr); align-items: start; } }
.cp-bl .cp-bl-faq .cp-faq summary { font-family: var(--bl-serif); font-size: clamp(19px, 1.8vw, 22px); font-weight: 600; }
.cp-bl-close { padding-block: clamp(64px, 8vw, 96px) 8px; text-align: center; }
.cp-bl-close .cp-bl-h2 { margin-inline: auto; max-width: 16em; }
.cp-bl-close-p { margin: 18px auto 0; max-width: 34em; font-size: clamp(17px, 1.6vw, 19px); line-height: 1.6; color: var(--bl-body); }
.cp-bl-close .cp-join-btns { justify-content: center; margin-top: 28px; }
.cp-bl-close .cp-join-btns > a { white-space: nowrap; }
.cp-bl-more-h { margin-top: clamp(48px, 6vw, 72px); }
.cp-bl-close .s-chips { justify-content: center; margin-top: 18px; }
.cp-bl-close .s-chips a { padding-inline: 18px; }
.cp-bl-sources { padding-block: clamp(40px, 5vw, 64px) 8px; }
.cp-bl-sources summary { display: flex; align-items: center; min-height: 44px; cursor: pointer; }
.cp-bl-sources summary h2 span { color: var(--bl-muted); }
.cp-bl-sources ol { display: grid; gap: 8px; margin-top: 14px; padding-inline-start: 22px; list-style: decimal; font-size: 14px; line-height: 1.5; color: var(--bl-muted); }
.cp-bl-sources a { color: var(--bl-body); text-underline-offset: 3px; overflow-wrap: anywhere; }
.cp-bl-sources li:target { color: var(--color-cream); }

/* The game skin: square corners, the cards framed like the stage card with hard shadows, the panel an arcade screen. */
:root[data-skin="game"] body.s-arcade .cp-bl :is(.cp-bl-sheet-in, .cp-bl-sheet::before, .cp-bl-bar, .cp-bl-unit, .cp-bl-take, .cp-bl-start, .cp-bl-status .s-soon, .cp-bl-legend i) { border-radius: 0; }
:root[data-skin="game"] body.s-arcade .cp-bl :is(.cp-bl-unit, .cp-bl-take) { border: 2px solid var(--a-line-2); box-shadow: 4px 4px 0 var(--arc-shadow-c, #05030d); }
:root[data-skin="game"] body.s-arcade .cp-bl .cp-bl-unit-blue { border-color: #3be7ff; }
:root[data-skin="game"] body.s-arcade .cp-bl .cp-bl-sheet-in { border: 2px solid #3be7ff; box-shadow: 6px 6px 0 #ff5fd2; }
:root[data-skin="game"] body.s-arcade .cp-bl .cp-bl-sheet::before { display: none; }
:root[data-skin="game"] body.s-arcade .cp-bl :is(.cp-bl-sheet-title, .cp-bl-unit-num, .cp-bl-when, .cp-bl-said, .cp-bl-safe-h, .cp-bl-take-count b, .cp-bl-song-year) { font-family: var(--a-display); font-weight: 400; letter-spacing: .01em; font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade .cp-bl :is(.cp-bl-sheet-title, .cp-bl-said) { text-transform: uppercase; }
:root[data-skin="game"] body.s-arcade .cp-bl .cp-bl-said { font-size: clamp(22px, 3.2vw, 38px); line-height: 1.2; }
:root[data-skin="game"] body.s-arcade .cp-bl .cp-bl-sheet-title { font-size: clamp(36px, 5vw, 58px); }
:root[data-skin="game"] body.s-arcade .cp-bl :is(.cp-bl-aim-h, .cp-bl-unit-song, .cp-bl-take-top b, .cp-bl-sheet-top, .cp-bl-start) { font-family: var(--a-hud); font-weight: 400; font-size: 9px; letter-spacing: .06em; line-height: 1.6; font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade .cp-bl :is(.cp-bl-row-h b, .cp-bl-take-row b, .cp-bl-sheet-lines b, .cp-bl-bar b) { font-family: var(--a-display); font-weight: 400; font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade .cp-bl :is(.cp-bl-take-key i.cp-bl-note, .cp-bl-note) { border-radius: 0; }
:root[data-skin="game"] body.s-arcade .cp-bl .cp-bl-sheet-lines span { font-family: inherit; font-style: normal; }
@media (min-width: 480px) { :root[data-skin="game"] body.s-arcade .cp-bl .cp-bl-years li { grid-template-columns: 132px minmax(0, 1fr); } }
:root[data-skin="game"] body.s-arcade .cp-bl .cp-bl-when { font-size: clamp(18px, 2vw, 22px); }
:root[data-skin="game"][data-theme$="-light"] body.s-arcade .cp-bl .cp-bl-sheet-in { border-color: #00708a; box-shadow: 6px 6px 0 #be176c; }

/* Learn your part for rehearsal (site/courses/learn-your-choir-part): Hillel's design (2026-11-18,
   ~/Code/course-designs/learn-your-choir-part), built round the score of the course's song. The four parts in the site's
   own part colours (s-v1 soprano to s-v4 bass: --c, --ci, --ct), the picked one also the page's --pc, --pci and --pct
   (main's data-part, set by js/public/learn-your-choir-part.js), and the theme's tokens, so calm light and dark and game
   all draw it. Instrument Serif for a few accents (the headline's "your", the song's name, the music signs), the
   site's serif until it's there. The hero's score card, the units as rehearsal marks between bar lines with a double
   bar at the end, a sample take, singing safely with its signs, the dark band with Amazing Grace's lanes (dark in calm
   light too), and every lesson page by its mark (so the shared list is left out: lesson-pages-inline). */
.cp-lcp { --lcp-serif: 'Instrument Serif', ui-serif, "Iowan Old Style", "Palatino Linotype", Palatino, Georgia, serif; --pc: var(--color-part-1); --pci: var(--color-part-ink-1); --pct: var(--color-part-text-1); }
.cp-lcp[data-part="alto"] { --pc: var(--color-part-2); --pci: var(--color-part-ink-2); --pct: var(--color-part-text-2); }
.cp-lcp[data-part="tenor"] { --pc: var(--color-part-3); --pci: var(--color-part-ink-3); --pct: var(--color-part-text-3); }
.cp-lcp[data-part="bass"] { --pc: var(--color-part-4); --pci: var(--color-part-ink-4); --pct: var(--color-part-text-4); }

/* The hero: the words at left, the score card at right from 900 px. */
.cp-lcp-hero { display: grid; grid-template-columns: minmax(0, 1fr); gap: 44px 56px; align-items: center; padding-top: 20px; }
.cp-lcp-status { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 12px; margin-top: 22px; }
.cp-lcp-open { display: inline-flex; align-items: center; gap: 7px; padding: 6px 12px; border-radius: 99px; background: color-mix(in srgb, var(--color-good) 18%, var(--color-ink)); color: var(--color-cream); font-size: 13px; font-weight: 700; white-space: nowrap; }
.cp-lcp-open-dot { flex: none; width: 8px; height: 8px; border-radius: 99px; border: 1.5px solid var(--color-good); }
.cp-lcp-count { font-size: 13.5px; color: var(--color-muted); }
.cp-lcp-hero h1 { margin-top: 22px; font-size: clamp(46px, 11vw, 84px); line-height: .94; font-weight: 900; letter-spacing: -0.045em; text-wrap: balance; }
.cp-lcp-your { font-family: var(--lcp-serif); font-style: italic; font-weight: 400; letter-spacing: -0.02em; color: var(--pci); padding-inline-end: .04em; }
.cp-lcp-lead { margin-top: 24px; font-size: clamp(17px, 1.6vw, 19px); line-height: 1.6; color: var(--color-muted); max-width: 32em; text-wrap: pretty; }
.cp-lcp-btns { display: flex; flex-wrap: wrap; gap: 12px; margin-top: 26px; }
.cp-lcp-btns > a { white-space: nowrap; }
.cp-lcp-ways { display: grid; gap: 4px; margin-top: 26px; padding-top: 14px; border-top: 1px solid var(--color-edge); }
.cp-lcp-ways > p { margin: 0; font-size: 15px; font-weight: 550; }
@media (max-width: 639px) {
    .cp-lcp-btns { flex-direction: column; align-items: stretch; }
    .cp-lcp-btns > a { justify-content: center; width: 100%; }
}

/* The score card: which part, the four lanes under numbered bar lines, the picked part's words. */
.cp-lcp-score { container-type: inline-size; display: grid; gap: 20px; padding: clamp(16px, 2.4vw, 28px); border-radius: 22px; background: var(--color-panel); border: 1px solid var(--color-edge); box-shadow: 0 30px 60px -34px rgb(60 40 20 / .3); }
.cp-lcp-score-head { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 12px 16px; }
.cp-lcp-score-song { margin-top: 4px; font-size: 15px; color: var(--color-muted); }
.cp-lcp-score-song i { font-family: var(--lcp-serif); font-size: 20px; color: var(--color-cream); }
.cp-lcp-play { display: inline-flex; align-items: center; gap: 10px; min-height: 44px; padding: 0 18px 0 7px; border-radius: 99px; background: var(--fill-2, var(--color-raised)); color: var(--color-cream); font-size: 15px; font-weight: 700; white-space: nowrap; }
.cp-lcp-play:hover { background: var(--fill-3, var(--color-line)); }
.cp-lcp-play:focus-visible, .cp-lcp-tab:focus-visible { outline: 3px solid var(--color-cream); outline-offset: 2px; }
.cp-lcp-play-icon { position: relative; flex: none; width: 30px; height: 30px; border-radius: 99px; background: var(--color-cream); }
.cp-lcp-play-icon::before { content: ""; position: absolute; inset-block-start: 9px; inset-inline-start: 11px; border-block: 6px solid transparent; border-inline-start: 10px solid var(--color-ink); }
.cp-lcp-play[aria-pressed="true"] .cp-lcp-play-icon::before { inset: 10px; border: 0; border-radius: 2px; background: var(--color-ink); }
.cp-lcp-pick { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 8px; }
.cp-lcp-tab { display: flex; align-items: center; justify-content: center; gap: 8px; min-height: 48px; padding-inline: 6px; border-radius: 12px; border: 1.5px solid var(--color-edge); background: var(--color-panel); color: var(--color-cream); font-size: 14px; font-weight: 700; white-space: nowrap; }
.cp-lcp-tab:hover { border-color: var(--c); }
.cp-lcp-tab[aria-pressed="true"] { background: var(--c); border-color: var(--c); color: var(--ct); }
.cp-lcp-dot { flex: none; width: 8px; height: 8px; border-radius: 99px; background: var(--c); }
.cp-lcp-tab[aria-pressed="true"] .cp-lcp-dot { background: var(--ct); }
.cp-lcp-fig { margin: 0; }
.cp-lcp-lanes { display: grid; grid-template-columns: 16px minmax(0, 1fr); grid-template-rows: 18px repeat(4, 52px) 22px; gap: 6px 10px; }
.cp-lcp-bars { grid-column: 2; grid-row: 1 / -1; position: relative; z-index: 0; }
.cp-lcp-bar { position: absolute; top: 18px; bottom: 22px; width: 1px; background: var(--color-edge); }
.cp-lcp-bar b { position: absolute; top: -20px; inset-inline-start: 4px; font-size: 11.5px; font-weight: 650; color: var(--pci); font-variant-numeric: tabular-nums; }
.cp-lcp-letter { grid-column: 1; display: flex; align-items: center; font-size: 13px; font-weight: 800; color: var(--ci); }
.cp-lcp-lane { grid-column: 2; position: relative; z-index: 1; border-radius: 8px; background: color-mix(in srgb, var(--color-cream) 3%, transparent); }
.cp-lcp-lane[data-picked] { background: color-mix(in srgb, var(--c) 12%, transparent); }
.cp-lcp-letter:not([data-picked]), .cp-lcp-lane:not([data-picked]) { opacity: .32; }
.cp-lcp-n { position: absolute; bottom: calc(12% + var(--y) * 60%); height: 7px; border-radius: 4px; border-inline-end: 3px solid transparent; background: var(--c); background-clip: padding-box; }
.cp-lcp-lane[data-picked] .cp-lcp-n { height: 10px; }
:is(.cp-lcp-n, .cp-lcp-gn)[data-on] { outline: 2px solid var(--color-cream); outline-offset: 1px; }
.cp-lcp-words { grid-column: 2; grid-row: 6; position: relative; }
.cp-lcp-say { position: absolute; inset: 0; visibility: hidden; }
.cp-lcp-say[data-picked] { visibility: visible; }
.cp-lcp-say > span { position: absolute; top: 2px; white-space: nowrap; font-size: 13px; color: var(--color-cream); }
.cp-lcp-say > span[data-cut] { visibility: hidden; }
.cp-lcp-caption { padding-top: 16px; border-top: 1px solid var(--color-edge); font-size: 14px; line-height: 1.5; color: var(--color-muted); }
@container (max-width: 360px) {
    .cp-lcp-pick { grid-template-columns: repeat(2, minmax(0, 1fr)); }
    .cp-lcp-lanes { grid-template-rows: 18px repeat(4, 44px) 22px; }
    .cp-lcp-say > span { font-size: 12px; }
}
@media (prefers-reduced-motion: no-preference) {
    .cp-lcp-letter, .cp-lcp-lane, .cp-lcp-n { transition: opacity .25s, background-color .25s, height .25s; }
}

/* The sections. */
.cp-lcp-sec { padding-top: clamp(64px, 9vw, 104px); }
.cp-lcp-h2 { margin-top: 14px; font-size: clamp(28px, 3.2vw, 36px); line-height: 1.05; font-weight: 800; letter-spacing: -0.03em; text-wrap: balance; }
.cp-lcp-h2-l { font-size: clamp(38px, 5vw, 60px); line-height: .98; font-weight: 900; letter-spacing: -0.04em; }
.cp-lcp-h2 em { font-family: var(--lcp-serif); font-style: italic; font-weight: 400; letter-spacing: -0.01em; }
.cp-lcp-p { margin-top: 18px; font-size: 17px; line-height: 1.65; color: var(--color-muted); max-width: 56ch; text-wrap: pretty; }
.cp-lcp-learn { display: grid; grid-template-columns: minmax(0, 1fr); gap: 28px 48px; }
.cp-lcp-outcomes { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 240px), 1fr)); column-gap: 32px; }
.cp-lcp-outcomes li { display: flex; gap: 16px; padding-block: 16px; border-top: 1px solid var(--color-edge); font-size: 16px; line-height: 1.45; }
.cp-lcp-num, .cp-lcp-ln { flex: none; min-width: 20px; font-size: 12px; font-weight: 700; color: var(--color-muted); font-variant-numeric: tabular-nums; }
.cp-lcp-num { padding-top: 3px; }

/* The units: rehearsal marks between bar lines, a double bar after the last. */
.cp-lcp-units-head { display: flex; flex-wrap: wrap; align-items: flex-end; justify-content: space-between; gap: 12px 16px; }
.cp-lcp-count { font-size: 14px; color: var(--color-muted); }
.cp-lcp-units { display: grid; grid-template-columns: minmax(0, 1fr); margin-top: 36px; border-block: 2px solid var(--color-cream); }
.cp-lcp-unit { display: flex; flex-direction: column; gap: 16px; padding: 28px 22px 30px; border-inline-start: 1px solid var(--color-cream); }
.cp-lcp-unit + .cp-lcp-unit { border-top: 1px solid var(--color-edge); }
.cp-lcp-unit:last-child { border-inline-end: 6px double var(--color-cream); }
.cp-lcp-unit-top { display: flex; align-items: center; gap: 12px; }
.cp-lcp-mark { flex: none; display: grid; place-items: center; width: 40px; height: 40px; border: 2px solid var(--color-cream); font-size: 20px; font-weight: 900; line-height: 1; }
.cp-lcp-unit-n { font-size: 12px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; color: var(--color-muted); }
.cp-lcp-unit h3 { font-size: 21px; font-weight: 800; letter-spacing: -0.02em; }
.cp-lcp-lessons li { display: flex; align-items: center; gap: 0 10px; min-height: 44px; font-size: 15.5px; }
.cp-lcp-lessons a { display: inline-flex; align-items: center; min-height: 44px; text-decoration: underline; text-decoration-color: color-mix(in srgb, var(--color-cream) 28%, transparent); text-underline-offset: 4px; }
.cp-lcp-lessons a:hover { text-decoration-color: currentColor; }
.cp-lcp-lessons .s-free { flex: none; margin: 0; }
@media (min-width: 600px) {
    .cp-lcp-units { grid-template-columns: repeat(2, minmax(0, 1fr)); }
    .cp-lcp-unit + .cp-lcp-unit { border-top: 0; }
    .cp-lcp-unit:nth-child(n+3) { border-top: 1px solid var(--color-cream); }
    .cp-lcp-unit:nth-child(2n) { border-inline-end: 1px solid var(--color-cream); }
    .cp-lcp-unit:last-child { border-inline-end: 6px double var(--color-cream); }
}

/* What the app listens for, beside the sample take. */
.cp-lcp-hears { display: grid; grid-template-columns: minmax(0, 1fr); gap: 36px 56px; align-items: center; }
.cp-lcp-card { display: grid; gap: 18px; padding: clamp(18px, 2.4vw, 28px); border-radius: 22px; background: var(--color-panel); border: 1px solid var(--color-edge); }
.cp-lcp-sample { display: flex; flex-wrap: wrap; align-items: baseline; gap: 6px 10px; font-size: 14px; line-height: 1.45; color: var(--color-muted); }
.cp-lcp-sample b { padding: 3px 10px; border-radius: 99px; background: var(--fill-2, var(--color-raised)); color: var(--color-cream); font-size: 12px; font-weight: 800; letter-spacing: .08em; text-transform: uppercase; white-space: nowrap; }
.cp-lcp-take-head { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 6px 12px; font-size: 14px; color: var(--color-muted); }
.cp-lcp-say-one:not([data-picked]), .cp-lcp-take-lane:not([data-picked]), .cp-lcp-tally:not([data-picked]) { display: none; }
.cp-lcp-take { position: relative; height: 96px; border-radius: 10px; background: color-mix(in srgb, var(--pc) 11%, transparent); }
.cp-lcp-take-lane { position: absolute; inset: 0 10px; }
.cp-lcp-sung, .cp-lcp-where { position: absolute; bottom: calc(16% + var(--y) * 58%); height: 10px; }
.cp-lcp-sung { border-radius: 5px; border-inline-end: 4px solid transparent; background: var(--c); background-clip: padding-box; }
.cp-lcp-sung.cp-lcp-off, .cp-lcp-key-off { background-color: color-mix(in srgb, var(--color-cream) 26%, var(--color-panel)); }
.cp-lcp-where::after { content: ""; position: absolute; inset: 0 4px 0 0; border: 2px dashed var(--color-muted); border-radius: 5px; }
.cp-lcp-tally { display: flex; flex-wrap: wrap; align-items: baseline; gap: 4px 12px; }
.cp-lcp-tally b { font-size: 44px; font-weight: 900; line-height: 1; letter-spacing: -0.03em; font-variant-numeric: tabular-nums; }
.cp-lcp-tally span { font-size: 16px; color: var(--color-muted); }
.cp-lcp-key { display: flex; flex-wrap: wrap; gap: 8px 20px; font-size: 13.5px; color: var(--color-muted); }
.cp-lcp-key li { display: flex; align-items: center; gap: 8px; }
.cp-lcp-key-on, .cp-lcp-key-off, .cp-lcp-key-where { flex: none; width: 18px; height: 8px; border-radius: 4px; }
.cp-lcp-key-on { background: var(--pc); }
.cp-lcp-key-where { border: 1.5px dashed var(--color-muted); }

/* Singing safely, each line by its music sign, beside the song. */
.cp-lcp-notes { display: grid; grid-template-columns: minmax(0, 1fr); gap: 0 56px; margin-top: clamp(56px, 7vw, 88px); background: linear-gradient(var(--color-edge), var(--color-edge)) top / 100% 1px no-repeat content-box; }
.cp-lcp-notes > * { padding-top: 40px; }
.cp-lcp-safe { margin-top: 10px; }
.cp-lcp-safe li { display: flex; align-items: baseline; gap: 18px; padding-block: 14px; font-size: 16px; line-height: 1.5; }
.cp-lcp-safe li + li { border-top: 1px solid var(--color-edge); }
.cp-lcp-sign { flex: none; width: 40px; font-family: var(--lcp-serif); font-style: italic; font-size: 26px; line-height: 1; color: var(--pci); }
.cp-lcp-songs li { display: grid; gap: 10px; padding-top: 14px; }
.cp-lcp-songs b { font-family: var(--lcp-serif); font-style: italic; font-weight: 400; font-size: clamp(28px, 3vw, 34px); line-height: 1.05; }
.cp-lcp-songs span { font-size: 16px; line-height: 1.6; color: var(--color-muted); }

/* The beginner course on the dark band (dark in calm light too, with its own light words and buttons), beside Amazing
   Grace's four parts, lit as they sound. */
.cp-lcp-today { margin-top: clamp(64px, 9vw, 112px); }
:root:not([data-skin="game"])[data-theme$="-light"] .cp-lcp-today {
    --color-ink: #1c1612; --color-cream: #f4ede3; --color-muted: #cfc5b8; --color-edge: #3d332b; --color-panel: #26201b;
    --color-part-ink-1: var(--color-part-1); --color-part-ink-2: #e0b43c; --color-part-ink-3: #3fc28a; --color-part-ink-4: #4aa8e8;
    --fill-2: color-mix(in srgb, #f4ede3 10%, transparent); --fill-3: color-mix(in srgb, #f4ede3 16%, transparent);
    --btn-soft: var(--fill-2); --btn-soft-hover: var(--fill-3);
    --primary: #f4ede3; --primary-ink: #1c1612; --primary-hover-to: #1c1612;
    background: #1c1612; color: var(--color-cream);
}
:root:not([data-skin="game"])[data-theme$="-light"] .cp-lcp-today .cp-lcp-glanes { --color-part-1: #f2a36a; --color-part-2: #e9d24a; --color-part-3: #3fc28a; --color-part-4: #4aa8e8; }
.cp-lcp-today-in { display: grid; grid-template-columns: minmax(0, 1fr); gap: 40px 56px; align-items: center; }
.cp-lcp-today .cp-lcp-h2-l { margin-top: 18px; }
.cp-lcp-grace { margin: 0; padding: clamp(18px, 2.4vw, 28px); border-radius: 22px; background: color-mix(in srgb, var(--color-cream) 5%, transparent); border: 1px solid color-mix(in srgb, var(--color-cream) 12%, transparent); }
.cp-lcp-grace-head { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 10px 16px; margin-bottom: 16px; }
.cp-lcp-grace-head p { font-size: 13.5px; color: var(--color-muted); }
.cp-lcp-glanes { display: grid; grid-template-columns: max-content minmax(0, 1fr); gap: 8px 12px; }
.cp-lcp-gname { display: flex; align-items: center; font-size: 13px; font-weight: 700; color: var(--c); }
.cp-lcp-glane { position: relative; height: 44px; border-radius: 8px; background: rgb(0 0 0 / .22); }
.cp-lcp-gn { position: absolute; bottom: calc(16% + var(--y) * 56%); height: 7px; border-radius: 4px; border-inline-end: 3px solid transparent; background: color-mix(in srgb, var(--c) 28%, transparent); background-clip: padding-box; }
.cp-lcp-gn.cp-lcp-still, .cp-lcp-gn[data-sung] { background-color: var(--c); box-shadow: 0 0 12px color-mix(in srgb, var(--c) 70%, transparent); }
.cp-lcp-grace[data-playing] .cp-lcp-gn.cp-lcp-still:not([data-sung]) { background-color: color-mix(in srgb, var(--c) 28%, transparent); box-shadow: none; }

/* Lesson 1, in four numbered bars between bar lines (as the units), the picked part's own card in bar 2. */
.cp-lcp-try { display: grid; grid-template-columns: minmax(0, 1fr); margin-top: 32px; border-block: 2px solid var(--color-cream); }
.cp-lcp-try > li { display: flex; flex-direction: column; gap: 14px; padding: 24px 22px 28px; border-inline-start: 1px solid var(--color-cream); }
.cp-lcp-try > li + li { border-top: 1px solid var(--color-edge); }
.cp-lcp-try > li:last-child { border-inline-end: 6px double var(--color-cream); }
.cp-lcp-try-n { display: flex; align-items: center; gap: 12px; font-size: 12px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; color: var(--color-muted); }
.cp-lcp-try-n .cp-lcp-mark { width: 32px; height: 32px; font-size: 16px; letter-spacing: 0; color: var(--color-cream); }
.cp-lcp-try-cards { display: grid; gap: 12px; font-size: 15px; line-height: 1.5; color: var(--color-muted); }
.cp-lcp-try-cards b { display: block; font-size: 15.5px; color: var(--color-cream); }
.cp-lcp-try-part:not([data-picked]) { display: none; }
.cp-lcp-try-head { margin-bottom: 12px; font-size: 16px; font-weight: 700; line-height: 1.4; color: var(--ci); }
.cp-lcp-try-text { font-size: 16.5px; font-weight: 600; line-height: 1.5; }
.cp-lcp-try-note { font-size: 14px; line-height: 1.5; color: var(--color-muted); }
.cp-lcp-join { margin-top: 12px; font-size: 14px; color: var(--color-muted); }
@media (min-width: 600px) {
    .cp-lcp-try { grid-template-columns: repeat(2, minmax(0, 1fr)); }
    .cp-lcp-try > li + li { border-top: 0; }
    .cp-lcp-try > li:nth-child(n+3) { border-top: 1px solid var(--color-cream); }
    .cp-lcp-try > li:nth-child(2n) { border-inline-end: 1px solid var(--color-cream); }
    .cp-lcp-try > li:last-child { border-inline-end: 6px double var(--color-cream); }
}
@media (min-width: 1024px) {
    .cp-lcp-try { grid-template-columns: repeat(4, minmax(0, 1fr)); }
    .cp-lcp-try > li:nth-child(n) { border-top: 0; border-inline-end: 0; }
    .cp-lcp-try > li:last-child { border-inline-end: 6px double var(--color-cream); }
}

/* Why it works: the course's findings on one dated line, oldest first (down the side on a phone, across from 1024 px). */
.cp-lcp-found { display: grid; grid-template-columns: minmax(0, 1fr); margin-top: 36px; }
.cp-lcp-found > li { position: relative; padding: 0 0 32px 28px; border-inline-start: 2px solid var(--color-cream); }
.cp-lcp-found > li::before { content: ""; position: absolute; top: 12px; inset-inline-start: -9px; width: 16px; height: 16px; border-radius: 99px; background: var(--pc); border: 3px solid var(--color-ink); }
.cp-lcp-year { font-size: clamp(36px, 4vw, 48px); font-weight: 900; line-height: 1; letter-spacing: -0.03em; font-variant-numeric: tabular-nums; }
.cp-lcp-found h3 { margin-top: 12px; font-size: 19px; font-weight: 800; letter-spacing: -0.01em; text-wrap: balance; }
.cp-lcp-found-text { margin-top: 8px; font-size: 15.5px; line-height: 1.6; color: var(--color-muted); }
.cp-lcp-found-use { margin-top: 14px; padding-top: 14px; border-top: 1px dashed var(--color-edge); font-size: 15px; line-height: 1.5; }
.cp-lcp-found-use .cp-lcp-unit-n { margin-inline-end: 6px; }
@media (min-width: 1024px) {
    .cp-lcp-found { grid-template-columns: repeat(4, minmax(0, 1fr)); }
    .cp-lcp-found > li { padding: 34px 28px 0 0; border-inline-start: 0; border-top: 2px solid var(--color-cream); }
    .cp-lcp-found > li::before { top: -9px; inset-inline-start: 0; }
}

/* Who it's for and what you need, two ruled lists; the questions; the close between a bar line and the final double
   bar; the numbered sources. */
.cp-lcp-who { display: grid; grid-template-columns: minmax(0, 1fr); gap: 40px 56px; }
.cp-lcp-ruled { margin-top: 12px; }
.cp-lcp-ruled li { padding-block: 14px; font-size: 16px; line-height: 1.5; }
.cp-lcp-ruled li + li { border-top: 1px solid var(--color-edge); }
.cp-lcp-close { display: grid; justify-items: center; padding: clamp(40px, 6vw, 72px) 22px; text-align: center; border-block: 2px solid var(--color-cream); border-inline-start: 1px solid var(--color-cream); border-inline-end: 6px double var(--color-cream); }
.cp-lcp-close .cp-lcp-p { margin-inline: auto; }
.cp-lcp-close .cp-lcp-btns { justify-content: center; }
.cp-lcp-sources ol { display: grid; gap: 8px; margin-top: 14px; padding-inline-start: 22px; list-style: decimal; font-size: 14px; line-height: 1.5; color: var(--color-muted); }
.cp-lcp-sources a { text-decoration: underline; text-underline-offset: 3px; overflow-wrap: anywhere; }
@media (min-width: 900px) {
    .cp-lcp-who { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}

/* Every lesson page, by its mark. */
.cp-lcp-reads { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 240px), 1fr)); gap: 12px; margin-top: 22px; }
.cp-lcp-reads a { display: flex; flex-direction: column; gap: 10px; height: 100%; padding: 20px; border-radius: 14px; border: 1px solid var(--color-edge); background: var(--color-panel); }
.cp-lcp-reads a:hover { border-color: var(--color-cream); }
.cp-lcp-reads .cp-lcp-mark { width: 30px; height: 30px; font-size: 15px; }
.cp-lcp-reads b { font-size: 16px; font-weight: 700; }
.cp-lcp-reads a > span:last-child { font-size: 14px; line-height: 1.45; color: var(--color-muted); }

@media (min-width: 900px) {
    .cp-lcp-hero { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); padding-top: 36px; }
    .cp-lcp-learn { grid-template-columns: minmax(0, 1fr) minmax(0, 2fr); }
    .cp-lcp-hears { grid-template-columns: repeat(2, minmax(0, 1fr)); }
    .cp-lcp-notes { grid-template-columns: repeat(2, minmax(0, 1fr)); }
    .cp-lcp-today-in { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (min-width: 1024px) {
    .cp-lcp-units { grid-template-columns: repeat(4, minmax(0, 1fr)); }
    .cp-lcp-unit:nth-child(n) { border-top: 0; border-inline-end: 0; }
    .cp-lcp-unit:last-child { border-inline-end: 6px double var(--color-cream); }
}

/* The game skin: the arcade's pixel headings and HUD labels, framed square panels, square notes and marks. */
:root[data-skin="game"] body.s-arcade :is(.cp-lcp-h2, .cp-lcp-tally b, .cp-lcp-mark, .cp-lcp-year) { font-family: var(--arc-pixel); font-weight: 400; letter-spacing: 0; font-size-adjust: .58; --arc-ex: .58; line-height: 1.25; text-shadow: .06em .06em 0 var(--arc-shade); }
:root[data-skin="game"] body.s-arcade .cp-lcp-h2 { font-size: clamp(22px, 3vw, 32px); }
:root[data-skin="game"] body.s-arcade .cp-lcp-h2-l { font-size: clamp(24px, 3.6vw, 40px); }
:root[data-skin="game"] body.s-arcade :is(.cp-lcp-your, .cp-lcp-h2 em, .cp-lcp-score-song i, .cp-lcp-songs b, .cp-lcp-sign) { font-family: inherit; font-style: normal; font-weight: inherit; letter-spacing: inherit; }
:root[data-skin="game"] body.s-arcade :is(.cp-lcp-songs b, .cp-lcp-sign) { font-weight: 700; }
:root[data-skin="game"] body.s-arcade :is(.cp-lcp-count, .cp-lcp-sample b, .cp-lcp-open, .cp-lcp-unit-n) { font-family: var(--a-hud); font-weight: 400; font-size: 11px; font-size-adjust: var(--arc-ex, none); letter-spacing: .06em; }
:root[data-skin="game"] body.s-arcade :is(.cp-lcp-score, .cp-lcp-card, .cp-lcp-grace, .cp-lcp-reads a) { border: var(--arc-edge-w, 2px) solid var(--arc-line); box-shadow: var(--arc-shadow); border-radius: 0; }
:root[data-skin="game"] body.s-arcade :is(.cp-lcp-tab, .cp-lcp-lane, .cp-lcp-n, .cp-lcp-take, .cp-lcp-sung, .cp-lcp-where::after, .cp-lcp-glane, .cp-lcp-gn) { border-radius: 0; }

/* Sea shanties and work songs (site/courses/sea-shanties-and-work-songs): Hillel's design (2026-11-18,
   ~/Code/course-designs/sea-shanties), built around call and response. A warm paper page in Figtree with the system
   serif's italic for the answer (the headline's second line, each section's second phrase, the songs) in the sea's teal,
   mono labels, and two sea-teal panels: the hero's Haul Away, Joe card (a demo stays the night cabinet in every look)
   and what the app listens for. The units are a dashed route, each with its voices: the shantyman a large ring, the crew
   small rings, you filled (and named for a screen reader). Calm dark: the same page at night. Game skin: neon on the
   arcade's ground, Bungee headings and pixel labels, square frames with hard shadows. The idle lane sweeps by CSS only,
   still under reduced motion (the answer lit); playing, js/public/sea-shanties-and-work-songs.js lights each note. */
.cp-sh { --sh-paper: #f9f5ef; --sh-band: #f4eee5; --sh-card: #fff; --sh-ink: #1a1411; --sh-body: #3f3731; --sh-muted: #5a514a; --sh-faint: #6b6158; --sh-line: #e0d6c8; --sh-edge: #e4ddd3; --sh-rule: #1a1411; --sh-dash: #c9b796;
    --sh-teal: #0c4b57; --sh-label: #7d6000; --sh-you: #e8833f; --sh-rust: #a8461a; --sh-crew: #8a8076; --sh-open-bg: #dfe9dc; --sh-open: #1f6b3a; --sh-start: #1f6b3a; --sh-start-ink: #fff;
    --sh-sea: #0f2f36; --sh-sea-ink: #f3ece1; --sh-sea-soft: #9fc0c2; --sh-sea-body: #cfd9d6; --sh-sea-gear: #b7c8c6; --sh-sea-kick: #e8b54a; --sh-sea-line: rgba(255, 255, 255, .12);
    --sh-call-dim: rgba(243, 227, 195, .35); --sh-call-lit: #f3e3c3; --sh-ans-dim: rgba(255, 255, 255, .14); --sh-ans-lit: #e8833f; --sh-head: #fff;
    --sh-take: #f9f5ef; --sh-take-ink: #1a1411; --sh-take-body: #4a423c; --sh-take-faint: #6b6158; --sh-take-line: #e4ddd3; --sh-hit: #0c4b57; --sh-miss: #a8461a;
    --sh-night: #17120f; --sh-night-ink: #f3ece1; --sh-night-body: #cbc2b7; --sh-night-raised: #2a221d;
    --sh-serif: ui-serif, "Iowan Old Style", "Palatino Linotype", Palatino, Georgia, serif; --sh-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
    --cp-a: var(--sh-teal); --cp-a-ink: #fff; --cp-a-text: var(--sh-teal); --cp-line: var(--sh-line);
    --color-cream: var(--sh-ink); --color-muted: var(--sh-muted); --fill-2: var(--sh-band); --fill-3: var(--sh-line);
    background: var(--sh-paper); color: var(--sh-ink); }
:root:not([data-theme$="-light"]) .cp-sh { --sh-paper: #15110e; --sh-band: #1b1612; --sh-card: #211b17; --sh-ink: #f3ece2; --sh-body: #d8cec2; --sh-muted: #c9bfb3; --sh-faint: #b3a797; --sh-line: #3a3029; --sh-edge: #3a3029; --sh-rule: #f3ece2; --sh-dash: #5a4d3e;
    --sh-teal: #7fc3cc; --sh-label: #e8b54a; --sh-rust: #ff9a7f; --sh-crew: #a99f94; --sh-open-bg: #1d3324; --sh-open: #9fe0b4; --sh-start: #9fe0b4; --sh-start-ink: #10261a;
    --sh-sea: #0d2a30; --sh-take: #16262a; --sh-take-ink: #f3ece1; --sh-take-body: #cfd9d6; --sh-take-faint: #9fc0c2; --sh-take-line: #2a4248; --sh-hit: #7fc3cc; --sh-miss: #ff9a7f;
    --sh-night: #0c0907; }
:root[data-skin="game"] .cp-sh { --sh-paper: #07060e; --sh-band: #0c0a17; --sh-card: #12101e; --sh-ink: #ede9ff; --sh-body: #d2ccf0; --sh-muted: #b8b2d8; --sh-faint: #aaa4d0; --sh-line: #2a2640; --sh-edge: #2a2640; --sh-rule: #3be7ff; --sh-dash: #3a3560;
    --sh-teal: #3be7ff; --sh-label: #ffd84a; --sh-you: #ffd84a; --sh-rust: #ff9de6; --sh-crew: #aaa4d0; --sh-open-bg: #0f2a1c; --sh-open: #45e3a5; --sh-start: #45e3a5; --sh-start-ink: #04140d;
    --sh-sea: #0b0820; --sh-sea-ink: #ede9ff; --sh-sea-soft: #3be7ff; --sh-sea-body: #d2ccf0; --sh-sea-gear: #b8b2d8; --sh-sea-kick: #ffd84a; --sh-sea-line: #2a2640;
    --sh-call-dim: rgba(59, 231, 255, .28); --sh-call-lit: #3be7ff; --sh-ans-dim: rgba(255, 255, 255, .14); --sh-ans-lit: #ffd84a; --sh-head: #ff5fd2;
    --sh-take: #12101e; --sh-take-ink: #ede9ff; --sh-take-body: #d2ccf0; --sh-take-faint: #aaa4d0; --sh-take-line: #2a2640; --sh-hit: #45e3a5; --sh-miss: #ff5fd2;
    --sh-night: #05040a; --sh-night-raised: #12101e;
    --cp-a: #45e3a5; --cp-a-ink: #04140d; }
:root[data-skin="game"][data-theme$="-light"] .cp-sh { --sh-paper: #f4f1ff; --sh-band: #ebe6ff; --sh-card: #fff; --sh-ink: #14122b; --sh-body: #2e2950; --sh-muted: #403a66; --sh-faint: #4d4775; --sh-line: #d9d3f2; --sh-edge: #d9d3f2; --sh-rule: #14122b; --sh-dash: #bdb5e3;
    --sh-teal: #00708a; --sh-label: #7a5a00; --sh-you: #b0157a; --sh-rust: #b0157a; --sh-crew: #4d4775; --sh-open-bg: #dff3e8; --sh-open: #1f6b3a; --sh-start: #1f6b3a; --sh-start-ink: #fff;
    --sh-take: #fff; --sh-take-ink: #14122b; --sh-take-body: #2e2950; --sh-take-faint: #4d4775; --sh-take-line: #d9d3f2; --sh-hit: #00708a; --sh-miss: #b0157a;
    --cp-a: #00708a; --cp-a-ink: #fff; }
.cp-sh a:not([class*="btn"]) { color: inherit; text-underline-offset: 3px; }
.cp-sh .s-crumb, .cp-sh .s-crumb a { color: var(--sh-muted); }
.cp-sh .btn-lg { white-space: nowrap; }
.cp-sh em { font-family: var(--sh-serif); font-style: italic; font-weight: 400; letter-spacing: -0.02em; color: var(--sh-teal); }
.cp-sh-kick { font-size: 12px; font-weight: 700; letter-spacing: .16em; text-transform: uppercase; color: var(--sh-label); }
.cp-sh-h2 { margin-top: 14px; font-size: clamp(32px, 4vw, 46px); line-height: 1.05; font-weight: 800; letter-spacing: -0.03em; text-wrap: balance; }

/* The hero: the call and its answer, then the card. Side by side from 900 px. */
.cp-sh-hero { display: grid; grid-template-columns: minmax(0, 1fr); gap: 44px; padding-top: 22px; padding-bottom: clamp(64px, 9vw, 96px); }
.cp-sh-hero-text { display: flex; flex-direction: column; gap: 22px; }
.cp-sh-status { display: flex; flex-wrap: wrap; align-items: center; gap: 10px 14px; margin-top: 10px; }
.cp-sh-open { display: inline-flex; align-items: center; gap: 7px; padding: 6px 12px; border-radius: 99px; background: var(--sh-open-bg); color: var(--sh-open); font-size: 13px; font-weight: 650; white-space: nowrap; }
.cp-sh-open-dot { width: 6px; height: 6px; border-radius: 99px; border: 1.5px solid currentColor; }
.cp-sh-meta { font-family: var(--sh-mono); font-size: 12px; font-weight: 500; letter-spacing: .04em; text-transform: uppercase; color: var(--sh-faint); }
.cp-sh-h1 { font-size: clamp(46px, 11vw, 80px); line-height: .96; font-weight: 800; letter-spacing: -0.04em; text-wrap: balance; }
.cp-sh-h1 em { display: block; letter-spacing: -0.025em; }
.cp-sh-lead { max-width: 520px; font-size: 18px; line-height: 1.6; color: var(--sh-body); text-wrap: pretty; }
.cp-sh-btns { display: flex; flex-wrap: wrap; gap: 12px; }
.cp-sh-btns > * { flex: 1 1 auto; justify-content: center; }

/* The card: Haul Away, Joe's call and answer over the tune's lane. */
.cp-sh-card { display: flex; flex-direction: column; gap: 24px; padding: 24px; border-radius: 24px; background: var(--sh-sea); color: var(--sh-sea-ink); box-shadow: 0 30px 60px -30px rgba(15, 47, 54, .55); }
.cp-sh-card-top, .cp-sh-lane-labels { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 6px 12px; font-family: var(--sh-mono); font-size: 12px; font-weight: 500; letter-spacing: .04em; text-transform: uppercase; color: var(--sh-sea-soft); }
.cp-sh-lane-labels { margin-top: -12px; font-size: 11px; }
.cp-sh-lines { display: flex; flex-direction: column; gap: 16px; }
.cp-sh-lines p { display: grid; gap: 6px; }
.cp-sh-who { font-size: 11px; font-weight: 650; letter-spacing: .14em; text-transform: uppercase; color: var(--sh-sea-soft); }
.cp-sh-who-you { color: var(--sh-ans-lit); }
.cp-sh-callline .cp-sh-sung { font-family: var(--sh-serif); font-style: italic; font-size: 21px; line-height: 1.3; color: var(--sh-sea-body); }
.cp-sh-answerline .cp-sh-sung { font-size: 24px; line-height: 1.2; font-weight: 700; letter-spacing: -0.02em; color: var(--sh-sea-ink); }
.cp-sh-pull { color: var(--sh-ans-lit); border-bottom: 3px solid var(--sh-ans-lit); white-space: nowrap; }
.cp-sh-lane { position: relative; height: 72px; }
.cp-sh-note { position: absolute; bottom: 0; box-sizing: border-box; border-inline-end: 3px solid transparent; background-clip: padding-box; border-radius: 4px; background-color: var(--sh-call-dim); transform-origin: bottom; }
.cp-sh-note-answer { background-color: var(--sh-ans-lit); }
.cp-sh-divide { position: absolute; left: var(--answer); top: -10px; bottom: -10px; border-left: 1px dashed rgba(159, 192, 194, .5); }
.cp-sh-head { position: absolute; top: -6px; bottom: -6px; left: calc(var(--p, 0) * 100%); width: 2px; border-radius: 1px; background: var(--sh-head); opacity: 0; }
.cp-sh-card[data-playing] .cp-sh-head { opacity: .85; }
.cp-sh-card[data-playing] .cp-sh-note-answer { background-color: var(--sh-ans-dim); }
.cp-sh-card[data-playing] .cp-sh-note[data-on]:not(.cp-sh-note-answer) { background-color: var(--sh-call-lit); }
.cp-sh-card[data-playing] .cp-sh-note-answer:is([data-on], [data-sung]) { background-color: var(--sh-ans-lit); }
.cp-sh-card[data-playing] .cp-sh-note[data-on] { transform: scaleY(1.06); }
/* Idle, a silent sweep: the call lit as the line passes, the answer lit after it, the designer's loop (Hillel's notes:
   the animation on, reduced motion respected). Each note's delay is its place (--d, its left in percent). */
@media (prefers-reduced-motion: no-preference) {
    .cp-sh-card:not([data-playing]) .cp-sh-head { opacity: .8; animation: cp-sh-sweep 9s linear infinite; }
    .cp-sh-card:not([data-playing]) .cp-sh-note { animation: cp-sh-call 9s linear infinite; animation-delay: calc(var(--d) * 0.09s - 9s); }
    .cp-sh-card:not([data-playing]) .cp-sh-note-answer { animation-name: cp-sh-answer; }
}
@keyframes cp-sh-sweep { from { left: 0; } to { left: 100%; } }
@keyframes cp-sh-call { 0% { background-color: var(--sh-call-lit); } 8% { background-color: var(--sh-call-lit); } 16%, 100% { background-color: var(--sh-call-dim); } }
@keyframes cp-sh-answer { 0% { background-color: var(--sh-ans-lit); transform: scaleY(1.06); } 6% { transform: scaleY(1); } 14% { background-color: var(--sh-ans-lit); } 24%, 100% { background-color: var(--sh-ans-dim); } }
.cp-sh-card-foot { display: flex; flex-wrap: wrap; align-items: center; gap: 12px 18px; padding-top: 18px; border-top: 1px solid var(--sh-sea-line); }
.cp-sh-play { display: inline-flex; align-items: center; gap: 10px; flex: none; min-height: 44px; padding: 0 20px 0 16px; border-radius: 99px; background: var(--sh-sea-ink); color: var(--sh-sea); font-size: 15px; font-weight: 650; white-space: nowrap; cursor: pointer; }
.cp-sh-play:focus-visible { outline: 2px solid var(--sh-sea-ink); outline-offset: 3px; }
.cp-sh-play-icon { width: 0; height: 0; border-block: 7px solid transparent; border-inline-start: 11px solid currentColor; }
.cp-sh-play[aria-pressed="true"] .cp-sh-play-icon { width: 11px; height: 11px; border: 0; border-radius: 2px; background: currentColor; }
.cp-sh-source { flex: 1 1 200px; font-size: 13px; line-height: 1.45; color: var(--sh-sea-soft); }

/* The course: a route from the crew to the shantyman, each unit a stop on a dashed line, with its voices. */
.cp-sh-voyage { padding-block: clamp(56px, 8vw, 80px); border-block: 1px solid var(--sh-edge); background: var(--sh-band); }
.cp-sh-voyage-head { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: flex-end; gap: 20px 24px; margin-bottom: 44px; }
.cp-sh-legend { display: flex; flex-wrap: wrap; align-items: center; gap: 10px 18px; font-size: 13px; color: var(--sh-muted); }
.cp-sh-legend li { display: inline-flex; align-items: center; gap: 7px; }
.cp-sh-dot { display: inline-block; flex: none; width: 10px; height: 10px; border-radius: 99px; box-sizing: border-box; }
.cp-sh-dot-lead { width: 14px; height: 14px; border: 1.5px solid var(--sh-teal); }
.cp-sh-dot-crew { border: 1.5px solid var(--sh-crew); }
.cp-sh-dot-you { background: var(--sh-you); }
.cp-sh-dot-youlead { width: 14px; height: 14px; background: var(--sh-you); box-shadow: 0 0 0 2px var(--sh-band), 0 0 0 3.5px var(--sh-teal); }
.cp-sh-units { display: grid; grid-template-columns: minmax(0, 1fr); row-gap: 36px; }
.cp-sh-unit { position: relative; display: flex; flex-direction: column; gap: 14px; padding: 26px 0 0; border-top: 2px dashed var(--sh-dash); }
.cp-sh-node { position: absolute; top: -8px; left: 0; width: 14px; height: 14px; border-radius: 99px; box-sizing: border-box; background: var(--sh-band); border: 2px solid var(--sh-teal); }
.cp-sh-crew { display: flex; align-items: center; gap: 8px; min-height: 16px; }
.cp-sh-voices { display: flex; align-items: center; gap: 6px; }
.cp-sh-role { font-family: var(--sh-mono); font-size: 11px; font-weight: 500; color: var(--sh-faint); }
.cp-sh-unit-n { margin-top: 4px; font-family: var(--sh-mono); font-size: 12px; font-weight: 500; letter-spacing: .04em; text-transform: uppercase; color: var(--sh-label); }
.cp-sh-unit h3 { margin-top: -8px; font-size: 22px; font-weight: 700; letter-spacing: -0.015em; }
.cp-sh-outcome { font-size: 14px; line-height: 1.5; color: var(--sh-body); text-wrap: pretty; }
.cp-sh-lessons { border-top: 1px solid var(--sh-line); }
.cp-sh-lessons li { border-bottom: 1px solid var(--sh-line); }
.cp-sh-lessons :is(a, .cp-sh-nolink) { display: grid; grid-template-columns: 22px minmax(0, 1fr); gap: 8px; min-height: 44px; padding: 11px 0; text-decoration: none; }
.cp-sh-ln { font-family: var(--sh-mono); font-size: 12px; line-height: 1.6; color: var(--sh-faint); }
.cp-sh-lt { display: flex; flex-direction: column; gap: 3px; }
.cp-sh-lname { display: flex; flex-wrap: wrap; align-items: center; gap: 4px 8px; }
.cp-sh-lname b { font-size: 15px; font-weight: 650; }
.cp-sh-lname b.cp-sh-song { font-family: var(--sh-serif); font-style: italic; font-weight: 500; font-size: 17px; line-height: 1.2; color: var(--sh-teal); }
.cp-sh-lessons a:hover b { text-decoration: underline; text-underline-offset: 3px; }
.cp-sh-start { padding: 2px 8px; border-radius: 99px; background: var(--sh-start); color: var(--sh-start-ink); font-size: 10px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; white-space: nowrap; }
.cp-sh-line { font-size: 13px; line-height: 1.4; color: var(--sh-faint); }
/* The page's paper reaches the footer below its <main> in calm (the shared data-course hook on the body), so there's no
   seam; game keeps the arcade's own ground. */
:root:not([data-skin="game"]) body[data-course="sea-shanties-and-work-songs"] { background: #f9f5ef; }
:root:not([data-skin="game"]):not([data-theme$="-light"]) body[data-course="sea-shanties-and-work-songs"] { background: #15110e; }

/* What the app listens for: the sea-teal panel, scored and not, beside the sample take. */
.cp-sh-listen-sec { padding-top: clamp(64px, 9vw, 96px); }
.cp-sh-listen { display: grid; grid-template-columns: minmax(0, 1fr); gap: 40px; padding: clamp(26px, 5vw, 56px); border-radius: 28px; background: var(--sh-sea); color: var(--sh-sea-ink); }
.cp-sh-listen .cp-sh-kick { color: var(--sh-sea-kick); }
.cp-sh-listen .cp-sh-h2 { color: var(--sh-sea-ink); }
.cp-sh-listen .cp-sh-h2 em { color: var(--sh-sea-soft); }
.cp-sh-scores { display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)); gap: 24px; margin-top: 26px; }
.cp-sh-score-h { margin-bottom: 10px; font-family: var(--sh-mono); font-size: 11px; font-weight: 500; letter-spacing: .06em; text-transform: uppercase; color: var(--sh-sea-soft); }
.cp-sh-score-yes { color: var(--sh-ans-lit); }
.cp-sh-scores li { font-size: 16px; line-height: 1.45; }
.cp-sh-scores li + li { margin-top: 10px; }
.cp-sh-unscored li { color: var(--sh-sea-body); }
.cp-sh-gear { margin-top: 24px; padding-top: 20px; border-top: 1px solid var(--sh-sea-line); font-size: 15px; line-height: 1.6; color: var(--sh-sea-gear); text-wrap: pretty; }
.cp-sh-sample { display: flex; flex-direction: column; gap: 20px; align-self: start; padding: 24px; border-radius: 20px; background: var(--sh-take); color: var(--sh-take-ink); }
.cp-sh-sample-top { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: center; gap: 8px 12px; font-family: var(--sh-mono); font-size: 12px; text-transform: uppercase; color: var(--sh-take-faint); }
.cp-sh-sample-tag { padding: 3px 9px; border: 1.5px solid currentColor; border-radius: 99px; font-weight: 600; color: var(--sh-take-ink); }
.cp-sh-cells { display: grid; grid-template-columns: repeat(12, minmax(0, 1fr)); gap: 5px; }
.cp-sh-cell { display: inline-block; height: 28px; border-radius: 5px; background: var(--sh-hit); }
.cp-sh-cell-off { box-sizing: border-box; border: 1.5px dashed var(--sh-miss); background: none; }
.cp-sh-cells-key { display: flex; flex-wrap: wrap; gap: 6px 18px; font-size: 13px; color: var(--sh-take-body); }
.cp-sh-cells-key > span { display: inline-flex; align-items: center; gap: 7px; }
.cp-sh-cells-key .cp-sh-cell { width: 14px; height: 14px; border-radius: 3px; }
.cp-sh-sample-n { font-size: clamp(28px, 4vw, 34px); line-height: 1.05; font-weight: 800; letter-spacing: -0.03em; }
.cp-sh-sample-foot { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: baseline; gap: 8px 16px; padding-top: 16px; border-top: 1px solid var(--sh-take-line); font-size: 14px; line-height: 1.45; color: var(--sh-take-body); }
.cp-sh-sample-foot b { color: var(--sh-take-ink); font-weight: 700; }
.cp-sh-sample-skin { font-family: var(--sh-serif); font-style: italic; font-size: 16px; }

/* The songbook's index beside singing safely, numbered. */
.cp-sh-book { display: grid; grid-template-columns: minmax(0, 1fr); gap: 56px; padding-top: clamp(64px, 9vw, 96px); }
.cp-sh-songs, .cp-sh-safety { margin-top: 20px; border-top: 1px solid var(--sh-rule); }
.cp-sh-songs li { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 4px 20px; padding: 16px 0; border-bottom: 1px solid var(--sh-line); }
.cp-sh-songs b { font-family: var(--sh-serif); font-style: italic; font-weight: 400; font-size: 25px; line-height: 1.15; letter-spacing: -0.01em; }
.cp-sh-year { align-self: center; font-family: var(--sh-mono); font-size: 13px; font-weight: 500; color: var(--sh-label); }
.cp-sh-src { grid-column: 1 / -1; font-size: 14px; line-height: 1.5; color: var(--sh-muted); text-wrap: pretty; }
.cp-sh-story { grid-column: 1 / -1; margin-top: 6px; font-size: 15px; line-height: 1.55; color: var(--sh-body); text-wrap: pretty; }
.cp-sh-story a { font-weight: 650; text-decoration: underline; text-decoration-color: var(--sh-dash); white-space: nowrap; }
.cp-sh-safety li { display: grid; grid-template-columns: 36px minmax(0, 1fr); gap: 12px; align-items: baseline; padding: 18px 0; border-bottom: 1px solid var(--sh-line); font-size: 17px; line-height: 1.45; text-wrap: pretty; }
.cp-sh-safety-n { font-family: var(--sh-mono); font-size: 13px; font-weight: 500; color: var(--sh-rust); }

/* The work and the rhythm: On the pull's words beside the heading, Conan Doyle's account as a quote, then the jobs, each
   with its pull drawn as four beats (the pull a tall bar, the feet dots, the capstan a ring) and said in words. */
.cp-sh-work-sec { padding-top: clamp(64px, 9vw, 96px); }
.cp-sh-work-head { display: grid; grid-template-columns: minmax(0, 1fr); gap: 18px; }
.cp-sh-work-lead { max-width: 560px; font-size: 17px; line-height: 1.6; color: var(--sh-body); text-wrap: pretty; }
.cp-sh-quote { margin-top: 36px; padding: 26px 0; border-block: 1px solid var(--sh-rule); }
.cp-sh-quote p { max-width: 900px; font-family: var(--sh-serif); font-style: italic; font-size: clamp(22px, 2.6vw, 30px); line-height: 1.35; letter-spacing: -0.01em; color: var(--sh-ink); text-wrap: pretty; }
.cp-sh .s-cite { font-family: var(--font-sans); font-style: normal; font-size: 12px; font-weight: 700; line-height: 0; }
.cp-sh .s-cite a { padding: 0 2px; color: var(--sh-teal); text-decoration: none; }
.cp-sh-jobs { display: grid; grid-template-columns: minmax(0, 1fr); gap: 16px; margin-top: 36px; }
.cp-sh-job { display: flex; flex-direction: column; gap: 12px; padding: 24px; border: 1px solid var(--sh-edge); border-radius: 20px; background: var(--sh-card); }
.cp-sh-job-n { font-family: var(--sh-mono); font-size: 12px; color: var(--sh-label); }
.cp-sh-job h3 { font-size: 21px; font-weight: 700; letter-spacing: -0.015em; }
.cp-sh-mark { display: flex; align-items: center; gap: 12px; font-family: var(--sh-mono); font-size: 11.5px; line-height: 1.4; color: var(--sh-faint); }
.cp-sh-mark-art { display: flex; flex: none; align-items: flex-end; gap: 5px; width: 64px; height: 28px; }
.cp-sh-mark-art span { flex: 1; height: 8px; border-radius: 2px; background: var(--sh-line); }
.cp-sh-mark-joe .cp-sh-mark-art span:last-child { height: 28px; background: var(--sh-you); }
.cp-sh-mark-hoist .cp-sh-mark-art span { height: 22px; background: var(--sh-you); }
.cp-sh-mark-hoist .cp-sh-mark-art span:nth-child(2) { margin-right: 6px; }
.cp-sh-mark-stamp .cp-sh-mark-art { align-items: center; }
.cp-sh-mark-stamp .cp-sh-mark-art span { flex: none; width: 11px; height: 11px; border-radius: 99px; background: var(--sh-teal); }
.cp-sh-mark-capstan .cp-sh-mark-art { position: relative; justify-content: center; align-items: center; }
.cp-sh-mark-capstan .cp-sh-mark-art span { display: none; }
.cp-sh-mark-capstan .cp-sh-mark-art::before { content: ""; width: 26px; height: 26px; box-sizing: border-box; border: 2px dashed var(--sh-teal); border-radius: 99px; }
.cp-sh-job-what { font-size: 15px; line-height: 1.55; color: var(--sh-body); text-wrap: pretty; }
.cp-sh-job-fact { margin-top: auto; padding-top: 12px; border-top: 1px solid var(--sh-line); font-size: 14px; line-height: 1.55; color: var(--sh-muted); text-wrap: pretty; }

/* From the old books: a year down the left, what the books tell at right, on the band. */
.cp-sh-books { margin-top: clamp(64px, 9vw, 96px); padding-block: clamp(56px, 8vw, 88px); border-block: 1px solid var(--sh-edge); background: var(--sh-band); }
.cp-sh-years { margin-top: 36px; border-top: 1px solid var(--sh-rule); }
.cp-sh-years > li { display: grid; grid-template-columns: minmax(0, 1fr); gap: 8px 32px; padding: 22px 0; border-bottom: 1px solid var(--sh-line); }
.cp-sh-yr { font-family: var(--sh-serif); font-style: italic; font-size: 34px; line-height: 1; color: var(--sh-teal); }
.cp-sh-yr-facts { display: grid; gap: 14px; }
.cp-sh-yr-facts p { max-width: 720px; font-size: 16.5px; line-height: 1.6; color: var(--sh-body); text-wrap: pretty; }

/* Your first lesson: its cards beside the steps you sing, numbered. */
.cp-sh-first { padding-top: clamp(64px, 9vw, 96px); }
.cp-sh-first-grid { display: grid; grid-template-columns: minmax(0, 1fr); gap: 32px; margin-top: 36px; }
.cp-sh-cards { display: grid; gap: 12px; align-content: start; }
.cp-sh-cards li { display: grid; gap: 4px; padding: 18px 20px; border-radius: 16px; background: var(--sh-band); }
.cp-sh-cards b { font-size: 16px; font-weight: 700; }
.cp-sh-cards span { font-size: 14.5px; line-height: 1.5; color: var(--sh-muted); }
.cp-sh-steps { border-top: 1px solid var(--sh-rule); }
.cp-sh-steps li { display: grid; grid-template-columns: 44px minmax(0, 1fr); gap: 12px; align-items: baseline; padding: 20px 0; border-bottom: 1px solid var(--sh-line); }
.cp-sh-step-n { font-family: var(--sh-serif); font-style: italic; font-size: 28px; line-height: 1; color: var(--sh-teal); }
.cp-sh-steps p { font-size: 18px; line-height: 1.5; text-wrap: pretty; }
.cp-sh-first-more { margin-top: 24px; font-weight: 650; }
@media (min-width: 960px) { .cp-sh-first-grid { grid-template-columns: minmax(0, .8fr) minmax(0, 1.2fr); gap: 48px; } }
:root[data-skin="game"] body.s-arcade .cp-sh-step-n { font-family: var(--a-display); font-style: normal; font-size: 22px; font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade .cp-sh-cards li { border: 2px solid var(--sh-line); border-radius: 0; }

/* Questions beside their heading, then the Sources the notes point at. */
.cp-sh-fine { display: grid; grid-template-columns: minmax(0, 1fr); gap: 8px 48px; padding-top: clamp(64px, 9vw, 96px); }
.cp-sh-sources { padding-top: 56px; }
.cp-sh-sources ol { margin-top: 14px; padding-left: 22px; list-style: decimal; font-size: 14px; line-height: 1.55; color: var(--sh-muted); }
.cp-sh-sources li + li { margin-top: 6px; }
.cp-sh-sources a { text-decoration: underline; text-decoration-color: var(--sh-dash); }
.cp-sh-sources li:target { color: var(--sh-ink); font-weight: 600; }
@media (min-width: 700px) {
    .cp-sh-jobs { grid-template-columns: repeat(2, minmax(0, 1fr)); }
    .cp-sh-years > li { grid-template-columns: 120px minmax(0, 1fr); }
}
@media (min-width: 960px) {
    .cp-sh-work-head { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 48px; align-items: end; }
    .cp-sh-fine { grid-template-columns: minmax(0, 1fr) minmax(0, 2fr); align-items: start; }
    .cp-sh-fine .cp-faq { margin-top: 0; }
}
@media (min-width: 1100px) { .cp-sh-jobs { grid-template-columns: repeat(4, minmax(0, 1fr)); } }
:root[data-skin="game"] body.s-arcade .cp-sh :is(.cp-sh-job-n, .cp-sh-mark) { font-family: "Stackapella Pixel", ui-monospace, monospace; font-size: 9.5px; line-height: 1.7; font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade .cp-sh :is(.cp-sh-quote p, .cp-sh-yr) { font-family: inherit; font-style: normal; }
:root[data-skin="game"] body.s-arcade .cp-sh-yr { font-family: var(--a-display); font-size: 26px; font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade .cp-sh-job { border: 2px solid var(--sh-teal); border-radius: 0; box-shadow: 4px 4px 0 var(--sh-rust); }

/* Start here: the beginner course on the dark band in every look, its real screen beside it. */
.cp-sh > .s-ink { --s-ink-bg: var(--sh-night); --color-cream: var(--sh-night-ink); --color-ink: var(--sh-night); --color-raised: var(--sh-night-raised); --color-part-ink-2: var(--sh-sea-kick); --color-muted: var(--sh-night-body);
    margin-top: clamp(64px, 9vw, 96px); color: var(--sh-night-ink); }
.cp-sh > .s-ink .btn-primary { --primary: var(--sh-night-ink); --primary-ink: var(--sh-night); }
.cp-sh-more { padding-block: clamp(56px, 8vw, 88px) clamp(48px, 7vw, 72px); }
.cp-sh-more .s-chips { margin-top: 20px; }

@media (min-width: 600px) {
    .cp-sh-btns > * { flex: 0 0 auto; }
    .cp-sh-card { padding: 32px; border-radius: 28px; gap: 26px; }
    .cp-sh-lines p { grid-template-columns: 96px minmax(0, 1fr); gap: 16px; align-items: baseline; }
    .cp-sh-callline .cp-sh-sung { font-size: 24px; }
    .cp-sh-answerline .cp-sh-sung { font-size: 28px; }
    .cp-sh-units { grid-template-columns: repeat(2, minmax(0, 1fr)); }
    .cp-sh-unit { padding-right: 24px; }
    .cp-sh-sample { padding: 28px; }
    .cp-sh-songs b { font-size: 26px; }
    .cp-sh-safety li { font-size: 18px; }
}
@media (min-width: 900px) {
    .cp-sh-hero { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 56px; align-items: center; padding-top: 22px; }
    .cp-sh-lead { font-size: 19px; }
    .cp-sh-listen { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 48px; align-items: start; }
    .cp-sh-book { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 64px; }
    .cp-sh-book > div:last-child { position: sticky; top: 100px; align-self: start; }
}
@media (min-width: 1100px) {
    .cp-sh-units { grid-template-columns: repeat(4, minmax(0, 1fr)); }
}

/* The game skin: the arcade's Bungee headings and pixel labels, square frames with hard shadows, the same words. */
:root[data-skin="game"] body.s-arcade .cp-sh :is(.cp-sh-h1, .cp-sh-h2, .cp-sh-sample-n) { font-family: var(--a-display); font-weight: 400; letter-spacing: .01em; text-transform: uppercase; font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade .cp-sh :is(.cp-sh-h1 em, .cp-sh-h2 em) { font-family: inherit; font-style: normal; letter-spacing: inherit; }
:root[data-skin="game"] body.s-arcade .cp-sh-h1 { font-size: clamp(44px, 10vw, 68px); line-height: 1.02; }
:root[data-skin="game"] body.s-arcade .cp-sh-h2 { font-size: clamp(26px, 4vw, 40px); line-height: 1.08; max-width: 100%; overflow-wrap: anywhere; }
:root[data-skin="game"] body.s-arcade .cp-sh-sample-n { font-size: clamp(20px, 3vw, 26px); line-height: 1.2; }
:root[data-skin="game"] body.s-arcade .cp-sh :is(.cp-sh-kick, .cp-sh-meta, .cp-sh-card-top, .cp-sh-lane-labels, .cp-sh-who, .cp-sh-role, .cp-sh-unit-n, .cp-sh-score-h, .cp-sh-sample-top, .cp-sh-year, .cp-sh-safety-n, .cp-sh-start) { font-family: "Stackapella Pixel", ui-monospace, monospace; font-size: 9.5px; line-height: 1.7; letter-spacing: .06em; font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade .cp-sh :is(.cp-sh-card, .cp-sh-listen, .cp-sh-sample, .cp-sh-play, .cp-sh-open, .cp-sh-start, .cp-sh-sample-tag, .cp-sh-cell, .cp-sh-note) { border-radius: 0; }
:root[data-skin="game"] body.s-arcade .cp-sh :is(.cp-sh-card, .cp-sh-listen) { border: 2px solid #3be7ff; box-shadow: 6px 6px 0 #ff5fd2; }
:root[data-skin="game"] body.s-arcade .cp-sh-sample { border: 2px solid var(--sh-teal); box-shadow: 4px 4px 0 var(--sh-rust); }
:root[data-skin="game"] body.s-arcade .cp-sh-play { background: none; border: 2px solid var(--sh-ans-lit); color: var(--sh-ans-lit); font-family: "Stackapella Pixel", ui-monospace, monospace; font-size: 11px; box-shadow: 4px 4px 0 #ff5fd2; font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade .cp-sh-card .cp-sh-note-answer:is([data-on], [data-sung]) { filter: drop-shadow(0 0 6px var(--sh-ans-lit)); }
:root[data-skin="game"] body.s-arcade .cp-sh-songs b { font-family: inherit; font-style: normal; font-weight: 700; font-size: 20px; }
:root[data-skin="game"] body.s-arcade .cp-sh-lname b.cp-sh-song { font-family: inherit; font-style: normal; font-weight: 700; font-size: 15px; }
:root[data-skin="game"] body.s-arcade .cp-sh :is(.cp-sh-callline .cp-sh-sung, .cp-sh-sample-skin) { font-family: inherit; }

:root[data-skin="game"] body.s-arcade .cp-bl .cp-dk-demo { --pd-bg: #0d0818; --pd-edge: #3be7ff66; --pd-rose: #3be7ff; --pd-gold: #ffd84a; --pd-bar: #2b2240; --pd-staff: #221a36; border-radius: 0; border: 2px solid #3be7ff; box-shadow: 6px 6px 0 #ff5fd2; }
:root[data-skin="game"] body.s-arcade .cp-bl :is(.cp-dk-roll, .cp-bl-card, .cp-bl-slip, .cp-bl-step) { border-radius: 0; }
:root[data-skin="game"] body.s-arcade .cp-bl :is(.cp-bl-card, .cp-bl-slip) { border: 2px solid var(--a-line-2); box-shadow: 4px 4px 0 var(--arc-shadow-c, #05030d); }
:root[data-skin="game"] body.s-arcade .cp-bl .cp-bl-card-blue { border-color: #3be7ff; }
:root[data-skin="game"] body.s-arcade .cp-bl :is(.cp-dk-demo-h, .cp-bl-card-n, .cp-bl-slip-year, .cp-bl-step-n, .cp-bl-faq .cp-faq summary) { font-family: var(--a-display); font-weight: 400; letter-spacing: .01em; font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade .cp-bl .cp-dk-demo-h { text-transform: uppercase; }
:root[data-skin="game"] body.s-arcade .cp-bl :is(.cp-bl-slip-where, .cp-bl-step-kind) { font-family: var(--a-hud); font-weight: 400; font-size: 9px; letter-spacing: .06em; line-height: 1.6; font-size-adjust: var(--arc-ex, none); }
/* The free course (site/features/course): the course map. A winding road of eight stops in the parts'
   four colours (the last ringed for Plus), ending in the four stacked bars of a song you sang every
   part of; the lesson's three steps numbered in those colours; the four parts stacking up on the
   dark band. The /courses page lists it first as a wide card with the same four bars. Both skins. */
.cp-free { --cp-a: var(--color-accent); }
.cp-free .cp-hero { background: radial-gradient(70% 90% at 75% 45%, color-mix(in srgb, var(--color-part-1) 12%, var(--color-ink)), var(--color-ink) 75%); }
:root[data-skin="game"] body.s-arcade .cp-free .cp-hero { background: radial-gradient(70% 80% at 72% 45%, color-mix(in srgb, #ff5fd2 12%, var(--a-bg)), var(--a-bg)); }
.cp-fr-art { display: grid; place-items: center; }
.cp-fr-svg { width: min(100%, 540px); height: auto; overflow: visible; }
.cp-fr-road { fill: none; stroke: var(--color-cream); stroke-width: 4; stroke-dasharray: 2 12; stroke-linecap: round; stroke-linejoin: round; opacity: .35; }
.cp-fr-stop { fill: var(--c); stroke: var(--color-ink); stroke-width: 4; }
.cp-fr-bar { fill: var(--c); }
:root[data-skin="game"] body.s-arcade :is(.cp-fr-stop, .cp-fr-bar) { filter: drop-shadow(0 0 6px var(--c)); }
@media (prefers-reduced-motion: no-preference) {
    .cp-fr-road { animation: cp-fr-walk 3s linear infinite; }
    .cp-fr-bar { transform-box: fill-box; transform-origin: left center; animation: cp-fr-grow 7s ease-out infinite both; }
    .cp-fr-bar.s-v2 { animation-delay: .3s; } .cp-fr-bar.s-v3 { animation-delay: .6s; } .cp-fr-bar.s-v4 { animation-delay: .9s; }
}
@keyframes cp-fr-walk { to { stroke-dashoffset: -28; } }
@keyframes cp-fr-grow { 0% { transform: scaleX(0); } 12%, 100% { transform: none; } }
.cp-fr-steps { display: grid; grid-template-columns: minmax(0, 1fr); gap: 14px; margin-top: 24px; }
.cp-fr-steps li { display: grid; grid-template-columns: auto minmax(0, 1fr); gap: 14px; align-items: start; }
.cp-fr-step-n { display: grid; place-items: center; width: 34px; height: 34px; border-radius: 99px; font-weight: 800; background: var(--c); color: var(--ci); }
.cp-fr-steps p { font-size: 15.5px; line-height: 1.5; color: var(--color-muted); }
.cp-fr-steps p b { display: block; font-size: 17px; color: var(--color-cream); }
.cp-fr-shot { margin-top: 28px; max-width: 760px; }
.cp-fr-layers { width: 100%; max-width: 420px; height: auto; justify-self: center; }
.cp-fr-layers rect { fill: var(--c); }
@media (prefers-reduced-motion: no-preference) {
    .cp-fr-layer { animation: cp-fr-in 8s ease-out infinite both; }
    .cp-fr-layer-2 { animation-delay: .8s; } .cp-fr-layer-3 { animation-delay: 1.6s; } .cp-fr-layer-4 { animation-delay: 2.4s; }
}
@keyframes cp-fr-in { 0% { opacity: 0; } 8%, 100% { opacity: 1; } }
.s-freecourse { display: grid; grid-template-columns: auto minmax(0, 1fr); gap: 18px; align-items: center; margin-top: 16px; padding: 22px; }
.s-freecourse b { display: block; font-size: 19px; }
.s-freecourse > span:last-child > span { display: block; margin-top: 4px; color: var(--color-muted); font-size: 15px; line-height: 1.5; }
.s-freecourse-stack { display: grid; gap: 5px; width: 64px; }
.s-freecourse-stack b { height: 9px; border-radius: 9px; background: var(--c); }
.s-freecourse-stack b:nth-child(1) { width: 100%; } .s-freecourse-stack b:nth-child(2) { width: 72%; } .s-freecourse-stack b:nth-child(3) { width: 88%; } .s-freecourse-stack b:nth-child(4) { width: 60%; }
@media (min-width: 900px) {
    .cp-fr-steps { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 18px; }
}

/* The comparison pages (site/compare, site/compare-page): calm and even-handed. The same card for
   both products (ours only faintly tinted), a table whose rows read across on
   a wide screen and stack as labelled cells on a phone, each of their cells with small source
   numbers, and the sources at the foot. No logos, no product colours. */
.cmp-head .s-lede { max-width: 62ch; }
.cmp-asof { margin-top: 10px; font-size: 14px; font-weight: 650; color: var(--color-muted); }
.cmp-two { display: grid; grid-template-columns: minmax(0, 1fr); gap: 14px; margin-top: 18px; }
.cmp-card { padding: 22px; border-radius: 22px; background: var(--color-panel); border: 1px solid var(--color-line); }
.cmp-card.cmp-us { background: color-mix(in srgb, var(--color-accent) 5%, var(--color-panel)); }
.cmp-card h3 { font-size: 18px; font-weight: 750; }
.cmp-card .s-ticks { margin-top: 12px; font-size: 15.5px; }
.cmp-tablewrap { margin-top: 22px; }
.cmp-table { width: 100%; border-collapse: collapse; font-size: 15px; line-height: 1.45; }
.cmp-table thead th { text-align: start; font-size: 16px; font-weight: 750; padding: 0 14px 12px; }
.cmp-table tbody th { text-align: start; font-weight: 650; color: var(--color-cream); padding: 14px; vertical-align: top; }
.cmp-table td { padding: 14px; vertical-align: top; color: var(--color-muted); }
.cmp-table tbody tr { border-top: 1px solid var(--color-line); }
.cmp-table td.cmp-us { color: var(--color-cream); background: color-mix(in srgb, var(--color-accent) 6%, transparent); }
.cmp-src { display: inline-grid; place-items: center; min-width: 18px; height: 18px; margin-inline-start: 4px; padding: 0 4px; border-radius: 99px; font-size: 11px; font-weight: 700; vertical-align: 2px; text-decoration: none; color: var(--color-muted); border: 1px solid var(--color-line); }
.cmp-src:hover, .cmp-src:focus-visible { color: var(--color-cream); border-color: var(--color-cream); }
.cmp-note { margin-top: 14px; font-size: 14px; line-height: 1.5; color: var(--color-muted); max-width: 70ch; }
.cmp-sources ol { margin-top: 12px; padding-inline-start: 22px; list-style: decimal; font-size: 15px; line-height: 1.7; }
.cmp-sources a { overflow-wrap: anywhere; }
.cmp-hub b { display: block; }
/* The close: words, then Start singing as a cream pill on the dark band (the theme's dark pill vanished on it). */
.cmp-try { --primary: #F7F1E6; --primary-ink: #211A14; }
.cmp-try-in { display: grid; gap: 22px; }
.cmp-try .btn-lg { justify-self: start; white-space: nowrap; }
/* From 900 px a comparison uses the width (docs/design-rules.md, "A page about one thing uses the width"): the heading
   at left and the lead large at right; Moving over, the questions and the sources each a row, the heading at left. */
@media (min-width: 900px) {
    .cmp-top { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 56px; align-items: start; }
    .cmp-top .s-lede { margin-top: 0; padding-top: 4px; font-size: 20px; line-height: 1.5; max-width: 46ch; }
    .cmp-row { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 2fr); column-gap: 64px; align-items: start; }
    .cmp-row > h2 { grid-column: 1; grid-row: 1 / span 6; }
    .cmp-row > :not(h2) { grid-column: 2; }
    .cmp-row > h2 + * { margin-top: 0; }
    .cmp-sources ol { columns: 2; column-gap: 40px; }
    .cmp-try-in { grid-template-columns: minmax(0, 1fr) auto; align-items: center; column-gap: 48px; }
    .cmp-try .btn-lg { justify-self: end; }
}
@media (max-width: 759px) {
    .cmp-table thead { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); }
    .cmp-table, .cmp-table tbody, .cmp-table tr, .cmp-table th, .cmp-table td { display: block; }
    .cmp-table tbody tr { padding: 14px 0; }
    .cmp-table tbody th { padding: 0 0 8px; }
    .cmp-table td { padding: 8px 12px; border-radius: 12px; }
    .cmp-table td::before { content: attr(data-col); display: block; font-size: 12px; font-weight: 700; letter-spacing: .04em; text-transform: uppercase; color: var(--color-muted); margin-bottom: 2px; }
}
@media (min-width: 760px) {
    .cmp-two { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 18px; }
    .cmp-table tbody th { width: 26%; }
}

/* The integrations (site/integrations, site/integration): Event Schedule's own page's one rule, kept on ours: what
   works today is solid (a framed panel, a green Works today tag), and what the connection will do is dashed on a
   dotted ground, under a dashed Coming tag. A visitor who reads nothing still sees which is which. The two apps
   share one panel, side by side from 900 px. Game mode squares every frame and gives the solid ones the arcade's
   hard shadow; the dashed ones keep their dashes. */
.int .s-actions { margin-top: 26px; }
.int-h2 { font-size: clamp(26px, 3.2vw, 34px); font-weight: 800; letter-spacing: -0.02em; line-height: 1.15; }
.int-sub { margin-top: 8px; font-size: 16.5px; line-height: 1.5; color: var(--color-muted); max-width: 62ch; }
.int-legend { display: flex; flex-wrap: wrap; gap: 10px 24px; margin-top: 16px; font-size: 14px; color: var(--color-muted); }
.int-legend li { display: inline-flex; align-items: center; gap: 10px; }
.int-legend li::before { content: ""; flex: none; width: 30px; height: 16px; border-radius: 6px; }
.int-key-today::before { background: var(--color-panel); border: 1.5px solid color-mix(in srgb, var(--color-cream) 45%, transparent); }
.int-key-coming::before { border: 1.5px dashed color-mix(in srgb, var(--color-cream) 45%, transparent); }
.int-tag { display: inline-flex; align-items: center; padding: 3px 10px; border-radius: 99px; font-size: 11.5px; font-weight: 800; letter-spacing: .06em; text-transform: uppercase; line-height: 1.4; }
.int-tag-today { color: #fff; background: #1d7a43; }
.int-tag-coming { color: var(--color-cream); border: 1.5px dashed color-mix(in srgb, var(--color-cream) 50%, transparent); }
.int-duet { display: grid; grid-template-columns: minmax(0, 1fr); margin-top: 22px; border-radius: 22px; background: var(--color-panel); border: 1px solid var(--color-line); overflow: hidden; }
.int-half { padding: 24px 22px; }
.int-half + .int-half { border-top: 1px solid var(--color-line); }
.int-us { background: color-mix(in srgb, var(--color-accent) 5%, var(--color-panel)); }
.int-half h3 { margin-top: 12px; font-size: 19px; font-weight: 800; }
.int-half .s-ticks { margin-top: 14px; font-size: 15.5px; }
.int-note { margin-top: 16px; font-size: 14px; line-height: 1.5; color: var(--color-muted); max-width: 70ch; }
.int-steps { display: grid; gap: 12px; margin-top: 18px; padding-inline-start: 1.4em; list-style: decimal; font-size: 17px; line-height: 1.5; max-width: 62ch; }
.int-steps li { padding-inline-start: 4px; }
.int-steps li::marker { font-weight: 800; color: var(--color-part-ink-2); }
.int-aside { max-width: 780px; padding: 24px 22px; border-radius: 22px; background: var(--color-panel); border: 1px solid var(--color-line); }
.int-aside h2 { margin-top: 12px; font-size: 21px; font-weight: 800; }
.int-aside p:not(.int-tag) { margin-top: 8px; font-size: 16px; line-height: 1.55; color: var(--color-muted); }
.int-aside .s-lk { display: inline-block; margin-top: 14px; text-wrap: balance; }
/* Inline, so when the link wraps ("Event Schedule and Stackapella" at 320, and to 390 in game mode's wider font) its arrow
   follows the last word instead of the link growing to the panel's width with the arrow at its far edge. */
.int-aside .s-lk svg { display: inline; vertical-align: -2px; margin-inline-start: 2px; }
.int-coming { padding: 28px 22px; border-radius: 22px; border: 1.5px dashed color-mix(in srgb, var(--color-cream) 35%, transparent); background-image: radial-gradient(color-mix(in srgb, var(--color-cream) 10%, transparent) 1.1px, transparent 1.4px); background-size: 18px 18px; }
.int-coming .int-h2 { margin-top: 14px; }
.int-who { margin-top: 26px; font-size: 13px; font-weight: 800; letter-spacing: .08em; text-transform: uppercase; color: var(--color-muted); }
.int-cards { display: grid; gap: 12px; margin-top: 12px; }
.int-cards li { padding: 18px; border-radius: 16px; border: 1.5px dashed color-mix(in srgb, var(--color-cream) 30%, transparent); background: color-mix(in srgb, var(--color-ink) 70%, transparent); }
.int-cards b { display: block; font-size: 16.5px; font-weight: 750; }
.int-cards span { display: block; margin-top: 6px; font-size: 15px; line-height: 1.5; color: var(--color-muted); }
.int-coming .int-note { margin-top: 22px; }
.int-hub { display: grid; gap: 16px; }
.int-hub-one { margin-top: 14px; max-width: 620px; }
.int-hubcard { display: flex; flex-direction: column; align-items: flex-start; gap: 8px; height: 100%; padding: 26px 24px; border-radius: 22px; background: var(--color-panel); border: 1px solid var(--color-line); color: inherit; text-decoration: none; transition: border-color .2s ease; }
.int-hubcard:hover, .int-hubcard:focus-visible { border-color: color-mix(in srgb, var(--color-cream) 50%, transparent); }
.int-hub-for { font-size: 12.5px; font-weight: 800; letter-spacing: .08em; text-transform: uppercase; color: var(--color-part-ink-2); }
.int-hubcard b { font-size: 24px; font-weight: 800; }
.int-hub-say { font-size: 16px; line-height: 1.5; color: var(--color-muted); }
.int-hub-status { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 4px; }
.int-hub-go { display: inline-flex; align-items: center; gap: 6px; margin-top: auto; padding-top: 10px; font-weight: 750; }
.int-hubcard:hover .int-hub-go, .int-hubcard:focus-visible .int-hub-go { text-decoration: underline; }
.int-maker { margin-top: 22px; font-size: 15px; line-height: 1.5; color: var(--color-muted); }
@media (max-width: 559px) {
    .int .s-actions > a { flex: 1 1 100%; justify-content: center; }
}
@media (min-width: 760px) {
    .int-cards { grid-template-columns: repeat(auto-fit, minmax(230px, 1fr)); }
    .int-coming { padding: 34px 32px; }
}
@media (min-width: 900px) {
    .int-duet { grid-template-columns: repeat(2, minmax(0, 1fr)); }
    .int-half { padding: 28px; }
    .int-half + .int-half { border-top: 0; border-inline-start: 1px solid var(--color-line); }
    .int-hub { grid-template-columns: repeat(2, minmax(0, 1fr)); }
    .int-hub-one { grid-template-columns: minmax(0, 1fr); }
}
:root[data-skin="game"] body.s-arcade .int :is(.int-duet, .int-aside, .int-hubcard) { border-radius: 0; background: var(--a-panel); border: 2px solid var(--a-line-2); box-shadow: 4px 4px 0 var(--arc-shadow-c, #05030d); }
:root[data-skin="game"] body.s-arcade .int .int-us { background: color-mix(in srgb, var(--color-accent) 8%, var(--a-panel)); }
:root[data-skin="game"] body.s-arcade .int :is(.int-coming, .int-cards li, .int-tag) { border-radius: 0; }
:root[data-skin="game"] body.s-arcade .int .int-coming { border-width: 2px; }
:root[data-skin="game"] body.s-arcade .int .int-tag { font: 400 9.5px/1.4 var(--a-hud); letter-spacing: .06em; padding: 5px 8px; }
:root[data-skin="game"] body.s-arcade .int .int-legend li::before { border-radius: 0; }
/* The pixel face set tight, as the arcade's other headings are: at 1.5 a wrapped panel heading read as two. */
:root[data-skin="game"] body.s-arcade .int :is(.int-half h3, .int-aside h2) { line-height: 1.25; }

/* Classical singing basics (site/courses/classical-singing-basics): sheet music, after Hillel's design (2026-11-18). The
   site's own warm ground and type, a system serif for the music's Italian (no new face), and the parts' four colours
   (.s-v1 to .s-v4: --c to draw with, --ci for words) marking the four units, so every theme and both skins keep them. The
   hero's card is lesson 1's phrase engraved (js/public/classical-singing-basics.js) with a sample voice line tracing it
   once; the units as four movements, each over its own slur; the score markings on a tinted band beside what isn't
   scored; the songs as a programme beside singing safely. Game skin: the arcade's type and square framed panels. */
.cp-cl { --cl-serif: ui-serif, "Iowan Old Style", "Palatino Linotype", Palatino, Georgia, serif; --cl-label: var(--s-hl-em); --cl-rule: var(--k-line-strong);
    --cl-body: color-mix(in srgb, var(--color-cream) 82%, var(--color-ink)); --cl-band: color-mix(in srgb, var(--color-raised) 55%, var(--color-ink)); --cl-paper: var(--color-panel); }
:root:not([data-theme$="-light"]) .cp-cl { --cl-band: color-mix(in srgb, var(--color-panel) 70%, var(--color-ink)); }
.cp-cl-kick { font-size: var(--k-eyebrow); font-weight: 700; letter-spacing: .16em; text-transform: uppercase; color: var(--cl-label); }
.cp-cl-title { margin-top: 12px; font-size: var(--k-h2); line-height: 1.06; font-weight: 800; letter-spacing: -0.03em; text-wrap: balance; max-width: 22ch; }
.cp-cl-body { margin-top: 16px; max-width: 46ch; font-size: 17px; line-height: 1.6; color: var(--cl-body); text-wrap: pretty; }
.cp-cl-sec { padding-top: var(--k-sec); }
.cp-cl :is(a, button):focus-visible { outline: 3px solid var(--cl-label); outline-offset: 3px; }

/* The hero: the words, then the card; side by side from 900 px. */
.cp-cl-hero { display: grid; grid-template-columns: minmax(0, 1fr); gap: var(--k-hero-gap); align-items: center; padding-top: var(--k-hero-top); }
@media (min-width: 900px) { .cp-cl-hero { grid-template-columns: minmax(0, 1.04fr) minmax(0, 1fr); } }
.cp-cl-pills { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 14px; margin-top: 14px; }
.cp-cl-pills .s-soonpill { margin: 0; }
.cp-cl-mood { font-family: var(--cl-serif); font-style: italic; font-size: 20px; line-height: 1.3; color: var(--cl-label); }
.cp-cl-hero h1 { margin-top: 18px; font-size: clamp(44px, 6.2vw, 84px); line-height: .98; font-weight: 800; letter-spacing: -0.035em; text-wrap: balance; }
.cp-cl-swash { position: relative; display: inline-block; }
.cp-cl-swash svg { position: absolute; inset: auto 0 -0.24em; width: 100%; height: .26em; overflow: visible; }
.cp-cl-swash path { fill: none; stroke: var(--s-hl-em); stroke-width: 3.5; stroke-linecap: round; vector-effect: non-scaling-stroke; }
.cp-cl-hero .s-lede { margin-top: 30px; max-width: 34em; }
.cp-cl-actions { display: flex; flex-wrap: wrap; align-items: center; gap: 12px; margin-top: 30px; }
.cp-cl-actions .btn-lg { white-space: nowrap; }
.cp-cl-actions-note { font-size: 14px; color: var(--color-muted); }
@media (max-width: 639px) {
    .cp-cl-actions { flex-direction: column; align-items: stretch; }
    .cp-cl-actions .btn-lg { justify-content: center; width: 100%; }
    .cp-cl-actions-note { text-align: center; }
}

/* The card: lesson 1's phrase on its paper, the legend, and what the app says after a take. */
.cp-cl-card { margin: 0; padding: clamp(18px, 3vw, 28px) clamp(16px, 3vw, 28px) clamp(18px, 2.4vw, 24px); border-radius: var(--k-r-feature); background: var(--cl-paper); border: 1px solid var(--k-line); box-shadow: var(--k-sh-feature), var(--k-hi); }
.cp-cl-card-head { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 4px 12px; font-size: 12px; font-weight: 700; letter-spacing: .14em; text-transform: uppercase; color: var(--cl-label); }
.cp-cl-card-head span + span { letter-spacing: .06em; color: var(--color-muted); }
.cp-cl-score { aspect-ratio: 520 / 143; margin-top: 18px; color: var(--color-cream); }
@media (max-width: 479px) { .cp-cl-score { aspect-ratio: 400 / 143; } }
.cp-cl-score svg { display: block; width: 100%; height: auto; overflow: visible; }
.cp-cl-trace, .cp-cl-trace-halo { fill: none; stroke-linecap: round; stroke-linejoin: round; }
.cp-cl-trace { stroke: var(--color-part-3); stroke-width: 2.6; }
.cp-cl-trace-halo { stroke: color-mix(in srgb, var(--color-part-3) 22%, transparent); stroke-width: 11; }
@media (prefers-reduced-motion: no-preference) {
    .cp-cl-score[data-drawn] :is(.cp-cl-trace, .cp-cl-trace-halo) { stroke-dasharray: 1; animation: cp-cl-trace 3.4s var(--k-ease) .5s both; }
}
@keyframes cp-cl-trace { from { stroke-dashoffset: 1; } to { stroke-dashoffset: 0; } }
.cp-cl-slur { fill: none; stroke: var(--color-part-1); stroke-width: 2; stroke-linecap: round; }
.cp-cl-legato { font: italic 400 17px/1 var(--cl-serif); fill: currentColor; }
.cp-cl-legend { display: flex; flex-wrap: wrap; gap: 8px 22px; margin-top: 4px; font-size: 13.5px; color: var(--color-muted); }
.cp-cl-legend li { display: inline-flex; align-items: center; gap: 8px; }
.cp-cl-legend i { flex: none; width: 20px; height: 3px; border-radius: 3px; font-style: normal; }
.cp-cl-key-line { background: var(--color-part-3); }
.cp-cl-key-slur { background: var(--color-part-1); }
.cp-cl .cp-cl-key-breath { width: auto; height: auto; font: 700 20px/0.6 var(--cl-serif); color: var(--color-cream); }
.cp-cl-take { display: grid; grid-template-columns: auto minmax(0, 1fr); gap: 4px 16px; align-items: baseline; margin-top: 18px; padding-top: 16px; border-top: 1px solid var(--k-line); }
.cp-cl-take-kick { font-size: 11.5px; font-weight: 700; letter-spacing: .14em; text-transform: uppercase; color: var(--color-part-ink-3); white-space: nowrap; }
.cp-cl-take p:last-child { font-size: 15.5px; line-height: 1.55; color: var(--cl-body); }
.cp-cl-take b { color: var(--color-cream); }
@media (max-width: 479px) { .cp-cl-take { grid-template-columns: minmax(0, 1fr); } }

/* The units as four movements: a slur each over a short staff, its numeral and Italian name in its colour. One column on
   a phone, two on a tablet, four from 1024 px. */
.cp-cl-head { display: flex; flex-wrap: wrap; align-items: flex-end; justify-content: space-between; gap: 10px 24px; }
.cp-cl-count { font-size: 14.5px; color: var(--color-muted); }
.cp-cl-units { display: grid; grid-template-columns: minmax(0, 1fr); gap: 40px 28px; margin-top: clamp(32px, 4vw, 52px); }
@media (min-width: 640px) { .cp-cl-units { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (min-width: 1024px) { .cp-cl-units { grid-template-columns: repeat(4, minmax(0, 1fr)); } }
.cp-cl-staff { display: block; width: 100%; height: 46px; overflow: visible; }
.cp-cl-staff-line { stroke: var(--cl-rule); stroke-width: 1; vector-effect: non-scaling-stroke; }
.cp-cl-staff-slur { fill: none; stroke: var(--c); stroke-width: 2.5; stroke-linecap: round; vector-effect: non-scaling-stroke; }
.cp-cl-staff-bar { stroke: var(--color-cream); stroke-width: 1.2; vector-effect: non-scaling-stroke; }
.cp-cl-staff-end { stroke: var(--color-cream); stroke-width: 3.5; vector-effect: non-scaling-stroke; }
.cp-cl-staff-breath { font: 700 22px/1 var(--cl-serif); fill: var(--color-cream); }
.cp-cl-unit-n { display: flex; align-items: baseline; gap: 10px; margin-top: 16px; color: var(--ci); }
.cp-cl-roman { font: 400 38px/1 var(--cl-serif); }
.cp-cl-italian { font: italic 400 24px/1.1 var(--cl-serif); }
.cp-cl-unit h3 { margin-top: 12px; font-size: 21px; line-height: 1.2; font-weight: 750; letter-spacing: -0.01em; }
.cp-cl-unit-line { margin-top: 10px; font-size: 15px; line-height: 1.55; color: var(--cl-body); text-wrap: pretty; }
.cp-cl-lessons { display: grid; gap: 4px; margin-top: 16px; padding-top: 14px; border-top: 1px solid var(--k-line); font-size: 15px; }
.cp-cl-lessons li { display: flex; flex-wrap: wrap; align-items: baseline; gap: 4px 12px; padding-block: 3px; }
.cp-cl-lesson-n { width: 12px; flex: none; color: var(--ci); font-variant-numeric: tabular-nums; }
.cp-cl-first { font-weight: 700; }
.cp-cl-start { padding: 3px 10px; border-radius: 99px; background: var(--color-good); color: var(--color-ink); font-size: 11px; font-weight: 800; letter-spacing: .1em; text-transform: uppercase; white-space: nowrap; }

/* What the app listens for, on a tinted band: the heading and what isn't scored, beside the markings as a ruled list. */
.cp-cl-band { margin-top: var(--k-sec); padding-block: var(--k-sec); background: var(--cl-band); border-block: 1px solid var(--k-line); }
.cp-cl-hears { display: grid; grid-template-columns: minmax(0, 1fr); gap: 40px clamp(32px, 5vw, 64px); align-items: start; }
@media (min-width: 900px) { .cp-cl-hears { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); } }
.cp-cl-unscored { margin-top: 28px; padding: 20px 22px 22px; border-radius: 16px; border: 1.5px dashed var(--cl-rule); }
.cp-cl-unscored-kick { font-size: 12px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; color: var(--color-muted); }
.cp-cl-unscored ul { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 14px; }
.cp-cl-unscored li { padding: 7px 14px; border-radius: 99px; background: var(--cl-paper); font-size: 14px; white-space: nowrap; }
.cp-cl-marks > div { display: grid; grid-template-columns: minmax(0, 1fr); gap: 4px 24px; align-items: baseline; padding-block: 16px; border-bottom: 1px solid var(--k-line); }
.cp-cl-marks > div:first-child { padding-top: 0; }
@media (min-width: 480px) { .cp-cl-marks > div { grid-template-columns: 9.5em minmax(0, 1fr); } }
.cp-cl-marks dt { font: italic 400 25px/1.15 var(--cl-serif); color: var(--ci); }
.cp-cl-marks dd { font-size: 15.5px; line-height: 1.55; }

/* The songs as a concert programme, beside singing safely. */
.cp-cl-concert { display: grid; grid-template-columns: minmax(0, 1fr); gap: 48px clamp(32px, 4vw, 48px); align-items: start; }
@media (min-width: 900px) { .cp-cl-concert { grid-template-columns: minmax(0, 1.7fr) minmax(0, 1fr); } }
.cp-cl-programme { padding: clamp(24px, 4vw, 48px); border-radius: var(--k-r-feature); background: var(--cl-paper); border: 1px solid var(--k-line); text-align: center; }
.cp-cl-programme-h { margin-top: 8px; font: 400 clamp(32px, 4vw, 42px)/1.1 var(--cl-serif); letter-spacing: -0.01em; }
.cp-cl-programme-note { margin-top: 6px; font-size: 14px; color: var(--color-muted); }
.cp-cl-pieces { margin-top: 26px; text-align: start; }
.cp-cl-pieces li { padding-block: 20px; border-top: 1px solid var(--k-line); }
.cp-cl-pieces li:last-child { padding-bottom: 0; }
.cp-cl-piece { font-family: var(--cl-serif); line-height: 1.25; }
.cp-cl-piece b { font-style: italic; font-weight: 400; font-size: clamp(24px, 3vw, 28px); }
.cp-cl-piece span { font-size: 18px; color: var(--color-muted); }
.cp-cl-credit { margin-top: 6px; font-size: 15px; line-height: 1.55; color: var(--cl-body); }
.cp-cl-safety { padding-top: 12px; }
.cp-cl-motto { margin-top: 10px; font: italic 400 30px/1.15 var(--cl-serif); }
.cp-cl-safety ul { display: grid; gap: 14px; margin-top: 20px; }
.cp-cl-safety li { display: flex; gap: 12px; font-size: 16px; line-height: 1.55; }
.cp-cl-safety li svg { flex: none; margin-top: 3px; color: var(--color-part-ink-1); }

/* Lesson 1's first round (the length pass, 2026-11-18): the words and the steps to sing beside the round on its paper,
   two takes to hear and the choice under them; side by side from 900 px. */
.cp-cl-try { display: grid; grid-template-columns: minmax(0, 1fr); gap: 40px clamp(32px, 5vw, 64px); align-items: start; }
@media (min-width: 900px) { .cp-cl-try { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); } }
.cp-cl-steps-kick { margin-top: 28px; font-size: 12px; font-weight: 700; letter-spacing: .14em; text-transform: uppercase; color: var(--color-muted); }
.cp-cl-steps { display: grid; gap: 10px; margin-top: 12px; }
.cp-cl-steps li { display: flex; align-items: baseline; gap: 14px; font-size: 16px; line-height: 1.55; }
.cp-cl-step-n { flex: none; width: 18px; font: italic 400 24px/1 var(--cl-serif); color: var(--color-part-ink-1); }
.cp-cl-try-after { margin-top: 16px; max-width: 46ch; font-size: 15px; line-height: 1.55; color: var(--color-muted); }
.cp-cl-round { padding: clamp(20px, 3vw, 28px); border-radius: var(--k-r-feature); background: var(--cl-paper); border: 1px solid var(--k-line); box-shadow: var(--k-sh-feature), var(--k-hi); }
.cp-cl-prompt { margin-top: 14px; font: italic 400 clamp(26px, 3vw, 32px)/1.15 var(--cl-serif); }
.cp-cl-takes { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 14px; margin-top: 20px; }
.cp-cl-hear { display: grid; gap: 6px; justify-items: start; min-height: 44px; padding: 16px 18px 14px; border-radius: 16px; border: 1px solid var(--k-line); background: var(--cl-band); color: var(--color-cream); text-align: start; cursor: pointer; }
.cp-cl-hear:hover { border-color: var(--cl-rule); }
.cp-cl-hear[aria-pressed="true"] { box-shadow: 0 0 0 2px var(--color-cream); }
.cp-cl-hear-n { font: italic 400 44px/1 var(--cl-serif); color: var(--color-part-ink-3); }
.cp-cl-hear-label { font-size: 15px; font-weight: 700; white-space: nowrap; }
.cp-cl-hear-bar { display: block; width: 100%; height: 3px; margin-top: 6px; border-radius: 3px; background: var(--k-line); overflow: hidden; }
.cp-cl-hear-bar i { display: block; width: 0; height: 100%; background: var(--color-part-3); }
.cp-cl-hear[data-playing] .cp-cl-hear-bar i { width: 100%; }
@media (prefers-reduced-motion: no-preference) {
    .cp-cl-hear[data-playing] .cp-cl-hear-bar i { animation: cp-cl-take var(--take, 4s) linear both; }
}
@keyframes cp-cl-take { from { width: 0; } to { width: 100%; } }
.cp-cl-picks { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 16px; }
.cp-cl-pick { display: inline-flex; align-items: center; gap: 8px; min-height: 44px; padding: 10px 18px; border-radius: 99px; background: color-mix(in srgb, var(--color-part-1) 16%, var(--cl-paper)); color: var(--color-cream); font-size: 15px; font-weight: 700; white-space: nowrap; cursor: pointer; }
.cp-cl-pick:disabled { cursor: default; opacity: .55; }
.cp-cl-pick[data-mark] { opacity: 1; }
.cp-cl-pick[data-mark="right"]::before { content: "\2713"; color: var(--color-good); font-weight: 800; }
.cp-cl-pick[data-mark="wrong"]::before { content: "\2715"; color: var(--color-bad); font-weight: 800; }
.cp-cl-say { min-height: 3.1em; margin-top: 16px; font-size: 15.5px; line-height: 1.55; color: var(--cl-body); }
.cp-cl-next-row { margin-top: 12px; }
.cp-cl-next-row .btn-secondary { white-space: nowrap; }

/* Performance practice: the old books' rules, two to a row from 760 px, each under its source in its movement's colour. */
.cp-cl-rules { display: grid; grid-template-columns: minmax(0, 1fr); gap: 0 clamp(32px, 5vw, 64px); margin-top: clamp(24px, 3vw, 36px); }
@media (min-width: 760px) { .cp-cl-rules { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
.cp-cl-rule { padding-block: 22px; border-top: 1px solid var(--k-line); }
.cp-cl-rule-from { font: italic 400 18px/1.3 var(--cl-serif); color: var(--ci); }
.cp-cl-rule h3 { margin-top: 6px; font-size: 21px; line-height: 1.2; font-weight: 750; letter-spacing: -0.01em; }
.cp-cl-rule p:last-child { margin-top: 8px; font-size: 15.5px; line-height: 1.6; color: var(--cl-body); text-wrap: pretty; }

/* Programme notes: dated, two to a row from 900 px, each year set in the music's serif. */
.cp-cl-notes { display: grid; grid-template-columns: minmax(0, 1fr); gap: 0 clamp(32px, 5vw, 64px); margin-top: clamp(24px, 3vw, 36px); }
@media (min-width: 900px) { .cp-cl-notes { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
.cp-cl-notes li { display: grid; grid-template-columns: 5.2em minmax(0, 1fr); gap: 4px 18px; padding-block: 22px; border-top: 1px solid var(--k-line); }
.cp-cl-year { font: 400 28px/1.05 var(--cl-serif); font-variant-numeric: oldstyle-nums; color: var(--cl-label); }
.cp-cl-notes h3 { font-size: 19px; line-height: 1.25; font-weight: 750; }
.cp-cl-notes p:last-child { margin-top: 6px; font-size: 15.5px; line-height: 1.6; color: var(--cl-body); text-wrap: pretty; }
@media (max-width: 479px) { .cp-cl-notes li { grid-template-columns: minmax(0, 1fr); } }

/* Who it's for beside what you need; the questions beside their heading. */
.cp-cl-who { display: grid; grid-template-columns: minmax(0, 1fr); gap: 36px clamp(32px, 5vw, 64px); }
@media (min-width: 900px) { .cp-cl-who { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
.cp-cl-ticks { display: grid; gap: 12px; margin-top: 16px; }
.cp-cl-ticks li { display: flex; gap: 12px; font-size: 16px; line-height: 1.55; }
.cp-cl-ticks li svg { flex: none; margin-top: 3px; color: var(--color-part-ink-2); }
.cp-cl-faqsec { display: grid; grid-template-columns: minmax(0, 1fr); gap: 28px clamp(32px, 5vw, 64px); align-items: start; }
@media (min-width: 900px) { .cp-cl-faqsec { grid-template-columns: minmax(0, .8fr) minmax(0, 1.6fr); } }

/* Da capo: back to the start, centred under a short staff that ends on its final bar; then the group's other courses. */
.cp-cl-close { text-align: center; }
.cp-cl-close-staff { display: block; width: min(360px, 80%); height: 46px; margin-inline: auto; overflow: visible; }
.cp-cl-close .cp-cl-staff-slur { stroke: var(--color-part-1); }
.cp-cl-dc { margin-top: 18px; font: italic 400 34px/1.1 var(--cl-serif); color: var(--cl-label); }
.cp-cl-close .cp-cl-title { margin-inline: auto; }
.cp-cl-close .cp-cl-body { margin-inline: auto; }
.cp-cl-close .cp-cl-actions { justify-content: center; }
.cp-cl-close .cp-cl-actions-note { margin-top: 12px; }
.cp-cl-more-h { margin-top: 44px; }
.cp-cl-more { justify-content: center; margin-top: 14px; }

/* The sources, numbered as the notes point at them: two columns from 900 px. */
.cp-cl-sources { padding-block: var(--k-sec) 8px; }
.cp-cl-sources ol { margin-top: 16px; padding-inline-start: 1.6em; list-style: decimal; font-size: 14px; line-height: 1.55; color: var(--color-muted); }
@media (min-width: 900px) { .cp-cl-sources ol { columns: 2; column-gap: 48px; } }
.cp-cl-sources li { margin-bottom: 8px; break-inside: avoid; scroll-margin-top: 96px; }
.cp-cl-sources a { color: inherit; text-decoration: underline; text-underline-offset: 3px; }
/* The shared dark band ("Start here", site/_course-today) is dark in calm light too: its button light on it, never dark on
   dark (the shared hooks, 2026-11-18). */
:root:not([data-skin="game"]) .cp-cl .s-ink .btn-primary { --primary: #f7f1e6; --primary-ink: #211b17; }


/* Every lesson, to read (the shared site/courses/_lesson-pages, after this page's <main>): on this page each unit a column
   from 1024 px under a rule in its movement's colour, its lessons as ruled rows rather than cards (calm). */
.cp-cl ~ [data-lesson-pages] h3 { padding-bottom: 10px; border-bottom: 2px solid var(--color-part-1); }
.cp-cl ~ [data-lesson-pages] h3:nth-of-type(4n + 2) { border-color: var(--color-part-2); }
.cp-cl ~ [data-lesson-pages] h3:nth-of-type(4n + 3) { border-color: var(--color-part-3); }
.cp-cl ~ [data-lesson-pages] h3:nth-of-type(4n + 4) { border-color: var(--color-part-4); }
.cp-cl ~ [data-lesson-pages] .s-cards { grid-template-columns: minmax(0, 1fr); gap: 0; margin-top: 4px; }
:root:not([data-skin="game"]) .cp-cl ~ [data-lesson-pages] .s-card { gap: 2px; padding: 12px 0; border: 0; border-bottom: 1px solid var(--k-line); border-radius: 0; background: none; }
:root:not([data-skin="game"]) .cp-cl ~ [data-lesson-pages] .s-card:hover b { text-decoration: underline; text-underline-offset: 4px; }
.cp-cl ~ [data-lesson-pages] .s-card b { font-size: 16px; }
.cp-cl ~ [data-lesson-pages] .s-card span:not(.s-soon) { font-size: 14px; }
@media (min-width: 1024px) {
    .cp-cl ~ [data-lesson-pages] { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); grid-template-rows: auto auto auto; grid-auto-flow: column; column-gap: 28px; align-items: start; }
    .cp-cl ~ [data-lesson-pages] > h2 { grid-column: 1 / -1; grid-row: 1; }
}

/* The game skin: the arcade's type on the labels and headings (the music's Italian in the HUD face), square framed panels. */
:root[data-skin="game"] body.s-arcade .cp-cl :is(.cp-cl-kick, .cp-cl-card-head, .cp-cl-take-kick, .cp-cl-unscored-kick, .cp-cl-start, .cp-cl-steps-kick) { font-family: var(--a-hud); font-size: 9.5px; font-weight: 400; letter-spacing: .08em; line-height: 1.6; font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade .cp-cl :is(.cp-cl-hero h1, .cp-cl-title, .cp-cl-programme-h) { font-family: var(--a-display); font-weight: 400; letter-spacing: .01em; text-transform: uppercase; line-height: 1.1; font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade .cp-cl .cp-cl-hero h1 { font-size: clamp(30px, 5vw, 56px); }
:root[data-skin="game"] body.s-arcade .cp-cl :is(.cp-cl-title, .cp-cl-programme-h) { font-size: clamp(22px, 3.2vw, 34px); }
:root[data-skin="game"] body.s-arcade .cp-cl :is(.cp-cl-mood, .cp-cl-roman, .cp-cl-italian, .cp-cl-marks dt, .cp-cl-motto, .cp-cl-piece b, .cp-cl-prompt, .cp-cl-rule-from, .cp-cl-year, .cp-cl-dc, .cp-cl-step-n, .cp-cl-hear-n) { font-family: var(--a-hud); font-style: normal; font-size: 14px; line-height: 1.5; font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade .cp-cl .cp-cl-roman { font-size: 20px; }
:root[data-skin="game"] body.s-arcade .cp-cl .cp-cl-piece span { font-family: inherit; font-size: 15px; }
:root[data-skin="game"] body.s-arcade .cp-cl .cp-cl-swash svg { display: none; }
:root[data-skin="game"] body.s-arcade .cp-cl .cp-cl-swash { color: var(--color-part-ink-2); }
:root[data-skin="game"] body.s-arcade .cp-cl :is(.cp-cl-card, .cp-cl-programme, .cp-cl-unscored, .cp-cl-unscored li, .cp-cl-start, .cp-cl-round, .cp-cl-hear, .cp-cl-pick, .cp-cl-hear-bar) { border-radius: 0; }
:root[data-skin="game"] body.s-arcade .cp-cl .cp-cl-hear-n { font-size: 22px; }
:root[data-skin="game"] body.s-arcade .cp-cl :is(.cp-cl-card, .cp-cl-programme, .cp-cl-round) { background: var(--a-panel); border: 2px solid var(--a-line-2); box-shadow: 4px 4px 0 var(--arc-shadow-c, #05030d); }
:root[data-skin="game"] body.s-arcade .cp-cl .cp-cl-band { background: var(--a-bg-2, var(--cl-band)); }
:root[data-skin="game"] body.s-arcade .cp-cl ~ [data-lesson-pages] .s-cards { gap: 8px; margin-top: 12px; }
:root[data-skin="game"] body.s-arcade .cp-cl ~ [data-lesson-pages] .s-card { border-radius: 0; }
/* A button's label never wraps: the pixel face is wide, so a narrow phone sets the hero's buttons a step smaller. */
:root[data-skin="game"] body.s-arcade .cp-cl .cp-cl-actions .btn-lg { white-space: nowrap; }
@media (max-width: 419px) { :root[data-skin="game"] body.s-arcade .cp-cl .cp-cl-actions .btn-lg { padding-inline: 14px; font-size: 13px; } }

/* Whistling (site/courses/whistling): the app's note bars in magenta, the course's colour, after Hillel's design
   (2026-11-18, ~/Code/course-designs/whistling). Magenta is two tokens, AA on its ground in every theme: --wh-mag for
   words and marks (#a8236e on the warm light ground, #f28cc4 on a dark one) and --wh-bar for the drawings' bars. The
   hero's card is a screen, the same night in every theme: Hot Cross Buns as lesson 4 lays it, coloured by a labelled
   sample take (on pitch sits on its line; a little flat drops below it; the note being whistled now is ringed; still to
   come is hollow), its line moved from the audio clock while it plays (js/public/whistling.js). The units two by two in
   one frame, each with a drawing of its own exercise; what the app listens for on a magenta panel with a sample result;
   the facts each under a large word. The code face is the system's monospace (no new font). Game skin: the arcade's type
   and square framed panels; the screen stays a screen. */
.cp-wh { --wh-mag: #a8236e; --wh-bar: #a8236e; --wh-lite: #cc4590; --wh-tint: #f3e3ec; --wh-draw: #f6efe6; --cp-line: var(--k-line);
    --wh-mono: ui-monospace, SFMono-Regular, Menlo, Consolas, "Liberation Mono", monospace;
    --wh-screen: #1e1712; --wh-screen-ink: #faf5ee; --wh-screen-muted: #c9bfb3; --wh-grid: #3a302a; --wh-todo: #8a7f75;
    --wh-on: #3dd68c; --wh-flat: #e2a93b; --wh-now: #f06bb4; }
:root:not([data-theme$="-light"]) .cp-wh { --wh-mag: #f28cc4; --wh-bar: #e05ba4; --wh-lite: #f6a8d2; --wh-tint: #2a1822; --wh-draw: color-mix(in srgb, var(--color-raised) 70%, var(--color-ink)); }
.cp-wh-mono { font-family: var(--wh-mono); }
.cp-wh-kick { font-family: var(--wh-mono); font-size: var(--k-eyebrow); font-weight: 700; letter-spacing: .12em; text-transform: uppercase; color: var(--wh-mag); }
.cp-wh-title { margin-top: 12px; font-size: var(--k-h2); line-height: 1.06; font-weight: 800; letter-spacing: -0.03em; text-wrap: balance; max-width: 22ch; }
.cp-wh-body { margin-top: 16px; max-width: 48ch; font-size: 17px; line-height: 1.6; color: var(--color-muted); text-wrap: pretty; }
.cp-wh-sec { padding-top: var(--k-sec); }
.cp-wh-label { font-size: 12px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--color-muted); }
.cp-wh :is(a, button):focus-visible { outline: 3px solid var(--wh-mag); outline-offset: 3px; }

/* The hero: the words, then the card; side by side from 900 px. */
.cp-wh-hero { display: grid; grid-template-columns: minmax(0, 1fr); gap: var(--k-hero-gap, 48px); align-items: center; padding-top: var(--k-hero-top); }
@media (min-width: 900px) { .cp-wh-hero { grid-template-columns: minmax(0, 1fr) minmax(0, 1.02fr); gap: 56px; } }
.cp-wh-pills { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; margin-top: 18px; }
.cp-wh-pills .s-soonpill { margin: 0; }
.cp-wh-free { padding: 4px 12px; border-radius: 99px; background: var(--wh-tint); color: var(--wh-mag); font-size: 13px; font-weight: 700; }
.cp-wh-hero h1 { margin-top: 20px; font-size: clamp(48px, 7vw, 96px); line-height: .94; font-weight: 800; letter-spacing: -0.04em; text-wrap: balance; }
/* No pink in calm's headlines (docs/design-rules.md): the key phrase takes the warm accent; magenta stays the accent everywhere else. */
.cp-wh-em { display: block; color: var(--s-hl-em); }
.cp-wh-hero .s-lede { margin-top: 28px; max-width: 32em; }
.cp-wh-quiet { margin-top: 16px; max-width: 34em; font-size: 14.5px; line-height: 1.55; color: var(--color-muted); }
.cp-wh-actions { display: flex; flex-wrap: wrap; gap: 12px; margin-top: 30px; }
.cp-wh-actions .btn-lg { white-space: nowrap; }
@media (max-width: 639px) {
    .cp-wh-actions { flex-direction: column; }
    .cp-wh-actions .btn-lg { justify-content: center; width: 100%; }
}

/* The card: a screen, the same in every theme. */
.cp-wh-card { margin: 0; padding: clamp(20px, 3vw, 28px) clamp(16px, 3vw, 28px) clamp(18px, 2.4vw, 22px); border-radius: var(--k-r-feature); background: var(--wh-screen); color: var(--wh-screen-ink); box-shadow: 0 30px 60px -30px rgb(30 23 18 / .5); }
:root:not([data-theme$="-light"]) .cp-wh-card { border: 1px solid var(--color-line); }
.cp-wh-card-top { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: baseline; gap: 6px 12px; }
.cp-wh-card-top .cp-wh-mono { font-size: 12px; letter-spacing: .08em; text-transform: uppercase; color: var(--wh-screen-muted); }
.cp-wh-card-top b { font-size: 16px; }
.cp-wh-sample { margin-top: 12px; }
.cp-wh-sample span, .cp-wh-sample-tag { display: inline-block; padding: 3px 9px; border: 1px dashed currentColor; border-radius: 6px; font-family: var(--wh-mono); font-size: 11px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; }
.cp-wh-sample span { color: var(--wh-screen-muted); }
.cp-wh-lane { display: grid; grid-template-columns: auto minmax(0, 1fr); gap: 12px; margin-top: 14px; }
.cp-wh-rows { display: grid; grid-auto-rows: 44px; align-items: center; font-family: var(--wh-mono); font-size: 11.5px; color: var(--wh-screen-muted); white-space: nowrap; }
.cp-wh-track { position: relative; height: calc(var(--rows) * 44px); background: repeating-linear-gradient(to bottom, transparent 0 43px, var(--wh-grid) 43px 44px); }
.cp-wh-n { position: absolute; left: calc(var(--l) + 1.5px); width: calc(var(--w) - 3px); top: calc(var(--r) * 44px + 11px); height: 20px; border-radius: 6px; background: var(--wh-on); }
.cp-wh-n[data-state="flat"], .cp-wh-key[data-state="flat"] { background: var(--wh-flat); translate: 0 7px; }
.cp-wh-n[data-state="sharp"] { background: var(--wh-flat); translate: 0 -7px; }
.cp-wh-n[data-state="now"], .cp-wh-key[data-state="now"] { background: var(--wh-now); box-shadow: 0 0 0 2px var(--wh-screen), 0 0 0 4px var(--wh-screen-ink); }
.cp-wh-n[data-state="todo"] { background: none; border: 1.5px solid var(--wh-todo); }
.cp-wh-at { position: absolute; top: -6px; bottom: -4px; left: var(--at); width: 2px; margin-left: -1px; background: var(--wh-screen-ink); }
.cp-wh-card[data-done] .cp-wh-at { opacity: 0; }
@media (prefers-reduced-motion: reduce) { .cp-wh-card[data-playing] .cp-wh-at { opacity: 0; } }
.cp-wh-card-foot { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: center; gap: 10px 18px; margin-top: 18px; padding-top: 14px; border-top: 1px solid var(--wh-grid); }
.cp-wh-legend { display: flex; flex-wrap: wrap; gap: 6px 16px; font-size: 13px; color: var(--wh-screen-muted); }
.cp-wh-legend li { display: inline-flex; align-items: center; gap: 7px; }
.cp-wh-key { flex: none; width: 16px; height: 9px; border-radius: 3px; background: var(--wh-on); }
.cp-wh-legend .cp-wh-key[data-state="flat"] { translate: 0 3px; }
.cp-wh-legend .cp-wh-key[data-state="now"] { box-shadow: 0 0 0 1.5px var(--wh-screen), 0 0 0 3px var(--wh-screen-ink); }
.cp-wh-count { font-size: 14px; font-weight: 700; font-variant-numeric: tabular-nums; }
.cp-wh-playrow { margin-top: 16px; }
.cp-wh-play { display: inline-flex; align-items: center; gap: 10px; min-height: 44px; padding: 10px 20px 10px 16px; border-radius: 99px; background: var(--wh-screen-ink); color: var(--wh-screen); font-size: 15px; font-weight: 700; white-space: nowrap; cursor: pointer; }
.cp-wh-play:hover { background: #fff; }
.cp-wh-play:focus-visible { outline-color: var(--wh-now); }
.cp-wh-play-icon { width: 0; height: 0; border-block: 7px solid transparent; border-inline-start: 11px solid currentColor; }
.cp-wh-play[aria-pressed="true"] .cp-wh-play-icon { width: 11px; height: 11px; border: 0; border-radius: 2px; background: currentColor; }
.cp-wh-card[data-loading] .cp-wh-play { opacity: .8; }
.cp-wh-note { margin-top: 12px; font-size: 13px; line-height: 1.5; color: var(--wh-screen-muted); }
@media (max-width: 479px) { .cp-wh-rows { font-size: 10.5px; } .cp-wh-lane { gap: 8px; } }

/* The units two by two in one frame, each with its exercise drawn. */
.cp-wh-head { display: flex; flex-wrap: wrap; align-items: flex-end; justify-content: space-between; gap: 10px 24px; }
.cp-wh-count-all { font-size: 13px; color: var(--color-muted); }
.cp-wh-units { display: grid; grid-template-columns: minmax(0, 1fr); gap: 1px; margin-top: clamp(28px, 4vw, 44px); overflow: hidden; border: 1px solid var(--k-line); border-radius: var(--k-r-feature); background: var(--k-line); }
@media (min-width: 768px) { .cp-wh-units { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
.cp-wh-unit { padding: clamp(20px, 3vw, 30px); background: var(--color-panel); }
.cp-wh-draw { display: block; width: 100%; height: auto; border-radius: 14px; background: var(--wh-draw); }
.cp-wh-bar { fill: var(--wh-bar); }
.cp-wh-bar-mark { fill: var(--wh-lite); }
.cp-wh-slide { fill: none; stroke: var(--wh-lite); stroke-width: 6; stroke-linecap: round; stroke-linejoin: round; }
.cp-wh-breath { font: 700 20px/1 var(--wh-mono); fill: var(--wh-mag); }
.cp-wh-unit-n { margin-top: 20px; font-size: 12px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--wh-mag); }
.cp-wh-unit h3 { margin-top: 6px; font-size: 22px; line-height: 1.2; font-weight: 750; letter-spacing: -0.01em; }
.cp-wh-unit-line { margin-top: 10px; font-size: 15px; line-height: 1.55; color: var(--color-muted); text-wrap: pretty; }
.cp-wh-lessons { display: grid; gap: 2px; margin-top: 16px; padding-top: 14px; border-top: 1px solid var(--k-line); font-size: 15px; }
.cp-wh-lessons li { display: flex; flex-wrap: wrap; align-items: center; gap: 4px 10px; min-height: 30px; }
.cp-wh-lessons a { text-decoration: underline; text-decoration-color: color-mix(in srgb, var(--wh-mag) 45%, transparent); text-underline-offset: 4px; }
.cp-wh-lessons a:hover { color: var(--wh-mag); }
.cp-wh-ln { width: 20px; flex: none; font-size: 12.5px; color: var(--color-muted); }
.cp-wh-start { padding: 3px 9px; border-radius: 99px; background: var(--color-good); color: var(--color-ink); font-size: 10.5px; font-weight: 800; letter-spacing: .1em; text-transform: uppercase; white-space: nowrap; }

/* Before your first note: lesson 1's first card beside the heading, then a tip from each unit. */
.cp-wh-first { display: grid; grid-template-columns: minmax(0, 1fr); gap: 28px clamp(32px, 5vw, 64px); align-items: start; }
@media (min-width: 900px) { .cp-wh-first { grid-template-columns: minmax(0, .85fr) minmax(0, 1.15fr); } }
.cp-wh-first-card { padding: clamp(20px, 3vw, 30px); border-radius: 20px; background: var(--color-panel); border: 1px solid var(--k-line); }
.cp-wh-first-lead { margin-top: 10px; font-size: 18px; line-height: 1.55; text-wrap: pretty; }
.cp-wh-points { display: grid; gap: 14px; margin-top: 18px; }
@media (min-width: 640px) { .cp-wh-points { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
.cp-wh-points li { display: grid; gap: 4px; padding: 14px 16px; border-radius: 14px; background: var(--wh-tint); }
.cp-wh-points b { font-size: 15.5px; }
.cp-wh-points span { font-size: 14.5px; line-height: 1.5; color: var(--color-muted); }
.cp-wh-tips { grid-column: 1 / -1; }
.cp-wh-tips ol { display: grid; grid-template-columns: minmax(0, 1fr); gap: 24px; margin-top: 16px; }
@media (min-width: 640px) { .cp-wh-tips ol { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (min-width: 1024px) { .cp-wh-tips ol { grid-template-columns: repeat(4, minmax(0, 1fr)); } }
.cp-wh-tips li { display: grid; gap: 4px; padding-top: 14px; border-top: 2px solid var(--wh-bar); }
.cp-wh-tip-n { font-size: 12px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--wh-mag); }
.cp-wh-tips b { margin-top: 4px; font-size: 18px; }
.cp-wh-tips span:last-child { font-size: 15px; line-height: 1.5; color: var(--color-muted); }

/* The last lesson: its card beside the two whistles, the tune over the low line, each on its own track. */
.cp-wh-finale { display: grid; grid-template-columns: minmax(0, 1fr); gap: 32px clamp(32px, 5vw, 64px); align-items: center; }
@media (min-width: 900px) { .cp-wh-finale { grid-template-columns: minmax(0, .9fr) minmax(0, 1.1fr); } }
.cp-wh-points-3 { margin-top: 22px; }
@media (min-width: 640px) { .cp-wh-points-3 { grid-template-columns: minmax(0, 1fr); } }
.cp-wh-two { display: grid; gap: 18px; margin: 0; padding: clamp(18px, 3vw, 28px); border-radius: var(--k-r-feature); background: var(--wh-draw); }
.cp-wh-two-track { position: relative; height: 120px; margin-top: 10px; background: repeating-linear-gradient(to bottom, transparent 0 29px, var(--k-line) 29px 30px); }
.cp-wh-two-under { height: 44px; background: none; border-top: 1px solid var(--k-line); }
.cp-wh-two-track span { position: absolute; left: var(--l); width: max(8px, calc(var(--w) - 2px)); top: calc(var(--t) * .9); height: 9px; border-radius: 5px; background: var(--wh-bar); }
.cp-wh-two-under span { top: calc(8px + var(--t) * .4); height: 12px; border-radius: 6px; background: var(--wh-lite); }

/* What the app listens for, on a magenta panel: scored beside what you check, and a sample result. */
.cp-wh-hears { display: grid; grid-template-columns: minmax(0, 1fr); gap: 36px clamp(32px, 5vw, 64px); align-items: center; padding: clamp(28px, 5vw, 60px); border-radius: 28px; background: var(--wh-tint); }
@media (min-width: 900px) { .cp-wh-hears { grid-template-columns: minmax(0, 1.15fr) minmax(0, .85fr); } }
.cp-wh-hears .cp-wh-body { color: var(--color-cream); }
.cp-wh-split { display: grid; grid-template-columns: minmax(0, 1fr); gap: 20px 28px; margin-top: 26px; }
@media (min-width: 480px) { .cp-wh-split { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
.cp-wh-split dt { font-size: 14px; font-weight: 800; }
.cp-wh-split dd { margin-top: 6px; font-size: 15px; line-height: 1.55; color: var(--color-cream); }
.cp-wh-result { margin: 0; padding: clamp(20px, 3vw, 28px); border-radius: 20px; background: var(--color-panel); box-shadow: var(--k-sh-feature, 0 20px 40px -24px rgb(0 0 0 / .3)); }
.cp-wh-result-top { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 12px; font-size: 12px; letter-spacing: .06em; text-transform: uppercase; color: var(--color-muted); }
.cp-wh-sample-tag { color: var(--wh-mag); }
.cp-wh-verse { position: relative; height: 84px; margin-top: 18px; }
.cp-wh-verse span { position: absolute; left: var(--l); width: max(7px, calc(var(--w) - 1.5px)); top: calc(var(--t) * .88); height: 8px; border-radius: 4px; background: var(--color-good); }
.cp-wh-verse span[data-state="flat"] { background: none; border: 1.5px solid var(--color-warn); translate: 0 6px; }
.cp-wh-legend-light { margin-top: 14px; color: var(--color-muted); }
.cp-wh-legend-light .cp-wh-key { background: var(--color-good); }
.cp-wh-legend-light .cp-wh-key[data-state="flat"] { background: none; border: 1.5px solid var(--color-warn); }
.cp-wh-result-big { margin-top: 14px; font-size: clamp(26px, 3vw, 34px); line-height: 1.15; font-weight: 800; letter-spacing: -0.02em; font-variant-numeric: tabular-nums; }
.cp-wh-small { margin-top: 8px; font-size: 14px; line-height: 1.55; color: var(--color-muted); }

/* Did you know, each fact under a large word; then two more, smaller. */
.cp-wh-facts { display: grid; grid-template-columns: minmax(0, 1fr); gap: 32px; margin-top: 22px; }
@media (min-width: 900px) { .cp-wh-facts { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 40px; } }
.cp-wh-facts li { padding-top: 18px; border-top: 2px solid var(--color-cream); }
.cp-wh-big { font-size: clamp(44px, 5vw, 64px); line-height: 1; font-weight: 800; letter-spacing: -0.035em; }
.cp-wh-facts li p:last-child { margin-top: 14px; font-size: 16px; line-height: 1.6; text-wrap: pretty; }
.cp-wh-facts-more { margin-top: 44px; }
@media (min-width: 900px) { .cp-wh-facts-more { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
.cp-wh-facts-more li { border-top: 1px solid var(--k-line); }
.cp-wh-facts-more .cp-wh-big { font-size: clamp(30px, 3.2vw, 40px); color: var(--wh-mag); }

/* Inside a whistle: the heading beside four cards. */
.cp-wh-science { display: grid; grid-template-columns: minmax(0, 1fr); gap: 32px clamp(32px, 5vw, 64px); align-items: start; }
@media (min-width: 900px) { .cp-wh-science { grid-template-columns: minmax(0, .8fr) minmax(0, 1.2fr); } }
.cp-wh-cards { display: grid; grid-template-columns: minmax(0, 1fr); gap: 16px; }
@media (min-width: 640px) { .cp-wh-cards { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
.cp-wh-cards li { padding: 22px; border-radius: 18px; background: var(--color-panel); border: 1px solid var(--k-line); }
.cp-wh-cards h3 { font-size: 20px; line-height: 1.2; font-weight: 800; color: var(--wh-mag); }
.cp-wh-cards p { margin-top: 10px; font-size: 15px; line-height: 1.6; text-wrap: pretty; }

/* Whistled speech: four large words across a rule. */
.cp-wh-speech { display: grid; grid-template-columns: minmax(0, 1fr); gap: 28px 32px; margin-top: clamp(24px, 3vw, 36px); }
@media (min-width: 640px) { .cp-wh-speech { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (min-width: 1024px) { .cp-wh-speech { grid-template-columns: repeat(4, minmax(0, 1fr)); } }
.cp-wh-speech li { padding-top: 16px; border-top: 1px solid var(--k-line); }
.cp-wh-speech .cp-wh-big { font-size: clamp(32px, 3.4vw, 44px); color: var(--wh-mag); }
.cp-wh-speech li p:last-child { margin-top: 12px; font-size: 15.5px; line-height: 1.6; text-wrap: pretty; }

/* The songs in the order you meet them, beside whistling safely. */
.cp-wh-notes { display: grid; grid-template-columns: minmax(0, 1fr); gap: 44px clamp(32px, 5vw, 64px); align-items: start; }
@media (min-width: 900px) { .cp-wh-notes { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
.cp-wh-songs { margin-top: 14px; }
.cp-wh-songs li { display: grid; grid-template-columns: 76px minmax(0, 1fr); gap: 12px; align-items: baseline; padding-block: 14px; border-bottom: 1px solid var(--k-line); }
.cp-wh-song-u { font-size: 12px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--wh-mag); }
.cp-wh-songs b { display: block; font-size: 17px; }
.cp-wh-songs div span { display: block; margin-top: 2px; font-size: 14px; line-height: 1.5; color: var(--color-muted); }
.cp-wh-safety { display: grid; gap: 14px; margin-top: 14px; padding: 20px 22px; border-radius: 16px; background: var(--color-panel); border: 1px solid var(--k-line); }
.cp-wh-safety li { display: flex; gap: 12px; font-size: 16px; line-height: 1.55; }
.cp-wh-safety svg { flex: none; margin-top: 3px; color: var(--wh-mag); }

.cp-wh-faq .cp-faq { margin-top: 22px; }
.cp-wh-today { margin-top: var(--k-sec); }
.cp-wh-sources { padding-block: 8px 40px; }
.cp-wh-sources summary { display: flex; align-items: center; gap: 14px; min-height: 44px; cursor: pointer; list-style: none; }
.cp-wh-sources summary::-webkit-details-marker { display: none; }
.cp-wh-sources details[open] .cp-faq-sign { rotate: 45deg; }
.cp-wh-sources summary span { color: var(--color-muted); }
.cp-wh-sources ol { margin-top: 12px; padding-inline-start: 22px; list-style: decimal; display: grid; gap: 8px; font-size: 14px; line-height: 1.5; color: var(--color-muted); }
.cp-wh-sources a { overflow-wrap: anywhere; text-decoration: underline; text-underline-offset: 3px; }

/* The game skin: the arcade's type on labels and headings, square framed panels; the hero's screen stays a screen. */
:root[data-skin="game"] body.s-arcade .cp-wh :is(.cp-wh-kick, .cp-wh-label, .cp-wh-unit-n, .cp-wh-tip-n, .cp-wh-song-u, .cp-wh-start, .cp-wh-card-top .cp-wh-mono, .cp-wh-sample span, .cp-wh-sample-tag) { font-family: var(--a-hud); font-size: 9.5px; font-weight: 400; letter-spacing: .08em; line-height: 1.6; font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade .cp-wh :is(.cp-wh-hero h1, .cp-wh-title, .cp-wh-big) { font-family: var(--a-display); font-weight: 400; letter-spacing: .01em; text-transform: uppercase; line-height: 1.1; font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade .cp-wh .cp-wh-hero h1 { font-size: clamp(30px, 5vw, 56px); }
:root[data-skin="game"] body.s-arcade .cp-wh .cp-wh-em { color: var(--wh-mag); }
:root[data-skin="game"] body.s-arcade .cp-wh .cp-wh-title { font-size: clamp(22px, 3.2vw, 34px); }
:root[data-skin="game"] body.s-arcade .cp-wh .cp-wh-big { font-size: clamp(24px, 3vw, 36px); }
:root[data-skin="game"] body.s-arcade .cp-wh :is(.cp-wh-card, .cp-wh-units, .cp-wh-first-card, .cp-wh-points li, .cp-wh-hears, .cp-wh-result, .cp-wh-cards li, .cp-wh-safety, .cp-wh-draw, .cp-wh-two, .cp-wh-free, .cp-wh-start, .cp-wh-play) { border-radius: 0; }
:root[data-skin="game"] body.s-arcade .cp-wh :is(.cp-wh-card, .cp-wh-units, .cp-wh-first-card, .cp-wh-result, .cp-wh-cards li, .cp-wh-safety, .cp-wh-two) { border: 2px solid var(--a-line-2); box-shadow: 4px 4px 0 var(--arc-shadow-c, #05030d); }
:root[data-skin="game"] body.s-arcade .cp-wh :is(.cp-wh-first-card, .cp-wh-result, .cp-wh-cards li, .cp-wh-safety, .cp-wh-unit) { background: var(--a-panel); }
:root[data-skin="game"] body.s-arcade .cp-wh .cp-wh-units { background: var(--a-line-2); }
:root[data-skin="game"] body.s-arcade .cp-wh .cp-wh-actions .btn-lg { white-space: nowrap; }
@media (max-width: 419px) { :root[data-skin="game"] body.s-arcade .cp-wh .cp-wh-actions .btn-lg { padding-inline: 14px; font-size: 13px; } }

/* A course page (site/course): its units as cards, lesson by lesson, the first one free; what the app
   listens for beside two real screens; singing safely and the songs side by side. */
.s-units-head { display: flex; flex-wrap: wrap; align-items: baseline; justify-content: space-between; gap: 8px 16px; }
.s-units-count { font-size: 14px; color: var(--color-muted); }
.s-units { display: grid; gap: 14px; margin-top: 24px; counter-reset: unit; }
.s-unit { padding: 22px; border-radius: 22px; background: var(--color-panel); border: 1px solid var(--color-line); }
.s-unit-n { font-size: 12px; font-weight: 800; letter-spacing: .12em; text-transform: uppercase; color: var(--color-part-ink-2); }
.s-unit h3 { margin-top: 4px; font-size: 19px; font-weight: 800; }
.s-unit ol { margin-top: 12px; display: grid; gap: 8px; list-style: decimal; padding-inline-start: 1.3em; font-size: 15px; line-height: 1.4; color: var(--color-muted); }
.s-unit ol li::marker { font-variant-numeric: tabular-nums; }
.s-free { display: inline-flex; margin-inline-start: 8px; padding: 2px 9px; border-radius: 99px; font-size: 11.5px; font-weight: 800; letter-spacing: .06em; text-transform: uppercase; vertical-align: 1px; color: #fff; background: #1d7a43; box-shadow: 0 2px 8px -3px #1d7a43; }
.s-course-hears { align-items: start; }
.s-course-shots { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 16px; align-items: start; }
.s-course-shots > :nth-child(2) { margin-top: 48px; }
.cp .s-course-shots .s-appshot-tall picture { width: min(100%, 340px); }
.s-course-shots .s-appshot-tall picture { width: 100%; }
.s-course-notes { display: grid; gap: 40px; }
.s-course-notes .s-ticks svg { color: var(--color-part-ink-1); }
.s-course-songs { display: grid; gap: 10px; margin-top: 20px; font-size: 16px; line-height: 1.4; }
.s-course-songs span { color: var(--color-muted); }
@media (min-width: 900px) {
    .s-units { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 18px; }
    .s-unit { padding: 28px; }
    .s-course-notes { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 64px; }
}
:root[data-skin="game"] body.s-arcade .s-unit-n { font-family: var(--a-hud); font-size: 9.5px; font-weight: 400; letter-spacing: .06em; color: var(--a-cyan); font-size-adjust: var(--arc-ex, none); }
:root[data-skin="game"] body.s-arcade .s-unit { background: var(--a-panel); border-color: var(--a-line); }
