:root[data-skin="game"] body.s-arcade .s-video-len { font-family: var(--a-hud); font-size: 9.5px; font-weight: 400; letter-spacing: .04em; padding: 6px 9px; color: #ffd84a; font-size-adjust: var(--arc-ex, none); } /* on the video's dark chip in either mode */
