[data-skin='game'] .ge-boss-gem { position: relative; display: block; justify-self: center; align-self: center; width: 4.5rem; height: 4.5rem; margin-block: 0.5rem; transform: rotate(45deg); background: var(--color-accent); box-shadow: inset 6px 6px 0 rgb(255 255 255 / 0.28), inset -6px -6px 0 rgb(0 0 0 / 0.28), 6px 6px 0 var(--arc-shadow-c, rgb(0 0 0 / 0.5)); }
