[data-skin='game'] .ge-boss-gem[data-crack='4'] { opacity: 0.45; transform: rotate(45deg) scale(0.85); }
[data-skin='game'] .ge-boss-gem.is-small { width: 1.6rem; height: 1.6rem; margin: 0 0.35rem; box-shadow: inset 3px 3px 0 rgb(255 255 255 / 0.28), inset -3px -3px 0 rgb(0 0 0 / 0.28); }
[data-skin='game'] .ge-boss-hud { display: flex; align-items: center; gap: 0.75rem; padding: 0.65rem 0.85rem; background: var(--color-panel); box-shadow: inset 0 0 0 2px var(--color-accent), 4px 4px 0 var(--arc-shadow-c, rgb(0 0 0 / 0.5)); }
[data-skin='game'] .ge-boss-label { display: flex; justify-content: space-between; gap: 0.75rem; margin: 0 0 0.4rem; font: 400 10px/1.2 var(--ge-hud); letter-spacing: 0.06em; text-transform: uppercase; color: var(--color-cream); }
[data-skin='game'] .ge-boss-track { position: relative; display: block; height: 0.9rem; background: var(--color-ink); box-shadow: inset 0 0 0 2px var(--color-line); }
[data-skin='game'] .ge-boss-fill { display: block; width: 100%; height: 100%; background: var(--ge-red); transform-origin: left; transition: transform 240ms steps(6); } /* a scale, not a width: the compositor's (the slow-phone pass) */
[dir='rtl'][data-skin='game'] .ge-boss-fill, [dir='rtl'] [data-skin='game'] .ge-boss-fill { transform-origin: right; }
[data-skin='game'] .ge-boss-line { position: absolute; top: -3px; bottom: -3px; width: 3px; background: var(--ge-yellow); }
@media (prefers-reduced-motion: reduce) { [data-skin='game'] :is(.ge-boss-fill, .ge-boss-gem::after) { transition: none; } }

/* Stage select: the open unit as a winding dotted path, lit in the unit's colour up to you. */
[data-skin='game'] .ge-map { position: relative; max-width: 34rem; margin-inline: auto; }
[data-skin='game'] .ge-map-path { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; }
[data-skin='game'] .ge-map-path path { fill: none; stroke: var(--color-line); stroke-width: 3; stroke-linecap: round; stroke-dasharray: 0.1 9; }
[data-skin='game'] .ge-map-path path.is-lit { stroke: var(--ge-unit); }
[data-skin='game'] .ge-map ol { position: absolute; inset: 0; }
[data-skin='game'] .ge-map-stop { position: absolute; width: max-content; display: flex; align-items: center; gap: 0.75rem; transform: translate(-1.75rem, -1.75rem); }
:root[dir='rtl'][data-skin='game'] .ge-map-stop { transform: translate(1.75rem, -1.75rem); }
[data-skin='game'] .ge-map-node { position: relative; display: grid; place-items: center; flex: none; width: 3.5rem; height: 3.5rem; border-radius: 50%; border: 2px solid var(--color-line); background: var(--color-ink); color: var(--color-muted); transition: transform 160ms ease-out; }
[data-skin='game'] .ge-map-node:not(:disabled):hover { transform: scale(1.06); }
[data-skin='game'] .ge-map-node:disabled { cursor: not-allowed; opacity: 0.55; }
/* Game mode's circles: the arcade coin (Hillel's pick, 2026-11-08, of two shot options; serious mode's are bubbles). A
   smooth round in a flat colour (--coin), a 2 px dark edge, a hard 2 px light at its top and shade at its foot, and an
   arcade button's solid depth under it in a darker step of its colour: no gradient, blur or glow. The one you're on is
   filled in the accent and wears a 3 px accent ring clear of it; one to come is an empty slot, the well pressed in. */
[data-skin='game'] .ge-map-node:is(.is-done, .is-now) { --coin-edge: var(--arc-shadow-c, #05030d); background: var(--coin); border: 2px solid var(--coin-edge);
    --coin-face: inset 0 2px 0 color-mix(in oklab, var(--coin) 55%, white), inset 0 -3px 0 color-mix(in oklab, var(--coin) 62%, black), 0 4px 0 0 color-mix(in oklab, var(--coin) 45%, black), 0 4px 0 2px var(--coin-edge);
    box-shadow: var(--coin-face); }
[data-skin='game'] .ge-map-node.is-done { --coin: var(--ge-unit); color: var(--color-ink); }
[data-skin='game'][data-theme$='-light'] .ge-map-node.is-done { color: #fff; }
[data-skin='game'] .ge-map-node.is-now { --coin: var(--color-accent); color: var(--color-accent-ink); box-shadow: var(--coin-face), 0 0 0 5px var(--color-ink), 0 0 0 8px var(--color-accent); }
[data-skin='game'] .ge-map-node:not(.is-done, .is-now, .is-special) { background: var(--arc-well, var(--color-ink)); box-shadow: inset 0 3px 0 rgb(0 0 0 / 0.35); }
[data-skin='game'] .ge-map-node.is-special:not(.is-done) { border-radius: 0.9rem; transform: rotate(45deg); border-color: var(--ge-yellow); color: var(--ge-yellow); }
[data-skin='game'] .ge-map-node.is-special:not(.is-done) .ge-map-star { transform: rotate(-45deg); }
[data-skin='game'] .ge-map-node.is-picked { box-shadow: var(--coin-face, inset 0 3px 0 rgb(0 0 0 / 0.35)), 0 0 0 5px var(--color-ink), 0 0 0 8px var(--color-cream); }
[data-skin='game'] .ge-map-node.is-now.is-picked { box-shadow: var(--coin-face), 0 0 0 5px var(--color-ink), 0 0 0 8px var(--color-accent); } /* the one you're on keeps its accent ring when picked */
[data-skin='game'] .ge-map-num { font: 400 13px/1 var(--ge-hud); }
[data-skin='game'] .ge-map-here { position: absolute; bottom: calc(100% + 0.2rem); inset-inline-start: 50%; translate: -50% 0; white-space: nowrap; padding: 0.2rem 0.45rem; border-radius: 6px; background: var(--ge-cyan); color: #04121a; font: 400 9px/1.4 var(--ge-hud); text-transform: uppercase; letter-spacing: 0.04em; }
[data-skin='game'][data-theme$='-light'] .ge-map-here { color: #fff; }
[data-skin='game'] .ge-map-label { display: grid; justify-items: start; gap: 0.2rem; max-width: min(17rem, 58vw); }
/* Over a title (Hillel's 98.png): "You are here" sits in the label's own stack, never over the node. */
[data-skin='game'] .ge-map-label .ge-map-here { position: static; translate: none; }
:root[dir='rtl'][data-skin='game'] .ge-map-label .ge-map-here { translate: none; }
[data-skin='game'] .ge-map-stars { font-style: normal; font-size: 0.7rem; letter-spacing: 0.1em; color: var(--color-line); }
[data-skin='game'] .ge-map-stars i { font-style: normal; }
[data-skin='game'] .ge-map-stars i.is-on { color: var(--ge-yellow); }
[data-skin='game'] .ge-map-special { font: 400 9px/1.4 var(--ge-hud); text-transform: uppercase; letter-spacing: 0.06em; color: var(--ge-yellow); }
[data-skin='game'] .ge-map-title { font-size: 0.875rem; font-weight: 700; line-height: 1.25; color: var(--color-cream); }
[data-skin='game'] .ge-map-target { font-size: 0.75rem; color: var(--color-muted); }
[data-skin='game'] .ge-map-node.is-special:not(.is-done):not(:disabled):hover { transform: rotate(45deg) scale(1.06); }

/* Choose your part, as a reskin of the part list: portraits in the part colours, each with its own
   range, meters and badge, the 1P cursor in your accent. */
[data-skin='game'] .ge-select-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 0.85rem; padding-top: 0.5rem; }
@media (min-width: 768px) { [data-skin='game'] .ge-select-grid { grid-template-columns: repeat(4, minmax(0, 1fr)); } }
[data-skin='game'] .ge-portrait { position: relative; display: grid; grid-template-columns: auto 1fr; align-items: start; gap: 0.3rem 0.5rem; width: 100%; height: 100%; padding: 0.85rem; border-radius: 0; text-align: start; border: 2px solid color-mix(in srgb, var(--ge-part) 55%, var(--color-line)); box-shadow: 4px 4px 0 var(--arc-shadow-c, rgb(0 0 0 / 0.5)); background: linear-gradient(160deg, color-mix(in srgb, var(--ge-part) 26%, var(--color-panel)), var(--color-panel) 75%); transition: transform 160ms ease-out; }
[data-skin='game'] .ge-portrait:hover { transform: translateY(-2px); }
[data-skin='game'] .ge-portrait.is-picked::after { content: ''; position: absolute; inset: -6px; border-radius: 0; border: 3px solid var(--color-accent); pointer-events: none; }
[data-skin='game'] .ge-portrait.is-blinking::after { animation: ge-blink 500ms steps(1) 5; }
[data-skin='game'] .ge-portrait.is-locking { animation: ge-lock 280ms ease-out; }
[data-skin='game'] .ge-portrait.is-locking::before { content: ''; position: absolute; inset: 0; border-radius: inherit; background: #fff; pointer-events: none; animation: ge-flash 280ms ease-out both; }
[data-skin='game'] .ge-1p { position: absolute; z-index: 2; top: -0.7rem; inset-inline-start: 50%; translate: -50% 0; padding: 0.15rem 0.4rem; border-radius: 0; background: var(--color-accent); color: var(--color-accent-ink); font: 400 9px/1.4 var(--ge-hud); }
[data-skin='game'] .ge-portrait-letter { font: 400 2.5rem/0.9 var(--ge-display); color: var(--ge-part); }
[data-skin='game'] .ge-portrait-name { grid-column: span 2; font-weight: 700; color: var(--color-cream); }
/* The part in words under its name (part-words.js): a sentence, so Figtree, calm. */
[data-skin='game'] .ge-portrait-words { grid-column: span 2; font-size: 0.8125rem; line-height: 1.35; color: var(--color-muted); }
[data-skin='game'] .ge-fits { grid-column: span 2; justify-self: start; text-wrap: balance; padding: 0.2rem 0.4rem; border-radius: 0; border: 1px solid var(--color-part-3); color: var(--color-part-3); font: 400 8.5px/1.4 var(--ge-hud); text-transform: uppercase; }
/* No voice yet (Be the voice): a quiet cartridge label, muted on a dashed line (an empty slot), beside Best for you's lit one. */
[data-skin='game'] .ge-novoice { grid-column: span 2; justify-self: start; text-wrap: balance; padding: 0.2rem 0.4rem; border: 1px dashed var(--color-line); color: var(--color-muted); font: 400 8.5px/1.4 var(--ge-hud); letter-spacing: 0.03em; text-transform: uppercase; }
[data-skin='game'] .ge-portrait-stats { grid-column: span 2; display: grid; gap: 0.3rem; margin-top: 0.15rem; }
[data-skin='game'] .ge-stat { display: grid; grid-template-columns: minmax(3.6rem, max-content) 1fr; align-items: center; gap: 0.4rem; font: 400 8px/1.4 var(--ge-hud); letter-spacing: 0.03em; text-transform: uppercase; color: var(--color-muted); }
[data-skin='game'] .ge-stat > span:nth-child(2) { color: var(--color-cream); }
[data-skin='game'] .ge-statbar { display: flex; gap: 2px; }
[data-skin='game'] .ge-statbar i { flex: 1; height: 0.45rem; border-radius: 1px; background: var(--color-raised); }
[data-skin='game'] .ge-statbar i.is-lit { background: var(--ge-yellow); }
@keyframes ge-lock { 35% { transform: scale(1.04); } }
@keyframes ge-flash { 0% { opacity: 0; } 35% { opacity: 0.55; } 100% { opacity: 0; } }
@media (prefers-reduced-motion: reduce) { [data-skin='game'] .ge-portrait.is-blinking::after, [data-skin='game'] .ge-portrait.is-locking, [data-skin='game'] .ge-portrait.is-locking::before { animation: none; } }
/* The first week's welcome on the stage card: a sentence, so Figtree, in the score yellow. */
:root[data-skin='game']:not([data-game-off~='title']) [data-lead] [data-welcome] { color: var(--ge-yellow); }

/* Item get: a new badge's toast, as A Link to the Past's item get: a star gem held up at its start,
   bobbing twice, the toast in an arcade frame (a reskin of the toast; Celebrations switch). */
:root[data-skin='game']:not([data-game-off~='celebrations']) [data-toast-tone='badge'] { overflow: visible; padding-inline-start: 3.4rem; border-color: color-mix(in srgb, var(--ge-yellow) 60%, var(--color-line)); font-weight: 700; }
:root[data-skin='game']:not([data-game-off~='celebrations']) [data-toast-tone='badge']::before {
    content: ''; position: absolute; inset-inline-start: 0.85rem; top: 50%; width: 1.9rem; height: 1.9rem; margin-top: -0.95rem; border-radius: 50%;
    background: radial-gradient(circle at 34% 28%, #fff 0 6%, color-mix(in oklab, var(--ge-fill-y) 55%, white) 22%, var(--ge-fill-y) 55%, color-mix(in oklab, var(--ge-fill-y) 60%, black) 100%);
    box-shadow: inset 0 -3px 4px rgb(0 0 0 / 0.25);
    animation: ge-item 1.1s cubic-bezier(0.3, 1.4, 0.5, 1) both;
}
@keyframes ge-item { 0% { transform: translateY(0.9rem) scale(0.4); opacity: 0; } 30% { transform: translateY(-0.35rem) scale(1.1); opacity: 1; } 50% { transform: translateY(0); } 70% { transform: translateY(-0.2rem); } 100% { transform: none; opacity: 1; } }
@media (prefers-reduced-motion: reduce) { :root[data-skin='game']:not([data-game-off~='celebrations']) [data-toast-tone='badge']::before { animation: none; } }
/* A lesson's new badges, said once in its result (game/badge-news.js; onboarding review 2, Must 5): a line
   in the result's own flow, never over it. With Celebrations, the item get's gem, landing after the
   stars and the count (about 1.2 s); still, it's simply there. */
.ge-badge-line { position: relative; display: inline-flex; align-items: center; gap: 0.5rem; padding: 0.3rem 0.6rem; border: 1px solid var(--color-line); border-radius: 0; background: var(--color-raised); color: var(--color-cream); font-size: 0.8125rem; font-weight: 700; }
/* A new badge: a flat tag with a small square marker in the arcade's yellow (no glossy capsule: the first-15-minutes review, item 20). */
:root[data-skin='game']:not([data-game-off~='celebrations']) .ge-badge-line { border-color: color-mix(in srgb, var(--ge-yellow) 60%, var(--color-line)); animation: ge-badge-in 0.35s ease-out 1.2s both; }
:root[data-skin='game']:not([data-game-off~='celebrations']) .ge-badge-line::before { content: ''; flex-shrink: 0; width: 0.6rem; height: 0.6rem; background: var(--ge-yellow); animation: ge-item 1.1s cubic-bezier(0.3, 1.4, 0.5, 1) 1.2s both; }
@keyframes ge-badge-in { from { opacity: 0; transform: translateY(0.4rem); } to { opacity: 1; transform: none; } }
[data-lesson-end].is-landed .ge-badge-line, [data-lesson-end].is-landed .ge-badge-line::before { animation: none; }
@media (prefers-reduced-motion: reduce) { :root[data-skin='game'] .ge-badge-line, :root[data-skin='game'] .ge-badge-line::before { animation: none; } }

/* Small reskins of words already on screen: weeks in a row as a multiplier chip, the take heard back
   as a sports replay (a red dot and REPLAY in HUD type). */
[data-skin='game'] [data-weeks] { display: inline-block; padding: 0.15rem 0.45rem; border-radius: 6px; background: var(--color-raised); font: 400 9px/1.6 var(--ge-hud); letter-spacing: 0.04em; text-transform: uppercase; color: var(--ge-yellow); }
[data-skin='game'] [data-replay] { display: flex; align-items: center; gap: 0.45rem; font: 400 11px/1.6 var(--ge-hud); letter-spacing: 0.06em; text-transform: uppercase; color: var(--ge-red); }
[data-skin='game'] [data-replay]::before { content: ''; width: 0.55rem; height: 0.55rem; border-radius: 50%; background: var(--ge-red); animation: ge-blink 1s steps(1) 3; }
@media (prefers-reduced-motion: reduce) { [data-skin='game'] [data-replay]::before { animation: none; } }
/* Right to left: the centred tags move back by half their own width the other way. */
:root[dir='rtl'][data-skin='game'] :is(.ge-1p, .ge-map-here) { translate: 50% 0; }

/* Two last moments: the CRT boot of the session's first Sing lane (it folds open from a bright line,
   0.4 s, before any take), and a small screen shake (3 px, 200 ms) as NEW RECORD lands and on a
   level-up; never while singing, never with reduced motion. */
:root[data-skin='game']:not([data-game-off~='titles']) .ge-crt { transform-origin: 50% 50%; animation: ge-crt 420ms cubic-bezier(0.2, 0.8, 0.2, 1) both; }
@keyframes ge-crt { 0% { opacity: 0; transform: scale(1, 0.006); } 35% { opacity: 1; transform: scale(1, 0.006); } 100% { opacity: 1; transform: none; } }
:root[data-skin='game']:not([data-game-off~='celebrations']) [data-take-best]:has([data-game-record]) { animation: ge-shake 200ms linear 0.7s; }
:root[data-skin='game']:not([data-game-off~='celebrations']) [data-lesson-end]:has([data-level-up]) { animation: ge-shake 200ms linear 1.4s; }
@keyframes ge-shake { 20% { transform: translate(-3px, 1px); } 40% { transform: translate(3px, -1px); } 60% { transform: translate(-2px, 0); } 80% { transform: translate(2px, 1px); } }
@media (prefers-reduced-motion: reduce) {
    :root[data-skin='game'] .ge-crt, :root[data-skin='game'] [data-take-best], :root[data-skin='game'] [data-lesson-end] { animation: none !important; }
}

/* The super meter (Breath and stamina's hold, after SF Alpha): three segments to your own goal, full
   at GOAL and no further (the fill stops there, breath-hold.js); it fills and never drains. */
:root[data-skin='game']:not([data-game-off~='hud']) [data-breath-bar] { overflow: visible; border-radius: 4px; }
:root[data-skin='game']:not([data-game-off~='hud']) [data-breath-fill] { border-radius: 3px; }
:root[data-skin='game']:not([data-game-off~='hud']) [data-breath-bar]::after { content: ''; position: absolute; inset: 0; z-index: 1; pointer-events: none; border-radius: inherit; background: repeating-linear-gradient(90deg, transparent 0 calc(var(--meter-seg) - 3px), var(--color-ink) calc(var(--meter-seg) - 3px) var(--meter-seg)); }
:root[data-skin='game']:not([data-game-off~='hud']) [data-breath-goal] { z-index: 2; background: var(--ge-yellow); }
[data-skin='game'] .ge-goal { position: absolute; bottom: calc(100% + 0.3rem); inset-inline-start: 50%; translate: -50% 0; white-space: nowrap; font: 400 8.5px/1.4 var(--ge-hud); letter-spacing: 0.04em; text-transform: uppercase; color: var(--ge-yellow); }
:root[dir='rtl'][data-skin='game'] .ge-goal { translate: 50% 0; }
/* The on-fire trail's colour (Sing's voice ribbon at 10 in a row; the painter reads it). */
:root[data-skin='game'] { --ge-fire: #ff4fa8; }
:root[data-skin='game'][data-theme$='-light'] { --ge-fire: #c81872; }

/* The studio's tracks as players (idea 11, after the 4-player cabinets), a reskin with no words in
   CSS: each track's name gets "1P", "2P"... from a counter, the armed track an all-round accent ring
   (never a stripe down one side), and Record a ▸ that blinks 5 times before its own words. Mixing
   stays calm. Character select switch. */
:root[data-skin='game']:not([data-game-off~='select']) [data-tracks] { counter-reset: ge-player; }
:root[data-skin='game']:not([data-game-off~='select']) [data-tracks] section { counter-increment: ge-player; }
:root[data-skin='game']:not([data-game-off~='select']) [data-tracks] section [data-track-name]::before { content: counter(ge-player) 'P'; display: inline-block; margin-inline-end: 0.45rem; padding: 0.1rem 0.3rem; border-radius: 4px; background: var(--color-raised); color: var(--ge-yellow); font: 400 8.5px/1.5 var(--ge-hud); vertical-align: 0.15em; }
:root[data-skin='game']:not([data-game-off~='select']) [data-tracks] section[data-next-track] { box-shadow: 0 0 0 2px var(--color-accent); border-radius: var(--r-control); }
:root[data-skin='game']:not([data-game-off~='select']) [data-tracks] section[data-next-track] [data-track-name]::before { background: var(--color-accent); color: var(--color-accent-ink); }
/* Record had a blinking ▸ before its words; it has its own disc now, so the mark read as stray (the finish-line audit,
   2026-11-13) and went. The screen font is wider than the calm one, so the studio's lines that cut off there wrap
   instead: the song's line under its name to two lines (a tap opens it all), a part's state and the place under the
   time in full. */
:root[data-skin='game'][data-gs] [data-song-meta] { display: -webkit-box; -webkit-box-orient: vertical; -webkit-line-clamp: 2; white-space: normal; }
:root[data-skin='game'][data-gs] [data-tracks] [data-status] { white-space: normal; text-overflow: clip; overflow: visible; line-height: 1.15; }
/* The place under the time keeps one line (a second would make the dock taller than the room the page keeps for it): its
   box grows to fit it instead. */
:root[data-skin='game'][data-gs] :has(> [data-bar-beat]) { width: auto; min-width: 4rem; }
:root[data-skin='game'][data-gs] [data-bar-beat] { text-overflow: clip; overflow: visible; }
@media (max-width: 359.98px) {
    /* A 320 phone: the box keeps its 64 px so Record keeps its words; the place a size smaller fits it. */
    :root[data-skin='game'][data-gs] :has(> [data-bar-beat]) { width: 4rem; }
    :root[data-skin='game'][data-gs] [data-bar-beat] { font-size: 9.5px; letter-spacing: -0.02em; }
}
/* Settings' Delete everything here is wide in the pixel face: its words keep a column of their own (the button wraps under
   them on a phone) rather than one word a line beside it. */
:root[data-skin='game'][data-gs] [data-wipe-text] { flex-basis: 14rem; }

/* Initials: the arcade letter picker (three tall letters, ▲ and ▼ for each, the one now in your
   accent), and a board's entry shown by initials in HUD type. The picker is a form: plain in both
   skins but its letters (the picker only exists in game mode). */
.ge-initials { display: flex; justify-content: center; gap: 0.75rem; }
.ge-initial { display: grid; justify-items: center; gap: 0.25rem; }
.ge-initial-step { display: grid; place-items: center; width: 2.75rem; height: 2.75rem; border-radius: var(--r-control, 12px); background: var(--fill-2); color: var(--color-cream); }
.ge-initial-step:hover { background: var(--fill-3); }
.ge-initial-letter { width: 3.5rem; height: 4rem; border-radius: 12px; border: 0; background: var(--fill-2); color: var(--color-cream); text-align: center; font: 400 2.25rem/1 var(--ge-display, inherit); text-transform: uppercase; caret-color: transparent; }
.ge-initial.is-now .ge-initial-letter { box-shadow: 0 0 0 2px var(--color-accent); color: var(--color-accent); }
.ge-initial-letter:focus-visible { outline: 2px solid var(--ring, var(--color-accent)); outline-offset: 2px; }
[data-skin='game'] [data-initials] { font: 400 0.75rem/1.6 var(--ge-hud); letter-spacing: 0.08em; color: var(--ge-yellow); }
/* A part's leaderboard as one card (Hillel's mockup 1a, components/boards.js): the part as a tag, a small
   switch, a table whose first place wears a gold circle, your row tinted with a YOU tag. Game mode only. */
[data-skin='game'] .ge-board-part { display: inline-flex; align-items: center; gap: 0.35rem; padding: 0.15rem 0.55rem; border-radius: 9999px; background: color-mix(in srgb, var(--ge-yellow) 16%, transparent); color: var(--color-cream); font-size: 0.8125rem; font-weight: 700; }
[data-skin='game'] .ge-board-scope .seg-option { min-height: 2rem; padding-inline: 0.8rem; font-size: 0.8125rem; }
@media (max-width: 30rem) { [data-skin='game'] .ge-board-scope .seg-option { padding-inline: 0.6rem; font-size: 0.75rem; } }
[data-skin='game'] .ge-board-rank { display: inline-grid; place-items: center; width: 1.75rem; height: 1.75rem; border-radius: 50%; background: var(--color-raised); color: var(--color-cream); font-size: 0.75rem; font-weight: 800; }
[data-skin='game'] .ge-board-rank.is-first { background: var(--ge-fill-y); color: var(--ge-fill-y-ink); }
[data-skin='game'] .ge-board-you > td { background: color-mix(in srgb, var(--color-accent) 12%, transparent); box-shadow: inset 0 1px 0 color-mix(in srgb, var(--color-accent) 30%, transparent), inset 0 -1px 0 color-mix(in srgb, var(--color-accent) 30%, transparent); }
[data-skin='game'] .ge-board-you > td:first-child { box-shadow: inset 1px 1px 0 color-mix(in srgb, var(--color-accent) 30%, transparent), inset 0 -1px 0 color-mix(in srgb, var(--color-accent) 30%, transparent); }
[data-skin='game'] .ge-board-you > td:last-child { box-shadow: inset -1px 1px 0 color-mix(in srgb, var(--color-accent) 30%, transparent), inset 0 -1px 0 color-mix(in srgb, var(--color-accent) 30%, transparent); }
[data-skin='game'] .ge-board-you-tag { flex-shrink: 0; padding: 0.05rem 0.4rem; border: 1px solid color-mix(in srgb, var(--color-accent) 70%, transparent); border-radius: 9999px; color: var(--color-accent); font-size: 0.6875rem; font-weight: 800; text-transform: uppercase; letter-spacing: 0.04em; }

/* The daily challenge, a reskin of the day's song card on Home: an all-round ring in the score yellow
   and a "Today's challenge" tag on it (a button beside the card's own, so it never nests). */
:root[data-skin='game']:not([data-game-off~='daily']) [data-daily] > button:not(.ge-daily-tag) { box-shadow: 0 0 0 2px var(--ge-yellow); border-radius: 1.5rem; }
[data-skin='game'] .ge-daily-tag { position: absolute; z-index: 2; bottom: calc(100% - 0.55rem); inset-inline-start: 0.6rem; max-width: calc(100% - 1.2rem); min-height: 1.5rem; display: inline-flex; align-items: center; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; padding: 0.3rem 0.45rem; border-radius: 6px; background: var(--ge-fill-y); color: var(--ge-fill-y-ink); font: 400 8.5px/1.4 var(--ge-hud); letter-spacing: 0.06em; text-transform: uppercase; }
[data-skin='game'] .ge-daily-tag:hover { background: color-mix(in srgb, var(--ge-fill-y) 88%, white); }
[data-skin='game'] .ge-daily-what { font: 400 1.25rem/1.2 var(--ge-display); text-transform: uppercase; color: var(--color-cream); }
/* The song list scrolls sideways, which clips above it: room for the tag when a challenge card is in it. */
:root[data-skin='game']:not([data-game-off~='daily']) #home-songs:has([data-daily]) { padding-top: 1.1rem; padding-bottom: 0.25rem; }
/* The bonus's rate beside the combo (docs/game-feel-plan.md): x2 from 20 in a row, x3 from 30. */
[data-skin='game'] .ge-rate { padding: 0.15rem 0.5rem; border-radius: 6px; background: var(--ge-fill-y); color: var(--ge-fill-y-ink); font: 400 10px/1.6 var(--ge-hud); text-transform: uppercase; letter-spacing: 0.04em; }
/* A chord ringing in tune glows in game mode (Sing's ring meter, data-locked): was a class switched in JS. */
[data-skin='game'] [data-ring-meter][data-locked] { animation: celebrate-glow 2.1s ease-in-out; }

/* game-elements:end */

/* arcade-screen:start (game/arcade.js; Hillel's Home design, images/90.png, 2026-10-30: "make it look
   as close to the image I shared as possible", then "use these new styles everywhere for game mode").
   One layer for every screen it covers (<html data-gs>, set only on those screens and with the Arcade
   screen switch on): the pixel face (Stackapella Pixel) for headings, labels and buttons, VT323 for body text (each sized
   by font-size-adjust, so lines keep today's sizes and lengths), square pixel edges with hard shadows,
   buttons that press down, the dotted screen with faint scanlines, hazard stripes on the asks.
   Reduced motion: no scanlines, no sweep, no press movement. Serious mode never sees it. */
:root[data-skin='game'][data-gs] {
    /* The buttons' shape (the primitives read these): a hard drop, an outlined secondary, a press into the shadow. */
    --btn-drop: var(--arc-shadow);
    --btn-outline: inset 0 0 0 var(--arc-edge-w) var(--arc-purple), var(--arc-shadow);
    --btn-outline-pressed: inset 0 0 0 var(--arc-edge-w) var(--arc-purple);
    --btn-press: translate(var(--arc-press), var(--arc-press));
    --btn-soft: transparent;
    --btn-soft-hover: transparent;
    --btn-soft-active: transparent;
    --btn-go-bg: transparent;
    --btn-go-hover: transparent;
    --color-panel: var(--arc-panel);
    --color-edge: var(--arc-line);
    --color-ink: var(--arc-bg);
    --radius-card: var(--arc-radius);
    --r-control: var(--arc-radius);
    --r-multi: var(--arc-radius);
    --r-seg: var(--arc-radius);
    --r-box: var(--arc-radius);
}

@media (prefers-reduced-motion: reduce) { :root[data-skin='game'][data-gs] { --btn-press: none; } }

/* The screen: a dotted grid with faint scanlines behind everything; body text in the screen font. */
:root[data-skin='game'][data-gs] body {
    background-color: var(--arc-bg);
    background-image: var(--arc-ground);
    background-size: var(--arc-ground-size);
    font-family: var(--arc-screen);
    /* VT323 sized by its character width (0.4 em, the same as its x-height, so the same size as before), which sizes
       its fallback to the same width too; the x-height value first, for a browser without ch-width. */
    font-size-adjust: 0.62;
    font-size-adjust: ch-width 0.62;
    --arc-ex: 0.62;
    font-synthesis-weight: none; /* the screen font has one weight: no smeared fake bold */
}
@media (prefers-reduced-motion: reduce) { :root[data-skin='game'][data-gs] body { background-image: var(--arc-ground-still); } }
/* Every other face keeps the x-height sizing it had: a game rule that sets a face also sets font-size-adjust to
   var(--arc-ex, none), the x-height value in force there, and a rule that sets an x-height value sets --arc-ex with
   it (game.test.js holds the sheet to this). */
:root[data-skin='game'][data-gs] [data-ui='part-time'] { font-size-adjust: var(--arc-ex, none); } /* a part player's time, in the system monospace */

/* A screen's own full-page ground lets the dotted screen show through. */
:root[data-skin='game'][data-gs] [data-ui='screen'] { background-color: transparent; }

/* Pixel type: headings (with a hard shadow), the logo, labels and every button. */
:root[data-skin='game'][data-gs] :is(h1, h2, h3, .btn, .btn-primary, .btn-secondary, .btn-ghost, .btn-danger, .btn-go, .seg-option) { font-family: var(--arc-pixel); font-weight: 400; font-size-adjust: 0.5; letter-spacing: 0; --arc-ex: 0.5; }
:root[data-skin='game'][data-gs] :is(h1, h2) { font-size-adjust: 0.58; --arc-ex: 0.58; }
:root[data-skin='game'][data-gs] :is(h1, h2) { line-height: 1.02; text-shadow: 0.06em 0.06em 0 var(--arc-shade); }
:root[data-skin='game'][data-gs] #app header [data-ui='wordmark'] { font-family: var(--arc-pixel); font-weight: 400; font-size-adjust: 0.66; text-shadow: 0.08em 0.08em 0 color-mix(in srgb, var(--color-accent) 70%, transparent); --arc-ex: 0.66; }

/* Short labels set side by side keep each phrase whole in the wider screen font. */
:root[data-skin='game'][data-gs] [data-ui='facts'] > span:not(:has(*)) { white-space: nowrap; }
/* Except a take's chart key, whose middle phrase ("Inside the band is on pitch") is long: it wraps, centred, between Start
   and End (single words, so they never wrap), and End stays inside the card on a 320 px phone. */
:root[data-skin='game'][data-gs] [data-take-result] [data-ui='facts'] > span { white-space: normal; text-align: center; }

/* A lesson's instruction is a sentence, so it's in the screen font at heading size (pixel type is for titles). */
:root[data-skin='game'][data-gs] #app [data-step-line] { font-family: var(--arc-screen); font-size-adjust: 0.66; font-size-adjust: ch-width 0.66; --arc-ex: 0.66; line-height: 1.2; text-shadow: 0.05em 0.05em 0 var(--arc-shade); }

/* A screen's own title in its header bar stays on one line beside the back button and the actions. */
:root[data-skin='game'][data-gs] #app header h1 { font-size-adjust: 0.46; --arc-ex: 0.46; }

/* Square pixel edges: the app's and dialogs' corner tokens are 0 (Tailwind's rounded-* read --radius-*; the primitives
   read --r-*), so a corner set anywhere follows; round things (rounded-full: avatars, dots, bars) stay round, and a gem
   keeps its own corners. */
:root[data-skin='game'][data-gs] :is(#app, [role='dialog']) { --radius-xs: 0px; --radius-sm: 0px; --radius-md: 0px; --radius-lg: 0px; --radius-xl: 0px; --radius-2xl: 0px; --radius-3xl: 0px; --radius-4xl: 0px; --radius-stage: 0px; --radius-tile: 0px; --radius-inset: 0px; --radius-bar: 0px; --radius-field: 0px; --r-pill: 0px; }
:root[data-skin='game'][data-gs] :is(#app, [role='dialog']) .gem { --radius-xs: 0.125rem; --radius-sm: 0.25rem; --radius-md: 0.375rem; --radius-lg: 0.5rem; --radius-xl: 0.75rem; --radius-2xl: 1rem; --radius-3xl: 1.5rem; }

/* Panels are framed like the stage card (docs/design-rules.md): a thin bright frame and a hard offset shadow. */
:root[data-skin='game'][data-gs] :is(#app, [role='dialog']) .card:not([data-ask], [data-lead], [data-ui]) { border: var(--arc-edge-w) solid var(--arc-purple); box-shadow: var(--arc-shadow); }
/* Settings' link rows (Lend your voice, Notices, Contact us) are framed like its panels above them, not on a hairline. */
:root[data-skin='game'][data-gs] :is([data-lend-voice], [data-notices-row], [data-contact-row]) { border: var(--arc-edge-w) solid var(--arc-purple); box-shadow: var(--arc-shadow); }
:root[data-skin='game'][data-gs] :is([data-lend-voice], [data-notices-row], [data-contact-row]):is(:hover, :focus-visible) { border-color: var(--color-cream); }
/* A paused song's note (components/paused-note.js) on the arcade's panel in a dashed frame: paused by its edge, not a grey
   box; and Send diagnostics' list of what's sent in the arcade's well, as its fields are. */
:root[data-skin='game'][data-gs] [data-paused-note] { border: var(--arc-edge-w) dashed var(--arc-line); background: var(--arc-panel); }
:root[data-skin='game'][data-gs] [data-diag-details] { background: var(--arc-well); }
/* Sing's coach and chooser, game skin: the screen font runs wider, so a phrase's words take two lines instead of an
   ellipsis, a step's name stays on one line, and a way's tag drops under its name rather than breaking it. */
:root[data-skin='game'][data-gs] [data-phrase-line] { display: -webkit-box; -webkit-box-orient: vertical; -webkit-line-clamp: 2; white-space: normal; line-height: 1.15; }
:root[data-skin='game'][data-gs] [data-step-name] { white-space: nowrap; }
:root[data-skin='game'][data-gs] [data-way-head] { flex-wrap: wrap; row-gap: 6px; }
:root[data-skin='game'][data-gs] [data-way-name] { white-space: nowrap; }
/* The course's account wall where it's compact (components/course-wall.js: the course map's picked lesson, Home's ask): its
   heading is the pixel face at 1.5, so a wrapped "Keep going with a free account" read as two lines; tight, as the
   arcade's other headings are. The full wall's heading is tight already. */
:root[data-skin='game'][data-gs] [data-needs-account]:not(.card) > :is(h2, h3) { line-height: 1.25; }
:root[data-skin='game'][data-gs] [data-ui='stage'][data-theme-menu] { border-width: var(--arc-edge-w); box-shadow: var(--arc-shadow-lg); }

/* A pill (a fully rounded button, link or tag with words: Microphone, Record, Armed) is square too; a round icon
   button (sized by size-*) and the round things (avatars, gems, dots, a switch's track) stay round. */
:root[data-skin='game'][data-gs] :is(#app, [role='dialog']) :is(button, a, span, p).rounded-full:not(.gem, [class*='size-'], .switch-track, .switch-knob, [class~='h-1'], [class~='h-1.5'], [class~='h-2'], [class~='h-2.5'], [class~='h-3'], [class~='w-1'], [class~='w-1.5'], [class~='w-2'], [class~='w-3']) { border-radius: 0; }

/* The pixel type is wide: a long label ("Remind me on my practice days") wraps onto balanced lines inside its
   box instead of running off a 320 px phone (the widths flow). Serious mode's labels stay on one line. */
:root[data-skin='game'][data-gs] :is(.btn, .btn-primary, .btn-secondary, .btn-ghost, .btn-danger, .btn-go) { white-space: normal; text-wrap: balance; text-align: center; max-width: 100%; min-width: 0; line-height: 1.35; }

/* The header: Theme as an outlined pixel button, you as the pink 1P chip. */
@media (max-width: 30rem) { :root[data-skin='game'][data-gs] #app header [data-ui='wordmark'] { font-size-adjust: 0.46; --arc-ex: 0.46; } } /* as the site's .s-word */
/* Narrow phones: the header's pieces fit in one line with nothing off the side (the widths flow, 320 px up). Below
   400 px the player chip drops its level (P1 stays); below 344 px the chip goes, the initials' square still saying
   it's you. The wordmark steps as the site's does, and goes below 360 px, the mark alone (components/icon.js Logo). */
@media (max-width: 25rem) { :root[data-skin='game'][data-gs] #app header [data-ui='wordmark'] { font-size-adjust: 0.35; --arc-ex: 0.35; } :root[data-skin='game'][data-gs] #app header .ge-p1 > span:not(.ge-p1-tag) { display: none; } }
@media (max-width: 374px) { :root[data-skin='game'][data-gs] #app header [data-ui='wordmark'] { font-size-adjust: 0.3; --arc-ex: 0.3; } } /* as the site's .s-word */
@media (max-width: 21.5rem) { :root[data-skin='game'][data-gs] #app header .ge-p1 { display: none; } }
:root[data-skin='game'][data-gs] #app header .glass-bubble { border-radius: 0; background: transparent; background-image: none; box-shadow: inset 0 0 0 var(--arc-edge-w) var(--arc-purple); font-family: var(--arc-pixel); font-weight: 400; font-size-adjust: 0.5; --arc-ex: 0.5; }
:root[data-skin='game'][data-gs] #app header .glass-bubble::before, :root[data-skin='game'][data-gs] #app header .glass-bubble::after { display: none; }
:root[data-skin='game'][data-gs] #app header [data-ui='player'] { box-shadow: inset 0 0 0 var(--arc-edge-w) var(--color-accent); border-radius: 0; padding: 0.3rem; }
:root[data-skin='game'][data-gs] #app header [data-ui='player'] > img { width: 1.75rem; height: 1.75rem; flex-shrink: 0; object-fit: cover; border-radius: 0; box-shadow: none; }
:root[data-skin='game'][data-gs] #app header [data-ui='player'] > :is(.gem, .bubble) { flex-shrink: 0; width: 2rem; height: 2rem; border-radius: 0; background: var(--color-accent); color: var(--color-accent-ink); box-shadow: none; }
:root[data-skin='game'][data-gs] #app header [data-ui='player'] > :is(.gem, .bubble)::before, :root[data-skin='game'][data-gs] #app header [data-ui='player'] > :is(.gem, .bubble)::after { display: none; }
:root[data-skin='game'][data-gs] #app header [data-ui='player']:not(:has(.ge-p1)) > span[translate='no']::before { content: '1P'; display: block; font: 400 8px/1.4 var(--arc-pixel); color: var(--ge-yellow); }

/* The player chip (data-ui="player"): the original's 1P card, your square initials beside a small yellow
   player line (1P, or P1 at your level) over your name, in an outline of the accent. */
:root[data-skin='game'][data-gs] #app header [data-ui='player'] { display: grid; grid-template-columns: auto minmax(0, auto) auto; grid-auto-flow: dense; column-gap: 0.55rem; row-gap: 0.15rem; align-items: center; }
:root[data-skin='game'][data-gs] #app header [data-ui='player'] > :is(img, .gem, .bubble) { grid-column: 1; grid-row: 1 / span 2; }
:root[data-skin='game'][data-gs] #app header [data-ui='player'] > .ge-p1 { grid-column: 2; grid-row: 1; align-self: end; }
:root[data-skin='game'][data-gs] #app header [data-ui='player'] > span[translate='no'] { grid-column: 2; grid-row: 2; align-self: start; }
:root[data-skin='game'][data-gs] #app header [data-ui='player']:not(:has(.ge-p1)) > span[translate='no'] { grid-row: 1 / span 2; align-self: center; }
:root[data-skin='game'][data-gs] #app header [data-ui='player'] > .chip-accent { grid-column: 3; grid-row: 1 / span 2; }
@media (max-width: 39.99rem) { :root[data-skin='game'][data-gs] #app header [data-ui='player'] > .ge-p1 { grid-row: 1 / span 2; align-self: center; } } /* a phone hides the name */
:root[data-skin='game'][data-gs] #app header [data-ui='player'] .ge-p1 { font-size: 8px; line-height: 1.4; }
:root[data-skin='game'][data-gs] #app header [data-ui='player'] .ge-p1-tag { padding: 0; border-radius: 0; background: none; color: inherit; }

/* Home's hero: a pink pixel frame with a hard shadow, the stage and your high score in its corner,
   the four lanes as pixel blocks in a framed track with a playhead sweeping across, your lane framed. */
/* A stage panel (Home's card, data-lead, and any data-ui="stage": the lesson end): the framed pink panel. */
:root[data-skin='game'][data-gs] :is([data-lead], [data-ui='stage']) { border-radius: var(--arc-radius); border: var(--arc-frame) solid var(--color-accent); background-image: none !important; background-color: var(--arc-panel); box-shadow: var(--arc-shadow-lg); }
:root[data-skin='game'][data-gs] [data-lead] h1 { max-width: 42rem; font-size: var(--arc-title); line-height: 1.12; text-shadow: 0.06em 0.06em 0 var(--arc-shade); }
@media (min-width: 48rem) { :root[data-skin='game'][data-gs] [data-lead] h1 { font-size-adjust: 0.74; line-height: 1.3; --arc-ex: 0.74; } :root[data-skin='game'][data-gs] [data-lead] :is(.btn-primary, .btn-lg) { min-height: 3.4rem; padding-inline: 1.6rem; font-size-adjust: 0.6; --arc-ex: 0.6; } :root[data-skin='game'][data-gs] [data-lead-lanes] > li { min-height: 2.6rem; } :root[data-skin='game'][data-gs] [data-lead-lanes] svg { height: 2.2rem; } :root[data-skin='game'][data-gs] #app h2 { font-size-adjust: 0.66; --arc-ex: 0.66; } :root[data-skin='game'][data-gs] #app [data-ask] h2 { font-size-adjust: 0.5; --arc-ex: 0.5; } }
:root[data-skin='game'][data-gs] .gs-hi { position: absolute; top: 2.2rem; inset-inline-end: 2.2rem; display: grid; justify-items: end; gap: 0.55rem; margin: 0; font: 400 12px/1 var(--arc-pixel); text-transform: uppercase; }
:root[data-skin='game'][data-gs] .gs-hi-stage { color: var(--arc-purple); }
:root[data-skin='game'][data-gs] .gs-hi-score { color: var(--ge-yellow); }
/* A returning singer's card: the high score beside the course map (the eyebrow already names the stage). */
:root[data-skin='game'][data-gs] .gs-score { display: block; margin: 0; font: 400 12px/1 var(--arc-pixel); text-transform: uppercase; color: var(--arc-yellow); white-space: nowrap; }
/* Before a first song (game/fresh.js), no STAGE 01 / HI 000000: a score for a game not yet played. */
:root[data-skin='game'][data-gs][data-game-fresh] :is(.gs-hi, .gs-score) { display: none; }
@media (max-width: 47.99rem) { :root[data-skin='game'][data-gs] .gs-hi { position: static; justify-items: start; margin-top: 0.9rem; } }
:root[data-skin='game'][data-gs] [data-lead-lanes] { --gs-label: 7.5rem; position: relative; container-type: inline-size; margin-top: 1.75rem; padding: 0.9rem 1rem; background: var(--arc-well); box-shadow: inset 0 0 0 var(--arc-edge-w) var(--arc-line); }
:root[data-skin='game'][data-gs] [data-lead-lanes] > li { gap: 1rem; }
/* A long label wraps within its column (Spanish "Contralto · tú" ran into the lane, 2026-11-12). */
:root[data-skin='game'][data-gs] [data-lead-lanes] > li > span { width: var(--gs-label); overflow-wrap: anywhere; font: 400 11px/1.4 var(--arc-pixel); }
@media (max-width: 47.99rem) { :root[data-skin='game'][data-gs] [data-lead-lanes] { --gs-label: 6rem; } :root[data-skin='game'][data-gs] [data-lead-lanes] > li > span { font-size: 8px; } }
:root[data-skin='game'][data-gs] [data-lead-lanes] > li > span[data-you] { color: var(--ge-yellow); }
:root[data-skin='game'][data-gs] [data-lead-lanes] svg { height: 1.9rem; border-radius: 0; background: transparent; box-shadow: none !important; }
:root[data-skin='game'][data-gs] [data-lead-lanes] svg rect { rx: 0; width: 2.4px; }
:root[data-skin='game'][data-gs] [data-lead-lanes] > li:has(> span[data-you]) svg { outline: 3px solid var(--ge-yellow); outline-offset: 1px; background: color-mix(in srgb, var(--ge-yellow) 10%, transparent); }
:root[data-skin='game'][data-gs] [data-lead-lanes]::after { content: ''; position: absolute; top: 0.45rem; bottom: 0.45rem; inset-inline-start: calc(2rem + var(--gs-label)); width: 3px; background: color-mix(in srgb, var(--color-accent) 75%, white); box-shadow: 0 0 8px 2px var(--color-accent); animation: gs-sweep 7s linear infinite; pointer-events: none; }
@keyframes gs-sweep { from { transform: translateX(0); } to { transform: translateX(calc(100cqw - 2rem - var(--gs-label) - 3px)); } }
