:root[data-skin='game'][data-gs] [data-ui='band'][data-tone] h2 + span { color: var(--arc-cyan); }
/* The bigger title and its count wrap on a phone rather than push the page sideways. */
:root[data-skin='game'][data-gs] [data-ui='band'] > div:first-child > div:first-child { flex-wrap: wrap; white-space: normal; }
