:root[data-skin='game'][data-gs] [data-ui='cartridge'] [data-ui='cartridge-title'] { padding-top: 0.85rem; font-family: var(--arc-pixel); font-weight: 400; font-size-adjust: 0.46; line-height: 1.5; --arc-ex: 0.46; }
:root[data-skin='game'][data-gs] [data-ui='cartridge'] > :last-child { margin-top: 0.3rem; }
