:root[data-skin='game'][data-gs] [data-ui='cartridge']::after { content: '\25B6'; position: absolute; inset-inline-end: 0.75rem; bottom: 0.75rem; font: 400 10px/1 var(--arc-pixel); color: var(--arc-yellow); opacity: 0; }
@media (hover: hover) {
    :root[data-skin='game'][data-gs] [data-ui='cartridge']:hover { transform: translate(calc(var(--arc-press) * -0.5), calc(var(--arc-press) * -0.5)); box-shadow: inset 0 0 0 var(--arc-chunk) var(--color-accent), var(--arc-shadow-lg); }
    :root[data-skin='game'][data-gs] [data-ui='cartridge']:hover::after { opacity: 1; animation: gs-blink 1s steps(1) infinite; }
}
:root[data-skin='game'][data-gs] [data-ui='cartridge']:focus-visible::after { opacity: 1; }
@keyframes gs-blink { 50% { opacity: 0; } }
@media (prefers-reduced-motion: reduce) { :root[data-skin='game'][data-gs] [data-ui='cartridge']:hover { transform: none; } :root[data-skin='game'][data-gs] [data-ui='cartridge']:hover::after { animation: none; } }
/* Its part bars as pixel blocks (a round's stay staggered: that's the song's own shape). */
:root[data-skin='game'][data-gs] [data-cover] * { border-radius: 0; }
/* A unit's song on Home (retention row 8): the rows of the parts that are you are lit, the others are hollow bulbs. */
:root[data-skin='game'][data-gs] [data-cover-row][data-mine='no'] [data-cover-dash] { background: transparent !important; box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--color-muted) 75%, transparent); }

/* A tag on a card (data-ui="tag": Real voices, Free this month, Draft): a square pixel label, on one line. */
:root[data-skin='game'][data-gs] [data-ui='tag'] { border-radius: 0; padding: 0.25rem 0.35rem; font: 400 7px/1.2 var(--arc-pixel); letter-spacing: 0; white-space: nowrap; box-shadow: inset 0 0 0 1px currentColor; background: var(--arc-panel); }
:root[data-skin='game'][data-gs] [data-ui='tag'][data-tone] { background: var(--tone); color: #07060e; box-shadow: none; }
/* Light: the tones and part colours are darker there, so their words are white (AA). */
:root[data-skin='game'][data-gs][data-theme$='-light'] :is([data-ui='tag'][data-tone], .gs-slot) { color: #fff; }

/* A list of rows (data-ui="rows", the choirs): a bright frame with dashed dividers; each row's player slot (P1, P2 ...)
   a square tag in the part colours in turn. */
:root[data-skin='game'][data-gs] [data-ui='rows'] { border: var(--arc-edge-w) solid var(--color-cream); box-shadow: var(--arc-shadow); }
:root[data-skin='game'][data-gs] [data-ui='rows'] > li > a { min-height: 4rem; }
:root[data-skin='game'][data-gs] [data-ui='rows'] [translate='no'] { font-family: var(--arc-pixel); font-weight: 400; font-size-adjust: 0.46; --arc-ex: 0.46; }
:root[data-skin='game'][data-gs] [data-ui='rows'] [data-ui='rows-count'] { color: var(--arc-cyan); }
:root[data-skin='game'][data-gs] [data-ui='rows'] > li > a > svg { color: var(--arc-pink); }
:root[data-skin='game'][data-gs] [data-ui='rows'] > :not(:last-child) { border-bottom: var(--arc-edge-w) dashed var(--arc-line); }
:root[data-skin='game'][data-gs] .gs-slot { display: inline-grid; place-items: center; min-width: 2.2rem; padding: 0.3rem 0.35rem; font: 400 9px/1 var(--arc-pixel); color: #07060e; background: var(--color-part-1); }
:root[data-skin='game'][data-gs] .gs-slot[data-slot='2'] { background: var(--color-part-4); }
:root[data-skin='game'][data-gs] .gs-slot[data-slot='3'] { background: var(--color-part-3); }
:root[data-skin='game'][data-gs] .gs-slot[data-slot='4'] { background: var(--color-part-2); }

/* New song: a dashed pixel tile with a green + block. */
:root[data-skin='game'][data-gs] [data-new-song] > span:first-child { border: var(--arc-edge-w) dashed var(--arc-purple); font-family: var(--arc-pixel); font-weight: 400; font-size-adjust: 0.5; --arc-ex: 0.5; }
:root[data-skin='game'][data-gs] [data-new-song] > span:first-child > span[aria-hidden] { border-radius: 0; background: var(--arc-green); color: #06130b; }
/* Make your own's ways in (frontend2's option cards): a pixel card that presses in, its icon tile a square accent block. */
:root[data-skin='game'][data-gs] [data-make-option] { box-shadow: inset 0 0 0 var(--arc-edge-w) var(--arc-line), var(--arc-shadow); }
:root[data-skin='game'][data-gs] [data-make-option]:focus-visible { box-shadow: inset 0 0 0 var(--arc-edge-w) var(--color-accent), var(--arc-shadow); }
:root[data-skin='game'][data-gs] [data-make-option]:active { transform: translate(var(--arc-press), var(--arc-press)); box-shadow: inset 0 0 0 var(--arc-edge-w) var(--arc-line); }
@media (prefers-reduced-motion: reduce) { :root[data-skin='game'][data-gs] [data-make-option]:active { transform: none; } }
:root[data-skin='game'][data-gs] [data-make-option] [data-ui='option-title'] { font-family: var(--arc-pixel); font-weight: 400; font-size-adjust: 0.5; --arc-ex: 0.5; }
:root[data-skin='game'][data-gs] [data-make-icon] { border-radius: 0; background: var(--color-accent); color: var(--color-accent-ink); }
/* Leaderboards (frontend2's structure, ge-board-* and its hooks) as an arcade high-score table: a framed panel, the title,
   ranks, tags and scores in pixel type (scores in yellow), square chips; an empty board's first line in yellow pixel type
   inside a dashed frame. After a take (data-ui="take-best"): the result as a framed block, the best in yellow. */
/* The board is the picked part card's lower half under a divider, never a third frame (docs/leaderboard-redesign-plan.md; the
   game agent's arcade pass follows). */
:root[data-skin='game'][data-gs] .ge-board { border-top: var(--arc-edge-w) solid var(--arc-line); background: none; box-shadow: none; }
