:root[data-skin='game'][data-gs] [data-ui='board-gap'] > td { border-top: 2px dashed var(--arc-line); padding-block: 0.15rem; }
:root[data-skin='game'][data-gs] .ge-board [data-ui='board-title'] { font-family: var(--arc-pixel); font-weight: 400; font-size-adjust: 0.5; --arc-ex: 0.5; }
:root[data-skin='game'][data-gs] :is(.ge-board-part, .ge-board-you-tag, .ge-board-rank) { border-radius: 0; font-family: var(--arc-pixel); font-weight: 400; font-size-adjust: 0.45; --arc-ex: 0.45; }
:root[data-skin='game'][data-gs] .ge-board [data-ui='board-score'] { font-family: var(--arc-pixel); font-weight: 400; font-size-adjust: 0.5; color: var(--arc-yellow); --arc-ex: 0.5; }
:root[data-skin='game'][data-gs] [data-board-empty] { border: var(--arc-edge-w) dashed var(--arc-purple); }
:root[data-skin='game'][data-gs] [data-ui='board-empty-title'] { font-family: var(--arc-pixel); font-weight: 400; font-size-adjust: 0.5; color: var(--arc-yellow); --arc-ex: 0.5; }
:root[data-skin='game'][data-gs] [data-ui='take-best'] { padding: 1rem 1.1rem; background: var(--arc-panel); box-shadow: inset 0 0 0 var(--arc-edge-w) var(--arc-purple), var(--arc-shadow); }
:root[data-skin='game'][data-gs] [data-ui='take-best'] [data-best] { font: 400 1.05rem/1.3 var(--arc-pixel); color: var(--arc-yellow); }
:root[data-skin='game'][data-gs] [data-ui='take-best'] .ge-record [data-sep] { display: none; }
:root[data-skin='game'][data-gs] [data-ui='take-best'] .ge-record-line { margin-inline-start: 0.5em; }

/* The public site on the arcade screen (a page opts in with @section('arcade'), which sets data-gs; the landing
   first, Hillel 2026-10-31: "closer to the original design"). The rules above already give it the ground, the screen
   font, pixel headings and the buttons; these only undo the site's own marquee look: Bungee and its gradient, round
