:root[data-skin='game'][data-gs] body.s-arcade:not(.s-calm) { background-repeat: repeat; }
:root[data-skin='game'][data-gs] body.s-arcade:not(.s-calm) :is(main h1, .s-title, .s-rowtitle, .s-final h2, .s-end h2) { font-family: var(--arc-pixel); font-weight: 400; text-transform: none; letter-spacing: 0; font-size-adjust: 0.58; line-height: 1.25; text-shadow: 0.06em 0.06em 0 var(--arc-shade); --arc-ex: 0.58; }
:root[data-skin='game'][data-gs] body.s-arcade:not(.s-calm) main h1 { font-size: clamp(22px, 4.6vw, 48px); overflow-wrap: break-word; } /* a 320 px phone: pixel type is wide */
:root[data-skin='game'][data-gs] body.s-arcade:not(.s-calm) :is(main a:not(.gt), main button:not(.gt, .s-pipe-key), main img, .s-mixer, .s-ch, .s-ch-pick, .s-play, .s-end, .s-card3d, .s-cabinet, .s-cab-screen, .s-cab-play, .s-cab-progress, .s-stage, .s-board-rows li, .s-tag, .s-badges span, .s-board-tabs span, .s-howsteps li, .s-step, .s-vis, .s-vis img, .s-feature, .s-pic, .s-pic img, .s-plan, .s-plan-soon, .s-plan-paused, .s-final, .s-seg, .s-seg > *, .s-recpill, .s-linkrow) { border-radius: var(--arc-radius); }
/* Features and the course pages on the arcade screen (frontend2, master plan #22; marketing: "wrap the course
