:root[data-skin='game'][data-gs] body.s-arcade:not(.s-calm) :is(.s-xcard, .s-xplace, .s-xfilter-seg, .s-xfilter-menu, .s-xcount, .s-xtonight, .s-xband, .s-xhero, .s-xfoot) { border-radius: var(--arc-radius); }
